export const FULL_LEKCIJE: FullLesson[] = [{"nivo":1,"slug":"uvodna-rijec","naslov":"Uvodna riječ","content_html":"<div class=\"lesson-container\">\n    <h1>UVODNA RIJEČ</h1>\n\n    <div class=\"hero-box\">\n        <img src=\"/edu/assets/images/uvodna.jpg\" alt=\"Dobrodošlica u mekteb\">\n    </div>\n\n    <p class=\"lesson-text\">\n        Draga djeco, pred vama je vaš prvi <strong>Ilmihal</strong>. Ova knjiga će biti vaš vodič kroz prelijepi svijet naše vjere islama. Kroz njene stranice ćemo zajedno učiti o našem Stvoritelju, o Njegovim poslanicima i o tome kako da postanemo dobri i čestiti ljudi.\n    </p>\n\n    <div class=\"info-box\">\n        Mekteb nije samo mjesto gdje učimo lekcije. To je mjesto gdje sklapamo nova prijateljstva i učimo kako da jedni drugima budemo podrška na putu dobra.\n    </div>\n\n    <p class=\"lesson-text\">\n        Učenje o islamu je put koji traje cijeli život, a svaki novi korak na tom putu donosi nam radost i mir u srcu. Neka nam ovi prvi koraci budu hairli i sretni!\n    </p>\n\n    <div class=\"arabic-card\">\n        <p style=\"font-style: italic; color: var(--primary); font-weight: 700;\">\n            \"Traženje znanja je obaveza svakog muslimana i muslimanke.\"\n        </p>\n        <p style=\"font-size: 0.9rem; margin-top: 10px; color: #94a3b8;\">(Hadis)</p>\n    </div>\n\n    <div style=\"text-align: center; margin-top: 40px;\">\n        <a href=\"../../../mekteb-kviz/index.html?quiz=uvodna\" class=\"btn-wow\">🚀 KRENI NA PRVI KVIZ</a>\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Uvodna riječ – upoznavanje sa mektebom</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema mektebu, druženju i učenju o vjeri</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa mektebom, muallimom i pravilima ponašanja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pozitivnog stava prema vjerskoj pouci</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Es-selamu alejkum, draga djeco! Dobro došli u mekteb. Hajde da se prvo upoznamo. Ja sam vaš/a muallim/a, a vi mi recite kako se zovete. Da li znate šta je mekteb i zašto smo ovdje?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mekteb je kuća za učenje vjere u kojoj djeca uče o Allahu, Poslaniku Muhammedu, a.s., i lijepom ponašanju.</p><p>U mektebu učimo Kur’an, dove, sure, ilmihal i mnoge druge korisne stvari.</p><p>Razgovaram sa djecom o tome šta očekuju od mekteba, koje stvari su čuli kod kuće, te ih ohrabrujem da slobodno postavljaju pitanja.</p><p>Objašnjavam pravila ponašanja: pažljivo slušamo, dižemo ruku kad želimo nešto reći, lijepo se odnosimo prema svima.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam djecu šta su naučili na ovom času i kako se osjećaju u mektebu. Najavljujem da ćemo na sljedećem času početi učiti prve dove.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":0,"is_published":true,"kviz_pitanja":[{"answer":"Vodič kroz svijet naše vjere islama","options":["Knjiga o sportskim aktivnostima","Vodič kroz svijet naše vjere islama","Priča o životinjama","Zbirka matematičkih zadataka"],"question":"Šta je Ilmihal koji ste dobili?"},{"answer":"O Stvoritelju, poslanicima i kako biti dobri","options":["Samo matematiku i fiziku","O Stvoritelju, poslanicima i kako biti dobri","Samo istoriju svijeta","Kako igrati razne sportove"],"question":"Što ćemo učiti kroz stranice Ilmihala?"},{"answer":"Mjesto učenja, prijateljstva i uzajamne podrške","options":["Samo mjesto gdje učimo lekcije","Mjesto učenja, prijateljstva i uzajamne podrške","Mjesto gdje se igramo video igre","Samo biblioteka s knjigama"],"question":"Što je mekteb prema tekstu lekcije?"},{"answer":"Cijeli život čovjeka","options":["Samo jednu godinu","Samo dvije godine","Cijeli život čovjeka","Samo tri mjeseca"],"question":"Koliko dugo traje učenje o islamu?"},{"answer":"Traženje znanja i učenja","options":["Putovanje po svijetu","Traženje znanja i učenja","Samo igranje i zabava","Samo obavljanje namaza"],"question":"Prema hadisu, što je obaveza svakog muslimana?"}]},{"nivo":1,"slug":"euzubilla-i-bismilla","naslov":"Euzubilla i Bismilla","content_html":"<div class=\"lesson-container\">\n        <h1>EUZUBILLA I BISMILLA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/euzubilla.jpg\">\n        </div>","audio_src":"euzubilla.mp3","redoslijed":1,"is_published":true,"kviz_pitanja":[{"answer":"Tražim Allahovu zaštitu od prokletog Šejtana","options":["Tražim Allahovu zaštitu od prokletog Šejtana","U ime Allaha, milostivog, samilosnog","Čitam Kuran sa poštovanjem","Molim Allaha za pomoć u školi"],"question":"Šta znači E'uzubilla?"},{"answer":"U ime Allaha, milostivog, samilosnog","options":["Tražim zaštitu od Šejtana","U ime Allaha, milostivog, samilosnog","Učim arabski jezik","Molim za dobar dan"],"question":"Šta znači Bismillah?"},{"answer":"Prije pisanja zadaće i prije jela","options":["Samo pisanje domaće zadaće","Prije pisanja zadaće i prije jela","Samo prije spavanja","Samo u mektebu sa učiteljem"],"question":"Koju od ovih aktivnosti trebamo početi sa E'uzubillom i Bismillahom?"},{"answer":"Allah nam daje uspjeh i pomoć","options":["Naši roditelji","Allah nam daje uspjeh i pomoć","Samo učitelj u mektebu","Naši prijatelji"],"question":"Ko nam daje uspjeh i pomoć u našim poslovima?"},{"answer":"Kada vozimo biciklo i kada se želimo igrati","options":["Samo kada se oblačimo za školu","Kada vozimo biciklo i kada se želimo igrati","Nikad, to je nepotrebno","Samo na molitvi u džamiji"],"question":"U kojoj situaciji trebamo učiti E'uzubillu i Bismillu?"}]},{"nivo":1,"slug":"kako-pocinjem-posao","naslov":"Kako počinjemo svaki dobar posao","content_html":"<div class=\"lesson-container\">\n        <h1>KAKO POČINJEMO SVAKI DOBAR POSAO</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/euzubilla2.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kako počinjemo svaki dobar posao</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike spominjanja Allaha prije svakog posla</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti učenike da svaki dobar posao počinju Bismillom i dovom</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvoj svijesti o stalnoj povezanosti sa Stvoriteljem</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kada krećete u školu, kada jedete ili kada legnete spavati – kažete li nešto prije toga? Kakav osjećaj imate kad nešto započnete sa lijepim riječima?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Musliman svaki dobar posao započinje učenjem Bismille: <em>Bismillahi-r-Rahmani-r-Rahim</em> – U ime Allaha, Milostivog, Samilosnog.</p><p>Time tražimo Allahovu pomoć i bereket u onome što radimo.</p><p>Pored Bismille, lijepo je proučiti i kratku dovu (npr. Rabbi jessir) kojom molimo Allaha da nam olakša posao.</p><p>Postupak: Pišem na tabli Bismillu sa značenjem. Učenici je ponavljaju nekoliko puta. Razgovaramo o prilikama u kojima se uči (prije jela, ulaska u kuću, polaska u školu, učenja, putovanja).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju situacije u kojima će ubuduće učiti Bismillu. Zajedno učimo Bismillu još jednom, glasno i pravilno.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">\n                1. PRIČA O NAJLJEPŠEM POČETKU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">\n                2. NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    SVE SVOJE DOBRE I HAIRLI POSLOVE I RADNJE POČINJEMO IZGOVARANJEM EUZUBILLE I BISMILLE.\n                </p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">\n                    UČENJEM EUZUBILLE I BISMILLE MOLIMO MILOSTIVOG ALLAHA DA NAS ČUVA I DARUJE NAM SVOJU MILOST. ZATO IH UČIMO U RAZNIM PRILIKAMA.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('kada', this)\">\n                3. BISMILLU JE LIJEPO IZGOVORITI: <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"kada\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>UJUTRO I NAVEČER</li>\n                    <li>KADA UČIMO</li>\n                    <li>U VOŽNJI</li>\n                    <li>U IGRI I ZABAVI</li>\n                    <li>KADA POČINJEMO S JELOM ILI PIĆEM</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\">\n                4. MOJI MALI ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <p class=\"lesson-text\">1. RAZGOVARAJ SA MUALLIMOM/MUALLIMOM I RODITELJIMA/STARATELJIMA KADA SVE TREBAŠ UČITI EUZUBILLU I BISMILLU!</p>\n                <p class=\"lesson-text\">2. KO NAM DAJE SNAGU DA URADIMO DOBRE POSLOVE?</p>\n                \n                <hr style=\"border: 0; border-top: 2px solid var(--accent-border-y); margin-top: 20px; margin-bottom: 20px;\">\n                <p class=\"lesson-text\">POKUŠAJ DANAS SVAKI SVOJ POSAO ZAPOČETI SA BISMILLOM I OSJETI ALLAHOVU MILOST!</p>\n            </div>\n        </div>","audio_src":"lekcija3.mp3","redoslijed":2,"is_published":true,"kviz_pitanja":[{"answer":"Euzubille i Bismille","options":["Euzubille i Bismille","Samo Bismille","Samo Euzubille","Alhamdu lillah"],"question":"Šta kažemo na početku svakog dobrog posla?"},{"answer":"Ujutro, navečer i pri jelу","options":["Samo ujutro","Ujutro, navečer i pri jelу","Samo prije spavanja","Samo u džamiji"],"question":"Kada je lijepo izgovoriti Bismillu?"},{"answer":"Allah","options":["Naši roditelji","Allah","Naši učitelji","Naši prijatelji"],"question":"Ko nam daje snagu za dobre poslove?"},{"answer":"U raznim prilikama","options":["Samo kod kuće","U raznim prilikama","Samo u školi","Samo na putu"],"question":"Gdje trebamo učiti Euzubillu i Bismillu?"},{"answer":"Čuvanje i Allahovu milost","options":["Bogato bogatstvo","Čuvanje i Allahovu milost","Nove igračke","Bolje ocjene"],"question":"Što molimo Allahu kada učimo Euzubillu i Bismillu?"}]},{"nivo":1,"slug":"covjek-najljepse-stvorenje","naslov":"Čovjek je najljepše Allahovo stvorenje","content_html":"<div class=\"lesson-container\">\n        <h1>ČOVJEK JE NAJLJEPŠE ALLAHOVO STVORENJE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/covjek.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Čovjek je najljepše Allahovo stvorenje</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje zahvalnosti Allahu na blagodatima i darovima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti da je čovjek najodabranije Allahovo stvorenje, počašćeno razumom</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje samopoštovanja i poštovanja drugih ljudi</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pogledajte oko sebe – životinje, biljke, planine, more. Sve je to Allah stvorio. A ko je, prema Kur’anu, najljepše Allahovo stvorenje? Hajde da to danas otkrijemo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah, dž.š., je stvorio čovjeka u najljepšem obliku i dao mu razum kojim razlikuje dobro od zla.</p><p>Čovjek se po tome razlikuje od svih drugih stvorenja: zna govoriti, učiti, raditi, donositi odluke.</p><p>Allah od nas traži da budemo zahvalni na svemu – na zdravlju, vidu, sluhu, porodici i pameti.</p><p>Razgovor: Šta sve mogu moje oči, uši, ruke, srce? Kako se zahvaljujemo Allahu? (kroz dove, namaz, lijepa djela)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju blagodati za koje su zahvalni. Zaključujemo da svako od nas treba čuvati ono što mu je Allah dao i koristiti to za dobro.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">\n                1. PRIČA O NAJLJEPŠEM STVORENJU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">\n                2. NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">REKAO JE UZVIŠENI ALLAH: MI ČOVJEKA STVARAMO U SKLADU NAJLJEPŠEM (KUR'AN, ET-TÎN, 4) <br>\n                    A ON VAS POSTEPENO STVARA (KUR'AN, NUH, 14)</p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">ČOVJEK JE NAJLJEPŠE I NAJSAVRŠENIJE ALLAHOVO STVORENJE. ZATO VELIČAMO ALLAHA: NEKA JE UZVIŠEN ALLAH, NAJLJEPŠI STVORITELJ! (KUR'AN, EL-MU'MINUN, 14)</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">ČOVJEK JE ODLIKOVAN I IMA PREDNOSTI NAD OSTALIM STVORENJIMA. UZVIŠENI ALLAH JE ČOVJEKA OBDARIO RAZUMOM I POSTAVIO SVOJIM NAMJESNIKOM NA ZEMLJI.</p>\n\n                <div class=\"arabic-box\">\n                    <p class=\"lesson-text\">REKAO JE UZVIŠENI ALLAH: ON VAS STVARA U UTROBAMA MATERA VAŠIH, DAJUĆI VAM LIKOVE... (KUR'AN, EZ-ZUMER, 6)</p>\n                </div>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">U MOZGU IMA OKO 100 BILIONA NEURONA, KOLIKO I ZVIJEZDA U NAŠOJ GALAKSIJI. NAJSPORIJA BRZINA KRETANJA INFORMACIJA IZMEĐU NEURONA JE 416 KM/H. DNEVNO KROZ MOZAK PROĐE 70 000 MISLI.</p>\n                </div>\n            \n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">MI TREBAMO ŽIVJETI NA ZEMLJI ODGOVORNO I U POKORNOSTI UZVIŠENOM ALLAHU. REKAO JE UZVIŠENI ALLAH: DŽINE I LJUDE SAM STVORIO SAMO ZATO DA MI SE KLANJAJU (KUR'AN, EZ-ZARIJAT, 56)</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">\n                3. PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>KAKO NAS JE UZVIŠENI ALLAH STVORIO?</li>\n                    <li>KO JE NAJLJEPŠE ALLAHOVO STVORENJE?</li>\n                    <li>ČIME NAS JE UZVIŠENI ALLAH OBDARIO?</li>\n                    <li>KOGA JE UZVIŠENI ALLAH POSTAVIO SVOJIM NAMJESNIKOM?</li>\n                    <li>KAKO TREBAMO ŽIVJETI NA ZEMLJI?</li>\n                </ol>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\">\n                4. ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>SA RODITELJIMA RAZGOVARATI O LJEPOTI ALLAHOVOG STVARANJA</li>\n                    <li>UKAZATI NA ONO ŠTO ČOVJEK IMA - A DRUGA STVORENJA NEMAJU</li>\n                </ul>\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"font-weight: bold;\">ZAPAMTI!</p>\n                    <p class=\"lesson-text\">ALLAH, DŽ.Š., JE DAO ČOVJEKU RAZUM I POSTAVIO GA SVOJIM NAMJESNIKOM NA ZEMLJI. NA ZEMLJI TREBAMO ŽIVJETI ODGOVORNO I U POKORNOSTI UZVIŠENOM ALLAHU I TREBAMO GA VOLJETI.</p>\n                </div>\n            </div>\n        </div>","audio_src":"covjek.mp3","redoslijed":3,"is_published":true,"kviz_pitanja":[{"answer":"Čovjeka stvaramo u skladu najljepšem","options":["Čovjeka stvaramo u skladu najljepšem","Čovjeka stvaramo kao druga stvorenja","Čovjeka stvaramo bez razuma","Čovjeka stvaramo na nebu"],"question":"Šta je Uzvišeni Allah rekao o stvaranju čovjeka?"},{"answer":"Najljepše i najsavršenije stvorenje","options":["Najljepše i najsavršenije stvorenje","Najmanje važno stvorenje","Jednako kao životinje","Najslabije stvorenje"],"question":"Koji je čovjek među Allahovih stvorenjima?"},{"answer":"Razumom i postavio ga namjesnikom","options":["Razumom i postavio ga namjesnikom","Samo tjelom bez duše","Samo očima za gledanje","Samo nogama za hodanje"],"question":"Čime je Uzvišeni Allah obdario čovjeka?"},{"answer":"Oko 100 biliona neurona","options":["Oko 100 biliona neurona","Oko 10 biliona neurona","Oko 1 bilion neurona","Oko 1000 neurona"],"question":"Koliko neurona ima u ljudskom mozgu?"},{"answer":"Samo zato da mu se klanjaju","options":["Samo zato da mu se klanjaju","Samo za rad na polju","Samo za ratovanje međusobno","Samo da se igraju"],"question":"Zašto je Uzvišeni Allah stvorio džine i ljude?"}]},{"nivo":1,"slug":"ja-idem-u-mekteb","naslov":"Ja idem u mekteb","content_html":"<div class=\"lesson-container\">\n        <h1>JA IDEM U MEKTEB</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mekteb_prvi_dan.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ja idem u mekteb</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema dolasku u mekteb i druženju u njemu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pravila ponašanja u mektebu i odnosa prema muallimu i drugovima</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Stvaranje navike redovnog dolaska u mekteb</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako ste se pripremili za današnji dolazak u mekteb? Šta osjećate kad uđete u učionicu? Hajde da razgovaramo o tome zašto rado dolazimo u mekteb.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mekteb je posebno mjesto gdje učimo o Allahu, Kur’anu i lijepom ponašanju.</p><p>Prije dolaska treba se umiti, lijepo obući i ponijeti potrebne knjige i pribor.</p><p>U mekteb ulazimo sa selamom, pozdravljamo muallima i drugove, sjedamo mirno i pažljivo slušamo.</p><p>Prema muallimu se odnosimo s poštovanjem, prema drugovima sa ljubavlju, a knjige i učionicu čuvamo čistim.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici sami nabrajaju lijepe navike koje će primjenjivati pri dolasku u mekteb. Pohvaljujem one koji već dolaze redovno i uredno.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">\n                1. MIRZIN PRVI DAN U MEKTEBU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">\n                2. NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">SVI SU UPOZNALI SVOGA MUALLIMA I MUALLIMU KOJI ĆE IH U MEKTEBU UČITI O:</p>\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>ISLAMSKOM VJEROVANJU,</li>\n                    <li>ISLAMSKIM DUŽNOSTIMA,</li>\n                    <li>ISLAMSKOM PONAŠANJU.</li>\n                </ul>\n            <p class=\"lesson-text\">MIRZA JE U MEKTEB PRVI DAN DOŠAO SA SVOJIM RODITELJIMA.</p>\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; font-weight: bold;\">JA U MEKTEB IDEM</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">JA U MEKTEB IDEM PONOSIM SE TIME, SREĆU DA POSTIGNEM ŽELIM I SA TIME!</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">JA U MEKTEB IDEM RADOSTAN SAM ZATO, DŽENNET DA STEKNEM SREĆU, BLAGO, ZLATO.</p>\n                </div>\n             <p class=\"lesson-text\">OBRADOVAO SE SUSRETU SA SVOJIM DRUGOVIMA I DRUGARICAMA. ALI JE UPOZNAO I NOVE PRIJATELJE.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\">\n                3. PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>ŠTA UČIMO U MEKTEBU?</li>\n                    <li>NAUČI PJESMICU O MEKTEBU!</li>\n                    <li>NACRTAJ SVOJ MEKTEB I DŽAMIJU!</li>\n                    <li>ISPRIČAJ RODITELJIMA SVOJ DOŽIVLJAJ U MEKTEBU!</li>\n                </ol>\n            </div>\n        </div>","audio_src":"ja_idem_u_mekteb.mp3","redoslijed":4,"is_published":true,"kviz_pitanja":[{"answer":"Islamsko vjerovanje, dužnosti i ponašanje","options":["Matematiku i engleski jezik","Islamsko vjerovanje, dužnosti i ponašanje","Samo Kuran bez drugih predmeta","Samo arapski jezik"],"question":"Šta učimo u mektebu?"},{"answer":"Muallim i muallimu","options":["Muallim i muallimu","Samo naši roditelji","Samo imam iz džamije","Naši stariji brat i sestra"],"question":"Ko će nas učiti u mektebu?"},{"answer":"Obradovao se i upoznao nove prijatelje","options":["Uplašio se i plakao","Obradovao se i upoznao nove prijatelje","Bio je tužan i samotан","Nije mu se sviđalo"],"question":"Kako se osjećao Mirza kada je prvi dan došao u mekteb?"},{"answer":"Jer želi postići sreću i džennet","options":["Jer ne mora učiti","Jer želi postići sreću i džennet","Jer može biti kod kuće","Jer neće raditi"],"question":"Zašto je dječak ponosan što ide u mekteb?"},{"answer":"Sa svojim roditeljima","options":["Sa svojim prijateljima","Sa svojim učiteljima","Sa svojim roditeljima","Samo"],"question":"Sa kim je Mirza došao prvi dan u mekteb?"}]},{"nivo":1,"slug":"rabbi-jessir","naslov":"Dove za hairli početak - Rabbi jessir","content_html":"<div class=\"lesson-container\">\n        <h1>DOVA ZA HAJIRLI POČETAK - RABBI JESSIR</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/rabbi_jessir.jpg\">\n        </div>","audio_src":"rabbijessir.mp3","redoslijed":5,"is_published":true,"kviz_pitanja":[{"answer":"Svemogući Allah","options":["Svemogući Allah","Naši učitelji","Naši roditelji","Naši prijatelji"],"question":"Ko nam daje uspjeh i pomoć u našim poslovima?"},{"answer":"Za olakšanje, blagoslov i sreću","options":["Za novac i bogatstvo","Za olakšanje, blagoslov i sreću","Za igračke i darove","Za brze noge"],"question":"Šta molimo Allahu kada učimo rabbi jessir?"},{"answer":"Prije učenja ili pisanja zadaće","options":["Prije sna i odmora","Prije učenja ili pisanja zadaće","Prije gledanja televizije","Prije čišćenja"],"question":"Prije čega možemo učiti rabbi jessir?"},{"answer":"Rabbi jessir","options":["Rabbi akbar","Rabbi jessir","Bismillah","Subhanallah"],"question":"Kako se zove dova koju učimo za olakšanje?"},{"answer":"U mnogim korisnim poslovima i prilikama","options":["Samo kod kuće","Samo u školi","U mnogim korisnim poslovima i prilikama","Samo kod liječnika"],"question":"U koliko situacija možemo koristiti rabbi jessir?"}]},{"nivo":1,"slug":"dova-za-znanje","naslov":"Dova za znanje","content_html":"<div class=\"lesson-container\">\n        <h1>DOVA ZA ZNANJE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dova_za_znanje.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dova za znanje – Rabbi zidni ‘ilmen</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kiraet</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema znanju i učenju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti dovu kojom molimo Allaha da nam poveća znanje</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Stvaranje navike učenja dove prije sticanja znanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta radimo kad nešto želimo, a sami ne možemo postići? – Pitamo nekog ko može pomoći. Pa hajde da i mi za znanje, koje je najveći dar, zamolimo Allaha.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Dova za znanje glasi: <em>Rabbi zidni ‘ilmen</em> – Gospodaru moj, povećaj mi znanje!</p><p>Ovu dovu nas je naučio sam Allah, dž.š., u Kur’anu (sura Ta-ha, 114).</p><p>Učimo je prije početka učenja, prije časa u školi i mektebu, te kad god želimo nešto novo naučiti.</p><p>Postupak: Pišem dovu na tabli sa značenjem. Učimo je više puta, glasno i pravilno. Učenici je ponavljaju zajedno i pojedinačno.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Provjeravam ko je naučio dovu napamet. Dogovaramo se da je svaki dan učimo prije početka časa.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O DOVI ZA ZNANJE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">ALLAH JE SVEZNAJUĆI I ON ZNANJE DARUJE ONOME KOME ON HOĆE. NJEGA MOLIMO DA I NAMA UVEĆA ZNANJE DOVOM:</p>\n                \n                <div class=\"arabic-card\">\n                    <span class=\"arabic-text\">رَبِّ زِدْنِي عِلْمًا</span>\n                    <span class=\"trans-text\">RABBI ZIDNI ‘ILMÃ!</span>\n                    <p style=\"margin-top:10px;\">GOSPODARU MOJ, TI ZNANJE MOJE PROŠIRI! (KUR'AN, TA-HA, 114)</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> ZADATAK <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <p class=\"lesson-text\">NAPIŠITE NA KORICI SVESKE OVU DOVU! UČITE JE PRIJE POČETKA UČENJA I PISANJA ZADAĆE! POKLONITE OVU DOVU SVOJIM DRUGOVIMA I DRUGARICAMA!</p>\n            </div>\n        </div>","audio_src":"dova_za_znanje.mp3","redoslijed":6,"is_published":true,"kviz_pitanja":[{"answer":"Allah je sveznajući i On znanje daruje","options":["Allah je sveznajući i On znanje daruje","Nastavnik daruje znanje učenicima","Knjige daju znanje čitaocima","Roditelji uče djecu"],"question":"Ko je prema lekciji taj koji daruje znanje onome kome hoće?"},{"answer":"Rabbi zidni 'ilmã","options":["Rabbi zidni 'ilmã","Alhamdulillahi rabbil alamin","Subhanallah wa bihamdihi","Assalamu alaikum wa rahmatullahi"],"question":"Kako glasi dova za znanje na arapskom jeziku?"},{"answer":"Gospodaru moj, ti znanje moje proširi","options":["Gospodaru moj, ti znanje moje proširi","Gospodaru moj, pomoži mi u bedi","Gospodaru moj, daj mi zdravlje","Gospodaru moj, čuva me od zla"],"question":"Šta znači dova 'Rabbi zidni ilmã' na bosanskom jeziku?"},{"answer":"Prije početka učenja i pisanja zadaće","options":["Prije početka učenja i pisanja zadaće","Prije spavanja","Samo petkom nakon molitve","Samo kada se pripremam za ispite"],"question":"Kada treba učiti dovu za znanje prema zadatku u lekciji?"},{"answer":"Iz sure Ta-Ha, ajet 114","options":["Iz sure Ta-Ha, ajet 114","Iz sure Fatiha, ajet 1","Iz sure Ikhlas, ajet 1","Iz sure Nas, ajet 6"],"question":"Iz kojeg dijelа Kur'ana dolazi dova za znanje?"}]},{"nivo":1,"slug":"nasa-vjera","naslov":"Kako se zove naša vjera","content_html":"<div class=\"lesson-container\">\n        <h1>KAKO SE ZOVE NAŠA VJERA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/nasa_vjera.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kako se zove naša vjera</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i ponosa prema vjeri islamu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti naziv vjere, sljedbenika i njene osnovne karakteristike</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o vlastitom vjerskom identitetu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko vas je naučio prvim riječima o Allahu? Šta su vam roditelji rekli – koja je naša vjera? Hajde danas to lijepo da utvrdimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Naša vjera se zove <strong>islam</strong>.</p><p>Sljedbenici islama nazivaju se <strong>muslimani</strong> i <strong>muslimanke</strong>.</p><p>Riječ \"islam\" znači predanost Allahu, a \"musliman\" je onaj koji se predaje Allahovoj volji.</p><p>Naša vjera nas uči da vjerujemo u jednog Allaha i da je Muhammed, a.s., Allahov posljednji poslanik. Naša sveta knjiga je Kur’an.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam učenike: Kako se zove naša vjera? Kako se zovu njeni sljedbenici? U koga vjerujemo? Pohvaljujem tačne odgovore.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O NAŠOJ VJERI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">NAŠA VJERA JE ISLAM. MI SMO MUSLIMANI I MUSLIMANKE! MI VJERUJEMO U ALLAHA I POSLANIKA MUHAMMEDA, GOVORIMO ISTINU I RADIMO DOBRA DJELA!</p>\n                \n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; font-weight: bold;\">ISLAM</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">ISLAM MI JE VJERA</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">ISLAM MI JE SPAS</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">ISLAM MENE UČI</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">DA VOLIM SVE VAS.</p>\n                    <p class=\"lesson-text\" style=\"text-align: center; margin-top: 10px;\">ISLAM ŽRTVU TRAŽI</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">NAUKU I RAD</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">ISLAM NEĆE LAŽI</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">VJERUJ DOK SI MLAD.</p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">ISLAM JE VJERA KOJU JE UZVIŠENI ALLAH OBJAVIO PREKO SVOJIIH POSLANIKA CIJELOM ČOVJEČANSTVU!</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> ODGOVORI NA PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>KAKO SE ZOVE NAŠA VJERA?</li>\n                    <li>ŠTA SMO MI PO VJERI?</li>\n                    <li>ŠTA JE ISLAM?</li>\n                    <li>KAKO SE PJESNIK IZRAŽAVA O ISLAMU?</li>\n                    <li>ČEMU NAS ISLAM VODI?</li>\n                </ol>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>NAUČITI PJESMICU ISLAM NAPAMET</li>\n                </ul>\n            </div>\n        </div>","audio_src":"nasa_vjera.mp3","redoslijed":7,"is_published":true,"kviz_pitanja":[{"answer":"Islam","options":["Islam","Hrišćanstvo","Judaizam","Budizam"],"question":"Kako se zove naša vjera?"},{"answer":"Islam cijeloj čovječanstvu","options":["Samo Kuran","Islam cijeloj čovječanstvu","Samo dobre dijelove","Samo hrvatske knjige"],"question":"Što je Allah objavio preko svojih poslanika?"},{"answer":"U Allaha i poslanika Muhammeda","options":["U Allaha i poslanika Muhammeda","Samo u Allaha","U bogove prirode","U careve i kraljeve"],"question":"U koga vjerujemo kao muslimani?"},{"answer":"Da ih volimo","options":["Da ih mrzimo","Da im govorimo neistinu","Da ih volimo","Da ih izbjegavamo"],"question":"Što nas Islam učи da činimo prema drugima?"},{"answer":"Laži i neistinu","options":["Dobra djela","Laži i neistinu","Učenje","Rad i žrtvu"],"question":"Šta Islam ne dozvoljava?"}]},{"nivo":1,"slug":"allahu-rabbi","naslov":"Allahu Rabbi","content_html":"<div class=\"lesson-container\">\n        <h1>ALLAHU RABBI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/allahu_rabbi.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Allahu Rabbi – ilahija</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kiraet</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema ilahijama i spominjanju Allahovog imena</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti riječi i melodiju ilahije \"Allahu Rabbi\"</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje muzičkog osjećaja i pamćenja kroz pjesmu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, volite li pjevati? Postoje posebne pjesme koje muslimani pjevaju u slavu Allaha – zovu se ilahije. Danas učimo jednu kratku i lijepu ilahiju.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ilahija \"Allahu Rabbi\" pjeva o tome da je Allah naš Gospodar, a Muhammed, a.s., naš poslanik.</p><p>Postupak: Učim ilahiju nekoliko puta sam, polako i razgovijetno. Zatim učenici ponavljaju stih po stih.</p><p>Razgovaram s djecom o tome šta znače riječi: Allahu Rabbi (Allah je moj Gospodar), Muhammed Nebijji (Muhammed je moj Vjerovjesnik).</p><p>Ilahiju učimo u različitim prilikama: kod kuće, u mektebu, na priredbama.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici zajedno pjevaju cijelu ilahiju. Pohvaljujem trud i najavljujem ponavljanje na sljedećem času.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> ODGOVORI NA NAJVAŽNIJA PITANJA! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>KO JE TVOJ GOSPODAR?</li>\n                    <li>KO TI JE POSLANIK?</li>\n                    <li>KOJA JE TVOJA KNJIGA?</li>\n                    <li>KOJA JE TVOJA VJERA?</li>\n                </ol>\n            </div>\n        </div>","audio_src":"allahu_rabbi.mp3","redoslijed":8,"is_published":true,"kviz_pitanja":[{"answer":"Allah","options":["Allah","Muhammed","Knjiga","Vjera"],"question":"Ko je tvoj Gospodar prema lekciji 'Allahu Rabbi'?"},{"answer":"Muhammed","options":["Muhammed","Allah","Neko drugi Poslanik","Svaki čovjek"],"question":"Ko je tvoj Poslanik prema islamu?"},{"answer":"Kur'an","options":["Kur'an","Biblija","Tora","Psalmi"],"question":"Koja je toja Knjiga kao muslimana?"},{"answer":"Islam","options":["Islam","Kršćanstvo","Judaizam","Hinduizam"],"question":"Koja je tvoja vjera prema lekciji?"},{"answer":"Allah je moj Gospodar, Muhammed je moj Poslanik","options":["Allah je moj Gospodar, Muhammed je moj Poslanik","Samo Allah je Bog","Kur'an je najbolja knjiga","Islam je samo vjera"],"question":"Šta znači dua 'Allahu Rabbi'?"}]},{"nivo":1,"slug":"zuri-mirza-na-pouku","naslov":"Žuri Mirza na pouku","content_html":"<div class=\"lesson-container\">\n        <h1>ŽURI MIRZA NA POUKU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mirza_zuri.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Žuri Mirza na pouku – pjesma o redovnosti</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema redovnom dolasku u mekteb</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti poruku pjesme i primijeniti je u svom životu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike tačnosti i odgovornosti</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, znate li nekog drugara koji uvijek dolazi na vrijeme i radostan je što ide u mekteb? Hajde da upoznamo Mirzu iz naše pjesmice.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Pjesma \"Žuri Mirza na pouku\" govori o dječaku koji rado i na vrijeme dolazi u mekteb da bi učio o vjeri.</p><p>Pjesmu čitam izražajno, a učenici slušaju. Zatim je čitamo zajedno.</p><p>Razgovor: Zašto Mirza žuri u mekteb? Kako se vi pripremate za dolazak? Šta nas čeka u mektebu?</p><p>Učenici stih po stih ponavljaju, a najbolje pamtitelji recituju pred razredom.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici recituju strofe pjesme. Dogovaramo se da i mi, poput Mirze, redovno i radosno dolazimo u mekteb.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O MIRZINOM UZBUĐENJU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO PJESMICU <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n    <div class=\"info-box\" style=\"line-height: 1.4;\"> <p class=\"lesson-text\" style=\"text-align: center; font-weight: bold; margin-bottom: 20px;\">ŽURI MIRZA NA POUKU</p>\n        <hr style=\"border: 0; height: 3px; background: #145234; border-radius: 10px; margin: 20px 0; opacity: 0.7;\">\n        <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 20px;\">\n            RANIM JUTROM PRIJE ZORE,<br>\n            USTO’ MIRZA IZ POSTELJE.<br>\n            UMIO SE, OBUKAO,<br>\n            KO’ ZA BAJRAM DOTJERAO.\n        </p>\n\n        <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 20px;\">\n            UZBUĐEN JE USTREPTAO,<br>\n            NE GOVORI, UMUKAO.<br>\n            PA SVE NEŠTO IZVIRUJE,<br>\n            ČEKA BABU PROVIRUJE.\n        </p>\n\n        <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 20px;\">\n            NIJE ČUDO TAKAV ŠTO JE,<br>\n            JUČE BABO OBEĆ’O JE.<br>\n            U DŽAMIJU S NJIME HODIT’,<br>\n            NA POUKU MIRZU VODIT’.\n        </p>\n\n        <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 20px;\">\n            TU ĆE UČIT O ISLAMU,<br>\n            O ALLAHU I KUR’ANU.<br>\n            O BOŽIJEM MILJENIKU,<br>\n            MUHAMEDU POSLANIKU.\n        </p>\n\n        <p class=\"lesson-text\" style=\"text-align: right; font-style: italic; margin-top: 30px;\">REŠAD KADIĆ</p>\n    </div>\n</div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> RAZGOVOR O PJESMICI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>ZAŠTO JE MIRZA TOLIKO UZBUĐEN?</li>\n                    <li>KAKO SE MIRZA DOTJERAO ZA ODLAZAK U MEKTEB?</li>\n                    <li>ŠTA JE BABO OBEĆAO MIRZI?</li>\n                    <li>ŠTA ĆE MIRZA SVE NAUČITI NA POUCI?</li>\n                </ol>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>NAUČITI PJESMICU ŽURI MIRZA NA POUKU NAPAMET.</li>\n                    <li>NACRTAJ MIRZU KAKO SRETAN IDE U DŽAMIJU.</li>\n                </ul>\n            </div>\n        </div>","audio_src":"mirza_zuri.mp3","redoslijed":9,"is_published":true,"kviz_pitanja":[{"answer":"Ranim jutrom prije zore","options":["Ranim jutrom prije zore","After breakfast","Nakon što se probudio babu","U podne kada je sunce"],"question":"Kada se Mirza usto' iz postelje?"},{"answer":"Ko' za bajram dotjerao","options":["Ko' za bajram dotjerao","Obukao samo pantalone","Obuo cipele od oca","Stavio samo majicu"],"question":"Kako se Mirza dotjerao prije odlaska?"},{"answer":"U džamiju s njime hodit' i na pouku ga vodit'","options":["U džamiju s njime hodit' i na pouku ga vodit'","Kupiti mu igračke","Dati mu novac za sladoled","Ostati kod kuće cijeli dan"],"question":"Šta je Mirzi obećao babu juče?"},{"answer":"O Allahu, Kur'anu i proroku Muhamedu","options":["O Allahu, Kur'anu i proroku Muhamedu","Kako pisati na arapskom jeziku","Samo male duáe","Samo molitve za jelo"],"question":"Što će Mirza naučiti na pouci u džamiji?"},{"answer":"Jer ide prvi put na pouku u džamiju","options":["Jer ide prvi put na pouku u džamiju","Jer je dobio novu igračku","Jer je njegovo rođendan","Jer dolaze njegovi prijatelji"],"question":"Zašto je Mirza toliko uzbuđen tog jutra?"}]},{"nivo":1,"slug":"kelimei-sehadet-1","naslov":"Kelimei-šehadet","content_html":"<div class=\"lesson-container\">\n        <h1>KELIMEI ŠEHADET</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/kelimei_sehadet.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kelimei-šehadet – prvi islamski šart</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o pripadnosti islamu i ponosa zbog vjerovanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pravilno izgovoriti i razumjeti značenje kelimei-šehadeta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike čestog izgovaranja šehadeta</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Es-selamu alejkum, djeco. Ko od vas zna kako se zove naša vjera? A kako, nekim posebnim riječima, izjavljujemo da smo muslimani? Te riječi danas učimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kelimei-šehadet su riječi kojima izjavljujemo i svjedočimo da smo muslimani.</p><p>Kelimei-šehadet glasi: <em>Ešhedu en lā ilāhe illallāh, ve ešhedu enne Muhammeden ‘abduhū ve resūluhū.</em></p><p>Značenje: Vjerujem i izjavljujem da je samo Allah Bog, i vjerujem i izjavljujem da je Muhammed Allahov rob i poslanik.</p><p>Šehadet je prvi islamski šart. Izgovara ga svako ko prima islam, a muslimani ga ponavljaju u namazu i u mnogim drugim prilikama.</p><p>Postupak: Pišem šehadet na tabli arapski i sa transkripcijom. Učim ga polako, naglašavajući svaku riječ. Učenici ga ponavljaju zajedno i pojedinačno. Ispravljam izgovor.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Provjeravam ko je naučio šehadet napamet. Učenici recituju i pjesmicu \"Šehadet\". Najavljujem da ćemo sljedeći čas učiti o ostalim islamskim šartima.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O SVJEDOČENJU VJERE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                <div class=\"lesson-text\">\n                    <p>ES-SELAMU ‘ALEJKUM, DRAGA DJECO! KELIME-I ŠEHADET SU RIJEČI S KOJIMA IZJAVLJUJEMO I SVJEDOČIMO DA SMO MUSLIMANI I MUSLIMANKE.</p>\n                    <p>OVE RIJEČI SU NAJVAŽNIJI POTVRDA NAŠE PRIPADNOSTI ISLAMU. KADA IH IZGOVARAMO, MI CIJELOM SVIJETU PORUČUJEMO ŠTA JE U NAŠIM SRCIMA I U ŠTA VJERUJEMO.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">SVOJU PRIPADNOST ISLAMU POTVRĐUJEMO IZGOVARANJEM KELIMEI ŠEHADETA. KELIMEI ŠEHADET GLASI:</p>\n                \n                <div class=\"arabic-card\">\n                    <span class=\"arabic-text\" style=\"text-align: right;\"\">أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ</span>\n                    <span class=\"trans-text\">EŠHEDU EN LÃ ILÃHE ILLALLÃH, VE EŠHEDU ENNE MUHAMMEDEN ‘ABDUHŨ VE RESŨLUHŨ!</span>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px; font-weight: bold;\">OVE RIJEČI ZNAČE:</p>\n                <p class=\"lesson-text\">VJERUJEM I IZJAVLJUJEM DA JE SAMO ALLAH BOG, I VJERUJEM I IZJAVLJUJEM DA JE MUHAMMED ALLAHOV ROB I POSLANIK!</p>\n\n                <div class=\"info-box\" style=\"margin-top: 25px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; font-weight: bold;\">ŠEHADET</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">NEMA BOGA OSIM ALLAHA,</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">NEKA MU JE VJEČNA HVALA,</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">A MUHAMMED MILJENIK,</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">ALLAHOV JE POSLANIK.</p>\n                    <p class=\"lesson-text\" style=\"text-align: right; font-size: 1rem;\">R. KADIĆ</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('vazno', this)\"> VAŽNO JE ZAPAMTITI! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"vazno\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>KELIMEI ŠEHADET JE PRVI ISLAMSKI ŠART.</li>\n                    <li>KADA NEKO PRIMA ISLAM IZGOVARA KELIMEI ŠEHADET.</li>\n                    <li>SVAKOG DANA SVAKI MUSLIMAN VIŠE PUTA IZGOVARA KELIMEI ŠEHADET DOK KLANJA.</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">ODGOVORI NA PITANJA:</p>\n                <ol class=\"lesson-text\" style=\"padding-left: 30px; margin-bottom: 20px;\">\n                    <li>KAKO POTVRĐUJEMO PRIPADNOST ISLAMU?</li>\n                    <li>IZGOVORI KELIMEI ŠEHADET!</li>\n                    <li>ŠTA ZNAČE OVE RIJEČI?</li>\n                    <li>ODRECITUJ PJESMICU ŠEHADET!</li>\n                </ol>\n                \n                <p class=\"lesson-text\" style=\"font-weight: bold;\">ZADACI:</p>\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>NAUČITI NAPAMET KELIMEI ŠEHADET I NJEGOV PRIJEVOD.</li>\n                    <li>SA MUALLIMOM I SA RODITELJIMA RAZGOVARATI O VAŽNOSTI KELIMEI ŠEHADETA.</li>\n                    <li>UZ POMOĆ RODITELJA PREVESTI ILAHIJU SA YOUTUBE - LA ILAHE ILELLAH.</li>\n                </ul>\n            </div>\n        </div>","audio_src":null,"redoslijed":10,"is_published":true,"kviz_pitanja":[{"answer":"Riječi kojima izjavljujemo da smo muslimani","options":["Riječi kojima izjavljujemo da smo muslimani","Naziv za islamski praznik","Posebna dova prije jela","Dio Kur'ana koji učimo napamet"],"question":"Šta je Kelimei šehadet?"},{"answer":"Prvi","options":["Prvi","Drugi","Treći","Peti"],"question":"Koji je po redu islamski šart Kelimei šehadet?"},{"answer":"Vjerujem da je samo Allah Bog i da je Muhammed Allahov rob i poslanik","options":["Vjerujem da je samo Allah Bog i da je Muhammed Allahov rob i poslanik","Hvala Allahu na svemu","Tražim oprost od Allaha","Allah je najveći"],"question":"Šta znače riječi šehadeta?"},{"answer":"Allahov rob i poslanik","options":["Allahov rob i poslanik","Allahov sin","Prvi čovjek","Halifa"],"question":"Ko je Muhammed prema Kelimei šehadetu?"},{"answer":"Kada neko prima islam i kada klanjamo namaz","options":["Kada neko prima islam i kada klanjamo namaz","Samo na Bajram","Samo prije spavanja","Samo kad se pozdravljamo"],"question":"Kada izgovaramo Kelimei šehadet?"}]},{"nivo":1,"slug":"selam","naslov":"Islamski pozdrav - selam","content_html":"<div class=\"lesson-container\">\n        <h1>ISLAMSKI POZDRAV - SELAM</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/selam.jpg\">\n        </div>","audio_src":"selam.mp3","redoslijed":11,"is_published":true,"kviz_pitanja":[{"answer":"Pozdrav kojim se muslimani međusobno pozdravljaju","options":["Pozdrav kojim se muslimani međusobno pozdravljaju","Posebna molitev koju čitamo pet puta dnevno","Naziv za islamski praznik","Dio Kur'ana koji učimo napamet"],"question":"Šta je selam?"},{"answer":"Es-selamu alejkum","options":["Es-selamu alejkum","Alhamdulillah","Bismillah","Subhanallah"],"question":"Kako glasi islamski pozdrav?"},{"answer":"Ve alejkumus-selam","options":["Ve alejkumus-selam","Es-selamu alejkum","Alhamdulillah","Allahu akbar"],"question":"Kako se odgovara na selam?"},{"answer":"Neka je na vas Allahov mir i blagoslov","options":["Neka je na vas Allahov mir i blagoslov","Hvala Allahu za sve","Nema boga osim Allaha","Neka nam Allahu prosti sve greške"],"question":"Šta znači selam?"},{"answer":"Roditeljima, rodbini i prijateljima pri ulasku i izlasku","options":["Roditeljima, rodbini i prijateljima pri ulasku i izlasku","Samo muezzinu tijekom azana","Samo učitelju u školi svaki dan","Samo Imamu u džamiji nakon namaza"],"question":"Kome se i kada se naziva selam?"}]},{"nivo":1,"slug":"voda-izvor-zivota","naslov":"Voda je izvor života","content_html":"<div class=\"lesson-container\">\n        <h1>VODA JE IZVOR ŽIVOTA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/voda.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Voda je izvor života</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje zahvalnosti Allahu na blagodati vode</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti važnost vode za sav život i njenu ulogu u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike štednje i čuvanja vode</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta bi se desilo da nemamo vode? Možemo li bez nje? Hajde danas razgovarati o ovom velikom Allahovom daru.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah, dž.š., u Kur’anu kaže da je od vode svako živo biće stvoreno (sura El-Enbija, 30).</p><p>Voda je potrebna za piće, čistoću tijela, abdest i gusul, te za biljke i životinje.</p><p>Bez vode nema života – ona je jedna od najvećih Allahovih blagodati.</p><p>Razgovor: Kako se zahvaljujemo Allahu na vodi? Treba li je rasipati? Kako se ponašamo kada uzimamo abdest – štedimo li vodu?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju gdje sve koristimo vodu. Dogovaramo se da je čuvamo i ne rasipamo, jer je to ibadet i znak zahvalnosti.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O NAJVEĆOJ BLAGODATI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">VODA JE JEDNA OD NAJVEĆIH ALLAHOVIH MILOSTI. UZVIŠENI ALLAH SPOMENUO JE U KUR'ANU STVARANJE SVEGA ŽIVOG IZ VODE. ZATO I KAŽEMO DA JE VODA IZVOR ŽIVOTA.</p>\n                \n                <div class=\"arabic-card\">\n                    <span class=\"trans-text\">... MI OD VODE SVE ŽIVO STVARAMO...</span>\n                    <p style=\"margin-top:10px; font-weight: bold;\">(KUR'AN, EL-ENBIJA', 30)</p>\n                </div>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">VODA JE NUŽNA ZA ŽIVOT LJUDI I SVIH ŽIVIH ORGANIZAMA. SVA ŽIVA BIĆA NAJVEĆIM DIJELOM SASTOJE SE OD VODE. NAŠA TIJELA IMAJU U SEBI OKO 70 POSTO VODE. VODA ČINI VIŠE OD DVIJE TREĆINE UKUPNE POVRŠINE ZEMLJE. NEPREKIDNO KRUŽENJE VODE U PRIRODI SAVRŠENI JE SKLAD KOJEG JE UZVIŠENI ALLAH STVORIO.<br>\nMILOSTIVI ALLAH JE VODU STVORIO ČISTOM I ČISTEĆOM. OSIM ŠTO VODA ČISTI VIDLJIVU NEČISTOĆU I NEVIDLJIVE BAKTERIJE, ONA NAM POMAŽE I DA SE OPUSTIMO I TAKO DUHOVNO PRIPREMIMO ZA NAMAZ. ZATO JE I PROPISANO ČIŠĆENJE VODOM I\nREDOVNO KUPANJE.</p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"font-weight: bold; margin-bottom: 10px;\">REKAO JE MUHAMMED, ALEJHIS-SELAM:</p>\n                    <span class=\"trans-text\">“NAJBOLJA VODA NA LICU ZEMLJE JE ZEMZEM. U NJOJ SE KRIJE HRANA ZA GLADNE I LIJEK ZA BOLESNE.”</span>\n                    <p style=\"margin-top:10px; font-weight: bold; text-align: right;\">(TABERANI, IBN HIBBAN)</p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">PITKE VODE IMA MALO, ZATO ŠTEDIMO VODU I SPASIMO ŽIVOT NA ZEMLJI!<br>RAZMIŠLJAJMO O BLAGODATI VODE I BUDIMO ZAHVALNI SVOME GOSPODARU!</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>OD ČEGA JE UZVIŠENI ALLAH SVE STVORIO?</li>\n                    <li>ZAŠTO KAŽEMO DA JE VODA IZVOR ŽIVOTA?</li>\n                    <li>KAKO JE VODA I ČISTA I ČISTEĆA?</li>\n                    <li>ZAŠTO ŠTEDIMO VODU?</li>\n                    <li>NA ČEMU ZAHVALJUJEMO SVOME GOSPODARU?</li>\n                    <li>KOJA JE NAJBOLJA VODA NA ZEMLJI?</li>\n                </ol>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> ZADACI I ZAPAMTI! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <div class=\"info-box\" style=\"margin-bottom: 20px;\">\n                    <p class=\"lesson-text\" style=\"font-weight: bold;\">ZAPAMTI!</p>\n                    <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                        <li>VODA JE JEDNA OD NAJVEĆIH BLAGODATI ALLAHA, DŽ.Š.</li>\n                        <li>NAJBOLJA VODA NA ZEMLJI JE ZEMZEM.</li>\n                    </ul>\n                </div>\n            </div>\n        </div>","audio_src":"voda.mp3","redoslijed":12,"is_published":true,"kviz_pitanja":[{"answer":"Od vode","options":["Od zemlje","Od vode","Od zraka","Od vatre"],"question":"Od čega je Uzvišeni Allah sve živo stvorio?"},{"answer":"Oko 70 posto","options":["Oko 50 posto","Oko 70 posto","Oko 90 posto","Oko 30 posto"],"question":"Koliko posto vode ima u ljudskom tijelu?"},{"answer":"Zemzem","options":["Morska voda","Zemzem","Riječna voda","Kišna voda"],"question":"Koja je najbolja voda na licu zemlje?"},{"answer":"Voda čisti i duhovnо nas priprema","options":["Jer je voda hladna","Jer čini nam se","Voda čisti i duhovnо nas priprema","Jer je tako tradicija"],"question":"Zašto je propisano čišćenje vodom prije namaza?"},{"answer":"Oko dvije trećine","options":["Manje od polovine","Oko dvije trećine","Samo četvrtinu","Cijelу površinu"],"question":"Koliko vode čini površinu Zemlje?"}]},{"nivo":1,"slug":"subhaneke","naslov":"Subhaneke s prijevodom","content_html":"<div class=\"lesson-container\">\n        <h1>SUBHANEKE S PRIJEVODOM</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/subhaneke.jpg\">\n        </div>","audio_src":"subhaneke.mp3","redoslijed":13,"is_published":true,"kviz_pitanja":[{"answer":"Vrsta zikra - spominjanja Allaha Uzvišenog","options":["Vrsta zikra - spominjanja Allaha Uzvišenog","Islamska knjiga za učenje","Vrsta hrane koju jedemo na Bajramu","Islamski praznik"],"question":"Šta je Subhaneke?"},{"answer":"Često, a posebno na početku svakog namaza","options":["Samo u mjesecu Ramazanu","Često, a posebno na početku svakog namaza","Samo na джумʻи","Samo na školskom času"],"question":"Kada učimo i izgovaramo Subhaneke?"},{"answer":"Veličamo i slavimo Allaha","options":["Veličamo i slavimo Allaha","Prosimo Allahu hljeb","Zahvaljujemo na hrани","Tražimo oprost od Allaha"],"question":"Šta znači prijevod 'Slava tebi, Allahu moj'?"},{"answer":"Osim Allaha drugog boga nema","options":["Tri boga","Dva boga","Osim Allaha drugog boga nema","Deset bogova"],"question":"Koliko boga postoji prema Subhaneku?"},{"answer":"Na svakom namazu","options":["Na svakom namazu","Samo kod kuće","Samo u džamiji","Samo prije spavanja"],"question":"Gdje se Subhaneke uči?"}]},{"nivo":1,"slug":"sura-el-fatiha","naslov":"Sura El-Fatiha","content_html":"<div class=\"lesson-container\">\n        <h1>SURA FATIHA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/fatiha.jpg\">\n        </div>","audio_src":"fatiha.mp3","redoslijed":14,"is_published":true,"kviz_pitanja":[{"answer":"Sura Fatiha","options":["Sura Fatiha","Sura Bakara","Sura Aliimran","Sura Nisa"],"question":"Koja je Sura prva u Kur'anu?"},{"answer":"7 ajeta","options":["5 ajeta","7 ajeta","10 ajeta","3 ajeta"],"question":"Koliko ajeta ima Sura Fatiha?"},{"answer":"Majka Kur'ana","options":["Otac Kur'ana","Majka Kur'ana","Srdce Kur'ana","Početak Kur'ana"],"question":"Kako se Sura Fatiha još naziva?"},{"answer":"U namazu, buđenju i spavanju","options":["Samo u mektebskom času","U namazu, buđenju i spavanju","Samo tijekom Ramazana","Samo kod kuće"],"question":"U kojim prilikama se učimo Sura Fatiha?"},{"answer":"Muhammed, a.s.","options":["Abubekr, r.a.","Muhammed, a.s.","Omar, r.a.","Ali, r.a."],"question":"Ko je rekao da je Sura Fatiha najbolja dova?"}]},{"nivo":1,"slug":"allah-dz-s","naslov":"Allah, dželle šanuhu - Svemogući Stvoritelj","content_html":"<div class=\"lesson-container\">\n        <h1>SVEMOGUĆI STVORITELJ</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/stvoritelj.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Allah, dž.š. – Svemogući Stvoritelj</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i strahopoštovanja prema Allahu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti da je Allah jedan, Stvoritelj svega i Gospodar svih svjetova</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti da je Allah uvijek prisutan i sve zna</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je stvorio nebo, sunce, zvijezde i nas? Ko nam daje hranu, zdravlje, roditelje? Hajde danas da naučimo nešto više o našem Stvoritelju.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Naš Bog se zove <strong>Allah</strong>. On je jedan, jedini, nema druga ni saučesnika.</p><p>Allah je Stvoritelj svega što postoji – nas, životinja, biljaka, planeta i čitavog svemira.</p><p>Kad god spomenemo Allahovo ime, lijepo je dodati <em>dželle šanuhu</em> (uzvišen je) ili kratko <em>dž.š.</em></p><p>Allah sve vidi, sve čuje i sve zna – i ono što govorimo i ono što mislimo.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam: Ko je stvorio sve? Kako spominjemo Allahovo ime? Učenici odgovaraju, a ja pohvaljujem ispravne odgovore.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O FABRICI I STVARANJU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">ALLAH JE STVORIO SVE ŠTO POSTOJI: PLANETE, NEBESA, ZEMLJU, ŽIVOTINJE I LJUDE.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">ON JE STVORIO PLANINE, RIJEKE I BRDA, SUNCE, MJESEC I ZVIJEZDE, BILJKE, VOĆE I POVRĆE, TE ČOVJEKA - MUŠKARCA I ŽENU.</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">ALLAH JE JEDAN I ON JE STVORITELJ SVJETLOSTI I TAME, ŽIVOTA I SMRTI.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('vazno', this)\"> VAŽNO JE ZAPAMTITI! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"vazno\" class=\"lesson-content\">\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"font-weight: bold;\">ZAPAMTI!</p>\n                    <p class=\"lesson-text\">KADA SPOMENEMO ALLAHOVO IME KAŽEMO: <span style=\"color: var(--primary); font-weight: bold;\">DŽELLE ŠANUHU (DŽ.Š.)</span> – ŠTO ZNAČI UZVIŠENI.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> MOJI ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>NACRTAJ PET STVARI KOJE JE ALLAH STVORIO.</li>\n                    <li>SA RODITELJIMA POSLUŠAJ ILAHIJE O STVORITELJU I RAZGOVARAJTE O ČEMU ONE GOVORE.</li>\n                    <li>POKUŠAJ PREVESTI JEDNU ILAHIJU NA BOSANSKI JEZIK UZ POMOĆ STARIJIH.</li>\n                </ul>\n            </div>\n        </div>","audio_src":"stvoritelj.mp3","redoslijed":15,"is_published":true,"kviz_pitanja":[{"answer":"Planete, nebesa, zemlju, životinje i ljude","options":["Samo životinje i biljke","Planete, nebesa, zemlju, životinje i ljude","Samo sunce i mjesec","Samo planine i rijeke"],"question":"Šta je Allah stvorio prema lekciji?"},{"answer":"Dželle šanuhu (Dž.Š.)","options":["Allahu akbar","Dželle šanuhu (Dž.Š.)","Subhana Allahu","Bismillah"],"question":"Koja kratka forma se koristi kada spomenemo Allahovo ime?"},{"answer":"Uzvišeni","options":["Velik i moćan","Uzvišeni","Milosrdni i maganan","Stvoritelj neba"],"question":"Šta znači izrazu 'Dželle šanuhu'?"},{"answer":"Allah","options":["Sunce","Mjesec","Allah","Priroda"],"question":"Ko je Stvoritelj svjetlosti, tame, života i smrti?"},{"answer":"Pet stvari koje je Allah stvorio","options":["Deset životinja","Pet stvari koje je Allah stvorio","Sve planete","Sve rijeke na svijetu"],"question":"Šta bi trebalo da nacrtaš kao zadatak iz ove lekcije?"}]},{"nivo":1,"slug":"muhammed-as-poslanik","naslov":"Muhammed, a.s., je naš poslanik","content_html":"<div class=\"lesson-container\">\n        <h1>MUHAMMED, ALEJHIS-SELAM, JE NAŠ POSLANIK</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/poslanik.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Muhammed, a.s., je naš poslanik</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Allahovom Poslaniku, a.s.</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti osnovne podatke o Muhammedu, a.s., i njegovoj ulozi</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike donošenja salavata na Poslanika</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koju knjigu je Allah, dž.š., poslao muslimanima? Preko koga? Danas govorimo o tome ko je Muhammed, a.s., i zašto ga toliko volimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Muhammed, a.s., je posljednji Allahov poslanik. Allah ga je poslao da nas pouči vjeri.</p><p>Rođen je u Mekki, a Allahov govor (Kur’an) primao je preko meleka Džibrila.</p><p>Kad god spomenemo njegovo ime, donesemo salavat: <em>sallallahu ‘alejhi ve sellem</em> (s.a.v.s.) ili <em>alejhis-selam</em> (a.s.).</p><p>Muhammed, a.s., je bio najljepšeg ahlaka – iskren, milostiv, pravedan – i on je naš najveći uzor.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici ponavljaju: Ko je Muhammed, a.s.? Šta kažemo kad spomenemo njegovo ime? Učimo zajedno: <em>Allahumme salli ‘alā Muhammed.</em></p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O NAJPOZNATIJEM ČOVJEKU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">MUHAMMED, ALEJHIS-SELAM, JE POSLJEDNJI ALLAHOV POSLANIK. ROĐEN JE U MEKKI 571. GODINE.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">NJEGOV OTAC SE ZVAO ABDULLAH, A MAJKA AMINA. POŠTO SU MU RODITELJI RANO UMRLI, O NJEMU JE PRVO BRINUO DJED ABDULMUTTALIB, A POSLIJE AMIDŽA EBU TALIB.</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">ALLAH GA JE ODABRAO DA POSTANE POSLJEDNJI POSLANIK KADA JE IMAO 40 GODINA. SVI MUSLIMANI TREBAJU ZNATI OVE VAŽNE INFORMACIJE O SVOME POSLANIKU.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('vazno', this)\"> VAŽNO JE ZAPAMTITI! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"vazno\" class=\"lesson-content\">\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"font-weight: bold;\">ZAPAMTI!</p>\n                    <p class=\"lesson-text\">KADA SPOMENEMO IME MUHAMMED KAŽEMO: <span style=\"color: var(--primary); font-weight: bold;\">ALEJHIS-SELAM (SKRAĆENO A.S.)</span> – ŠTO ZNAČI NEKA JE NA NJEGA ALLAHOV MIR!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> MOJI ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">ODGOVORI NA PITANJA:</p>\n                <ol class=\"lesson-text\" style=\"padding-left: 30px; margin-bottom: 20px;\">\n                    <li>KO JE POSLJEDNJI ALLAHOV POSLANIK?</li>\n                    <li>KAKO SU SE ZVALI NJEGOVI RODITELJI?</li>\n                    <li>ŠTA KAŽEMO KADA SPOMENEMO IME MUHAMMED?</li>\n                </ol>\n                \n                <p class=\"lesson-text\" style=\"font-weight: bold;\">ZADACI:</p>\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>SA RODITELJIMA RAZGOVARAJ O MUHAMMEDU, ALEJHIS-SELAM.</li>\n                    <li>POGLEDAJ CRTANI FILM O ŽIVOTU POSLANIKA MUHAMMEDA, A.S.</li>\n                </ul>\n            </div>\n        </div>","audio_src":"muhammed_as.mp3","redoslijed":16,"is_published":true,"kviz_pitanja":[{"answer":"U Mekki","options":["U Medini","U Mekki","U Jerusalemu","U Bagdadu"],"question":"U kojem gradu je rođen Muhammed, alejhis-selam?"},{"answer":"Abdullah","options":["Amidža Abu Talib","Abdullah","Abdulmuttalib","Umar"],"question":"Kako se zvao otac Muhammeda, alejhis-selam?"},{"answer":"U 571. godini","options":["U 540. godini","U 571. godini","U 610. godini","U 632. godini"],"question":"U kojem godinu je rođen Muhammed, alejhis-selam?"},{"answer":"Neka je na njega Allahov mir","options":["Allah je svemoćan","Neka je na njega Allahov mir","Allah ga je poslao","Alejhisselam sigurno"],"question":"Šta znači A.S. kada napišemo Muhammed, a.s.?"},{"answer":"Četrdeset godina","options":["Trideset godina","Četrdeset godina","Pedeset godina","Dvadeset godina"],"question":"Koliko je godina imao Muhammed kada je postao poslanik?"}]},{"nivo":1,"slug":"hasbi-rabbi","naslov":"Hasbi Rabbi","content_html":"<div class=\"lesson-container\">\n        <h1>HASBI RABBI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/hasbi_rabbi.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Hasbi Rabbi – ilahija/dova</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kiraet</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema spominjanju Allaha i Poslanika, a.s.</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti riječi ilahije \"Hasbi Rabbi\"</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti memorisanja i lijepog učenja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kome se obraćamo kada nam je teško? Ko nam je uvijek dovoljan? Hajde danas naučiti jednu prelijepu ilahiju kojom to izričemo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ilahija glasi: <em>Hasbi Rabbi džellallah, ma fi kalbi gajrullah, nūr Muhammed sallallah, lā ilāhe illallah.</em></p><p>Značenje: Dovoljan mi je Gospodar moj, Uzvišeni Allah; u mom srcu nema nikog osim Allaha; svjetlost je Muhammed, neka je Allahov salavat na njega; nema boga osim Allaha.</p><p>Postupak: Učim ilahiju polako stih po stih. Učenici ponavljaju zajedno i pojedinačno. Pažnju usmjeravam na pravilan izgovor.</p><p>Razgovor: Šta nam ova ilahija poručuje o našem odnosu prema Allahu i Poslaniku, a.s.?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici zajedno uče cijelu ilahiju. Najboljima dajem priliku da je samostalno prouče pred razredom.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O NAJVEĆEM SNAGATORU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO STIHOVE ILAHIJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"text-align: center; font-weight: bold; font-size: 1.6rem;\">\n                    HASBĨ RABBĨ DŽELLALLÃH<br>\n                    MÃ FĨ KALBĨ GAJRULLÃH<br>\n                    NŨR MUHAMMED SALLALLÃH<br>\n                    LÃ ILÃHE ILLALLÃH\n                </p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 25px; text-align: center;\">\n                    MENI JE DOVOLJAN UZVIŠENI ALLAH, U MOM SRCU JE SAMO ALLAH. MOJE SVJETLO JE MUHAMMED, BOG JE JEDAN, SAMO ALLAH.\n                </p>\n                <p class=\"lesson-text\" style=\"text-align: center; font-weight: bold;\">LA ILAHE ILLALLAH!</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('vazno', this)\"> VAŽNO JE ZAPAMTITI! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"vazno\" class=\"lesson-content\">\n                <p class=\"lesson-text\">MUSLIMAN SE OSLANJA SAMO NA ALLAHA, DŽELLE ŠANUHU, VJERUJE U NJEGA I IZVRŠAVA NJEGOVE NAREDBE. MUHAMMED, ALEJHIS-SELAM, JE SVJETLO U NAŠIM SRCIMA TAKO ŠTO NAM JE UZOR U PONAŠANJU.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>KAKO GLASI ILAHIJA HASBI RABBI?</li>\n                    <li>NA KOGA SE OSLANJA MUSLIMAN?</li>\n                    <li>KAKO NAM JE MUHAMMED, ALEJHIS-SELAM, SVJETLO?</li>\n                </ol>\n            </div>\n        </div>","audio_src":"hasbi_rabbi.mp3","redoslijed":17,"is_published":true,"kviz_pitanja":[{"answer":"Meni je dovoljan Uzvišeni Allah","options":["Meni je dovoljan Uzvišeni Allah","Allah je moj najbolji prijatelj","Molim te Allah pomozi mi","Hvala ti Allah na svemu"],"question":"Šta znači izraz 'Hasbi Rabbi'?"},{"answer":"Samo na Allaha, Dželle Šanuhu","options":["Samo na Allaha, Dželle Šanuhu","Na svoje roditelje i učitelje","Na svoje vlastite snage","Na druge muzikalne osobe"],"question":"Na koga se oslanja musliman?"},{"answer":"Muhammed, Alejhis-Selam je naš uzor","options":["Muhammed, Alejhis-Selam je naš uzor","Sunce koje sijaje noću","Električno svjetlo kod kuće","Zvijezde na nebu"],"question":"Šta je svjetlo u našim srcima?"},{"answer":"Samo Allah","options":["Samo Allah","Samo njegovo bogatstvo","Samo njegov grad","Samo njegove igračke"],"question":"Što se nalazi samo u srcu muslimana?"},{"answer":"Jer nam je uzor u ponašanju","options":["Jer nam je uzor u ponašanju","Jer osvjetljava našu kuću","Jer je bio veoma bogat","Jer je bio vrlo jak i snažan"],"question":"Kako je Muhammed, Alejhis-Selam, svjetlo za nas?"}]},{"nivo":1,"slug":"prednost-desne-strane","naslov":"Prednost desne strane","content_html":"<div class=\"lesson-container\">\n        <h1>PREDNOST DESNE STRANE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/desna_strana.jpg\">\n        </div>","audio_src":"desna_strana.mp3","redoslijed":18,"is_published":true,"kviz_pitanja":[{"answer":"Desna strana","options":["Lijeva strana","Desna strana","Obje strane jednako","Ni jedna strana"],"question":"Koja strana ima prednost u islamu?"},{"answer":"Desnom rukom","options":["Lijevom rukom","Desnom rukom","Obema rukama","Oboje je dozvoljeno"],"question":"Kojom rukom trebamo jesti prema islamu?"},{"answer":"Desnu cipelu","options":["Lijevu cipelu","Desnu cipelu","Obje istovremeno","Nije važno"],"question":"Koju cipelu prvo obuvamo?"},{"answer":"Profeta Muhammed, alejhis-selam","options":["Profeta Muhammed, alejhis-selam","Aiša, radijallahu anha","Njegovi drugovi","Njegovi sinovi"],"question":"Ko je dao primjer prednosti desne strane?"},{"answer":"Desni rukav","options":["Lijevi rukav","Desni rukav","Nije važno","Oboje istovremeno"],"question":"Koji rukav prvo oblačimo kada se odijevamo?"}]},{"nivo":1,"slug":"dinski-sarti","naslov":"Dinski šarti","content_html":"<div class=\"lesson-container\">\n        <h1>TRIDESET TRI ŠARTA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dinski_sarti.jpg\">\n        </div>","audio_src":"dinski_sarti.mp3","redoslijed":19,"is_published":true,"kviz_pitanja":[{"answer":"Trideset i tri","options":["Dvadeset i tri","Trideset i tri","Četrdeset i tri","Petnaest"],"question":"Koliko dinskih šartova ima ukupno?"},{"answer":"Šest","options":["Pet","Šest","Četiri","Tri"],"question":"Koliko imanskih šartova moramo ispuniti?"},{"answer":"Amin","options":["Namaz","Ramazanski post","Amin","Zekat"],"question":"Koji od ovih nije islamski šart?"},{"answer":"Tri puta","options":["Dva puta","Pet puta","Tri puta","Jednom"],"question":"Koliko puta treba oprati lice tijekom abdesta?"},{"answer":"Šest dijelova","options":["Pet dijelova","Sedam dijelova","Šest dijelova","Osam dijelova"],"question":"Koliko sastavnih dijelova ima namaz?"}]},{"nivo":1,"slug":"imanski-sarti","naslov":"Imanski šarti","content_html":"<div class=\"lesson-container\">\n        <h1>Imanski šarti</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/imanski_sarti.jpg\">\n        </div>","audio_src":"imanski_sarti.mp3","redoslijed":20,"is_published":true,"kviz_pitanja":[{"answer":"Šest","options":["Tri","Četiri","Pet","Šest"],"question":"Koliko ima imanskih šarta?"},{"answer":"Vjerovanje u Allaha","options":["Vjerovanje u Allahove meleke","Vjerovanje u Allaha","Vjerovanje u Allahove knjige","Vjerovanje u sudnji dan"],"question":"Koji je prvi imanski šart?"},{"answer":"Vjerovanje u Allahove poslanike","options":["Vjerovanje u Allahove knjige","Vjerovanje u Allahove poslanike","Vjerovanje u Allahove meleke","Vjerovanje u sudnji dan"],"question":"Šta je četvrti imanski šart?"},{"answer":"Da vjerujem da se sve dogaða Allahovom voljom","options":["Da vjerujem u sve knjige","Da vjerujem da se sve dogaða Allahovom voljom","Da vjerujem samo u dobre stvari","Da vjerujem u sve melek"],"question":"Šta znači šesti imanski šart?"},{"answer":"Tri zadatka","options":["Dva zadatka","Tri zadatka","Četiri zadatka","Pet zadataka"],"question":"Koliko glavnih zadataka imamo za imanskog šarte?"}]},{"nivo":1,"slug":"sura-el-ihlas","naslov":"Sura El-Ihlas","content_html":"<div class=\"lesson-container\">\n        <h1>SURA EL-IHLAS</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sura_el_ihlas.jpg\">\n        </div>","audio_src":"ihlas.mp3","redoslijed":21,"is_published":true,"kviz_pitanja":[{"answer":"Vrijedi kao trećina Kur'ana","options":["Jednaka je cijelom Kur'anu","Vrijedi kao trećina Kur'ana","Vrijedi kao četvrtina Kur'ana","Vrijedi kao polovica Kur'ana"],"question":"Koliko dijelova Kur'ana vrijedi Sura El-Ihlas?"},{"answer":"Iskrenost","options":["Veličanstvo","Iskrenost","Čistoća","Moć"],"question":"Šta znači naziv Sura El-Ihlas?"},{"answer":"O Allahovom jedinstvu i jednosti","options":["O molitvi i postu","O Allahovom jedinstvu i jednosti","O običajima muslimana","O životinjama i biljkama"],"question":"O čemu govori Sura El-Ihlas?"},{"answer":"Ujutro i navečer","options":["Samo u džamiji","Ujutro i navečer","Samo tokom Ramazana","Samo na Bajram"],"question":"Kada se Sura El-Ihlas posebice uči i čita?"},{"answer":"Četiri ajeta","options":["Tri ajeta","Pet ajeta","Četiri ajeta","Dva ajeta"],"question":"Koliko ajeta ima Sura El-Ihlas?"}]},{"nivo":1,"slug":"islamski-sarti-1","naslov":"Islamski šarti","content_html":"<div class=\"lesson-container\">\n        <h1>Islamski šarti</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/islamski_sarti.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Islamski šarti – pet stubova islama</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o značaju glavnih islamskih dužnosti</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pet islamskih šarta po redoslijedu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti pamćenja i nabrajanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, zamislite veliku zgradu na pet stubova. Ako bilo koji stub fali, zgrada se ruši. Tako je i sa našom vjerom – ima pet stubova, koje danas učimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Islamski šarti su glavne islamske dužnosti koje treba izvršavati svaki punoljetni musliman i muslimanka.</p><p>Ima ih pet: <strong>1) kelimei-šehadet, 2) namaz, 3) post, 4) zekat, 5) hadž.</strong></p><p>Prva tri šarta odnose se na svakog muslimana, a zekat i hadž samo na one koji to mogu i imaju mogućnosti.</p><p>Postupak: Pišem šarte na tabli po redoslijedu. Učenici ih ponavljaju zajedno više puta. Pojedinačno provjeravam ko ih zna nabrojati.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam: Koliko ima islamskih šarta? Koji je prvi? Koji drugi? Učenici nabrajaju, a ja pohvaljujem.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O PET STUBOVA ISLAMA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                <div class=\"lesson-text\">\n                    <p>Zamislite jednu veliku i lijepu zgradu koja stoji na pet čvrstih stubova. Bez tih stubova, zgrada ne bi mogla stajati i srušila bi se. Muallima Fatima nas uči da je upravo tako sagrađen i islam.</p>\n\n                    <p>Tih pet stubova nazivamo <strong>islamski šarti</strong>. Oni su najvažnija pravila koja muslimani i muslimanke trebaju znati i praktikovati u svom životu. Prvi od njih je Kelime-i šehadet, kojim potvrđujemo svoju vjeru u Allaha i Njegovog poslanika Muhammeda, alejhis-selam Zatim dolaze namaz, post, zekat i hadž.</p>\n\n                    <p>Dok se prva tri šarta odnose na svakog odraslog muslimana, zekat i hadž su obaveza za one koji su bogati i mogu to sebi priuštiti. Hajde da ih naučimo nabrojati redom kako bismo znali na kojim stubovima stoji naša vjera!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO ISLAMSKE ŠARTE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">ISLAMSKI ŠARTI SU GLAVNE ISLAMSKE DUŽNOSTI KOJE JE OBAVEZAN IZVRŠAVATI SVAKI PUNOLJETAN MUSLIMAN I MUSLIMANKA. IMA IH PET:</p>\n\n                <div class=\"sarti-table\">\n                    <div class=\"sart-row\">\n                        <div class=\"sart-num\">1</div>\n                        <div class=\"sart-arabic\">KELIMEI-ŠEHADET</div>\n                        <div class=\"sart-bosnian\">VJERU IZJAVITI</div>\n                    </div>\n                    <div class=\"sart-row\">\n                        <div class=\"sart-num\">2</div>\n                        <div class=\"sart-arabic\">NAMAZ</div>\n                        <div class=\"sart-bosnian\">NAMAZ KLANJATI</div>\n                    </div>\n                    <div class=\"sart-row\">\n                        <div class=\"sart-num\">3</div>\n                        <div class=\"sart-arabic\">POST</div>\n                        <div class=\"sart-bosnian\">POSTITI MJESEC RAMAZAN</div>\n                    </div>\n                    <div class=\"sart-row\">\n                        <div class=\"sart-num\">4</div>\n                        <div class=\"sart-arabic\">ZEKAT</div>\n                        <div class=\"sart-bosnian\">DIO IMETKA DAVATI</div>\n                    </div>\n                    <div class=\"sart-row\">\n                        <div class=\"sart-num\">5</div>\n                        <div class=\"sart-arabic\">HADŽ</div>\n                        <div class=\"sart-bosnian\">HADŽ OBAVITI</div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">ODGOVORI NA PITANJA:</p>\n                <ol class=\"lesson-text\" style=\"padding-left: 30px; margin-bottom: 20px;\">\n                    <li>ŠTA SU ISLAMSKI ŠARTI?</li>\n                    <li>KOLIKO IMA I KOJE SU GLAVNE ISLAMSKE DUŽNOSTI?</li>\n                    <li>KO NAM JE NAREDIO OVE DUŽNOSTI?</li>\n                    <li>KOJI JE UVJET DA BI NEKO BIO MUSLIMAN?</li>\n                    <li>ŠTA ISKAZUJEMO IZVRŠAVANJEM GLAVNIH ISLAMSKIH DUŽNOSTI?</li>\n                </ol>\n                \n                <p class=\"lesson-text\" style=\"font-weight: bold;\">ZADATAK:</p>\n                <ul class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>NAUČI NAPAMET ISLAMSKE ŠARTE I NJIHOVO ZNAČENJE.</li>\n                    <li>KROZ IGROKAZ SA DRUGOVIMA UVJEŽBAJ IZGOVARANJE ISLAMSKIH ŠARTA PO REDU.</li>\n                </ul>\n            </div>\n        </div>","audio_src":null,"redoslijed":22,"is_published":true,"kviz_pitanja":[{"answer":"Pet","options":["Pet","Tri","Sedam","Deset"],"question":"Koliko ima islamskih šarta?"},{"answer":"Glavne islamske dužnosti","options":["Glavne islamske dužnosti","Imena Allahova","Vrste namaza","Mjeseci u godini"],"question":"Šta su islamski šarti?"},{"answer":"Kelimei šehadet","options":["Kelimei šehadet","Namaz","Post","Hadž"],"question":"Koji je prvi islamski šart?"},{"answer":"Namaz","options":["Namaz","Post","Zekat","Hadž"],"question":"Koji je drugi islamski šart?"},{"answer":"Zekat i hadž","options":["Zekat i hadž","Kelimei šehadet i namaz","Namaz i post","Post i zekat"],"question":"Koji su islamski šarti obavezni samo za one koji to mogu?"}]},{"nivo":1,"slug":"namaz-1","naslov":"Namaz","content_html":"<div class=\"lesson-container\">\n        <h1>NAMAZ JE NAŠA ZAHVALNOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/namaz_djeca.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Namaz – stub vjere</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema namazu i navike njegovog obavljanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta je namaz i zašto ga klanjamo</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike redovnog klanjanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako se zahvaljujemo nekome ko nam je učinio dobro? Allah nam svaki dan daje toliko blagodati – kako Mu mi to vraćamo? Najljepši način je – namazom.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Namaz je drugi islamski šart i stub vjere.</p><p>Klanjajući namaz, mi se zahvaljujemo Allahu na svemu što nam daje: zdravlju, hrani, roditeljima, životu.</p><p>Poslanik, a.s., je rekao: \"Namaz je radost mog oka.\"</p><p>Namaz nas čini smirenim, sretnim i boljim ljudima jer kroz njega razgovaramo sa Allahom.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Razgovaramo o tome ko od učenika već klanja kod kuće sa roditeljima. Pohvaljujem one koji to čine i podstičem druge da pokušaju.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O NAJLJEPŠEM \"HVALA\" <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                <div class=\"lesson-text\">\n                    <p>Zamislite da vam najbolji prijatelj ili neko od rodbine donese prelijep poklon – vašu omiljenu čokoladu! Šta je prva stvar koju ćete uraditi? Naravno, reći ćete jedno iskreno i glasno: \"Hvala!\" Naši roditelji nas od malih nogu uče da je lijepo i važno zahvaliti se onome ko nam učini neko dobro.</p>\n\n                    <p>A sada, razmislite o svim darovima koje nam Allah, dž.š., daje svakoga dana. Dao nam je vid da gledamo boje svijeta, sluh da čujemo ptice, zdravlje, hranu koju jedemo i porodicu koja nas voli. Ti darovi su mnogo veći od bilo koje čokolade na svijetu!</p>\n\n                    <p>Upravo tu dolazi <strong>namaz</strong>. Namaz je naš poseban način da kažemo \"Hvala\" Allahu na svemu što nam daruje. Kada stanemo na sedždžadu, mi se obraćamo našem Gospodaru i pokazujemo da cijenimo sve blagodati koje imamo. To je razgovor ispunjen ljubavlju i zahvalnošću.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> ŠTA NAMAZ ZNAČI ZA MUSLIMANA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">NAMAZ JE DRUGI ISLAMSKI ŠART. ON JE STUB VJERE I NAJLJEPŠA VEZA IZMEĐU ALLAHA I NJEGOVOG ROBA.</p>\n                \n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"font-weight: bold; text-align: center;\">ZAPAMTI!</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">KROZ NAMAZ MI SE ZAHVALJUJEMO ALLAHU NA ZDRAVLJU, HRANI, RODITELJIMA I SVIM DRUGIM DAROVIMA KOJE NAM SVAKODNEVNO DAJE.</p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">KLANJANJE NAMAZA NAS ČINI SMIRANIM, SRETNIM I BOLJIM LJUDIMA. POSLANIK, A.S., JE REKAO DA JE NAMAZ \"RADOST NJEGOVOG OKA\".</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> MOJI ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 30px; font-weight: bold;\">\n                    <li>RAZMISLI I NABROJ PET STVARI NA KOJIMA SI DANAS ZAHVALAN ALLAHU.</li>\n                    <li>VJEŽBAJ STAJANJE U NAMAZU SA SVOJIM RODITELJIMA.</li>\n                    <li>NAUČI DA JE NAMAZ NAJLJEPŠI NAČIN DA KAŽEMO \"HVALA ALLAHU\".</li>\n                </ul>\n            </div>\n        </div>","audio_src":null,"redoslijed":23,"is_published":true,"kviz_pitanja":[{"answer":"Drugi","options":["Drugi","Prvi","Treći","Peti"],"question":"Koji je po redu islamski šart namaz?"},{"answer":"Naša zahvalnost Allahu","options":["Naša zahvalnost Allahu","Vrsta posta","Islamski praznik","Dio Kur'ana"],"question":"Šta je namaz prema lekciji?"},{"answer":"Da je radost njegovog oka","options":["Da je radost njegovog oka","Da je najteža dužnost","Da je samo za odrasle","Da se klanja samo petkom"],"question":"Šta je Poslanik a.s. rekao za namaz?"},{"answer":"Da se zahvalimo Allahu na blagodatima","options":["Da se zahvalimo Allahu na blagodatima","Da pokažemo drugima","Da bismo postali bogati","Samo iz navike"],"question":"Zašto klanjamo namaz?"},{"answer":"Stub vjere","options":["Stub vjere","Knjiga vjere","Mjesto vjere","Oblik posta"],"question":"Šta je namaz za vjeru?"}]},{"nivo":1,"slug":"namaski-sarti","naslov":"Namaski šarti","content_html":"<div class=\"lesson-container\">\n        <h1>NAMASKI ŠARTI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/namaski_sarti.jpg\">\n        </div>","audio_src":"namaski_sarti_story.mp3","redoslijed":24,"is_published":true,"kviz_pitanja":[{"answer":"Dvanaest šarta","options":["Šest šarta","Devet šarta","Dvanaest šarta","Petnaest šarta"],"question":"Koliko ukupno ima namaskih šarta?"},{"answer":"Čisto tijelo, abdest, propisna odjeća","options":["Čisto tijelo, abdest, propisna odjeća","Nijet, tekbir, stajanje","Kiraet, ruku', sedžda","Vremenske osnove, kibla, sjedenje"],"question":"Koja su prva tri namaska uvjeta prije klanjanja namaza?"},{"answer":"Okrenuti se prema Kibli","options":["Okrenuti se prema Kibli","Učiniti nijet za namaz","Stajati u namazu","Učiti Kur'an"],"question":"Šta moramo učiniti prije klanjanja namaza prema Kibli?"},{"answer":"Šest ruknova","options":["Tri runkova","Šest ruknova","Osam ruknova","Deset ruknova"],"question":"Koliko ima namaskih ruknova ili sastavnih dijelova namaza?"},{"answer":"Početni tekbir","options":["Početni tekbir","Pregibanje u namazu","Spuštanje lica na tlo","Učenje Kur'ana"],"question":"Šta se prvo radi u namaznim ruknovnom dijelovima?"}]},{"nivo":1,"slug":"prvi-namaski-sart","naslov":"Prvi namaski šart (Čistoća)","content_html":"<div class=\"lesson-container\">\n        <h1>PRVI NAMASKI ŠART</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/cistoca.jpg\">\n        </div>","audio_src":"prvi_namaski_sart_story.mp3","redoslijed":25,"is_published":true,"kviz_pitanja":[{"answer":"Čistoća tijela, odjeće i mjesta","options":["Čistoća tijela, odjeće i mjesta","Lijepa odjeća i украсни predmeti","Glasno čitanje Kurana prije namaza","Dugačka brada i duge kose"],"question":"Šta je prvi šart – uvjet za namaz?"},{"answer":"Čistoća je pola imana","options":["Čistoća je cijeli iman","Čistoća je pola imana","Čistoća je samo za žene","Čistoća nije važna za namaz"],"question":"Što je rekao Muhammed, alejhis-selam, o čistoći?"},{"answer":"Ličnom higijenom, pranjem ruku i zuba, abdesnom","options":["Samo pranjem ruku","Samo kupanjem","Ličnom higijenom, pranjem ruku i zuba, abdesnom","Samo četkanjem zuba"],"question":"Kako održavamo čistoću tijela?"},{"answer":"Od alkohola, krvi, mokraće i pljuvačke psa","options":["Od boja i šara","Od sunčeve svjetlosti","Od alkohola, krvi, mokraće i pljuvačke psa","Od vode i kiše"],"question":"Od čega čuvamo odjeću za klanjanje?"},{"answer":"Sedžadu ili serždadu – namjensku prostirku","options":["Slike živih bića","Sedžadu ili serždadu – namjensku prostirku","Šarene zastave","Svijeće i lampe"],"question":"Šta stavljamo na mjesto gdje klanjamo namaz?"}]},{"nivo":1,"slug":"abdest","naslov":"Drugi namaski šart - abdest","content_html":"<div class=\"lesson-container\">\n        <h1>DRUGI NAMASKI ŠART: ABDEST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/abdest1.jpg\">\n        </div>","audio_src":"abdest_story.mp3","redoslijed":26,"is_published":true,"kviz_pitanja":[{"answer":"Vjersko pranje dijelova tijela prije namaza","options":["Vjersko pranje dijelova tijela prije namaza","Islamska hrana","Vrsta molitve","Islamski odjevni predmet"],"question":"Šta je abdest?"},{"answer":"Tri puta","options":["Dva puta","Tri puta","Četiri puta","Pet puta"],"question":"Koliko puta operemo ruke na početku abdesta?"},{"answer":"Najmanje četvrtina glave","options":["Cijela glava","Najmanje četvrtina glave","Samo čelo","Samo tjeme"],"question":"Koji dio glave se tare tijekom abdesta?"},{"answer":"Do lakta i članaka","options":["Do šaka i prstiju","Do lakta i članaka","Do ramena i koljena","Do pazuha i bedara"],"question":"Do gdje operemo ruke i noge u abdestu?"},{"answer":"Izdati niyjet","options":["Izdati niyjet","Isprati lice","Operati ruke","Isperati usta"],"question":"Šta trebamo prvo učiniti prije uzimanja abdesta?"}]},{"nivo":1,"slug":"abdeski-sarti","naslov":"Abdeski šarti","content_html":"<div class=\"lesson-container\">\n        <h1>ABDESKI ŠARTI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/abdeski_sarti.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Abdeski šarti – farzovi abdesta</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pažnje i odgovornosti pri uzimanju abdesta</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti četiri farza (šarta) abdesta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti pravilnog uzimanja abdesta</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko od vas zna uzeti abdest? Šta od abdesta je obavezno – tj. mora se uraditi da bi abdest bio ispravan? Hajde danas naučiti abdeske šarte.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Abdeski šarti (farzovi) su dijelovi abdesta bez kojih abdest nije ispravan. Ima ih četiri:</p><p><strong>1.</strong> oprati cijelo lice,</p><p><strong>2.</strong> oprati ruke do iznad laktova,</p><p><strong>3.</strong> potrati (mesh) jednu četvrtinu glave,</p><p><strong>4.</strong> oprati noge do iznad članaka.</p><p>Postupak: Pišem šarte na tabli po redu. Demonstriram svaki pokret. Učenici ih ponavljaju i pokazuju mjesta na sebi. Naglašavam da ako neki od farza propustimo, abdest nije ispravan.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Provjeravam ko je naučio sva četiri šarta. Učenici redom nabrajaju. Najavljujem vježbu uzimanja abdesta na sljedećem času.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O NAJVAŽNIJIM DIJELOVIMA ABDESTA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO ČETIRI ABDESKA FARZA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"margin-bottom: 15px;\">ČETIRI OBAVEZNE RADNJE PRI UZIMANJU ABDESTA ZOVU SE ABDESKI ŠARTI ILI FARZI. BEZ NJIHOVOG IZVRŠAVANJA ABDEST NIJE ISPRAVAN.</p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"margin-bottom: 5px;\">1. UMITI LICE JEDANPUT</p>\n                    <p class=\"lesson-text\" style=\"margin-bottom: 5px;\">2. OPRATI DESNU I LIJEVU RUKU DO IZNAD LAKATA PO JEDANPUT</p>\n                    <p class=\"lesson-text\" style=\"margin-bottom: 5px;\">3. POTRATI MOKROM RUKOM NAJMANJE ČETVRTINU GLAVE – MESH</p>\n                    <p class=\"lesson-text\">4. OPRATI DESNU I LIJEVU NOGU DO IZNAD ČLANAKA PO JEDANPUT</p>\n                </div>\n\n                <div class=\"arabic-card\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 10px;\">REKAO JE UZVIŠENI ALLAH: “O VJERNICI, KADA HOĆETE DA NAMAZ OBAVITE, LICA SVOJA I RUKE SVOJE DO IZA LAKATA OPERITE – A DIO GLAVA SVOJIH POTRITE – I NOGE SVOJE DO IZA ČLANAKA...”</p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">(KUR’AN, EL-MA’IDE, 6)</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaci', this)\"> ODGOVORI NA PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaci\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>ŠTA SU ABDESKI ŠARTI?</li>\n                    <li>KOLIKO IMA ABDESKIH ŠARTA?</li>\n                    <li>KOJI SU ABDESKI ŠARTI?</li>\n                </ol>\n            </div>\n        </div>","audio_src":"abdesni_sarti_story.mp3","redoslijed":27,"is_published":true,"kviz_pitanja":[{"answer":"Četiri obavezne radnje pri uzimanju abdesta","options":["Četiri obavezne radnje pri uzimanju abdesta","Opcione radnje koje se rade ako želimo","Radnje koje radimo nakon namaznog vremena","Posebne molitve koje čitamo prije abdesta"],"question":"Šta su abdeski šarti?"},{"answer":"Četiri šarta","options":["Pet šarta","Tri šarta","Četiri šarta","Šest šarta"],"question":"Koliko ima obaveznih abdeskih šarta?"},{"answer":"Umiti lice jedanput","options":["Umiti ruke do lakata","Umiti lice jedanput","Potrati glavu","Umiti noge do članaka"],"question":"Koja je prva obavezna radnja pri uzimanju abdesta?"},{"answer":"Do lakata","options":["Do zapešća","Do lakata","Do prstiju","Do ramena"],"question":"Do kuda moramo oprati ruke pri abdestenju?"},{"answer":"Potiranje mokrom rukom najmanje četvrtine glave","options":["Pranje lica vodom","Potiranje mokrom rukom najmanje četvrtine glave","Pranje nogu do članaka","Pranje ruku do lakata"],"question":"Koju radnju zovemo 'mesh' u abdestenju?"}]},{"nivo":1,"slug":"sta-kvari-abdest","naslov":"Šta kvari abdest","content_html":"<div class=\"lesson-container\">\n        <h1>ŠTA KVARI ABDEST?</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sta_kvari_abdest.jpg\">\n        </div>","audio_src":"sta_kvari_abdest_story.mp3","redoslijed":28,"is_published":true,"kviz_pitanja":[{"answer":"Spavanje ili gubitak svijesti","options":["Razgovor sa drugim ljudima","Spavanje ili gubitak svijesti","Smijanje bez zvuka","Dodirivanje nečega prljavo"],"question":"Šta od navedenog kvari abdest?"},{"answer":"Više namaza ako nam se ne dogodi ništa što kvari abdest","options":["Samo jedan namaz","Samo dva namaza","Više namaza ako nam se ne dogodi ništa što kvari abdest","Tri namaza maksimalno"],"question":"Koliko namaza možemo klanjati sa jednim abdestom?"},{"answer":"Da, povraćanje kvari abdest","options":["Ne, nikada ne kvari abdest","Da, povraćanje kvari abdest","Samo ako je glasno","Samo ako se dogodi tijekom namaza"],"question":"Da li povraćanje iz želuca kvari abdest?"},{"answer":"Razgovor sa drugima","options":["Bilo koja prirodna nužda","Razgovor sa drugima","Oticanje krvi iz tijela","Gubitak svijesti"],"question":"Šta od navedenog NEĆE pokvariti abdest?"},{"answer":"Nema potrebe ako smo sigurni da smo ga imali","options":["Odmah se abdestimo ponovo","Nema potrebe ako smo sigurni da smo ga imali","Čekamo sat vremena","Odustajemo od namaza"],"question":"Ako sumnjamo da smo izgubili abdest, šta radimo?"}]},{"nivo":1,"slug":"sura-en-nas","naslov":"Sura En-Nas","content_html":"<div class=\"lesson-container\">\n        <h1>SURA EN-NAS</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sura_en_nas.jpg\">\n        </div>","audio_src":"sura_en_nas_story.mp3","redoslijed":29,"is_published":true,"kviz_pitanja":[{"answer":"Sura En-Nās","options":["Sura En-Nās","Sura Al-Fatiha","Sura Jāsin","Sura Al-Ihlās"],"question":"Kako se zove zadnja sura u Kur'anu koju učimo?"},{"answer":"Od zla šejtana i njegovih zamisli","options":["Od bogatstva i novca","Od zla šejtana i njegovih zamisli","Od svih životinja","Od vode i kiše"],"question":"Od čega se prema suri En-Nās trebamo zaštititi?"},{"answer":"Muhammed, alejhis-selam","options":["Poznati učenjak","Muhammed, alejhis-selam","Ebu Bekr","Bilal ibn Rabah"],"question":"Ko je rekao da se nikada ne možemo bolje zaštititi nego sa dvije sure?"},{"answer":"U srcima ljudi","options":["U očima","U nohama","U srcima ljudi","U rukama"],"question":"Gdje šejtan unosi loše misli prema suri En-Nās?"},{"answer":"Od džina i od ljudi","options":["Od učitelja","Od biljaka","Od džina i od ljudi","Od životinja"],"question":"Od koga osim šejtana trebamo da se zaštitimo prema suri?"}]},{"nivo":1,"slug":"treci-namaski-sart","naslov":"Treći namaski šart (Odijevanje)","content_html":"<div class=\"lesson-container\">\n        <h1>TREĆI NAMASKI ŠART</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/odjeca.jpg\">\n        </div>","audio_src":"treci_namaski_sart_story.mp3","redoslijed":30,"is_published":true,"kviz_pitanja":[{"answer":"Lijepo se obuciti","options":["Lijepo se obuciti","Obavezno nos masku","Stani brže na nogu","Zatvori oči"],"question":"Šta Allah kaže da trebamo uraditi kada hoćemo da molitvu obavimo?"},{"answer":"Cijelo tijelo osim lica, šaka i stopala","options":["Cijelo tijelo osim lica, šaka i stopala","Samo glavu i vrat","Samo noge","Samo ruke"],"question":"Koje dijelove tijela ženske osobe trebaju pokriti u namazu?"},{"answer":"Čista, uredna i komotna","options":["Čista, uredna i komotna","Kratka i tijesna","Prozirna i lijepa","Nečista i raspala"],"question":"Koje karakteristike TREBALA bi imati odjeća u namazu?"},{"answer":"Od pojasa do ispod koljena","options":["Od pojasa do ispod koljena","Samo leđa","Samo stomak","Samo vrat"],"question":"Koje dijelove tijela muškarci najmanje trebaju pokriti pri nedostatku odjeće?"},{"answer":"Kratku, tijesnu i prozirnu","options":["Kratku, tijesnu i prozirnu","Čistu i urednu","Komfortnu i mekanu","Boju i dekorativnu"],"question":"Koju vrstu odjeće NIKADA ne trebamo nositi u namazu?"}]},{"nivo":1,"slug":"cetvrti-namaski-sart","naslov":"Četvrti namaski šart (Vrijeme)","content_html":"<div class=\"lesson-container\">\n        <h1>ČETVRTI NAMASKI ŠART</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/namaska_vremena.jpg\">\n        </div>","audio_src":"cetvrti_namaski_sart_story.mp3","redoslijed":31,"is_published":true,"kviz_pitanja":[{"answer":"Pet puta","options":["Tri puta","Pet puta","Četiri puta","Šest puta"],"question":"Koliko ima namaskih vremena tijekom dana?"},{"answer":"Sabah-namaz","options":["Podne-namaz","Sabah-namaz","Ikindija-namaz","Jacija-namaz"],"question":"Kako se zove jutarnji namaz?"},{"answer":"Mujezin","options":["Učitelj","Mujezin","Imam","Roditelj"],"question":"Ko oglašava početak namaskog vremena?"},{"answer":"Kada Sunce izlazi i na sredini neba","options":["Ujutro","Kada Sunce izlazi i na sredini neba","Nakon západa Sunca","Noću"],"question":"Kada se namaz ne smije klanjati?"},{"answer":"Jacija-namaz","options":["Akšam-namaz","Podne-namaz","Jacija-namaz","Sabah-namaz"],"question":"Koji je noćni namaz?"}]},{"nivo":1,"slug":"ezan","naslov":"Ezan","content_html":"<div class=\"lesson-container\">\n        <h1>EZAN</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ezan_munara.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ezan – poziv na namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema ezanu i džamiji</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti riječi ezana i njihovo značenje</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike pažljivog slušanja ezana</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta čujemo pet puta dnevno sa munare? Ko ga uči? Šta nam taj poziv govori? Hajde danas naučiti riječi ezana.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ezan je poziv kojim se muslimani pozivaju na namaz. Uči ga muezzin sa munare.</p><p>Riječi ezana glase: <em>Allahu ekber (4×), Ešhedu en lā ilāhe illallāh (2×), Ešhedu enne Muhammeden resūlullāh (2×), Hajje ‘ales-salāh (2×), Hajje ‘alel-felāh (2×), Allahu ekber (2×), Lā ilāhe illallāh.</em></p><p>U sabahskom ezanu, poslije \"Hajje ‘alel-felāh\", dodaje se: <em>Es-salātu hajrun mine-n-nevm</em> (Namaz je bolji od sna).</p><p>Postupak: Pišem ezan na tabli sa transkripcijom i prijevodom. Puštam snimak ezana. Učenici slušaju i ponavljaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Razgovor: Šta osjećamo kada čujemo ezan? Kako se ponašamo dok ezan uči? Pohvaljujem one koji su zapamtili dijelove.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O POZIVU KOJI SPAJA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Ezan je oglašavanje početka namaskog vremena i poziv na zajedničko klanjanje namaza. Ezan uči mujezin. Kada on započne učenje ezana, prekidamo svaki govor i posao i pratimo učenje ponavljajući riječi ezana u sebi.</p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 20px; margin-bottom: 20px;\">\n                    <p class=\"lesson-text\" style=\"margin-bottom: 10px;\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Ezan glasi:</span></p>\n                    <p class=\"lesson-text\">ALLÃHU EKBER (4 puta)</p>\n                    <p class=\"lesson-text\">EŠHEDU EN LÃ ILÃHE ILLALLÃH (2 puta)</p>\n                    <p class=\"lesson-text\">EŠHEDU ENNE MUHAMMEDEN RESŪLULLÃH (2 puta)</p>\n                    <p class=\"lesson-text\">HAJJE 'ALES-SALÃH (2 puta)</p>\n                    <p class=\"lesson-text\">HAJJE 'ALEL-FELÃH (2 puta)</p>\n                    <p class=\"lesson-text\">ALLÃHU EKBER (2 puta)</p>\n                    <p class=\"lesson-text\">LÃ ILÃHE ILLALLÃH (1 put)</p>\n                </div>\n\n                <div class=\"lesson-text\" style=\"margin-bottom: 20px;\">\n                    <p>Kod sabahskog ezana poslije riječi HAJJE 'ALEL-FELÃH dodajemo 2 x riječi: <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">EṢ-ṢALATU HAYRUN MINEN-NEVM</span> – Namaz je bolji od spavanja.</p>\n                </div>\n\n                <table style=\"width: 100%; border-collapse: collapse; margin-bottom: 20px; font-size: 1.4rem;\">\n                    <tr>\n                        <th colspan=\"2\" style=\"background-color: #2e7d32; color: white; padding: 10px; border: 1px solid #ddd; text-align: center;\">Značenje riječi ezana:</th>\n                    </tr>\n                    <tr>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Allahu Ekber!</td>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Allah je najveći!</td>\n                    </tr>\n                    <tr>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Ešhedu en la ilahe illallah!</td>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Svjedočim da je samo Allah Bog!</td>\n                    </tr>\n                    <tr>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Ešhedu enne Muhammeden Resulullah!</td>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Svjedočim da je Muhammed Allahov poslanik!</td>\n                    </tr>\n                    <tr>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Hajje 'ales-salah!</td>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Dođi na namaz!</td>\n                    </tr>\n                    <tr>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Hajje 'alel-felah!</td>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Dođi na spas!</td>\n                    </tr>\n                    <tr>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">La ilahe illallah!</td>\n                        <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">Samo je Allah Bog.</td>\n                    </tr>\n                </table>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">ZADATAK</span></p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">Svojim lijepim glasom prouči ezan! Poslije ezana prouči dovu ili Fatihu!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>Šta je ezan?</li>\n                    <li>Ko uči ezan?</li>\n                    <li>Kako se ponašamo kada uči ezan?</li>\n                    <li>Kako glasi ezan?</li>\n                    <li>Šta dodajemo kod sabahskog ezana?</li>\n                    <li>Šta znače riječi ezana?</li>\n                </ol>\n            </div>\n        </div>","audio_src":"ezan_story.mp3","redoslijed":32,"is_published":true,"kviz_pitanja":[{"answer":"Oglašavanje početka namaskog vremena i poziv na namaz","options":["Oglašavanje početka namaskog vremena i poziv na namaz","Molitva koju čitamo u kući","Pjesma koju pjevamo na svečanostima","Priča o životima Allahovim poslanicima"],"question":"Šta je ezan?"},{"answer":"Mujezin","options":["Mujezin","Imam","Učitelj","Roditelj"],"question":"Ko uči ezan?"},{"answer":"Prekidamo govor i posao te pratimo ezan","options":["Nastaviti sa svim aktivnostima","Prekidamo govor i posao te pratimo ezan","Otići kući što prije","Čekati da se ezan završi pa tek onda stati"],"question":"Šta trebamo uraditi kada mujezin započne ezan?"},{"answer":"4 puta","options":["1 put","2 puta","3 puta","4 puta"],"question":"Koliko puta se kaže 'Allahu Ekber' na početku ezana?"},{"answer":"Riječi 'Eṣ-ṣalatu hayrun minen-nevim'","options":["Allahu Ekber više puta","Imena svih poslanika","Riječi 'Eṣ-ṣalatu hayrun minen-nevim'","Posebnu dovu za zdravlje"],"question":"Šta se dodaje posebno u sabahskom ezanu?"}]},{"nivo":1,"slug":"ikamet","naslov":"Ikamet","content_html":"<div class=\"lesson-container\">\n        <h1>IKAMET</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ikamet.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ikamet – poziv pred početak namaza</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pažnje i ozbiljnosti pred početak namaza</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti razliku između ezana i ikameta i riječi ikameta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti pravilnog izgovora arapskih riječi</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, znamo da nas ezan poziva na namaz. A kako se zove poziv kojim počinjemo sam namaz u džematu? To je ikamet, koji danas učimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ikamet se uči neposredno pred početak farz-namaza, kad se klanja u džematu.</p><p>Riječi ikameta su slične ezanu, samo se uči brže i tiše, te se dodaje: <em>Kad kāmeti-s-salāh (2×)</em> – Eto, namaz je počeo.</p><p>Razlika ezan/ikamet: ezan poziva ljude izdaleka, a ikamet je znak da klanjači stanu u sufove i počnu namaz.</p><p>Postupak: Pišem riječi ikameta na tabli. Puštam snimak. Učenici uče zajedno. Ispravljam izgovor.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Provjeravam: Šta je ezan, a šta ikamet? Kada se uči ikamet? Učenici odgovaraju, a ja pohvaljujem.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> ŠTA MISLITE, KAKO ZNAMO DA NAMAZ UPRAVO POČINJE? <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Ikamet uče muškarci prije klanjanja farz-namaza. Kada namaz klanjamo u džematu, ikamet uči samo mujezin. Ikamet učimo malo brže nego ezan.</p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 20px; margin-bottom: 20px;\">\n                    <p class=\"lesson-text\" style=\"margin-bottom: 10px;\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Ikamet glasi:</span></p>\n                    <p class=\"lesson-text\">ALLÃHU EKBER (4 puta)</p>\n                    <p class=\"lesson-text\">EŠHEDU EN LÃ ILÃHE ILLALLÃH (2 puta)</p>\n                    <p class=\"lesson-text\">EŠHEDU ENNE MUHAMMEDEN RESŪLULLÃH (2 puta)</p>\n                    <p class=\"lesson-text\">HAJJE 'ALES-SALÃH (2 puta)</p>\n                    <p class=\"lesson-text\">HAJJE 'ALEL-FELÃH (2 puta)</p>\n                    <p class=\"lesson-text\">KAD KÃMETIṢ-ṢALÃH (2 puta)</p>\n                    <p class=\"lesson-text\">ALLÃHU EKBER (2 puta)</p>\n                    <p class=\"lesson-text\">LÃ ILÃHE ILLALLÃH (1 put)</p>\n                </div>\n\n                <div class=\"lesson-text\" style=\"margin-bottom: 20px;\">\n                    <p>Za razliku od ezana, ikametu dodajemo: <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">KAD KÃMETIṢ-ṢALÃH</span> – Namaz već počinje.</p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">ZADATAK</span></p>\n                    <p class=\"lesson-text\" style=\"text-align: center;\">Svi dječaci će proučiti ikamet a djevojčice će davati ocjene! Pobjednik će za nagradu proučiti ikamet u džamiji!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>Ko i kada uči ikamet?</li>\n                    <li>Ko uči ikamet kada namaz klanjamo u džematu?</li>\n                    <li>Kako glasi ikamet?</li>\n                    <li>Kakva je razlika između ezana i ikameta?</li>\n                </ol>\n            </div>\n        </div>","audio_src":"ikamet_story.mp3","redoslijed":33,"is_published":true,"kviz_pitanja":[{"answer":"Samo muškarci","options":["Samo žene","Samo muškarci","Samo djeca","Svi vjernici"],"question":"Ko uči ikamet prije klanjanja farz-namaza?"},{"answer":"Mujezin","options":["Imam","Mujezin","Svi vjernici","Nastavnik"],"question":"Ko uči ikamet kada namaz klanjamo u džematu?"},{"answer":"4 puta","options":["2 puta","3 puta","4 puta","5 puta"],"question":"Koliko puta se govori 'Allahu Ekber' na početku ikameta?"},{"answer":"Kad kametiş-salah","options":["Hajje ales-salah","Kad kametiş-salah","Eşhedu en la ilahe","Allahu ekber"],"question":"Što se dodaje ikametu što nema u ezanu?"},{"answer":"Brže od ezana","options":["Sporije od ezana","Brže od ezana","Isto kao ezan","Tri puta brže"],"question":"Da li se ikamet učи brže ili sporije od ezana?"}]},{"nivo":1,"slug":"dova-poslije-ezana","naslov":"Dova poslije ezana","content_html":"<div class=\"lesson-container\">\n        <h1>DOVA POSLIJE EZANA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dova_poslije_ezana.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dova poslije ezana</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kiraet</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Poslaniku, a.s., i navike učenja dova</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti dovu koja se uči odmah poslije ezana</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti pamćenja kratkih dova</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta uradimo nakon što čujemo ezan? Da li samo idemo dalje, ili kažemo nešto posebno? Danas učimo dovu koja se uči poslije ezana.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kada čujemo ezan, lijepo je tiho ponavljati riječi za muezzinom, a nakon završenog ezana proučiti dovu.</p><p>Dova glasi: <em>Allahumme Rabbe hāzihi-d-da‘veti-t-tāmmeh, ve-s-salāti-l-kā’imeh, āti Muhammeden el-vesīlete vel-fadīleh, veb‘ashu mekāmen mahmūden ellezī ve‘adteh.</em></p><p>Značenje: Allahu, Gospodaru ovog savršenog poziva i namaza koji se uspostavlja, podari Muhammedu počasno mjesto i odlikovanje, te ga proživi na hvaljenom položaju koji si mu obećao.</p><p>Postupak: Pišem dovu na tabli, s transkripcijom i prijevodom. Učimo je polako, dio po dio. Učenici ponavljaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče dovu napamet, dio po dio. Dogovaramo se da je svaki put kad čujemo ezan učimo.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> KAKO ISKORISTITI POSEBAN TRENUTAK? <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                \n                <div class=\"lesson-text\">\n                    <p>Jedne noći Poslanikov ashab – drug Abdullah sanjao je čovjeka u zelenoj odjeći kako nosi zvono. Abdullah htjede kupiti od njega to zvono da njime oglašava namasko vrijeme i poziva na namaz u džamiju ali mu ovaj ponudi da ga pouči nečem ljepšem pa mu prouči ezan.</p>\n                    <p>Sutradan je Abdullah obavijestio Muhammeda, alejhis-selam, o svom snu. Poslanik mu reče da je njegov san istinit i da ode do Bilala koji ima lijep glas i nauči ga riječima ezana. Tako je Bilal proučio prvi ezan.</p>\n                    <p>Uzvišeni Allah daje posebnu milost kada mujezin uči ezan. Cijela priroda čuje i razumije to učenje. I mi prestajemo sa svim aktivnostima, pripremamo se za namaz i ponavljamo za mujezinom riječi ezana. A kada prouči: “Hajje 'ales-salah” i “Hajje 'alel-felah” mi izgovaramo: “La havle ve la kuvvete illa billahil-'alijjil-'azim.”</p>\n                </div>\n\n                <div style=\"background-color: #e8f5e9; padding: 20px; border-radius: 10px; margin: 20px 0; border: 1px solid #c8e6c9;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 15px;\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Na munari</span></p>\n                    <p class=\"lesson-text\" style=\"text-align: center; font-style: italic;\">\n                        Kad mujezin ezan poče,<br>\n                        odjeknuše sa svih strana<br>\n                        topli glasi mujezina,<br>\n                        s raznih strana i munara.<br><br>\n                        Drhti Mirza kao ptiče,<br>\n                        ustreptalo svo mu biće,<br>\n                        Bož'je ime svud se čuje,<br>\n                        Allahu ekber – odjekuje.<br><br>\n                        Sutradan su na pouci,<br>\n                        kazivali drugoj djeci,<br>\n                        na munari kad su bili,<br>\n                        kol'ko su se uzbudili.\n                    </p>\n                    <p class=\"lesson-text\" style=\"text-align: right; font-size: 1rem;\">R.Kadić</p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"text-align: center; margin-top: 30px;\">Kada mujezin završi učenje ezana proučimo dovu:</p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 10px; margin-bottom: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; color: #2e7d32; font-size: 1.6rem;\">\n                        ALLÃHUMME RABBE HAZIHID-DA'VETIT-TÃMMETI VEṢ-ṢALÃTIL-KÃ'IMETI ÃTI MUHAMMEDENIL-VESĪLETE VEL-FADĪLETE VED-DEREDŽETER-REFĪ'ATE VEB'ASHU MEKÃMEN MAHMŪDENILLEZĪ VE'ADTEH, INNEKE LÃ TUHLIFUL-MĪ'ÃD.\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">Moj Allahu, Gospodaru ovog savršenog poziva i nastupajućeg namaza, podari Muhammedu poseban stepen u Džennetu i svako dobro i proživi ga na pohvalnom mjestu koje Si mu obećao. Ti, zaista, nećeš iznevjeriti obećanje!</p>\n            </div>\n        </div>\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>Kada je lijepo proučiti ovu dovu?</li>\n                    <li>O čemu govori dova poslije ezana?</li>\n                    <li>Šta molimo Allaha da podari Muhammedu, alejhis-selam?</li>\n                    <li>Šta je lijepo proučiti na samom kraju?</li>\n                </ol>\n            </div>\n        </div>","audio_src":"dova_poslije_ezana_story.mp3","redoslijed":34,"is_published":true,"kviz_pitanja":[{"answer":"Bilal","options":["Bilal","Abdullah","Mirza","Muhammed"],"question":"Tko je prvi naučio ezan na osnovu Abdullahova sna?"},{"answer":"Allah mu daje posebnu milost","options":["Nove odjeće","Novca","Allah mu daje posebnu milost","Hvale od ljudi"],"question":"Šta se javlja mujezinu kao posebna milost kada uči ezan?"},{"answer":"Hajje 'ales-salah i Hajje 'alel-felah","options":["Subhanallah i Alhamdulillah","Hajje 'ales-salah i Hajje 'alel-felah","Allahu ekber samo","La ilaha illallah"],"question":"Koje dvije fraze ponavljamo za mujezinom tokom ezana?"},{"answer":"Dova navedena u lekciji","options":["Tekbir","Dova navedena u lekciji","Samo ćutanje","Drugi ezan"],"question":"Šta se kaže nakon što mujezin završi ezan?"},{"answer":"Nije rekao svoje ime","options":["Nije rekao svoje ime","Bilal","Muhammed","Abdullah"],"question":"Kako se zvao čovjek u zelenoj odjeći iz Abdullahova sna?"}]},{"nivo":1,"slug":"peti-namaski-sart","naslov":"Peti namaski šart (Kibla)","content_html":"<div class=\"lesson-container\">\n        <h1>PETI NAMASKI ŠART</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/kibla.jpg\">\n        </div>","audio_src":"peti_namaski_sart_story.mp3","redoslijed":35,"is_published":true,"kviz_pitanja":[{"answer":"Smjer gdje se nalazi Kaba u Mekki","options":["Smjer gdje se nalazi Kaba u Mekki","Naziv za sveti hram u Jerusalimu","Crni kamen ugrađen u Kabu","Obilazak oko svetog mjesta"],"question":"Šta je Kibla?"},{"answer":"U gradu Mekki na Arabijskom poluotoku","options":["U gradu Mekki na Arabijskom poluotoku","U gradu Medini u Arabiji","U Jerusalimu u Palestini","U gradu Kairu u Egiptu"],"question":"Gdje se nalazi Kaba?"},{"answer":"Oblik kocke sa ravnim krovom","options":["Oblik kocke sa ravnim krovom","Okrugli oblik sa kupolom","Oblik piramide sa vrhom","Pravougaoni oblik sa kosim krovom"],"question":"Kakav je oblik Kabe?"},{"answer":"Crni kamen ugrađen u jedan ugao Kabe","options":["Crni kamen ugrađen u jedan ugao Kabe","Prostor oko Kabe gdje se obavljaju namazi","Prekrivač na kojem su kur'anski ajeti","Naziv za obilazak oko Kabe"],"question":"Šta je Hadžerul-esved?"},{"answer":"Istraživati i okrenuti se prema gdje mislimo","options":["Istraživati i okrenuti se prema gdje mislimo","Klanjati prema fotografiji osobe","Ignorisati Kiblu i klanjati se gdje želimo","Čekati da nas neko drugi usmjeri"],"question":"Šta trebamo učiniti ako ne znamo smjer Kible?"}]},{"nivo":1,"slug":"odredjivanje-kible","naslov":"Orijentacija i određivanje kible","content_html":"<div class=\"lesson-container\">\n        <h1>ORIJENTACIJA U PRIRODI I ODREĐIVANJE KIBLE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/orijentacija.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Orijentacija i određivanje kible</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o povezanosti svih muslimana kroz Kabu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je kibla i kako je odrediti</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje praktične sposobnosti orijentacije u prostoru</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kad muslimani klanjaju, svi se okreću u istom pravcu. Šta mislite, prema čemu? Hajde danas da naučimo kako se taj pravac određuje.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kibla je pravac prema Kabi u Mekki, prema kojem se okrećemo u namazu.</p><p>U našim krajevima (Bosna i Hercegovina) kibla je u pravcu jugoistoka.</p><p>Kibla se može odrediti na više načina: pomoću Sunca (zalazak je na zapadu), kompasa, mobilnih aplikacija ili praćenjem kible u džamijama.</p><p>Postupak: Pokazujem na karti gdje je Mekka. Pomoću kompasa pokazujem pravac kible u učionici. Učenici se okreću prema kibli.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam: Šta je kibla? U kojem pravcu je iz naših krajeva? Kako je možemo odrediti? Učenici odgovaraju.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> KAKO PRONAĆI PRAVI PUT U PRIRODI? <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                \n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">Postoji mnogo načina kako da odredimo smjer Kible, kao npr.:</p>\n\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Kompas ili GPS uređaj</span></p>\n                <p class=\"lesson-text\">Osim kompasa ili kibletname, mnoge aplikacije na mobilnim telefonima omogućuju prikaz tačnog vremena namaza i smjer Kible.</p>\n\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Kibla-sat</span></p>\n                <p class=\"lesson-text\">Kibla-sat je vrijeme kada je pravac sjenke nekog promatranog predmeta nasuprot pravcu Kible. To znači da, ako se nalazimo u nekom mjestu gdje nam nije poznat smjer Kible, toga dana u vrijeme navedeno u koloni Takvima ‘Kibla-sat’ pogledamo sjenu nekog predmeta. Pravac prema Kibli je nasuprot sjene posmatranog predmeta.</p>\n\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; margin-top: 20px; margin-bottom: 20px; border: 1px solid #f9f1a5;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 15px;\">Orijentacija po pojavama u prirodi</p>\n                    <div style=\"display: flex; justify-content: space-around; flex-wrap: wrap;\">\n                        <div style=\"width: 48%;\">\n                            <p class=\"lesson-text\">- Krošnje drveća su na južnoj strani bujnije nego na sjevernoj.</p>\n                            <p class=\"lesson-text\">- Na sjevernoj strani kora drveta je hrapavija i prekrivena mahovinom.</p>\n                        </div>\n                        <div style=\"width: 48%;\">\n                            <p class=\"lesson-text\">- Godovi na panju posječenog stabla su uži na sjevernoj, a širi na južnoj strani.</p>\n                            <p class=\"lesson-text\">- Mravinjak je na južnoj strani panja, kamena ili grma.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> ZADACI I PONAVLJANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <div class=\"arabic-card\" style=\"margin-bottom: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 10px;\">ZADATAK</p>\n                    <p class=\"lesson-text\">1. Objasni načine na koje možemo odrediti smjer Kible!</p>\n                    <p class=\"lesson-text\">2. Instalirajte mobilnu aplikaciju koja pokazuje smjer Kible!</p>\n                    <p class=\"lesson-text\">3. Ispred mekteba odredite Kiblu pomoću Kibla-sata!</p>\n                    <p class=\"lesson-text\">4. Na mektebskom izletu odredite Kiblu pomoću mahovine!</p>\n                </div>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 20px; margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">PITANJA ZA RAZGOVOR:</span>\n                </p>\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>Na koji način kompas pomaže u određivanju Kible?</li>\n                    <li>Kako pomoću obične sjene predmeta možemo pronaći pravac namaza?</li>\n                    <li>Ako se izgubimo u šumi, koji nam prirodni znakovi govore gdje je jug?</li>\n                </ol>\n            </div>\n        </div>","audio_src":"orijentacija_story.mp3","redoslijed":36,"is_published":true,"kviz_pitanja":[{"answer":"Kompas i GPS uređaj","options":["Kompas i GPS uređaj","Satnica i razglednica","Karta i dalekozor","Kompjuter i mobilni telefon"],"question":"Koja su dva glavna tehnološka sredstva za određivanje smjera Kible?"},{"answer":"Vrijeme kada je sjena nasuprot pravcu Kible","options":["Vrijeme kada je sjena nasuprot pravcu Kible","Sat koji pokazuje vrijeme molitve","Elektronski uređaj za mjerenje vremena","Sat koji se koristi samo za Džumu"],"question":"Šta je Kibla-sat?"},{"answer":"Na sjevernoj strani kore","options":["Na sjevernoj strani kore","Na južnoj strani kore","Na vrhu krošnje","Na korijenima stabla"],"question":"Na kojem dijelu drveća je mahovina?"},{"answer":"Na južnoj strani panja, kamena ili grma","options":["Na južnoj strani panja, kamena ili grma","Na sjevernoj strani panja","Na istočnoj strani grma","Na zapadnoj strani kamena"],"question":"Gdje se nalazi mravinjak u odnosu na svjetske strane?"},{"answer":"Bujnija je na južnoj, a slabija na sjevernoj","options":["Bujnija je na južnoj, a slabija na sjevernoj","Bujnija je na sjevernoj, a slabija na južnoj","Jednako bujne na obje strane","Nema razlike između strana"],"question":"Kako izgleda krošnja drveća na južnoj i sjevernoj strani?"}]},{"nivo":1,"slug":"sesti-namaski-sart","naslov":"Šesti namaski šart (Nijet)","content_html":"<div class=\"lesson-container\">\n        <h1>ŠESTI NAMASKI ŠART</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/nijjet.jpg\">\n        </div>","audio_src":"sesti_namaski_sart_story.mp3","redoslijed":37,"is_published":true,"kviz_pitanja":[{"answer":"Nijet - učiniti odluku klanjati namaz","options":["Nijet - učiniti odluku klanjati namaz","Čistoća tijela prije namaza","Znanje sve sure iz Kur'ana","Nošenje особе duge odjeće"],"question":"Koji je šesti šart – uvjet za namaz?"},{"answer":"Svjesna odluka zašto i zbog čega nešto činimo","options":["Bolna osjećanja u srcu","Svjesna odluka zašto i zbog čega nešto činimo","Poseban obred prije jela","Boja dresa za muškarce"],"question":"Što je nijet prema lekciji?"},{"answer":"U srcu kao odluka","options":["Na papiru pisano","U glavi razmišljanjem","U srcu kao odluka","Na usnama glasno"],"question":"Gdje se donosi nijet prije namaza?"},{"answer":"Izgovaranjem riječi nijeta","options":["Eating dobru hranu prije namaza","Izgovaranjem riječi nijeta","Čitanjem novinama","Sjeđenjem tiho"],"question":"Kako možemo ojačati nijet?"},{"answer":"Dela se cijene prema namerema","options":["Djela se cijene prema novcu","Dela se cijene prema namerema","Djela moraju biti teška","Nije bitno šta radimo"],"question":"Šta je rekao Muhammed, alejhis-selam, o djelima?"}]},{"nivo":1,"slug":"namaski-ruknovi-1","naslov":"Namaski ruknovi (I dio)","content_html":"<div class=\"lesson-container\">\n        <h1>NAMASKI RUKNOVI (I DIO)</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ruknovi1.jpg\">\n        </div>","audio_src":"namaski_ruknovi_story.mp3","redoslijed":38,"is_published":true,"kviz_pitanja":[{"answer":"Šest ruknova","options":["Tri ruknova","Šest ruknova","Osam ruknova","Deset ruknova"],"question":"Koliko ima namaskih ruknova koje trebamo izvršiti u namazu?"},{"answer":"Podižu ruke u visinu ušiju","options":["Drže ruke na grudima","Podižu ruke u visinu ušiju","Spuštaju ruke niže","Stavljaju ruke iza leđa"],"question":"Što dječaci rade sa rukama pri Iftitahi-tekbiru?"},{"answer":"Na grudima","options":["Na pojasu","Na grudima","Iza leđa","Uz boke"],"question":"Gdje djevojčice državaju ruke tijekom Kijama-stajanja?"},{"answer":"Subhaneke, Euzubillu, Bismillu, Fatihu i suru","options":["Samo Fatihu i jednu suru","Samo Euzubillu","Subhaneke, Euzubillu, Bismillu, Fatihu i suru","Samo Bismillu"],"question":"Šta učimo na prvom stajanju tijekom Kiraeta?"},{"answer":"Namaz nije ispravan i trebamo ga obnoviti","options":["Namaz je ispravan","Namaz nije ispravan i trebamo ga obnoviti","Treba obaviti dodatnu sedždu","Ništa se ne dešava"],"question":"Što se dešava ako ne izvršimo sve namaske ruknove?"}]},{"nivo":1,"slug":"namaski-ruknovi-2","naslov":"Namaski ruknovi (II dio)","content_html":"<div class=\"lesson-container\">\n        <h1>NAMASKI RUKNOVI (II DIO)</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ruknovi2.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Namaski ruknovi (II dio)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pažnje i ozbiljnosti pri obavljanju namaza</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti preostale namaske ruknove</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti pravilnog obavljanja namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, prošlog časa smo počeli učiti namaske ruknove – stvari koje se obavezno čine u namazu. Ko se sjeća prvih? Danas učimo i preostale.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Namaski ruknovi su radnje koje se obavezno čine u namazu. U II dijelu učimo:</p><p><strong>Sedžda</strong> – padanje na sedždu sa sedam dijelova tijela (čelo s nosom, dvije šake, dva koljena, prsti obje noge).</p><p><strong>Ka’da</strong> (sjedenje) – sjedenje na kraju namaza pri učenju Et-tehijatu.</p><p><strong>Predaja selama</strong> – završetak namaza okretanjem glave desno i lijevo uz riječi <em>Es-selamu alejkum ve rahmetullāh.</em></p><p>Postupak: Pokazujem svaki rukn praktično. Učenici ponavljaju. Naglašavam da bez ovih ruknova namaz nije potpun.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju sve namaske ruknove (I i II dio). Provjeravam praktičnim pokazivanjem.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('osvrt', this)\"> NAŠ PUT KROZ NAMASKE RUKNOVE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"osvrt\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Esselamu ‘alejkum, dragi moji đaci! Do sada smo naučili da je namaz sastavljen od posebnih radnji koje nazivamo ruknovi. U prošloj lekciji smo detaljno objasnili prva tri: početni tekbir kojim ulazimo u namaz, kijam ili mirno stajanje, te kiraet – učenje Kur'ana.</p>\n                    <p>Danas nastavljamo našu obuku i naučit ćemo preostala tri rukna koji upotpunjavaju naš namaz. Vidjet ćemo kako se pravilno pregibamo, kako spuštamo lice na tlo iskazujući poštovanje Allahu, dželle šanuhu, i kako završavamo naš namaz mirnim sjedenjem. Budite pažljivi, jer svaki ovaj pokret ima svoj propis i ljepotu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">4. RUKU' – PREGIBANJE U NAMAZU</span>\n                </p>\n                <p class=\"lesson-text\">Rukū' je pregibanje u namazu. Savijemo se do polovine tijela tako da nam leđa budu ravna. Obuhvatimo koljena rukama, dječaci rastavljenih a djevojčice sastavljenih prstiju. Na rukū'u gledamo u nožne prste i tri puta učimo: SUBḤĀNE RABBIJEL-'AẒĪM – Slavljen je moj Gospodar Veličanstveni!</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">5. SEDŽDA – SPUŠTANJE LICA NA TLO</span>\n                </p>\n                <p class=\"lesson-text\">Sedždu obavljamo tako što prvo na tlo spuštamo koljena, zatim dlanove ruku, pa na kraju čelo i nos. Ruke su za širinu lica razmaknute. Dok smo na sedždi, prsti stopala su savijeni i ne odvajaju se od tla, pete su spojene. U dječaka su laktovi ruku podignuti od tla, a u djevojčica skoro spušteni na tlo. Na sedždi gledamo niz lice i tri puta učimo: SUBḤĀNE RABBIJEL-E'ALĀ – Slavljen je moj Gospodar Uzvišeni!</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">6. KADEI-EHIRE – SJEDENJE NA KRAJU NAMAZA</span>\n                </p>\n                <p class=\"lesson-text\">Kadei-ehire je posljednje sjedenje na kraju namaza. Namazi od dva rekata imaju jedno sjedenje a namazi od tri ili četiri rekata imaju dva sjedenja. Na sjedenju gledamo u ruke koje držimo na koljenima do vrha koljena. Dječaci sjednu na lijevu nogu, a stopalo desne noge drže uspravno, povijenih prstiju okrenutih prema Kibli. Djevojčice iskrenu obje noge na desnu stranu. Na zadnjem sjedenju svih namaza učimo: ET-TEHIJATU, SALAVATE I DOVE.</p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">Na sjedenju, kada učimo Et-Tehijatu prilikom izgovaranja prvog dijela Kelimei-šehadeta (LA ILAHE) savijemo prste desne ruke a kažiprst ispružimo, a kada izgovorimo (ILLALLAH) kažiprst spustimo.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('objasnjenja', this)\"> PRAVILNO IZVRŠAVANJE I ČESTE GREŠKE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"objasnjenja\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">RUKU'</span></p>\n                <p class=\"lesson-text\">Kada završimo sa učenjem na stajanju, izgovaramo tekbir Allahu ekber i pregibamo se. Dječaci stavljaju dlanove na koljena sa raširenim prstima, a djevojčice sa sastavljenim. Leđa moraju biti ravna, a pogled usmjeren u nožne prste.</p>\n                <div style=\"background-color: #ffebee; padding: 10px; border-radius: 10px; margin-bottom: 20px;\">\n                    <p class=\"lesson-text\">Greške na ruku'u: Gledati naprijed ili u mjesto sedžde; samo se malo nakloniti ili previše spustiti glavu tako da leđa nisu ravna; prekratko se zadržati.</p>\n                </div>\n\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">SEDŽDA</span></p>\n                <p class=\"lesson-text\">Spuštanje koljena, dlanova, čela i nosa na tlo zovemo sedžda. Svaki rekat ima dvije identične sedžde. Dlanovi se rašire toliko da između njih možemo spustiti lice. Pete su spojene, a prsti stopala na tlu okrenuti naprijed.</p>\n                <div style=\"background-color: #ffebee; padding: 10px; border-radius: 10px; margin-bottom: 20px;\">\n                    <p class=\"lesson-text\">Greške na sedždi: Spuštati prvo dlanove pa koljena; žmiriti; dječaci spuštaju laktove ili djevojčice dižu laktove s poda; podizati nos s poda; ne napraviti pauzu između dvije sedžde.</p>\n                </div>\n\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">KADEI-EHIRE</span></p>\n                <p class=\"lesson-text\">Zadnji dio namaza je sjedenje. Gledamo u ruke na natkoljenicama. Dječaci sjede na lijevoj nozi s povijenim prstima desne noge, a djevojčice bez povijanja prstiju.</p>\n                <div style=\"background-color: #ffebee; padding: 10px; border-radius: 10px;\">\n                    <p class=\"lesson-text\">Greške na sjedenju: Brzo i nepravilno učenje; stavljanje ruku u krilo umjesto na natkoljenice.</p>\n                </div>\n                \n                <div class=\"arabic-card\" style=\"margin-top: 25px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">ZAPAMTI!</p>\n                    <p class=\"lesson-text\">Namaskih ruknova ima šest. Prvi i zadnji (početni tekbir i zadnje sjedenje) su vezani za namaz u cjelini, a ostala četiri čine svaki rekat. Ako izostavimo neki rukn, namaz neće biti ispravan.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> ODGOVORI NA PITANJA! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ol class=\"lesson-text\" style=\"padding-left: 30px;\">\n                    <li>Šta su namaski ruknovi?</li>\n                    <li>Kada namaz nije ispravan?</li>\n                    <li>Nabroji namaske ruknove?</li>\n                    <li>Opiši namaske ruknove?</li>\n                    <li>Šta čini jedan rekat?</li>\n                    <li>Koliko rekata može imati namaz?</li>\n                </ol>\n            </div>\n        </div>","audio_src":null,"redoslijed":39,"is_published":true,"kviz_pitanja":[{"answer":"Dječaci rastavljenih prstiju, djevojčice sastavljenih","options":["Dječaci rastavljenih prstiju, djevojčice sastavljenih","Svi sa rastavljenim prstima","Svi sa sastavljenim prstima","Bez doticanja rukama"],"question":"Kako se rukama drže koljena tijekom rukū'a?"},{"answer":"Koljena, dlanovi, čelo i nos","options":["Koljena, dlanovi, čelo i nos","Čelo, nos, koljena, dlanovi","Dlanovi, koljena, čelo, nos","Nos, čelo, dlanovi, koljena"],"question":"Koji je redoslijed spuštanja u sedždi?"},{"answer":"Dva sjedenja","options":["Dva sjedenja","Jedno sjedenje","Tri sjedenja","Četiri sjedenja"],"question":"Koliko sjedenja ima namaz od tri rekata?"},{"answer":"Lijeva noga pregibljena, desna uspravna","options":["Lijeva noga pregibljena, desna uspravna","Obje noge na desnu stranu","Obje noge na lijevu stranu","Obje noge pregibljene"],"question":"Kako dječaci stave noge tijekom sjedenja?"},{"answer":"Tri puta","options":["Tri puta","Dva puta","Četiri puta","Pet puta"],"question":"Koliko puta učimo zikr tijekom rukū'a?"}]},{"nivo":1,"slug":"ulazak-izlazak","naslov":"Ponašanje pri ulasku i izlasku","content_html":"<div class=\"lesson-container\">\n        <h1>PONAŠANJE PRI ULASKU I IZLASKU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ulazak_izlazak.jpg\">\n        </div>","audio_src":null,"redoslijed":40,"is_published":true,"kviz_pitanja":[{"answer":"Desnom nogom","options":["Lijevom nogom","Desnom nogom","Obje noge odjednom","Bilo kojom nogom"],"question":"Koje noge ulazimo u džamiju i kuću?"},{"answer":"Desnom nogom","options":["Lijevom nogom","Desnom nogom","Obje noge istovremeno","Bilo kojom nogom"],"question":"Koje noge izlazimo iz kupatila?"},{"answer":"Lijeva noga","options":["Desna noga","Lijeva noga","Obje noge zajedno","Nije bitno koja noga"],"question":"Koja noga ide prva pri ulazu u kupatilo?"},{"answer":"Obavezno dobiti dozvolu","options":["Obavezno dobiti dozvolu","Samo postucati vrata","Direktno ući bez dozvole","Čekati 5 minuta"],"question":"Šta obavezno trebamo uraditi prije ulaska u tuđu kuću?"},{"answer":"Nazvati selam onima koji su unutra","options":["Nazvati selam onima koji su unutra","Odmah sjesti","Ići direktno u sobu","Presvući se"],"question":"Šta trebamo uraditi pri ulasku u tuđu kuću?"}]},{"nivo":1,"slug":"sura-el-felek","naslov":"Sura El-Felek","content_html":"<div class=\"lesson-container\">\n        <h1>SURA EL-FELEK</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sura_felek.jpg\">\n        </div>","audio_src":"sura_felek_story.mp3","redoslijed":41,"is_published":true,"kviz_pitanja":[{"answer":"Svitanje","options":["Svitanje","Noć","Zaštita","Šejtan"],"question":"Šta znači riječ 'El-Felek' u prevodu?"},{"answer":"Od zla koje Allah stvara","options":["Od bogatstva","Od zla koje Allah stvara","Od kišе","Od učenja"],"question":"Od čega tražimo zaštitu u suri El-Felek?"},{"answer":"Zaštitnice","options":["Velike sure","Zaštitnice","Duge sure","Kratke sure"],"question":"Kako se nazivaju sura El-Felek i sura En-Nas zajedno?"},{"answer":"Tri puta","options":["Jednom","Dva puta","Tri puta","Pet puta"],"question":"Koliko puta dnevno je preporučeno učiti zaštitnice?"},{"answer":"Kad omrkneš i kada osvaneš","options":["Samo ujutru","Kad omrkneš i kada osvaneš","Samo uveče","Samo tokom dana"],"question":"Kada Muhammed, alejhis-selam, preporučuje učenje zaštitnica?"}]},{"nivo":1,"slug":"gusulski-sarti","naslov":"Gusulski šarti","content_html":"<div class=\"lesson-container\">\n        <h1>GUSULSKI ŠARTI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/gusul.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Gusulski šarti – farzovi gusula</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike čistoće tijela</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je gusul i tri njegova farza</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje znanja za pravilno obavljanje gusula</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ponekad nije dovoljno samo uzeti abdest – treba se okupati na poseban način. To kupanje zovemo gusul. Šta je obavezno pri gusulu? Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Gusul je obavezno kupanje cijelog tijela u određenim prilikama (npr. nakon sna iz kojeg se sanja…, prije Bajram-namaza poželjno).</p><p>Gusulski šarti (farzovi) su tri:</p><p><strong>1.</strong> isprati usta vodom,</p><p><strong>2.</strong> isprati nos vodom,</p><p><strong>3.</strong> oprati cijelo tijelo, tako da nigdje ne ostane suho mjesto.</p><p>Postupak: Pišem šarte na tabli. Razgovaram o važnosti čistoće u islamu. Naglašavam da Poslanik, a.s., kaže: \"Čistoća je pola vjere.\"</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju tri gusulska šarta. Pitanje: Koja Poslanikova izreka govori o čistoći? Pohvaljujem.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> ŠTA JE TO GUSUL? <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Esselamu ‘alejkum dragi učenici!</p>\n                <p class=\"lesson-text\">Nedavno smo spomenuli da u mektebu najviše učimo o 33 dini-islamska šarta. Neke smo već naučili, a danas radimo sljedeću grupu šartova. Ima ih svega tri i zato će ovo biti kratka lekcija. Posebno zbog toga što ćemo o gusulu učiti mnogo više kada budete stariji.</p>\n                <p class=\"lesson-text\">Riječ gusul znači kupanje. Kada je u pitanju gusul, onda trebamo znati da se farzovi gusula ili gusulski šarti moraju ispuniti kako bi gusul u vjerskom smislu bio ispravan.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">Osim preporučenog redovnog kupanja i uzimanja abdesta, u određenim slučajevima za namaz je obavezno i kupanje koje se naziva gusul. Gusul je obavezno vjersko kupanje koje je propisano punoljetnim muslimanima i muslimankama kada su nečisti – džunub.</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px; margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Gusulski šarti</span>\n                </p>\n                <p class=\"lesson-text\">Gusulski šarti su tri obavezne radnje koje trebamo izvršiti da bi gusul – obavezno kupanje, bilo ispravno i potpuno. Prije kupanja srcem zanijetimo i izgovorimo nijet:</p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">NEVEJTUL-GUSLE LIREF'IL-DŽENĀBETI VE LIREF'IL-HADEŠI TEKARRUBEN ILALLĀHI TE'ĀLĀ.</p>\n                    <p class=\"lesson-text\" style=\"text-align: center; font-size: 1.1rem; margin-top: 10px;\">– Odlučih se okupati radi odstranjivanja nečistoće da se približim Uzvišenom Allahu. Zatim izvršimo tri gusulska šarta:</p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">1. GARGARA – usta i grlo isprati tri puta.</p>\n                <p class=\"lesson-text\">2. ISTINŠAK – nos tri puta isprati.</p>\n                <p class=\"lesson-text\">3. GASLI VUDŽUD – cijelo tijelo oprati, da nigdje suho ne ostane.</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 30px; margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Sunneti gusula</span>\n                </p>\n                <p class=\"lesson-text\">\n                1. Proučiti Euzubillu, Bismillu i zanijetiti<br>\n                2. Oprati vidljive nečistoće sa tijela<br>\n                3. Saprati tijelo tri puta<br>\n                4. Početi sa pranjem glave pa oprati desnu a zatim lijevu stranu.\n                </p>\n\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                1. Šta je gusul?<br>\n                2. Šta su gusulski šarti?<br>\n                3. Šta uradimo prije kupanja?<br>\n                4. Koliko ima i koji su gusulski šarti?<br>\n                5. Koji su sunneti gusula?<br>\n                6. Šta je pokuđeno prilikom gusula?\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":42,"is_published":true,"kviz_pitanja":[{"answer":"Obavezno religijsko kupanje za nečiste vjernika","options":["Obavezno religijsko kupanje za nečiste vjernika","Redovno kupanje koje se čini svaki dan","Obavezno pranje ruku prije namaza","Kupanje samo po završetku mjeseca Ramazana"],"question":"Što je gusul?"},{"answer":"Tri šarta","options":["Pet šarti","Dva šarta","Tri šarta","Četiri šarta"],"question":"Koliko ima gusulskih šarti?"},{"answer":"Gargara - oprati usta i grlo tri puta","options":["Oprati cijelo tijelo","Gargara - oprati usta i grlo tri puta","Istinšak - oprati nos tri puta","Izgovoriti nijet"],"question":"Koja je prva obavezna radnja gusula?"},{"answer":"Nijet - odlučimo se okupati","options":["Bismilu-lah","Alhamdulillah","Nijet - odlučimo se okupati","Subhanallah"],"question":"Što izgovaramo prije početka gusula?"},{"answer":"Oprati cijelo tijelo, bez suhog mjesta","options":["Pranje noса tri puta","Oprati cijelo tijelo, bez suhog mjesta","Pranje ruku do lakta","Pranje lica i brade"],"question":"Što znači 'gasli vudžud' u gusulu?"}]},{"nivo":1,"slug":"tejemumski-sarti","naslov":"Tejemumski šarti","content_html":"<div class=\"lesson-container\">\n        <h1>TEJEMMUMSKI ŠARTI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/tejemmum.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Tejemumski šarti – zamjena za abdest i gusul</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o olakšicama u islamu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je tejemum i kada se uzima</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje znanja o postupanju u posebnim situacijama</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta će uraditi musliman koji nema vode, a vrijeme namaza je nastupilo? Allah je dao olakšicu – tejemum. Šta je to, danas učimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Tejemum je čišćenje suhom čistom zemljom (ili pijeskom) kao zamjena za abdest ili gusul kada nema vode ili je voda štetna za zdravlje.</p><p>Tejemumski šarti su:</p><p><strong>1.</strong> nijet (namjera) za tejemum,</p><p><strong>2.</strong> udariti dlanovima po čistoj zemlji i potrati lice,</p><p><strong>3.</strong> ponovo udariti dlanovima i potrati ruke do iznad laktova.</p><p>Postupak: Demonstriram tejemum praktično. Učenici ponavljaju pokrete. Naglašavam da se tejemum uzima samo kad nema vode ili je voda nedostupna/štetna.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam: Šta je tejemum? Kada se uzima? Učenici odgovaraju i pokazuju pokrete.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> PRIČA O TEJEMMUMU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Esselamu ‘alejkum dragi moji učenici!</p>\n                <p class=\"lesson-text\">Do sada smo učili šest grupa dini-islamskih šarta i ostala nam je posljednja grupa. To su tejemmumski šarti. Tejemmum je simbolično čišćenje suhom zemljom ili predmetom od zemlje u nedostatku vode.</p>\n                <p class=\"lesson-text\">To nam se može desiti, na primjer, ako odemo negdje u planine ili na izlet i nestane nam vode. Tada možemo uzeti tejemmum i obaviti namaz.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">Tejemum je doticanje zemlje ili zemljine tvari radi simboličnog čišćenja.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">Ovo čišćenje obavljamo u situacijama:</p>\n                <p class=\"lesson-text\">\n                    - kada želimo klanjati ili učiti Kur'an, a nemamo vode za abdest ili gusul<br>\n                    - kada imamo sasvim malo vode koja nam je potrebnija za piće i spremanje hrane<br>\n                    - kada vodu iz bilo kojeg razloga ne možemo upotrijebiti kao npr. zbog nečistoće vode, bolesti, velike hladnoće i sl.\n                </p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 25px; margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Tejemumski šarti</span>\n                </p>\n                <p class=\"lesson-text\">Tejemumski šarti su obavezne radnje koje trebamo izvršiti da bi tejemum bio ispravan i potpun. Tri tejemumska šarta obavljamo tako što:</p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 15px; margin-bottom: 15px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">1 Srcem zanijetimo i proučimo Euzubillu i Bismillu. Lijepo je i nijet izgovoriti:<br>\n                    NEVEJTUT-TEJEMMUME LI EDŽLIṢ-ṢALĀTI VE LIREF'IL-HADEŠI TEḰARRUBEN ILALLĀHI TE'ĀLĀ – Odlučih obaviti tejemum radi namaza, otklanjanja nečistoće i približavanja Uzvišenom Allahu.</p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    2 Dotaknemo dlanovima suhu zemlju – ili predmet od zemlje i jedanput potaremo lice.<br>\n                    3 Ponovo dotaknemo suhu zemlju – ili predmet od zemlje pa potaremo desnu i lijevu ruku do iznad lakata.\n                </p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 25px; border: 1px solid #ff0000; background-color: #fff;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; color: #ff0000;\">Tejemum će pokvariti sve što kvari abdest, kao i mogućnost da upotrijebimo vodu za abdest ili gusul.</p>\n                </div>\n\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Šta je tejemum?<br>\n                    2. Kada se obavlja tejemum?<br>\n                    3. Šta su tejemumski šarti?<br>\n                    4. Koliko ima i kako se obavljaju tejemumski šarti?<br>\n                    5. Šta će pokvariti tejemum?\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":43,"is_published":true,"kviz_pitanja":[{"answer":"Doticanje zemlje radi simboličnog čišćenja","options":["Doticanje zemlje radi simboličnog čišćenja","Pranje ruku vodom pet puta","Čitanje Kur'ana naglas","Stajanje prema Kabi"],"question":"Šta je tejemum?"},{"answer":"Kada nemamo vode za abdest ili gusul","options":["Kada nemamo vode za abdest ili gusul","Kada želimo jesti hranu","Kada je vrijeme za spavanje","Kada idemo u školu"],"question":"Kada obavljamo tejemum?"},{"answer":"Tri tejemumska šarta","options":["Tri tejemumska šarta","Pet tejemumskih šarti","Dva tejemumska šarta","Osam tejemumskih šarti"],"question":"Koliko tejemumskih šarti trebamo obaviti?"},{"answer":"Dotičemo землю i taremo lice","options":["Dotičemo землю i taremo lice","Taremo samo desnu ruku","Izgovaramo nijet naglas","Umivamo nogu"],"question":"Šta radimo u drugom tejemumskom šartu?"},{"answer":"Sve što kvari abdest i mogućnost upotrebe vode","options":["Sve što kvari abdest i mogućnost upotrebe vode","Samo jela hrana","Samo loše vrijeme","Samo razgovor sa drugima"],"question":"Šta će pokvariti obavljeni tejemum?"}]},{"nivo":1,"slug":"et-tehijatu","naslov":"Et-Tehijatu","content_html":"<div class=\"lesson-container\">\n        <h1>ET-TEHIJATU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/et_tehijatu.jpg\">\n        </div>","audio_src":null,"redoslijed":44,"is_published":true,"kviz_pitanja":[{"answer":"Iskazivanje zahvalnosti i pokornosti Allahu","options":["Iskazivanje zahvalnosti i pokornosti Allahu","Učenje o drugim vjerama","Priča o Muhammedi, alejhis-selam","Pesma koju pjevamo u džamiji"],"question":"Šta je Et-Tehijatu?"},{"answer":"Na svakom sjedenju u namazu","options":["Na početku namaza","Na svakom sjedenju u namazu","Na kraju namaza","Samo u petničnom namazu"],"question":"Kada učimo Et-Tehijatu u namazu?"},{"answer":"Allaha i vjerovjesnika Muhammeda","options":["Samo vjerovjesnika Muhammeda","Allaha i vjerovjesnika Muhammeda","Samo Allaha","Sve ljude na svijetu"],"question":"Koga se tiče Et-Tehijatu prema lekciji?"},{"answer":"Na Miradžu","options":["U Mekki","Na Miradžu","U Medini","U džamiji"],"question":"Gdje se dogodio razgovor Et-Tehijatu?"},{"answer":"Kroz iskreno obavljene namaze","options":["Kroz iskreno obavljene namaze","Kroz putovanja","Kroz novac i bogatstvo","Kroz samo čitanje Kurana"],"question":"Kako možemo biti bliski sa našim Gospodarom?"}]},{"nivo":1,"slug":"salavati","naslov":"Salavati","content_html":"<div class=\"lesson-container\">\n        <h1>SALAVATI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/salavati.jpg\">\n        </div>","audio_src":null,"redoslijed":45,"is_published":true,"kviz_pitanja":[{"answer":"Iskazi naše ljubavi prema poslaniku Muhammedu","options":["Iskazi naše ljubavi prema poslaniku Muhammedu","Posebne dnevne obaveze muslimana","Dijelovi Kur'ana koje čitamo","Vrste molitve u džamiji"],"question":"Šta su salavati?"},{"answer":"Na sjedenju nakon Et-Tehijata","options":["Na početku namaza","Na sjedenju nakon Et-Tehijata","Tijekom rikâta","Nakon završetka namaza"],"question":"Kada učimo salavate u namazu?"},{"answer":"Njegovu porodicu i Ibrahima sa njegovom porodicom","options":["Njegovu porodicu i Ibrahima sa njegovom porodicom","Samo njegove dragocene prijatelje","Sve vjerovesnike Allahovog zakona","Samo njegove najstarije sinove"],"question":"Koga spominjemo zajedno s Muhammekom u salatima?"},{"answer":"Allah i meleci ga blagosiljaju, vi blagosiljajte","options":["Samo žene trebaju da ga blagosiljaju","Allah i meleci ga blagosiljaju, vi blagosiljajte","Nema potrebe da ga blagosiljamo","Samo imami trebaju da ga blagosiljaju"],"question":"Što je rekao Uzvišeni Allah o blagosiljanju Vjerovjesnika?"},{"answer":"Dva dijela salavata","options":["Jedan dio salavata","Dva dijela salavata","Tri dijela salavata","Četiri dijela salavata"],"question":"Koliko dijelova salavata imamo u lekciji?"}]},{"nivo":1,"slug":"dove","naslov":"Dove","content_html":"<div class=\"lesson-container\">\n        <h1>DOVE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dove.jpg\">\n        </div>","audio_src":null,"redoslijed":46,"is_published":true,"kviz_pitanja":[{"answer":"Naše molbe Svemoćnom Allahu","options":["Naše molbe Svemoćnom Allahu","Dijelovi namaza gdje čitamo Kuran","Posebne pesme za praznike","Pravila islamske vjere"],"question":"Šta su dove?"},{"answer":"Na posljednjem sjedenju poslije salavata","options":["Na početku namaza","Na posljednjem sjedenju poslije salavata","Tijekom ruku'a","Između sura Kurana"],"question":"Gdje učimo dove u namazu?"},{"answer":"Za dobro na ovome i onom svijetu","options":["Samo za bogatstvo na ovome svijetu","Za dobro na ovome i onom svijetu","Samo za znanje i mudrost","Za brzi dolazak Sudnjega dana"],"question":"Za šta molimo Allaha u ovoj dovi?"},{"answer":"Od patnje u Džehennemu","options":["Od bolesti i boli","Od patnje u Džehennemu","Od neprijatelja","Od siromaštva"],"question":"Od čega nas molimo Allaha da spasi u dovi?"},{"answer":"U raznim prilikama tijekom dana","options":["Samo kada nam naredimo stariji","Samo u džamiji","U raznim prilikama tijekom dana","Samo prije spavanja"],"question":"Kada možemo učiti dovu osim u namazu?"}]},{"nivo":1,"slug":"pravila-ponasanja","naslov":"Islamska pravila ponašanja","content_html":"<div class=\"lesson-container\">\n        <h1>ISLAMSKA PRAVILA PONAŠANJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/masallah.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Islamska pravila ponašanja</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje lijepog ahlaka i ponašanja u svakodnevnom životu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti osnovna islamska pravila ponašanja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Primjena pravila ponašanja u različitim situacijama</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koje su to lijepe stvari koje radimo svaki dan, a koje pokazuju da smo dobro odgojeni? Hajde danas razgovarati o islamskim pravilima ponašanja.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Islam nas uči lijepom ponašanju u svakoj situaciji. Neka osnovna pravila su:</p><p><strong>1.</strong> nazvati selam pri susretu i pri ulasku u kuću ili učionicu,</p><p><strong>2.</strong> proučiti Bismillu prije svakog dobrog posla,</p><p><strong>3.</strong> jesti i piti desnom rukom, sjedeći,</p><p><strong>4.</strong> poštivati starije i biti milostiv prema mlađima,</p><p><strong>5.</strong> govoriti istinu i ne psovati,</p><p><strong>6.</strong> čuvati čistoću tijela, odjeće i okoliša.</p><p>Razgovor: Koja od ovih pravila već primjenjujemo? Koja možemo poboljšati?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici sami nabrajaju pravila i daju primjere iz svog života. Dogovaramo se da svako sebi izabere jedno pravilo na kojem će raditi.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> MALA PRAVILA ZA VELIKE LJUDE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Od kako ste se rodili i počeli govoriti, hodati i istraživati svijet, vaši roditelji vas uče šta je lijepo, a šta nije. Sjećate li se onog čuvenog pitanja: \"A šta se kaže?\", kada bi vas podsjećali da zahvalite na poklonu ili slatkišu?</p>\n                <p class=\"lesson-text\">Naša lijepa vjera islam je poput najboljeg prijatelja koji nam pomaže da budemo kulturni i dobri prema svima. To nisu samo neka pravila iz knjige, već način na koji živimo svaki dan. Biti musliman znači biti pažljiv, čist i ljubazan.</p>\n                <p class=\"lesson-text\">Danas ćemo naučiti te \"čarobne riječi\" koje otvaraju sva vrata i čine Allaha zadovoljnim. Možemo se čak i takmičiti – ko će od nas tokom dana više puta ispravno upotrijebiti Bismillu, Mašallah ili El-hamdu lillah! Spremni?</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\" style=\"margin-bottom: 15px;\">Islamska pravila su i da u raznim situacijama izgovaramo prikladne riječi:</p>\n\n                <table class=\"lesson-table\" style=\"width: 100%; border-collapse: collapse; margin-bottom: 25px;\">\n                    <thead>\n                        <tr style=\"background-color: #fff9c4;\">\n                            <th style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: left; color: var(--primary);\">Termin</th>\n                            <th style=\"padding: 10px; border: 2px solid #f9f1a5; text-align: left; color: var(--primary);\">Značenje / Kada se kaže</th>\n                        </tr>\n                    </thead>\n                    <tbody class=\"lesson-text\" style=\"font-size: 1.2rem;\">\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Bismillāh</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">U ime Allaha kada nešto radimo</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Inšallāh</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Ako Bog da kada se nadamo nečemu</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Mašallāh</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Što hoće Allah - Kada se divimo</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Subhanallāh</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Slava Allahu - Kada smo oduševljeni i kada se čudimo</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">El-hamdu lillāh</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Hvala Allahu - U svakoj prilici</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Jerhamukellāh</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Allah ti se smilovao - Kada čujemo da je neko kihnuo</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Ja Allāh</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">O Allahu - Kada smo u bolu i nevolji</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Estagfirullāh</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Oprosti mi Bože  - Kada se kajemo za loše djelo</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Ne'uzubillāhi</td>\n                            <td style=\"padding: 8px; border: 1px solid #f9f1a5;\">Tražimo zaštitu od Allaha - Kada ukazujemo na nešto ružno</td>\n                        </tr>\n                    </tbody>\n                </table>\n\n                <p class=\"lesson-text\" style=\"margin-bottom: 15px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">ISLAMSKA PRAVILA PRILIKOM JELA I PIĆA</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    - Jesti zdravu i halal – dozvoljenu hranu<br>\n                    - Prije i poslije jela oprati ruke<br>\n                    - Proučiti Euzubillu i Bismillu i jesti desnom rukom<br>\n                    - Jesti zajedno sa porodicom<br>\n                    - Ne jesti vrelu hranu i ne puhati u jelo,<br>\n                    - Nakon jela zahvaliti Allahu riječima: El-hamdu lillāh – hvala Allahu<br>\n                    - Pospremiti sofru<br>\n                    - Nakon jela oprati zube.\n                </p>\n\n            </div>\n        </div>\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('EXTRA', this)\"> PRAKTIČNI SAVJETI ZA SVAKODNEVNU PRIMJENU <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"EXTRA\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Još nekoliko \"zlatnih\" pravila:</span>\n                </p>\n                <p class=\"lesson-text\">\n                    - Jesti ispred sebe ili uzimati hranu ispred sebe.<br>\n                    - U jelu ne pretjerivati i polahko jesti.<br>\n                    - Ne jesti stojeći (osim kada drugačije ne možemo).<br>\n                    - Ne govoriti dok su nam puna usta hrane.<br>\n                    - Kada nam neko učini dobro, kažemo: Džezakellahu hajren (Allah te nagradio dobrom).\n                </p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">MOŽEMO SE TAKMIČITI! Ko će danas najviše puta ispravno upotrijebiti ova pravila kod kuće i u školi? Zapamtite, svaka lijepa riječ je sevap!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ZAPAMTI', this)\"> VAŽNO ZA ZAPAMTITI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ZAPAMTI\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Dobar musliman je kulturan i uvijek se lijepo ponaša.<br>\n                    2. Svojim lijepim ponašanjem mi utječemo da i drugi ljudi budu lijepog ponašanja.\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":47,"is_published":true,"kviz_pitanja":[{"answer":"Bismillāh","options":["Bismillāh","Inšallāh","Mašallāh","El-hamdu lillāh"],"question":"Koju riječ izgovaramo kada nešto počinjemo?"},{"answer":"Ako Bog da","options":["Hvala Allahu","Ako Bog da","Slava Allahu","Oprosti mi Bože"],"question":"Šta znači Inšallāh?"},{"answer":"Kada se divimo","options":["Kada smo tužni","Kada smo bolesni","Kada se divimo","Kada se molimo"],"question":"Kada izgovaramo Mašallāh?"},{"answer":"Jerhamukellāh","options":["Subhanallāh","Jerhamukellāh","Estagfirullāh","Ja Allāh"],"question":"Koju riječ kazujemo kada neko kihnuo?"},{"answer":"Hvala Allahu","options":["O Allahu","Hvala Allahu","Slava Allahu","Ako Bog da"],"question":"Šta znači El-hamdu lillāh?"}]},{"nivo":1,"slug":"mubarek-dani","naslov":"Muslimanski mubarek-dani","content_html":"<div class=\"lesson-container\">\n        <h1>MUSLIMANSKI MUBAREK-DANI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mubarek_dani.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Muslimanski mubarek dani</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje radosti i poštovanja prema vjerskim praznicima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa značajnim danima u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o vjerskoj tradiciji</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koje praznike slavimo u našoj porodici? Koji je najradosniji dan u godini? Danas učimo o našim vjerskim mubarek danima.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mubarek znači blagoslovljen, a mubarek dani su posebno vrijedni dani u islamu.</p><p>Najpoznatiji mubarek dani su: <strong>Ramazanski bajram, Kurban-bajram, Lejletul-Kadr, Mevlud, Lejletul-Bera’et, Lejletul-Mi’radž, Lejletu-r-Regaib</strong> i nova hidžretska godina.</p><p>U te dane se posebno klanja, uči Kur’an, donose salavati, posjećuju rodbina i komšije, i čine dobra djela.</p><p>Razgovor: Koje smo mubarek dane već proslavili u porodici? Kako ih najljepše proslaviti?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju mubarek dane. Pohvaljujem one koji su zapamtili veći broj.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> POSEBNI DANI U NAŠIM ŽIVOTIMA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">E, dragi moji učenici, danas imam jedno pitanje za vas: koji vam je najvažniji dan u životu? Razmislite... Nekome je to rođendan kada dobije poklone, nekome dan kada je dobio novu igračku, a nekome dan kada se okupila cijela porodica. Svi ljudi na svijetu imaju neke odabrane dane koje posebno pamte i kojima se raduju.</p>\n                <p class=\"lesson-text\">Muslimani također imaju svoje odabrane i blagoslovljene dane koje nazivamo mubarek-danima. To su dani u kojima se trebamo posebno osjećati i dočekivati ih svečano i radosno. Bilo da je riječ o Novoj hidžretskoj godini, Mevludu ili našim najdražim bajramima, svaki od tih dana nosi prelijepu priču i podsjeća nas na važne događaje iz naše povijesti. Hajde da naučimo koji su to dani i zašto su nam toliko važni!</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">Muslimanski mubarek-dani su četiri odabrana datuma tokom godine koje zbog svoje važnosti muslimani posebno obilježavaju propisanim obredima i prigodnim svečanostima. Za te dane pripremimo se kako bismo ih što svečanije dočekali i obilježili na prigodan način. U tim danima nastojimo učestvovati u porodičnim, džematskim i društvenim manifestacijama povodom tih dana.</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px; margin-bottom: 20px;\">U hidžretskom kalendaru sljedeći dani su mubarek – odabrani:</p>\n\n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">1. Nova hidžretska godina – 1. muharrem</span>\n                </p>\n                <p class=\"lesson-text\" style=\"margin-bottom: 20px;\">\n                    Ovog dana muslimani obilježavaju početak nove godine kao sjećanje na Hidžru. Hidžra je iseljenje Muhammeda, alejhis-selam, i muslimana iz Mekke u Medinu. Hidžra se dogodila 622. godine i od tada muslimani računaju svoje godine po hidžretskom kalendaru.\n                </p>\n\n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">2. Mevlud – rođenje Muhammeda, alejhis-selam – 12. rebiul-evvel</span>\n                </p>\n                <p class=\"lesson-text\" style=\"margin-bottom: 20px;\">\n                    Mevlud je dan kada je rođen Muhammed, alejhis-selam. Ovaj dan se obilježava učenjem mevluda i drugim prigodnim programima.\n                </p>\n\n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">3. Ramazanski bajram – 1. 2. i 3. ševval</span>\n                </p>\n                <p class=\"lesson-text\" style=\"margin-bottom: 20px;\">\n                    Ramazanski bajram se obilježava nakon mjeseca ramazana kao radost izvršavanja dužnosti posta i drugih obaveza u mjesecu ramazanu.\n                </p>\n\n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">4. Kurban (hadžijski) bajram – 10. 11. 12. i 13. zul-hidže</span>\n                </p>\n                <p class=\"lesson-text\" style=\"margin-bottom: 20px;\">\n                    Kurban-bajram ili Hadžijski bajram se obilježava kao radost izvršavanja obreda hadža, kurbana i tekbiri-tešrika očekujući Allahovu milost i nagradu.\n                </p>\n\n                <p class=\"lesson-text\">Osim ova četiri mubarek-dana, muslimani obilježavaju i četiri mubarek-noći.</p>\n\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Šta su muslimanski mubarek-dani?<br>\n                    2. Kako se pripremamo za ove dane?<br>\n                    3. Nabroji mubarek-dane!<br>\n                    4. Opiši mubarek-dane!\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":48,"is_published":true,"kviz_pitanja":[{"answer":"Četiri dana","options":["Dva dana","Četiri dana","Pet dana","Šest dana"],"question":"Koliko muslimanski mubarek-dana muslimani obilježavaju tokom godine?"},{"answer":"12. rebiul-evvel","options":["1. muharrem","12. rebiul-evvel","1. ševval","10. zul-hidže"],"question":"Koji mjesec hidžretskog kalendara obilježava Mevlud?"},{"answer":"Iseljenje Muhammeda iz Mekke u Medinu","options":["Hadženje u Mekku","Iseljenje Muhammeda iz Mekke u Medinu","Godišnjicu smrti Muhammeda","Početak mjeseca ramazana"],"question":"Šta predstavlja Hidžra koju obilježavamo 1. muharrema?"},{"answer":"1., 2. i 3. ševval","options":["10. zul-hidže","1. muharrem","1., 2. i 3. ševval","12. rebiul-evvel"],"question":"Kada se obilježava Ramazanski bajram?"},{"answer":"Hadža, kurbana i tekbiri-tešrika","options":["Mjesečnog posta","Hadža, kurbana i tekbiri-tešrika","Dnevnog molenja","Učenja Kur'ana"],"question":"Kurban-bajram se obilježava kao radost izvršavanja kojeg obreda?"}]},{"nivo":1,"slug":"ramazanski-bajram","naslov":"Radost Ramazanskog bajrama","content_html":"<div class=\"lesson-container\">\n        <h1>RADOST RAMAZANSKOG BAJRAMA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ramazanski_bajram.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Radost Ramazanskog bajrama</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje radosti i zahvalnosti zbog dolaska Bajrama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je Ramazanski bajram i kako se proslavlja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati osnovne bajramske običaje</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je dan najradosniji nakon mjeseca ramazana? Šta uradite ujutro na taj dan? Hajde da razgovaramo o ljepoti Ramazanskog bajrama.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ramazanski bajram nastupa prvi dan ševvala – odmah nakon završetka mjeseca ramazana. Traje tri dana.</p><p>Tog dana se klanja Bajram-namaz u džamiji, dijeli se sadekatu-l-fitr siromašnima, posjećuju roditelji, rodbina i komšije.</p><p>Lijepo je obući novu ili čistu odjeću, namirisati se, čestitati Bajram riječima: <em>Bajram šerif mubarek olsun!</em> – odgovor: <em>Allah razi olsun!</em></p><p>Razgovor: Kako vi proslavljate Bajram? Koga prvo posjetite? Šta najviše volite na taj dan?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju svoje bajramske doživljaje. Dogovaramo se da Bajram dočekamo kao istinski praznik – sa namazom, sadakom i radošću.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> NAJSLAĐE JUTRO U GODINI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Zamislite jutro koje miriše na baklavu, svježu odjeću i radost koja se osjeća u zraku. To je jutro Ramazanskog bajrama! Nakon mjeseca posta, truda i učenja, dolazi dan kada nas Allah dragi nagrađuje posebnom srećom.</p>\n                <p class=\"lesson-text\">Bajram je vrijeme kada se oblačimo najljepše što imamo, kada očevi i sinovi skupa idu u džamiju na bajram-namaz, a kuće se pune smijehom rodbine i prijatelja. To je dan kada zaboravljamo sve ljutnje, grlimo se i govorimo: \"Bajram šerif mubarek olsun!\"</p>\n                <p class=\"lesson-text\">Najljepši dio bajrama je dijeljenje radosti. Dobiti bajramluk je lijepo, ali je još ljepše vidjeti sreću na licu nane kojoj smo otišli u posjetu ili prijatelja s kojim smo podijelili kolač. Hajde da naučimo zašto je ovaj praznik toliko važan u našim srcima.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Ramazanski bajram su mubarek tri dana poslije mjeseca ramazana. Ramazanski bajram se obilježava 1. 2. i 3. dan mjeseca ševvala kao radost izvršavanja dužnosti posta i drugih obaveza u mjesecu ramazanu.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">Ujutro, prvog dana Bajrama, odlazimo u džamiju klanjati bajram-namaz.</p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 15px; margin-bottom: 15px;\">\n                    <p class=\"lesson-text\">U danima Bajrama radimo Allahu draga djela, veselimo se, obilazimo rodbinu, komšije i prijatelje, međusobno razmjenjujemo poklone.</p>\n                </div>\n\n                <p class=\"lesson-text\">Drugi dan Ramazanskog bajrama u Bosni i Hercegovini se obilježava kao Dan šehida. Na taj dan odlazimo na mezarja i učimo Ja-Sine i Fatihe svojim najbližim, šehidima i svim muslimanima i muslimankama.</p>\n\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; border: 1px solid #f9f1a5; margin-top: 20px;\">\n                    <p class=\"lesson-text\">Bajram čestitamo riječima: BAJRAM ŠERIF MUBAREK OLSUN!</p>\n                    <p class=\"lesson-text\">Na čestitke odgovaramo: ALLAH RAZI OLSUN!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Šta je Ramazanski bajram?<br>\n                    2. Šta radimo prvi dan Bajrama?<br>\n                    3. Kako provodimo dane Bajrama?<br>\n                    4. Kada je Dan šehida?<br>\n                    5. Kako čestitamo Bajram?\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":49,"is_published":true,"kviz_pitanja":[{"answer":"Tri dana","options":["Dva dana","Tri dana","Četiri dana","Pet dana"],"question":"Koliko dana traje Ramazanski bajram?"},{"answer":"Odlazimo u džamiju klanjati bajram-namaz","options":["Idemo na pazar","Odlazimo u džamiju klanjati bajram-namaz","Pripremamo hranu","Posjetimo rodbinu"],"question":"Šta radimo prvi dan Bajrama ujutro?"},{"answer":"Drugog dana Ramazanskog bajrama","options":["Prvog dana Bajrama","Drugog dana Ramazanskog bajrama","Trećeg dana Bajrama","Tokom mjeseca ramazana"],"question":"Kada se obilježava Dan šehida u Bosni i Hercegovini?"},{"answer":"Bajram šerif mubarek olsun!","options":["Novom godinom!","Sretan dan!","Bajram šerif mubarek olsun!","Živjeli!"],"question":"Kako čestitamo Ramazanski bajram?"},{"answer":"U mjesecu ševvalu","options":["U mjesecu ramazanu","U mjesecu ševvalu","U mjesecu muharremu","U mjesecu dhul-hijji"],"question":"U kojem mjesecu se slave tri dana Ramazanskog bajrama?"}]},{"nivo":1,"slug":"kurban-bajram","naslov":"Radost Kurban-bajrama","content_html":"<div class=\"lesson-container\">\n        <h1>RADOST KURBAN-BAJRAMA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/kurban.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Radost Kurban-bajrama</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje žrtve, dijeljenja i pomaganja drugima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je Kurban-bajram i šta je kurban</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati običaje vezane za Kurban-bajram</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li ste čuli za priču o poslaniku Ibrahimu, a.s., i njegovom sinu Ismailu? Šta je Allah od njega tražio? Danas govorimo o Kurban-bajramu.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kurban-bajram nastupa 10. dana mjeseca zul-hidže i traje četiri dana.</p><p>Tog dana se klanja Bajram-namaz, a oni koji to mogu kolju kurban (ovcu, kozu, govedo) – u sjećanje na žrtvu Ibrahima, a.s.</p><p>Meso kurbana se dijeli na tri dijela: jedan za porodicu, jedan za rodbinu i prijatelje, jedan za siromašne.</p><p>U te dane se obavlja i hadž – muslimani iz cijelog svijeta posjećuju Kabu u Mekki.</p><p>Razgovor: Šta nas Kurban-bajram uči? – žrtvu, dijeljenje, brigu za one koji nemaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju razlike između Ramazanskog i Kurban-bajrama. Pohvaljujem trud i znanje.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> DAN ŽRTVE I VELIKE RADOSTI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Dok se još sliježu utisci od Ramazanskog bajrama, u naša srca polahko kuca još jedan veliki praznik – Kurban-bajram. Ovo je poseban dan koji nas uči solidarnosti, hrabrosti i dijeljenju sa onima koji imaju manje od nas.</p>\n                <p class=\"lesson-text\">Kurban-bajram nazivamo i Hadžijski bajram, jer dok mi kod kuće slavimo, milioni muslimana iz cijelog svijeta okupljaju se u časnoj Mekki kako bi obavili petu islamsku dužnost – hadž. To je dan kada mislimo na sve ljude svijeta kao na jednu veliku porodicu.</p>\n                <p class=\"lesson-text\">Posebna ljepota ovog bajrama je kurban. To nije samo običaj, već način da pokažemo Allahu dž.š. našu zahvalnost i da usrećimo komšije i siromašne sočnom bajramskom trpezom. Hajde da naučimo kako se ovaj mubarek-dan ispravno obilježava.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Kurban-bajram su četiri mubarek-dana (10. 11. 12. i 13. dan) mjeseca zul-hidžeta. U tim danima muslimani izvršavaju obrede hadža, kurbana i tekbiri-tešrika očekujući Allahovu milost i nagradu.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">Imućniji muslimani iz cijelog svijeta prije Bajrama otputuju u Mekku radi obavljanja pete islamske dužnosti – hadža. Zato Kurban-bajram zovemo i Hadžijski bajram.</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">Dan uoči i sva četiri dana Kurban-bajrama učimo tekbiri-tešrik. Ovim riječima u danima Kurban-bajrama veličamo Uzvišenog Allaha:</p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        ALLĀHU EKBER, ALLĀHU EKBER, LĀ ILĀHE ILLALLĀHU, VALLĀHU EKBER, ALLĀHU EKBER, VE LILLĀHIL-ḤAMD!\n                    </p>\n                    <p class=\"lesson-text\" style=\"text-align: center; font-style: italic; margin-top: 10px;\">\n                        Allah je najveći, Allah je najveći, samo je Allah Bog, Allah je najveći, Allah je najveći, Allahu neka je hvala!\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px;\">Ujutro prvog dana Bajrama odlazimo u džamiju klanjati bajram-namaz. Poslije klanjanja bajram-namaza oni koji su u mogućnosti prinose kurbane. Kurban je žrtvovanje deve ili govečeta za više a najviše za sedam osoba ili bravčeta – ovna ili ovce za jednu osobu.</p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 15px; margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">PODJELA KURBANSKOG MESA</span>\n                </p>\n                <p class=\"lesson-text\">\n                    Jednu trećinu kurbanskog mesa možemo zadržati za sebe, drugu trećinu dijelimo siromašnima a treću dijelimo rodbini, komšijama i prijateljima.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('EXTRA', this)\"> ŠTA JE TO TEKBIRI-TEŠRIK? <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"EXTRA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Tekbiri-tešrik je posebna vrsta veličanja Allaha koja se uči samo uz ovaj bajram. Počinjemo ga učiti od sabah-namaza na dan Arefata (dan prije Bajrama) i završavamo sa ikindija-namazom četvrtog dana Bajrama.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 10px; margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Zašto koljemo kurban?</span>\n                </p>\n                <p class=\"lesson-text\">Kurban nas podsjeća na poslanika Ibrahima a.s. i njegovu spremnost da izvrši Allahovu naredbu. Danas, mi kroz kurban pokazujemo da smo spremni žrtvovati dio svog imetka kako bismo pomogli drugima. To je vrhunac humanosti u islamu.</p>\n                \n                <div class=\"arabic-card\" style=\"margin-top: 15px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">ZANIMLJIVOST: Kurban-bajram traje jedan dan duže od Ramazanskog bajrama – ukupno četiri dana!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Šta je Kurban-bajram?<br>\n                    2. Šta se obavlja u Mekki u dane Kurban-bajrama?<br>\n                    3. Šta je tekbiri-tešrik i kako glasi?<br>\n                    4. Šta radimo poslije klanjanja bajram-namaza?<br>\n                    5. Šta je kurban i kako dijelimo kurbansko meso?\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":50,"is_published":true,"kviz_pitanja":[{"answer":"Četiri dana","options":["Tri dana","Četiri dana","Pet dana","Sedam dana"],"question":"Koliko dana traje Kurban-bajram?"},{"answer":"Hadž","options":["Hadž","Molitva","Post","Milostinja"],"question":"Koja je peta islamska dužnost koju muslimani obavljaju prije Bajrama?"},{"answer":"Na tri jednaka dijela","options":["Sve se daje siromašnima","Na tri jednaka dijela","Sve se čuva za sebe","Pola se baca"],"question":"Na koji način se dijeli kurbansko meso?"},{"answer":"Od sabah-namaza na dan Arefata","options":["Od bajram-namaza","Od sabah-namaza na dan Arefata","Od akšama-namaza","Od džuhr-namaza"],"question":"Kada počinjemo učiti tekbiri-tešrik?"},{"answer":"Maksimalno sedam osoba","options":["Samo jedna osoba","Maksimalno tri osobe","Maksimalno sedam osoba","Samo pet osoba"],"question":"Koliko ljudi može koristiti jednu devu ili govečeta kao kurban?"}]},{"nivo":1,"slug":"za-bajram-je-pohvalno","naslov":"Za Bajram je lijepo i pohvalno","content_html":"<div class=\"lesson-container\">\n        <h1>ZA BAJRAM JE LIJEPO I POHVALNO</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/bajramsko_veselje.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Za Bajram je lijepo i pohvalno</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema bajramskim sunnetima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je sunnet i pohvalno činiti za Bajram</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike pripreme za Bajram</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako se vi pripremate za Bajram? Šta uradite uvečer prije Bajrama, a šta ujutro? Hajde da naučimo šta je za Bajram pohvalno raditi.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Za Bajram je lijepo i pohvalno (sunnet) sljedeće:</p><p><strong>1.</strong> rano ustati i okupati se (uzeti gusul),</p><p><strong>2.</strong> obući lijepu i čistu odjeću,</p><p><strong>3.</strong> namirisati se,</p><p><strong>4.</strong> pojesti nešto slatko prije Bajram-namaza (na Ramazanski bajram),</p><p><strong>5.</strong> u džamiju i iz džamije ići različitim putevima,</p><p><strong>6.</strong> donositi tekbire i salavate,</p><p><strong>7.</strong> čestitati Bajram poznanicima i nepoznatima.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju bajramske sunnete. Dogovaramo se da na sljedećem Bajramu primijenimo sve što smo naučili.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> KAKO DOČEKATI NAJDRAŽEG GOSTA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Kada nam u kuću dolazi drag gost, mi očistimo sobe, pripremimo najljepšu hranu i obučemo najljepšu odjeću. Bajram je upravo to – naš najdraži gost koji nam dolazi dva puta godišnje.</p>\n                <p class=\"lesson-text\">Naša vjera nas uči da taj dan zablistamo i izvana i iznutra. Lijepo ponašanje za Bajram pokazuje koliko poštujemo te mubarek dane. To su mali koraci – od čišćenja kuće do osmijeha i ljubaznosti prema našim roditeljima i rodbini. Svaki taj postupak čini Bajram praznikom ljubavi, čistoće i zajedništva.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Pohvalne radnje za bajram su:</span>\n                </p>\n                <p class=\"lesson-text\">\n                    - očistiti i uljepšati kuću, džamiju i okolinu<br>\n                    - proučiti nešto pred duše svojih najbližih<br>\n                    - okupati se i namirisati<br>\n                    - obući najljepšu svečanu odjeću<br>\n                    - poraniti u džamiju na sabah-namaz<br>\n                    - učiti tekbire i udijeliti što više sadake<br>\n                    - podijeliti radost Bajrama sa drugima<br>\n                    - darivati drugima bajramske darove<br>\n                    - pripremiti bajramska jela i kolače<br>\n                    - posjetiti svoje najbliže, komšije, rodbinu i prijatelje.\n                </p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">Roditeljima čestitamo bajram ljubeći ih u desnu ruku i darivajući im neki dar. Oni nama daruju bajramluk. Roditeljima pomažemo u pripremi bajramskih jela i kolača.</p>\n                </div>\n\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; border: 1px solid #f9f1a5; margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center; margin-bottom: 5px;\">ZAPAMTI!</p>\n                    <p class=\"lesson-text\">Pohvalne radnje za oba Bajrama su iste. Razlika je samo što je za Ramazanski bajram lijepo nešto pojesti – npr. hurmu poslije zore a prije odlaska u džamiju, a za Kurban-bajram lijepo je postiti od zore do klanjanja bajram-namaza.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('SUNNET', this)\"> SAVJETI ZA LJEPŠI BAJRAM <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"SUNNET\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Dodatni bajramski bonton:</span>\n                </p>\n                <p class=\"lesson-text\">\n                    - Posebno očistiti zube (misvakom ili četkicom) prije odlaska u džamiju.<br>\n                    - Za Ramazanski bajram je lijepo pojesti neparan broj hurmi (1, 3 ili 5) prije namaza.<br>\n                    - Otići u džamiju ranije radi učenja zikra i mirnog dočeka namaza.<br>\n                    - Pri povratku iz džamije promijeniti put kako bismo sreli i poselamili što više ljudi.<br>\n                    - Putem do džamije tiho učiti tekbire u sebi.\n                </p>\n                <div class=\"arabic-card\" style=\"margin-top: 15px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">Znaš li zašto mijenjamo put? Da bi što više ulica i mjesta na zemlji svjedočilo našem odlasku na namaz i radosti koju širimo!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Koje su pohvalne radnje za Bajram?<br>\n                    2. Kako čestitamo Bajram roditeljima?<br>\n                    3. Zašto je lijepo promijeniti put pri povratku iz džamije?<br>\n                    4. Šta pojesti prije odlaska na bajram-namaz?<br>\n                    5. Opiši svoje doživljaje Bajrama!\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":51,"is_published":true,"kviz_pitanja":[{"answer":"Očistiti i uljepšati kuću, džamiju i okolinu","options":["Očistiti i uljepšati kuću, džamiju i okolinu","Ostati kod kuće cijeli dan","Spavati duže nego obično","Izbjegavati druge ljude"],"question":"Koja je jedna od pohvalnih radnji za Bajram?"},{"answer":"Pojesti neparan broj hurmi","options":["Pojesti neparan broj hurmi","Postiti od zore do klanjanja","Ostati kod kuće","Spavati dodatno"],"question":"Šta je lijepo uraditi za Ramazanski bajram prije odlaska u džamiju?"},{"answer":"Ljubeći ih u desnu ruku i darivajući dar","options":["Ljubeći ih u desnu ruku i darivajući dar","Samo kažemo čestitku","Ne čestitamo ništa","Samo slanjem poruke"],"question":"Kako čestitamo Bajram roditeljima?"},{"answer":"Za Ramazanski je lijepo pojesti hurmu, za Kurban postiti","options":["Za Ramazanski je lijepo pojesti hurmu, za Kurban postiti","Nema nikakve razlike","Kurban-bajram je važniji","Samo se datumi razlikuju"],"question":"Koja je razlika između Ramazanskog i Kurban-bajrama?"},{"answer":"Promijeniti put kako bismo sreli više ljudi","options":["Promijeniti put kako bismo sreli više ljudi","Brže trčati kući","Direktno ići kući","Čekati druge ljude"],"question":"Što je dodatni bajramski bonton pri povratku iz džamije?"}]},{"nivo":1,"slug":"nova-hidzretska-godina","naslov":"Nova hidžretska godina","content_html":"<div class=\"lesson-container\">\n        <h1>NOVA HIDŽRETSKA GODINA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/nova_godina.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Nova hidžretska godina</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o islamskoj historiji</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je hidžretska godina i kako je nastala</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati način računanja vremena u islamu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, znate da postoji naša \"obična\" godina koja počinje 1. januara. Ali postoji i druga, posebna godina koju koriste muslimani. Kako se zove i kada počinje?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Hidžretska godina je islamska godina koja se računa od preseljenja (hidžre) Poslanika, a.s., iz Mekke u Medinu (622. godine po miladu).</p><p>Prvi mjesec u hidžretskoj godini je <strong>muharrem</strong>. Kada nastupi 1. muharrem, to je nova hidžretska godina.</p><p>Godina se računa po kretanju mjeseca, pa hidžretska godina ima oko 354 dana – kraća je od miladske za oko 11 dana.</p><p>Hidžra je bila važan događaj jer je Poslanik, a.s., u Medini osnovao prvu islamsku zajednicu i izgradio prvu džamiju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam: Od kojeg događaja počinje hidžretska godina? Koji je prvi mjesec? Učenici odgovaraju.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> KAKO MJERIMO VRIJEME <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Jeste li se ikada zapitali zašto imamo kalendare? Oni su tu da nas podsjete na važne događaje iz prošlosti. Dok cijeli svijet prati jedan kalendar, mi muslimani imamo i svoj poseban – Hidžretski kalendar.</p>\n                <p class=\"lesson-text\">Sve je počelo jednim velikim putovanjem koje se zove Hidžra. To nije bilo obično putovanje radi odmora, već putovanje našeg Poslanika, alejhis-selam, iz Mekke u Medinu kako bi sačuvao vjeru i izgradio zajednicu u kojoj će svi biti sigurni. Taj događaj je bio toliko važan da smo od tog trenutka počeli brojati naše godine.</p>\n                <p class=\"lesson-text\">Nova hidžretska godina nas podsjeća da svaki novi početak donosi nadu i priliku da budemo bolji ljudi, baš kao što su to bili ashabi koji su krenuli na put Hidžre.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Nova muslimanska godina počinje prvog dana mjeseca muharrema. Na ovaj dan obilježavamo sjećanje na Hidžru pa ovu godinu nazivamo hidžretska. Hidžra je iseljenje Muhammeda, alejhis-selam, i muslimana iz Mekke u Medinu.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px; margin-bottom: 15px;\">Hidžra se dogodila 622. godine i od tada muslimani računaju svoje godine po hidžretskom kalendaru. Hidžretski kalendar ima dvanaest mjeseci:</p>\n\n                <table class=\"lesson-table\" style=\"width: 100%; border-collapse: collapse; margin-bottom: 20px;\">\n                    <tbody class=\"lesson-text\">\n                        <tr>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; width: 10%; text-align: center;\">1.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center; width: 40%;\">MUHARREM</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; width: 10%; text-align: center;\">7.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center; width: 40%;\">REDŽEB</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">2.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">SAFER</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">8.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">ŠA'BAN</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">3.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">REBIUL-EVVEL</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">9.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">RAMAZAN</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">4.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">REBIUL-AHIR</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">10.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">ŠEVVAL</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">5.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">DŽUMADEL-ULA</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">11.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">ZUL-KADE</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">6.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">DŽUMADEL-UHRA</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; background-color: #fff9c4; text-align: center;\">12.</td>\n                            <td style=\"padding: 10px; border: 1px solid #f9f1a5; text-align: center;\">ZUL-HIDŽE</td>\n                        </tr>\n                    </tbody>\n                </table>\n\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; border: 1px solid #f9f1a5; margin-bottom: 20px;\">\n                    <p class=\"lesson-text\">Hidžretska godina je lunarna – mjesečeva godina i ima trista pedeset pet dana. Prvi dan sedmice hidžretskog kalendara je petak. Dan u hidžretskom kalendaru počinje od zalaska Sunca i traje do sljedećeg zalaska.</p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">Hidžretsku godinu čestitamo riječima:<br>MUBAREK NOVA HIDŽRETSKA GODINA!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('EXTRA', this)\"> MJESEC I NAŠ KALENDAR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"EXTRA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Za razliku od sunčevog kalendara koji prati Sunce, naš kalendar prati kretanje Mjeseca. Zato naši blagdani, poput Ramazana i Bajrama, svake godine dolaze desetak dana ranije.</p>\n                <p class=\"lesson-text\" style=\"margin-top: 10px;\">Riječ \"hidžra\" znači seoba. To je bio trenutak kada su muslimani morali napustiti svoje domove u Mekki kako bi mogli slobodno živjeti svoju vjeru u Medini. Taj događaj je bio prekretnica u povijesti islama.</p>\n                <div class=\"arabic-card\" style=\"margin-top: 15px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">ZANIMLJIVOST: Mjesec muharrem, kojim počinje naša godina, jedan je od četiri sveta mjeseca u islamu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Kada počinje i kako se zove muslimanska nova godina?<br>\n                    2. Šta je Hidžra i kada se dogodila?<br>\n                    3. Nabroji mjesece hidžretskog kalendara?<br>\n                    4. Opiši hidžretsku godinu!\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":52,"is_published":true,"kviz_pitanja":[{"answer":"Sjećanje na Hidžru Muhammeda i muslimana","options":["Sjećanje na Hidžru Muhammeda i muslimana","Proslava Muhammadovog rođenja","Obilježavanje kraja mjeseca ramazana","Proslava osvajanja Mekke"],"question":"Koja je glavna svrha obilježavanja novog dana muharrema?"},{"answer":"Iseljenje Muhammeda iz Mekke u Medinu","options":["Iseljenje Muhammeda iz Mekke u Medinu","Put od Medine do Mekke","Mjesec u kojem se fali","Naziv za molitvu u džamiji"],"question":"Šta je Hidžra?"},{"answer":"622. godine","options":["622. godine","712. godine","520. godine","632. godine"],"question":"Koje godine se dogodila Hidžra?"},{"answer":"Po hidžretskom kalendaru","options":["Po hidžretskom kalendaru","Po gregorijanskom kalendaru","Po egipatskom kalendaru","Po turskom kalendaru"],"question":"Po kojem kalendaru muslimani računaju godine nakon Hidžre?"},{"answer":"Dvanaest mjeseci","options":["Dvanaest mjeseci","Deset mjeseci","Trinaest mjeseci","Jedanaest mjeseci"],"question":"Koliko mjeseci ima hidžretski kalendar?"}]},{"nivo":1,"slug":"mevlud","naslov":"Mevlud","content_html":"<div class=\"lesson-container\">\n        <h1>MEVLUD</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mevlud.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Mevlud – sjećanje na rođenje Poslanika, a.s.</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Poslaniku, a.s.</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je mevlud i kada se obilježava</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati tradiciju proslave mevluda</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako se osjećate kad neko od vaših drugara ima rođendan? A da li znate kada je rođen najdraži čovjek svim muslimanima – Muhammed, a.s.?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mevlud je sjećanje na rođenje Allahovog Poslanika Muhammeda, a.s.</p><p>Poslanik, a.s., rođen je u Mekki, 12. dana mjeseca rebi’ul-evvela.</p><p>Mevlud se proslavlja u džamijama i kućama – uče se ilahije i kaside, donose salavati i prepričava život Poslanika, a.s.</p><p>Kod nas je posebno poznat Mevlud Hafiza Saliha Gaševića pisan na bosanskom jeziku.</p><p>Razgovor: Jeste li bili na mevludu? Koje ste ilahije čuli? Kako se osjećate kad slušate o životu Poslanika, a.s.?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učimo zajedno salavat: <em>Allahumme salli ‘alā Muhammed.</em> Dogovaramo se da na mevlud donosimo što više salavata.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> DAN KADA JE SVANUO NAJLJEPŠI DAN <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Es-selamu ‘alejkum ve rahmetullahi ve berekatuhu, dragi moji učenici!</p>\n                <p class=\"lesson-text\">Svi mi imamo dane kojima se radujemo, ali jedan datum je poseban za sve muslimane svijeta – to je Mevlud, dan u kojem je rođen Allahov poslanik, Muhammed, alejhis-selam. Pošto ga mi neizmjerno volimo, taj dan obilježavamo s posebnom radošću.</p>\n                <p class=\"lesson-text\">Kod nas, Bošnjaka, običaj je da se okupimo u džamijama, učimo ilahije, kaside i slušamo priče o Poslanikovom životu i njegovoj porodici. A znate li šta je djeci najdraži dio? Podjela slatkiša i onog posebnog soka koji se zove šerbe! Šerbe je sok koji se priprema samo za najsvečanije prilike. Pitajte roditelje o njemu, oni se sigurno sjećaju mirisa šerbeta iz svog djetinjstva.</p>\n                <p class=\"lesson-text\">Danas ćemo kroz stihove i priču osjetiti tu toplinu Mevluda i naučiti zašto je važno da se sjećamo našeg miljenika, Muhammeda, alejhis-selam</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Mevlud je dan rođenja Muhammeda, alejhis-selam. Muhammed, alejhis-selam, rođen je u ponedjeljak, u zoru, 12. rebiul-evvela (20. aprila 571. godine) u gradu Mekki.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 15px; margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">KAKO SE OBILJEŽAVA MEVLUD?</span>\n                </p>\n                <p class=\"lesson-text\">\n                    Muslimani širom svijeta obilježavaju ovaj dan učenjem Kur’ana i prigodnim programima u kojima se podsjećaju na život Muhammeda, alejhis-selam. U našim džamijama se tim povodom uči poseban spjev o njegovom rođenju koji se naziva mevlud.\n                </p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        Rekao je Muhammed, alejhis-selam:<br>\n                        \"Meni će najpreči na Sudnjem danu biti oni koji mi najviše prouče salavata.\"<br>\n                        (Tirmizi)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('POETRY', this)\"> MEVLUDSKI STIHOVI I SALAVATI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"POETRY\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-style: italic;\">\n                    Proučimo Muhammedu mevlud mi,<br>\n                    zahvalimo punim srcem njemu svi!<br>\n                    Nek’ to bude topla hvala sviju nas,<br>\n                    Pejgamberu što pokaza put i spas.<br><br>\n                    Mevlud, mevlud, Muhammeda rođendan,<br>\n                    nesta mraka i zabluda sviće dan!<br>\n                    Muhammed je ljudskom rodu na dar dat,<br>\n                    donesimo odabranom salavat:\n                </p>\n\n                <div class=\"arabic-card\" style=\"margin-top: 15px; margin-bottom: 15px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        ES-SALATU VES-SELAMU ‘ALEJKE JA RESULALLAH!<br>\n                        ES-SALATU VES-SELAMU ‘ALEJKE JA HABIBALLAH!<br>\n                        ES-SALATU VES-SELAMU ‘ALEJKE JA ŠEFI’ALLAH!\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-bottom: 20px;\">\n                    Neka je na tebe Allahov blagoslov i mir, Allahov poslaniče!<br>\n                    Neka je na tebe Allahov blagoslov i mir, Allahov miljeniče!<br>\n                    Neka je na tebe Allahov blagoslov i mir, kod Allaha zagovorniče!\n                </p>\n\n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Dobro nam doš'o:</span>\n                </p>\n                <p class=\"lesson-text\" style=\"font-style: italic;\">\n                    Dobro nam doš’o najveći sine<br>\n                    arapskog roda i domovine!<br>\n                    Dobro nam doš’o stari plemiću<br>\n                    Hašimoviću, Kurejševiću!<br>\n                    Koji će slabe dići na noge<br>\n                    i spasit ropstva narode mnoge!\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ZAPAMTI', this)\"> VAŽNO ZA ZAPAMTITI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ZAPAMTI\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Mevlud je dan u kojem je rođen Muhammed, alejhis-selam.<br>\n                    2. Muslimani obilježavaju dan Mevluda prigodnim programima.<br>\n                    3. Mevludom pokazujemo ljubav prema Allahovom poslaniku.\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":53,"is_published":true,"kviz_pitanja":[{"answer":"12. rebiul-evvela","options":["10. rebiul-evvela","12. rebiul-evvela","15. rebiul-evvela","20. rebiul-evvela"],"question":"Koji je dan po redu iz mjeseca Rebiul-evvela rođen Muhammed, alejhis-selam?"},{"answer":"Mekki","options":["Medini","Mekki","Jerusalimu","Taifi"],"question":"U kojem gradu je rođen Muhammed, alejhis-selam?"},{"answer":"Mevlud","options":["Kaside","Mevlud","Dova","Tilava"],"question":"Kako se zove poseban spjev o Muhammeda rođenju koji se uči u džamijama?"},{"answer":"Ponedjeljak","options":["Petak","Ponedjeljak","Srijeda","Četvrtak"],"question":"Kojim danom sedmice je rođen Muhammed, alejhis-selam?"},{"answer":"Put i spas","options":["Bogato blago","Moć i vlast","Put i spas","Broje i slavlje"],"question":"Šta je Muhammed, alejhis-selam, ljudskom rodu dao prema tekstu?"}]},{"nivo":1,"slug":"dobro-nam-dos-o","naslov":"Dobro nam doš'o","content_html":"<div class=\"lesson-container\">\n        <h1>DOBRO NAM DOŠAO</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mevlud2.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dobro nam doš’o – ilahija o ramazanu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kiraet</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje radosti zbog dolaska mjeseca ramazana</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti riječi ilahije \"Dobro nam doš’o\"</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje muzičkog osjećaja kroz ilahije</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako dočekujemo dragog gosta u našoj kući? A koji nam to mjesec dolazi jednom godišnje, kao najdraži gost? Hajde danas naučiti ilahiju kojom ga dočekujemo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ilahija \"Dobro nam doš’o\" pjeva o radosti zbog dolaska mjeseca ramazana – mjeseca posta, Kur’ana i milosti.</p><p>Postupak: Učim ilahiju polako, stih po stih. Učenici slušaju, zatim ponavljaju zajedno.</p><p>Razgovor: Šta nam ramazan donosi? Zašto smo radosni kad dođe? Šta posebno radimo u tom mjesecu? (post, teravije, učenje Kur’ana, sehur, iftar)</p><p>Učenici uče ilahiju i razgovaraju o ljepotama ramazana.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici zajedno pjevaju ilahiju. Pohvaljujem trud i podstičem ih da je nauče napamet do dolaska ramazana.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> LJUBAV KOJA SE PJESMOM KAZUJE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Muslimani širom svijeta već stoljećima pišu najljepše stihove i pjevaju kaside u kojima hvale i iskazuju svoju neizmjernu ljubav prema Poslaniku, alejhis-selam Ove pjesme su odraz duše vjernika koji u svakoj riječi traži način da se zahvali na uputi koju nam je Muhammed, alejhis-selam, donio.</p>\n                <p class=\"lesson-text\">Iako tu ljubav najbolje iskazujemo slijedeći njegov sunnet i moralne principe u svakodnevnom životu, naša tradicija pisanja i učenja mevluda pokazuje koliko je on voljen u našim porodicama.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; border: 1px solid #f9f1a5; margin-bottom: 20px;\">\n                    <p class=\"lesson-text\">\n                        Rekao je Muhammed, alejhis-selam:<br>\n                        “Meni će najpreči na Sudnjem danu biti oni koji mi najviše prouče salavata.” (Tirmizi)\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center; font-size: 1.6rem; color: var(--primary); margin-bottom: 20px;\">Dobro nam doš’o</p>\n                    <div style=\"display: flex; justify-content: space-between; gap: 20px;\">\n                        <div style=\"flex: 1;\">\n                            <p class=\"lesson-text\">\n                                Dobro nam doš’o najveći sine<br>\n                                arapskog roda i domovine!<br><br>\n                                Dobro nam doš’o stari plemiću,<br>\n                                Hašimoviću, Kurejševiću!\n                            </p>\n                        </div>\n                        <div style=\"flex: 1;\">\n                            <p class=\"lesson-text\">\n                                Dobro nam doš’o prosvjetitelju,<br>\n                                zagovorniče i spasitelju!<br><br>\n                                Suri Israfil kada zapuše,<br>\n                                u te se naše uzdaće duše!\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Kako muslimani iskazuju ljubav prema Poslaniku, alejhis-selam?<br>\n                    2. Šta je Muhammed, alejhis-selam, rekao o salavatima?<br>\n                    3. Zašto su mevludski spjevovi važni u našoj tradiciji?\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":54,"is_published":true,"kviz_pitanja":[{"answer":"Meni će najpreči biti oni koji mi najviše prouče salavata","options":["Meni će najpreči biti oni koji mi najviše prouče salavata","Salavati nisu važni za muslimane","Samo žene trebaju čitati salavate","Salavati se čitaju samo u mjesecu Ramazanu"],"question":"Šta je Muhammed, alejhis-selam, rekao o salavatima?"},{"answer":"570. godine","options":["570. godine","612. godine","622. godine","632. godine"],"question":"Koje godine se Muhammed, alejhis-selam, rodio?"},{"answer":"Kroz čitanje i pjevanje mevludskih spjevova","options":["Kroz čitanje i pjevanje mevludskih spjevova","Kroz blagajne i sadaku","Kroz brojanje tasbih-a","Kroz pisanje pismo Poslaniku"],"question":"Kako se tradicionalno u našoj kulturi iskazuje ljubav prema Poslaniku?"},{"answer":"Od Hašimovića i Kurejšana","options":["Od Hašimovića i Kurejšana","Od Omejada","Od Abbasa","Od Umayyada"],"question":"Od koje племenske linije je bio Muhammed, alejhis-selam?"},{"answer":"Muhammed, alejhis-selam","options":["Muhammed, alejhis-selam","Abubekr, radijallahu anhu","Ali ibn Abi Talib","Osman ibn Affan"],"question":"Ko je prema tekstu pozvan kao najveći sine arapskog roda?"}]},{"nivo":1,"slug":"pet-dnevnih-namaza","naslov":"Pet dnevnih namaza","content_html":"<div class=\"lesson-container\">\n        <h1>PET DNEVNIH NAMAZA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dnevni_namazi.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Pet dnevnih namaza</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o važnosti redovnog obavljanja namaza</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti imena pet dnevnih namaza i njihova okvirna vremena</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti prepoznavanja vremena namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko puta dnevno čujemo ezan? Šta to znači? Allah nam je propisao pet susreta sa Njim svaki dan – pet namaza, koje danas učimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>U toku jednog dana i noći klanja se pet farz-namaza:</p><p><strong>1. Sabah</strong> – od zore do pred izlazak Sunca,</p><p><strong>2. Podne</strong> – kad Sunce prođe sredinu neba do kasnog popodneva,</p><p><strong>3. Ikindija</strong> – kad Sunce nagne zapadu do pred zalazak,</p><p><strong>4. Akšam</strong> – odmah nakon zalaska Sunca, do potpunog mraka,</p><p><strong>5. Jacija</strong> – nakon što potpuno padne mrak, do pred zoru.</p><p>Postupak: Pišem nazive namaza na tabli. Pomoću slike sata pokazujem približna vremena. Učenici nabrajaju namaze.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Provjeravam: Koliko ima dnevnih namaza? Nabroji ih po redu. Kada je sabah, a kada akšam? Učenici odgovaraju.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> PET SUSRETA SA GOSPODAROM <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Zamislite da imate najboljeg prijatelja koji je uvijek tu za vas, koji vas najbolje razumije i koji vam može ispuniti svaku želju. Namaz je upravo to – naš direktni razgovor sa Uzvišenim Allahom.</p>\n                <p class=\"lesson-text\">Klanjanje namaza je druga islamska dužnost i to je najuzvišeniji način na koji pokazujemo svoju zahvalnost Stvoritelju. Kroz namaz mi čistimo svoju dušu, smirujemo srce i punimo se snagom za sve izazove koje nam dan donosi.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Druga islamska dužnost – šart je klanjati namaz.</p>\n                <p class=\"lesson-text\" style=\"margin-top: 10px;\">\n                    <span style=\"background-color: #fff9c4; padding: 2px 5px; border-radius: 5px; color: var(--primary);\">Namaz</span> je najuzvišeniji način iskazivanja pokornosti i zahvalnosti Uzvišenom Allahu. Klanjajući namaz mi se želimo približiti svom Gospodaru i steći Njegovu naklonost.\n                </p>\n                <p class=\"lesson-text\" style=\"margin-top: 10px;\">U toku dana i noći pet je namaza: <strong>sabah, podne, ikindija, akšam i jacija</strong>.</p>\n\n                <div class=\"namaz-grid\">\n                    <div class=\"namaz-item\">\n                        <img src=\"/edu/assets/images/sabah.png\">\n                        <p class=\"lesson-text\" style=\"font-size: 0.9rem;\">SABAH</p>\n                    </div>\n                    <div class=\"namaz-item\">\n                        <img src=\"/edu/assets/images/podne.png\">\n                        <p class=\"lesson-text\" style=\"font-size: 0.9rem;\">PODNE</p>\n                    </div>\n                    <div class=\"namaz-item\">\n                        <img src=\"/edu/assets/images/ikindija.png\">\n                        <p class=\"lesson-text\" style=\"font-size: 0.9rem;\">IKINDIJA</p>\n                    </div>\n                    <div class=\"namaz-item\">\n                        <img src=\"/edu/assets/images/aksam.png\">\n                        <p class=\"lesson-text\" style=\"font-size: 0.9rem;\">AKŠAM</p>\n                    </div>\n                    <div class=\"namaz-item\">\n                        <img src=\"/edu/assets/images/jacija.png\">\n                        <p class=\"lesson-text\" style=\"font-size: 0.9rem;\">JACIJA</p>\n                    </div>\n                </div>\n\n                <div class=\"namaz-time-box\">\n                    <div class=\"namaz-number\">1.</div>\n                    <p class=\"lesson-text\"><strong>SABAH-NAMAZ:</strong> Vrijeme sabah-namaza počinje od zore i traje do pred izlazak Sunca – ili pri naklanjavanju, do pred podne.</p>\n                </div>\n                <div class=\"namaz-time-box\">\n                    <div class=\"namaz-number\" style=\"background-color: #fbc02d;\">2.</div>\n                    <p class=\"lesson-text\"><strong>PODNE-NAMAZ:</strong> Vrijeme podne-namaza počinje kada Sunce malo odmakne sa sredine neba i traje do kasnog popodneva.</p>\n                </div>\n                <div class=\"namaz-time-box\">\n                    <div class=\"namaz-number\" style=\"background-color: #03a9f4;\">3.</div>\n                    <p class=\"lesson-text\"><strong>IKINDIJA-NAMAZ:</strong> Vrijeme ikindija-namaza počinje kada Sunce nagne zapadu i traje do pred zalazak Sunca.</p>\n                </div>\n                <div class=\"namaz-time-box\">\n                    <div class=\"namaz-number\" style=\"background-color: #7e57c2;\">4.</div>\n                    <p class=\"lesson-text\"><strong>AKŠAM-NAMAZ:</strong> Vrijeme akšam-namaza počinje od zalaska Sunca i traje do potpunog mraka.</p>\n                </div>\n                <div class=\"namaz-time-box\">\n                    <div class=\"namaz-number\" style=\"background-color: #3f51b5;\">5.</div>\n                    <p class=\"lesson-text\"><strong>JACIJA-NAMAZ:</strong> Vrijeme jacija-namaza počinje kada potpuno nestane Sunčeve svjetlosti i traje do pred zoru.</p>\n                </div>\n\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; border: 1px solid #f9f1a5; margin: 20px 0;\">\n                    <p class=\"lesson-text\"><strong>Osim pet dnevnih namaza još klanjamo:</strong></p>\n                    <ul class=\"lesson-text\">\n                        <li>petkom džuma-namaz</li>\n                        <li>teravih-namaz tokom ramazana</li>\n                        <li>dva bajram-namaza</li>\n                        <li>povremeno dženaza-namaz.</li>\n                    </ul>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        Klanjati namaze učimo od ranog djetinjstva a redovno klanjamo od desete godine do kraja života.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Koja je druga islamska dužnost?<br>\n                    2. Šta je namaz?<br>\n                    3. Šta želimo postići klanjajući namaz?<br>\n                    4. Opiši vrijeme pet dnevnih namaza?<br>\n                    5. Koje još namaze klanjamo?<br>\n                    6. Kada učimo klanjati namaze?\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":55,"is_published":true,"kviz_pitanja":[{"answer":"Pet","options":["Pet","Tri","Sedam","Deset"],"question":"Koliko ima dnevnih namaza?"},{"answer":"Sabah, podne, ikindija, akšam, jacija","options":["Sabah, podne, ikindija, akšam, jacija","Podne, ikindija, akšam, sabah, jacija","Sabah, akšam, jacija, podne, ikindija","Jacija, sabah, podne, akšam, ikindija"],"question":"Koji su dnevni namazi po redu?"},{"answer":"Od zore do pred izlazak Sunca","options":["Od zore do pred izlazak Sunca","Od zalaska Sunca","U podne","Pred spavanje"],"question":"Kada je vrijeme sabah-namaza?"},{"answer":"Od zalaska Sunca do potpunog mraka","options":["Od zalaska Sunca do potpunog mraka","U zoru","Na podne","Poslije ponoći"],"question":"Kada je vrijeme akšam-namaza?"},{"answer":"Klanjati namaz","options":["Klanjati namaz","Postiti","Davati zekat","Obaviti hadž"],"question":"Šta je druga islamska dužnost?"}]},{"nivo":1,"slug":"sabah-namaz","naslov":"Sabah-namaz","content_html":"<div class=\"lesson-container\">\n        <h1>SABAH-NAMAZ</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sabah_namaz.jpg\">\n        </div>","audio_src":null,"redoslijed":56,"is_published":true,"kviz_pitanja":[{"answer":"Četiri rekata","options":["Dva rekata","Tri rekata","Četiri rekata","Pet rekata"],"question":"Koliko rekata ima sabah-namaz?"},{"answer":"Od zore do pred izlaska Sunca","options":["Od zore do pred izlaska Sunca","Od podne do popodneva","Od zalaska do ponoći","Od ponoći do zore"],"question":"Kada se klanja sabah-namaz?"},{"answer":"Od dva rekata sunneta i dva rekata farza","options":["Samo od sunneta","Samo od farza","Od dva rekata sunneta i dva rekata farza","Od tri rekata sunneta i jednog farza"],"question":"Od čega se sastoji sabah-namaz?"},{"answer":"Prvo sunnet, pa onda farz","options":["Prvo farz, pa onda sunnet","Prvo sunnet, pa onda farz","Istovremeno sunnet i farz","Po želji vjernika"],"question":"Koji je redoslijed klanjanja sabah-namaza?"},{"answer":"Obavezni namazi","options":["Dobrovoljni namazi","Obavezni namazi","Namazi samo za muškarce","Namazi samo za žene"],"question":"Šta znači termin 'farzi' ili 'farz-namazi'?"}]},{"nivo":1,"slug":"sura-el-leheb","naslov":"Sura El-Leheb","content_html":"<div class=\"lesson-container\">\n        <h1>SURA EL-LEHEB</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/leheb.jpg\">\n        </div>","audio_src":null,"redoslijed":57,"is_published":true,"kviz_pitanja":[{"answer":"Plamen","options":["Plamen","Svjetlost","Vatra i dim","Bol"],"question":"Šta znači riječ 'Leheb' iz naslova sure?"},{"answer":"Amidža Muhammeda, a.s.","options":["Amidža Muhammeda, a.s.","Brat Muhammeda, a.s.","Sin Muhammeda, a.s.","Prijatelj Muhammeda, a.s."],"question":"Ko je bio Ebu Leheb?"},{"answer":"Jer je napadao i vrijeđao Muhammeda, a.s.","options":["Jer je napadao i vrijeđao Muhammeda, a.s.","Jer je bio bogat","Jer nije mogao da čita","Jer je putovao"],"question":"Zašto je Ebu Leheb proklinjet u ovoj suri?"},{"answer":"Više od jednog","options":["Više od jednog","Samo jedan","Pet naziva","Deset naziva"],"question":"Koliko naziva ima Sura Leheb?"},{"answer":"Leheb, Mesed, Tebbet","options":["Leheb, Mesed, Tebbet","Leheb, Fatiha, Bakarah","Leheb, Ikhlas, Nas","Leheb, Asr, Kafirun"],"question":"Šta su drugi nazivi za Suru Leheb?"}]},{"nivo":1,"slug":"aksam-namaz","naslov":"Akšam-namaz","content_html":"<div class=\"lesson-container\">\n        <h1>AKŠAM-NAMAZ</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/aksam_namaz.jpg\">\n        </div>","audio_src":null,"redoslijed":58,"is_published":true,"kviz_pitanja":[{"answer":"Pet rekata","options":["Tri rekata","Četiri rekata","Pet rekata","Dva rekata"],"question":"Koliko rekata ima akšam-namaz?"},{"answer":"Od zalaska Sunca do potpunog smračenja","options":["Od zore do sunčeva izlaska","Od zalaska Sunca do potpunog smračenja","U podne kada je Sunce najvisoko","Uvijek nakon iftara"],"question":"Kada klanjamo akšam-namaz?"},{"answer":"Tri farza i dva sunneta","options":["Dva farza i tri sunneta","Tri farza i dva sunneta","Četiri farza i jedan sunnet","Svi su farz, nema sunneta"],"question":"Koliko je rekata farza a koliko sunneta u akšam-namazu?"},{"answer":"Sve što nam je Allah naredio da radimo","options":["Sve što nam je Muhammed preporučio","Sve što nam je Allah naredio da radimo","Samo sabahski namaz","Izborni namaz koji možemo preskoči"],"question":"Šta je farz prema tekstu lekcije?"},{"answer":"Prvo farz pa zatim sunnet","options":["Prvo sunnet pa zatim farz","Prvo farz pa zatim sunnet","Istovremeno farz i sunnet","Tek kada se u potpunosti smrači"],"question":"U kojem redoslijedu klanjamo rekat u akšam-namazu?"}]},{"nivo":1,"slug":"ajetul-kursija","naslov":"Ajetul-Kursija","content_html":"<div class=\"lesson-container\">\n        <h1>AJETUL-KURSIJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/kuran.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ajetul-Kursija</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kiraet</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Kur’anu i učenju njegovih ajeta</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst i značenje Ajetul-Kursije</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti memorisanja dužih kur’anskih tekstova</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je najveći ajet u Kur’anu? Poslanik, a.s., je rekao da onaj ko ga uči poslije svakog farz-namaza ne razdvaja ga od Dženneta osim smrti. To je Ajetul-Kursija.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ajetul-Kursija je 255. ajet sure El-Bekare. Govori o veličini i moći Allaha, dž.š.</p><p>U njemu se spominje da Allah nikoga ne ostavlja bez nadgledanja, da Mu ne sustiže ni san ni drijem, te da Njegova vlast obuhvata nebesa i Zemlju.</p><p>Postupak: Učim ajet polako, dio po dio, naglašavajući svaku riječ. Učenici ponavljaju zajedno i pojedinačno. Pišem ajet na tabli s transkripcijom.</p><p>Razgovor: Šta nam ovaj ajet poručuje o Allahovoj veličini? Kada se uči? (poslije svakog farz-namaza, prije spavanja, kao zaštita).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče ajet u dijelovima. Najboljima dajem priliku da prouče naučeni dio. Najavljujem nastavak učenja na sljedećem času.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> NAJVEĆI AJET U KUR'ANU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Vidjeli ste gore iznad naslov današnje lekcije. Znači, ne radi se o suri nego o samo jednom ajetu. Istina, nešto duljem ajetu. Ovaj ajet učimo napamet zbog mnogo razloga. Allahov poslanik, Muhammed, alejhis-selam, je kazao da je <span style=\"background-color: #fff9c4;\">Ajetu-l-kursijj najveći i najveličanstveniji ajet u cijelom Kur’anu</span>.</p>\n                <p class=\"lesson-text\">Ovaj ajet učimo u raznim prilikama. Posebno je važno i dobro da ga učimo prije spavanja jer je Muhammed, alejhis-selam, rekao da onome ko prouči ovaj ajet prije spavanja Allah dragi pošalje meleka čuvara da ga čuva dok ne svane. Meleke ne možemo vidjeti, ali znamo da postoje. Baš kao što ne možemo vidjeti prijateljstvo, ljubav ili poštovanje, a znamo da to postoji.</p>\n                <p class=\"lesson-text\">Allah dragi je stvorio ljude i životinje, ali je čovjeku dao nešto što nije dao drugim stvorenjima – <span style=\"background-color: #fff9c4;\">razum i pamet</span>. Zato je važno da se trudimo slušati i pamtiti ono što učimo. Muhammed, alejhis-selam, je kazao da postoje specijalni meleki čuvari koji idu čuvati muslimane i muslimanke tokom noći koji su proučili Ajetu-l-kursijju. Mi tog meleka ne možemo vidjeti, ali kao muslimani vjerujemo i znamo da je on tu s nama, u našoj sobi.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Ajetul-Kursija</span> je najuzvišeniji ajet u Kur'anu koji govori o Allahovom Prijestolju. Ajetul-Kursiju učimo kao zaštitu i traženje utočišta kod Uzvišenog Allaha. Ajetul-Kursija glasi:\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center; line-height: 2;\">\n                        E'ŪZU BILLĀHI MINEŠ-ŠEJTĀNIR-RADŽĪM<br>\n                        BISMILLĀHIR-RAHMĀNIR-RAHĪM<br><br>\n                        ALLĀHU LĀ-ILĀHE ILLĀ-HŪ, EL-HAJJUL-KAJJŪM.<br>\n                        LĀ TE'HUZUHŪ SINETUN VVE-LĀ NEVM.<br>\n                        LEHŪ MĀ FIS-SEMĀVĀTI VE MĀ FIL-ERD.<br>\n                        MEN ZELLEZĪ JEŠFE'U 'INDEHŪ ILLĀ BI IZNIH.<br>\n                        JA'LEMU MĀ BEJNE EJDĪHIM VE MĀ HALFEHUM.<br>\n                        VE LĀ JUHĪTŪNE BI ŠEJ'IN MMIN 'ILMIHĪ ILLĀ BI-MĀ ŠĀ'E.<br>\n                        VESI'A KURSIJJUHUS-SEMĀVĀTI VEL-ERD,<br>\n                        VE-LĀ JEŪDUHŪ HIFZUHUMĀ,<br>\n                        VE HUVEL-'ALIJJUL-'AZĪM.\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"text-align: center; margin-top: 20px;\">\n                    <span style=\"background-color: #fff9c4;\">PRIJEVOD:</span>\n                </p>\n\n                <p class=\"lesson-text\" style=\"text-align: center;\">\n                    TRAŽIM ALLAHOVU ZAŠTITU OD PROKLETOG ŠEJTANA<br>\n                    U IME ALLAHA, MILOSTIVOG, SAMILOSNOG!<br><br>\n                    ALLAH JE – NEMA BOGA OSIM NJEGA – ŽIVI I VJEČNI! NE OBUZIMA GA NI DRIJEMEŽ NI SAN! NJEGOVO JE ONO ŠTO JE NA NEBESIMA I ONO ŠTO JE NA ZEMLJI! KO SE MOŽE PRED NJIM ZAUZIMATI ZA NEKOGA BEZ DOPUŠTENJA NJEGOVA?! ON ZNA ŠTA JE BILO I PRIJE NJIH I ŠTA ĆE BITI POSLIJE NJIH, A OD ONOGA ŠTO ON ZNA – DRUGI ZNAJU SAMO ONOLIKO KOLIKO ON ŽELI. MOĆ NJEGOVA OBUHVATA I NEBESA I ZEMLJU I NJEMU NE DOJADI ODRŽAVANJE NJIHOVO; ON JE SVEVIŠNJI, VELIČANSTVENI!\n                </p>\n\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; border: 1px solid #f9f1a5; margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        Rekao je Muhammed, alejhis-selam: “Ko poslije svakog propisanog namaza prouči Ajetul-Kursiju samo ga smrt dijeli od ulaska u Džennet.” (Taberani)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('FINISH', this)\"> ZAPAMTI I PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"FINISH\" class=\"lesson-content\">\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; border: 1px solid #f9f1a5; margin-bottom: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">ZAPAMTI!</span><br>\n                        - AJETU-L-KURSIJJ JE NAJVELIČANSTVENIJI AJET U KUR'ANU<br>\n                        - OVAJ AJET SE UČI PRIJE SPAVANJA, POSLIJE SVAKOG NAMAZA I U RAZNIM PRILIKAMA<br>\n                        - OVAJ AJET JE, UZ SURU IHLAS, NAJBOLJI OPIS NAŠEG GOSPODARA\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\" style=\"margin-bottom: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">O SINKO MOJ! NAMAZ KLANJAJ. (Kur'an, Lukman, 17)</p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-bottom: 10px;\">\n                    <span style=\"background-color: #fff9c4;\">PITANJA:</span>\n                </p>\n                <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px;\">\n                    <p class=\"lesson-text\">1. Šta je Ajetul-Kursija?</p>\n                    <p class=\"lesson-text\">3. Kako glasi Ajetul-Kursija?</p>\n                    <p class=\"lesson-text\">2. Zašto učimo Ajetul-Kursiju?</p>\n                    <p class=\"lesson-text\">4. Kaži prijevod Ajetul-Kursije!</p>\n                </div>\n            </div>\n        </div>","audio_src":null,"redoslijed":59,"is_published":true,"kviz_pitanja":[{"answer":"Najuzvišeniji ajet u Kur'anu koji govori o Allahovom Prijestolju","options":["Najuzvišeniji ajet u Kur'anu koji govori o Allahovom Prijestolju","Dua koju čitamo prije spavanja","Poglavlje iz Kur'ana o ljudima","Molitva koju molimo samo u Ramazanu"],"question":"Što je Ajetul-Kursija?"},{"answer":"Na nebesima i na zemlji koje Allah posjeduje","options":["Samo na zemlji","Samo na nebesima","Na nebesima i na zemlji koje Allah posjeduje","U šumama i planinama"],"question":"Gdje živimo prema Ajetul-Kursiji?"},{"answer":"Ne obuzima ga drijemež ni san","options":["Ne vidi nas","Ne čini nas","Ne obuzima ga drijemež ni san","Ne voli nas"],"question":"Šta Allah prema Ajetul-Kursiji ne čini?"},{"answer":"Samo ga smrt dijeli od ulaska u Džennet","options":["Postaje bogat","Samo ga smrt dijeli od ulaska u Džennet","Očistit će se sve njegove greške","Postaje ponosan čovjek"],"question":"Što se događa onome ko čita Ajetul-Kursiju nakon svakog namaza?"},{"answer":"Živi i vječni","options":["Živi i vječni","Samo vječni i strogi","Samo živi ali nema moći","Nema moći i nije vječan"],"question":"Kakav je Allah prema Ajetul-Kursiji?"}]},{"nivo":1,"slug":"zikr","naslov":"Zikr poslije namaza","content_html":"<div class=\"lesson-container\">\n        <h1>ZIKR POSLIJE NAMAZA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/zikr.jpg\">\n        </div>","audio_src":null,"redoslijed":60,"is_published":true,"kviz_pitanja":[{"answer":"Sjećanje na Allaha i Njegovo spominjanje","options":["Sjećanje na Allaha i Njegovo spominjanje","Čitanje Kur'ana","Molitva pred nosom","Tišina u namazu"],"question":"Šta je zikr prema lekciji?"},{"answer":"Od Salavata, Ajetul-Kursije i Tesbiha","options":["Samo od Tesbiha","Od Salavata, Ajetul-Kursije i Tesbiha","Od dve sure Kur'ana","Od pet hodžinih učenja"],"question":"Od čega se sastoji zikr poslije namaza?"},{"answer":"33 puta","options":["10 puta","20 puta","33 puta","99 puta"],"question":"Koliko puta izgovaramo 'Subhānallāh' sa tespihom?"},{"answer":"Nakon predavanja posljednjeg selama","options":["Prije namaza","Tijekom namaza","Nakon predavanja posljednjeg selama","Kod kuće prije spavanja"],"question":"Kada počinjemo sa zikrom poslije namaza?"},{"answer":"U desnu ruku","options":["U lijevu ruku","U desnu ruku","U obje ruke","Ne trebamo tespih"],"question":"U koju ruku uzimamo tespih za zikr?"}]},{"nivo":1,"slug":"sura-en-nasr","naslov":"Sura En-Nasr","content_html":"<div class=\"lesson-container\">\n        <h1>SURA EN-NASR</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/nasr.jpg\">\n        </div>","audio_src":null,"redoslijed":61,"is_published":true,"kviz_pitanja":[{"answer":"U Medini","options":["U Mekki","U Medini","U Jerusalimu","U Egiptu"],"question":"Gdje je objavljena Sura En-Nasr?"},{"answer":"Pomoć","options":["Vjera","Pomoć","Pobjeda","Svetost"],"question":"Što znači reč 'Nasr'?"},{"answer":"Muhammeda a.s. uskoro umrijeti","options":["Dolazak novog poslanika","Muhammeda a.s. uskoro umrijeti","Otvaranje nove džamije","Kraj mjeseca Ramazana"],"question":"Što Sura En-Nasr najavljuje?"},{"answer":"Da ga hvalimo i tražimo oprost","options":["Da se ne moljimo","Da ga hvalimo i tražimo oprost","Da ne čitamo Kuran","Da ignoriramo vjeru"],"question":"Što Allah nas podsjeća u ovoj suri?"},{"answer":"A'ūdhu","options":["Tashahhud","Tawhid","A'ūdhu","Tazkirah"],"question":"Kako se naziva iskaz 'E'ūzu billāhi mineš-šejtānir-radžīm'?"}]},{"nivo":1,"slug":"bajramske-aktivnosti","naslov":"Bajramske aktivnosti polaznika mekteba","content_html":"<div class=\"lesson-container\">\n        <h1>BAJRAMSKE AKTIVNOSTI POLAZNIKA MEKTEBA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/bajram_priprema.jpg\">\n        </div>","audio_src":null,"redoslijed":62,"is_published":true,"kviz_pitanja":[{"answer":"Mnogo prije Bajrama","options":["Tri dana prije Bajrama","Mnogo prije Bajrama","Samo dan prije Bajrama","Nakon što Bajram počne"],"question":"Kada počnu pripreme za Bajram u mektebu?"},{"answer":"Bajramsku akademiju ilahija i recitacija","options":["Bajramsku akademiju ilahija i recitacija","Samo pjesme za djecu","Samo igre i zabavu","Samo islamsku knjižu"],"question":"Što mektebski hor priprema za Bajram?"},{"answer":"Uraditi veliki bajramski transparent","options":["Kupiti nove knjige","Uraditi veliki bajramski transparent","Napraviti novu pločicu","Pozvati sve učitelje"],"question":"Što bi trebalo da uradite za bajramsku akademiju?"},{"answer":"Bajramsko društenje","options":["Samo hrana za učitelje","Bajramsko društenje","Samo nove učionike","Samo Kuran"],"question":"Šta se priprema iz sredstava mektebskog fonda?"},{"answer":"Bolesnoj drugarici ili drugu","options":["Samo najboljim učenicima","Svim roditeljima","Bolesnoj drugarici ili drugu","Samo djevojčicama"],"question":"Kome trebate dati poseban bajramski dar?"}]},{"nivo":1,"slug":"sport","naslov":"Sport i rekreacija","content_html":"<div class=\"lesson-container\">\n        <h1>SPORT I REKREACIJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sport.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Sport i rekreacija</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike brige o tijelu i zdravlju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti odnos islama prema sportu i tjelesnoj aktivnosti</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje aktivnog načina života</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kojim se sportovima bavite? Volite li trčati, plivati, jahati? Šta mislite, šta islam kaže o sportu i kretanju?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Islam nas uči da je tijelo emanet (povjerenje) od Allaha i da o njemu trebamo brinuti.</p><p>Poslanik, a.s., preporučivao je svojim drugovima: gađanje strijelom, jahanje konja i plivanje – aktivnosti koje jačaju tijelo i pripremaju za život.</p><p>Sport i rekreacija nas čine zdravijim, jačim i vedrijim, ali pri tome ne smijemo zanemariti ibadete i obaveze.</p><p>Razgovor: Koje sportove vi volite? Kako možemo balansirati između sporta, učenja i namaza? Šta nije dozvoljeno (npr. okladovi, nasilje, nepristojna odjeća)?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju koristi sporta. Dogovaramo se da uz sport ne zaboravimo na namaz, učenje i lijepo ponašanje.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\"> ZDRAV DUH U ZDRAVOM TIJELU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <p class=\"lesson-text\">Vjera nas ne uči samo kako da hranimo svoju dušu, već i kako da čuvamo naše tijelo koje nam je Allah, dž.š., dao kao emanet – na čuvanje. Jeste li primijetili kako se bolje osjećate, kako lakše učite i kako ste sretniji nakon što se dobro iskačete, istrčite ili odigrate utakmicu sa prijateljima?</p>\n                <p class=\"lesson-text\">Sport nije samo zabava; on nas uči disciplini, timskom radu i poštovanju drugih. Naš Poslanik, alejhis-selam, bio je fizički jak i podsticao je ashabe da budu snažni i vješti. <span style=\"background-color: #fff9c4;\">Snažan vjernik je bolji i Allahu draži od slabog vjernika</span>, jer snaga tijela pomaže snazi duha u činjenju dobrih djela.</p>\n                <p class=\"lesson-text\">Bilo da volite fudbal, plivanje ili samo dugu šetnju prirodom, važno je da se krećete. Kroz sport učimo i kako da budemo strpljivi kada gubimo i skromni kada pobjeđujemo. Iskoristite svaku priliku u mektebu i školi da se bavite sportom i tako zahvalite Allahu na blagodati zdravlja koju vam je darovao.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Svemogući Allah je stvorio naše duše i tijela i sjedinio ih u našim životima na Zemlji. Njemu zahvaljujemo na darovima života i čuvamo svoje zdravlje. Vjerom oplemenjujemo dušu a tijelo održavamo radom, sportom i zdravim navikama.</p>\n                \n                <div style=\"text-align: center; margin: 20px 0;\">\n                    <img src=\"/edu/assets/images/streljastvo.jpg\" style=\"width: 100%; max-width: 400px; height: auto;\">\n                </div>\n\n                <p class=\"lesson-text\">Sport promovira zdravlje, naš fizički i duhovni odgoj. Takmičarski duh kroz sport povezuje nas i zbližava. Ko se bavi sportom ne ljuti se čak i kada ne pobijedi.</p>\n                \n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">Islam podstiče bavljenje mnogim sportovima: trčanjem, plivanjem, streljaštvom i jahanjem. Zdrava osoba lakše izvršava vjerske obaveze. Vjerski propisi pomažu nam u održavanju dobre kondicije i čuvaju naše zdravlje.</p>\n\n                <div style=\"text-align: center; margin: 20px 0;\">\n                    <img src=\"/edu/assets/images/jahanje.jpg\" style=\"width: 100%; max-width: 400px; height: auto;\">\n                </div>\n\n                <p class=\"lesson-text\">U mektebu imamo sportske aktivnosti i mektebska sportska takmičenja.</p>\n\n                <div style=\"background-color: #fff9c4; padding: 15px; border-radius: 10px; border: 1px solid #f9f1a5; margin-top: 20px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        Rekao je Muhammed, alejhis-selam:<br>\n                        <span style=\"background-color: #fff9c4;\">\"...Tvoje tijelo ima prava kod tebe...\"</span> (Muttefekun 'alejh)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\"> PITANJA ZA RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    1. Kako nas je stvorio Svemogući Allah?<br>\n                    2. Čime oplemenjujemo dušu i kako održavamo tijelo?<br>\n                    3. Koje sportove islam podstiče?<br>\n                    4. Šta je rekao Muhammed, alejhis-selam, za naša tijela?<br>\n                    5. Opiši svoje sportske aktivnosti!\n                </p>\n            </div>\n        </div>","audio_src":null,"redoslijed":63,"is_published":true,"kviz_pitanja":[{"answer":"Duše i tijela","options":["Samo duše","Duše i tijela","Samo tijela","Srce i mozak"],"question":"Šta je stvorio Svemogući Allah za ljude?"},{"answer":"Vjerom","options":["Vjerom","Sportom","Jilom","Putovanjem"],"question":"Čime oplemenjujemo našu dušu prema tekstu?"},{"answer":"Jahanje, streljašstvo, trčanje i plivanje","options":["Jahanje, streljašstvo, trčanje i plivanje","Samo fudbal","Samo tenis","Samo košarka"],"question":"Koje od ovih sportova islam podstiče?"},{"answer":"Nas povezuje i zbližava","options":["Ga uništava","Nas povezuje i zbližava","Nas razdvaja","Ga smanjuje"],"question":"Šta sport čini sa takmičarskim duhom?"},{"answer":"Zdrava osoba","options":["Bolesna osoba","Tužna osoba","Zdrava osoba","Umorni čovjek"],"question":"Ko lakše izvršava vjerske obaveze?"}]},{"nivo":2,"slug":"sehvi-sedzda","naslov":"Sehvi-sedžda","content_html":"<div class=\"lesson-container\">\n<h1>SEHVI-SEDŽDA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/sehvi_sedzda.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Sehvi-sedžda</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje strpljenja i pažnje u namazu te svijesti da se Allahu vraćamo i kada pogriješimo</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je sehvi-sedžda, kada se obavlja i kako se ispravno čini</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobljavanje učenika da samostalno učine sehvi-sedždu kada zaborave dio namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li se ikada desilo da u namazu zaboravite koji ste rekat klanjali ili preskočite sjedenje? Allah je dao olakšicu – sehvi-sedždu. Danas učimo kako se ispravlja namaz.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sehvi-sedžda znači sedžda zbog zaborava i obavlja se kada se u namazu vadžib propusti, izostavi ili učini nepotrebno.</p><p>Obavlja se na sljedeći način: nakon posljednjeg sjedenja predaje se selam samo na desnu stranu, zatim se učine dvije sedžde, prouči se tešehhud, salavati i dove, te se preda selam na obje strane.</p><p>Najčešći razlozi: zaborav Učenja Fatihe na prva dva rekata, zaborav prvog sjedenja, propuštanje kunut-dove na vitru, ili zaborav drugog rekata sure.</p><p>Postupak: Crtam na tabli sliku rekata namaza i pokazujem gdje se javlja propust i kako se on ispravlja sehvi-sedždom. Učenici praktično pokazuju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Kratak razgovor: Šta je sehvi-sedžda? Kada se obavlja? Učenici odgovaraju i ponavljaju postupak.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":13,"is_published":true,"kviz_pitanja":[{"answer":"Naknadna sedžda koja se čini da se ispravi greška","options":["Naknadna sedžda koja se čini da se ispravi greška","Sedžda na početku namaza","Obavezna sedžda u svakom namazu","Sedžda samo za žene"],"question":"Šta je sehvi-sedžda?"},{"answer":"Poslije selama na desnu stranu","options":["Na početku namaza","Poslije selama na desnu stranu","Prije ruku-a","Za vrijeme Kunut-dove"],"question":"Kada se čini sehvi-sedžda?"},{"answer":"Dvije sedžde","options":["Jednu sedždu","Tri sedžde","Dvije sedžde","Četiri sedžde"],"question":"Koliko sedždi sadrži sehvi-sedžda?"},{"answer":"Da, može ispraviti više grešaka","options":["Ne, samo jednu grešku","Da, može ispraviti više grešaka","Samo dvije greške","Ne zna se"],"question":"Može li jedna sehvi-sedžda ispraviti više grešaka?"},{"answer":"Ponovo sjediti i pročitati Et-Tehijat","options":["Odmah predati selam","Ponovo sjediti i pročitati Et-Tehijat","Klanjati dodatni rakat","Nema dodatnih radnji"],"question":"Šta treba učiniti nakon dvije sehvi-sedžde?"}]},{"nivo":2,"slug":"prispijevanje","naslov":"Prispijevanje u džemat","content_html":"<div class=\"lesson-container\">\n<h1>PRISPIJEVANJE U DŽEMAT</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/prispijevanje.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Prispijevanje u džemat</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema zajedničkom namazu i poštivanje džemata</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pravila prispijevanja u džemat – kada se zatekne imam u različitim dijelovima namaza</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da se ispravno priključi džematu i upotpuni propušteni dio namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta uradite kada uđete u džamiju, a imam već klanja? Da li samo stanete sa strane ili se priključite? Danas učimo pravila prispijevanja u džemat.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Onaj ko stigne u džemat dok je imam u kijamu, na rukuu ili sjedenju – učini nijet, donese tekbir i priključi se imamu u onom položaju u kojem ga je zatekao.</p><p>Ako stigne dok je imam na rukuu i klanjač uhvati ruku sa imamom – smatra se da je ulovio cijeli rekat.</p><p>Nakon imamovog selama, klanjač ustaje i upotpunjava propuštene rekate – sam donosi sure i zikrove kao da klanja od početka.</p><p>Postupak: Postavljam različite scenarije (zatečen u sedždi, na sjedenju, na rukuu) i učenici demonstriraju kako bi se priključili. Razgovor o tome zašto je važno doći u džemat na vrijeme.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam: Šta uraditi kada se zatekne imam na rukuu? A kada na sjedenju? Učenici odgovaraju i ponavljaju ključna pravila.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":16,"is_published":true,"kviz_pitanja":[{"answer":"Uhvatiti ruku' s jednim subhane rabbijel-azim","options":["Uhvatiti ruku' s jednim subhane rabbijel-azim","Klanjati sve rekate sami prije imama","Stajati iza imama bez klanjanja","Izgovoriti tekbir na početku namaza"],"question":"Šta znači 'uhvatiti rekat' u džematu?"},{"answer":"Sunnete","options":["Sunnete","Sve rekate","Selam nakon namaza","Stajanje u sfu"],"question":"Šta trebamo izostaviti kada kasno dođemo u džamiju?"},{"answer":"Nikad, čekamo da imam počne predavati","options":["Nikad, čekamo da imam počne predavati","Odmah kad dođemo u džamiju","Kada imam završi sjedenje","Samo na desnu stranu"],"question":"Kada predajemo selam zajedno s imamom u džematu?"},{"answer":"Sjedenje","options":["Sjedenje","Predavanje selama","Izlaženje iz džamije","Ponavljanje tekbira"],"question":"Šta je obavezno послije svakih dva naklanjana rekata?"},{"answer":"Da, imamo nagradu džemata","options":["Da, imamo nagradu džemata","Ne, jer smo kasno stigli","Samo pola nagrade","Moramo naklanjavati dodatne rekate"],"question":"Ako stignemo prije nego što imam preda selam, imamo li nagradu?"}]},{"nivo":2,"slug":"cistoca","naslov":"Čistoća i lična higijena","content_html":"<div class=\"lesson-container\">\n<h1>ČISTOĆA I LIČNA HIGIJENA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/čistoća.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Čistoća i lična higijena</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike čistoće tijela, odjeće i okoline kao dijela imana</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa značajem čistoće u islamu i osnovama lične higijene</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svakodnevnih navika održavanja čistoće</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta sve radite svaki dan da biste bili čisti? Pranje ruku, pranje zuba, kupanje... A znate li šta je Poslanik, a.s., rekao za čistoću?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanik, a.s., je rekao: <em>\"Čistoća je pola imana.\"</em> Time nas uči da musliman uvijek treba biti čist.</p><p>Lična higijena obuhvata: redovno pranje ruku prije i poslije jela, pranje zuba, kupanje, čišćenje noktiju, češljanje kose i čistu odjeću.</p><p>Čistoća tijela je uslov ibadeta – bez čistoće nema namaza, nema učenja Kur’ana iz mushafa.</p><p>Razgovor: Kada se peremo prije namaza? (uzimanje abdesta) Šta sve treba čistiti? (tijelo, odjeća, mjesto na kojem klanjamo)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju navike čistoće koje će svaki dan obavljati. Zaključujemo da je čistoća dio našeg imana i ponašanja.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":21,"is_published":true,"kviz_pitanja":[{"answer":"One koji se često kaju i mnogo čiste","options":["One koji se često kaju i mnogo čiste","One koji manje rade","One koji dugo spavaju","One koji se ne kupaju"],"question":"Šta Allah, dž.š., voli prema El-Bekari 222?"},{"answer":"Voda","options":["Voda","Krv","Urin","Gnoj"],"question":"Koja od sljedećih nije osnovne nečistoće?"},{"answer":"Abdestiti se ili umiti i oprati zube","options":["Abdestiti se ili umiti i oprati zube","Samo se okrenuti u krevetu","Odmah pojesti doručak","Obuti cipele"],"question":"Šta treba da uradiš svakog jutra za ličnu higijenu?"},{"answer":"Poslije nužde","options":["Poslije nužde","Samo vikendom","Samo prije spavanja","Nikad nije važno"],"question":"Kada trebaš oprati ruke sa sapunom prema lekciji?"},{"answer":"Čistoću stana, dvorišta i okoline","options":["Čistoću stana, dvorišta i okoline","Samo bicikl","Samo knjige","Samo igračke"],"question":"Pored lične higijene, šta još trebaš čuvati?"}]},{"nivo":2,"slug":"ishrana","naslov":"Zdrava ishrana","content_html":"<div class=\"lesson-container\">\n<h1>ZDRAVA ISHRANA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/ishrana.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Zdrava ishrana</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje zahvalnosti Allahu na hrani i odgovornog odnosa prema vlastitom zdravlju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti učenike šta je halal i zdrava ishrana te koju hranu islam preporučuje</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike biranja zdrave i halal hrane</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta volite jesti? A da li znate da postoji hrana koja je za muslimane dozvoljena (halal) i ona koja nije (haram)? Šta je zdrava hrana?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah je u Kur’anu rekao: <em>\"Jedite od onoga što vam je dozvoljeno i ono što je čisto.\"</em></p><p>Halal hrana je sva hrana koja je islamskim propisima dozvoljena: voće, povrće, žitarice, mlijeko, riba, meso zaklane stoke (osim svinje).</p><p>Haram je: svinjsko meso, krv, lešina, alkohol i sve što je ovisnost.</p><p>Zdrava ishrana znači: jesti raznovrsno, ne pretjerivati, manje slatkiša i grickalica, više voća i povrća, dovoljno vode.</p><p>Poslanik, a.s., je rekao: <em>\"Ne ispunite stomak više od trećine hranom, trećine vodom i trećinu ostavite za disanje.\"</em></p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju zdravu hranu koju vole. Razgovor o tome šta će promijeniti u svojim navikama (više voća, manje slatkiša).</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">HRANA KAO ALLAHOVA BLAGODAT <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Svaki put kada sjednemo za sofru, pred nama je nešto nevjerovatno: hljeb napravljen od zrnevlja koje je nicalo iz zemlje, mlijeko koje je darovala životinja, med koji su prikupile pčele, voće i povrće koje je sazrijevalo pod Allahovim suncem. Sve to je tu – za nas, besplatno, svaki dan. Allah, dž.š., je stvorio čovjeka i podario mu mnogobrojna blagodati, a među najznačajnijim su hrana, voda i zrak. Da bismo sačuvali blagodat zdravlja, trebamo paziti na zdravu ishranu. Islam nas uči ne samo šta smijemo jesti, nego i kako i koliko. Musliman gleda na hranu kao sredstvo za očuvanje života i zdravlja – ona mu daje snagu za ibadet i životne aktivnosti. Nije hrana cilj sam po sebi, nego je sredstvo da ostanemo živi, zdravi i sposobni za ibadete. Zato postoje jasna pravila o halal hrani i umjerenosti u jelu.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p>Allah, dž.š., kaže: I jedite i pijte, samo ne pretjerujte, jer On ne voli one koji pretjeruju. (El-A'rāf, 31)</p></div><p>Allah, dž.š., je stvorio čovjeka i podario mu mnogobrojna blagodati kojima se koristi u životu na ovom svijetu. Među najznačajnijim blagodatima su: hrana, voda i zrak. Pored spomenutih blagodati koje su nam darovane, Allah, dž.š., nam je podario i zdravlje.</p><p>Da bismo čuvali blagodat zdravlja, potrebno je prije svega da pazimo na zdravu ishranu. To znači da trebamo jesti raznovrsnu, lijepu i ukusnu hranu, koju nam je dozvolio Allah, dž.š., a koja treba da sadrži sve potrebne sastojke za organizam – mlijeko i mliječne proizvode, med, žitarice, voće i povrće, meso.</p><p>Islam nas uči da je prekomjerno uzimanje hrane zabranjeno i štetno, jer narušava čovjekovo zdravlje, uzrokuje velike probleme i izvor je mnogih neugodnosti. U današnjem vremenu mnogo je ljudi koji boluju od gojaznosti a to je direktna posljedica pretjerivanja u ishrani.</p><p>Nezdrava hrana uzrok je velikog broja bolesti koje su danas rasprostranjene u svijetu. Zbog toga svaki musliman zna da konzumiranjem halal-hrane u umjerenim količinama, čuva svoje zdravlje i zaštićen je od mnogih bolesti.</p><p>Islam je posebno zabranio sljedeće vrste hrane i pića jer štete njegovom zdravlju:</p><ul><li><p>svinjsko meso, svinjsku mast i proizvode i prerađevine od svinjetine,</p></li><li><p>meso uginulih životinja,</p></li><li><p>meso svih deraćih životinja, gmizavaca i glodara,</p></li><li><p>krv,</p></li><li><p>pijenje alkoholnih pića.</p></li></ul><p>Uzvišeni Allah još je zabranio i:</p><ul><li><p>upotrebu opojnih sredstava,</p></li><li><p>prekomjerno jedenje bilo koje vrste hrane, pa i one koja je halal.</p></li></ul><p>Musliman gleda hranu kao sredstvo za očuvanje života i zdravlja, koje mu omogućava da Uzvišenom Allahu čini ibadet i ima snage za životne aktivnosti. Zato musliman ne treba jesti dok ne ogladni i ne treba piti dok ne ožedni.</p><p>U tom smislu su riječi Muhammeda, alejhis-selam: <em>„Čovjek goru posudu od stomaka neće napuniti...\"</em> (Ahmed)</p><div class=\"info-box\"><p><strong>Namirnice spomenute u Kur'anu:</strong> med, smokve, masline, grožđe, voda, mlijeko, hurme, nar, crveni luk, leća, pšenica, krastavci, banana i tikva.</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – ZDRAVA ISHRANA</h2>\n                <div id=\"question-container\">\n                    <p class=\"quiz-question\" id=\"q-text\"></p>\n                    <div class=\"quiz-options\" id=\"q-options\"></div>\n                </div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p class=\"lesson-text\" style=\"font-weight:bold;\">PITANJA I ZADACI</p>\n    <ol class=\"lesson-text\">\n        <li>Koje su najznačajnije blagodati koje nam je Allah, dž.š., podario?</li>\n        <li>Na koji način ishranom čuvamo svoje zdravlje?</li>\n        <li>Šta kaže Allah, dž.š., o prekomjernom uzimanju hrane?</li>\n        <li>Šta je od hrane i pića Allah, dž.š., zabranio?</li>\n        <li>ZADATAK: Nacrtaj tabelu u svesku i stavi znak x u odgovarajuće polje. Kada dobiješ rezultate, uporedi ih sa svojim prijateljem ili prijateljicom i zajednički donesite zaključak koliko ko čuva svoje zdravlje.\n            <br><br>\n            <table class=\"lesson-text\" style=\"border-collapse:collapse; width:100%;\">\n                <tbody><tr style=\"background:#f0fdf4;\"><th style=\"border:1px solid #ccc;padding:6px;\">Djela</th><th style=\"border:1px solid #ccc;padding:6px;\">Uvijek</th><th style=\"border:1px solid #ccc;padding:6px;\">Često</th><th style=\"border:1px solid #ccc;padding:6px;\">Ponekad</th><th style=\"border:1px solid #ccc;padding:6px;\">Nikad</th></tr>\n                <tr><td style=\"border:1px solid #ccc;padding:6px;\">Jedem slatkiše i brzu hranu (sendviče, ćevape...)</td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td></tr>\n                <tr><td style=\"border:1px solid #ccc;padding:6px;\">Jedem mliječne proizvode</td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td></tr>\n                <tr><td style=\"border:1px solid #ccc;padding:6px;\">Provjeravam sastojke u proizvodima koje kupujem</td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td></tr>\n                <tr><td style=\"border:1px solid #ccc;padding:6px;\">Ne provjeravam sastojke u hrani koju kupujem</td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td></tr>\n                <tr><td style=\"border:1px solid #ccc;padding:6px;\">Pijem gazirane sokove</td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td><td style=\"border:1px solid #ccc;padding:6px;\"></td></tr>\n            </tbody></table>\n        </li>\n    </ol>\n    <div class=\"info-box\" style=\"margin-top:16px;\">\n        <p class=\"lesson-text\"><strong>RAZGOVOR S MUALLIMOM</strong><br>Kada i zašto musliman konzumira hranu i piće?</p>\n    </div>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":23,"is_published":true,"kviz_pitanja":[{"answer":"Jedite i pijte, samo ne pretjerujte","options":["Jedite koliko god želite","Jedite i pijte, samo ne pretjerujte","Ne smijete jesti meso","Hrana je zabranjena u islamu"],"question":"Šta Allah, dž.š., kaže u ajetu o hrani i piću?"},{"answer":"Svinjsko meso","options":["Med","Smokve","Svinjsko meso","Hurme"],"question":"Koje od sljedećih namirnica je islamski zabranjeno?"},{"answer":"Pijenje alkoholnih pića","options":["Vodu","Pijenje alkoholnih pića","Voće","Povrće"],"question":"Šta je islam posebno zabranio pored hrane?"},{"answer":"Gojaznost","options":["Poboljšanje zdravlja","Gojaznost","Brža rast","Veća snaga"],"question":"Koja je direktna posljedica pretjerivanja u ishrani?"},{"answer":"Kao sredstvo za očuvanje zdravlja","options":["Kao zabavu","Kao sredstvo za očuvanje zdravlja","Kao kaznu","Kao igru"],"question":"Kako musliman gleda na hranu?"}]},{"nivo":2,"slug":"ponasanje-jela","naslov":"Ponašanje prilikom jela","content_html":"<div class=\"lesson-container\">\n<h1>PONAŠANJE PRILIKOM JELA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/ponasanje_jela.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ponašanje prilikom jela</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje lijepog ponašanja, zahvalnosti i poštivanja sunneta Poslanika, a.s.</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pravila lijepog ponašanja prilikom jela po islamskim propisima</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika sunnetskog ponašanja za sofrom</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako se ponašate kada sjednete za sofru? Šta kažete prije nego počnete jesti? Hajde da naučimo kako su Poslanik, a.s., i ashabi jeli.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Prije jela: oprati ruke, sjesti pristojno, proučiti Bismillu.</p><p>Tokom jela: jesti desnom rukom, uzimati hranu ispred sebe, ne puhati u vruću hranu, ne kritikovati hranu.</p><p>Jesti umjereno – ne pretjerivati, jer Poslanik, a.s., je rekao da je najgora posuda koju čovjek napuni svoj stomak.</p><p>Poslije jela: proučiti dovu zahvale, oprati ruke i pospremiti za sobom.</p><p>Postupak: Demonstriram pravilno sjedenje, postavljam pitanja \"šta bi sad bilo lijepo uraditi\", učenici nabrajaju adabe.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju adabe jela. Pitam ih koji adab smatraju najvažnijim i zašto.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":24,"is_published":true,"kviz_pitanja":[{"answer":"Spomeni Allahovo ime, jedi desnom rukom i ispred sebe","options":["Jedi lijevom rukom i brzo","Spomeni Allahovo ime, jedi desnom rukom i ispred sebe","Jedi sam i tiho","Jedi toplinu hranu i puno"],"question":"Šta je Poslanik, alejhis-selam, rekao Omeru b. Selemi o jelu?"},{"answer":"Trebamo ih obavezno operemo","options":["Trebamo ih zagrijati vodom","Trebamo ih osušiti na odjeću","Trebamo ih obavezno operemo","Trebamo ih mazati uljem"],"question":"Šta treba da uradimo sa rukama prije jela?"},{"answer":"Hrana mora biti halal i počnemo sa Bismillom","options":["Hrana mora biti topla i skupo","Hrana mora biti halal i počnemo sa Bismillom","Hrana mora biti od mesa samo","Hrana mora biti zaslađena i obila"],"question":"Koja su važna pravila prije nego počnemo jelo?"},{"answer":"Domaćin ili najstariji član porodice","options":["Najmlađu dijete u kući","Onaj ko je najgluplji","Domaćin ili najstariji član porodice","Onaj ko je najgladniji"],"question":"Ko bi trebao prvi početi sa jelom po islamu?"},{"answer":"El-hamdu lillah – Hvala Allahu!","options":["Subhanallah i Alhamdulillah","El-hamdu lillah – Hvala Allahu!","Allahu Akbar tri puta","Mashallah i Inshallah zajedno"],"question":"Šta trebamo reći nakon jela kao zahvalu Allahu?"}]},{"nivo":2,"slug":"dova-poslije-jela","naslov":"Učenje dove poslije jela","content_html":"<div class=\"lesson-container\">\n<h1>UČENJE DOVE POSLIJE JELA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/dova_poslije_jela.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje dove poslije jela</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje zahvalnosti Allahu na blagodati hrane i pića</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti dovu koja se uči poslije jela i razumjeti njeno značenje</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike učenja dove zahvale nakon svakog obroka</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kome se zahvaljujemo kada nam neko da poklon? A kada nas Allah hrani – kako Mu se zahvaljujemo? Postoji posebna dova koju je Poslanik, a.s., učio.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Dova poslije jela: <em>El-hamdu lillāhi-llezī at‘amenā ve sekānā ve dže‘alenā minel-muslimīn</em> – Hvala Allahu koji nas je nahranio i napojio i učinio muslimanima.</p><p>Ova dova se uči nakon svakog obroka, glasno ili u sebi.</p><p>Značenje: zahvaljujemo Allahu na hrani, na vodi i na najvećoj blagodati – islamu.</p><p>Postupak: Pišem dovu na tabli arapskim pismom i transkripcijom. Učimo izgovor riječ po riječ. Razgovaramo o značenju svake riječi. Učenici glasno ponavljaju u horu i pojedinačno.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici proučavaju dovu nekoliko puta zajedno. Domaća zadaća: učiti dovu poslije svakog obroka i naučiti je napamet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">ZAHVALA ZA SVAKI ZALOGAJ <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Zamislite da vam neko svaki dan spremi ručak, bez ijedne zamjerke, bez ijednog izostanka – cijeli život. Šta biste učinili? Sigurno biste zahvalili. Allah, dž.š., nam svaki dan daje hranu, vodu i sve što nam treba za život – i On od nas traži samo jedno: zahvalnost. Dova poslije jela je ta zahvalnost. Nije duga, nije teška – ali ona mijenja naš odnos prema hrani. Svaki zalogaj postaje svjestan čin, a ne puka navika. Muslimani i muslimanke zahvaljuju Allahu, dž.š., na svakom stanju koje im odredi – pa to čine i poslije jela zbog opskrbe koju im je On darovao. Naučiti dovu poslije jela i redovno je učiti – to je sunnet koji možemo primijeniti već danas.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p>Allah, dž.š., kaže: O vjernici, jedite ukusna jela koja smo vam podarili i budite Allahu zahvalni, ta vi se samo Njemu klanjate! (El-Bekare, 172)</p></div><p>Muslimani i muslimanke zahvaljuju Allahu, dž.š., na svakom stanju koje im odredi pa to čine i poslije jela zbog opskrbe koju im je On darovao. Lijepo je proučiti sljedeću dovu poslije jela:</p><p>Poslanik, alejhis-selam, je zahvaljivao Allahu, dž.š., poslije jela, a i nama je preporučio da učimo dovu. Nije uvjet da dova bude na arapskom jeziku – Uzvišenom Allahu možemo se zahvaliti i na bosanskom jeziku.</p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>DOVA POSLIJE JELA:</strong><br><br>BISMILLĀHIR-RAHMĀNIR-RAHĪM<br>KULŪ VEŠREBŪ VE LĀ TUSRIFŪ, INNEHŪ LĀ JUHIBBUL-MUSRIFĪN.<br>EL-HAMDU LILLĀHIL-LEZĪ AT'AMENĀ VE SEḲĀNĀ VE DŽE'ALENĀ MINEL-MUSLIMĪN.<br><br><strong>Prijevod:</strong><br>U IME ALLAHA, MILOSTIVOG, SAMILOSNOG. I JEDITE I PIJTE, SAMO NE PRETJERUJTE; ON NE VOLI ONE KOJI PRETJERUJU. HVALA ALLAHU KOJI NAM JE DAO HRANU I VODU, I KOJI NAS JE UČINIO MUSLIMANIMA.</p></div><div class=\"info-card\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong></p><p style=\"text-align: center;\">Ako zaboravimo proučiti Bismillu prije jela, kada se sjetimo, proučit ćemo: <strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Bismillahi fi</mark></strong></p><p style=\"text-align: center;\"><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">evvelihi ve ahirihi</mark></strong> ‒ sa Allahovim imenom počinjem i završavam.</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – UČENJE DOVE POSLIJE JELA</h2>\n                <div id=\"question-container\">\n                    <p class=\"quiz-question\" id=\"q-text\"></p>\n                    <div class=\"quiz-options\" id=\"q-options\"></div>\n                </div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p class=\"lesson-text\" style=\"font-weight:bold;\">PITANJA I ZADACI</p>\n    <ol class=\"lesson-text\">\n        <li>Napiši i nauči dovu poslije jela na arapskom i bosanskom jeziku.</li>\n        <li>Zašto muslimani uče dovu poslije jela?</li>\n        <li>Da li dova mora biti na arapskom jeziku?</li>\n    </ol>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":25,"is_published":true,"kviz_pitanja":[{"answer":"Da budu zahvalni Allahu","options":["Da budu zahvalni Allahu","Da odmoraju sat vremena","Da izađu vani","Da čitaju Kur'an"],"question":"Šta Allah nalaže muslimanima da čine poslije jela?"},{"answer":"Poslanik Muhammad, alejhis-selam","options":["Poslanik Muhammad, alejhis-selam","Kalif Ali","Sahaba Bilal","Učeni ulema"],"question":"Ko je prvi učio dovu poslije jela?"},{"answer":"Ne, može biti i na bosanskom jeziku","options":["Ne, može biti i na bosanskom jeziku","Da, obavezno na arapskom","Samo za odrasle na arapskom","Samo vikendi na bosanskom"],"question":"Da li dova mora biti na arapskom jeziku?"},{"answer":"One koji pretjeruju","options":["One koji pretjeruju","One koji su mirni","One koji su poniznI","One koji se zahvaljuju"],"question":"Šta Allah ne voli prema dovi poslije jela?"},{"answer":"Za hranu, vodu i islam","options":["Za hranu, vodu i islam","Za novac i bogatstvo","Za ljepotu i snagu","Za brzinu i inteligenciju"],"question":"Za što se zahvaljujemo Allahu u dovi poslije jela?"}]},{"nivo":2,"slug":"braca-sestre","naslov":"Pažnja prema sestrama i braći","content_html":"<div class=\"lesson-container\">\n<h1>PAŽNJA PREMA SESTRAMA I BRAĆI</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/braca_sestre.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Pažnja prema sestrama i braći</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi, pažnje i poštovanja prema braći i sestrama u porodici</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti značaj porodičnih veza i obaveze koje imamo prema braći i sestrama</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike pomaganja, dijeljenja i lijepog ponašanja unutar porodice</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko ima brata ili sestru? Kako se odnosite prema njima? Da li se ponekad svađate? Hajde da razgovaramo zašto je važno dobro se odnositi prema braći i sestrama.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Braća i sestre su nam najveći Allahov dar nakon roditelja. Sa njima dijelimo dom, igre i život.</p><p>Naša obaveza je da ih volimo, čuvamo, branimo i pomažemo im, posebno mlađima.</p><p>Stariji treba da budu primjer mlađima, a mlađi da poštuju starije.</p><p>Poslanik, a.s., je rekao: <em>\"Niko od vas neće biti pravi vjernik dok ne bude želio bratu svome ono što želi i sebi.\"</em></p><p>Razgovor: Kako pomažem bratu/sestri? Šta uraditi kada se posvađamo? (oprostiti, izviniti se, ne ljutiti se dugo)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici opisuju jedno lijepo djelo koje će uraditi za brata ili sestru ovaj tjedan. Zajedno učimo dovu za braću i sestre.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":27,"is_published":true,"kviz_pitanja":[{"answer":"Pokazati dobročinstvo i pažnju","options":["Samo slušati što kažu","Pokazati dobročinstvo i pažnju","Samo se igrati s njima","Biti im strogi"],"question":"Šta Allah, dž.š., kaže da trebamo činiti prema članovima porodice?"},{"answer":"Ih paziti, štititi i učiti","options":["Ih slušati i poštovati","Ih paziti, štititi i učiti","Ih izbjegavati","Biti im ravnodušan"],"question":"Koja je obaveza prema mlađoj braći i sestrama?"},{"answer":"Ih slušati, poštovati i pitati za savjet","options":["Ih zanemarivati","Ih slušati, poštovati i pitati za savjet","Ih kritizirati","Biti im nepristojni"],"question":"Što trebamo činiti sa starijom braćom i sestrama?"},{"answer":"Dvije vrste","options":["Samo jedna vrsta","Tri vrste","Dvije vrste","Četiri vrste"],"question":"Koliko vrsta srodstva postoji prema islamskim propisima?"},{"answer":"Ljubav, poštovanje i zadovoljstvo Allaha","options":["Samo ljutnju roditelja","Ljubav, poštovanje i zadovoljstvo Allaha","Srama i poniženja","Bolest i tugu"],"question":"Šta dobijamo izvršavajući obaveze prema braći i sestrama?"}]},{"nivo":2,"slug":"namaz-cuva","naslov":"Namaz čuva i odgaja","content_html":"<div class=\"lesson-container\">\n<h1>NAMAZ ČUVA I ODGAJA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/namaz_cuva.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Namaz čuva i odgaja</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema namazu i svijesti o njegovom odgojnom utjecaju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti kako namaz čuva čovjeka od loših djela i odgaja ga</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje navike redovnog klanjanja namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta nas može odvratiti od loših djela? Allah u Kur’anu kaže da to čini namaz. Kako jedan ibadet može odgajati i čuvati čovjeka? Danas otkrivamo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah u Kur’anu kaže: <em>\"Namaz, doista, odvraća od razvrata i svega što je ružno.\"</em></p><p>Onaj ko klanja pet puta dnevno, uvijek je u kontaktu sa Allahom – to ga čuva da ne čini grijehe.</p><p>Namaz odgaja: uči nas tačnosti (vremena namaza), čistoći (abdest), pokornosti, strpljivosti i poniznosti.</p><p>Onaj ko propušta namaz – udaljava se od Allaha i lakše čini loša djela.</p><p>Razgovor: Kako se osjećate kada klanjate namaz? Šta vam pomaže da redovno klanjate?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju kako ih namaz čini boljim. Donosimo zaključak: ko čuva namaz – Allah čuva njega.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":30,"is_published":true,"kviz_pitanja":[{"answer":"Namaz odvraća od razvrata i svega ruznog","options":["Namaz odvraća od razvrata i svega ruznog","Namaz je teško za sve muslimane","Namaz se obavlja samo pet dana","Namaz nije obavezan za djecu"],"question":"Šta kaže Allah u ajetu El-Ankebut 45 o namazу?"},{"answer":"Kao rijeka u kojoj se pet puta kupamo","options":["Kao rijeka u kojoj se pet puta kupamo","Grišeće se opraštaju jednom godišnje","Samo ako je namaz savršen bez greške","Nije povezan sa našim grijehima"],"question":"Kako se namaz odnosi prema našim grijehima?"},{"answer":"Tačnost, preciznost, organizovanost i aktivnost","options":["Tačnost, preciznost, organizovanost i aktivnost","Samo fizičku snagu i brzinu","Samo duhovnu moć bez rada","Samo pamćenje i inteligenciju"],"question":"Koje osobine namaz razvija u nama?"},{"answer":"Namaz","options":["Namaz","Sadaka i milostinya","Dobra djela prema roditeljima","Poznavanje Kurana"],"question":"Šta je prvi put za što će čovjek biti pitan na Sudnjem danu?"},{"answer":"U ajetu Ta-Ha 132 gdje se kaže naredi svojoj porodici","options":["U ajetu Ta-Ha 132 gdje se kaže naredi svojoj porodici","Samo kada djecu dostignu devet godina","Kada god roditelj misli da je vrijeme","Namaz se nikada ne naredi djeci"],"question":"Kada je Allah naredio da se djeci ukazuje na namaz?"}]},{"nivo":2,"slug":"mesh","naslov":"Mesh po mestvama i zavoju","content_html":"<div class=\"lesson-container\">\n<h1>MESH PO MESTVAMA I ZAVOJU</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/mesh.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Mesh po mestvama i zavoju</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o Allahovim olakšicama i prihvatanju olakšica koje je On dozvolio</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je mesh, kako se uzima, koliko traje i kada se pokvari</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da samostalno uzme mesh kada je u potrebi</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta da uradi neko ko ima nogu u gipsu i ne može je oprati? Šta da uradi onaj ko nosi mestve po hladnoći? Allah je dao olakšicu – mesh.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mesh znači potirati vlažnom rukom po mestvama (kožnim čarapama) ili po zavoju umjesto pranja nogu pri abdestu.</p><p>Uslovi: mestve moraju biti čiste, obučene na čiste oprane noge, da pokrivaju članke.</p><p>Trajanje mesha: za mukima (onaj koji nije na putu) – 24 sata, za musafira (putnika) – 72 sata.</p><p>Mesh se kvari: skidanjem mestvi, isteknutim vremenom mesha, ili onim što kvari abdest (osim onog što kvari abdest, npr. spavanje).</p><p>Kod zavoja: prelazi se vlažnom rukom preko zavoja kad se zavoj ne smije skidati zbog rane.</p><p>Postupak: Demonstracija mesha na mestvama i zavoju. Učenici ponavljaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici odgovaraju: Šta je mesh? Koliko traje? Kada se kvari? Zaključak o Allahovim olakšicama u vjeri.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":33,"is_published":true,"kviz_pitanja":[{"answer":"Lahka kućna obuća od kože","options":["Lahka kućna obuća od kože","Teške zimske čizme","Sportske patike","Sandale za ljetovanje"],"question":"Šta su mestve?"},{"answer":"72 sata","options":["24 sata","48 sati","72 sata","36 sati"],"question":"Koliko sati može putnik koristiti mesh po mestvama?"},{"answer":"Potiranjem mokrom rukom od prsta prema članovima","options":["Potiranjem mokrom rukom od prsta prema članovima","Perenjem sa sapunom","Hladnom vodom","Brzo trljanjem"],"question":"Kako se pravi mesh po mestvama?"},{"answer":"Ako su mestve poderane ili prljave","options":["Ako su mestve poderane ili prljave","Ako su nove mestve","Ako su lijepe boje","Ako su skupo kupljene"],"question":"Kada mesh po mestvama NIJE valjan?"},{"answer":"Po zavoju, gipsu ili langeti","options":["Po zavoju, gipsu ili langeti","Po svježi bandaži","Po običnom papiru","Po drvenoj dasci"],"question":"Po čemu se može raditi mesh umjesto po mestvama?"}]},{"nivo":2,"slug":"veliki-grijesi","naslov":"Veliki grijesi","content_html":"<div class=\"lesson-container\">\n<h1>VELIKI GRIJESI</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/veliki_grijesi.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Veliki grijesi</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o ozbiljnosti grijeha i jačanje takvaluka</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa pojmom velikih grijeha i njihovim posljedicama</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike izbjegavanja velikih grijeha i tevbe</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je grijeh? A šta mislite, da li su svi grijesi isti? Postoje grijesi koje Allah strožije zabranjuje – to su veliki grijesi.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Veliki grijesi (kebair) su oni za koje je Allah propisao strogu kaznu na ovom ili budućem svijetu, ili za koje je Poslanik, a.s., posebno upozorio.</p><p>Najteži veliki grijesi su: <strong>širk</strong> (pridruživanje Allahu), ubistvo, neposlušnost roditeljima, lažno svjedočenje, jedenje kamate, varanje siročadi, bježanje sa bojnog polja.</p><p>Svi veliki grijesi se mogu oprostiti iskrenom tevbom – osim širka, ako se s njim umre.</p><p>Poslanik, a.s., je rekao: <em>\"Ko se kloni velikih grijeha, Allah će mu oprostiti male grijehe.\"</em></p><p>Razgovor: Zašto je važno izbjegavati grijehe? Šta uraditi kada smo pogriješili? (tevba)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju neke velike grijehe. Zaključujemo da su Allahova milost i tevba uvijek otvoreni vrata.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":36,"is_published":true,"kviz_pitanja":[{"answer":"Allah ga je u Kuranu jasno zabranio i predvidjena je kazna","options":["Allah ga je u Kuranu jasno zabranio i predvidjena je kazna","To je greška koja se često pravi bez namjere","To je mali grijeh koji se lako može ispraviti","To je samo greška u ponašanju prema prijateljima"],"question":"Koja je glavna karakteristika velikog grijeha?"},{"answer":"Post, zekat i hadž su sve tri farz","options":["Samo post i zekat, hadž nije obavezan","Post, zekat i hadž su sve tri farz","Samo hadž je farz, ostalo je dobrovoljno","Nijedna od njih nije obavezna za djecu"],"question":"Koliko od navedenih islamskih dužnosti je farz (stroga obaveza)?"},{"answer":"Alkohol je majka svih zala","options":["Alkohol je koristan u malim količinama","Alkohol je majka svih zala","Alkohol je dozvoljen na važnim praznikom","Alkohol je samo malo štetan za zdravlje"],"question":"Šta je Poslanik (alejhis-selam) rekao o alkoholu?"},{"answer":"Samo Allah, dz.s., ima to pravo","options":["Samo doktori i liječnici imaju to pravo","Samo starješine i liderzi mogu odlučiti","Samo Allah, dz.s., ima to pravo","Svaki čovjek može odlučiti sam za sebe"],"question":"Ko ima pravo da daruje i uzme život prema Islamu?"},{"answer":"Kocka, igre na sreću i kladionica","options":["Čitanje knjiga i učenje novih stvari","Igranje fudbalske utakmice s prijateljima","Kocka, igre na sreću i kladionica","Pomoć roditeljima u domaćinstvu"],"question":"Koja je od ovih aktivnosti zabranjjena prema lekciji?"}]},{"nivo":2,"slug":"teski-grijesi","naslov":"Teški grijesi","content_html":"<div class=\"lesson-container\">\n<h1>TEŠKI GRIJESI</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/teski_grijesi.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Teški grijesi</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje takvaluka i izbjegavanja teških grijeha kroz svijest o Allahovoj kontroli</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti koji su to teški grijesi koji posebno štete pojedincu i zajednici</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike samoispitivanja i čuvanja od grijeha</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, na prošlom času smo pričali o velikim grijesima. Postoje i teški grijesi koji posebno ruše društvo i porodicu. Koje sve grijehe znate?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Teški grijesi su djela koja teško štete pojedincu, porodici i zajednici, te se Allah na njih ljuti.</p><p>Među najteže ubrajamo: ubistvo nedužnog, krađu, prevaru, alkohol i drogu, blud, kamatu, klevetu, ogovaranje.</p><p>Svaki od ovih grijeha ima svoje posljedice: razara povjerenje, rušisreću, oduzima bereket i izaziva Allahovu srdžbu.</p><p>Razgovor: Zašto Allah zabranjuje krađu? (zato što oštećuje drugoga) Zašto laž? (zato što razara povjerenje)</p><p>Najbolje liječenje: izbjegavanje društva koje vodi grijehu, čuvanje namaza, učenje Kur’ana, druženje sa dobrim ljudima.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako čuvati sebe od teških grijeha. Naglašavamo da je svako od nas odgovoran za svoja djela.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":37,"is_published":true,"kviz_pitanja":[{"answer":"Grijesi koji čine osoba nevjernikom i izvode je iz vjere","options":["Grijesi koji čine osoba nevjernikom i izvode je iz vjere","Mali grijesi koje čini svaki musliman","Grijesi koje mogu oprostiti roditelji","Grijesi koje Allah nikad ne može oprostiti"],"question":"Šta su teški grijesi prema lekciji?"},{"answer":"Kufr - nevjerovanje i poricanje temeljnih istina vjere","options":["Kufr - nevjerovanje i poricanje temeljnih istina vjere","Zaboravljanje da se nađe na namazu","Slučajno ljutiti se u toku dana","Zaboravljanje Kurana tokom učenja"],"question":"Koji od sljedećih primjera je teški grijeh?"},{"answer":"Pripisivanje druga Allahu i vjerovanje u druga božanstva","options":["Pripisivanje druga Allahu i vjerovanje u druga božanstva","Zaboravljanje imena Allaha","Neispunjavanje malih obaveza","Nedolazak u džamiju redovno"],"question":"Šta je Širk prema islamskoj vjeri?"},{"answer":"Srcem se pokajati i izgovoriti kelime-i-sehadet","options":["Srcem se pokajati i izgovoriti kelime-i-sehadet","Samo malo dati milostinje","Čekati godine prije nego što se pomiri","Samo obaviti jedan namaz"],"question":"Šta mora učiniti musliman da se ponovo vrati u vjeru nakon težkog grijeha?"},{"answer":"Smatra se nevjernikom prema islamskom učenju","options":["Smatra se nevjernikom prema islamskom učenju","Čeka se godinu dana prije nego što joj se prašta","Postaje anđeo i ide u raj","Može se vratiti u vjeru nakon smrti"],"question":"Koji status ima osoba koja umre bez pokajanja nakon težkog grijeha?"}]},{"nivo":2,"slug":"posljedice-grijeha","naslov":"Posljedice grijeha","content_html":"<div class=\"lesson-container\">\n<h1>POSLJEDICE GRIJEHA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/posljedice_grijeha.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Posljedice grijeha</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o tome da grijeh ima posljedice na ovom i budućem svijetu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti kako grijesi utječu na pojedinca, porodicu i društvo</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje motivacije za izbjegavanje grijeha i činjenje tevbe</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kada uradite nešto loše, kako se osjećate? Da li grijeh ostavlja trag? Allah u Kur’anu govori o posljedicama grijeha.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Grijeh ima posljedice na <strong>tri razine</strong>: u srcu čovjeka, u njegovom životu na dunjaluku i na ahiretu.</p><p>U srcu: grijeh stvara nemir, tugu, gubitak slasti ibadeta i hladno srce.</p><p>Na dunjaluku: grijeh oduzima bereket iz nafake, vremena, zdravlja i odnosa.</p><p>Na ahiretu: grijeh donosi kaznu, ako se ne učini iskrena tevba.</p><p>Allah u Kur’anu kaže: <em>\"Pojavio se nered na kopnu i moru zbog onoga što ljudi rade...\"</em></p><p>Lijek: tevba (iskreno kajanje), vraćanje prava ljudima i činjenje dobrih djela.</p><p>Razgovor: Šta sve može pomoći da izbjegnemo grijehe? (dobro društvo, dova, namaz, čitanje Kur’ana)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razmišljaju o tome kakvi su tragovi dobrih i loših djela. Učimo dovu za oprost grijeha (Estagfirullah).</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">GRIJEH NIJE BESPLATAN <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Mladi čovjek jednom upita muallima: Ako mi je Allah svemilostiv, zašto da brinem o grijesima? Muallim ga upita: Jesi li ikad sjeo na vrelu ploču slučajno? Jesam, reče dječak. I šta se desilo? Opekao sam se. Je li vatra bila zla prema tebi? Ne, samo sam se opekao. Tako je i s grijehom, reče muallim. Allah nije zao - ali grijeh ima svoju posljedicu kao i svaka vatra. I ona počinje odmah. Posljedice grijeha nisu samo na ahiretu - mnoge od njih vidimo već na ovom svijetu: u zdravlju, u porodici, u nafaki. Musliman koji razumije ovo ne bježi od grijeha iz straha, nego iz mudrosti.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Uzvišeni Allah je stvorio čovjeka i On najbolje poznaje njegovu narav, dušu i tijelo. Allah, dž.š., zna šta čovjeku koristi, a šta šteti. Zbog toga je čovjeku zabranjeno da čini grijehe.</p><p>Najveće posljedice grijeha grješnik će osjetiti na Sudnjem danu, međutim, mnoge od njih su vidljive još na ovom svijetu. Posljedice su pogubne za pojedinca, porodicu ili društvo, a najčešće za svaku od navedenih kategorija.</p><p><strong>U posljedice grijeha ubrajamo:</strong></p><ul><li><p>narušavanje psihičkog i fizičkog zdravlja pojedinca,</p></li><li><p>slabljenje ili gubitak vjere,</p></li><li><p>ugrožavanje dostojanstva čovjeka,</p></li><li><p>umanjenje nafake i bereketa,</p></li><li><p>siromaštvo u porodici,</p></li><li><p>pojava raznih bolesti,</p></li><li><p>slabljenje porodičnih veza i harmonije,</p></li><li><p>slabljenje društvene zajednice,</p></li><li><p>prirodne nepogode – suša, poplave,</p></li><li><p>povezanost s drugim grijesima.</p></li></ul><p>Ako se grijesi prošire, posljedice osim grješnika osjećaju i vjernici putem raznih iskušenja na dunjaluku. Na vezu između grijeha i njegovih posljedica upozorio je Muhammed, alejhis-selam, u hadisu:</p><div class=\"info-box\"><p>„Kad se u jednom narodu pojavi nemoral pa se počne činiti javno, stići će epidemije – zarazne bolesti koje nisu bile poznate narodima koji su prije živjeli.“ (Ibn Madže)</p></div><p>Cilj čovjekova života je sreća na ovom i budućem svijetu. Da bismo je postigli, obaveza je svakog muslimana i muslimanke da se čuva grijeha.</p><div class=\"arabic-card\"><p>Poslanik, alejhis-selam, je rekao: „Čovjek ponekada izrekne neku riječ - ne vodeći računa je li ona dobra ili nije a zbog nje će biti bačen u džehennemsku vatru.“ (Buhari)</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – POSLJEDICE GRIJEHA</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p><strong>PITANJA I ZADACI</strong></p><ol><li><p>Zbog čega je grijeh zabranjen?</p></li><li><p>Gdje će se osjetiti najveće posljedice grijeha?</p></li><li><p>Šta ubrajamo u posljedice grijeha?</p></li><li><p>ZADATAK: U mektebsku svesku nacrtaj tabelu, napiši u prvu kolonu grijehe o kojima smo učili u prethodnim lekcijama a zatim stavi X u kolonu u koju oni spadaju: teški, mali ili veliki grijeh.</p><table style=\"width: 762px;\"><colgroup><col style=\"width: 277px;\"><col style=\"width: 147px;\"><col style=\"width: 171px;\"><col style=\"width: 167px;\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"277\"><p style=\"text-align: center;\">IMENOVANJE GRIJEHA</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"147\"><p style=\"text-align: center;\">TEŠKI</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"171\"><p style=\"text-align: center;\">VELIKI</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"167\"><p style=\"text-align: center;\">MALI</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"277\"><p>Laž</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"147\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"171\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"167\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"277\"><p>Psovanje islamskih svetinja</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"147\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"171\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"167\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"277\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"147\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"171\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"167\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"277\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"147\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"171\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"167\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"277\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"147\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"171\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"167\"><p></p></td></tr></tbody></table></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">RAZGOVOR S MUALLIMOM</mark></strong><br>Grijeh te tišti i muči!</p><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">IZABERI ZADAĆU!</mark></strong><br>1. Šta su mali grijesi i da li su oni beznačajni? Zašto?<br>2. Šta su veliki grijesi? Razmisli - zašto su ubrojani u velike a ne u male?<br>3. Zašto se teški grijesi baš tako zovu? Koji su to teški grijesi?</p><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":38,"is_published":true,"kviz_pitanja":[{"answer":"Jer Allah najbolje poznaje što čovjeku koristi i šteti","options":["Jer Allah najbolje poznaje što čovjeku koristi i šteti","Jer su grijesi dosadni","Jer se svi griješnici hvataju u zatvoru","Jer su grijesi skupi"],"question":"Zbog čega je čovjeku zabranjeno činiti grijehe?"},{"answer":"Na Sudnjem danu","options":["U školi","Na Sudnjem danu","U svojoj kući","U bolnici"],"question":"Gdje će grješnik osjetiti najveće posljedice grijeha?"},{"answer":"Epidemije zarazne bolesti koje nisu bile poznate","options":["Pojava samo bogatstva","Epidemije zarazne bolesti koje nisu bile poznate","Poboljšanje zdravlja","Jačanje vjere"],"question":"Šta je posljedica grijeha prema hadisu?"},{"answer":"Pojava novih pažljenih zakona","options":["Narušavanje zdravlja","Umanjenje nafake i bereketa","Pojava novih pažljenih zakona","Slabljenje porodičnih veza"],"question":"Koja od ovih opšenosti NIJE navedena kao posljedica grijeha?"},{"answer":"Vjernice putem raznih iskušenja","options":["Samo nastavnike","Samo obitelj","Vjernice putem raznih iskušenja","Samo druge zemlje"],"question":"Koga osim grješnika pogađaju posljedice grijeha?"}]},{"nivo":2,"slug":"cestitost","naslov":"Čestitost i odgovornost","content_html":"<div class=\"lesson-container\">\n<h1>ČESTITOST I ODGOVORNOST</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/cestitost.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Čestitost i odgovornost</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje čestitog karaktera i osjećaja odgovornosti za svoje postupke</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta znači biti čestit i odgovoran musliman</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika preuzimanja odgovornosti za vlastite obaveze i postupke</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta znači biti čestit čovjek? A odgovoran? Da li poznajete nekog ko je čestit? Po čemu ga prepoznajete?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Čestitost znači biti pošten, iskren, ne varati, ne lagati, ispunjavati obećanja i raditi ono što je ispravno.</p><p>Odgovornost znači prihvatiti posljedice svojih djela – kako dobrih, tako i loših.</p><p>Musliman je odgovoran za: namaz, znanje, ponašanje prema roditeljima, učenje, čuvanje povjerenih stvari.</p><p>Poslanik, a.s., je rekao: <em>\"Svako od vas je pastir i svako će biti odgovoran za svoje stado.\"</em></p><p>Razgovor: Za šta sam ja odgovoran? (za učenje, za svoje stvari, za ponašanje prema mlađima i starijima)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju primjere čestitosti i odgovornosti u svom životu. Zaključak: čestit i odgovoran musliman je ponos svoje porodice.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":40,"is_published":true,"kviz_pitanja":[{"answer":"Cestitost i odgovornost","options":["Cestitost i odgovornost","Hrabrost i pažljivost","Ljubaznost i poslušnost","Vještina i znanje"],"question":"Koje dvije osobine se nadopunjuju jedna drugom prema lekciji?"},{"answer":"Naša djela, Poslanik i vjernici","options":["Naša djela, Poslanik i vjernici","Samo naše myšljene","Samo naše škole","Samo našu igru"],"question":"Šta Allah, dz.s., će vidjeti od nas prema ajetu?"},{"answer":"Moraju biti čiste i uredno","options":["Moraju biti čiste i uredno","Mogu biti prljave","Trebaju biti zbrkane","Mogu biti poničene"],"question":"Što trebamo uraditi sa stranicama na kojima radimo zadace?"},{"answer":"Nakon što se odmorimo","options":["Nakon što se odmorimo","Prije nego se odморимо","Nikad nije važno","Samo za posebne zadace"],"question":"Kada trebamo pristupiti izradi mektebske zadace?"},{"answer":"Izvršavanje obaveza na vrijeme savjesno","options":["Izvršavanje obaveza na vrijeme savjesno","Vršenje obaveza kada želimo","Nerada obaveza u školi","Igranje umjesto rada"],"question":"Šta pokazuje cestitost i odgovornost prema lekciji?"}]},{"nivo":2,"slug":"namaz-bolesnika","naslov":"Namaz bolesnika","content_html":"<div class=\"lesson-container\">\n<h1>NAMAZ BOLESNIKA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/namaz_bolesnika.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Namaz bolesnika</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti da se namaz ne ostavlja ni u bolesti i da Allah ne opterećuje preko mogućnosti</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti kako klanja bolesnik koji ne može stajati, sjediti ili se kretati</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pomogne bolesniku ili sam klanja u slučaju bolesti</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta da uradi onaj ko je bolestan i ne može stajati? Da li ostavlja namaz? Allah je dao olakšice – namaz se klanja koliko se može.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Bolesnik klanja redovne namaze, ali na način koji mu omogućuje njegovo zdravstveno stanje.</p><p>Ko ne može stajati – klanja sjedeći. Ko ne može sjediti – klanja ležeći (sa naslonjenom glavom prema kibli ako može).</p><p>Ruku se izvodi blagim pognjem glave naprijed. Sedžda se izvodi dubljim pognjem od rukua.</p><p>Ako bolesnik ne može uzeti abdest, uzima tejemum.</p><p>Bolesniku se ne smiju izostavljati namazi – on klanja sve namaze u njihovo vrijeme, koliko može.</p><p>Postupak: Demonstracija – kako klanjati sjedeći, kako ležeći. Razgovor o tome kako pomoći bolesniku da klanja (postaviti ga prema kibli, donijeti mu vodu za abdest itd.).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam: Šta uraditi kad ne možemo stajati? Učenici odgovaraju i pokazuju. Zaključak: namaz se ne ostavlja zbog bolesti.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">IBADET I U BOLESTI <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Zamislite čovjeka u bolničkoj sobi. Boli ga svaki pokret. Ne može ustati iz kreveta. Dolazi vrijeme namaza. Šta će učiniti? Da li Allah traži od njega nesto što mu je nemoguce? Ne. Allah nikoga ne opterecuje preko mogućnosti njegovih. Bolest je iskušenje, ali nije kazna koja prekida ibadet. Bolesniku je dozvoljeno klanjati sjedeci, pa lezeci, pa i ishharetom glave, pa čak i u mislima. Allah gleda srce i namjeru, a ne položaj tijela. Ko god zeli klanjati - može klanjati, ma kakvo mu bilo zdravstveno stanje. To je Allahova milost.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p>Allah, dz.s., kaže: Allah nikoga ne opterecuje preko mogućnosti njegovih... (El-Bekare, 286)</p></div><p>Bolest je iskušenje u životu vjernika i vjernice, ali i pored tog stanja moramo očuvati stalnu vezu sa Gospodarom putem klanjanja namaza. Bolest nas ponekad sprečava u propisanom načinu izvršavanja namaza pa je Allah, dž.š., omogućio olakšicu za bolesnike.</p><p><strong>Olakšice za bolesnike su sljedeće:</strong></p><ul><li><p>Ako bolesnik namaz ne može klanjati stojeći, klanjat će sjedeći, izvršavajući rukuu i sedždu išaretom tako da se na sedždi naginje naprijed više nego na rukuu;</p></li><li><p>Bolesnik koji ne može sjedeći klanjati namaz, učinit će to u ležećem položaju, okrećući noge prema Kibli, ali će ih saviti u koljenu. Glavu će uzdignuti kako bi njome simbolićki mogao obavljati namaske dijelove. Bolesnik koji ne može pomjerati ni ove dijelove tijela, namaz može klanjati u mislima;</p></li><li><p>Teška stanja koja ne dozvoljavaju klanjanje namaza prema ovim olaksišama, odgađaju obavljanje namaza do vremena kada ga bolesnik mogne naklanjati. Ukoliko teže stanje potraje duže od jednog dana, bolesnik nije obavezan naklanjati propuštene namaze.</p></li><li><p>Bolesnici koji se nalaze u komi ili bez svijesti duže od jednog dana i noći, odnosno ako broj propuštenih namaza bude šest i više, nisu dužni naklanjati namaze koje propuste u tom stanju.</p></li><li><p>Bolesnik će u stanju bolesti sam procijeniti svoje stanje i namaz klanjati na najbolji način koji mu to njegovo zdravlje dopušta.</p></li></ul><div class=\"info-box\"><p><strong>HADIS</strong><br>Poslanik, alejhis-selam, je rekao: „Neće vjernika zadesiti nikakva teškoća, tuga, niti bolest, čak ni briga koja ga mori, a da mu Allah neće zato oprostiti neke njegove grijehe.“ (Tirmizi)</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – NAMAZ BOLESNIKA</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p><strong>PITANJA I ZADACI</strong></p><ol><li><p>Kako će bolesnik klanjati namaz?</p></li><li><p>Kakav je status bolesnika koji je u stanju kome ili bez svijesti?</p></li><li><p>ZADATAK: Uz opise bolesti nekih ljudi i njihovog stanja napisi kako će oni postupiti kada je u pitanju klanjanje namaza. <br><br></p><table style=\"width: 708px;\"><colgroup><col style=\"width: 350px;\"><col style=\"width: 358px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\" colwidth=\"350\"><p>Stanje osobe</p></th><th colspan=\"1\" rowspan=\"1\" colwidth=\"358\"><p>Da li će i kako obaviti namaz?</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"350\"><p>Osoba ima jake bolove u nogama</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"358\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"350\"><p>Osoba se tek operisala i ne smije ustajati iz kreveta</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"358\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"350\"><p>Osoba je doživjela nezgodu i ne može pomjerati tijelom</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"358\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"350\"><p>Osoba se onesvijestila</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"358\"><p></p></td></tr></tbody></table></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":45,"is_published":true,"kviz_pitanja":[{"answer":"Klanja sjedeći, izvršavajući ruku i suždu pokretem","options":["Klanja sjedeći, izvršavajući ruku i suždu pokretem","Klanja stojeći sa pomoću štapa","Klanja samo mentalno bez ikakvih pokreta","Klanja prevaljujući se na podu"],"question":"Kako se klanja namaz ako bolesnik ne može stajati?"},{"answer":"Može klanjati namaz u mislima","options":["Trajno je oslobođen od namaza zauvijek","Može klanjati namaz u mislima","Mora čekati da ozdravi prije nego počne","Klanja sa dozvolom samo četiri puta godišnje"],"question":"Šta može uraditi bolesnik koji ne može pomjerati dijelove tijela?"},{"answer":"Više od jednog dana i noći","options":["Tri dana ili duže","Pet dana ili duže","Više od jednog dana i noći","Samo dva dana"],"question":"Koliko dana mora bolesnik da bude u komi da ne klanja propuštene namaze?"},{"answer":"Okrepuje noge prema Kibli i savija ih u koljenu","options":["Vodi ih prema naprijed bez savijanja","Okrepuje noge prema Kibli i savija ih u koljenu","Ostavlja noge potpuno ravne i nepomične","Pokreće samo jednu nogu prema Kibli"],"question":"Kako bolesnik u ležećem položaju pokreće noge prema Kibli?"},{"answer":"Sam bolesnik prema svom stanju","options":["Ljekar koji ga liječi","Učitelj vjeronauke","Sam bolesnik prema svom stanju","Starji član porodice"],"question":"Ko procjenjuje kako bolesnik može klanjati namaz?"}]},{"nivo":2,"slug":"kunut-dova","naslov":"Učenje Kunut-dove","content_html":"<div class=\"lesson-container\">\n<h1>UČENJE KUNUT-DOVE</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/kunut_dova.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje Kunut-dove</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema dovi i potrebe za stalnim obraćanjem Allahu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti Kunut-dovu, njeno značenje i pravilan izgovor</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobljavanje učenika da uče Kunut-dovu na vitr-namazu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li znate šta je vitr-namaz? Kada se klanja? Na trećem rekatu vitra uči se posebna dova – Kunut-dova. Hajde da je naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kunut-dova se uči na trećem rekatu vitr-namaza, prije rukua, nakon Fatihe i sure, donese se tekbir i ruke se podignu pa skupe i prouči se Kunut.</p><p>Tekst Kunut-dove: <em>Allahumme innā nestea‘īnuke ve nestagfiruke ve nu’minu bike ve netevekkelu alejke...</em></p><p>Značenje: <em>\"Allahu naš, mi od Tebe pomoć tražimo, oprosta tražimo, u Tebe vjerujemo i na Tebe se oslanjamo...\"</em></p><p>Učenje pojedinih dijelova: pišem dovu na tabli, ponavljamo dio po dio.</p><p>Postupak: Učenici slušaju izgovor, ponavljaju u horu, zatim pojedinačno. Naglasak na pravilan izgovor arapskih harfova.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici proučavaju dovu nekoliko puta. Zadaća: učiti Kunut-dovu svaki dan dok je ne nauče napamet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":47,"is_published":true,"kviz_pitanja":[{"answer":"Na trećem rekatu, prije ruku'a","options":["Na prvom rekatu, nakon sure","Na trećem rekatu, prije ruku'a","Na drugom rekatu, nakon ruku'a","Na kraju namaza, nakon taslima"],"question":"Gdje se Kunut-dova učí u vitr-namazu?"},{"answer":"Pomoć, oprost i uputstvo","options":["Hrana, odjeća i novac","Pomoć, oprost i uputstvo","Zdravlje, bogatstvo i deca","Putovanje, rad i učenje"],"question":"Koja su tri glavna prošenja u Kunut-dovi?"},{"answer":"Pouzdajemo se u Tebe","options":["Tražimo tvoju pomoć","Pouzdajemo se u Tebe","Pokajanja se obračamo","Zahvaljujemo Ti"],"question":"Šta znači 'Netevekkelu Alejke' u Kunut-dovi?"},{"answer":"Tekbir, pa onda sure, pa Kunut-dova","options":["Sure, pa onda Kunut-dova","Tekbir, pa onda sure, pa Kunut-dova","Samo Kunut-dova bez sure","Ruku'a, pa onda Kunut-dova"],"question":"Koji je redoslijed učenja prije Kunut-dove?"},{"answer":"Pomoć, oprost, uputstvo i vjerovanje","options":["Samo veliku kuću i auto","Pomoć, oprost, uputstvo i vjerovanje","Samo da budemo bogati","Samo da se igramo"],"question":"Šta tražimo od Allaha u Kunut-dovi?"}]},{"nivo":2,"slug":"namaska-dova","naslov":"Namaska dova","content_html":"<div class=\"lesson-container\">\n<h1>NAMASKA DOVA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/namaska_dova.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Namaska dova</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o vrijednosti dove nakon namaza i jačanje veze sa Allahom</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti dove koje se uče poslije farz-namaza</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike učenja namaske dove nakon svakog farza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kada predamo selam i završimo namaz, šta učimo poslije? Postoje posebne dove koje su nas Poslanik, a.s., podučili. Hajde da ih naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslije svakog farz-namaza lijepo je proučiti: 3x <em>Estagfirullah</em>, zatim <em>Allahumme entes-selām...</em></p><p>Nakon toga uči se Ajetul-Kursi (najveći ajet u Kur’anu, sura Bekare 255).</p><p>Zatim 33x <em>Subhānallāh</em>, 33x <em>El-hamdu lillāh</em>, 33x <em>Allāhu ekber</em>, te jednom <em>Lā ilāhe illallāhu vahdehu lā šerīke leh...</em></p><p>Na kraju – lična dova: čovjek moli Allaha za ono što mu treba na svom jeziku.</p><p>Vrijednosti: Ko ovo uči poslije svakog namaza – grijesi mu se opraštaju, makar bili kao morska pjena.</p><p>Postupak: Učimo dove redom, brojimo prstima 33 puta. Demonstracija sjedenja nakon namaza.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici proučavaju dijelove namaske dove zajedno. Zaključak: namaz nije završen selamom – završen je tek nakon dove.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">DOVA NA KRAJU DANA <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Jednog dana imam je djeci nakon namaza rekao: „Znate li da svaka lijepa stvar ima svoj završetak? Kao što nakon ručka dolazi desert, tako i nakon namaza dolazi nešto posebno.“ Djeca su ga radoznalo gledala, pa im je objasnio: „To je namaska dova – ona je kao slatki završetak našeg namaza.“</p><p>Namaska dova je ono što učimo na kraju namaza, kao lijep i važan završetak našeg ibadeta. Kroz nju zahvaljujemo Allahu i molimo Ga za dobro. Zato je važno da je naučimo i redovno učimo, jer time naš namaz postaje potpun i još ljepši.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Namaska dova uči se nakon predaje selama na kraju namaza.</p><div class=\"arabic-card\"><p><strong>NAMASKA DOVA GLASI:</strong><br><br>E'UZU BILLAHI MINEŠ-ŠEJTANIR-RADŽIM<br>BISMILLAHIR-RAHMANIR-RAHIM<br><br>EL-HAMDU LILLAHI RABBIL-'ALEMIN. VES-SALATU VES-SELAMU 'ALA SEJJIDINA MUHAMMEDIN VE 'ALA ALIHI VE SAHBIHI EDŽME'IN. ALLAHUMME RABBENA TEKABBEL MINNA HAZIHIS-SALATE KEMA TEKABBELTE MIN 'IBADIKES-SALIHIN. ALLAHUMME HABBIB ILEJNEL-IMANE VEL-ISLAME VEL-IHSANE, VE KERRIH ILEJNEL-KUFRE VEL-FUSUKA VEL-'ISJAN.<br>RABBENA ATINA FID-DUNJA HASENETEN VE FIL-AHIRETI HASENETEN VEKINA 'AZABEN-NAR. RABBI DŽ'ALNI MUKIMES-SALATI VE MIN ZURRIJJETI, RABBENA VE TEKABBEL DU'A. RABBENA-GFIRLI VE LI VALIDEJJE VE LIL-MUMINNE JEVME JEKUMUL-HISAB, BI RAHMETIKE JA ERHAMER-RAHIMIN.<br>SUBHANE RABBIKE RABBIL-'IZZETI 'AMMA JESIFUN, VE SELAMUN 'ALEL-MURSELIN, VEL-HAMDU LILLAHI RABBIL-'ALEMIN.</p></div><p><strong>Prijevod namaska dove (dijelovi):</strong></p><div class=\"info-box\"><p><strong>Utječem se Allahu od prokletog šejtana.<br>U ime Allaha, Milostivog, Samilosnog.</strong></p><p>Hvala Allahu, Gospodaru svjetova. Neka je salavat i selam na našeg prvaka Muhammeda, na njegovu porodicu i sve njegove ashabe.</p><p>Allahu naš, primi od nas ovaj namaz kao što si primao od Svojih dobrih robova. Allahu naš, učini nam dragim iman, islam i ihsan, a omrzni nam nevjerstvo, griješenje i neposlušnost.</p><p>Gospodaru naš, podari nam na ovom svijetu dobro i na budućem svijetu dobro i sačuvaj nas od patnje u vatri.</p><p>Gospodaru moj, učini da ja redovno obavljam namaz, i dio mog potomstva. Gospodaru naš, primi moju dovu.</p><p>Gospodaru naš, oprosti meni, mojim roditeljima i svim vjernicima na Dan kada se bude polagao račun, Tvojom milošću, o Najmilostiviji.</p><p>Slavljen neka je Gospodar tvoj, Gospodar veličanstva, iznad onoga što Mu pripisuju, i mir neka je na poslanike, i hvala Allahu, Gospodaru svjetova.</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – NAMASKA DOVA</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p><strong>PITANJA I ZADACI</strong></p><ol><li><p>Kada se uči namaska dova?</p></li><li><p>Za šta molimo Allah u namaskoj dovi?</p></li><li><p>ZADATAK: Nauči namasku dovu napamet i uvježbaj je sa muallimom!</p></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":48,"is_published":true,"kviz_pitanja":[{"answer":"Nakon predaje selama na kraju namaza","options":["Nakon predaje selama na kraju namaza","Na početku namaza","Prije nego što se počne namaz","Tijekom ruku'a"],"question":"Kada se uči namaska dova?"},{"answer":"Da prihvati naš namaz i da nam da dobro","options":["Da prihvati naš namaz i da nam da dobro","Da nam da samo novac i bogatstvo","Da nam učini bogatima i moćnima","Da nam oslobodi svih obaveza"],"question":"Za što molimo Allah u namaskoj dovi?"},{"answer":"Ljubav prema imanu, islamu i ihsanu","options":["Ljubav prema imanu, islamu i ihsanu","Mržnju prema svim ljudima","Želju za bogatstvom i moći","Strah od svih drugih ljudi"],"question":"Šta molimo Allah da usadi u naša srca?"},{"answer":"Od vatre džehennemske","options":["Od vatre džehennemske","Od kiše i snijega","Od buke i brijesa","Od morskih vala"],"question":"Od čega molimo Allah da nas čuva?"},{"answer":"Nama, roditeljima i svim vjernicima","options":["Nama, roditeljima i svim vjernicima","Samo nama samima","Samo našim roditeljima","Samo bogatim ljudima"],"question":"Koga molimo Allah da oprosti u namaskoj dovi?"}]},{"nivo":2,"slug":"radne-navike","naslov":"Razvijanje radne navike","content_html":"<div class=\"lesson-container\">\n<h1>RAZVIJANJE RADNIH NAVIKA I STJECANJE ZNANJA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/radne_navike.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Razvijanje radne navike</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema radu i odgovornosti prema svojim obavezama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti vrijednost rada u islamu i kako razviti radne navike</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svakodnevnih navika urednog ispunjavanja obaveza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kakve obaveze imate svaki dan? Učenje, pomaganje u kući, briga o sebi... Da li volite raditi? Šta islam kaže o radu?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Rad je u islamu vrlo cijenjen. Poslanik, a.s., je rekao: <em>\"Niko ne jede bolju hranu od one koju zaradi vlastitim rukama.\"</em></p><p>Radne navike se razvijaju malim koracima: redovno učenje, pospremanje sobe, pomaganje roditeljima, uredno radjenje zadaće.</p><p>Lijenost je loša osobina koju islam osuđuje. Allahov Poslanik je tražio utočište kod Allaha od lijenosti i nemoći.</p><p>Razgovor: Koje sam radne navike već razvio? Šta još mogu poboljšati? (rano ustajanje, učenje istog vremena svaki dan, planiranje sedmice)</p><p>Mali planovi vode velikim ciljevima – kap po kap napravi se rijeka.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Svaki učenik bira jednu radnu naviku koju će razvijati ovaj tjedan. Razgovor o tome kako se osjećamo kad obavimo posao.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">RAD JE IBADET <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Muhammed, alejhis-selam, je molio Allaha da ga sacuva lijenosti. Dakle, najdrazi čovjek Allahu – molio se protiv lijenosti. To nam govori koliko je lijenost opasna. Rad, s druge strane, Allah je opisao kao temeljni dio covjekove prirode: Mi čovjeka stvaramo da se trudi. Musliman koji ide na mekteb i školu, koji uči, koji pomaže u kući, koji ucesstvuje u sportu i igri – taj musliman živi islamski svaki dan, ne samo u namazu. Djecak koji uradi zadaću na vrijeme vjezbuje osobinu koja će ga pratiti cijeli život. Djevojcica koja pomaže majci razvija empatiju koja će joj trebati kao roditelju jednog dana.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p>Allah, dz.s., kaže: Mi čovjeka stvaramo da se trudi. (El-Beled, 4)</p></div><p>Prve radne navike stječemo u svojoj porodici a nasljeđujemo ih od svojih roditelja, oca i majke. Dok odrastamo uz roditelje/staratelje, primjećujemo da oni neumorno rade i privređuju kako bi nam osigurali uvjete za život. Tako od roditelja/staratelja naučimo da u toku života treba raditi i privređivati i na taj način izdržavati svoju porodicu.</p><p>Rad se u islamu tretira kao vrsta ibadeta, Bogu dragog djela, zato ćemo za svoj rad i trud biti nagrađeni od Allaha, dž.š., na ovom i budućem svijetu.</p><p>Djetinjstvo je veoma važan period u životu svakog čovjeka, tada se pripremamo za život i stječemo naviku za rad i privređivanje.</p><p>Obaveza djece je da pomažu roditeljima kada to oni od njih traže i kada sama djeca osjete da je roditeljima/starateljima potrebna njihova pomoć. Pored toga naša najveća obaveza je da učimo i stječemo znanje. Od našeg znanja i uspjeha u mektebu i školi zavisi naše životno zanimanje, tj. šta ćemo raditi i čime ćemo se u životu baviti. Redovnim učenjem u školi i mektebu vršimo pripreme za život. Ako mektebske i školske obaveze izvršavamo na vrijeme, stječemo naviku da i svoje buduće životne obaveze, koje preuzmemo na sebe, izvršavamo na vrijeme. Pored učenja i stjecanja znanja, u djetinjstvu je veoma važno druženje i igranje sa vršnjacima.</p><ul><li><p>Druženjem sa vršnjacima stječemo određene društvene osobine i stječemo svoje prve prijatelje, s kojima će prijateljstvo počesto trajati cijelog života.</p></li><li><p>Povremena igra sa vršnjacima jača naše druženje i prijateljstvo. Važno je da se u toku igre pridržavamo određenih pravila. Spomenuta pravila nas navikavaju na primjenjivanje određenih životnih pravila ili propisa kada odrastemo. Kao muslimani moramo se pridržavati propisa koji su od Allaha, dž.š., a kao građani zakona koje su ljudi propisali.</p></li></ul><p>Također, moramo se čuvati lijenosti jer ona nije svojstvena muslimanu i muslimanki. Muhammed, a.s., je molio Allaha, dž.š., da ga sačuva lijenosti.</p><p>Ako hoćemo biti uspješni u životu na ovome svijetu, ako želimo postići sreću na budućem svijetu, potrebno je da svaki dan započnemo klanjanjem sabah-namaza a nakon toga da izvršavamo svoje radne obaveze. Klanjanjem pet dnevnih namaza učimo se kako isplanirati dnevne obaveze. Važno je da ih na vrijeme izvršavamo jer poslije njih ostat će nam više slobodnog vremena koje možemo provesti u igri sa svojim prijateljima. Još važnije je da se pridržavamo pravila islamskog ponašanja, a to je da radimo djela koja je Allah, dž.š., naredio ili dozvolio a da izbjegavamo činiti djela koja je Allah, dž.š., zabranio.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – RAZVIJANJE RADNIH NAVIKA I STJECANJE ZNA</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p><strong>PITANJA I ZADACI</strong></p><ol><li><p>Kako se u islamu tretira rad?</p></li><li><p>Čime trebamo započinjati svoj dan?</p></li><li><p>Čemu naš uči obavljanje dnevnih namaza?</p></li><li><p>ZADATAK 1: Napravi svoju tabelu dnevnih aktivnosti!</p></li><li><p>ZADATAK 2: Napravi plan za čitanje knjiga u toku jednog mjeseca – ne računajući školske obaveze i lektire i na vidno mjesto stavi taj plan. Na kraju mjeseca nagradi sebe ukoliko si ispunio planirano.</p></li></ol><div class=\"info-box\"><p><strong>RAZGOVOR S MUALLIMOM</strong><br>Poslovica: Ko radi, ne boji se gladi!</p></div><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":50,"is_published":true,"kviz_pitanja":[{"answer":"U svojoj porodici od roditelja","options":["U svojoj porodici od roditelja","U školi od učitelja","Na ulici od prijatelja","U mektebu od imama"],"question":"Gdje stječemo prve radne navike?"},{"answer":"Vrsta ibadeta, Bogu dragog djela","options":["Vrsta ibadeta, Bogu dragog djela","Samo način da zaradimo novac","Obaveza samo za odrasle","Nešto što nije važno"],"question":"Šta je prema islamu rad?"},{"answer":"Učenje i stjecanje znanja","options":["Učenje i stjecanje znanja","Igranje sa prijateljima","Gledanje televizije","Mirovanje i odmor"],"question":"Koja je najveća obaveza djece pored pomoći roditeljima?"},{"answer":"Od našeg znanja i uspjeha u školi","options":["Od našeg znanja i uspjeha u školi","Od plate koju želimo","Od broja prijatelja","Od našeg izgleda"],"question":"Od čega zavisi naše budućno zanimanje?"},{"answer":"Čuvanje se od ljenosti","options":["Čuvanje se od ljenosti","Mnogo spavanja","Izbjegavanje radnih obaveza","Nedostatak planiranja"],"question":"Šta je karakteristika muslimana prema lekciji?"}]},{"nivo":2,"slug":"srednji-put","naslov":"Uloga i važnost srednjeg puta","content_html":"<div class=\"lesson-container\">\n<h1>ULOGA I VAŽNOST SREDNJEG PUTA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/srednji_put.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Uloga i važnost srednjeg puta</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje umjerenosti, izbjegavanja krajnosti i balansiranog života</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta znači \"ummetun vesat\" i zašto je islam vjera srednjeg puta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike umjerenosti u jelu, ponašanju, igri i ibadetu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je bolje – previše jesti ili premalo jesti? Previše spavati ili premalo? Allah voli sredinu. Islam zovemo \"vjerom srednjeg puta\".</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah u Kur’anu kaže: <em>\"I tako smo vas učinili pravednim narodom (ummetom vesat)...\"</em> – narodom srednjeg puta.</p><p>Srednji put znači umjerenost u svemu: u ibadetu (ne pretjerivati niti zanemarivati), jelu, govoru, ponašanju, trošenju.</p><p>Pretjerivanje je opasnost: ko jede previše – razboli se; ko priča previše – pogriješi; ko se igra previše – zanemari obaveze.</p><p>Poslanik, a.s., je živio umjereno – jeo malo, govorio kratko i jasno, klanjao redovno, ali se i odmarao i smijao sa ashabima.</p><p>Razgovor: Gdje pretjerujem? (sa telefonom, sa slatkišima, sa igrom...) Kako da se vratim na sredinu?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju oblasti u kojima trebaju biti umjereniji. Zaključak: srednji put vodi sreći i miru.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">RAVNOTEŽA JE MUDROST <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Jedan dječak je volio da u svemu ide do kraja – ili bi radio previše, ili uopće ne bi radio. Jednog dana ga je učitelj zaustavio i rekao: „Znaš li da ni previše ni premalo nije ispravno?“ Dječak se začudio, pa ga učitelj odvede do puta i reče: „Pogledaj – ako ideš samo lijevo ili samo desno, sići ćeš s puta. Samo sredinom stižeš sigurno.“</p><p>I u našem životu često biramo između krajnosti, a zaboravljamo ono što je najispravnije – sredinu. Islam nas uči upravo tome: da budemo umjereni, uravnoteženi i pravedni. To je put koji vodi stabilnosti, miru i uspjehu, i na ovom i na budućem svijetu.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Svakodnevno u namazu molimo Allaha, dž.š., da nas uputi na Pravi put što je osnovni uvjet za uspješan život na dunjaluku. Ustrajati na Pravom putu znači držati se puta sredine, a Allah, dž.š., u Kurʼanu je muslimane opisao kao narod sredine, umjerenosti i uravnoteženosti.</p><p>Srednji put podrazumijeva traženje sredine i ravnoteže između dvije suprotstavljene krajnosti. To je put držanja i traženja ravnoteže ali da nijedna strana ne pretegne, nego da se slijedi ono što je najvrednije, najpravednije, najbolje i najpotpunije.</p><p>Slijeđenje srednjeg puta i uravnoteženost u prakticiranju vjerskih propisa i u životu ima presudni značaj za jedinstvo, harmoniju i slogu u zajednici. Srednji put je pravac i ponašanje koje nikoga ne stavlja u podređen položaj i koje svakom daje pravo koje zaslužuje u zajednici.</p><p>Primjeri za shvatanje srednjeg puta:</p><ol><li><p>Duhovnost i materijalizam – Islam od nas traži da radimo i privređujemo za ovaj svijet i da stječemo opskrbu za sebe i porodicu, ali od nas zahtijeva i zalaganje za budući vječni svijet. …i nastoj time što ti je Allah dao da stekneš onaj svijet, a ne zaboravi ni svoj udio na ovom svijetu i čini drugima dobro, kao što je Allah tebi dobro učinio... (El-Kasas, 77)</p></li><li><p>Pojedinac i zajednica – Također, islam poziva da se čvrsto držimo zajednice i da budemo što korisniji članovi. U isto vrijeme, islam traži i da se posvetimo porodici i našem zdravlju na individualnom nivou. Stoga je potrebno pronaći ravnotežu u zalaganju za obje dužnosti. </p></li></ol><div class=\"arabic-card\"><p>Allah, dz.s., kaže: I tako smo od vas stvorili pravednu zajednicu da budete svjedoči protiv ostalih ljudi, i da poslanik bude protiv vaš svjedok. (El-Bekare, 143)</p></div><p>Islam uči, odgaja i upućuje muslimane da ne idu u krajnost, nego da se drže srednjeg puta, kojim su išli i kojim idu oni kojima je Allah, dž.š., zadovoljan i kojima je darovao Svoje blagodati.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – ULOGA I VAŽNOST SREDNJEG PUTA</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p><strong>PITANJA I ZADACI</strong></p><ol><li><p>Šta je srednji put?</p></li><li><p>Koji su primjeri uravnoteženosti?</p></li><li><p>ZADATAK 1: Imaš dvojicu prijatelja od kojih je jedan redovan u džamiji ali skromnog materijalnog stanja. Drugi je iz bogate porodice, međutim rijetko ide u džamiju. Šta ćeš savjetovati jednom i drugom prijatelju?</p></li><li><p>ZADATAK 2: Napiši sastav o temi: Srednji put nije ponekad namaz obavljati!</p></li></ol><p><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">RAZGOVOR S MUALLIMOM</mark><br>Ne pretjerujem, ali i redovno obavljam svoje zadatke i obaveze.</p><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":51,"is_published":true,"kviz_pitanja":[{"answer":"Kao narod sredine, umjerenosti i uravnotezenosti","options":["Kao narod krajnosti i neravnoteže","Kao narod sredine, umjerenosti i uravnotezenosti","Kao narod bogatstva i moći","Kao narod samo duhovnosti"],"question":"Kako su Allah, dz.s., opisao muslimane u Kuranu?"},{"answer":"Traženje sredine i ravnoteže između dvije krajnosti","options":["Slijedi samo duhovnost i molitvu","Traženje sredine i ravnoteže između dvije krajnosti","Biranjem samo materijalne stvari i bogatstva","Izbjegivanjem svih vjerskih propisa"],"question":"Što je srednji put po definiciji?"},{"answer":"Ima presudni značaj za jedinstvo i harmoniju","options":["Nimalo važna za zajednicu","Ima mali značaj za jedinstvo","Ima presudni značaj za jedinstvo i harmoniju","Samo je važna za pojedince"],"question":"Koliko je važna uravnotezenost u prakticiranju vjerskih propisa?"},{"answer":"Rad za ovaj svijet i zalaganje za budući vijek","options":["Samo rad za budući vijek bez brige za ovaj svijet","Rad za ovaj svijet i zalaganje za budući vijek","Samo brinuti se o svojoj porodici","Ignorirati materijalne potrebe"],"question":"Prema Ayetu iz Sure El-Kasas, šta Islam od nas zahtijeva?"},{"answer":"U zalaganju za zajednicu i osobnu dužnost","options":["Samo u duhovnosti i molitvi","Samo u radu i zaradi","U zalaganju za zajednicu i osobnu dužnost","U izbjegivanju teških dužnosti"],"question":"Gdje trebamo pronići ravnoteži prema islamskom učenju?"}]},{"nivo":2,"slug":"teravih-namaz","naslov":"Teravih-namaz","content_html":"<div class=\"lesson-container\">\n<h1>TERAVIH-NAMAZ - RAMAZANSKI IBADET</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/teravih_namaz.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Teravih-namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema mubarek mjesecu Ramazanu i posebnim ibadetima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je teravih-namaz, kada se klanja, koliko ima rekata</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da klanja teravih-namaz u Ramazanu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je najmubarekniji mjesec? U Ramazanu, poslije jacije, klanja se poseban namaz – teravih. Šta o njemu znate?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Teravih-namaz je sunnet-namaz koji se klanja samo u mjesecu Ramazanu, poslije jacije, prije vitra.</p><p>Klanja se u 20 rekata, dva po dva (deset selama). Između svaka četiri rekata pravi se kratki odmor (otud naziv \"teravih\" – odmori).</p><p>Klanja se zajedno u džamiji za imamom – muslimani se okupljaju i slušaju Kur’an.</p><p>U mnogim džamijama imam u toku Ramazana prouči cijeli Kur’an na teravih-namazima – to je hatma.</p><p>Vrijednost: Poslanik, a.s., je rekao: <em>\"Ko klanja Ramazan u vjerovanju i nadi u nagradu, oprošteni su mu prijašnji grijesi.\"</em></p><p>Razgovor: Da li ste klanjali teravih? Kako ste se osjećali? Hoćete li klanjati ovog Ramazana?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici opisuju atmosferu u džamiji u Ramazanu. Zaključak: teravih je prilika za druženje sa Allahom i sa zajednicom.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":55,"is_published":true,"kviz_pitanja":[{"answer":"Namaz koji se klanja u nocima mjeseca ramazana","options":["Namaz koji se klanja u nocima mjeseca ramazana","Namaz koji se klanja samo u džamiji","Namaz koji se klanja prije fajr-namaza","Namaz koji se klanja pet puta dnevno"],"question":"Šta je teravih-namaz?"},{"answer":"Dvadeset rekata","options":["Deset rekata","Petnaest rekata","Dvadeset rekata","Trideset rekata"],"question":"Koliko rekata ima teravih-namaz?"},{"answer":"U jacijsko vrijeme nakon sunsunneta i prije vitr-namaza","options":["Prije sunsunneta i nakon vitr-namaza","U jacijsko vrijeme nakon sunsunneta i prije vitr-namaza","Između zuhr i asr-namaza","Prije fajr-namaza u ramazanu"],"question":"Kada se klanja teravih-namaz?"},{"answer":"Nakon svaka četiri ili svaka dva rekata","options":["Samo nakon svih dvadeset rekata","Nakon svakog reketa","Nakon svaka četiri ili svaka dva rekata","Nakon svakog trećeg reketa"],"question":"Kako se predaje selam kod teravih-namaza?"},{"answer":"Sunnet jacia-namaza","options":["Sunet fajd","Sunnet jacia-namaza","Sunnet vitr-namaza","Sunnet zuhr-namaza"],"question":"Koja je vrsta suneta teravih-namaz?"}]},{"nivo":2,"slug":"istina","naslov":"Važnost i snaga istine","content_html":"<div class=\"lesson-container\">\n<h1>VAŽNOST I SNAGA ISTINE</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/istina.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Važnost i snaga istine</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema istini i odbojnosti prema laži</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti vrijednost istinoljubivosti u islamu i njenu snagu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike govorenja istine u svim okolnostima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako se osjećate kada vam neko kaže istinu? A kad vam slaže? Šta je bolje – istina koja boli ili lijepa laž?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Istina je jedna od najvećih vrlina muslimana. Poslanik, a.s., zvao se <em>El-Emin</em> – Pouzdani, prije nego je dobio poslanstvo.</p><p>Allah u Kur’anu kaže: <em>\"O vjernici, bojte se Allaha i govorite samo istinu.\"</em></p><p>Istina vodi u dobro, a dobro vodi u Džennet. Laž vodi u grijeh, a grijeh u Vatru – kako je rekao Poslanik, a.s.</p><p>Istinu je ponekad teško reći, ali ona uvijek pobjeđuje. Lažac kad-tad bude otkriven i izgubi povjerenje.</p><p>Razgovor: Da li je nekad teško reći istinu? (kada se bojimo kazne) Šta je bolje – kazna ili gubitak povjerenja?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na istinu kao svoju životnu vrijednost. Učimo dovu za istinu (<em>Allahumme erinel-hakka hakkan...</em>).</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">ISTINA JE SILA <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Jeste li se nekada našli u situaciji da kažete nešto što nije istina, pa poslije osjetite nelagodu ili strah da se to ne otkrije? A kako se osjećate kada kažete istinu, pa makar bila i teška? Upravo taj osjećaj smirenosti pokazuje koliko je istina važna u našem životu.</p><p>Istina i iskrenost su temelj svakog ispravnog odnosa – prema Allahu i prema ljudima. U ovoj lekciji vidjet ćemo zašto islam toliko naglašava istinu i kako ona vodi čovjeka ka dobru i Allahovom zadovoljstvu.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Da bismo spoznali važnost istine, potrebno je prije svega znati da je iskrenost svojstvo koje nas vodi do istine. Istina je u životima ljudi veoma važna, a posebno je važna u životu vjernika.</p><p>Allah, dž.š., objavio nam je Kurʼan i u njemu je sve istina. Također, naš poslanik Muhammed, a.s., slijedio je Istinu koja je objavljena, a i sam je uvijek govorio samo istinu. Jednom prilikom pokazao je na svoja usta i rekao: “Tako mi Onoga u čijoj je Ruci moj život, iz njih izlazi samo istina.” (Ebu Davud)</p><p>Dužnost svakog muslimana i muslimanke je da govori istinu, jer ona vodi dobročinstvu, a dobročinstvo vodi u Džennet.</p><p>Naši roditelji, muallimi/e i učitelji/ce uče nas da volimo i uvijek govorimo istinu, te da je djelima potvrđujemo.</p><p>Istinoljubive osobe govore istinu, pa i kada je ona protiv njih. Muhammed, a.s., je rekao: “Reci istinu pa makar bila i gorka.” (Ahmed)</p><p>Adem, a.s., je boraveći u Džennetu pogriješio pa radi ljubavi prema istini priznao svoju grešku i zbog toga mu je Uzvišeni Allah oprostio njegov grijeh.</p><p>Ashab K‘ab ibn Malik je Muhammedu, a.s., rekao istinu o grešci koju je učinio pa ga je Poslanik, a.s., obradovao riječima da mu je Allah, dž.š., oprostio. Na to je Ka‘b ibn Malik kazao: “Allahov Poslaniče, Allah me je spasio zato što sam govorio istinu. Znak moga pokajanja je da, dok sam živ, govorim samo istinu.”</p><div class=\"arabic-card\"><p>Allah, dž.š., kaže: O vjernici, bojte se Allaha i budite sa onima koji su iskreni. (Et-Tevba, 119)</p></div><div class=\"info-box\"><p><strong>HADIS: </strong>Poslanik, alejhis-selam, je rekao: „Govorite istinu, jer istina vodi dobrocinjenstvou, a dobrocinjenstvo vodi u Dzennet.“ (Buhari)</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – VAŽNOST I SNAGA ISTINE</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <ol><li><p>Zašto je važno govoriti samo istinu?</p></li><li><p>Šta kaže Allah, dž.š., o iskrenima, a šta Poslanik, a.s., o iskrenosti?</p></li><li><p>Ko nas sve uči da govorimo i volimo istinu?</p></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">RAZGOVOR S MUALLIMOM</mark></strong></p><p>Poslovica: U laži su kratke noge!</p><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":56,"is_published":true,"kviz_pitanja":[{"answer":"Et-Tevba, 119","options":["Et-Tevba, 119","El-Fatiha, 1","Jakub, 28","Ja-Sin, 82"],"question":"Koji Kuran ajet govori o iskrenosti i strahu od Allaha?"},{"answer":"U Džennetu","options":["U Džennetu","U svijetu","Na zemlji","U Paklu"],"question":"Gdje je Adem, alejhis-selam, pogriješio?"},{"answer":"Istina","options":["Istina","Molitva","Susret","Ramazan"],"question":"Šta je prema hadisu svojstvo koje vodi dobrocinjenstvu?"},{"answer":"Roditelji, muallimi i učitelji","options":["Roditelji, muallimi i učitelji","Samo učitelji","Samo muallim","Samo prijatelji"],"question":"Ko nas uči da volimo i govorimo istinu?"},{"answer":"Samo istina","options":["Samo istina","Samo dobre riječi","Samo molitve","Samo savjeti"],"question":"Što je Muhammed, alejhis-selam, rekao da izlazi iz njegovih usta?"}]},{"nivo":2,"slug":"prevara","naslov":"Prevara, laž i krađa","content_html":"<div class=\"lesson-container\">\n<h1>PREVARA, LAŽ I KRAĐA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/prevara.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Prevara, laž i krađa</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje odbojnosti prema laži, prevari i tuđem haku</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti zašto su prevara, laž i krađa teški grijesi i kakve posljedice donose</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike izbjegavanja i tih i sličnih grijeha u svakodnevnom životu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je prevara? Šta je laž? Šta je krađa? Sve su to djela koja Allah strogo zabranjuje. Zašto?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Laž je govoriti suprotno od istine. Prevara je obmana drugoga radi vlastite koristi. Krađa je uzimanje tuđeg bez dozvole.</p><p>Sva tri djela ruše povjerenje među ljudima – temelj svakog društva.</p><p>Poslanik, a.s., je rekao: <em>\"Ko nas vara, nije od nas.\"</em></p><p>Krađa je posebno težak grijeh – uzimanje hakka drugog čovjeka. Sitno – velika krivica.</p><p>Allah na Sudnjem danu posebno pita za prava ljudi (<em>hukukul-‘ibād</em>) – ona se moraju vratiti, da bi se grijeh oprostio.</p><p>Razgovor: Da li sam nekad uzeo nešto tuđe? Da li sam nešto dužan vratiti? Lijepo je pojasniti – malo prepisivanje na testu je također prevara.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o pravima drugih ljudi koja moraju poštovati. Učimo dovu za zaštitu od grijeha jezika i ruku.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">LANAC KOJI POČINJE S LAŽJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Jeste li se nekada našli u situaciji da sakrijete istinu kako biste izbjegli problem? U tom trenutku možda izgleda lakše reći nešto što nije tačno, ali takva odluka često vodi u još veće poteškoće. Jedna mala laž može otvoriti vrata mnogim drugim lošim postupcima.</p><p>Zato je važno razumjeti kakvu ulogu istina ima u našem životu i zašto islam toliko upozorava na opasnost laži. U ovoj lekciji vidjet ćemo kako laž utiče na čovjeka i zašto je iskrenost temelj svakog ispravnog ponašanja.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Lijepe osobine koje krase naše ponašanje jesu cilj odgoja i obrazovanja, a loše osobine su one koje formiraju lošu sliku o nama. Među lošim osobinama posebno se ističe laž koja je početak mnogih drugih loših djela ali i osobina.</p><p>Laž je svjesno izgovorena neistina. Dvije stvari karakteriziraju laž i ukoliko se jave skupa, to znači da osoba boluje od opasne i teške bolesti duše:</p><ul><li><p>učestalosti kojom se osoba služi lažima u razgovoru sa drugim ljudima,</p></li><li><p>potpunim izostankom grižnje savjesti zbog izgovorene laži.</p></li></ul><p>Laž je osobina licemjera, pa se takve osobine ne smiju naći kod muslimana. Poslanik, a.s., je upitan o tome da li vjernik može biti kukavica pa je odgovorio da može. “Može li vjernik biti škrtac?” – “Može” – odgovorio je. “A može li vjernik biti lažac?” – “Ne može” – kazao je.</p><p>Čovjek je biće koje ima nedostatke pa tako može u svome ponašanju da ima neke osobine koje nisu svojstvene za vjernika. Međutim, vjernik ne smije biti lažljivac.</p><p>U izuzetnim situacijama u kojima je zajednica ili život pojedinca u pitanju, dozvoljava se izgovaranje neistine:</p><ul><li><p>u ratnim okolnostima</p></li><li><p>da bi se izmirila dvojica muslimana.</p></li></ul><p>Laž uvodi u druga loša djela kao što su prevara i krađa.</p><div class=\"arabic-card\"><p>Allah, dž.š., kaže: Usuđuju se da laži izmišljaju samo oni koji u Allahove riječi ne vjeruju, i oni su pravi lažljivci. (En-Nahl, 105)</p></div><p>Prevara je svjesna obmana drugog čovjeka i pokušaj skrivanja istinitih činjenica dok krađa predstavlja oduzimanje imovine druge osobe u bilo kojoj vrijednosti.</p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong><br>Laž je ključ svakog zla, jer ko laže on i krade, a ko krade on radi i druge velike grijehe.</p></div><p>I prevara i krađa nanose štetu ugledu, dostojanstvu ali i imetku drugoga čovjeka, te su stoga to grijesi za koje čovjek na ovom svijetu treba tražiti halala – oprosta od onog kome je učinjena šteta. Ukoliko se radi o materijalnoj šteti, obaveza je da se nadoknadi.</p><p>Za postupak krađe, prema propisima islama, postoji kazna i na ovom i budućem svijetu. U današnje vrijeme, kada je krađa mnogo raširena, ne postoji drugi način iskorjenjivanja ove opasne bolesti osim čvrsto uvjerenje da je to veliki grijeh za koji će se snositi određene posljedice.</p><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Događaj iz vremena Poslanika, a.s.</mark></strong></p><p>Neki čovjek je došao poslaniku Muhammedu, a.s., i rekao: “O Allahov Poslaniče, ja imam mnogo loših navika. Koju od njih najprije da ostavim?” Poslanik mu reče: “Prvo ostavi laž i uvijek govori istinu.” Čovjek je obećao da će tako učiniti i otišao kući.</p><p>Kad je pala noć, spremao se da ode u krađu. Ali prije nego što je izišao iz kuće, na trenutak se sjetio obećanja koje je dao Poslaniku: “Ako me sutra Poslanik upita gdje sam bio, šta ću reći? Hoću li reći da sam išao krasti? Ne, ja to ne mogu. Ali ne mogu ni lagati. Ako kažem istinu, svako će me mrziti i zvat će me lopovom, a biti ću kažnjen i za krađu.”</p><p>Tako je čovjek odlučio da ne krade te noći i ostavio je ovu lošu naviku. Sljedećeg dana poželio je piti vino, ali kad se spremao da to učini, pomisli: “Šta ću kazati Poslaniku ako me upita šta sam radio tokom dana? Ne mogu slagati, a ako kažem istinu, ljudi će me mrziti zato što muslimanu nije dozvoljeno piti vino.” I on je tako odustao od namjere piti vino.</p><p>I tako, kad god bi ovom čovjeku naumpalo da učini nešto loše, sjetio bi se svoga obećanja da će uvijek govoriti istinu. Na taj način je napuštao jednu po jednu lošu naviku.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – PREVARA, LAŽ I KRAĐA</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p><strong>PITANJA I ZADACI</strong></p><ol><li><p>Šta je to laž i u koje grijehe ona vodi?</p></li><li><p>U kojim životnim situacijama osoba smije izgovoriti laž?</p></li><li><p>ZADATAK: Pročitajte događaj iz vremena Poslanika, alejhis-selam, i napišite pitanja u mektebsku bilježnicu. Zatim pitanja razmijenite sa prijateljem/icom u klupi i odgovorite na ta pitanja.</p></li></ol><div class=\"info-box\"><p><strong>IZABERI ZADAĆU!</strong><br>1. Objasni šta za tebe predstavljaju istina, a šta prevara, laž i krađa.<br>2. Koliko često razmišljaš o posljedicama svojih dijela?</p></div><table style=\"width: 880px;\"><colgroup><col style=\"width: 434px;\"><col style=\"width: 115px;\"><col style=\"width: 111px;\"><col style=\"width: 111px;\"><col style=\"width: 109px;\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"434\"><p>DJELA</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"115\"><p>UVIJEK</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p>ČESTO</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p>PONEKAD</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"109\"><p>NIKAD</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"434\"><p>Lažem da sam bio bolestan kada ne dođem u mekteb</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"115\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"109\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"434\"><p>Ne kažem svu istinu svojim roditeljima/ukućanima</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"115\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"109\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"434\"><p>Zeznem svoga brata/sestru jer želim da je meni bolje</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"115\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"109\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"434\"><p>Izgovaram ružne riječi/psovku kada se naljutim</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"115\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"109\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"434\"><p>Vješt sam u prepisivanju kada je test u mektebu</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"115\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"111\"><p></p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"109\"><p></p></td></tr></tbody></table><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":57,"is_published":true,"kviz_pitanja":[{"answer":"Oni su pravi lazljivci","options":["Oni su pravi lazljivci","Oni su hrabri ljudi","Oni su pametni","Oni su dobri"],"question":"Šta Allah, dz.s., kaže o onima koji izmišljaju laži?"},{"answer":"Čestotina i odsustvo grize savjesti","options":["Čestotina i odsustvo grize savjesti","Ljepota i istina","Jačina i brzina","Boja i veličina"],"question":"Koje dvije stvari karakteriziraju laz?"},{"answer":"U ratnim okolnostima i pomirenju muslimana","options":["U ratnim okolnostima i pomirenju muslimana","Kada je teško biti iskren","Kada želimo dobar результat","Nikada nije dozvoljeno"],"question":"U kojim situacijama je Islam dozvolio izgovaranje neistine?"},{"answer":"Svjesna obmana drugog čovjeka","options":["Svjesna obmana drugog čovjeka","Slučajna greška","Čestit čin","Dobronamjerna laž"],"question":"Šta je prevara?"},{"answer":"Laž","options":["Laž","Ljutnja","Neznanje","Siromaštvо"],"question":"Što je prema islamu ključ svakog zla?"}]},{"nivo":2,"slug":"ponasanje-drustvo","naslov":"Ponašanje u društvu","content_html":"<div class=\"lesson-container\">\n<h1>PONAŠANJE U DRUSTVU</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/ponasanje_drustvo.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ponašanje u društvu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje lijepog ahlaka prema svim ljudima u različitim društvenim situacijama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti adabe ponašanja u društvu (sa drugovima, u školi, na ulici, u javnom prevozu)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika lijepog ponašanja u javnosti kao predstavnik islama</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako se ponašate kad ste sa drugovima? A na ulici? U autobusu? Naše ponašanje govori o nama – i o našoj vjeri.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Musliman je ogledalo islama – kako se on ponaša, tako ljudi gledaju islam.</p><p>U društvu: nazivamo selam, smiješimo se, govorimo lijepe riječi, ne ogovaramo, ne psujemo.</p><p>Na ulici: ne smetamo prolaznicima, pomažemo starijim, ustupamo mjesto, ne bacamo smeće.</p><p>U javnom prevozu: ustupamo sjedište starijima, trudnicama, ne pričamo glasno, ne smetamo drugima.</p><p>Sa drugovima: dijelimo, ne se svađamo, branimo slabije, ne podsmijehujemo se.</p><p>Poslanik, a.s., je rekao: <em>\"Najbolji od vas su oni koji su najboljeg ahlaka.\"</em></p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici biraju jedan adab koji će ovaj tjedan posebno paziti. Razgovor o tome kako se ljudi osjećaju kad nam je ahlak lijep.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">PRAVILA ISLAMSKOG DRUŽENJA <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Svaki čovjek svakodnevno boravi među ljudima – u porodici, školi, džematu ili među prijateljima. Način na koji se ponašamo u društvu govori mnogo o nama i ostavlja utisak na druge. Nekada i male stvari, poput pozdrava, osmijeha ili lijepih riječi, mogu učiniti da se neko osjeća prihvaćeno i poštovano.</p><p>Zato islam nije ostavio čovjeka bez upute, nego je jasno pokazao kako se treba ponašati u društvu. U ovoj lekciji vidjet ćemo koje su to lijepe osobine i postupci koje trebamo njegovati, ali i šta trebamo izbjegavati.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Islam je postavio jasne propise za svaki čovjekov postupak. Propisi islama nisu samo propisi prema Uzvišenom Allahu, već duboko zadiru u sve dijelove čovjekovog pojedinačnog, ali i društvenog života.</p><p>U društvu trebamo se ponašati onako kako bismo željeli da se drugi ponašaju prema nama. Islamski način ponašanja podrazumijeva da:</p><ul><li><p>nastojimo biti čisto i lijepo odjeveni</p></li><li><p>prilikom dolaska u društvo, ali i prilikom odlaska, poselamimo prisutne, odnosno one koji ostaju</p></li><li><p>sjedamo na slobodno mjesto ili tamo gdje nam domaćin kaže</p></li><li><p>budemo vedra i nasmijana lica</p></li><li><p>razgovaramo o lijepim i korisnim temama</p></li><li><p>spomenemo Allaha, dž.š.</p></li><li><p>spomenemo Muhammeda, a.s., i donesemo salavat na njega</p></li><li><p>proučimo dovu</p></li></ul><div class=\"arabic-card\"><p>Allah, dž.š., kaže: O vjernici, klonite se mnogih sumnjičenja, neka sumnjičenja su, zaista, grijeh. I ne uhodite jedni druge i ne ogovarajte jedni druge! (El-Hudžurat, 12)</p></div><div class=\"info-box\"><p>HADIS</p><p>Poslanik, a.s., je rekao: “Nepotpun je postupak ljudi koji se nađu na nekom skupu i tom prilikom ne spomenu Allaha niti donesu salavat na Njegovog Poslanika. Allahovo je da ih kazni za to ili da im oprosti!” (Tirmizi)</p></div><p>Posebno trebamo paziti da ne uradimo nešto što je islam zabranio:</p><ul><li><p>ne ulaziti u kuću bez dozvole</p></li><li><p>ne tražiti od drugoga da sjednemo na njegovo mjesto</p></li><li><p>ne razdvajati dvije osobe bez njihove dozvole</p></li><li><p>ne uznemiravati druge u društvu</p></li><li><p>ne sašaptavati se u društvu</p></li><li><p>ne pričati i ne smijati se pretjerano glasno</p></li><li><p>ne ogovarati nikoga u društvu</p></li><li><p>ne prenositi tuđe riječi</p></li><li><p>ne imitirati druge</p></li></ul><div class=\"info-box\"><p><strong>HADIS</strong></p><p>Muhammed, a.s., je objašnjavajući postupak ulaska kod nekoga i ponašanja na skupu rekao: “Kada neko od vas traži dopuštenje za ulazak, neka to učini tri puta pa ako mu se ne dozvoli, neka se vrati!” (Buhari)</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – PONAŠANJE U DRUSTVU</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <ol><li><p>Šta podrazumijeva islamski način ponašanja?</p></li><li><p>Koji su zabranjeni postupci kada je u pitanju ponašanje u društvu?</p></li><li><p>ZADATAK: Nauči hadise Poslanika, alejhis-selam, u kojima on objašnjava postupak ulaska kod nekoga i ponašanja na nekom skupu!</p></li></ol><p><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">IZABERI ZADAĆU!</mark></p><ol><li><p>Pronađi u Kuranu 12. ajet sure El-Hudžurat i napiši ga. Razgovaraj sa muallimom i roditeljima o navedenom ajetu.</p></li><li><p>Napiši sastav o temi: Moje ponašanje u društvu.</p></li><li><p>Razmisli i napiši zašto se nekada osjećamo usamljeno iako smo u drustvu?</p></li></ol><div class=\"info-box\"><p><strong>RAZGOVOR S MUALLIMOM</strong><br>Sohbet, sijelo i muhabbet.</p></div><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":58,"is_published":true,"kviz_pitanja":[{"answer":"Jedno drugome uhoditi i ogavrajati se","options":["Jedno drugome uhoditi i ogavrajati se","Biti čisto i lijepo odjeveni","Poselamiti prisutne","Razgovarati o lijepim temama"],"question":"Šta Allah, dž.s., kaže da trebamo izbjeći u društvu?"},{"answer":"Vedra i nasmijana lica","options":["Tužni i ozbiljni","Vedra i nasmijana lica","Samo da razgovaramo","Šutljivi i mirni"],"question":"Kako trebamo biti kada dolazimo u društvo?"},{"answer":"Tri puta","options":["Samo jednom","Dva puta","Tri puta","Koliko god puta trebamo"],"question":"Koliko puta trebamo zatražiti dozvolu da uđemo u kuću?"},{"answer":"Šapatanje i prenosenje tuđih riječi","options":["Sjećanje na Allaha","Donošenje salavata","Šapatanje i prenosenje tuđih riječi","Vedra lica"],"question":"Što je zabranjeno u društvu prema islamskom učenju?"},{"answer":"Poselamiti prisutne","options":["Odmah sjediti gdje nam se sviđa","Poselamiti prisutne","Razgovarati o tuđim greškama","Biti veoma glasni"],"question":"Što trebamo uraditi prilikom dolaska u društvo?"}]},{"nivo":2,"slug":"kultura","naslov":"Kultura i tradicija","content_html":"<div class=\"lesson-container\">\n<h1>KULTURA I TRADICIJA BOŠNJAKA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/kultura.jpg\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kultura i tradicija</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje poštovanja prema vlastitoj kulturi i tradiciji u okvirima islama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta je kultura, šta tradicija, te razlikovati dobre i loše običaje</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o očuvanju lijepih običaja koji su u skladu sa islamom</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta sve čini našu bošnjačku kulturu? Koje običaje imate u porodici? Šta je tradicija? Da li su sve tradicije dobre?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kultura je sve što čovjek stvara: jezik, knjige, muzika, arhitektura, hrana, običaji.</p><p>Tradicija je ono što se prenosi sa generacije na generaciju – običaji, vjerovanja, postupci.</p><p>Bošnjačka islamska tradicija je bogata: ezan sa munare, mevludi, prolaska sevapa, dženaze, davanja sadake, pomaganja komšija.</p><p>Islam podržava sve tradicije koje su u skladu sa Kur’anom i Sunnetom. Ono što je u suprotnosti – mijenja se ili odbacuje.</p><p>Naša obaveza je čuvati i njegovati lijepe običaje naših djedova – mevludi, druženja, posjete bolesnima.</p><p>Razgovor: Koje običaje imate kod kuće za Ramazan, Bajram, mevlud? Kako ih nastaviti i prenijeti?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju lijepe običaje svoje porodice. Zaključak: naš identitet je u našoj vjeri i kulturi koje moramo čuvati.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":65,"is_published":true,"kviz_pitanja":[{"answer":"Složena cjelina koja uključuje znanja, vjerovanja, umjetnost i običaje","options":["Samo tradicionalna hrana i napitci jednog naroda","Složena cjelina koja uključuje znanja, vjerovanja, umjetnost i običaje","Samo jezik koji govori jedan narod","Grupa ljudi koja živi u istoj državi"],"question":"Šta je kultura?"},{"answer":"Kroz usmenoj predaji znanja, vještina i običaja","options":["Samo kroz pisane knjige i dokumenta","Kroz usmenoj predaji znanja, vještina i običaja","Samo kroz vjerske molitve i obrede","Kroz glasine i priče za koju se ne zna odakle dolaze"],"question":"Kako se tradicija prenosi sa generacije na generaciju?"},{"answer":"Bujrum","options":["Ceif","Jemin","Bujrum","Divan"],"question":"Koja je specifična bosanska riječ koja govori o prijemu gostiju?"},{"answer":"Specifičan odnos prema uživanju u životu","options":["Dato obećanje i zakletva","Poziv na druženja i dobrodosnicu","Specifičan odnos prema uživanju u životu","Poseban način oblačenja i ponašanja"],"question":"Šta znači riječ 'ceif' u bosanskoj kulturi?"},{"answer":"Teritorija, država, kultura, tradicija i jezik","options":["Samo bogatstvo i tehnologija","Teritorija, država, kultura, tradicija i jezik","Samo religija i vjerske tradicije","Samo brojnost stanovništva"],"question":"Koji su bitni dijelovi identiteta svakog naroda?"}]},{"nivo":2,"slug":"bosnjak","naslov":"Ja sam Bošnjak/Bošnjakinja","content_html":"<div class=\"lesson-container\">\n<h1>JA SAM BOŠNJAK/BOŠNJAKINJA</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/bosnjak.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ja sam Bošnjak/Bošnjakinja</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ponosa na vlastiti identitet, vjeru i nacionalnu pripadnost</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojmove identiteta: vjerski (musliman), nacionalni (Bošnjak), jezički (bosanski jezik)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje samopouzdanja i odgovornosti prema vlastitoj zajednici</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko ste vi? Bošnjak, musliman, učenik, sin, kćer... Svako od nas ima više identiteta. Šta znači biti Bošnjak/Bošnjakinja?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Identitet je odgovor na pitanje \"Ko sam ja?\" Ima više slojeva: vjerski (musliman), nacionalni (Bošnjak), porodični, građanski.</p><p>Bošnjaci su narod sa dugom historijom u Bosni i Hercegovini, prepoznatljiv po islamu, bosanskom jeziku i bošnjačkoj kulturi.</p><p>Naši preci su islam prihvatili svojevoljno i čuvali ga kroz vjekove, čak i u najtežim vremenima.</p><p>Biti Bošnjak/Bošnjakinja znači čuvati svoju vjeru, jezik, kulturu i pomagati svojoj zajednici.</p><p>Naš identitet ne smije biti razlog za umišljanje ili omalovažavanje drugih – Allah nas je sve stvorio kao narode da se upoznajemo.</p><p>Razgovor: Po čemu se ponosim svojim identitetom? Šta mogu uraditi za svoju zajednicu?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici opisuju šta najviše vole u svom narodu i kulturi. Zaključak: ponosni smo na ono što jesmo i odgovorni za ono što nam je povjereno.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">PONOS I AMANET <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Hajde da vidimo nešto jednostavno. Kada igra reprezentacija, za koga navijaš? Kad neko spomene Bosnu, osjetiš li nešto u sebi? A kada čuješ riječ “Bošnjak” — šta to za tebe znači?</p><p>Nije isto reći gdje živiš i ko si. Danas ćemo razjasniti upravo to — razliku između države, nacije i naroda, i gdje mi tu pripadamo.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Čovjek je društveno biće čiji je razvoj i postojanje na dunjaluku ovisno o zajednici sa kojom se on identificira. Kroz historiju nije postojao narod koji nije imao svoju zajednicu i društvenu hijerarhiju. Tako su nastale skupine ljudi koji žive na određenom teritoriju čineći jednu državu i naciju. One skupine koje se identificiraju po istoj kulturi i tradiciji, običajima i prošlošću ‒ nazivamo narodima.</p><p>Mi pripadamo bosanskohercegovačkoj naciji ‒ stanovnici smo domovine Bosne i Hercegovine i bošnjačkom narodu koji njeguje dug kontinuitet i historiju. Bošnjaci su južnoslavenski narod koji vodi porijeklo od srednjovjekovnih Bošnjana – Slavena koji su naseljavali prostor Bosne, te su bili različitih religija. Sam naziv Bošnjak vodi porijeklo od istoimene države i rijeke Bosne.</p><p>Bošnjački narod danas naseljava područje Bosne i Hercegovine, Sandžaka, Turske ‒ Bošnjaci koji su odselili povlačenjem Osmanskog carstva sa područja Bosne, te mnogobrojne zemlje zapadne Evrope i drugih kontinenata.</p><p>Ovakva raseljenost naroda po cijelom svijetu uglavnom je rezultat nasrtaja i teških zločina koje je preživio bošnjački narod, ali je i dalje ostao vjeran svojoj bosanskohercegovačkoj naciji i bošnjačkom narodu, ma gdje živio. Ta specifična povezanost sa nacijom i narodom nas čini jedinstvenim narodom na evropskom tlu.</p><p>Bošnjački narod je islamske vjere i baštini bošnjačku kulturu i tradiciju, a koja sadrži neizbrisive tragove onih kultura i tradicija koje su se smjenjivale na ovim prostorima od vremena srednjovjekovne Bosne i starih Bošnjana, pa do danas.</p><p><strong>Šehidi</strong> koji su dali svoje živote za opstanak svog bošnjačkog naroda i vjere islama daju nam dodatnu obavezu da volimo, poštujemo i čuvamo svoju domovinu Bosnu i Hercegovinu, svoju bosanskohercegovačku naciju i bošnjački narod. Njegovanjem svoje kulture i tradicije Bošnjaci će i dalje odolijevati nasrtajima na svoju domovinu i narod pa će tako i dalje bilježiti svoj dugi kontinuitet i bogatu historiju.</p><div class=\"info-card\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong></p><ol><li><p style=\"text-align: center;\">Bosanac i Hercegovac je naziv za pripadnika bosanskohercegovačke ‒ bosanske nacije. Bosanskohercegovačku naciju čine svi stanovnici Bosne i Hercegovine čija je ona domovina.</p></li><li><p style=\"text-align: center;\">Bošnjak je naziv za pripadnika bošnjačkog naroda. Pripadnici bošnjačkog naroda osjećaju Bosnu i Hercegovinu svojom matičnom domovinom i po nacionalnosti su Bosanci i Hercegovci.</p></li></ol></div><h3 style=\"text-align: center;\"><strong>JA SAM BOŠNJAK</strong></h3><p style=\"text-align: center;\">Ja sam Bošnjak – dičan junak:<br>Vjeran svetom domu svome,<br>Vjeran slavi svojih djeda<br>I narodu bosanskome!</p><p style=\"text-align: center;\">Njegov ponos na mom srcu<br>Ko amanet sveti stoji;<br>Ponos koji nigdje ne da,<br>da se Bošnjak lava boji!</p><p style=\"text-align: center;\">...</p><p style=\"text-align: center;\">Izdajicu uspomeni<br>Svojih djela slave stare,<br>Što se drznʼo blatnom rukom,<br>Da svetinje njine tare!</p><p style=\"text-align: center;\">...</p><p style=\"text-align: center;\">A Ti sakri mrsko lice<br>Ispred svʼjeta cijeloga:<br>U podzemlje mračno bježi,<br>Izdajico roda svoga!</p><p style=\"text-align: center;\">Jer nad tobom rodnog neba<br>Zlatnog sunca plaču zrake,<br>Plače jasna mjesečina<br>I treptanje zvjezde svake,<br>Plače svaki zemni atom,<br>Na kog tvoja noga stane;<br>Svaka travka tebi kliče:<br>Izdajica, nek propane!</p><p style=\"text-align: center;\">Sakrij lice izdajico,<br>Nek ne pljuju ljudi na te,<br>A znaj i to: Izdajicu<br>I pod zemljom klevete prate!…</p><p style=\"text-align: center;\">(Musa Ćazim Ćatić)</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – JA SAM BOŠNJAK/BOŠNJAKINJA</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <ol><li><p>Koja je naša nacija, a koja narodnost?</p></li><li><p>Zasto je važno da smo svjesni svoje narodnosti?</p></li><li><p>ZADATAK: Razgovaraj sa svojim roditeljima o šehidu iz tvoje porodice ili komšiluka i napiši njegovu biografiju u svoju mektebsku svesku!</p></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">RAZGOVOR S MUALLIMOM</mark></strong><br>Pročitajte i razgovarajte o poemi „Ja sam Bošnjak“ Muse Ćazima Ćatića!</p><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('section-1775141862275', this)\">DODATAK <span class=\"section-icon\">▶</span></button>\n        <div id=\"section-1775141862275\" class=\"lesson-content\">\n            <p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">IZABERI ZADAĆU!</mark></strong></p><p>1. Napiši sastav o temi Ja sam ponosni Bošnjak/Bošnjakinja!</p><p>2. Pročitaj i napiši pouke iz navedene poeme Ja sam Bošnjak.</p><p>3. Na panou nacrtaj granice Bosne i Hercegovine i unutar njih napiši osobine Bošnjaka koje zna</p><p>4. Nauči kompoziciju ''Devet heroja'', link: <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"https://www.youtube.com/watch?v=P5Lr4fhjHjY\">https://www.youtube.com/watch?v=P5Lr4fhjHjY</a></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":66,"is_published":true,"kviz_pitanja":[{"answer":"Od istoimene države i rijeke Bosne","options":["Od rijeke Drine i srednjovjekovne države","Od istoimene države i rijeke Bosne","Od imena bosanskog kralja","Od turskog jezika i kulture"],"question":"Od čega potječe naziv Bošnjak?"},{"answer":"Islamska vjera","options":["Pravoslavna vjera","Katolicizam","Islamska vjera","Protestantizam"],"question":"Koja je vjera bosnjačkog naroda?"},{"answer":"Bosna, Hercegovina, Sandžak i dijelovi Europe","options":["Samo Srbija i Crna Gora","Bosna, Hercegovina, Sandžak i dijelovi Europe","Samo zapadna Evropa","Samo Turska"],"question":"Koji prostori su domovina Bošnjaka?"},{"answer":"Pripadnik bosansko-hercegovacke nacije","options":["Pripadnik samo jednog naroda","Pripadnik bosansko-hercegovacke nacije","Stanovnik samo Hercegovine","Podanak osmanske države"],"question":"Šta je Bosanac i Hercegovac po nacionalnosti?"},{"answer":"Tragovi kultura od srednjovjekovne Bosne","options":["Samo turska kultura","Samo evropska kultura","Tragovi kultura od srednjovjekovne Bosne","Samo rimska kultura"],"question":"Koja kultura i tradicija se nalazi u bosnjačkoj tradiciji?"}]},{"nivo":2,"slug":"lekad-dzaekum","naslov":"Lekad džāekum","content_html":"<div class=\"lesson-container\">\n<h1>LEKAD DŽĀEKUM S PRIJEVODOM</h1><div class=\"hero-box\"><img src=\"/edu/assets/images/lekad_dzaekum.jpg\"></div>\n    \n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Lekad džāekum (sura Et-Tevbe, ajet 128)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Poslaniku Muhammedu, a.s., i njegovom blagom karakteru</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst i značenje ajeta \"Lekad džāekum...\" iz sure Et-Tevbe</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno izgovara i razumije ovaj ajet</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je nama poslan kao milost svjetovima? Allah je u Kur’anu opisao Poslanika, a.s., posebnim ajetom. Hajde da ga naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ajet \"Lekad džāekum\" nalazi se u suri Et-Tevbe, ajet 128.</p><p>Tekst (transkripcija): <em>Lekad džāekum resūlun min enfusikum, azīzun alejhi mā anittum, harīsun alejkum, bil-mu’minīne raūfun-rahīm.</em></p><p>Značenje: <em>\"Doista vam je došao Poslanik od vas samih, teško mu je što ćete vi na muke udariti, jedva čeka da pravim putem pođete, a prema vjernicima je blag i milostiv.\"</em></p><p>Ovaj ajet opisuje Poslanika, a.s., kao: <strong>od nas samih</strong> (čovjeka kao i mi), <strong>teško mu je naš svaki promašaj</strong>, <strong>silno želi naše dobro</strong>, <strong>blag je i milostiv</strong>.</p><p>Postupak: Pišem ajet na tabli arapskim pismom. Učimo izgovor riječ po riječ. Razgovaramo o značenju svake riječi.</p><p>Učimo o lijepim osobinama Poslanika, a.s., i kako ga slijediti.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici proučavaju ajet u horu i pojedinačno. Zadaća: učiti ajet svaki dan dok se ne nauči napamet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">POSLANIK KOJI TE VOLI <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Postoji li neko kome je stvarno stalo do tebe – ali ne samo kad ti je dobro, nego i kad pogriješiš, kad kreneš lošim putem, kad sam sebi praviš probleme?</p><p>Zamisli osobu kojoj je teško kad tebi bude teško. Koja želi tvoje dobro čak i kad ti to ne vidiš. Takav je bio Poslanik, a.s., prema svom ummetu.</p><p>Ova dva ajeta govore upravo o toj brizi, toj ljubavi i o tome kome se čovjek vraća kada ga drugi ne razumiju.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">►</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Posljednja dva ajeta sure Et-Tevbe, objavlene u Medini, sure koja sadrzi 129 ajeta.</p><div class=\"arabic-card\"><p style=\"text-align: center;\"><strong>BISMILLAHIR-RAHMANIR-RAHIM</strong></p><p style=\"text-align: center;\">LEKAD DŽAEKUM RESULUN MIN ENFUSIKUM ‘AZIZUN ‘ALEJHI MA ‘ANITTUM HARISUN ‘ALEJKUM BIL-MU’MININE RE’UFUN RAHIM</p><p style=\"text-align: center;\">FE’IN TEVELLEV FEKUL HASBIJALLAHU LA ILAHE ILLA HUVE ‘ALEJHI TEVEKKELTU VE HUVE RABBUL-‘ARŠIL-‘AZIM</p></div><div class=\"info-box\"><p style=\"text-align: center;\"><strong>Prijevod:</strong><br>U ime Allaha, Milostivog, Samilosnog!</p><p style=\"text-align: center;\">Došao vam je Poslanik, jedan od vas, teško mu je što ćete na muke udariti, jedva čeka da Pravim putem pođete, a prema vjernicima je blag i milostiv.</p><p style=\"text-align: center;\">A ako oni glave okrenu, ti reci: “Meni je dovoljan Allah, nema boga osim Njega; samo se uzdam u Njega, On je Gospodar svemira veličanstvenoga!”</p></div><p>U posljednja dva ajeta sure Et-Tevbe spomenuta je velika Božija blagodat. Allah, dž.š., je poslao Poslanika da bi ljude pozivao na Pravi put. Njegov Poslanik, a.s., toliko voli svoje sljedbenike da mu je teško kada ih zadesi iskušenje. On je prema njima i blag i milostiv.</p><p>Međutim, ako ljudi neće da ga slijede, Allahovom Poslaniku, a.s., dovoljan je Allah, osim Njega drugog Boga nema. On je Gospodar svemira veličanstvenog.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">►</span></button>\n        <div id=\"quiz-section\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                <h2 class=\"quiz-title\">KVIZ – LEKAD DŽĀEKUM S PRIJEVODOM</h2>\n                <div id=\"question-container\"><p class=\"quiz-question\" id=\"q-text\"></p><div class=\"quiz-options\" id=\"q-options\"></div></div>\n                <div id=\"quiz-res\" class=\"quiz-results\"></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">►</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <ol><li><p>Iz koje sure su ovi ajeti i koliko ima ajeta ta sura?</p></li><li><p>Šta govori prvi, a šta drugi ajet?</p></li><li><p>Koja je poruka ovih ajeta?</p></li><li><p>ZADATAK: Nauči ova dva ajeta napamet i uvježbaj ih sa muallimom!</p></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":67,"is_published":true,"kviz_pitanja":[{"answer":"Sure Et-Tevbe","options":["Sure El-Fatiha","Sure Et-Tevbe","Sure Jasina","Sure El-Ihlasa"],"question":"Iz koje sure su ajeti ''Lekad džaekum''?"},{"answer":"129 ajeta","options":["99 ajeta","114 ajeta","129 ajeta","156 ajeta"],"question":"Koliko ajeta sadrži sura Et-Tevbe?"},{"answer":"O Poslaniku koji je jedan od nas","options":["O blagajima i bogatstvu","O Poslaniku koji je jedan od nas","O molitvi i roditeljima","O hadždžu i putovanju"],"question":"Šta govori prvi ajet ''Lekad džaekum''?"},{"answer":"Blag i milostiv","options":["Strogar i strog","Blag i milostiv","Odlučan i ozbiljan","Tužan i žalostan"],"question":"Kako je Poslanik prema vjernicima prema ovim ajetima?"},{"answer":"Allah je dovoljan ako te napuste","options":["Moraš se ženiti","Allah je dovoljan ako te napuste","Moraš biti bogat","Moraš biti vojnik"],"question":"Šta je poruka drugog ajeta ''Lekad džaekum''?"}]},{"nivo":3,"slug":"duznosti-allah","naslov":"Izvršavanje dužnosti prema Allahu","content_html":"<div class=\"lesson-container\">\n        <h1>IZVRŠAVANJE DUŽNOSTI PREMA ALLAHU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/izvrsavanje_duznosti.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Izvršavanje dužnosti prema Allahu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o dužnostima prema Allahu i navike njihovog izvršavanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta su dužnosti čovjeka prema Allahu i kako se ispunjavaju</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike svakodnevnog ibadeta i čuvanja granica</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta dugujemo Allahu za sve blagodati koje nam je dao? Hajde da razgovaramo o dužnostima čovjeka prema Allahu.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Naše osnovne dužnosti prema Allahu su: vjerovati u Njega, obožavati Ga (klanjati, postiti, dijeliti zekat, hadž), zahvaljivati Mu, pokoravati Mu se, voljeti Ga iznad svega.</p><p>Svako stvorenje ima Stvoritelja, a najveća čast čovjeka je da spozna i obožava svog Stvoritelja.</p><p>Allah je rekao: \"Ja sam džine i ljude stvorio samo zato da Mi ibadet čine.\"</p><p>Izvršavanje dužnosti čini čovjeka srećnim, smirenim i ispunjenim.</p><p>Razgovor: koje dužnosti smo danas izvršili?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju 3 svoje dužnosti prema Allahu i obavezuju se da ih čuvaju ovaj tjedan.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PUTOKAZI SREĆE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                \n                <div class=\"lesson-text\">\n                    <p>Zamislite da idete na jedno veoma važno putovanje, a pred vama se nalazi mnogo različitih staza. Kako ćete znati koja je ona prava koja vodi do cilja? Upravo tako izgleda naš životni put.</p>\n                    <p>Naš Stvoritelj nam je, iz Svoje velike ljubavi, postavio jasne putokaze. Ti putokazi su naše dužnosti. One nisu tu da nas opterete, već da nam osvijetle stazu i učine nas sretnim. Kada klanjamo, postimo ili činimo dobro, mi zapravo gradimo najljepšu verziju sebe.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <i>Allah, dž.š., kaže: O vjernici pokoravajte se Allahu... (En-Nisa, 59)</i>\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Uzvišeni Allah je muslimane i muslimanke zadužio određenim dužnostima koje trebaju redovno činiti i biti ustrajni u njihovom izvršavanju. Neke od tih dužnosti su na stepenu farza, tj. naređene su kao stroge islamske dužnosti. To su:\n                </p>\n                \n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: disc;\">\n                    <li>Kelimei-šehadet – očitovanje pripadnosti islamu,</li>\n                    <li>namaz – redovna molitva,</li>\n                    <li>post – suzdržavanje od hrane i pića, te drugih tjelesnih uživanja,</li>\n                    <li>zekat – islamska imovinska dužnost,</li>\n                    <li>hadž – hodočašće Kabe i drugih svetih mjesta.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Pored glavnih islamskih dužnosti, postoje i druge koje su na stepenu vadžiba i nisu strogo naređene kao farz (klanjati vitr-namaz i bajram-namaz, žrtvovati kurban te dijeliti sadekatul-fitr prije klanjanja bajram-namaza). Izvršavanjem dužnosti prema Allahu, dž.š., vjernik ima koristi na ovom svijetu <span style=\"background-color: #fff9c4;\">dunjaluku</span> i na budućem svijetu <span style=\"background-color: #fff9c4;\">ahiretu</span>. Allah, dž.š., je neovisan o tome da li ćemo spomenute dužnosti izvršavati ili ne. One su naređene zato što oplemenjuju ljudska srca i moralno uzdižu izvršioca.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Svaka islamska dužnost djeluje odgojno, tj. ima za cilj da nas učini boljim i potpunijim čovjekom. Tako nas namaz odvraća od onoga što je loše, post nas čini bogobojaznijim, zekat darežljivijim, a hadž čini vjernike moralnijima. Izvršavanjem dužnosti prema Allahu, dž.š., čovjek postaje Allahov rob, a biti Allahov rob znači biti najslobodnije biće na Zemlji. Da bismo izvršavali spomenute dužnosti, potrebno je i sljedeće:\n                </p>\n\n                <p class=\"lesson-text\">\n                    • <span style=\"background-color: #fff9c4;\">Vjerovati u Allaha, dž.š., čvrsto i nepokolebljivo.</span> Muhammed, alejhis-selam, nas uči da u Allaha trebamo vjerovati kao da Ga vidimo, jer ako mi Njega ne vidimo, On nas zaista vidi. <i>Allah, dž.š., kaže: O vjernici, vjerujte u Allaha. (En-Nisa, 136)</i>\n                </p>\n\n                <p class=\"lesson-text\">\n                    • <span style=\"background-color: #fff9c4;\">Voljeti Ga</span> – ljubav prema Allahu, dž.š., je jača i veća od svake druge ljubavi. <i>Allah, dž.š., kaže: Ima ljudi koji su umjesto Allaha kumire prihvatili, vole ih kao što se Allah voli, ali pravi vjernici još više vole Allaha. (El-Bekare, 165)</i>\n                </p>\n\n                <p class=\"lesson-text\">\n                    • <span style=\"background-color: #fff9c4;\">Sjećati Ga se i Allaha stalno spominjati</span>, tj. da Allahu, dž.š., zikr činimo. Spominjanje Allaha, dž.š., treba biti rezultat stalne svijesti o Bogu. <i>O vjernici, često Allaha spominjite i hvalite, i ujutro i navečer Ga veličajte. (El-Ahzab, 41-42)</i>\n                </p>\n\n                <p class=\"lesson-text\">\n                    • <span style=\"background-color: #fff9c4;\">Zahvaljivati Mu na blagodatima koje nam je podario</span> – Allahove blagodati su nebrojene i zato moramo biti zahvalni na svemu što nam je podario. Zahvalnost Allahu, dž.š., se iskazuje riječima i djelima. <i>Allah vas iz trbuha majki vaših izvodi, vi ništa ne znate i daje vam sluh i vid i razum da biste bili zahvalni. (En-Nahl, 78)</i>\n                </p>\n\n                <p class=\"lesson-text\">\n                    • <span style=\"background-color: #fff9c4;\">Kloniti se onoga što je Allah, dž.š., zabranio</span> – zabranjenih radnji se moramo čuvati jer je u njima šteta, za pojedinca i za zajednicu. <i>...a razvrat i sve što je odvratno i nasilje zabranjuje, da pouku primite, On vas savjetuje. (En-Nahl, 90)</i>\n                </p>\n                            <img src=\"/edu/assets/images/estagfirullah.jpg\" style=\"float: right; width: 250px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n            \n                <p class=\"lesson-text\">\n                    Tražiti oprosta i kajati se zbog počinjenih grijeha – oprost (istigfar) činimo svakodnevno u životu a kajemo se (činimo tevbu) kada pogriješimo. <i>Allah ih nije kaznio, jer si ti među njima bio; i Allah ih neće kazniti sve dok neki od njih mole da im se oprosti. (El-Enfal, 33)</i>\n                </p>\n\n                <p class=\"lesson-text\">\n                    Izvršavanjem dužnosti prema Allahu, dž.š., i čuvanjem od Njegovih zabrana kročimo Pravim putem i stječemo Njegovo zadovoljstvo i sreću na ovom i budućem svijetu. Pravi put kojim musliman hodi je put izvršavanja Allahovih naredbi i klonjenja Njegovih zabrana.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 1</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div class=\"quiz-results\" id=\"quiz-res\"></div>\n                    <p id=\"unlock-msg\" style=\"display: none;\">⭐ MAŠAALLAH! Postigli ste sjajan rezultat. Sada možete označiti lekciju naučenom!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <p class=\"lesson-text\">1. Koje su to stroge islamske dužnosti? </p>\n                <p class=\"lesson-text\">2. Šta znači da je neka dužnost na stepenu vadžiba? </p>\n                <p class=\"lesson-text\">3. Kako izvršavanje islamskih dužnosti djeluje na izvršioca? Objasni primjerima! </p>\n                <p class=\"lesson-text\">4. Šta je još potrebno, pored čvrste volje, da bismo ispunjavali dužnosti prema Allahu? </p>\n                <p class=\"lesson-text\">5. ZADATAK: Opiši svoj osjećaj onda kada izvršiš neku od dužnosti prema Allahu, dž.š. (npr. kada klanjaš akšam-namaz ili kada ispostiš jedan dan ramazana), a kako se osjećaš onda kada ispustiš neku od obaveza koju si bio u mogućnosti obaviti (npr. bez razloga prekineš dan posta). </p>\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">IZABERI ZADATAK!</span><br>1. Razmisli i nabroj dužnosti kojima je Allah, dž.š., zadužio svakog muslimana!<br>2. Na koji način se ti sjećaš Allaha, dž.š., odnosno kako Mu zikr činimo?</p>\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">RAZGOVOR S MUALLIMOM</span><br>• Biti Allahov rob znači biti najslobodnije biće na Zemlji. </p>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":0,"is_published":true,"kviz_pitanja":[{"answer":"Kelimei-šehadet, namaz, post, zekat i hadž","options":["Kelimei-šehadet, namaz, post, zekat i hadž","Samo namaz i post","Vitr-namaz i bajram-namaz","Samo zekat i hadž"],"question":"Koja su glavna islamska učenja na stepenu farza?"},{"answer":"Odvraća nas od onoga što je loše","options":["Bogatijima","Odvraća nas od onoga što je loše","Jače vidimo","Brže se kretamo"],"question":"Šta nas namaz učini prema lekciji?"},{"answer":"Vitr-namaz, bajram-namaz, kurban i sadekatul-fitr","options":["Vitr-namaz, bajram-namaz, kurban i sadekatul-fitr","Samo hadž","Kelimei-šehadet","Samo zekat"],"question":"Koje dužnosti su na stepenu vadžiba?"},{"answer":"Allahov rob","options":["Allahov rob","Allahov prijatelj","Allahov učitelj","Allahov sluga"],"question":"Kako se называет osoba koja izvršava Allahove dužnosti?"},{"answer":"Vjerujte u Allaha","options":["Vjerujte u Allaha","Vjerujte samo u hadž","Vjerujte samo u bogove","Vjerujte samo u učitelje"],"question":"Šta Allah, dž.š., kaže o vjerovanju prema En-Nisi 136?"}]},{"nivo":3,"slug":"el-fil","naslov":"Učenje sure El-Fīl","content_html":"<div class=\"lesson-container\">\n        <h1>UČENJE SURE EL-FIL</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/fil.jpg\" alt=\"Sura El-Fil\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure El-Fīl</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Kur’anu i razumijevanja poruke sure El-Fīl</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst, prijevod i osnovnu poruku sure El-Fīl (105. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno uči i koristi suru El-Fīl u namazu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, danas učimo suru El-Fīl. Ima 5 ajeta i objavljena je u Mekkai. Šta nas Allah uči u njoj?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura El-Fīl je 105. sura Kur’ana, ima 5 ajeta.</p><p>Objavljena je u Mekkai.</p><p>Glavna poruka: Allah je uništio vojsku Ebrehe sa slonom kada je krenuo srušiti Ka’bu — pokazatelj da Allah čuva Svoju svetinju.</p><p>Pišem suru na tabli (arapski + transkripcija + prijevod).</p><p>Učenici slušaju izgovor (sa snimka), zatim ponavljaju ajet po ajet u horu i pojedinačno.</p><p>Razgovor o značenju i poruci za naš svakodnevni život.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče cijelu suru zajedno. Zadaća: usavršiti učenje sure napamet i znati njen prijevod.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":1,"is_published":true,"kviz_pitanja":[{"answer":"Pet ajeta","options":["Tri ajeta","Pet ajeta","Sedam ajeta","Deset ajeta"],"question":"Koliko ajeta sadrži sura El-Fil?"},{"answer":"Mekanska sura","options":["Medinanska sura","Mekanska sura","Mešovita sura","Noćna sura"],"question":"Koja je sura El-Fil po vrsti?"},{"answer":"Ebreha","options":["Sultan Selim","Ebreha","Abu Sufjan","Abu Jahl"],"question":"Ko je bio abesinski vladar koji je htio srušiti Kabu?"},{"answer":"Komadićima pečene gline","options":["Pijeskom","Komadićima pečene gline","Kamenjem","Ledom"],"question":"Čime su ptice gađale vojsku Ebrehe?"},{"answer":"Allah čuva Kabu od štete","options":["Kaba je stara građevina","Allah čuva Kabu od štete","Kaba je u Egiptu","Kaba nije važna"],"question":"Šta sura El-Fil učit nas o Kabi?"}]},{"nivo":3,"slug":"amentu-billahi3","naslov":"Āmentu billāhi - vjerovanje u Allaha, dž.š.","content_html":"<div class=\"lesson-container\">\n        <h1>ĀMENTU BILLĀHI – VJERUJEМ U ALLAHA, DŽ.Š.</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/amentu_billahi.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Āmentu billāhi – vjerovanje u Allaha (detaljno)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje imana u Allaha kao temelja sve vjere</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Detaljno razumjeti šta znači vjerovati u Allaha kao prvi imanski šart</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti dokazivanja Allahovog postojanja kroz prirodu i razum</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, naučili smo \"Āmentu billāhi\". Šta to detaljno znači? Kako vjerujemo u Allaha?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Vjerovati u Allaha znači biti potpuno uvjeren u Njegovo postojanje, jednoću, savršenstvo i da je On Stvoritelj svega.</p><p>Iman u Allaha obuhvata vjerovanje u: Njegova bića (zat), Njegove osobine (sifat), i Njegovih djela (efal).</p><p>Dokazi Allahovog postojanja: red u svemiru, savršenstvo u stvaranju (od atoma do zvijezda), neprestano stvaranje, fitra (urođeni osjećaj).</p><p>Allah nije dio stvorenog svijeta — On je iznad svega, ali je svemu blizak.</p><p>Iman u Allaha donosi: smirenost u srcu, nadu, zahvalnost, hrabrost u istini.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju 3 dokaza Allahovog postojanja iz prirode oko sebe. Zaključak: što više razmišljamo, više vjerujemo.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":2,"is_published":true,"kviz_pitanja":[{"answer":"Nema drugog boga osim Allaha, dž.š.","options":["Nema drugog boga osim Allaha, dž.š.","Allah je najveći i moćan","Vjerujem u sve proroka","Islam je najbolja vjera"],"question":"Što znači rečenica 'La ilahe illallah'?"},{"answer":"U šest vremenskih razdoblja","options":["U četiri razdoblja","U šest vremenskih razdoblja","U tri razdoblja","U sedam razdoblja"],"question":"Koliko vremenskih razdoblja je Allah stvorio nebesa i Zemlju?"},{"answer":"Āmentu billāhi - vjerovanje u Allaha","options":["Vjerovanje u proroka Muhammeda","Obavljanje molitve pet puta dnevno","Āmentu billāhi - vjerovanje u Allaha","Vjerovanje u Sudnji dan"],"question":"Koji je prvi imanski šart prema tekstu lekcije?"},{"answer":"Ga ne obuzima drijemež ili san","options":["Ne čuje molitvu svojih robova","Ga ne obuzima drijemež ili san","Ne poznaje budućnost","Ne čuva nebo i Zemlju"],"question":"Što Allah nikada ne čini prema ajet-ul-kursi?"},{"answer":"Mušicu i sićušnije stvari od nje","options":["Velikih životinja poput slona","Samo ljudskog bića","Mušicu i sićušnije stvari od nje","Samo biljke i drveće"],"question":"Koga je Allah dao kao primjer svoga stvaranja u Kur'anu?"}]},{"nivo":3,"slug":"tevhid","naslov":"Tevhid - Allah je jedan","content_html":"<div class=\"lesson-container\">\n        <h1>TEVHID - ALLAH JE JEDAN</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/jedan1.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Tevhid – Allah je jedan</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje čvrste vjere u Allahovu jednoću i odbacivanje svih oblika širka</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam tevhida i njegove vrste</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da prepozna tevhid i njegovu suprotnost — širk</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, najvažnija riječ u islamu je \"Lā ilāhe illallāh\". Šta ta riječ znači? To je tevhid.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Tevhid znači vjerovanje u Allahovu jednoću — da je On samo jedan, bez druga.</p><p>Vrste tevhida: <strong>Tevhid rububijjeta</strong> (Allah je jedini Gospodar i Stvoritelj), <strong>Tevhid uluhijjeta</strong> (samo Allah zaslužuje ibadet), <strong>Tevhid esma ve sifat</strong> (samo Allah ima savršena imena i osobine).</p><p>Tevhid je glavna poruka svih poslanika od Adema, a.s., do Muhammeda, a.s.</p><p>Suprotnost tevhidu je <strong>širk</strong> — pridruživanje Allahu sudruga (kipovi, talismani, čovjek, prirodne sile).</p><p>Onaj ko umre na tevhidu — sigurno će u Džennet, prije ili kasnije.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici izgovaraju \"Lā ilāhe illallāh\" sa razumijevanjem. Zaključak: tevhid je naš najveći ponos.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> JEDAN IZVOR SVJETLOSTI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite jedan ogroman sat sa hiljadama zupčanika koji rade u savršenoj tišini. Da bi taj sat kucao tačno, mora postojati samo jedan majstor koji ga je osmislio i koji ga navija. Da ih je više, svaki bi želio da sat kuca po njegovom, i mehanizam bi se brzo pokvario.</p>\n                    <p>Cijeli naš svemir – od ogromnih zvijezda do najsitnije travke – funkcioniše u savršenom redu jer njime upravlja Jedan Jedini Stvoritelj. Ta istina o Božijoj jednoći naziva se Tevhid. To je najvažnija poruka koju su donijeli svi poslanici, od prvog Adema do posljednjeg Muhammeda, alejhis-selam Danas učimo o tom temelju naše vjere koji nam daje mir i sigurnost.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <i>Allah, dž.š., kaže: O vjernici, vjerujte u Allaha. (En-Nisa, 136)</i>\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Vjerovanje u Jednog Boga dužnost je svakog muslimana i muslimanke. Jedan od osnovnih zadataka svih Božijih poslanika bio je da pozivaju svoj narod da vjeruju u postojanje Jednog Jedinog Boga, Allaha, dž.š., to jest da budu sljedbenici tevhida. Brojni su ajeti u Allahovoj, dž.š., knjizi koji govore o pojmu tevhida. Cijela sura El-Ihlas govori o Božijoj jednoći. Četiri su vrlo važna aspekta o kojima govori ova sura:\n                </p>\n                \n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: disc;\">\n                    <li><span style=\"background-color: #fff9c4;\">Reci</span> Allahova je naredba Muhammedu, alejhis-selam, koja podrazumijeva širenje istine o Allahovoj jednoći sadržane u riječima \"On je Allah Jedan\";</li>\n                    <li><span style=\"background-color: #fff9c4;\">Allah je utočište svakom</span> - samo se Njemu možemo obraćati dovom, što isključuje obraćanje nekome drugom mimo Allaha, dž.š.;</li>\n                    <li><span style=\"background-color: #fff9c4;\">Nije rodio i rođen nije</span> - poricanje tvrdnje židova i kršćana da On ima dijete i da ima roditelje;</li>\n                    <li><span style=\"background-color: #fff9c4;\">I niko Mu ravan nije</span> - ne postoji niko ko Mu je ravan u Njegovoj Uzvišenosti i u Njegovoj vlasti.</li>\n                </ul>\n                <p class=\"lesson-text\">\n                    Vjerovanje svakog muslimana utemeljeno je na tevhidu - Allahovoj jednoći. Allahova svojstva es-sifatuz-zatijje potvrđuju tu istinu tevhida. Po islamskom učenju, tevhid se sastoji od čvrstog ubjeđenja u sljedeće:\n                </p>\n                <img src=\"/edu/assets/images/jedan.jpg\" style=\"float: right; width: 250px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: disc;\">\n                    <li>samo je jedan Bog, Allah, dž.š.,</li>\n                    <li>On je vječan, a sve drugo je nastalo i nestaje,</li>\n                    <li>On je Gospodar svega što postoji, On Jedini stvara,</li>\n                    <li>samo je On dostojan obožavanja i samo se Njemu klanja.</li>\n                </ul>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <i>Allah, dž.š., kaže: Reci: On je Allah - Jedan! Allah je Utočište svakom! Nije rodio i rođen nije, i niko Mu ravan nije. (El-Ihlas, 1-4)</i>\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    <i>Da Zemljom i nebesima upravljaju drugi bogovi, a ne Allah, poremetili bi se. (El-Enbija, 22)</i>\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Jedan je Bog, Allah, drugog boga osim Njega nema.</span> <i>On je Prvi i Posljednji, i Vidljivi i Nevidljivi; i On zna sve! (Hadid, 3)</i> Postojanje Jednog Jedinog Boga, Allaha, dž.š., je najveća istina koja je naglašavana u toku poslaničke misije svih Božijih poslanika od Adema, alejhis-selam, do Muhammeda, alejhis-selam.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <i>Prije tebe nijednog poslanika nismo poslali, a da mu nismo objavili: Nema boga osim Mene, zato se Meni klanjajte! (El-Enbija, 25)</i> Brojni su ajeti koji spominju Allahovo, dž.š., postojanje (<span style=\"background-color: #fff9c4;\">Vudžud</span>) i Allahovu, dž.š., jednoću (<span style=\"background-color: #fff9c4;\">Vahdanijet</span>).\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 4</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                    <p id=\"unlock-msg\" style=\"display: none;\">⭐ MAŠAALLAH! Uspješno ste savladali lekciju o Tevhidu. Sada možete označiti naučeno!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja_list', this)\"> PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja_list\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Koja je bila zajednička misija svih poslanika?</li>\n                    <li>O koja četiri aspekta govori sura El-Ihlas?</li>\n                    <li>Šta podrazumijeva vjerovanje u tevhid?</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":3,"is_published":true,"kviz_pitanja":[{"answer":"Vjerovanje u Jednog Boga, Allaha","options":["Vjerovanje u Jednog Boga, Allaha","Čitanje svih knjiga na arapskom","Putovanje u sve zemlje svijeta","Učenje svih jezika"],"question":"Koja je glavna dužnost svakog muslimana i muslimanke?"},{"answer":"Sura El-Ihlas","options":["Sura El-Ihlas","Sura En-Nisa","Sura El-Enbija","Sura El-Fatiha"],"question":"Koja sura u Qur'anu potpuno govori o Allahovoj jednoći?"},{"answer":"Da Allah nema sina i nema roditelja","options":["Da Allah nema sina i nema roditelja","Da Allah ima djecu kao ljudi","Da Allah živi sa svojom porodicom","Da Allah brine samo za svoje dijete"],"question":"Šta Qur'an potvrđuje sa izrazom 'Nije rodio i rođen nije'?"},{"answer":"Četiri važna aspekta","options":["Četiri važna aspekta","Dva važna aspekta","Pet važnih aspekata","Deset važnih aspekata"],"question":"Koliko je važnih aspekata u suri El-Ihlas?"},{"answer":"Samo Allah, dž.š.","options":["Samo Allah, dž.š.","Allahovi anđeli","Allahovi poslanici","Dobri ljudski vladari"],"question":"Ko je Jedini dostojan obožavanja prema islamskom učenju?"}]},{"nivo":3,"slug":"vjerovanje-gajb","naslov":"Vjerovanje u gajb","content_html":"<div class=\"lesson-container\">\n        <h1>VJEROVANJE U GAJB</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/gajb.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Vjerovanje u gajb</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje povjerenja u Allahove vijesti o stvarima koje ne vidimo</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam gajba i njegove kategorije</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti vjerovanja bez vidljivog dokaza, samo na osnovu Kur’ana i hadisa</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li vjerujete u meleke iako ih ne vidite? U Džennet i Džehennem? To je gajb. Šta je gajb?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Gajb znači \"ono što je nevidljivo\" — sve čemu mi nemamo direktni pristup čulima.</p><p>U gajb spadaju: Allah, meleki, džini, duše, Sudnji dan, Džennet, Džehennem, kabur, sve što će biti...</p><p>Allah u Kur’anu kaže: \"Vjernici su oni koji u gajb vjeruju.\"</p><p>Vjerovanje u gajb je znak iskrenog imana — vjerujemo Allahu i Njegovom Poslaniku, a.s., čak i o stvarima koje ne vidimo.</p><p>Gajb znamo samo iz dva izvora: Kur’ana i ispravnog hadisa. Ne od gatara, vidovnjaka ili horoskopa!</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju primjere gajba. Zaključak: čvrsta vjera u gajb razlikuje vjernika od nevjernika.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> IZA ZAVJESE VIDLJIVOG <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da stojite ispred velike, teške zavjese. Vidite njenu boju i nabore, ali ne znate šta se nalazi iza nje dok vam neko ko je to vidio ne ispriča. Naš život na ovom svijetu je sličan tome – vidimo sunce, drveće i ljude, ali postoji jedan ogroman, prelijep i važan svijet koji je skriven od naših očiju.</p>\n                    <p>Taj skriveni svijet zovemo gajb. To nije bajka, već stvarna realnost o kojoj nas je obavijestio naš Stvoritelj. Vjerovati u gajb znači imati povjerenja u Allahove riječi o melekima, Džennetu i proživljenju, iako ih našim čulima trenutno ne možemo dosegnuti. To je prva osobina koju Allah ističe kod istinskih vjernika, jer pravo srce vidi dalje od onoga što oči mogu dohvatiti.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <i>Allah, dž.š., kaže: Elif Lam Mim. Ova Knjiga, u koju nema nikakve sumnje, uputstvo je svima onima koji se budu Allaha bojali; onima koji u nevidljivi svijet budu vjerovali i molitvu obavljali i udjeljivali dio od onoga što im Mi budemo davali. (El-Bekare, 1-3)</i>\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Stvoritelj svih svjetova, Allah, dž.š., nas je obavijestio u Kur'anu da pored ovog prolaznog, vidljivog svijeta na kojem živimo, postoji i drugi nevidljivi svijet koji se naziva svijet gajba. <span style=\"background-color: #fff9c4;\">Nevidljivi svijet gajba se ne može shvatiti niti spoznati našim razumom i čulima, zato ga treba prvenstveno vjerovati.</span> Vjerovanje u gajb - nevidljivo je prva osobina vjernika spomenuta u Kur'anu, te je osnovna odrednica i obilježje muslimana. Jedno od prvih obilježja vjernika spomenuto u Kur'anu jeste obilježje vjerovanja u gajb.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Vjerovanje u svijet gajba obuhvata:\n                </p>\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: disc;\">\n                    <li><span style=\"background-color: #fff9c4;\">Vjerovanje u Allaha, dž.š.</span>, Gospodara svih svjetova. Brojni su dokazi na nebesima i na Zemlji koji nam ukazuju na Njegovo postojanje: Na Zemlji su dokazi za one koji čvrsto vjeruju i u vama samima, zar ne vidite? (Ez-Zarijat, 20-21)</li>\n                    <li><span style=\"background-color: #fff9c4;\">Vjerovanje u postojanje Allahovih meleka.</span> Allah nas je obavijestio o postojanju Njegovih meleka. Poslanik vjeruje u ono što mu se objavljuje od Gospodara njegova, i vjernici-svaki vjeruje u Allaha, i meleke Njegove, i Knjige Njegove i poslanike Njegove... (El-Bekare, 285)</li>\n                    <li><span style=\"background-color: #fff9c4;\">Vjerovanje da postoji svijet džina</span> pokornih Allahu, dž.š., i svijet džina nepokornih Allahu, dž.š., koje nazivamo šejtanima. Allah, dž.š., kaže: A džine je od plamena vatre stvorio. (Er-Rahman, 15)</li>\n                    <li><span style=\"background-color: #fff9c4;\">Vjerovanje da Sudnjem danu prethode propast ovoga svijeta i proživljenje.</span> Allah, dž.š., kaže: I osluškuj! Dan kada će glasnik pozvati iz mjesta koje je blizu, Dan kada će oni čuti istinit glas - to će biti Dan oživljenja. (Kaf, 41-42)</li>\n                    <li><span style=\"background-color: #fff9c4;\">Vjerovanje u Sudnji dan.</span> Nakon naše smrti i ponovnog proživljenja nastupit će Sudnji dan. Allah će vas, nema drugog boga osim Njega, sigurno sabrati na Sudnjem danu. (En-Nisa, 87)</li>\n                    <li><span style=\"background-color: #fff9c4;\">Vjerovanje u Džennet.</span> To je boravište na drugom svijetu koje je Allah, dž.š., pripremio kao nagradu za muslimane i muslimanke. I nastojte da zaslužite oprost Gospodara svoga i Džennet prostran kao nebesa i Zemlja, pripremljen za one koji se Allaha boje. (Alu Imran, 133)</li>\n                    <li><span style=\"background-color: #fff9c4;\">Vjerovanje u Džehennem.</span> To je boravište na drugom svijetu koje je Allah, dž.š., pripremio kao kaznu za grješnike. U njemu će nevjernici vječno boraviti, a jedno vrijeme i vjernici počinioci velikih grijeha ako im Allah ne oprosti te grijehe. I tako će se riječ Gospodara tvoga ispuniti i da će oni koji nisu htjeli vjerovati-stanovnici u Vatri biti. (El-Mu'min, 6)</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Znanje o gajbu ima samo Uzvišeni Allah</span> On je Jedini vlasnik ključeva svih tajni (mefatihul-gajb). Samo On poznaje vidljivi i nevidljivi svijet, za Njega nema nikakvih tajni. Allah, dž.š., kaže: Samo Allah zna kad će Smak svijeta nastupiti, samo On spušta kišu i samo On zna šta je u matericama, a čovjek ne zna šta će sutra zaraditi i ne zna čovjek u kojoj će zemlji umrijeti; Allah, uistinu, sve zna i o svemu je obaviješten. (Lukman, 34)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Čovjek, najsavršenije Allahovo stvorenje, o gajbu zna samo onoliko koliko ga je obavijestio Allah, dž.š. Gajb nije bio poznat ni najodabranijem Allahovom poslaniku Muhammedu, alejhis-selam Allah, dž.š., mu objavljuje i naređuje: Reci: \"Ja vam ne kažem: 'U mene su Allahove riznice', niti: 'Meni je poznat nevidljivi svijet', niti vam kažem: 'Ja sam melek' - ja slijedim samo ono što mi se objavljuje.\" Reci: 'Zar su isto slijepac i onaj koji vidi? Zašto ne razmislite?\" (El-En'am, 50)\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        Temeljna obaveza svih muslimana i muslimanki je da u svijet gajba čvrsto vjeruju, te da se svaka sumnja u tom smislu odbacuje.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 5</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                    <p id=\"unlock-msg\" style=\"display: none;\">⭐ MAŠAALLAH! Uspješno ste savladali lekciju o svijetu gajba. Sada možete označiti naučeno!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Šta je gajb?</li>\n                    <li>Šta obuhvata vjerovanje u gajb - nevidljivo?</li>\n                    <li>Ko je poznavalac svih tajni?</li>\n                    <li>Koliko mi znamo o gajbu?</li>\n                </ul>\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">IZABERI ZADATAK!</span></p>\n                <p class=\"lesson-text\">1. U nekoliko rečenica odgovori na pitanje: kako razumiješ svijet gajba, čega se prvo sjetiš kada se spomene gajb?</p>\n                <p class=\"lesson-text\">2. Razgovaraj sa starijim prijateljem ili rođakom šta on zna o svijetu gajba, te za sljedeći čas pripremi zabilješke o tom razgovoru!</p>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":4,"is_published":true,"kviz_pitanja":[{"answer":"Nevidljivi svijet koji ne možemo vidjeti niti čuti","options":["Nevidljivi svijet koji ne možemo vidjeti niti čuti","Svijet u kojem živimo sada","Samo san koji imam noću","Izmišljeni svijet od priča"],"question":"Što je svijet gajba prema ovoj lekciji?"},{"answer":"Vjerovanje u gajb - nevidljivo","options":["Vjerovanje u gajb - nevidljivo","Briga o bogatstvu","Slaganje sa svima","Putovanje po svijetu"],"question":"Koja je prva osobina vjernika spomenuta u Kur'anu?"},{"answer":"Od plamena vatre","options":["Od plamena vatre","Od vode","Od zemlje","Od zraka"],"question":"Od čega je Allah stvorio džine prema Kur'anu?"},{"answer":"Allah će nas sabrati na Sudnjem danu","options":["Allah će nas sabrati na Sudnjem danu","Čovjek će postati anđeo","Svijet će se zauvijek zaustaviti","Neće biti više molitvi"],"question":"Šta se事件 Sudnjeg dana prema ovoj lekciji?"},{"answer":"Boravište koje je Allah pripremio kao nagrada","options":["Boravište koje je Allah pripremio kao nagrada","Mjesto gdje se obavlja molitva","Kuća od boga na Zemlji","Grad sa puno trgovina"],"question":"Što je Džennet prema ovoj lekciji?"}]},{"nivo":3,"slug":"kufr-sirk-nifak","naslov":"Kufr, širk, nifak","content_html":"<div class=\"lesson-container\">\n        <h1>KUFR, ŠIRK, NIFAK</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/kufr.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kufr, širk i nifak — najveći grijesi</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje gnušanja prema kufru, širku i nifaku te ljubavi prema čistom imanu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pojmove kufr (nevjerstvo), širk (idolatrija) i nifak (licemjerje)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti prepoznavanja i izbjegavanja ovih grijeha u životu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, postoje grijesi koje Allah nikako ne oprašta ako se čovjek za njih ne pokaje. Koji su to? Kufr, širk i nifak.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Kufr</strong> (nevjerstvo) — poricanje Allaha, Njegovog Poslanika ili nečega iz vjere što je očito poznato.</p><p><strong>Širk</strong> — pridruživanje Allahu sudruga (obožavanje kipova, sila, ljudi, ili pridruživanje Mu u Njegovim svojstvima).</p><p><strong>Nifak</strong> (licemjerje) — kada čovjek na jeziku govori da je vjernik, a u srcu nije ili djeluje suprotno.</p><p>Allah u Kur’anu kaže: \"Allah ne prašta da Mu se širk čini, a oprašta sve drugo manje od toga kome On hoće.\"</p><p>Kako se sačuvati: čvrst iman, ibadet, druženje sa dobrim ljudima, učenje vjere, dova: \"Allahumme innī e‘ūzu bike en ušrike bike šej’en ve ene a‘lemu, ve estagfiruke limā lā a‘lem.\"</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju razlike između tri pojma. Učimo dovu zaštite od širka.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> ČUVARI ČISTOGA SRCA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da imate najljepši, najčistiji izvor vode u svom vrtu. Ta voda je vaš život i vaša snaga. Da biste je sačuvali, morate paziti da je ništa ne zaprlja – ni blato, ni otrovi, ni skrivene pukotine kroz koje bi mogla isteći.</p>\n                    <p>Naša vjera je poput tog izvora u našim srcima. Da bismo je sačuvali čistom, moramo prepoznati stvari koje je kvare ili potpuno uništavaju. Postoje tri velike opasnosti o kojima nas Allah uči: poricanje istine, pridruživanje nekoga Allahu i pretvaranje. Danas učimo kako da prepoznamo te opasnosti pod nazivima kufr, širk i nifak, ne da bismo sudili drugima, već da bismo zaštitili svjetlost u vlastitim srcima i ostali na Pravom putu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <i>Allah, dž.š., kaže: O vjernici, vjerujte u Allahu, i Poslanika Njegova, i u Knjigu koju On Svome Poslaniku objavljuje, i u Knjigu koju je objavio prije. A onaj ko ne bude vjerovao u Allahu, i u meleke Njegove, i u knjige Njegove, i u poslanike Njegove, i u onaj svijet - daleko je zalutao. (En-Nisa, 136)</i>\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">Kufr</span></p>\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Kufr je nevjerovanje u Allaha, dž.š., i ostale temeljne istine vjere.</span> Kufr se ubraja u najtežu vrstu grijeha koje čovjek može učiniti. Osoba koja počini kufr naziva se kafir - nevjernik.\n                </p>\n                <p class=\"lesson-text\">Pod pojmom kufra se podrazumijeva sljedeće:</p>\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: disc;\">\n                    <li>nevjerovanje u Allaha, dž.š., i ostale temeljne istine vjere: Njegove meleke, Njegove knjige, Njegove poslanike, u Sudnji dan i Allahovo određenje,</li>\n                    <li>napuštanje islama - riddet,</li>\n                    <li>psovanje ili omalovažavanje Allaha, dž.š., i ostalih islamskih svetinja kao što su: Kur'an, Kaba, džamija, namaz, post itd.,</li>\n                    <li>negiranje Allahovih farzova: namaza, posta, zekata, hadža itd.,</li>\n                    <li>poricanje Allahovih harama: alkohola, kocke, krađe, laži, bluda itd.,</li>\n                    <li>namjerno laganje na Allaha, dž.š., i Njegovog poslanika Muhammeda, alejhis-selam</li>\n                </ul>\n\n                <p class=\"lesson-text\">U suri El-Kafirun Allah, dž.š., poručuje: <i>Reci: \"O vi nevjernici, ja se neću klanjati onima kojima se vi klanjate, a ni vi se nećete klanjati Onome kome se ja klanjam; ja se nisam klanjao onima kojima ste se vi klanjali, a i vi se niste klanjali Onome kome se ja klanjam, vama - vaša vjera, a meni - moja. (El-Kafirun, 1-6)</i></p>\n\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">Širk</span></p>\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Širk je jedan od najtežih grijeha, a podrazumijeva pripisivanje sudruga Allahu, dž.š., odnosno vjerovati da pored Allaha, dž.š., postoje i druga božanstva.</span> Osoba koja čini širk naziva se mušrik. Po riječima Kur'ana to je grijeh koji Uzvišeni Allah neće oprostiti, ukoliko se osoba ne pokaje zbog njega: <i>Allah neće oprostiti da Mu se neko drugi smatra ravnim, a oprostit će manje grijehe od toga kome On hoće... (En-Nisa 48)</i>\n                </p>\n                <p class=\"lesson-text\">Islamski učenjaci su širk podijelili na veliki i mali.</p>\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">Veliki širk (eš-širkul-ekber)</span> je obožavanje nekoga drugog pored Allaha ili činjenje bilo kojeg ibadeta nekom drugom pored Njega. Širk ne podrazumijeva nijekanje Allahovog postojanja jer Kur'an jasno ističe da su arapski mušrici vjerovali u Allaha, ali su istovremeno vjerovali i u kipove, smatrajući da oni približavaju Allahu, odnosno pribavljaju određenu korist ili nanose štetu. Kur'an je upravo takvo vjerovanje kvalificirao širkom, naglašavajući da je to neoprostiv grijeh.</p>\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">Mali širk (er-rija')</span> je pretvaranje ili neiskrenost u djelima, odnosno činjenje dobrih djela radi toga da bi se pred nekim pokazalo i time ostvario određeni dunjalučki interes, a ne Allahovo zadovoljstvo. U mali širk se ubraja i sljedeće: zaklinjanje nekim drugim mimo Allaha, nošenje hamajlije s uvjerenjem da ona može otkloniti nevolju.</p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <strong>HADIS</strong><br><br>\n                        Poslanik, alejhis-selam, je rekao: \"Najviše se za vas bojim malog širka', a ashabi ga upitaše: 'A šta je to mali širk, Allahov Poslaniče?' On odgovori: 'Rija - pretvaranje, jer će Allah na Sudnjem danu, kada bude nagrađivao Svoje robove, reći licemjerima: 'Idite onima kojima ste se prikazivali, pa vidite da li će vas oni nagraditi.\" (Ahmed)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">Osoba koja počini kufr i širk obavezna je učiniti gusul (okupati se), pokajati se za učinjeni grijeh i izgovoriti Kelimei-šehadet. Ako bi osoba umrla prije pokajanja, smatra se da je umrla kao nevjernik i takvoj osobi se po propisu ne klanja dženaza-namaz niti se ukopava u muslimansko mezarje.</p>\n\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">Nifak</span></p>\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Nifak je skrivanje nevjerovanja u srcu a pokazivanje vjerovanja riječima ili djelima pred drugim ljudima.</span> Osoba koja čini ovaj grijeh naziva se munafik licemjer. Licemjeri se ubrajaju među najomraženije osobe u svakom društvu. Postoje dvije vrste nifaka/licemjerstva i to en-nifakul-asgar mali nifak i en-nifakul-ekber veliki nifak.\n                </p>\n                <img src=\"/edu/assets/images/licemjer.jpg\" style=\"float: right; width: 250px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">Kur'an ističe da će licemjeri biti na samom dnu Džehennema: <i>Licemjeri će na samom dnu Džehennema biti i ti im nećeš zaštitnika naći. (En-Nisa, 145)</i></p>\n                <p class=\"lesson-text\">Brojni su ajeti koji govore o osobinama munafika. Allah, dž.š., na početku sure El-Bekare govori o vjernicima u samo tri ajeta, o nevjernicima u dva, a o licemjerima čak u trinaest ajeta.</p>\n                <p class=\"lesson-text\"><i>Ima ljudi koji govore: \"Vjerujemo u Allahu i u onaj svijet!\" - a oni nisu vjernici.\" Oni nastoje prevariti Allahu i one koji vjeruju, a oni i ne znajući, samo sebe varaju. (El-Bekare, 7-8)</i></p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <strong>HADIS</strong><br><br>\n                        Osobine licemjera spomenuo je i Muhammed, alejhis-selam, u sljedećem hadisu: \"Kod koga se nađu ova četiri svojstva on je munafik, a kod koga se nađe jedno od njih taj ima jedno od svojstava munafika sve dok ga ne ostavi: kada govori - laže; kada obeća - ne ispuni; kada mu se nešto povjeri - iznevjeri i kad se svađa prelazi sve granice.\" (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">Osoba koja kod sebe uoči osobine licemjerstva treba se pokajati i nastojati što prije svoje ponašanje mijenjati na bolje.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 6</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                    <p id=\"unlock-msg\" style=\"display: none;\">⭐ MAŠAALLAH! Uspješno ste savladali lekciju o kufru, širku i nifaku. Sada možete označiti naučeno!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Šta je kufr? Šta je širk? I šta je nifak?</li>\n                    <li>Šta se podrazumijeva pod pojmom kufra?</li>\n                    <li>Koje su vrste širka i šta podrazumijeva svaka od njih?</li>\n                    <li>Šta treba učiniti osoba koja počini kufr ili širk?</li>\n                    <li>Koje su osobine munafika i šta treba učiniti musliman koji kod sebe uoči neku od ovih osobina?</li>\n                </ul>\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">IZABERI ZADATAK!</span></p>\n                <p class=\"lesson-text\">1. Pronađi i napiši ajete iz sure El-Bekare koji govore o munaficima!</p>\n                <p class=\"lesson-text\">2. Napravi pano, navedi djela i osobine koje se odnose na kufr - ponašanje nevjernika.</p>\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">RAZGOVOR S MUALLIMOM</span><br>\n                        Povod objave sure El-Kafirun jeste taj da je grupa Kurejšija pozvala Muhammeda, alejhis-selam, i rekla mu: \"Slijedi našu vjeru i mi ćemo slijediti tvoju. Obožavat ćemo tvoga Boga godinu, a onda ti obožavaj naša božanstva godinu dana, pa ako ustanovimo da je ono što ti propovijedaš bolje od onoga što mi slijedimo, mi ćemo prigrliti tvoju vjeru, a ako je ono na čemu smo mi bolje od onoga čemu ti pozivaš, onda se ti prikloni našoj vjeri.\" Poslanik, alejhis-selam, na to reče: \"Neka me Allah sačuva od toga da Mu nekog ravnim pripišem.\" Tim povodom je Allah, dž.š., objavila ovu suru. Ujutro se Poslanik, alejhis-selam, zaputio u harem Kabe, u kome je bila skupina Kurejšija, pa im je proučio suru El-Kafirun sve do posljednjeg ajeta, nakon čega se ražalostiše i izgubiše nadu.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":5,"is_published":true,"kviz_pitanja":[{"answer":"Nevjerovanje u Allaha i temeljne istine vjere","options":["Nevjerovanje u Allaha i temeljne istine vjere","Mali grijeh koji Allah lako oprašta","Zaboravljanje da recitiraš Kur'an","Jelo haram hrane"],"question":"Što je kufr prema islamskoj vjeri?"},{"answer":"Kafir","options":["Kafir","Mušrik","Munafik","Musalman"],"question":"Kako se naziva osoba koja ne vjeruje u Allaha?"},{"answer":"Pripisivanje sudruga Allahu i drugim božanstvima","options":["Pripisivanje sudruga Allahu i drugim božanstvima","Zaboravljanje obaveza vjernika","Loše ponašanje prema roditeljima","Kratka molitev bez fokusa"],"question":"Što znači širk u islamu?"},{"answer":"Psovanje ili omalovažavanje Allaha i islamskih svetinja","options":["Psovanje ili omalovažavanje Allaha i islamskih svetinja","Zaboravljanje jedne dnevne molitve","Greška u recitaciji Kur'ana","Neurednost u oblačenju"],"question":"Koji od navedenih primjera je oblik kufra?"},{"answer":"Allah neće oprostiti širk ako se osoba ne pokaje","options":["Allah neće oprostiti širk ako se osoba ne pokaje","Allah lako oprašta sve vrste širka","Širk je mali grijeh kao ostali","Allah će oprostiti širk bez pokajanja"],"question":"Što kaže Allah o grijeh širka u suri En-Nisa?"}]},{"nivo":3,"slug":"zatijje-1","naslov":"Es-sifatuz-zatijje: Vudžud, Kidem i Beka","content_html":"<div class=\"lesson-container\">\n        <h1>ES-SIFATUZ-ZATIJJE: VUDŽUD, KIDEM I BEKA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/vjecnost.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Es-sifatuz-zatijje (1) – Vudžud, Kidem, Beka</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ispravnog poimanja Allahove uzvišenosti</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti prve tri osobine bića (zatijje): Vudžud, Kidem i Beka</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti razumjevanja Allahove apsolutnosti</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta znače riječi: Allah postoji oduvijek i zauvijek? Te osobine zovemo zatijje. Hajde da ih učimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Vudžud</strong> — postojanje. Allah postoji nužno, Njegovo postojanje nije zavisno od nikoga.</p><p><strong>Kidem</strong> — vječnost u prošlosti. Allah nije imao početka — postojao je oduvijek.</p><p><strong>Beka</strong> — vječnost u budućnosti. Allah neće prestati postojati — postoji zauvijek.</p><p>Sve drugo (ljudi, meleki, dunjaluk) ima početak i kraj. Samo Allah je vječan u oba smjera.</p><p>Razgovor: zašto je važno znati ove osobine?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici objašnjavaju Vudžud, Kidem i Beka svojim riječima. Zaključak: Allah je apsolutan – On je oduvijek i zauvijek.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> DOKAZI KOJI NAS OKRUŽUJU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Jeste li ikada razmišljali o tome kako je sve što vidimo oko sebe – od najsitnijeg zrna pijeska do ogromnih zvijezda – moralo imati svoj početak? Sve što postoji ima svog graditelja. Ako vidite lijepu kuću, znate da ju je neko sagradio, čak i ako niste vidjeli majstora.</p>\n                    <p>Naš svijet je pun dokaza o postojanju Velikog Stvoritelja. Allah nam je u Kur'anu otkrio Svoja svojstva kako bismo Ga bolje upoznali. Danas učimo o tri posebna svojstva Njegovog bića: o tome da On postoji, da je oduvijek i da će biti zauvijek. To su temelji koji nam pomažu da shvatimo veličinu našeg Gospodara koji nema ni početka ni kraja.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <i>Allah, dž.š., kaže: Na Zemlji su dokazi za one koji čvrsto vjeruju, a i u vama samima, zar ne vidite. (Ez-Zarijat, 20-21)</i>\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Uzvišeni Allah je u Kur'anu objavio ajete u kojima govori o Sebi s ciljem da Ga ljudi mogu spoznati i u Njega vjerovati. Allahova, dž.š., svojstva odnose se samo na Njega i govore o Njegovom uzvišenom Biću i Savršenstvu. Čovjeku je dozvoljeno opisivati Allaha, dž.š., samo onako kako je On sam Sebe opisao u Svojoj Knjizi. Muslimani i muslimanke ne smiju opisivati Allaha, dž.š., nikako drugačije osim Njegovim svojstvima, niti im je dozvoljeno upoređivati druga stvorenja s Uzvišenim Allahom.\n                </p>\n\n                <p class=\"lesson-text\">Allahova svojstva se dijele na:</p>\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: disc;\">\n                    <li><span style=\"background-color: #fff9c4;\">es-sifatuz-zatijje</span> svojstva kojima je opisano Allahovo, dž.š., biće i</li>\n                    <li><span style=\"background-color: #fff9c4;\">es-sifatus-subutijje</span> - svojstva kojima je opisano Njegovo savršenstvo.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Vudžud, Kidem i Beka su svojstva Allaha, dž.š., koja se ubrajaju u grupu svojstava es-sifatuz-zatijje, tj: svojstva Allahovog bića.</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Vudžud - Allah postoji.</span> Uzvišeni Allah je nama nevidljiv, ali nam je dao dokaze koji upućuju na Njegovo postojanje. Allahovo, dž.š., postojanje je neupitno jer naše stvaranje i postojanje proizlazi iz Njegovog postojanja. Na ovom prolaznom svijetu ništa nije nastalo samo od sebe, sve ima svoj uzrok nastajanja, a Allah, dž.š., je uzrok svih uzroka. Mi postojimo, stoga vjerujemo da Allah, dž.š., postoji.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Kidem - Allah je oduvijek.</span> Allahovo svojstvo Kidem govori o Allahovom stalnom postojanju, što podrazumijeva postojanje bez početka i nastanka. On, Allah, je prvi jer nije postao.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Beka - Allah je zauvijek.</span> Allah, dž.š., je Sebe opisao svojstvom koje znači da On nema početka, pa se podrazumijeva da On nema ni kraja. Njemu pripada vječnost koja nema početka i nema kraja, što nije nastalo neće ni nestati.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Na osnovu spomenutih svojstava znamo i vjerujemo da Allah, dž.š., postoji, Njegovo postojanje nema početka ni kraja. On je oduvijek, jer nije nastao i On je zauvijek jer neće nestati. Trebamo znati da razum nijednog čovjeka ne može u potpunosti shvatiti pojmove oduvijek i zauvijek, te nam je zbog toga dužnost da u njih čvrsto vjerujemo.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 7</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                    <p id=\"unlock-msg\" style=\"display: none;\">⭐ MAŠAALLAH! Uspješno ste savladali lekciju. Sada možete označiti naučeno!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Kako se dijele svojstva Allaha, dž.š.?</li>\n                    <li>Šta znače Allahova, dž.š., svojstva: Vudžud, Kidem i Beka i šta pomoću njih znamo?</li>\n                    <li>U koja Allahova svojstva se ubrajaju: Vudžud, Kidem i Beka?</li>\n                </ul>\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">RAZGOVOR S MUALLIMOM</span><br>\n                        • Vječnost pripada Allahu, dž.š., a prolaznost stvorenjima.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":6,"is_published":true,"kviz_pitanja":[{"answer":"Svojstva Allahovog bića","options":["Svojstva Allahovog bića","Svojstva Njegovog savršenstva","Svojstva čovjeka","Svojstva prirode"],"question":"Koja svojstva se ubrajaju u es-sifatuz-zatijje?"},{"answer":"Allah postoji","options":["Allah je oduvijek","Allah postoji","Allah je zauvijek","Allah je moćan"],"question":"Šta znači Vudžud kao Allahovo svojstvo?"},{"answer":"Samo onako kako je On sam Sebe opisao","options":["Na bilo koji način","Samo onako kako je On sam Sebe opisao","Kao druge ljude","Koristeći poređenja sa stvorenjima"],"question":"Kako je dozvoljeno opisivati Allaha, dž.š.?"},{"answer":"Beka","options":["Vudžud","Kidem","Beka","Vudžud i Kidem"],"question":"Koje od ovih svojstava znači da Allah nema početka ni kraja?"},{"answer":"Jer nam je dao dokaze","options":["Jer vidimo Ga","Jer nam je dao dokaze","Jer je to napisano u knjizi","Jer su to rekli drugi"],"question":"Zašto znamo da Allah postoji?"}]},{"nivo":3,"slug":"zatijje-2","naslov":"Es-sifatuz-zatijje: Vahdanijet, Muhalefetun lil-havadisi, Kijamun bi nefsihi","content_html":"<div class=\"lesson-container\">\n        <h1>ES-SIFATUZ-ZATIJJE: VAHDANIJET, MUHALEFETUN LIL-HAVADISI I KIJAMUN BI NEFSIHI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/priroda.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Es-sifatuz-zatijje (2) – Vahdanijet, Muhalefetun lil-havadisi, Kijam binefsihi</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pravilnog razumijevanja Allahove jednoće i različitosti od stvorenja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti druge tri osobine bića: Vahdanijet, Muhalefet i Kijam binefsihi</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti razlikovanja Stvoritelja od stvorenog</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, jučer smo učili tri osobine bića. Danas još tri: Vahdanijet, Muhalefet, Kijam binefsihi.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Vahdanijet</strong> — jedinstvenost. Allah je samo jedan, nema druga ni sličnog.</p><p><strong>Muhalefetun lil-havadisi</strong> — različitost od stvorenja. Allah ne liči ničemu što je stvorio.</p><p><strong>Kijam binefsihi</strong> — samoopstojnost. Allah postoji sam po sebi, ne treba nikoga.</p><p>Sve stvoreno ovisi od nečeg drugog (čovjek od hrane, biljke od sunca). Samo Allah ne ovisi od ničega.</p><p>Allah u Kur’anu kaže: \"Niko Mu ravan nije.\"</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju svih 6 zatijje osobina. Zaključak: Allah je apsolutno savršen.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> JEDINSTVENOST STVORITELJA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>U svijetu u kojem živimo, često vidimo stvari koje su slične jedna drugoj – dva cvijeta, dvije pahulje ili dva čovjeka. Međutim, Stvoritelj svega što postoji je potpuno drugačiji. On je Jedinstven i niko Mu nije sličan.</p>\n                    <p>Kroz današnju lekciju nastavljamo spoznavati Allaha, dž.š., preko svojstava Njegovog Bića. Naučit ćemo da je On Jedan u svemu, da nikome i ničemu ne sliči i da je potpuno neovisan o bilo kome, dok sve drugo ovisi o Njemu. To nam pomaže da izgradimo ispravno vjerovanje i duboko poštovanje prema Uzvišenom Allahu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <i>Allah, dž.š., kaže: Reci: \"On je Allah - Jedan! Allah je Utočište svakom! Nije rodio i roden nije, i niko Mu ravan nije.\" (El-Ihlas, 1-4)</i>\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">U grupu svojstava es-sifatuz-zatijje, svojstva Allahovog bića, ubrajaju se: Vahdanijet, Muhalefetun lil-havadisi i Kijamun bi nefsihi.</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Vahdanijet - Allah je jedan.</span> Ovo svojstvo označava Allahovu apsolutnu jednoću u svemu. On je Jedan Jedini kako u Svom biću tako i u Svojim svojstvima i lijepim imenima, nema sudruga i nema ortaka. Ljudsko razmišljanje o svemu što postoji upućuje na jednost Allaha, dž.š.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Muhalefetun lil-havadisi - Allah nikome i ničemu ne sliči.</span> Ovo Allahovo svojstvo označava Allahovu posebnost od svega i svakoga (svačega). Njegova različitost je apsolutna u odnosu na Njegova stvorenja koja je On stvorio, a koja su međusobno po mnogo čemu slična. Stoga, uporediti Ga s bilo kim i bilo čim znači svoje vjerovanje dovesti u pitanje.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Kijamun bi nefsihi - Allah sam po Sebi opstoji.</span> Svojstvo Allahove neovisnosti podrazumijeva Allahovo postojanje bez bilo čije pomoći i nemogućnost da se dovede u pitanje Njegovo postojanje. Da bi postojao, nije Mu ništa potrebno jer je u svemu savršen. On nije ograničen ni vremenom ni prostorom, On sam po Sebi postoji.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <i>Da Zemljom i nebesima upravljaju drugi bogovi, a ne Allah, poremetili bi se. (El-Enbija, 22)</i>\n                </p>\n\n                <p class=\"lesson-text\">\n                    Na osnovu spomenutih svojstava znamo i vjerujemo da je Allah, dž.š., jedan. Njegova jednoća poriče postojanje svih drugih božanstava. Njemu niko nije sličan, niti On na koga liči. On sam po Sebi opstoji, nije ovisan ni o kome, niti Mu je iko potreban da bi On postojao.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <strong>HADIS</strong><br><br>\n                        Poslanik, alejhis-selam, je rekao: \"Razmišljajte o Allahovim stvorenjima a nemojte razmišljati o Allahovom biću.\" (Taberani)\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Poslanik, alejhis-selam, nas je obavijestio da Uzvišeni Allah kaže: \"O robovi Moji, sve zavisi od vaših djela, koja su kod Mene sačuvana i prebrojana, i za koja ću Ja vama dati zaslugu. Ko nađe nagradu i dobro neka zahvali Allahu, a ko nađe nešto mimo toga neka ne kori nikog osim sebe.\" (Muslim)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 8</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                    <p id=\"unlock-msg\" style=\"display: none;\">⭐ MAŠAALLAH! Uspješno ste savladali lekciju o svojstvima Vahdanijet, Muhalefetun lil-havadisi i Kijamun bi nefsihi. Sada možete označiti naučeno!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Šta znače Allahova, dž.š., svojstva: Vahdanijet, Muhalefetun lil-havadisi i Kijamun bi nefsihi i šta pomoću njih znamo?</li>\n                    <li>Kako nas Poslanik, alejhis-selam, savjetuje da spoznajemo Allaha, dž.š.?</li>\n                </ul>\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">IZABERI ZADATAK!</span></p>\n                <p class=\"lesson-text\">1. Allah, dž.š., nije ovisan ni o kome, a po čemu smo mi ovisni o Allahu Uzvišenom? Nađi nekoliko praktičnih primjera, zapiši!</p>\n                <p class=\"lesson-text\">2. Posmatraj buđenje prirode u proljeće i njeno gašenje u jesen. Zabilježi svoje dileme i razgovaraj o njima s muallimom/muallimōm!</p>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":7,"is_published":true,"kviz_pitanja":[{"answer":"Vahdanijet, Muhalefetun lil-havadisi, Kijamun bi nefsihi","options":["Vahdanijet, Muhalefetun lil-havadisi, Kijamun bi nefsihi","Vahdanijet, Kadir, Alim","Muhalefetun lil-havadisi, Hayy, Qawi","Kijamun bi nefsihi, Samit, Basir"],"question":"Koja tri svojstva spadaju u es-sifatuz-zatijje?"},{"answer":"Allah je jedan","options":["Allah je jedan","Allah je moćan","Allah je mudар","Allah je milostiv"],"question":"Šta Vahdanijet znači?"},{"answer":"Muhalefetun lil-havadisi","options":["Muhalefetun lil-havadisi","Vahdanijet","Kijamun bi nefsihi","Qudret"],"question":"Koje svojstvo pokazuje da Allah nikome ne sliči?"},{"answer":"Allah nije ovisan ni o kome","options":["Allah nije ovisan ni o kome","Allah je stvorio sve","Allah čuje sve","Allah je svemogućan"],"question":"Šta znači da Allah sam po Sebi postoji?"},{"answer":"Reci: On je Allah - Jedan","options":["Reci: On je Allah - Jedan","Allah je najmoćniji","Boga trebam slaviti","Čitaj nešto iz Qur'ana"],"question":"Koji je Qur'anski ajet o Allahovu jedinstvu?"}]},{"nivo":3,"slug":"subutijje-1","naslov":"Es-sifatus-subutijje: Hajat, 'Ilm, Sem' i Besar","content_html":"<div class=\"lesson-container\">\n        <h1>ES-SIFATUS-SUBUTIJJE: HAJAT, 'ILM, SEM' I BESAR</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sve_vidi.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Es-sifatus-subutijje (1) – Hajat, ‘Ilm, Sem‘, Besar</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti da nas Allah uvijek vidi, čuje i zna</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti prve četiri osobine svojstva: Hajat, ‘Ilm, Sem‘, Besar</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje takvaluka kroz svijest o Allahovim svojstvima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li Allah spava? Da li nas vidi i čuje? Da li sve zna? Te osobine zovemo subutijje.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Hajat</strong> — život. Allah je Živ vječno, ne umire i ne spava.</p><p><strong>‘Ilm</strong> — znanje. Allah sve zna — i ono što je bilo, i ono što jest, i ono što će biti, i ono što nije bilo.</p><p><strong>Sem‘</strong> — sluh. Allah sve čuje — i tihi šapat, i misli na jeziku.</p><p><strong>Besar</strong> — vid. Allah sve vidi — i u tami, i ispod zemlje, i u srcu.</p><p>Razgovor: kako se ponašamo znajući da nas Allah uvijek vidi i čuje?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju četiri osobine. Zaključak: Allah je uvijek sa nama u Svom znanju.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> POD OKOM SAVRŠENOG STVORITELJA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da se nalazite u potpunom mraku, u najdubljoj pećini, i da niko na svijetu ne zna gdje ste. Čak i u tom trenutku, postoji Neko ko vas vidi, ko čuje vaše otkucaje srca i ko zna svaku vašu misao. To je naš Gospodar, Allah, dž.š., čija su svojstva savršena i bez ikakvih granica.</p>\n                    <p>Danas učimo o skupini svojstava koja opisuju Allahovo savršenstvo. Saznat ćemo šta znači da Allah vječno živi, da Njegovo znanje obuhvata baš sve, te da Njegov sluh i vid ne poznaju prepreke koje mi ljudi imamo. Razumijevanje ovih svojstava pomaže nam da se osjećamo sigurno, znajući da nikada nismo sami i da nas naš Stvoritelj uvijek pazi i čuje.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <i>Allah, dž.š., kaže: On zna šta je bilo prije njih i zna šta će biti poslije njih, a od onoga što On zna, drugi znaju samo onoliko koliko On želi. (El-Bekare, 255)</i>\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Hajat, 'Ilm, Sem' i Besar su svojstva Allaha, dž.š. Ubrajaju se u grupu svojstava es-sifatus-subutijje, svojstva Allahovog savršenstva.</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Hajat - Allah živi</span> <span style=\"background-color: #fff9c4;\">Svojim vječnim životom.</span> Allah je živi i vječni. Njegov život je savršen, bez nedostataka i ograničenja, niko ne može utjecati na Njegov život. Za razliku od vječnog Allahovog života, život ljudi i drugih stvorenja je ograničen i prepun je neizvjesnosti i on je u Njegovoj vlasti.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">'Ilm-Allah sve zna.</span> Allah, dž.š., posjeduje savršeno znanje koje obuhvata sve ono što se desilo, što se sada dešava i što će se desiti. Za Allaha, dž.š., nema tajni i ništa Mu nije skriveno. Njegovo znanje nije ograničeno ni vremenom, ni prostorom. Isto tako, od Svoga znanja On ljudima daje samo onoliko koliko On želi. Njemu je poznato ono što uradimo, što kažemo i što pomislimo.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Sem' - Allah sve čuje.</span> Ovo Allahovo svojstvo proizlazi iz Allahove savršenosti, zato je i Njegov sluh savršen. On ne sluša čulom sluha, na Njegov sluh ne utječu fizičke prepreke ili udaljenost. Mnogo je kur'anskih ajeta koji nam govore da Allah sve čuje.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Besar - Allah sve vidi.</span> Allahovo svojstvo vida, kao i spomenuto svojstvo čula, proizlazi iz Njegove savršenosti u svakom pogledu. Na vid Allaha, dž.š., ne utječu određene prepreke niti tama noći. Česta poruka Njegove knjige je da Allah sve vidi.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Na osnovu spomenutih svojstava znamo i vjerujemo da Allah, dž.š., vječno živi, te da Njegov život nema ni početka ni kraja. Njegovo znanje obuhvata sve i ništa Mu nije skriveno. Za Njega nema tajni na nebesima ni na Zemlji, niti na Njegovo znanje može utjecati zaborav. Njegov sluh i vid su apsolutni i nisu ograničeni bez obzira na to koliko nešto bilo tiho ili sićušno. Na sluh i vid Allaha, dž.š., ne utječe ni velika udaljenost, niti kakva prepreka.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <strong>HADIS</strong><br><br>\n                        Poslanik, alejhis-selam, je rekao: \"Najviši stepen vjere je da budeš pokoran Allahu kao da Ga vidiš, jer, ako ti Njega ne vidiš, On tebe uistinu vidi.\" (Muslim)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 9</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                    <p id=\"unlock-msg\" style=\"display: none;\">⭐ MAŠAALLAH! Uspješno ste savladali lekciju. Sada možete označiti naučeno!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\"> PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Šta znače Allahova, dž.š., svojstva: Hajat, 'Ilm, Sem' i Besar i šta pomoću njih znamo?</li>\n                    <li>U koja svojstva Allaha, dž.š., se ubrajaju: Hajat, 'Ilm, Sem' i Besar?</li>\n                </ul>\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">RAZGOVOR S MUALLIMOM</span><br>\n                        Kako objasniti Allahova svojstva nekome ko nije čvrsto uvjeren u njih, posebno u svojstva da On sve zna i sve čuje? Kojim primjerima bi se mogao/la poslužiti?\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":8,"is_published":true,"kviz_pitanja":[{"answer":"Hajat, 'Ilm, Sem' i Besar","options":["Hajat, 'Ilm, Sem' i Besar","Hajat, 'Ilm, Kudret i Irada","Sem', Besar, Kudret i Hilm","'Ilm, Besar, Hikmah i 'Adalah"],"question":"Koja četiri svojstva Allaha se spominju u ovoj lekciji?"},{"answer":"Allah vječno živi bez početka i kraja","options":["Allah vječno živi bez početka i kraja","Allah sve zna što je bilo i što će biti","Allah sve čuje gdje god se nalazi","Allah sve vidi bez prepreke i tame"],"question":"Šta znači svojstvo 'Hajat' od Allaha?"},{"answer":"Ljudima daje samo znanje koje On želi","options":["Svima ljudima daje cjelokupno znanje","Ljudima daje samo znanje koje On želi","Samo proroci imaju pristup Allahovom znanju","Nikome ne daje pristup Allahovom znanju"],"question":"Kako se Allah služi Svojstvom 'Ilm' u odnosu na ljude?"},{"answer":"Na Allahov sluh i vid","options":["Na ljudski sluh i vid","Na Allahov sluh i vid","Na znanje običnih ljudi","Na viđenje u noći"],"question":"Na što ne mogu utjecati prepreke niti udaljenost?"},{"answer":"Allah ima vječan i savršen život bez ograničenja","options":["Allah ima malu moć i znanje","Allah živi samo dio vremena","Allah ima vječan i savršen život bez ograničenja","Ljudski život je bolji od Allahovog"],"question":"Šta znači da je Allahov život različit od ljudskog?"}]},{"nivo":3,"slug":"subutijje-2","naslov":"Es-sifatus-subutijje: Iradet, Kudret, Kelam i Tekvin","content_html":"<div class=\"lesson-container\">\n        <h1>ES-SIFATUS-SUBUTIJJE: IRADET, KUDRET, KELAM I TEKVIN</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/tekvin.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Es-sifatus-subutijje (2) – Iradet, Kudret, Kelam, Tekvin</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pouzdanja u Allahovu volju i moć</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti druge četiri osobine svojstva: Iradet, Kudret, Kelam, Tekvin</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje tevekkula — oslanjanja na Allaha</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, jučer smo učili četiri osobine svojstva. Danas još četiri: Iradet, Kudret, Kelam, Tekvin.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Iradet</strong> — volja. Allah radi šta hoće — niko Mu ne može stati na put.</p><p><strong>Kudret</strong> — moć. Allah je svemoguć — sve Mu je moguće.</p><p><strong>Kelam</strong> — govor. Allah govori bez glasa, bez slova, bez jezika — Njegov govor čuli su Mūsa, a.s. (na Tūru) i Muhammed, a.s. (na Mi‘rādžu).</p><p><strong>Tekvin</strong> — stvaranje. Allah je Stvoritelj — sve što postoji, On je stvorio.</p><p>Allahove osobine su savršene — beskonačne i bez nedostatka.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju svih 8 subutijje osobina. Zaključak: razmišljati o Allahovim osobinama jača iman.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">\n                UVODNA PRIČA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Draga djeco, zamislite da želite nešto napraviti, ali nemate snage. Ili imate snagu, ali niste odlučili šta tačno želite. Kod nas ljudi, želja i mogućnost su često razdvojeni. Međutim, kod našeg Stvoritelja, sve što On poželi, On to Svojom moći i stvori. Ništa na ovom svijetu ne nastaje slučajno. Svaka pahulja snijega, svaki list na drvetu i svaki otkucaj tvog srca rezultat su Allahove volje i Njegove neopisive moći. Danas učimo kako Allah Svojim govorom i stvaranjem održava ovaj cijeli svijet u savršenom redu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Iradet, Kudret, Kelam i Tekvin su svojstva Allaha, dž.š. Ubrajaju se u grupu svojstava es-sifatus-subutijje, svojstva Allahovog savršenstva.</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Iradet - Allah sve Svojom voljom čini.</span>\n                </p>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: <i>Ako nešto hoćemo, Mi samo za to reknemo: \"Budi\", i ono bude.</i> (En-Nahl, 40)\n                    </p>\n                </div>\n                <p class=\"lesson-text\">\n                    Volja Allaha, dž.š., je neograničena i savršena. Ona obuhvata sve što se događa na ovome svijetu i što će se događati na budućem svijetu. U skladu s Njegovom voljom su zakoni u prirodi, lanac ishrane te društveni zakoni. Bez Njegove volje se ne događa ništa, On stvara šta hoće, On sve može.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Kudret - Allah je svemoćan.</span>\n                </p>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: <i>Allahova je vlast, na nebesima i na Zemlji i na onome što je između njih; On stvara šta hoće, Allah sve može.</i> (El-Maide, 17)\n                    </p>\n                </div>\n                <p class=\"lesson-text\">\n                    Svemoćan je Allah, upravlja onim što postoji, svemoćan je u Svom stvaranju. Njegovo stvaranje obuhvata savršenost u svemu što je stvorio, stvorio je Zemlju i nebesa; Sunce i Mjesec; dan i noć; biljni i životinjski svijet, Njemu ne dojadi održavanje svega spomenutog. Poseban primjer Božije svemoći je stvaranje čovjeka, najsavršenijeg stvorenja koje se sastoji od duše i tijela.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Kelam - Allah govori Svojim božanskim govorom.</span>\n                </p>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: <i>Allah objavljuje najljepši govor.</i> (Ez-Zumer, 23)\n                    </p>\n                </div>\n                <p class=\"lesson-text\">\n                    Govor Allaha, dž.š., je savršen i bez ikakvih nedostataka. Primjer Allahovog govora je sadržan u Kur'anu koji je dokaz Njegove savršenosti u govoru bez grešaka i proturječnosti. Mogućnost da kroz Kur'an čitamo i razumijevamo Allahov govor posebna je blagodat koja je data ljudima. Govor Allaha, dž.š., nadahnjuje čovjeka i onda kada ga ne razumije.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Tekvin - Allah sve stvara, održava i rastvara.</span>\n                </p>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: <i>Zato pogledaj tragove Allahove milosti kako On oživi zemlju nakon mrtvila njezina! On će, uistinu, i mrtve oživjeti, On sve može.</i> (Er-Rum, 50)\n                    </p>\n                </div>\n                <p class=\"lesson-text\">\n                    Allahovo svojstvo stvaranja, održavanja i rastvaranja je osnova Allahovog djelovanja. On sve stvara, zatim to Svojom moći održava i na kraju sve to rastvara. Sve što postoji ili je postojalo nekada je iz ničega nastalo, a nakon određenog vremena Allahovom voljom će sve to i nestati.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Na osnovu spomenutih svojstava znamo i vjerujemo da je volja Uzvišenog Allaha apsolutna i neograničena i da ona nije ničim uvjetovana. On čini šta hoće i ništa nije <span style=\"background-color: #fff9c4;\">izvan Njegove volje.</span> Isto tako, Njegova moć je neograničena - On je svemoćan. Allahov govor je sadržan u Kur'anu i on je savršen, nema nedostataka niti ima grešaka. Allah sve stvara, On sve održava i onog dana kada On odredi sve će nestati.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Pored toga što čovjek ima svoje osobine koje se imenuju kao i Allahova svojstva, treba znati i uvijek na umu imati da su svojstva čovjeka ograničena i kao takva neuporediva s Njegovim svojstvima.</span>\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz-section', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz-section\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 10</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"pitanja\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta znače sljedeća Allahova, dž.š., svojstva i šta pomoću njih znamo: Hajat, 'Ilm, Sem' i Besar?</li>\n                    <li>Po čemu se razlikuju ljudska svojstva koja se nazivaju kao neka Allahova svojstva?</li>\n                </ol>\n                <p class=\"lesson-text\" style=\"font-weight: bold; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Izaberi jedno od svojstava Allaha, dž.š., a kojim imenujemo neko ljudsko svojstvo i napiši šta karakterizira to ljudsko svojstvo. Navedi prednosti Allahovog svojstva.</li>\n                    <li>Istraži u svojoj okolini koje se to riječi ili sintagme koriste, a muslimani ih ne bi smjeli koristiti jer su svojstvene samo Allahu, tj. svojstvima Allahovog bića i Allahovog savršenstva!</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":9,"is_published":true,"kviz_pitanja":[{"answer":"Iradet","options":["Iradet","Kudret","Kelam","Tekvin"],"question":"Koje svojstvo Allaha znači da On sve stvara svojom voljom?"},{"answer":"Kur'an","options":["Suna Poslanika","Kur'an","Hadis","Fetvа"],"question":"Šta je primjer Allahovog govora prema tekstu lekcije?"},{"answer":"Četiri svojstva","options":["Dva svojstva","Tri svojstva","Četiri svojstva","Pet svojstava"],"question":"Koliko svojstava es-sifatus-subutijje se nalazi u ovoj lekciji?"},{"answer":"Punо savršenosti","options":["Sa greškama","Punо savršenosti","Nepotpuno","Slučajno"],"question":"Kakvo je stvaranje Allaha prema svojstvu Kudreta?"},{"answer":"Tekvin","options":["Iradet","Kudret","Kelam","Tekvin"],"question":"Koje svojstvo Allaha znači da On sve stvara, održava i rastvara?"}]},{"nivo":3,"slug":"esmaul-husna","naslov":"Allahova lijepa imena - El-Esmaul-husna","content_html":"<div class=\"lesson-container\">\n        <h1>ALLAHOVA LIJEPA IMENA - EL-ESMAUL-HUSNA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/husna.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">El-Esmā’ul-husnā – Allahova lijepa imena</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Allahu kroz Njegova lijepa imena</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pojam Esmaul-husna i bar 10 Allahovih imena sa značenjem</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da koriste Allahova imena u dovi</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, znate li da Allah ima 99 lijepih imena? Hajde da naučimo neka od njih.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Esmaul-husna su 99 najljepših Allahovih imena.</p><p>Poslanik, a.s., je rekao: \"Ko ih nauči i prema njima živi — ući će u Džennet.\"</p><p>Primjeri: <strong>Allāh</strong> (najveće ime), <strong>Er-Rahmān</strong> (Sveopći Milostivi), <strong>Er-Rahīm</strong> (Posebno Milostivi), <strong>El-Melik</strong> (Vladar), <strong>El-Quddūs</strong> (Sveti), <strong>Es-Selām</strong> (Mir), <strong>El-Mu’min</strong> (Pružatelj sigurnosti), <strong>El-Muhejmin</strong> (Čuvar), <strong>El-‘Azīz</strong> (Silni), <strong>El-Džebbār</strong> (Snažni), <strong>El-Mutekebbir</strong> (Uzvišeni)...</p><p>U dovi koristimo Allahova imena: \"O Rahmane, smiluj se\", \"O Razzaq, nahrani me halalom\".</p><p>Postupak: Učimo prvih 10 imena sa značenjem na tabli.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju 5-7 imena sa značenjem. Zadaća: naučiti narednih 10 imena.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                KAKO UPOZNATI ALLAHA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Draga djeco, kada nekoga volimo, želimo znati sve o njemu – kako se zove, kakav je i šta voli. Naš Stvoritelj nam je podario najljepši način da Ga upoznamo, a to je kroz Njegova imena. Svako Allahovo ime je kao jedan prozor kroz koji možemo vidjeti Njegovu beskrajnu milost, moć i dobrotu.</p>\n                    <p>Kada su ashabi pitali Muhammeda, alejhis-selam, kako da najbolje upoznaju Allaha, dobili su predivne odgovore koji su nas naučili da Ga dozivamo najljepšim imenima. Danas ćemo naučiti neka od tih imena koja nam pomažu da razumijemo koliko nas naš Gospodar voli i čuva.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: ALLAH IMA NAJLJEPŠA IMENA I VI GA ZOVITE NJIMA, A KLONITE SE ONIH KOJI ISKREĆU NJEGOVA IMENA - KAKO BUDU RADILI, ONAKO ĆE BITI KAŽNJENI. (El-A'raf, 180)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Vlastito Božije ime je Allah.</span> Ono označava Jednog, Jedinog Boga, Stvoritelja i Vladara svega što postoji. Ime Allah je u Kur'anu spomenuto 2.698 puta. Pored ovog imena, koje se najčešće spominje, postoje i druga Allahova lijepa imena koja nazivamo el-esmaul-husna.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        HADIS<br><br>\n                        Poslanik, alejhis-selam, je rekao: \"Allah, uistinu, ima devedeset devet imena, jedno manje od stotinu. Onaj ko ih bude znao (razumijevao njihova značenja i prema njima se vladao) ući će u Džennet.\" (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Razumijevati Allahova imena podrazumijeva shvatanje da ljudi mogu biti milostivi, blagi, istinoljubivi, pravedni, plemeniti, da mogu praštati jedni drugima itd. Allah je naš najveći Pomagač, Zaštitnik i Dobročinitelj, Koji život i smrt daje. On prima naša iskrena pokajanja i molbe naše uslišava. Kada su ashabi rekli Muhammedu, alejhis-selam, da žele upoznati Allaha, objavljena je sura El-Ihlas: Reci: \"On je Allah Jedan! Allah je Utočište svakom! Nije rodio i rođen nije, i niko Mu ravan nije!\"\n                </p>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., je vječan i neprolazan i svojstva koja izražavaju Njegova imena su vječna. Islamski učenjaci su imena Allaha, dž.š., podijelili u dvije grupe:\n                </p>\n                <ul>\n                    <li><span style=\"background-color: #fff9c4;\">imena ljepote - esmaul-džemal</span> - to su imena koja se odnose na Milost i Oprost, npr. Er-Rahman (Milostivi), Er-Rahim (Svemilosni), El-Kerim (Velikodušni), El-Gaffar (Onaj Koji prašta),</li>\n                    <li><span style=\"background-color: #fff9c4;\">imena uzvišenosti - esmaul-dželal</span> - to su imena koja se odnose na pravdu, presudu, strogost, npr. El-Adil (Pravedni), El-Aziz (Silni), Seriul-Hisab (Onaj Koji je brz u sravnavanju računa).</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Iz Svoje neizmjerne milosti Allah, dž.š., nam je otkrio Svoja imena i uputio nas da Mu se preko njih obraćamo dovom. Lijepo je kada molimo Allaha, dž.š., za milost, da Ga dozivamo: Ja Rahmanu, ja Rahimu – o Svemilosni, o Milostivi; kada tražimo od Allaha oprost, da Ga dozivamo: Ja Gaffaru – o Ti Koji mnogo praštaš; kada molimo za opskrbu, da Ga dozivamo: Ja Rezzaku itd.\n                </p>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">\n                    <span style=\"background-color: #fff9c4;\">Allahova lijepa imena opisuju svojstva Uzvišenog Allaha, npr.:</span>\n                </p>\n\n                <div class=\"names-grid\">\n                    <div class=\"name-item\">1. Allah - Allah je Jedan, osim Njega drugog boga nema,</div>\n                    <div class=\"name-item\">2. Er-Rahman - Milostivi, Koji Svojom milošću obuhvata sva stvorenja,</div>\n                    <div class=\"name-item\">3. Er-Rahim - Samilosni, Koji ima obilnu milost prema vjernicima,</div>\n                    <div class=\"name-item\">4. El-Melik - Vladar, Koji ima potpunu vlast,</div>\n                    <div class=\"name-item\">5. El-Kuddus - Sveti, Čisti, Koji je čist od svih nedostataka,</div>\n                    <div class=\"name-item\">6. Es-Selam - Izvor mira,</div>\n                    <div class=\"name-item\">7. El-Mu'min - Davatelj sigurnosti, Koji osigurava mir, sigurnost i pruža zaštitu,</div>\n                    <div class=\"name-item\">8. El-Muhejmin - Zaštitnik, Koji bdije nad Svojim stvorenjima,</div>\n                    <div class=\"name-item\">9. El-Aziz - Moćni, Koji posjeduje najveću snagu,</div>\n                    <div class=\"name-item\">10. El-Džebbar - Silni, Koji prisiljava da se sve prema Njegovoj volji događa,</div>\n                    <div class=\"name-item\">11. El-Mutekebbir - Veličanstveni, Koji je jedinstven po Svojoj veličini i ponosu,</div>\n                    <div class=\"name-item\">12. El-Halik - Tvorac, Koji je stvorio kosmos i sve što postoji,</div>\n                    <div class=\"name-item\">13. El-Bari' - Stvoritelj, Koji iz ničega stvara,</div>\n                    <div class=\"name-item\">14. El-Musavvir - Darovatelj oblika, Koji daje oblik i različite forme stvorenjima,</div>\n                    <div class=\"name-item\">15. El-Gaffar - Onaj Koji mnogo prašta,</div>\n                    <div class=\"name-item\">18. Er-Rezzak - Hranitelj, Koji Svojim stvorenjima neprestano daje opskrbu,</div>\n                    <div class=\"name-item\">19. El-Fettah - Koji sve otvara, Koji Svojim robovima poteškoće razrješava,</div>\n                    <div class=\"name-item\">20. El-Alim - Sveznajući, Koji zna ono što ne znaju Njegova stvorenja, bez čijeg se znanja ništa ne događa.</div>\n                </div>\n\n                <div class=\"info-box\" style=\"margin-top: 30px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">ZAPAMTI!</span><br><br>\n                        1. Poslanik, alejhis-selam, je preporučio sljedeće: \"Ko prouči posljednje ajete sure El-Hašr u toku noći ili dana i umre u toj noći ili u tom danu Allah će mu osigurati Džennet.\" (Bejheki)<br><br>\n                        2. On je Allah nema drugog boga osim Njega - On je poznavalac nevidljivog i vidljivog svijeta, On je Milostivi, Samilosni! On je Allah - nema drugog boga osim Njega, Vladar, Sveti, Onaj koji je bez nedostataka, Onaj koji svakoga osigurava, Onaj koji nad svim bdi, Silni, Uzvišeni, Gordi. Hvaljen neka je Allah, On je vrlo visoko iznad onih koje smatraju Njemu ravnim! On je Allah, Tvorac, Onaj koji iz ničega stvara, Onaj koji svemu daje oblik, On ima najljepša imena. Njega hvale onī na nebesima i na Zemlji, On je Silni i Mudri. (El-Hašr, 22-24)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 11</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Koliko puta je vlastito ime Allah spomenuto u Kur'anu?</li>\n                    <li>Koliko ima Allahovih lijepih imena i šta postižemo njihovim poznavanjem?</li>\n                    <li>Na koje dvije grupe se dijele Allahova lijepa imena?</li>\n                    <li>Pronađi u tekstu imena koja znače: Sveznajući, Vladar, Tvorac i Mir!</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":10,"is_published":true,"kviz_pitanja":[{"answer":"Devedeset devet imena","options":["Devedeset devet imena","Sto imena","Pedeset imena","Sto dvadeset imena"],"question":"Koliko Allahovih lijepih imena postoji prema hadisu?"},{"answer":"El-esmaul-husna","options":["El-esmaul-husna","El-Ihlas","El-Adil","Er-Rahman"],"question":"Kako se nazivaju Allahova lijepa imena?"},{"answer":"2.698 puta","options":["2.698 puta","1.000 puta","5.000 puta","3.000 puta"],"question":"Koliko puta je ime Allah spominjuto u Kur'anu?"},{"answer":"Er-Rahman, Er-Rahim, El-Kerim","options":["Er-Rahman, Er-Rahim, El-Kerim","El-Adil, El-Aziz","Seriul-Hisab","El-Gaffar"],"question":"Koja imena spadaju u esmaul-džemal (imena ljepote)?"},{"answer":"Ja Gaffaru - o Ti Koji praštaš","options":["Ja Gaffaru - o Ti Koji praštaš","Ja Rahmanu - o Svemilosni","Ja Rezzaku - o Uzdržavač","Ja Aziżu - o Silni"],"question":"Kako se Bogu obraćamo kada tražimo oprost?"}]},{"nivo":3,"slug":"melaike","naslov":"Ve melāiketihī - vjerovanje u Allahove meleke","content_html":"<div class=\"lesson-container\">\n        <h1>VE MELĀIKETIHĪ – VJEROVANJE U ALLAHOVE MELEKE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/meleki.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ve melāiketihī – vjerovanje u Allahove meleke</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o melekima koji nas okružuju i svjedoče</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Detaljno razumjeti drugi imanski šart i ulogu meleka</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike čišćeg ponašanja zbog svijesti o melekima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, danas više detaljno o melekima — drugom imanskom šartu. Šta meleki rade, kako ih opisujemo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Meleki su Allahova bića stvorena od svjetla (nūra), pokorni Mu i bez slobode izbora.</p><p>Imaju krila, mnogo ih je, mi ih ne vidimo (osim u posebnim prilikama).</p><p>Glavni meleki sa zaduženjima: Džibrīl (objava), Mikāil (kiša/opskrba), Israfil (sūr), Azrāil (smrt), Munker i Nekīr (kabur), Kirāmen Kātibīn (zapisivači), Ridvān (Džennet), Mālik (Džehennem).</p><p>Vjernik u Allaha mora vjerovati i u meleke — bez toga iman nije potpun.</p><p>Meleki vole vjernike, čine dovu za njih, prisustvuju nauci i namazu u džematu.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju glavne meleke i njihove funkcije. Zaključak: meleki su naši nevidljivi prijatelji u dobru.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":11,"is_published":true,"kviz_pitanja":[{"answer":"Od nura - svjetlosti","options":["Od vode i zemlje","Od nura - svjetlosti","Od kamena i drveta","Od pjeska i blata"],"question":"Od čega su Allah stvorili meleke?"},{"answer":"Džibril","options":["Mikail","Azrail","Džibril","Israfil"],"question":"Koji je melek donosio Allahove objave poslanicima?"},{"answer":"Dvadeset i tri godine","options":["Deset godina","Dvadeset i tri godine","Pet godina","Trideset godina"],"question":"Koliko godina je Džibril dostavljao Kur'an Poslaniku?"},{"answer":"Spuštanje kiše i vjetrova","options":["Uzimanje duša iz tijela","Obavijest o Smaku svijeta","Praćenje naših djela","Spuštanje kiše i vjetrova"],"question":"Koja je zadaća meleka Mikail?"},{"answer":"Griješe i čine loše","options":["Pojavljuju se u ljudskom liku","Griješe i čine loše","Hvale Allaha","Prate nas noću i danju"],"question":"Šta meleki NISU sposobni da rade?"}]},{"nivo":3,"slug":"dzini-sejtani","naslov":"Druga duhovna bića – džini i šejtani","content_html":"<div class=\"lesson-container\">\n        <h1>DRUGA DUHOVNA BIĆA – DŽINI I ŠEJTANI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dzini_sejtani.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Druga duhovna bića – džini i šejtani</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o opasnosti šejtana i načina zaštite od njega</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta su džini i šejtani, kako su stvoreni i kako djeluju</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da se zaštite od šejtana učenjem dova i Kur’ana</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, postoje li bića koja su zlo i šta žele od nas? Da! Šejtan i njegovi pomoćnici. Šta o njima znamo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Džini su bića stvorena od vatre (od dima vatre). Imaju razum i slobodu izbora — ima muslimana i kafira među njima.</p><p>Šejtan (Iblīs) je bio od džinā. Odbio je da učini sedždu Ademu — postao je prokleti, neprijatelj čovjeka.</p><p>Šejtanov posao: da nas zavodi sa pravog puta, šapuće zlo, izaziva svađe, navodi na grijehe.</p><p>Zaštita od šejtana: učenje Bismille, učenje sure El-Felek, En-Nās, Ajetul-kursijja, izbjegavanje samoće u tami, dova prije spavanja, čistoća (abdest).</p><p>Šejtan nema vlast nad iskrenim Allahovim robovima — jaki iman je najbolja zaštita.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju načine zaštite od šejtana. Učimo skraćeno \"E‘ūzu billāhi mineš-šejtānir-radžīm\".</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                BORBA IZMEĐU DOBRA I ZLA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Svijet koji nas okružuje mnogo je širi od onoga što možemo dohvatiti rukama ili vidjeti očima. Baš kao što osjećamo vjetar koji ne vidimo, ili ljubav koja nema boju, tako u kosmosu postoje i bića koja dijele prostor s nama, ali ostaju skrivena našem pogledu. Ponekad osjetimo neobičnu misao koja nas vuče da uradimo nešto što znamo da nije lijepo, ili pak osjetimo snagu da se odupremo nečemu lošem. To je ta vječita borba između svjetla i tame, dobra i zla, koja se ne odvija negdje daleko, već u srcu svakog od nas.</p>\n                    <p>Upoznati ta nevidljiva bića znači razumjeti kako sačuvati svoj mir i kako ostati na strani dobra. Danas ćemo naučiti ko su džini i šejtani, kako su stvoreni i zbog čega je važno znati da oni nemaju vlast nad onima koji se čvrsto oslone na svog Stvoritelja. Ova priča nije tu da nas plaši, već da nas učini mudrijim i snažnijim u našim svakodnevnim odlukama.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: ...on doista nema nikakve vlasti nad onima koji vjeruju i koji se u Gospodara svoga pouzdaju; njegova je vlast jedino nad onima koji njega za zaštitnika uzimaju i koji druge Allahu ravnim smatraju. (En-Nahl, 99-100)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Osim meleka, Uzvišeni Allah je stvorio i druga nevidljiva duhovna bića koja nazivamo džini i šejtani. \n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: a još prije smo stvorili džine od vatre užarene. (El-Hidžr, 27)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Zbog njihove nevidljivosti, postoje mnoga vjerovanja koja se tiču džina i većinu njih ubrajamo u sujevjerja. Muslimani i muslimanke o džinima znaju i vjeruju samo ono o čemu su obaviješteni u Kur'anu i hadisima. \n                </p>\n\n                <p class=\"lesson-text\">\n                    Prema islamskom učenju, džini su stvoreni od vatre, prije ljudi i kao takvi nastanjivali su Zemlju, ali i planete u svemiru. Džini imaju razum, pamet, veliku snagu i sposobnost. Ima ih dobrih i loših, vjernika i nevjernika, oni nas vide dok mi njih ne vidimo. \n                </p>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., u Kur'anu navodi riječi jednog džina: I ima nas muslimana, a ima nas zalutalih; oni koji islam prihvate Pravi put su izabrali. (El-Džin, 14) \n                </p>\n\n                <p class=\"lesson-text\">\n                    Džine nevjernike nazivamo šejtanima. Vođa im je Iblis. Šejtani su čovjekovi otvoreni neprijatelji. Oni opsjedaju ljudsku misao i podstiču na zlo prikazujući im grijeh lijepim i privlačnim. Šejtan je nagovorio Adema, alejhis-selam, da učini zabranjeno djelo, pa je izveden iz Dženneta. Šejtan čini sve da ljude zavede i da ih spriječi da uđu u Džennet, udaljava ih od Pravog puta, zavodi ih i uljepšava put ka vatri Džehennema. <span class=\"highlight\">Šejtan je simbol zla.</span> \n                </p>\n\n                <p class=\"lesson-text\">\n                    Zlobni i pokvareni ljudi koji raznim sredstvima i načinima napadaju na razum i srca ljudi da bi ih odvratili od pravog puta i od islamskog ponašanja pomažu šejtanima u njihovom djelovanju. \n                </p>\n\n                <p class=\"lesson-text\">\n                    Da bismo bili sačuvani od šejtana, prije svega treba tražiti Allahovu zaštitu od prokletog šejtana, jer on ne može nanijeti nikakvu štetu onima koji vjeruju i uzdaju se u Allaha. \n                </p>\n\n                <p class=\"lesson-text\">\n                    Allahovu zaštitu od šejtana tražimo riječima: <span style=\"background-color: #fff9c4;\">E'UZU BILLAHI MINEŠ-ŠEJTANIR-RADŽIM</span>, što znači: Tražim Allahovu zaštitu od prokletog šejtana. \n                </p>\n\n                <p class=\"lesson-text\">\n                    Također, učenjem sura El-Felek i En-Nas tražimo Allahovu zaštitu od prokletog šejtana. Čovjek je u stanju činiti dobra i korisna djela i biti daleko od šejtanskog zla ukoliko se pridržava kur'anskih uputa i ako se čuva od šejtanskog usmjeravanja. \n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <strong>HADIS</strong><br><br>\n                        Poslanik, alejhis-selam, je rekao: \"Šejtan vreba čovjekovo srce (da bi ga zaveo), ali kada čovjek spomene Allaha, on se povlači. Kada čovjek Allaha zaboravi, šejtan počinje napadati.\" (Buhari)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 13</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Koja je još nevidljiva bića stvorio Allah, dž.š., osim meleka? </li>\n                    <li>Šta su džini, a šta šejtani? </li>\n                    <li>Kako se čovjek može zaštititi od šejtana? </li>\n                </ol>\n\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">ZAPAMTI!</span><br>\n                        Kada nas šejtan nagovara na loša djela, prisjetimo se da nas Allah, dž.š., vidi u svakoj situaciji. \n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"font-weight: bold; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Opiši jednu životnu situaciju u kojoj te šejtan nagovorio na neko loše djelo. Razgovarajte s muallimom/muallimom o tom postupku i načinu na koji se mogao izbjeći! </li>\n                    <li>Napiši šta učiš kako bi se zaštitio od prokletog šejtana, te kada to učiš i podijeli sa svojim kolegama i kolegicama. </li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":12,"is_published":true,"kviz_pitanja":[{"answer":"Od vatre užarene","options":["Od vode","Od vatre užarene","Od zemlje","Od zraka"],"question":"Od čega su stvoreni džini prema Kur'anu?"},{"answer":"Iblis","options":["Šejtan sam","Malak","Iblis","Džin"],"question":"Ko je vođa šejtana?"},{"answer":"Podstižu na zlo i odvraćaju od puta","options":["Štite ih od bolesti","Daju im novac","Podstižu na zlo i odvraćaju od puta","Nauče ih liječenju"],"question":"Šta šejtani rade ljudima?"},{"answer":"Džini imaju razum, vidljivi su","options":["Nisu, isti su","Džini su nevidljivi duhovi kao anđeli","Džini imaju razum, vidljivi su","Nema razlike"],"question":"Kako su džini različiti od anđela?"},{"answer":"Od prokletog šejtana","options":["Od bolesti","Od gladnog šejtana","Od prokletog šejtana","Od vode"],"question":"Od koga se štitimo izgovaranjem 'E'UZU BILLAHI MINEŠ-ŠEJTANIR-RADŽIM'?"}]},{"nivo":3,"slug":"kitabi","naslov":"Ve kutubihī - vjerovanje u Allahove knjige i suhufe","content_html":"<div class=\"lesson-container\">\n        <h1>VE KUTUBIHĪ – VJEROVANJE U ALLAHOVE KNJIGE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/knjige_suhufi.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ve kutubihī – vjerovanje u Allahove knjige i suhufe</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje poštovanja prema Kur’anu kao posljednjoj objavi i ranijim Allahovim knjigama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti koje su knjige i suhufi objavljeni i kome</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike svakodnevnog čitanja Kur’ana</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko je Allah objavio knjiga? Nabrojite ih. A šta je sa suhufima — kratkim listovima objave?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah je objavio velike knjige: Tevrāt (Mūsau, a.s.), Zebūr (Dāvudu, a.s.), Indžil (Īsau, a.s.), Kur’an (Muhammedu, a.s.).</p><p>Pored knjiga, objavio je i suhufe (kratke listove): Ademu, a.s. (10), Šītu, a.s. (50), Idrisu, a.s. (30), Ibrāhīmu, a.s. (10), Mūsau, a.s. (10).</p><p>Sve prijašnje knjige i suhufi su tokom vremena izgubljeni ili izmijenjeni od strane ljudi.</p><p>Kur’an je posljednja Allahova objava i sačuvan je u izvornom obliku do Sudnjega dana — Allah Ga čuva.</p><p>Naša obaveza: vjerovati u sve Allahove objave, ali slijediti samo Kur’an i sunnet.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju četiri velike knjige i njihove poslanike. Zaključak: Kur’an je svjetlo i uputa za sve nas.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":13,"is_published":true,"kviz_pitanja":[{"answer":"Ve kutubihî","options":["Ve kutubihî","Ve rasulihî","Ve melekihî","Ve yaumihî"],"question":"Kako se zove vjerovanje u Allahove knjige na arapskom jeziku?"},{"answer":"Kroz meleka Džibrila","options":["Kroz meleka Džibrila","Kroz arađele","Kroz čovjeka","Kroz anđele bez imena"],"question":"Kroz koga je Allah objavljivao svoje knjige poslanicima?"},{"answer":"Tevrat objavljena Musau","options":["Tevrat objavljena Musau","Zebur objavljen Davudu","Indžil objavljen Isau","Kuran objavljen Muhammadu"],"question":"Koja je prva velika Allahova knjiga objavljena?"},{"answer":"Stotinu suhufa","options":["Stotinu suhufa","Pedeset suhufa","Dvjesto suhufa","Deset suhufa"],"question":"Koliko suhufa (manjih objava) je prema islamskoj tradiciji objavljeno?"},{"answer":"Vjerske pjesme","options":["Vjerske pjesme","Zakone i propise","Božje poruke","Priče i legende"],"question":"Šta znači Zebur objavljen Davudu, alejhis-selam?"}]},{"nivo":3,"slug":"kuran-objava","naslov":"Kur'an – Posljednja objava","content_html":"<div class=\"lesson-container\">\n        <h1>KUR'AN – POSLJEDNJA OBJAVA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/kuran.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kur’an – Posljednja objava</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje duboke ljubavi i poštovanja prema Kur’anu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti osnovne činjenice o Kur’anu — kako je objavljen, sastav, čuvanje</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike svakodnevnog učenja i razmišljanja o Kur’anu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koja je naša najveća čast? Kur’an. A šta o njemu znamo? Kako je sačuvan? Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kur’an je Allahov govor, objavljen Muhammedu, a.s., posredstvom meleka Džibrila, na arapskom jeziku.</p><p>Objavljivao se 23 godine — 13 godina u Mekki, 10 godina u Medini.</p><p>Sastav: 114 sūra, 6.236 ajeta, 30 džuzova (dijelova).</p><p>Prvi objavljeni ajeti: \"Iqra’ bismi rabbike-l-lezī halaq...\" (sura El-‘Alaq).</p><p>Kur’an je sačuvan: napamet (haffaz) i zapisivanjem (mushafi). Niko ga nije promijenio i nikad neće.</p><p>Razgovor: koliko vremena svaki dan učimo Kur’an? Kako razumjemo njegove poruke?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako će povećati svoj odnos sa Kur’anom. Zaključak: Kur’an je naše svjetlo.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":14,"is_published":true,"kviz_pitanja":[{"answer":"Na arabskom jeziku","options":["Na arabskom jeziku","Na turskom jeziku","Na perzijskom jeziku","Na hebrejskom jeziku"],"question":"Na kojem jeziku je objavljen Kur'an?"},{"answer":"114 sura","options":["114 sura","100 sura","150 sura","200 sura"],"question":"Koliko sura sadrži Kur'an?"},{"answer":"U pećini Hira na brdu Nur","options":["U pećini Hira na brdu Nur","U Medini","U Jerusalimu","U Al-Aksi"],"question":"Gdje je počelo objavljivanje Kur'ana?"},{"answer":"23 godine","options":["23 godine","10 godina","13 godina","30 godina"],"question":"Koliko godina je trajalo objavljivanje Kur'ana?"},{"answer":"Halifa Ebu Bekr","options":["Halifa Ebu Bekr","Muhammed alejhis-selam","Halifa Omer","Halifa Osman"],"question":"Ko je prvi sakupio Kur'an u zbirku Mushaf?"}]},{"nivo":3,"slug":"poslanici","naslov":"Ve rusulihī - vjerovanje u Allahove poslanike i odlike poslanika","content_html":"<div class=\"lesson-container\">\n        <h1>VE RUSULIHĪ – VJEROWANJE U ALLAHOVE POSLANIKE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/poslanici.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ve rusulihī – vjerovanje u Allahove poslanike i odlike poslanika</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i poštovanja prema svim Allahovim poslanicima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam poslanstva, broj poslanika i njihove odlike</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti slijeđenja Poslanikovog, a.s., sunneta</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko je bilo poslanika? Šta ih čini posebnim? Koje odlike (sifat) imaju svi poslanici?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanici su odabrani ljudi koje je Allah slao da poučavaju ljude vjeri.</p><p>Poimence se u Kur’anu spominju 25 poslanika, ali ih je bilo mnogo više.</p><p>Pet velikih poslanika (Ulul-‘azm): Nūh, Ibrāhīm, Mūsa, Īsa, Muhammed (alejhimus-selam).</p><p>Pet odlika (sifat) poslanika: <strong>Sıdk</strong> (istinitost), <strong>Emānet</strong> (povjerenje), <strong>Tebliġ</strong> (dostavljanje poruke), <strong>Fatānet</strong> (mudrost), <strong>‘Ismet</strong> (čistoća od grijeha).</p><p>Razlika: <strong>Nebijj</strong> — poslanik bez nove knjige; <strong>Resūl</strong> — poslanik sa novom knjigom/šerijatom.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju pet velikih poslanika i pet odlika. Zaključak: poslanici su svjetla na našem putu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":15,"is_published":true,"kviz_pitanja":[{"answer":"Adem, alejhis-selam","options":["Adem, alejhis-selam","Nuh, alejhis-selam","Ibrahim, alejhis-selam","Muhammed, alejhis-selam"],"question":"Koji je bio prvi Allahov poslanik na Zemlji?"},{"answer":"25","options":["5","25","100","124 hiljade"],"question":"Koliko je poslanika imenom spomenuto u Kur'anu?"},{"answer":"Ulul-'azm","options":["Enbija","Ulul-'azm","Mursalun","Rusul"],"question":"Kako se nazivaju pet najodabranijih Allahovih poslanika?"},{"answer":"Emanet","options":["Sidk","Emanet","Teblig","Ismet"],"question":"Koje svojstvo znači da su poslanici bili pouzdani i pošteni?"},{"answer":"Nema više poslanika niti objava","options":["Bilo je više poslanika","Stiglo je manje objava","Nema više poslanika niti objava","Ljudi su prestali vjerovati"],"question":"Šta se desilo nakon što je Muhammed, alejhis-selam, bio poslan?"}]},{"nivo":3,"slug":"mudzize","naslov":"Mudžize Allahovih poslanika","content_html":"<div class=\"lesson-container\">\n        <h1>MUDŽIZE ALLAHOVIH POSLANIKA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mudzize.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Mudžize Allahovih poslanika</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje vjerovanja u Allahovu moć kroz mudžize</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta je mudžiza i nabrojati primjere mudžiza poznatih poslanika</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da prepoznaju mudžize kao Allahove znakove</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako su poslanici dokazali svojim narodima da su od Allaha? Allah im je dao mudžize. Šta su to?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mudžiza je nadnaravno djelo koje Allah daje poslanicima kao dokaz njihove istinitosti — niko drugi to ne može učiniti.</p><p>Primjeri: <strong>Ibrāhīm, a.s.</strong> — vatra mu je postala hladna i sigurna; <strong>Mūsa, a.s.</strong> — štap se pretvarao u zmiju, more se rastvorilo; <strong>Īsa, a.s.</strong> — liječio bolesne, oživljavao mrtve uz Allahovu dozvolu, govorio u kolijevci.</p><p>Najveća mudžiza je <strong>Kur’an</strong> — vječna mudžiza Muhammeda, a.s. — knjiga koju niko ne može imitirati.</p><p>Druge mudžize Poslanika, a.s.: cijepanje mjeseca, voda iz prstiju, putovanje na Mi‘radž.</p><p>Mudžiza je Allahovo djelo, a poslanik je samo posrednik.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju mudžize. Zaključak: najveća mudžiza je Kur’an — vječni dokaz pred svijetom.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                DOKAZI NADPRIRODNE MOĆI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Kroz historiju, ljudi su često tragali za opipljivim dokazima kako bi povjerovali u poruke koje su im donosili poslanici. Da bi razbio sumnju i pokazao Svoju neizmjernu moć, Allah, dž.š., je Svojim odabranicima podario posebne darove koji prkose zakonima prirode. Zamislite trenutak kada se more razdvaja pred vašim očima, ili kada vatra, umjesto da prži, postaje hladna i spasonosna. Ti trenuci nisu bili magija ili trik, već jasni znaci od Stvoritelja.</p>\n                    <p>Ove natprirodne pojave nazivamo mudžizama. One su bile prilagođene vremenu i narodu kojem su poslanici dolazili – ljekarima su pokazivale veće znanje od medicine, a govornicima rječitost kojoj niko ne može parirati. Danas učimo o tim čudesnim događajima koji su kroz vijekove učvršćivali vjeru i ostavljali ljude bez daha, podsjećajući nas da je uz Allahovu pomoć sve moguće.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Mudžiza je natprirodna pojava, Božije djelo koje su imali Allahovi poslanici radi dokazivanja poslanstva.</span> Allah, dž.š., je poslanicima davao mudžize iz područja u kojima su njihovi narodi bili najvještiji i najupućeniji. Kada je Musa, alejhis-selam, boravio u Egiptu, bilo je rasprostranjeno čarobnjaštvo. Međutim, kada se Musaov štap, Allahovom voljom, pretvorio u zmiju koja je progutala zmije (konopce) čarobnjaka vidjeli su da je to pravo čudo - mudžiza, a ne kao njihovi konopci - obmana i čarolija. Povjerovali su u Allaha, dž.š., i priznali Musaa, alejhis-selam, i njegova brata Haruna, alejhis-selam, za Božije poslanike.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Još neke Musaove, alejhis-selam, mudžize bile su:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>razdvajanje mora,</li>\n                    <li>bijela ruka kad je izvadi ispod pazuha.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    U vrijeme Isaa, alejhis-selam, medicina je dostigla značajan stepen razvoja, pa je Allah, dž.š., njemu podario mudžize iz tog područja. Izliječio je osobu koja je slijepa od rođenja i gubavca, te je oživio mrtvaca. Još neke mudžize Isaa, alejhis-selam, su: progovorio je iz bešike, puhnuo u glinenu pticu i oživio je. Muhammedovi, alejhis-selam, savremenici dostigli su najviši stepen u rječitosti, govorništvu i pjesništvu, ali su i oni ostali nijemi i nemoćni kada su čuli Kur'an, jer on je najveća mudžiza Muhammeda, alejhis-selam Neki su činili uzaludne pokušaje da načine nešto slično Kur'anu, ali su na kraju morali priznati da Kur'an nije ljudsko djelo, nego Allahov govor.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Uzvišeni Allah kaže: A ako sumnjate u ono što objavljujemo robu Svome, načinite vi jednu suru sličnu objavljenim njemu, a pozovite i božanstva vaša, osim Allaha, ako istinu govorite. Pa ako ne učinite, a nećete učiniti, onda se čuvajte vatre za nevjernike pripremljene, čije će gorivo biti ljudi i kamenje. (El-Bekare, 23-24)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Kur'anski stil, izraz, sadržaj, značenje i melodičnost oduševili su one koji su ga prihvatili, ali i one koji su ga odbijali. Pred ovim kur'anskim izazovom ostat će nemoćne sve generacije ljudi do Sudnjeg dana.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Pored najveće mudžize, Kur'ana, Muhammedu, alejhis-selam, su date i sljedeće:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>Isra i Miradž (noćno putovanje i uzdignuće),</li>\n                    <li>panj koji je plakao zbog tog što s njega više nije držao hutbe,</li>\n                    <li>Mjesec koji se raspolutio na dvije polovine,</li>\n                    <li>voda koja je tekla između njegovih prstiju kako bi napojila vojsku.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    U Kur'anu se govori o mudžizama još nekih poslanika:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>Nuh, alejhis-selam - napravio lađu na kopnu prije potopa koji je zadesio nevjernike.</li>\n                    <li>Salih, alejhis-selam - kamila koja je izašla iz stijene, jer je to njegov narod tražio kao dokaz poslanstva.</li>\n                    <li>Ibrahim, alejhis-selam - bačen u veliku vatru koja je postala hladna i spasonosna za njega; četiri ptice koje je isjekao, pomiješao, raznio na četiri brežuljka, a kada ih je pozvao, one su oživjele i doletjele.</li>\n                    <li>Ismail, alejhis-selam - vrelo Zemzem.</li>\n                    <li>Junus, alejhis-selam - progutala ga velika riba, sačuvala ga i donijela do obale mora.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Mudžize se dijele u dvije grupe:\n                </p>\n                <ol class=\"lesson-text\">\n                    <li>hissijje - mudžize koje se opažaju osjetilima (čulne) i</li>\n                    <li>aklijje - mudžize koje se shvataju razumom (intelektualne).</li>\n                </ol>\n\n                <p class=\"lesson-text\">\n                    Mudžize Allahovih poslanika prije Muhammeda, alejhis-selam, bile su osjetilnog karaktera, te su ih mogli vidjeti i u njihovu istinitost se uvjeriti samo oni kojima su te mudžize pokazane, dok Muhammedove, alejhis-selam, mudžize pripadaju i jednoj i drugoj vrsti. Razumske mudžize imaju trajan karakter i njih mogu spoznati i buduće generacije sve do Sudnjeg dana.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_BOX', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_BOX\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 17</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">PITANJA I ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je mudžiza?</li>\n                    <li>Iz kojih oblasti su dolazile mudžize Allahovim poslanicima i navedite nekoliko primjera?</li>\n                    <li>Kako se dijele mudžize?</li>\n                    <li>Koja je najveća mudžiza Muhammeda, alejhis-selam?</li>\n                    <li>ZADATAK: Pokušaj pronaći do čega su to danas naučnici došli istražujući Mjesec, a što ima veze s ovom mudžizom Muhammeda, alejhis-selam, o raspolovljenju Mjeseca.</li>\n                </ol>\n\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        • Mjesec koji se raspolutio na dvije polovine posmatran kroz Kur'an i hadis.<br>\n                        • Allah, dž.š., je Salihovom, alejhis-selam, narodu poslao mudžizu, kamilu koja je iz stijene izašla.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":16,"is_published":true,"kviz_pitanja":[{"answer":"Natprirodna pojava koju su imali Allahovi poslanici","options":["Natprirodna pojava koju su imali Allahovi poslanici","Magija koju su učili čarobnjaci","Obična čuda koja se dešavaju svakodnevno","Priča koju su izmislili narodi"],"question":"Što je mudžiza?"},{"answer":"Štap koji se pretvorio u zmiju","options":["Štap koji se pretvorio u zmiju","Bijele ruke koje su sjajale","Moć da govori novim jezicima","Mogućnost da leti kroz zrak"],"question":"Kakvu mudžizu je Allah dao Musi, alejhis-selam, u Egiptu?"},{"answer":"Kur'an","options":["Kur'an","Isra i Miradž","Panj koji je plakao","Različita medicina"],"question":"Koja je najveća mudžiza Muhammeda, alejhis-selam?"},{"answer":"Izliječio je slijepe i gubavce, oživio je mrtvace","options":["Izliječio je slijepe i gubavce, oživio je mrtvace","Preobrazio je vodu u kruh","Podijeljio je imovinu bogatašima","Napravijo je nove knjige"],"question":"Što je Isa, alejhis-selam, radio kao svoju mudžizu?"},{"answer":"Jer su ta područja bila pozanta narodu i njihovoj vještini","options":["Jer su ta područja bila pozanta narodu i njihovoj vještini","Jer su ta područja bila bogatija od drugih","Jer su ta područja bila najbliža Meki","Jer su narodi u njima manje vjerovali u Allaha"],"question":"Zašto je Allah davao mudžize iz specifičnih područja?"}]},{"nivo":3,"slug":"isra-miradz","naslov":"Kur'an, Isra i Miradž","content_html":"<div class=\"lesson-container\">\n        <h1>KUR'AN, ISRA I MIRADŽ</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/miradz.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kur’an, Isra i Mi‘radž</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Poslaniku, a.s., i divljenja Allahovoj moći</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je Isra i Mi‘radž i šta se na njima desilo</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o važnosti namaza koji je propisan na Mi‘radžu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li ste čuli za noć kada je Poslanik, a.s., putovao iz Mekke u Jerusalem i potom na nebo? To je Isra i Mi‘radž.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Isra</strong> — noćno putovanje Poslanika, a.s., iz Mekke (Mesdžidul-Haram) do Jerusalema (Mesdžidul-Aksa) jašući na Buraku, u pratnji Džibrila.</p><p><strong>Mi‘radž</strong> — uzdizanje sa Mesdžidul-Aksaa kroz sedam nebesa do najuzvišenijeg mjesta gdje je razgovarao sa Allahom.</p><p>Na Mi‘radžu je Poslanik, a.s., susreo prijašnje poslanike (Adema, Īsau, Mūsau, Ibrāhīma...).</p><p>Najveća poruka Mi‘radža: propisivanje 5 dnevnih namaza — direktno od Allaha.</p><p>Sve se desilo u istoj noći — Poslanik se ujutro vratio u Mekku. Dokaz Allahove neograničene moći.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju Isra i Mi‘radž. Zaključak: namaz je dar Mi‘radža — čuvajmo ga.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":17,"is_published":true,"kviz_pitanja":[{"answer":"27. redžeba","options":["27. redžeba","15. ramadana","1. muharama","12. rebija"],"question":"Kojeg mjeseca se dogodio Isra i Miradž?"},{"answer":"Iz Mesdžidul-harama u Mekki","options":["Iz Mesdžidul-harama u Mekki","Iz Mesdžidul-aksaa","Iz Medine","Iz Taaifa"],"question":"Gdje je počelo putovanje Isra?"},{"answer":"Sedam nebesa","options":["Sedam nebesa","Pet nebesa","Devet nebesa","Tri neba"],"question":"Koliko nebeskih sfera je prošao Muhammed, alejhis-selam?"},{"answer":"Godina tuge - Senetul-huzn","options":["Godina tuge - Senetul-huzn","Godina migracije","Godina osvajanja","Godina blagoslova"],"question":"Kako se zvala godina u kojoj se dogodio Isra i Miradž?"},{"answer":"Allahov dar i nagrada","options":["Allahov dar i nagrada","Test vjere","Putovanje sa savjetnicima","Obaveza do Allaha"],"question":"Što je Isra i Miradž za Muhammeda, alejhis-selam?"}]},{"nivo":3,"slug":"sudnji-dan","naslov":"Vel-jevmil-āhiri – vjerovanje u Sudnji dan","content_html":"<div class=\"lesson-container\">\n        <h1>VEL-JEVMIL-ĀHIRI – VJEROWANJE U SUDNJI DAN</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sudnji_dan.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Vel-jevmil-āhiri – vjerovanje u Sudnji dan</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje takvaluka kroz svijest o ahiretu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti peti imanski šart i šta se dešava na Sudnjem danu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Motiviranje učenika na dobra djela</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta će biti kad ovaj svijet prestane postojati? Allah je obavijestio o Sudnjem danu. Šta se tada dešava?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sudnji dan (jevmu-l-āhir) — dan kad će ovaj svijet prestati i kada će svi ljudi biti proživljeni i obračunani.</p><p>Početak: Israfil puhne u sūr — sve umre. Drugi puh — svi ustaju iz kabura.</p><p>Ljudi se okupljaju na ravan, sunce se približi, znoj prelije — teško grešnicima, lahko vjernicima.</p><p>Nastupa hisab (obračun) — svako dobija svoju knjigu, vaga (mizan) važe djela.</p><p>Prelazi se preko Sirat-ćuprije — vjernici prelaze, grešnici padaju u Džehennem.</p><p>Konačno: Džennet za vjernike, Džehennem za nevjernike — vječno.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako se pripremiti za Sudnji dan. Zaključak: dunjaluk je sjetva, ahiret žetva.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":18,"is_published":true,"kviz_pitanja":[{"answer":"Dva puta","options":["Jednom","Dva puta","Tri puta","Četiri puta"],"question":"Koliko puta će se puhnuti u sur prije Sudnjeg dana?"},{"answer":"Sva stvorenja umiru","options":["Sva stvorenja umiru","Počinje proživljenje","Ljudi se prikupljaju","Počinje Sudnji dan"],"question":"Šta se dešava tokom prvog puhanja u sur?"},{"answer":"Vel-jevmil-āhiri","options":["El-jevmil-āhiri","Vel-jevmil-āhiri","Vel-jevmis-sālihi","El-jevmis-dunjā"],"question":"Kako se zove peti imanski šart?"},{"answer":"Vaga","options":["Knjiga","Vaga","Knjige","Mjerilo"],"question":"Šta se koristi za vaganje čovjekovih dobra i loša djela?"},{"answer":"Samo Allah, dž.š.","options":["Samo Muhammed a.s.","Samo Allah, dž.š.","Svi верни","Anđeli"],"question":"Ko zna kada će točno nastupiti Sudnji dan?"}]},{"nivo":3,"slug":"prozivljenje","naslov":"Proživljenje poslije smrti","content_html":"<div class=\"lesson-container\">\n        <h1>PROŽIVLJENJE POSLIJE SMRTI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/prozivljenje.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Proživljenje poslije smrti (Ba‘s)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje uvjerenja u proživljenje i odgovornost</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta je proživljenje i kako će se desiti</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje motivacije za pripremu za ahiret</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta će biti sa nama nakon smrti? Hoćemo li ostati u kaburu zauvijek? Ne! Bit ćemo proživljeni. Šta to znači?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Proživljenje (ba‘s) — Allah će nakon Sudnjeg dana ponovo stvoriti naša tijela i vratiti im duše.</p><p>Proživljenje je tjelesno — sa istim tijelom (samo u savršenom obliku).</p><p>Allah u Kur’anu kaže: \"Onaj ko vas je prvi put stvorio, On će vas i oživjeti.\"</p><p>Dokazi Allahove moći: život u proljeće poslije zime, snovi i buđenje, regeneracija tijela.</p><p>Nevjernici ne vjeruju u proživljenje — Allah ih u Kur’anu poziva da razmisle o stvaranju.</p><p>Razgovor: kako svijest o proživljenju mijenja naš život?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako bi se ponašali da svaki dan misle o proživljenju. Zaključak: vjernik živi za vječni život.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NOVO BUĐENJE U BESKRAJU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite jedan dugačak i miran san nakon kojeg se budite u svijetu koji nikada ne prestaje. Baš kao što se priroda svakog proljeća iznova rađa, tako i naš život ima svoj nastavak nakon ovog dunjalučkog putovanja. Smrt nije kraj, već samo jedna kapija kroz koju prolazimo kako bismo stigli do svog pravog i vječnog doma.</p>\n                    <p>Mnogi se pitaju šta se dešava kada se oči zatvore posljednji put. Allah, dž.š., nam u Svojoj Knjizi otkriva tajnu o berzahu – posebnom mjestu gdje se duša odmara i čeka veliki trenutak proživljenja. To je poput čekanja na najljepše jutro. Danas ćemo naučiti kako će nas naš Stvoritelj, koji nas je stvorio prvi put, ponovo oživjeti kako bi svaka pravednost bila ispunjena i svako dobro djelo nagrađeno vječnom srećom.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Berzah i život u kaburu</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    Smrt je rastanak duše od tijela. Tijelo se zakopava u zemlju i ponovo postaje zemlja od koje je i stvoreno, a duša prelazi u berzah i nastavlja drugu fazu života. Berzah je boravište ljudskih duša od smrti do proživljenja.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Svakom čovjeku će u kaburu Munkir i Nekir postaviti sljedeća pitanja: \"Ko ti je Gospodar? Ko ti je Poslanik? Koje si vjere?\", a kako će čovjek odgovoriti na ova pitanja ovisit će o tome da li je na ovom svijetu bio vjernik ili nevjernik. Vjerničke duše imat će ugodno boravište, a nevjerničke će osjetiti patnju u kaburu.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Nakon Bitke na Bedru, Muhammed, alejhis-selam, prišao je tijelima poginulih mušrika idolopoklonicima, pa ih je dozvao: \"Našli ste ono što vam je vaš Stvoritelj obećao!\" Omer, r.a., mu je prišao i rekao: \"Zar dozivaš mrtve ljude?\" Na to je Allahov Poslanik, alejhis-selam, odgovorio: \"Vi ništa ne čujete bolje od njih, samo oni ne odgovaraju.\" (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Muhammed, alejhis-selam, je u dovi molio: \"Gospodaru moj, zaštiti me od patnje u vatri i patnje u kaburu.\" (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Postoje mnogi hadisi u kojima su spomenuti grijesi zbog kojih će onaj ko ih je činio imati kaznu u kaburu, a neki od njih su: prenošenje tuđih riječi, ogovaranje, klanjanje namaza bez potpune čistoće, ostavljanje namaza i nemaran odnos prema njemu, laž, neizvršavanje obaveze zekata, blud, krađa, izdaja, širenje smutnje među muslimanima, uzimanje kamate, odbijanje pomoći obespravljenom, konzumiranje alkohola, bespravno ubistvo i drugo.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Proživljenje</span>\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I Nama navodi primjer, a zaboravlja kako je stvoren, i govori: \"Ko će oživjeti kosti kad budu truhle?\" Reci: \"Oživjet će ih Onaj koji ih je prvi put stvorio; On dobro zna sve što je stvorio.\" (Ja-Sin, 78-79)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., će narediti meleku Israfilu da drugi put puhne u sur, pa će ljudi biti proživljeni iz svojih kaburova. Allah, dž.š., kaže: I kada se duše s tijelima spare. (Et-Tekvir, 7)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Vjerovanje u proživljenje poslije smrti je temeljna istina islama. Onaj koji nas je stvorio prvi put u stanju je da to učini i drugi put. Na više mjesta u Kur'anu Allah, dž.š., je objasnio da je vjerovanje u proživljenje razumski prihvatljivo, jer ono ima svoje primjere u životu na ovom svijetu i na njega ukazuju mnoge prirodne pojave, koje su isto tako djelo Uzvišenog Allaha.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Svi ljudi, od Adema, alejhis-selam, pa do Smaka svijeta, ustat će iz kaburova i krenuti na mjesto okupljanja, koje se zove Mahšer, a ono je bijelo, ravno, bez izbočina, nepregledno tako da se nema gdje sakriti. Niko nikog neće gledati. Ljudi će se pojedinačno o sebi zabaviti. Ahiretsko sunce će se približiti, pa će se čovjek prema svojoj neposlušnosti utapati u znoju, neko do članaka, neko do koljena, a neko će do grla propasti. Koliko god bude težak za one koji su poricali i griješili, toliko će biti miran i spokojan za vjernike.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Dan kada će se desiti okupljanje zove se Mahšerski dan. Allah, dž.š., kaže:\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        A kada dođe glas zaglušujući - na Dan kada će čovjek od brata svoga pobjeći i od majke svoje i od oca svoga i od druge svoje i od sinova svojih - toga Dana će se svaki čovjek samo o sebi brinuti, neka lica bit će toga Dana blistava, nasmijana, radosna, a na nekim licima toga Dana bit će prašina, tama će ih prekrivati, to će nevjernici-razvratnici biti. (Abese, 33-42)\n                    </p>\n                </div>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">ZAPAMTI!</span><br>\n                        Nauka je došla do otkrića i zaključka da postoji jedan dio ljudskog tijela koji nikada ne truhne. Taj dio tijela se nalazi na kraju kičme i zove se trtična kost.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 20</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta za muslimana znači smrt?</li>\n                    <li>Šta je berzah?</li>\n                    <li>Od čega zavisi čovjekov odgovor na pitanja meleka u kaburu?</li>\n                    <li>Gdje će se dogoditi okupljanje poslije proživljenja i opiši taj dan?</li>\n                    <li>Kako se zove dan u kojem će se dogoditi okupljanje?</li>\n                </ol>\n\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        Odlazak s ovog prolaznog svijeta - dunjaluka na drugi vječni svijet - ahiret.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":19,"is_published":true,"kviz_pitanja":[{"answer":"Boravište ljudskih duša od smrti do proživljenja","options":["Boravište ljudskih duša od smrti do proživljenja","Mjesto gdje se zakopavaju tijela","Vrata raja i džehenema","Knjiga u kojoj se zapisuju grijesi"],"question":"Šta je berzah?"},{"answer":"Ko ti je Gospodar, ko ti je Poslanik, koje si vjere","options":["Koliko namaza si klanjao i ko ti je porodica","Ko ti je Gospodar, ko ti je Poslanik, koje si vjere","Šta si jeo i gdje si radio","Gdje je tvoja kuća i koliko imaš djece"],"question":"Koja pitanja postavljaju Munkir i Nekir u kaburu?"},{"answer":"Allah, dž.š.","options":["Muhammed, alejhis-selam","Munkir i Nekir","Allah, dž.š.","Anđeli raja"],"question":"Ko će narediti meleku Israfilu da puha u sur?"},{"answer":"Prenošenje tuđih riječi i ogovaranje","options":["Blagost prema siromašnima","Prenošenje tuđih riječi i ogovaranje","Redovno klanjanje namaza","Давање милостиње"],"question":"Koji od navedenih greške donose kaznu u kaburu?"},{"answer":"Ponovo postaje zemlja od koje je stvoreno","options":["Ostaje zauvijek nepromijenljivo","Ponovo postaje zemlja od koje je stvoreno","Prelazi u berzah s dušom","Ide u raj ili džehenem"],"question":"Šta se dešava sa tijelom nakon što duša napusti tijelo?"}]},{"nivo":3,"slug":"sefaat-mizan-sirat","naslov":"Šefaat, Mizan i Sirat-ćuprija","content_html":"<div class=\"lesson-container\">\n        <h1>Šefa'at, Mizan i Sirat-ćuprija</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sirat.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Šefaat, Mizan i Sirat-ćuprija</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje nade u Allahovu milost i ljubavi prema Poslaniku, a.s.</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta su šefaat, mizan i sirat</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike spominjanja Poslanika, a.s., kroz salavat</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta će se desiti ljudima na Sudnjem danu? Imaju li nadu? Da — kroz šefaat, mizan i sirat.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Šefaat</strong> — zauzimanje za druge na Sudnjem danu. Najveći šefaat ima Muhammed, a.s. — \"Šefā‘at u‘zma\" — pomognut će vjernicima.</p><p>Šefaat čine i meleki, poslanici, alimi, šehidi, iskreni vjernici — uz Allahovu dozvolu.</p><p>Salavat na Poslanika približava nas njegovom šefaatu.</p><p><strong>Mizan</strong> — vaga djela. Allah će vagati naša djela — dobra na jednoj strani, loša na drugoj.</p><p>Najteže djelo na vagi je: lijep ahlak, šehadet izgovoren iskreno, sjećanje na Allaha.</p><p><strong>Sirat-ćuprija</strong> — most preko Džehennema. Vjernici prelaze brzinom svjetla, grešnici padaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče salavat. Zaključak: dobra djela danas — laka prelaz preko sirata.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NA PUTU KA VJEČNOJ SREĆI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite jedan poseban dan u kojem se svaki vaš trud, svaki osmijeh i svako dobro djelo pažljivo mjere na najpreciznijoj vazi koju možete zamisliti. To je dan u kojem ništa neće biti zaboravljeno, a pravda će biti savršena. Ali, u tom velikom trenutku, nećemo biti ostavljeni sami. Baš kao što nam u školi nekada treba podrška ili savjet, tako će na tom putu postojati oni koji će se zauzeti za nas i vreli izvori koji će nas osvježiti.</p>\n                    <p>Danas ćemo naučiti o Mizanu – savršenoj vazi koja mjeri našu dobrotu, o Šefa'atu – posebnom daru zauzimanja za nas, te o Sirat-ćupriji – mostu koji vodi do našeg konačnog cilja. Ovo nije priča o strahu, već o nadi i Allahovoj neizmjernoj milosti koja nas prati. Saznat ćemo kako mala djela, poput riječi zahvale, mogu postati teška i vrijedna na tom putovanju ka vječnom miru.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Mjerenje toga dana bit će pravedno: oni čija dobra djela prevagnu oni će šta žele postići, a oni čija dobra djela budu lahka, oni će, zato što dokaze Naše nisu priznavali, stradati. (El-A'raf, 8-9)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Sakupljanjem svih ljudi koji su živjeli na dunjaluku od postanka čovječanstva označit će se početak Sudnjeg dana - dana predstavljanja ljudskih djela i Allahovog suđenja o njima. Svaki čovjek je zadužen da čini dobro, ali koliko god dobra činio ne može zaslužiti Džennet, nego će vjernici nakon presude Allahovom milošću ući u Džennet.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Šefa'at</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    Šefa'at je pravo poslanika, šehida, evlija i drugih odabranih robova da se zauzimaju na Sudnjem danu za druge ljude. Kur'an će imati pravo da se zauzima za one ljude koji su Ga učili i po njemu postupali. Zauzimanje za one ljude koji to budu zaslužili bit će u smislu oprosta grijeha od Allaha, dž.š., posredstvom kategorija koje imaju pravo šefa'ata. Šefa'at će biti omogućen samo onima kojima Allah, dž.š., to dozvoli. Poslanici će se zauzimati za svoje sljedbenike, tako da će se Muhammed, alejhis-selam, zauzimati za one u svome ummetu koji ga budu slijedili u njegovom sunnetu. Šehidi i ostali odabrani robovi će se zauzimati za članove svojih porodica.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Mizan</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    Mizan je savršena vaga na Sudnjem danu na koju će se postaviti ljudska djela kako bi bila izvagana. Mizan će na Sudnjem danu biti vaga koja ima dva tasa, na jedan će se postaviti dobra djela, a na drugi loša. Vaganjem čovjekovih dobrih i loših djela na Sudnjem danu bit će uspostavljena apsolutna pravda koja se nalazi jedino kod Allaha, dž.š., i toga dana nikome nepravda neće biti učinjena. Neka djela koja čovjek čini imaju posebnu težinu na Mizanu, pa je Poslanik, alejhis-selam, savjetovao da se čine: \"Čistoća je pola imana, a riječi El-Hamdulillahi - hvala Allahu, pune Mizan.\" (Muslim)\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Havd</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    Havd je vrelo Allahovog poslanika Muhameda, alejhis-selam, koje će dotjecati iz rijeke Kevser, pri polaganju računa na Sudnjem danu. Na taj dan s tog vrela bit će počašćeni poslanik Muhammed, alejhis-selam, i vjernici iz njegovog ummeta. Muhammed, alejhis-selam, kaže: \"Moje vrelo je veličine koliko mjesec dana putovanja. Njegova voda je bjelja od mlijeka, a miris ugodniji od miska, posude na njemu su poput zvijezda na nebu. Ko se s njega napije nikada više neće ožednjeti.\" (Buhari)\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Sirat-ćuprija</span>\n                </p>\n\n                <p class=\"lesson-text\">\n                    Sirat-ćuprija je most preko Džehennema koji će preći oni koji su nagrađeni Džennetom, a bit će prepreka za one koji su kažnjeni Džehennemom. Allah, dž.š., kaže: I svaki od vas će do njega stići! Gospodar tvoj se, sigurno, tako obavezao! Zatim ćemo one koji su se grijeha klonili spasiti, a nevjernike ćemo, da u njemu na koljenima kleče, ostaviti. (Merjem, 71-72)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Sirat-ćuprija je oštrija od sablje, tanja od dlake, i klizava tako da će samo oni koje Allah učini stabilnim ostati uspravni. Neki vjernici će je preći brzinom treptaja oka, neki kao munja, neki brzinom vjetra, neki kao ptice, neki kao trčeći konji, neki žurno, a posljednji će prelaziti puzajući.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">ZAPAMTI!</span><br>\n                        Poslije prelaska Sirat-ćuprije, a nakon što vjernici među sobom poravnaju račune, bit će im dozvoljen ulazak u Džennet.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 21</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"font-weight: bold;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je šefaat?</li>\n                    <li>Ko će imati pravo šefaata?</li>\n                    <li>Šta je Mizan-vaga i kako je opisana?</li>\n                    <li>Šta je Sirat-ćuprija i kako je opisana?</li>\n                    <li>Ko će preći preko Sirat-ćuprije, a ko će pasti s nje?</li>\n                    <li>Kako se zove vrelo Muhammeda, alejhis-selam, na Sudnjem danu?</li>\n                </ol>\n\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">IZABERI ZADATAK!</span><br>\n                        1. Razmisli i odgovori na sljedeće pitanje: da li čovjek svojim djelima može zaslužiti Džennet i zbog njih ući u njega?<br>\n                        2. Napiši nekoliko rečenica o temi: \"Pravda je spora, ali dostižna.\"\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":20,"is_published":true,"kviz_pitanja":[{"answer":"Pravo poslanika i drugih odabranih robova da se zauzimaju za ljude","options":["Pravo poslanika i drugih odabranih robova da se zauzimaju za ljude","Vaga za mjerenje dobrih i loših djela","Vrelo vode iz rijeke Kevser","Posebna nagrada za samce"],"question":"Šta je šefa'at na Sudnjem danu?"},{"answer":"Mizan","options":["Kevser","Sirat","Mizan","Havd"],"question":"Kako se zove vaga na Sudnjem danu?"},{"answer":"Dva tasa","options":["Jedan tas","Dva tasa","Tri tasa","Četiri tasa"],"question":"Koliko tasova ima Mizan?"},{"answer":"Šehidi i ostali odabrani robovi","options":["Samo poslanici","Šehidi i ostali odabrani robovi","Samo bogati ljudi","Svi vjernici bez razlike"],"question":"Ko će se zauzimati za članove svojih porodica na Sudnjem danu?"},{"answer":"Vrelo Allahovog poslanika Muhameda","options":["Posebna knjiga sa spiskom grijeha","Vrelo Allahovog poslanika Muhameda","Vrata u Džennet","Braneći anđeo Sudnjeg dana"],"question":"Šta je Havd prema lekciji?"}]},{"nivo":3,"slug":"dzennet-dzehennem","naslov":"Džennet i Džehennem","content_html":"<div class=\"lesson-container\">\n        <h1>DŽENNET I DŽEHENNEM</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dzennet_dzehennem.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Džennet i Džehennem</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje čežnje za Džennetom i straha od Džehennema</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam Dženneta i Džehennema, njihove vrste i stanovnike</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Motiviranje učenika na dobra djela koja vode u Džennet</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koje je krajnje odredište svakog čovjeka? Džennet ili Džehennem. Šta o njima znamo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Džennet</strong> — vječno boravište vjernika. Vrtovi, rijeke, hurije, susret sa Allahom — sve što duša poželi i više.</p><p>Imena Dženneta: El-Firdews (najviši stepen), Adn, Na‘im, Me’vā, Hulud, Selām, Dārul-mukāme.</p><p><strong>Džehennem</strong> — vječna kazna za nevjernike i veliki grešnici (privremeno).</p><p>Imena Džehennema: Džehīm, Sa‘īr, Sekar, Lezā, Hutame, Hāwije.</p><p>Ko ulazi u Džennet: vjernici, oni koji čine dobra djela.</p><p>Ko ulazi u Džehennem: nevjernici (zauvijek), grešnici (dok se ne očiste).</p><p>Razgovor: koja djela vode u Džennet? Koja u Džehennem?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju koja djela treba činiti za Džennet. Učimo dovu: \"Allahumme innī es’elukel-džennete ve e‘ūzu bike minen-nār.\"</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                VJEČNI DOM NAŠIH DUŠA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Svijet u kojem živimo je poput velike učionice u kojoj svakodnevno učimo i radimo. Svaki naš postupak, bio on mali ili veliki, ostavlja trag, a život na dunjaluku je prilika da prikupimo što više dobrih djela za ono što dolazi poslije. Zamislite da se spremate za najvažniji ispit nakon kojeg slijedi vječni raspust na najljepšem mjestu koje možete zamisliti. Taj vječni život na budućem svijetu nazivamo ahiret.</p>\n                    <p>Upoznati Džennet i Džehennem znači razumjeti cilj našeg putovanja. Allah nam u Svojoj milosti opisuje Džennet kao mjesto savršene radosti, mira i ljepote, dok nas istovremeno upozorava na Džehennem kako bismo znali od kojih postupaka se trebamo čuvati. Danas ćemo naučiti o tim boravištima i o tome kako naši postupci oblikuju našu vječnu budućnost, trudeći se da uvijek biramo put koji nas vodi ka Allahovom zadovoljstvu i džennetskim baščama.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    Ahiret je vječni život koji će uslijediti nakon čovjekovog preseljenja sa dunjaluka. Dunjaluk možemo shvatiti kao putovanje prema ahiretu u kome ćemo shodno svojim djelima zaslužiti nagradu ili kaznu. Džennet je vječno boravište na ahiretu pripremljeno za vjernike. Džehennem je boravište na ahiretu pripremljeno za nevjernike, nasilnike i zločince (teške grešnike).\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Džennet</span>\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: A oni koji su vjerovali i dobra djela činili, bit će uvedeni, voljom Gospodara njihova, u džennetske bašče kroz koje će rijeke teći i u njima će vječno boraviti, u njima će se riječju 'Mir' pozdravljati. (Ibrahim, 23)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Oni koji uspješno pređu Sirat-ćupriju stići će do svoga vječnog boravišta – Dženneta, gdje će uživati nagradu za djela koja su činili na dunjaluku.\n                </p>\n\n                <p class=\"lesson-text\">\n                    U Džennetu su rijeke i prostrane odaje, ugodan život bez poteškoća gdje će vjernici sve što požele dobiti. U njemu je ono što oči nisu vidjele, uši nisu čule, a i ono što nikome od Allahovih robova nije moglo naumpasti. U njemu će biti mirisi koji će se osjetiti na četrdeset godina hoda. Džennet ima stotinu deredža, a najviši nivo Dženneta je Firdevs koji se nalazi ispod Allahovog prijestolja – Arša. Osam je džennetskih vrata, a najveća počast za vjernike u Džennetu bit će gledanje u Allaha, dž.š.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Oni koji u Džennetu budu na najnižem stepenu, boravište će im biti poput dunjaluka i još deset puta toliko. Džennet je stvoren i već postoji, a Allah, dž.š., kaže: njih nagrada u Gospodara njihova čeka; edenski vrtovi kroz koje će rijeke teći, u kojima će vječno i zauvijek boraviti: Allah će biti njima zadovoljan, a i oni će biti Njime zadovoljni. To će biti za onoga koji se bude bojao Gospodara svoga. (El-Bejjine, 8)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Džennetske bašče su vječne i nikada neće presušiti niti uvehnuti. Njihovi stanovnici, vjernici, u njima će vječno boraviti.\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">Džehennem</span>\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I tako će se riječi Gospodara tvoga ispuniti da će oni koji nisu htjeli vjerovati – stanovnici u Vatri biti. (El-Mu'min, 6)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Džehennem je boravište na ahiretu pripremljeno za nevjernike u kojem će oni vječno boraviti, ali i za vjernike počinioce velikih grijeha ako im ne bude oprošteno, u kojem će oni jedno vrijeme boraviti.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Džehennem će strašno boravište biti, a napunit će ga ljudi i kamenje. Strašno će to boravište biti u kome će nevjernici iskusiti najteže kazne, a hrana i piće će im biti drvo zekum, te znoj i ključala voda. Najstrašnija džehennemska kazna je njegova vatra koja je 69 puta jača od ovodunjalučke.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Džehennem ima sedam vrata i džehennemske stepene koji su jedan ispod drugog po žestini kažnjavanja. Čuvari Džehennema će bit grubi i silni meleki. Vatri džehennemskoj neće dosaditi oni koji su u nju bačeni, štaviše, ona će govoriti: ima li još?\n                </p>\n\n                <p class=\"lesson-text\">\n                    Džehennem je kao i Džennet stvoren i postoji, a kažnjavanje pripremljeno za nevjernike je vječno i neće se prekinuti, te će oni u njemu vječno boraviti.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Vjernici koji su bili silnici i imali su grijeha u Džehennemu će biti kažnjavani ako im Allah ne oprosti, a nakon toga će Allahovom milošću ili šefaatom zagovornika biti uvedeni u Džennet.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Džehennemskoj kazni bit će izložen svako onaj ko bude činio grijehe, osim ako im se Allah Najmilostiviji ne smiluje i u Džennet ih uvede.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PROSIRIMO', this)\">\n                PROŠIRIMO ZNANJE UZ RAZGOVOR O HADISIMA! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PROSIRIMO\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Poslanik, alejhis-selam, je rekao: \"Tada će se postaviti Sirat-ćuprija iznad Džehennema. Ja i moj ummet ćemo biti prvi koji će je preći. Tada niko ništa neće govoriti, osim poslanika. Njihova dova toga dana će biti: 'Allahu, spasi, spasi!' U Džehennemu su željezne kuke kao veliko trnje drveta zvanog sa'dan. Njihovu veličinu ne zna niko osim Allaha. Povlačit će ljude u Džehennem prema njihovim djelima. Među njima će biti onih koji će propasti u Džehennem zbog svojih djela, a bit će i onih koje će kuke pocijepati, ali će se ipak spasiti.\" (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Poslanik, alejhis-selam, je rekao: \"Uvest će Allah koga hoće Svojom milošću od stanovnika Dženneta u Džennet i uvest će od stanovnika Džehennema u Džehennem, zatim će reći: 'Izvedite onoga u čijem srcu ima koliko trun imana.' Oni će tada izaći, a bit će već spaljeni do kostiju, pa će biti bačeni u rijeku života, a potom će iz nje iznići kao što iznikne sjemenka iz mulja bujice.\" (Buhari)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ 22</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je Džennet, a šta Džehennem?</li>\n                    <li>Kako je Džennet opisan u Kur'anu?</li>\n                    <li>Koliko Džennet ima deredža i koliko vrata?</li>\n                    <li>Šta će biti najveća počast za vjernike u Džennetu?</li>\n                    <li>Koliko puta je džehennemska vatra jača od ovodunjalučke?</li>\n                    <li>Da li će svi stanovnici Džehennema u njemu vječno ostati?</li>\n                </ol>\n\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":21,"is_published":true,"kviz_pitanja":[{"answer":"Vječno boravište na ahiretu za vjernike","options":["Vječno boravište na ahiretu za vjernike","Mjesto ispita na dunjaluku","Planina u Bosni i Hercegovini","Druga imena za dunjaluk"],"question":"Šta je Džennet?"},{"answer":"Za nevjernike, nasilnike i teške grešnike","options":["Za sve ljude bez razlike","Za nevjernike, nasilnike i teške grešnike","Za djecu koja nisu učila Kur'an","Za bolesne ljude"],"question":"Za koga je Džehennem pripremljen?"},{"answer":"Stotinu dredža","options":["Deset dredža","Pedeset dredža","Stotinu dredža","Hiljadu dredža"],"question":"Koliko dredža ima Džennet?"},{"answer":"Firdevs koji se nalazi ispod Arša","options":["Firdevs koji se nalazi ispod Arša","Bašča sa rijekama","Zlatna vrata Dženneta","Ograda od svile"],"question":"Koji je najviši nivo Dženneta?"},{"answer":"Gledanje u Allaha","options":["Bogatstvo i zlato","Gledanje u Allaha","Dobar hladak okom","Brojne živine"],"question":"Koja je najveća počast za vjernike u Džennetu?"}]},{"nivo":3,"slug":"kader","naslov":"Ve bil-kaderi hajrihī ve šerrihī minellāhi te'ālā – vjerovanje u Allahovo određenje","content_html":"<div class=\"lesson-container\">\n        <h1>VE BIL-KADERI HAJRIHĪ VE ŠERRIHĪ MINELLĀHI TE‘ĀLĀ</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/kader.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ve bil-kaderi – vjerovanje u Allahovo određenje (kader)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje strpljenja, povjerenja u Allaha i prihvatanja Njegovog određenja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam kadera u potpunosti — i šta je hajr (dobro) i šta je šerr (zlo)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje tevekkula i smirenosti u svim okolnostima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šesti imanski šart je vjerovanje u kader — Allahovo određenje, da je sve od Allaha. Kako to razumjeti?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kader — Allah zna sve unaprijed, sve je određeno Njegovom mudrošću.</p><p>Sve što se dešava (i hajr i šerr po našem mišljenju) — sa Allahovim znanjem i odredbom je.</p><p>Ali — Allah je čovjeku dao slobodu izbora i razum. Mi biramo svoja djela i odgovorni smo za njih.</p><p>Razlika: Allahovo znanje (Allah zna šta ćemo izabrati) ne natjeraje nas da to izaberemo.</p><p>Reakcije: u nesreći — sabr (\"Inna lillahi...\"), u radosti — šukr (\"Elhamdulillah\").</p><p>Vjerovanje u kader donosi smirenost — znamo da je sve u Allahovim rukama.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako se ponašati u nedaći. Zaključak: čovjek planira, Allah određuje — pravi vjernik je sa Allahom.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":22,"is_published":true,"kviz_pitanja":[{"answer":"Šesti imanski šart","options":["Treći imanski šart","Šesti imanski šart","Peti imanski šart","Četvrti imanski šart"],"question":"Koliko je imanski šart vjerovanje u Allahovo određenje?"},{"answer":"U Levhi-mahfuz","options":["U Kuranskom tekstu","U Levhi-mahfuz","U džamiji","U knjizi učitelja"],"question":"Gdje je Allah zapisao sudbinu svojih stvorenja?"},{"answer":"Zahvaliti Allahu","options":["Biti ponosan","Zahvaliti Allahu","Sakriti od drugih","Tražiti više"],"question":"Šta čovjek mora uraditi kada ga zadesi dobro?"},{"answer":"Allahovog Poslanika","options":["Umar","Allahovog Poslanika","Abubekra","Alija"],"question":"Ko je postavio Džibrilu pitanja o temeljima islamskog vjerovanja?"},{"answer":"Volja i moć","options":["Samo razum","Volja i moć","Samo emocije","Samo tijelo"],"question":"Šta je stvoreno u čovjeku da čini dobro ili loše?"}]},{"nivo":3,"slug":"el-humeze","naslov":"Učenje sure El-Humeze","content_html":"<div class=\"lesson-container\">\n        <h1>UČENJE SURE EL-HUMEZEH</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/humeze.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure El-Humeze</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Kur’anu i razumijevanja poruke sure El-Humeze</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst, prijevod i osnovnu poruku sure El-Humeze (104. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno uči i koristi suru El-Humeze u namazu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, danas učimo suru El-Humeze. Ima 9 ajeta i objavljena je u Mekkai. Šta nas Allah uči u njoj?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura El-Humeze je 104. sura Kur’ana, ima 9 ajeta.</p><p>Objavljena je u Mekkai.</p><p>Glavna poruka: Allah upozorava na one koji ogovaraju, ismijavaju i sakupljaju imetak — njihova kazna je teška vatra koja zahvaća srce.</p><p>Pišem suru na tabli (arapski + transkripcija + prijevod).</p><p>Učenici slušaju izgovor (sa snimka), zatim ponavljaju ajet po ajet u horu i pojedinačno.</p><p>Razgovor o značenju i poruci za naš svakodnevni život.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče cijelu suru zajedno. Zadaća: usavršiti učenje sure napamet i znati njen prijevod.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":23,"is_published":true,"kviz_pitanja":[{"answer":"U Mekki","options":["U Medini","U Mekki","U Jerusalemu","U Damasku"],"question":"Gdje je objavljena sura El-Humezeh?"},{"answer":"Devet ajeta","options":["Sedam ajeta","Devet ajeta","Deset ajeta","Jedanaest ajeta"],"question":"Koliko ajeta sadrži sura El-Humezeh?"},{"answer":"Klevetnika i podrugljivca","options":["Prosjake i siromašne","Klevetnika i podrugljivca","Školske učenike","Vojne vojnike"],"question":"Koga Allah upozorava u suri El-Humezeh?"},{"answer":"Vatra - Džehennem","options":["Vrata od zlata","Vatra - Džehennem","Mjesto mirovanja","Planinski vrh"],"question":"Šta će biti mjesto klevetnika na budućem svijetu?"},{"answer":"Klevetniku - podrugljivcu","options":["Blagajnik","Klevetniku - podrugljivcu","Učenjak","Trgovac"],"question":"Šta znači 'Humeza' na bosanskom jeziku?"}]},{"nivo":3,"slug":"kelimei-sehadet","naslov":"Kelimei-šehadet (detaljno)","content_html":"<div class=\"lesson-container\">\n        <h1>KELIMEI-ŠEHADET</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sehadet5.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kelimei-šehadet (detaljno)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje vjere u Allaha i Poslanika, a.s., kroz duboko razumijevanje šehadeta</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Detaljno razumjeti tekst, značenje i obaveze šehadeta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da svjedoči šehadet sa puninom razumijevanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šehadet smo naučili odavno. Danas ga razumijemo dublje — šta on tačno znači, šta od nas traži?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Tekst: <em>Ešhedu en lā ilāhe illallāh, ve ešhedu enne Muhammeden ‘abduhu ve resūluhu.</em></p><p>Šehadet ima dva dijela:</p><p><strong>1.</strong> Svjedočenje da nema boga osim Allaha — odbacivanje svih lažnih bogova i obožavanje samo Allaha.</p><p><strong>2.</strong> Svjedočenje da je Muhammed Allahov rob i poslanik — slijeđenje njegovog sunneta i pokornost.</p><p>Uslovi šehadeta: znanje o značenju, čvrsta uvjerenost, iskrenost, istinitost, ljubav, pokornost, prihvatanje.</p><p>Šehadet nije samo riječi — to je ugovor sa Allahom: živim za Tebe, slijedim Tvog Poslanika.</p><p>Posljednje riječi muslimana trebaju biti šehadet — to je ulaznica u Džennet.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici izgovaraju šehadet sa razumijevanjem. Zaključak: šehadet je naša najljepša izjava i najveća odgovornost.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":24,"is_published":true,"kviz_pitanja":[{"answer":"Dva dijela","options":["Tri dijela","Dva dijela","Četiri dijela","Jedan dio"],"question":"Koliko dijelova ima Kelimei-šehadet?"},{"answer":"Da nema drugog Boga osim Allaha","options":["Da je Muhammed poslanik Allaha","Da nema drugog Boga osim Allaha","Da trebamo moliti pet puta dnevno","Da trebamopost održavati"],"question":"Što znači prvi dio šehadeta?"},{"answer":"Allahov posljednji poslanik","options":["Allahov prijatelj","Allahov posljednji poslanik","Allahov anđeo","Allahov učenik"],"question":"Ko je Muhammed, alejhis-selam, prema drugom dijelu šehadeta?"},{"answer":"Obožavanje meleka, vjerovjesnika i drugih","options":["Molitve u džamiji","Obožavanje Allaha","Obožavanje meleka, vjerovjesnika i drugih","Čitanje Kur'ana"],"question":"Šta negira svjedočenje Božije jednoće?"},{"answer":"Pokoravati se njegovim naredbama","options":["Ignorirati njegova naređenja","Pokoravati se njegovim naredbama","Slijediti samo djelomično","Birirati koja naređenja slijediti"],"question":"Koja je naša obaveza prema Muhammadu, alejhis-selam?"}]},{"nivo":3,"slug":"pet-namaza","naslov":"Namaz – pet dnevnih namaza","content_html":"<div class=\"lesson-container\">\n        <h1>NAMAZ - PET DNEVNIH NAMAZA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/pet_namaza.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Pet dnevnih namaza – pregled</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema namazu kao stupu vjere</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti imena, vremena i broj rekata svih pet dnevnih namaza</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da samostalno klanjaju svih pet namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko namaza klanjamo svaki dan? Pet. Hajde da svih pet pregledamo zajedno.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Sabah</strong> — prije izlaska sunca. 2 sunneta + 2 farza = 4 rekata.</p><p><strong>Podne</strong> — kad sunce krene padati. 4 sunneta + 4 farza + 2 sunneta = 10 rekata.</p><p><strong>Ikindija</strong> — popodne. 4 sunneta + 4 farza = 8 rekata.</p><p><strong>Akšam</strong> — odmah poslije zalaska sunca. 3 farza + 2 sunneta = 5 rekata.</p><p><strong>Jacija</strong> — kad se smrkne. 4 sunneta + 4 farza + 2 sunneta + 3 vitra = 13 rekata.</p><p>Vremena su određena Allahovim određenjem — ne smiju se klanjati prije njihovog vremena.</p><p>Postupak: Tabela na tabli sa vremenima i rekatima. Učenici prepisuju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju strukturu svakog namaza. Zaključak: 5 dnevnih namaza — 5 stupova naše veze sa Allahom.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                RAZGOVOR KOJI SMI RUJE SRCE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da imate priliku svakoga dana, pet puta, razgovarati s Najboljim Prijateljem koji vas uvijek sluša, razumije i voli više od bilo koga drugog. Taj razgovor ne zahtijeva telefon niti internet, već samo vaše čisto srce i nekoliko trenutaka mira. Namaz je upravo taj čudesni most koji nas povezuje s našim Stvoriteljem, dajući nam snagu da kroz dan prolazimo s osmijehom i mirom u duši.</p>\n                    <p>Kada stanemo na sedždžadu, mi ostavljamo sve brige iza sebe i ulazimo u poseban svijet ljepote. To je naš \"mali miradž\" – putovanje duše ka svjetlosti. Danas ćemo naučiti zašto je namaz temelj naše vjere i kako nam on pomaže da postanemo bolji ljudi, čuvajući nas od loših postupaka i puneći naše dane neopisivim zadovoljstvom i radošću.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: ...molitva zaista odvraća od razvrata i svega što je ružno; obavljanje molitve je najveća poslušnost! A Allah zna šta radite. (El-Ankebut, 45)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Klanjanje namaza je drugi islamski šart i drugi stub islama.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Namaz je najuzvišeniji način iskazivanja pokornosti i zahvalnosti Uzvišenom Allahu, dž.š. To je savršeni čin ibadeta koji podrazumijeva specifične riječi i pokrete, počinje početnim tekbirom, a završava selamom. Namaz je osnova i temelj vjere i prvo za što će čovjek odgovarati na Sudnjem danu.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4;\">HADIS</span><br><br>\n                        Poslanik, alejhis-selam, je rekao: \"Prvo za što će čovjek biti pitan na Sudnjem danu je namaz, ako mu on bude ispravan, bit će ispravna i ostala djela, a ako mu namaz ne bude ispravan, neće mu biti ispravna ni ostala djela.\" (Taberani)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Namazu je ukazana posebna počast i vrijednost time što je propisan na najvišem nebu prilikom Poslanikovog, alejhis-selam, miradža. Namaz se obavlja isključivo radi Allaha, dž.š., s potpunom skrušenošću i prisutnošću, te posebno prisebnog i budnog stanja srca i duše.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ispravnost namaza, pored umnog prisustva u njemu, ogleda se i u pravilno obavljenim farzovima, vadžibima, te sunnetima koji ga upotpunjuju, uljepšavaju i čine ga vrednijim.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Pored duhovnog čišćenja za klanjača, namaz je najbolja zaštita u toku dunjalučkog života, od ružnih riječi i djela, pa i razvrata.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Onaj ko redovno obavlja pet dnevnih namaza nalazi se u stalnoj vezi s Allahom, dž.š., koja postaje neraskidiva ukoliko ustraje u toj svojoj obavezi. Takav musliman postaje svjestan sveprisutnosti Allaha, dž.š., u njegovom životu i njegova veza putem namaza s Uzvišenim Gospodarom ga čuva od grijeha i činjenja djela kojima Gospodar nije zadovoljan.\n                </p>\n\n                <p class=\"lesson-text\">\n                    U razgovoru s ljudima trudimo se da budemo uljudni, skoncentrirani, zahvalni sagovornici, dok u razgovoru s Allahom, dž.š., moramo biti potpuno umno prisutni i obazrivi, jer je namaz za vjernika razgovor s Allahom, dž.š., bez posrednika. Namaz je za vjernika rasterećenje i opuštanje jer je Poslanik, alejhis-selam, Bilalu govorio: \"O Bilale, pozovi na namaz, odmori nas, razrahati nas namazom.\" Iz toga znamo da je njegovo, alejhis-selam, rasterećenje, odmor i rahatluk bio upravo u namazu, kao što nas je obavijestio da je zadovoljstvo i radost njegova oka također u namazu.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4;\">ZAPAMTI!</span><br><br>\n                        U Allahovom hladu na Dan kad drugog hlada ne bude bit će i mladić/djevojka koji su odrasli u pokornosti Allahu.\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4;\">HADISI-KUDSI</span>\n                    </p>\n                    <p class=\"lesson-text\">\n                        Poslanik, alejhis-selam, prenosi da je Uzvišeni Allah rekao: \"Podijelio sam namaz između Mene i Moga roba na dva dijela, Mome robu pripada sve ono za šta Me zamoli.<br><br>\n                        Pa kada rob kaže: \"Hvala Allahu Gospodaru svih svjetova.\"<br>\n                        Allah kaže: \"Moj rob Mi zahvaljuje.\"<br>\n                        A kada kaže: \"Milostivom, Samilosnom.\"<br>\n                        Allah kaže: \"Moj rob Me pohvaljuje.\"<br>\n                        A kada kaže: \"Vladaru Dana sudnjega.\"<br>\n                        Allah kaže: \"Moj rob Me veliča.\"<br>\n                        A kada kaže: \"Samo Tebe obožavamo i samo od Tebe pomoć tražimo.\"<br>\n                        Allah kaže: \"Ovo je između Mene i Moga roba, a Mome robu pripada sve ono za šta Me moli.\"<br>\n                        A kada kaže: \"Uputi nas na pravi put, na put onih kojima si milost Svoju darovao, a ne na put onih koji su protiv sebe srdžbu izazvali, niti onih koji su zalutali!\"<br>\n                        Allah kaže: \"Ovo je Mome robu, a Mome robu pripada sve ono za šta Me moli.\"\" (Muslim)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - PET DNEVNIH NAMAZA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"font-weight: bold;\">PITANJA</p>\n                    <ol class=\"lesson-text\">\n                        <li>Šta je namaz?</li>\n                        <li>U čemu se ogleda ispravnost namaza?</li>\n                        <li>Pored zadovoljstva Allaha, dž.š., koje još koristi namaz donosi čovjeku?</li>\n                    </ol>\n                </div>\n\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4;\">RAZGOVOR S MUALLIMOM</span><br><br>\n                        • Namaz je miradž vjernika.<br>\n                        • Prvo za šta će čovjek biti pitan na Sudnjem danu je namaz.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":25,"is_published":true,"kviz_pitanja":[{"answer":"Pet namaza","options":["Tri namaza","Pet namaza","Sedam namaza","Dva namaza"],"question":"Koliko je namaza obaveza za muslimana svakog dana?"},{"answer":"Drugi stub islama","options":["Prvi stub islama","Drugi stub islama","Treći stub islama","Četvrti stub islama"],"question":"Koji je redoslijed islama po važnosti namaza?"},{"answer":"Namaz","options":["Ramazan","Namaz","Hadž","Zekat"],"question":"Šta će biti prvo što će čovjek ispitati na Sudnjem danu?"},{"answer":"Na najvišem nebu","options":["U Meki","Na Zemlji","Na najvišem nebu","U Medini"],"question":"Na kojem mjestu je propisan namaz prema hadisu?"},{"answer":"Razgovor s Allahom bez posrednika","options":["Samo obaveza","Razgovor s Allahom bez posrednika","Samo duhovnost","Samo习gewohnheit"],"question":"Šta je namaz za vjernika prema tekstu lekcije?"}]},{"nivo":3,"slug":"farzovi-namaz","naslov":"Farzovi u namazu","content_html":"<div class=\"lesson-container\">\n        <h1>FARZOVI U NAMAZU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/farzovi.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Farzovi u namazu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pažnje i tačnosti u namazu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta su farzovi u namazu — bez kojih namaz nije valjan</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno izvršava farzove namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta čini namaz valjanim? Postoje farzovi — bez njih namaz nije ispravan. Koji su to?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Farzovi u namazu su djela koja moramo obaviti — ako se izostave, namaz nije valjan.</p><p>Farzovi prije namaza (šartovi): čistoća tijela i odjeće, čistoća mjesta, pokrivenost, okretanje kibli, nastupanje vremena namaza, nijet.</p><p>Farzovi unutar namaza (rukni):</p><p><strong>1.</strong> Početni tekbir (Allāhu ekber)</p><p><strong>2.</strong> Stajanje (kijam)</p><p><strong>3.</strong> Učenje Kur’ana (kira’et)</p><p><strong>4.</strong> Rukū‘</p><p><strong>5.</strong> Sedžda (dvije sedžde)</p><p><strong>6.</strong> Posljednje sjedenje (ka‘da)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju farzove. Zaključak: ako izostavimo farz, ponavljamo namaz.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":26,"is_published":true,"kviz_pitanja":[{"answer":"Dijelovi namaza koji se moraju izvršiti kako bi namaz bio ispravan","options":["Dijelovi namaza koji se moraju izvršiti kako bi namaz bio ispravan","Dodatni dijelovi namaza koje nije obavezno raditi","Riječi koje izgovaramo prije namaza","Oblačenje koje nosimo tokom namaza"],"question":"Šta su farzovi u namazu?"},{"answer":"Iftitahi tekbir","options":["Kijam","Iftitahi tekbir","Ruku","Sedžda"],"question":"Kako se naziva početni tekbir u namazu?"},{"answer":"Čitati Kur'an","options":["Čitati Kur'an","Rukuu činiti duže","Sedždu činiti brže","Stajati tiho"],"question":"Što trebamo ispravno učiniti na svakom rekatu?"},{"answer":"Dvije sedžde","options":["Jednu sedždu","Tri sedžde","Dvije sedžde","Četiri sedžde"],"question":"Koliko sedždi trebamo učiniti u namazu?"},{"answer":"Obnovimo cijeli namaz","options":["Nastavljamo namaz dalje","Obnovimo cijeli namaz","Ne trebamo ništa učiniti","Dodajemo dodatni rekat"],"question":"Što činimo ako propustimo farz u namazu?"}]},{"nivo":3,"slug":"vadzibi-namaz","naslov":"Vadžibi u namazu","content_html":"<div class=\"lesson-container\">\n        <h1>VADŽIBI U NAMAZU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/vadzibi.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Vadžibi u namazu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje preciznosti i ozbiljnosti u namazu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta su vadžibi u namazu i šta se desi ako se izostave</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da prepozna i ispravno obavi vadžibe</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, pored farzova, postoje i vadžibi u namazu. Šta su to? Šta se desi ako ih izostavimo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Vadžib je propis koji je obavezan ali manjeg stepena od farza — ako ga namjerno izostavimo, namaz se ponavlja; ako nehotice, dovoljno je sehvi-sedžda.</p><p>Glavni vadžibi u namazu:</p><p><strong>1.</strong> Učenje Fātihe (na svakom rekatu) i sure poslije Fātihe (na prva dva rekata farza)</p><p><strong>2.</strong> Tertib — redoslijed (ne mijenjati raspored)</p><p><strong>3.</strong> Smirenost (tama’nina) u rukū‘u i sedždi</p><p><strong>4.</strong> Sjedenje poslije drugog rekata (ka‘da-i ūla)</p><p><strong>5.</strong> Učenje \"Tehijjat\" na sjedenju</p><p><strong>6.</strong> Predaja selama na kraju</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju vadžibe. Zaključak: čuvati vadžibe znači čuvati ljepotu namaza.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":27,"is_published":true,"kviz_pitanja":[{"answer":"Dijelovi namaza koje trebamo izvršiti","options":["Dijelovi namaza koje trebamo izvršiti","Dodatne molitve nakon namaza","Greške u namazu","Sunnetske radnje u namazu"],"question":"Šta su namaski vadžibi?"},{"answer":"Sehvi-sedždu nakon namaza","options":["Sehvi-sedždu nakon namaza","Ponoviti cijeli namaz odmah","Ništa, namaz je validan","Dodatna molitev"],"question":"Šta se mora učiniti ako zaboravimo namaski vadžib?"},{"answer":"Sabah, prva dva rekata akšama i jacije","options":["Sabah, prva dva rekata akšama i jacije","Samo na sabahu","Na svim namaza","Nikad naglas"],"question":"Na kojim namaza imam čita Fatihu i suru naglas?"},{"answer":"Više od tri je namaz nevalidan","options":["Više od tri je namaz nevalidan","Dva vadžiba su dovoljna","Jedan vadžib je dovoljan","Pet vadžiba je dozvoljeno"],"question":"Koliko minimalnih vadžiba smijemo izostaviti?"},{"answer":"Spustiti čelo i nos da osjetimo tlo","options":["Spustiti čelo i nos da osjetimo tlo","Samo čelo spustiti","Čitati tiho suru","Brzo ustati"],"question":"Šta trebamo učiniti na sedždi?"}]},{"nivo":3,"slug":"sunneti-namaz","naslov":"Sunneti u namazu","content_html":"<div class=\"lesson-container\">\n        <h1>SUNNETI U NAMAZU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sunneti.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Sunneti u namazu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema slijeđenju Poslanikovog, a.s., sunneta u svemu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta su sunneti u namazu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da obogati svoj namaz sunnetima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, pored farzova i vadžiba, postoje sunneti u namazu — Poslanikova, a.s., djela. Hajde da ih učimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sunnet je propis koji je Poslanik, a.s., redovno činio — ne kvari namaz ako se izostavi, ali se gubi nagrada.</p><p>Glavni sunneti unutar namaza:</p><p><strong>1.</strong> Učenje \"Subhāneke\" na početku</p><p><strong>2.</strong> \"E‘ūzu\" i \"Bismillāh\" prije Fātihe</p><p><strong>3.</strong> Učenje \"Subhāne rabbijel-‘azīm\" tri puta na rukū‘u</p><p><strong>4.</strong> Učenje \"Subhāne rabbijel-a‘la\" tri puta na sedždi</p><p><strong>5.</strong> Učenje salavata i dove poslije Tehijjata</p><p><strong>6.</strong> Podizanje ruku na tekbiru, držanje desne ruke na lijevoj na kijamu...</p><p>Sunneti uz namaz: 12 redovnih sunneta dnevno + nafile.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju 4-5 sunneta. Zaključak: sunneti su ljepota namaza.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":28,"is_published":true,"kviz_pitanja":[{"answer":"Nisu dužni ponavljati taj namaz","options":["Ponavljati taj namaz ponovno","Nisu dužni ponavljati taj namaz","Dati milostinju","Obaviti dodatni namaz"],"question":"Što trebaju učiniti vjernici ako ne izvršavaju namaske sunnete?"},{"answer":"Do visine ušiju","options":["Do visine ramena","Do visine ušiju","Do visine glave","Do visine prsa"],"question":"Do koje visine muškarci trebaju podići ruke kod početnog tekbira?"},{"answer":"Sjede na lijevoj nozi sa uspravljivanjem desne","options":["Sjede na obje noge jednako","Sjede na desnoj nozi sa podignutom lijevom","Sjede na lijevoj nozi sa uspravljivanjem desne","Stoje cijelo vrijeme"],"question":"Kako se muškarci trebaju sjediti na intervalu između dvije sedžde?"},{"answer":"Prvo koljena, zatim dlanovi i lice","options":["Prvo lice, zatim dlanove i koljena","Prvo koljena, zatim dlanovi i lice","Prvo šake, zatim noge","Prvo čelo na tlo"],"question":"Kojim redoslijedom se spuštamo na sedždu?"},{"answer":"Predati selam prvo na desnu, pa na lijevu stranu","options":["Prečitati dovu","Predati selam prvo na desnu, pa na lijevu stranu","Učiniti tasbeeh","Ponoviti Fatihu"],"question":"Što trebamo prvo učiniti kada završimo namaz?"}]},{"nivo":3,"slug":"mekruhi-namaz","naslov":"Mekruhi u namazu","content_html":"<div class=\"lesson-container\">\n        <h1>MEKRUHI U NAMAZU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mekruhi.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Mekruhi u namazu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ozbiljnosti i poštovanja u namazu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta su mekruhi — pokuđena djela u namazu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da izbjegava mekruhe i čuva ljepotu namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, postoje stvari koje ne kvare namaz, ali umanjuju njegovu vrijednost. Zovemo ih mekruhi. Koji su to?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mekruh je nešto što je pokuđeno (nepoželjno) — ne kvari namaz, ali smanjuje njegovu nagradu i ljepotu.</p><p>Glavni mekruhi:</p><p><strong>1.</strong> Igranje sa odjećom, kosom, prstima</p><p><strong>2.</strong> Gledanje desno-lijevo (oči trebaju biti na sedždi)</p><p><strong>3.</strong> Klanjanje gladnog ili kad nas tera nužda</p><p><strong>4.</strong> Nepokrivanje usta pri zijevanju</p><p><strong>5.</strong> Učenje različitog reda sūra (npr. kratku pa dužu)</p><p><strong>6.</strong> Grickanje noktiju, češkanje bez potrebe</p><p><strong>7.</strong> Klanjanje ispred slika ili ka grobu</p><p>Cilj namaza: huše‘ — skrušenost srca pred Allahom.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju mekruhe. Zaključak: namaz je razgovor sa Allahom — neka bude pažljiv i lijep.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":29,"is_published":true,"kviz_pitanja":[{"answer":"Dela koja je muslimanu pokuđeno činiti","options":["Dela koja je muslimanu pokuđeno činiti","Обavezne radnje u namazu","Načini kako se klanja sunce","Dijelovi Kur'ana koji se moraju čitati"],"question":"Šta su mekruhi u namazu?"},{"answer":"Okretanje i namještanje odjeće tokom namaza","options":["Okretanje i namještanje odjeće tokom namaza","Čitanje Kur'ana tiho","Stajanje mirno u namazu","Klanjanje s čistom odjećom"],"question":"Koji je primjer mekruh rada u namazu?"},{"answer":"Štap visine oko 80 cm koji se stavlja ispred klanjača","options":["Štap visine oko 80 cm koji se stavlja ispred klanjača","Posebna tkanina za pokrivanje glave","Molitev koju čitamo u namazu","Nešto što se stavlja u džamiji na pod"],"question":"Šta je perda (es-sutra) u namazu?"},{"answer":"Drugi rekat učiniti dužim od prvog","options":["Drugi rekat učiniti dužim od prvog","Čitati El-Fatihu na početku","Biti čist i umiven prije namaza","Skidati cipele prije namaza"],"question":"Koji red je mekruh u namazu?"},{"answer":"Prema otvorenom plamenu ili na prohodnom putu","options":["Prema otvorenom plamenu ili na prohodnom putu","U džamiji s drugim vjernicima","U čistoj odjeći na meketu","Pod stablom tokom dana"],"question":"Gdje je mekruh klanjati se prema namjeri?"}]},{"nivo":3,"slug":"el-asr","naslov":"Učenje sure El-'Asr","content_html":"<div class=\"lesson-container\">\n        <h1>UČENJE SURE EL-'ASR</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/asr.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure El-‘Asr</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Kur’anu i razumijevanja poruke sure El-‘Asr</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst, prijevod i osnovnu poruku sure El-‘Asr (103. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno uči i koristi suru El-‘Asr u namazu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, danas učimo suru El-‘Asr. Ima 3 ajeta i objavljena je u Mekkai. Šta nas Allah uči u njoj?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura El-‘Asr je 103. sura Kur’ana, ima 3 ajeta.</p><p>Objavljena je u Mekkai.</p><p>Glavna poruka: Allah se kune vremenom da je čovjek u gubitku — osim onih koji vjeruju, čine dobro, podstiču istinu i strpljivost.</p><p>Pišem suru na tabli (arapski + transkripcija + prijevod).</p><p>Učenici slušaju izgovor (sa snimka), zatim ponavljaju ajet po ajet u horu i pojedinačno.</p><p>Razgovor o značenju i poruci za naš svakodnevni život.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče cijelu suru zajedno. Zadaća: usavršiti učenje sure napamet i znati njen prijevod.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":30,"is_published":true,"kviz_pitanja":[{"answer":"U Mekki","options":["U Mekki","U Medini","U Jerusalemu","U Egiptu"],"question":"Gdje je objavljena sura El-'Asr?"},{"answer":"Tri ajeta","options":["Dva ajeta","Tri ajeta","Pet ajeta","Jedan ajet"],"question":"Koliko ajeta sadrži sura El-'Asr?"},{"answer":"Vrijeme","options":["Mjesec i zvezde","Vrijeme","Planine","Rijeke"],"question":"Šta Alah, dž.š., zaklinju na početku sure?"},{"answer":"Vjernici koji čine dobra djela","options":["Svi ljudi bez izuzetka","Samo bogati ljudи","Vjernici koji čine dobra djela","Samo učenjaci"],"question":"Ko će uspjeti na ovom i budućem svijetu prema suri?"},{"answer":"Istinu i strpljenje","options":["Samo novac i bogatstvo","Istinu i strpljenje","Samo ljepotu","Samo zabavu"],"question":"Šta preporučuju jedni drugima vjernici prema suri?"}]},{"nivo":3,"slug":"vaznost-dzemata","naslov":"Smisao i važnost džemata i namaza u džematu","content_html":"<div class=\"lesson-container\">\n        <h1>SMISAO I VAŽNOST DŽEMATA I NAMAZA U DŽEMATU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dzemat.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Smisao i važnost džemata i namaza u džematu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema zajedničkom namazu i osjećaja zajedništva</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti vrijednost namaza u džematu i kako se on klanja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike redovnog odlaska u džemat</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, zašto je važan džemat? Zašto je namaz u džematu vredniji od namaza u samoći?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Džemat — zajednica muslimana koja zajedno klanja iza imama.</p><p>Vrijednost: 27 puta veća nagrada od namaza u samoći.</p><p>Pravila džemata: dolazak ranije, čistoća, lijepa odjeća, pravo stajanje u saffu (rame uz rame), slijeđenje imama (ne pretjecati ga).</p><p>Imam je vodič — bira se prema znanju Kur’ana i ahlaku.</p><p>Džemat je škola jedinstva: svi smo jednaki pred Allahom — bogati i siromah, mlad i star.</p><p>Posebne nagrade: čekanje džemata u džamiji = klanjanje, odlazak na noge u džamiju = jedna nagrada za svaki korak.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju koliko često idu u džemat. Zaključak: idemo u džemat barem jednom dnevno.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                SNAGA ZAJEDNIŠTVA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite jedan snažan lanac. Svaka karika tog lanca, iako mala, doprinosi njegovoj ukupnoj čvrstini. Ako se jedna karika izdvoji, ona gubi snagu koju ima dok je dio cjeline. Naš život u vjeri je upravo takav lanac, a džemat je zajednica koja nas drži povezanim, snažnim i sigurnim. Kada smo zajedno, nijedna prepreka nije nepremostiva.</p>\n                    <p>Danas učimo o džematu – mjestu gdje se muslimani i muslimanke susreću, vole, pomažu i zajedno klanjaju. Saznat ćemo zašto je namaz u džematu toliko vredniji i kako nas stajanje u safovima uči da smo pred našim Gospodarom svi jednaki, bez obzira na to ko smo i odakle dolazimo. Džemat nije samo skup ljudi, to je naša duhovna porodica i naš sigurni smiraj.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Vjernici i vjernice su prijatelji jedni drugima: traže da se čine dobra djela, a od nevaljalih odvraćaju, i molitvu obavljaju i zekat daju, i Allahu i Poslaniku Njegovu se pokoravaju. To su oni kojima će se Allah, sigurno, smilovati. - Allah je doista silan i mudar. (Et-Tevbe, 71)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Džemat je muslimanska zajednica u kojoj se muslimani i muslimanke međusobno poštuju, vole, pomažu i savjetuju. Riječ džemat je nastala od arapske riječi koja znači skupiti, sabrati, sjediniti i slično. Od iste riječi je nastala i riječ džamija kojom se naziva Allahova kuća u kojoj se muslimani okupljaju s ciljem ibadeta Allahu, dž.š.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ističući vrijednost zajednice, Poslanik, alejhis-selam, je po dolasku u Medinu uspostavio Medinsku zajednicu i Medinski džemat u džamiji koju je sagradio. Njen smisao bio je razvijanje ljubavi prema Allahu i prema Njegovom poslaniku, a zatim razvijanje bratske ljubavi između muhadžira i ensarija, pa je džamija bila mjesto njihovog zajedničkog rada i potpomaganja.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: \"Ko bude želio srednji dio Dženneta neka se drži džemata jer šejtan je sa pojedincem, a od dvojice se drži podalje...\" (Tirmizi)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Džemat i džamija u životu jednog muslimana i muslimanke imaju veoma važnu ulogu. To su mjesta koja označavaju njihov duševni smiraj i harmoniju, mjesta s kojih počinju hairli poslovi i putovanja, mjesta gdje će rješavati probleme i iskušenja koja ne mogu sami prebroditi, mjesta savjetovanja i bratske ljubavi. O suštini odnosa među muslimanima i muslimankama u džematu kazuju nam i sljedeći kur'anski ajeti: Vjernici su uistinu braća...(El-Hudžurat, 10)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Zajednica muslimana je snažna i jedinstvena cjelina koja može prebroditi i riješiti bilo kakav problem, dok je pojedinac izložen raznim napadima i nedaćama. Muslimansko jedinstvo u džematu i međusobna jednakost su najočitiji prilikom zajedničkog klanjanja namaza u džematu.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        Poslanikova, alejhis-selam, redovna praksa je bila da obavlja namaz u džematu: \"Namaz u džematu vredniji je od namaza klanjanog pojedinačno za dvadeset i sedam puta.\" (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"info-box\" style=\"margin-top: 10px;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Otkad postoji islam, postoji i džemat. Svaka karika u lancu daje čvrstinu i snagu džematu.\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"margin-top: 20px;\">\n                    Smisao namaza u džematu ogleda se u sljedećem:<br>\n                    • džemat nas uči da je čovjek društveno biće i da su njegov dolazak na dunjaluk, život i odlazak na ahiret vezani za zajednicu,<br>\n                    • džemat i stajanje u safovima pokazuju snagu zajednice i razvijaju osjećaj za jedinstvom koji jednu zajednicu čini čvrstom na Pravom putu,<br>\n                    • stajanje u safu nas podsjeća na jednakost pred Gospodarom Allahom, dž.š., bez obzira na boju kože, rasu, imovinsko stanje,<br>\n                    • namaz u džematu nas uči čistoći i higijeni, pedantnosti i tačnosti,<br>\n                    • kontakt s drugima prilikom namaza u džematu razvija međusobnu ljubav, saosjećanje i milost među muslimanima,<br>\n                    • vrijeme prije i poslije namaza prilika je za razgovor i pomoć u rješavanju problema onima koji ih imaju,<br>\n                    • safovi nas podsjećaju i na stajanje pred Allahom, dž.š., na Sudnjem danu,<br>\n                    • samo snažna zajednica džemat, koja brine o svakom svom članu i koja je jedinstvena, garantira nam lični i društveni uspjeh.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - DŽEMAT</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase; display: inline-block;\">Pitanja</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je džemat?</li>\n                    <li>Koji je bio Poslanikov, alejhis-selam, prvi postupak po dolasku u Medinu?</li>\n                    <li>Koja je bila svrha tog postupka?</li>\n                    <li>Gdje je najočitije jedinstvo džemata?</li>\n                    <li>Navedi hadis o vrijednosti namaza u džematu!</li>\n                    <li>U čemu je smisao namaza u džematu?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase; display: inline-block; margin-top: 20px;\">Izaberi zadatak!</p>\n                <ol class=\"lesson-text\">\n                    <li>Opiši kako ti vidiš odnose među muslimanima u tvom džematu! Šta bi ti promijenio i šta bi popravio?\n                    </li>\n                    <li>Koje si od navedenih koristi namaza u džematu prepoznao kod nekog od svojih bližih?</li>\n                </ol>\n\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">Razgovor s muallimom</span><br><br>\n                        • Koliko muslimana u tvom džematu redovno obavlja pet dnevnih namaza i redovno posjećuje džamiju?<br>\n                        • Svi se čvrsto Allahova užeta držite i nikako se ne razjedinjujte. (Alu Imran, 103)\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":31,"is_published":true,"kviz_pitanja":[{"answer":"Skupiti, sabrati, sjediniti","options":["Skupiti, sabrati, sjediniti","Moliti se svaki dan","Učiti djecu kuran","Davati sadaku siromašnima"],"question":"Što džemat znači prema arapskoj riječi od koje je nastala?"},{"answer":"U džamiji koju je sagradio","options":["U džamiji koju je sagradio","U svojoj kući u Medini","Na grobljima i blagajnama","U tvrđavi od Medine"],"question":"Gdje je Poslanik, alejhis-selam, uspostavio Medinsku zajednicu i džemat?"},{"answer":"Dvadeset i sedam puta","options":["Dvadeset i sedam puta","Deset puta","Pedeset puta","Tri puta"],"question":"Koliko puta je namaz u džematu vredniji od namaza samog?"},{"answer":"Sa pojedincem je, od dvojice se drži podalje","options":["Sa pojedincem je, od dvojice se drži podalje","Teže se bori sa dvojicom","Jednako napada sve","Ne postoji razlika"],"question":"Kako je šejtan prema jednom pojedincu, a prema dvojici?"},{"answer":"Mjesta duševnog smiraja i harmonije","options":["Mjesta duševnog smiraja i harmonije","Samo mjesta za učenje","Mjesta za igru i zabavu","Mjesta samo za muškarce"],"question":"Što su džamija i džemat za muslimana i muslimanku?"}]},{"nivo":3,"slug":"vrste-namaza","naslov":"Podjela namaza po stepenu važnosti","content_html":"<div class=\"lesson-container\">\n        <h1>PODJELA NAMAZA PO STEPENU VAŽNOSTI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/vrste_namaza.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Podjela namaza po stepenu važnosti</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pravilnog razumijevanja prioriteta u ibadetu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti podjelu namaza: farz, vadžib, sunnet, mustehab, nafila</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno postavlja prioritete u namazu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, nisu svi namazi iste važnosti. Postoji podjela. Koje vrste namaza znamo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Farz</strong> — najveća obaveza. Pet dnevnih namaza, džuma-namaz, dženaza-namaz.</p><p><strong>Vadžib</strong> — skoro kao farz. Vitr-namaz, Bajram-namaz.</p><p><strong>Sunnet mu’ekkede</strong> (potvrđeni sunnet) — Poslanik, a.s., redovno klanjao. Sunneti uz farzove (npr. 2 sunneta sabaha, 4 podneva).</p><p><strong>Sunnet gajri-mu’ekkede</strong> (nepotvrđeni sunnet) — preporučen, ali ne tako stalno (4 sunneta ikindije).</p><p><strong>Mustehab/nafila</strong> — dobrovoljni namaz (tehedždžud, duha, istihara, hādže).</p><p>Prioritet: prvo farz → vadžib → sunnet mu’ekkede → ostalo.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici klasificiraju razne namaze. Zaključak: znati prioritete znači ispravno klanjati.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                STAZAMA POKORNOSTI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da idete na važno putovanje. Postoje stvari koje su neophodne da biste uopće krenuli, poput pasoša ili karte, ali postoje i one koje će vaše putovanje učiniti ugodnijim i ljepšim. Naš namaz je upravo takvo putovanje ka Allahovom zadovoljstvu. On ima svoje stepene i nivoe, od onih koji su stroga obaveza za svakog od nas, do onih koje činimo iz čiste ljubavi i želje da budemo bliže našem Stvoritelju i slijedimo put našeg Poslanika, alejhis-selam</p>\n                    <p>Danas učimo o tome kako se namazi dijele prema svojoj važnosti. Saznat ćemo šta su to farzovi koji čine stub naše vjere, šta su vadžibi koje je Uzvišeni propisao, te šta su sunneti – dragocjeni primjeri iz života Muhammeda, alejhis-selam Razumijevanje ove podjele pomoći će nam da shvatimo težinu i ljepotu svakog namaza koji obavljamo, jačajući našu vezu s Allahom kroz redovnost i skrušenost u svakom reka'tu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: O vjernici, molitvu obavljajte i Gospodaru svome se klanjajte, i dobra djela činite da biste postigli ono što želite. (El-Hadždž, 77)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Namaz je najvažniji ibadet koji je propisan muslimanima, a vrijeme dok vjernik obavlja namaz je vrijeme razgovora s Allahom, dž.š. Namaz je jedan od stubova vjere i onaj ko zaniječe njegovu obaveznost prestaje biti musliman, dok onaj ko ne obavlja propisane namaze čini veliki grijeh.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., je propisao obavljanje pet dnevnih namaza i stavio ih kao strogu obavezu svim punoljetnim i umno zdravim muslimanima i muslimankama ukoliko nemaju neku šerijatski opravdanu situaciju. Pored obaveznih pet dnevnih namaza, propisani su još neki obavezni namazi te dobrovoljni - nafila-namazi koji su na stepenu sunneta - prakse Poslanika, alejhis-selam\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">Farz-namazi</p>\n                <ul class=\"lesson-text\">\n                    <li>pet dnevnih namaza - dnevno klanjamo 17 rekata farz-namaza, i to: 2 sabahska, 4 podnevska, 4 ikindijska, 3 akšamska i 4 jacijska,</li>\n                    <li>džuma-namaz - 2 rekata džuma-namaza,</li>\n                    <li>dženaza-namaz.</li>\n                </ul>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">Vadžib-namazi</p>\n                <p class=\"lesson-text\">\n                    Vadžib-namazi su namazi koje je Uzvišeni Allah propisao, ali nisu na stepenu farza. U vadžib-namaze ubrajamo:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>3 rekata vitr-namaza koji se klanjaju zajedno s jacija-namazom,</li>\n                    <li>2 rekata ramazanskog bajram-namaza,</li>\n                    <li>2 rekata kurbanskog bajram-namaza.</li>\n                </ul>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">Sunnet-namazi</p>\n                <p class=\"lesson-text\">\n                    Sunneti se dijele na:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>pritvrđene - sunneti-muekkede, koje je Poslanik, alejhis-selam, uvijek klanjao, a to su: 2 sabahska, 6 podnevskih, 2 akšamska i 2 jacijska,</li>\n                    <li>nepritvrđene – sunneti-gajri-muekkede, koje je Poslanik, alejhis-selam, povremeno izostavljao, a to su: 4 ikindijska i 4 jacijska sunneta, klanjanje tehijetul-mesdžida, te nafila-namazi koji se klanjaju kada vjernik ima neku potrebu poput hadže-namaza, istihara-namaza, namaza za kišu i slično.</li>\n                </ul>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span>\n                    </p>\n                    <p class=\"lesson-text\">\n                        Ummu Habiba, r.a., prenosi predaju: \"Čula sam Allahovog Poslanika, s.a.v.s., kada je rekao: 'Onaj ko u jednom danu i noći klanja dvanaest rekata sunnet-namaza, zbog tog djela će mu biti sagrađena kuća u Džennetu.'\" (Muslim)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - PODJELA NAMAZA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase; display: inline-block;\">Pitanja</p>\n                <ol class=\"lesson-text\">\n                    <li>Koji su uvjeti za obaveznost pet dnevnih namaza?</li>\n                    <li>Koji su farz, a koji vadžib-namazi?</li>\n                    <li>Kako se dijele namazi koji su na stepenu sunneta?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase; display: inline-block; margin-top: 20px;\">Popuni tabelu!</p>\n                <p class=\"lesson-text\">\n                    Vodeći računa o tome u koju skupinu spada koja namaska radnja (1. farz, 2. vadžib, 3. sunnet i 4. mekruh), razvrstaj sljedeće pojmove:\n                </p>\n                <p class=\"lesson-text\">\n                    Izgovoriti amin, Proučiti suru, Izgovarati tekbir, Posljednje sjedenje, Stajanje u namazu, Proučiti Subhaneke, Proučiti Fatihu, Prvo sjedenje, Sehvi-sedžda, Predati selam, Žmiriti, zijevati i gledati gore, Pregibanje u namazu.\n                </p>\n\n                <table class=\"sorting-table lesson-text\">\n                    <tr>\n                        <th>1. FARZ</th>\n                        <th>2. VADŽIB</th>\n                        <th>3. SUNNET</th>\n                        <th>4. MEKRUH</th>\n                    </tr>\n                    <tr>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                    </tr>\n                    <tr>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                    </tr>\n                    <tr>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                        <td>&nbsp;</td>\n                    </tr>\n                </table>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":32,"is_published":true,"kviz_pitanja":[{"answer":"Pet namaza dnevno","options":["Tri namaza dnevno","Pet namaza dnevno","Sedam namaza dnevno","Deset namaza dnevno"],"question":"Koliko obaveznih dnevnih namaza je Allah, dž.š., propisao muslimanima?"},{"answer":"17 rekata","options":["15 rekata","17 rekata","19 rekata","21 rekat"],"question":"Koliko rekata farz-namaza klanjamo dnevno u ukupnosti?"},{"answer":"Namazi koje je Allah propisao ali nisu na stepenu farza","options":["Namazi koje je Allah propisao ali nisu na stepenu farza","Namazi koje je Poslanik povremeno klanjao","Namazi koje musliman klanja samo u Ramazanu","Namazi koje čini veliki grijeh ako se ne obave"],"question":"Što su vadžib-namazi u islamu?"},{"answer":"Sunnet-muakkede je obavezna, sunnet-gajri-muakkede nije","options":["Sunnet-muakkede je obavezna, sunnet-gajri-muakkede nije","Sunnet-muakkeda je Poslanik uvijek klanjao, gajri-muakkede povremeno","Sunnet-muakkede se klanja samo u Ramazanu","Nema nikakve razlike između njih"],"question":"Koja je razlika između sunnet-muakkede i sunnet-gajri-muakkede?"},{"answer":"Tri rekata","options":["Jedan rekat","Dva rekata","Tri rekata","Četiri rekata"],"question":"Koliko rekata ima vitr-namaz koji se klanja sa jacija-namazom?"}]},{"nivo":3,"slug":"dzenaza-namaz","naslov":"Dženaza-namaz","content_html":"<div class=\"lesson-container\">\n        <h1>DŽENAZA-NAMAZ</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dzenaza.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dženaza-namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o smrti i međusobne odgovornosti muslimana</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je dženaza-namaz, kako se klanja i ko ga klanja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da prisustvuje dženazi i klanja je ispravno</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kad neko od muslimana umre, šta je naša obaveza? Kupanje, kefin, dženaza-namaz, ukop. Šta je dženaza-namaz?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Dženaza-namaz je farz kifaje — obaveza zajednice; ako ga obavi dovoljan broj muslimana, ostali su oslobođeni obaveze.</p><p>Klanja se za umrlim muslimanom, prije ukopa, u džamiji ili na groblju.</p><p>Struktura: 4 tekbira, bez rukū‘a i sedžde, stojeći.</p><p>Nakon prvog tekbira: učenje subhaneke; nakon drugog: salavat; nakon trećeg: dova za umrlog; nakon četvrtog: selam.</p><p>Pravila: imam stoji nasuprot prsa muškarca ili sredine žene.</p><p>Vrijednost: ko klanja dženazu — dobiva nagradu jednog kirata, ko prati i ukop — dva kirata (kirat = veličina Uhuda).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako se ponašati na dženazi. Zaključak: dženaza je amanet zajednice.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":33,"is_published":true,"kviz_pitanja":[{"answer":"Poseban namaz koji se klanja za umrle muslimane","options":["Poseban namaz koji se klanja za umrle muslimane","Namaz koji se klanja samo za muškarce","Namaz koji se klanja pet puta dnevno","Namaz koji se klanja na početku mjeseca"],"question":"Šta je dženaza-namaz?"},{"answer":"Hadis od Poslanika, alejhis-selam, kod melek Džibrila","options":["Hadis od Poslanika, alejhis-selam, kod melek Džibrila","Hadis o čistoći od Usmana, radijallahu anhu","Hadis o molitvi od Abubekra, radijallahu anhu","Hadis o postu od Alija, radijallahu anhu"],"question":"Koji hadis govori o tome kako trebamo živjeti?"},{"answer":"Četiri tekbira","options":["Četiri tekbira","Tri tekbira","Pet tekbira","Dva tekbira"],"question":"Koliko tekbira se izgovara u dženaza-namazu?"},{"answer":"Umrla osoba je musliman i okupana i okrenuta prema Kibli","options":["Umrla osoba je musliman i okupana i okrenuta prema Kibli","Umrla osoba je samo musliman","Umrla osoba je samo okupana","Umrla osoba je samo okrenuta prema Kibli"],"question":"Koji su uvjeti za ispravnost dženaza-namaza?"},{"answer":"Nije dozvoljeno tražiti smrt od Allaha","options":["Nije dozvoljeno tražiti smrt od Allaha","Dozvoljeno je tražiti smrt od Allaha","Dozvoljeno je samo starijim ljudima","Dozvoljeno je ako ste jako bolni"],"question":"Da li je dozvoljeno tražiti smrt od Allaha zbog tegobe?"}]},{"nivo":3,"slug":"post-propisi","naslov":"Post – propisi i fadileti ramazanskog posta","content_html":"<div class=\"lesson-container\">\n        <h1>POST - PROPISI I ODLIKE RAMAZANSKOG POSTA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/iftar.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Post – propisi i fadileti ramazanskog posta</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema postu i Ramazanu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti propise (farzove, vadžibe, sunnete) i fadilete (vrijednosti) posta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike za pravilno postenje</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je naš najmubarekniji mjesec? Ramazan! Šta o postu detaljno znamo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Farzovi posta: <strong>nijet</strong>, <strong>suzdržavanje</strong> od jela/pića/intimnih odnosa, <strong>vrijeme</strong> (od sabaha do akšama).</p><p>Vadžibi: paziti da se ne prekidi nehotice (oprez s jelom).</p><p>Sunneti: sehur (kasniti), iftar (požuriti), učenje dove pri iftaru, učenje Kur’ana, teravije, posjete džamiji.</p><p>Šta kvari post: jelo, piće, namjerno povraćanje, intimni odnosi.</p><p>Šta ne kvari post: zaboravljanje (jelo iz zaborava), kupanje, mirisanje, čišćenje zuba miswakom.</p><p>Fadileti: oprost grijeha, ulazak kroz vrata Rejjān u Džennet, jača empatija prema gladnima, samokontrola.</p><p>Ko može odgoditi post: bolesnik, putnik, trudnica, dojilja, žena u hajzu/nifasu — naklanja se kasnije.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o pripremi za Ramazan. Zaključak: Ramazan je dar — iskoristimo ga.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                MJESEC DUŠEVNOG PROCVATA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite jedan poseban dar koji nam dolazi svake godine, dar koji ne otvaramo rukama, već srcem. Taj dar je mjesec Ramazan. Dok se cijeli svijet žuri, postač pronalazi mir u tišini suzdržavanja. Post nije samo odricanje od hrane i pića; to je škola strpljenja, suosjećanja i duboke povezanosti s našim Stvoriteljem. To je vrijeme kada naša duša dobija krila, a naši loši postupci ostaju iza nas.</p>\n                    <p>Danas ćemo naučiti o ljepoti i propisima posta – trećeg islamskog šarta. Saznat ćemo ko je obavezan postiti, kako se donosi nijet i koje su to neizmjerne nagrade koje čekaju postače na oba svijeta. Otkrit ćemo zašto su sehuri i iftari najljepši trenuci u porodici i kako nam post pomaže da postanemo bolji, plemenitiji i bliži jedni drugima. Krenimo zajedno u istraživanje ovog blagoslovljenog puta bogobojaznosti.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: O vjernici! Propisuje vam se post kao što je propisan onima prije vas, da biste bili bogobojazni. (El-Bekare, 183)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Post je suzdržavanje od jela, pića, spolnog odnosa i drugih tjelesnih uživanja od zore do zalaska Sunca s namjerom približavanja Allahu, dž.š. Post u mjesecu ramazanu je propisao Allah, dž.š.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Početak posta u mjesecu ramazanu danas se utvrđuje savremenim proračunima, a tačna vremena sehura i iftara bilježe se u takvimu, odnosno vaktiji, koji priprema, uređuje i izdaje Rijaset Islamske zajednice u Bosni i Hercegovini.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">Obaveznost posta</p>\n                <p class=\"lesson-text\">\n                    Postiti je obavezan svaki punoljetan, umno i fizički zdrav musliman i muslimanka koji se nalaze kod kuće, u mogućnosti su i nemaju neku od šerijatskih zapreka za post.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Prema tome, nisu obavezni postiti maloljetna djeca (ali ih je lijepo navikavati na post), osoba koja nije pri zdravom razumu, žena u stanju hajza i nifasa.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Post ženama u stanju hajza i nifasa nije dozvoljen i, ukoliko bi postile, on neće biti primljen. Propuštene dane posta dužne su napostiti poslije ramazana.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">Farzovi posta</p>\n                <ol class=\"lesson-text\">\n                    <li>Nijet, tj. da postač namjerava svojim postom činiti ibadet Allahu, dž.š. (Nijet je potrebno donijeti na način da namjeravamo ispostiti cijeli ramazan te svaku večer iskazati namjeru posta narednog dana.)</li>\n                    <li>Sustezanje od jela, pića, spolnog odnosa i drugih tjelesnih uživanja od pojave zore do zalaska Sunca.</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">Privremeno odgađanje posta</p>\n                <p class=\"lesson-text\">\n                    Sljedećim osobama je dozvoljeno da odgode post u mjesecu ramazanu, uz obavezu da nadoknade propuštene dane:\n                </p>\n                <ol class=\"lesson-text\">\n                    <li>Bolesne i stare osobe kojima post predstavlja poteškoću. Ukoliko ne postoji nada za izlječenje ili poboljšanje stanja, bolesnik i stara osoba će koristiti alternativni propis, a to je fidja. Fidja znači za svaki dan posta nahraniti siromaha ručkom i večerom, u iznosu koji je u skladu s imovinskim stanjem osobe. Fidja se može dati u novčanom iznosu.</li>\n                    <li>Putnici koji imaju pravo da krate namaze imaju pravo i da odgode post, ali propuštene dane moraju napostiti.</li>\n                    <li>Trudnice i dojilje. One će svoj post nadoknaditi nakon trudnoće i dojenja.</li>\n                    <li>Radnici koji obavljaju teške fizičke poslove.</li>\n                    <li>Zatvorenici, ukoliko nemaju uvjeta za post.</li>\n                </ol>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        Posebna radost za djecu je oglašavanje kraja posta paljenjem kandilja, i njihovo trčanje kući kako bi obradovali i obavijestili roditelje.\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">Nadoknada i iskup za post</p>\n                <p class=\"lesson-text\">\n                    Kada je nadoknada opravdano izostavljenih dana posta. Ove dane osoba je dužna napostiti nakon Ramazanskog bajrama do idućeg ramazana. Osoba je dužna napostiti isti broj propuštenih dana posta.\n                </p>\n                <p class=\"lesson-text\">\n                    Kefaret je iskup za namjerno prekidanje posta u toku mjeseca ramazana. Osoba koja to učini dužna je postiti 60 dana uzastopno za jedan dan prekinutog posta i napostiti dotični dan. Ukoliko nije u mogućnosti postiti 60 dana, umjesto toga može nahraniti 60 siromaha.\n                </p>\n                <img src=\"/edu/assets/images/post1.jpg\" style=\"float: left; width: 250px; margin-right: 10px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">Odlike posta</p>\n                <p class=\"lesson-text\">\n                    Post je Allahu, dž.š., posebno drag ibadet, pa stoga i obećava veliku nagradu onome ko u Njegovo ime, s namjerom približavanja Njemu, posti. Neki od posebnih fadileta spremljeni su i omogućeni samo postaču:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>Upućivanje dove u vrijeme iftara i u toku posta, jer Poslanik, alejhis-selam, kaže: “Trojici dova neće biti odbijena: postaču prilikom iftara, pravednom vođi i onome kome je nepravda učinjena.” (Ebu Davud)</li>\n                    <li>Posebna vrijednost teravih-namaza i noćnog namaza. “Ko u ramazanu klanja noćni namaz, vjerujući u Allaha i očekujući Njegovu nagradu, bit će mu oprošteni raniji grijesi.” (Buhari)</li>\n                    <li>Nagrada za postače je posebna. Poslanik, alejhis-selam, je rekao: “Kaže Allah, dž.š.: ‘Sva čovjekova djela pripadaju njemu osim posta, post je Moj i Ja za njega posebno nagrađujem.’” (Buhari)</li>\n                </ul>\n                <p class=\"lesson-text\">\n                    Post će muslimanu donijeti dobro i korist na dunjaluku i na ahiretu, a neke od vrijednosti posta su:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>post je štit od grijeha i džehennemske vatre,</li>\n                    <li>na džennetska vrata Rejjan moći će ući samo postači,</li>\n                    <li>najveća postačeva radost bit će susret s Allahom, dž.š.,</li>\n                    <li>nagrada za post kod Gospodara je neprocjenjiva,</li>\n                    <li>post briše ljudske grijehe,</li>\n                    <li>post će biti čovjekov zagovornik na Sudnjem danu.</li>\n                </ul>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">Dobrovoljni post</p>\n                <p class=\"lesson-text\">\n                    Pored obaveznog, ramazanskog posta, postoji i dobrovoljni post na koji je Poslanik, alejhis-selam, podsticao svoj ummet. Dani u kojima je lijepo postiti dobrovoljni post su:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>ponedjeljkom i četvrtkom,</li>\n                    <li>tri srednja dana u mjesecu po hidžretskom kalendaru,</li>\n                    <li>dan Ašure (10. muharrem),</li>\n                    <li>dan Arefata (9. zul-hidže),</li>\n                    <li>šest dana mjeseca ševvala,</li>\n                    <li>post u mjesecu muharremu,</li>\n                </ul>\n                <p class=\"lesson-text\">\n                    Zabranjeno je postiti na dan Ramazanskog bajrama i dane Kurbanskog bajrama.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - POST</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase; display: inline-block;\">Pitanja za razgovor</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je post i ko su obveznici posta?</li>\n                    <li>Kojim kategorijama je dozvoljeno privremeno odložiti post?</li>\n                    <li>Koje su najveće koristi i nagrade za postače?</li>\n                    <li>Kada je zabranjeno, a kada lijepo dobrovoljno postiti?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase; display: inline-block; margin-top: 20px;\">Izaberi zadatak!</p>\n                <ol class=\"lesson-text\">\n                    <li>Istraži i objasni razliku između fidje i kefareta na primjerima iz svakodnevnog života.</li>\n                    <li>Pronađi na YouTube kanalu kompoziciju \"Šukren Rahmanu\", uvježbaj je i uči sa društvom iz mekteba.</li>\n                </ol>\n            </div>\n        </div>","audio_src":null,"redoslijed":34,"is_published":true,"kviz_pitanja":[{"answer":"Suzdržavanje od jela, pića i spolnog odnosa od zore do zalaska Sunca","options":["Suzdržavanje od jela, pića i spolnog odnosa od zore do zalaska Sunca","Samo suzdržavanje od jela tijekom cijelog dana","Molitev koju верници obavezno čine pet puta dnevno","Čitanje Kur'ana tijekom mjeseca ramazana"],"question":"Što je post prema tekstu lekcije?"},{"answer":"Maloljetna djeca, ali je lijepo ih navikavati na post","options":["Samo djeca starija od deset godina","Maloljetna djeca, ali je lijepo ih navikavati na post","Sva djeca koja imaju više od osam godina","Djeca koja su završila osnovnu školu"],"question":"Koja djeca nisu obavezna da postiti?"},{"answer":"Dva farza posta","options":["Tri farza posta","Pet farzova posta","Dva farza posta","Četiri farza posta"],"question":"Koliko farzova posta postoji prema lekciji?"},{"answer":"Bolesnim i starim osobama kojima post predstavlja poteškoću","options":["Samo studentima koji se pripremaju za ispite","Bolesnim i starim osobama kojima post predstavlja poteškoću","Svima koji žele da odgode post bez razloga","Samo muškarcima koji obavljaju teške poslove"],"question":"Kome je dozvoljeno da odgodi post u ramazanu?"},{"answer":"Namjera da se post čini kao ibadet Allahu","options":["Nabavka hrane za iftar sa prijateljima","Namjera da se post čini kao ibadet Allahu","Vrijeme kada završavamo jelo prije zore","Molitva koju čitamo nakon zalaska Sunca"],"question":"Što znači nijet kod posta?"}]},{"nivo":3,"slug":"zekat-bejtul-mal","naslov":"Zekat – Bejtul-mal","content_html":"<div class=\"lesson-container\">\n        <h1>ZEKAT - BEJTUL-MAL</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/bejtul_mal.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Zekat – Bejtul-mal</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje plemenitosti i odgovornosti za potrebne u zajednici</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je zekat detaljno i šta je Bejtul-mal</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti ulogu zekata u islamskom društvu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je obavezan davati zekat? Kome? Šta je Bejtul-mal? Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Zekat — 2,5% od imovine koja stoji godinu dana iznad nisaba (cca 85g zlata ili ekvivalent).</p><p>Vrste zekata: zekat na novac, zekat na trgovačku robu, zekat na stoku, zekat na poljoprivredne plodove (ušr).</p><p>Korisnici zekata (8 kategorija u Kur’anu): siromasi, ubogi, sakupljači zekata, oni čija srca treba osvojiti, zarobljenici, dužnici, na Allahovom putu, putnici u nuždi.</p><p><strong>Bejtul-mal</strong> — riznica islamske države/zajednice, gdje se sakuplja zekat i druga sredstva i raspoređuje pravedno.</p><p>Bejtul-mal su ustanovili ashabi — služi za pomoć siromašnima, izgradnju, plate učitelja, vojsku.</p><p>U BiH danas: Vakufska direkcija i Islamska zajednica imaju ulogu u upravljanju vakufima i zekatom.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o važnosti zekata u zajednici. Zaključak: zekat je most između bogatih i siromašnih.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NAŠ IMETAK KAO PLODOVI VRTA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Da bi vrt svake godine rađao još ljepšim plodovima, baštovan ga mora redovno čistiti i orezivati. Naš imetak je poput tog vrta. Zekat nije uzimanje od onoga što imamo, već čišćenje i rast našeg bogatstva. To je način na koji pokazujemo da smo zahvalni na onome što nam je darovano i da brinemo o drugima.</p>\n                    <p>Danas učimo o zekatu – četvrtom islamskom šartu. Saznat ćete kako on čisti dušu od škrtosti, donosi berićet u naše domove i zašto je važno da on teče kroz zajednički fond – Bejtul-mal.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I molitvu obavljajte i zekat dajite. (El-Bekare, 43)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Zekat je izdvajanje određenog dijela imovine koja dostiže vrijednost nisaba. Zekat je četvrti islamski šart i farz - obaveza za svakog muslimana i muslimanku koji ispunjavaju uvjete pod kojima su obavezni izvršiti ovu dužnost. Smatrati zekat farzom je uvjet ispravnosti vjerovanja jednog muslimana, a onaj ko negira obaveznost zekata smatra se nemuslimanom.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        Poslanik, alejhis-selam, je rekao: \"Islam se temelji na pet dužnosti: svjedočenje da nema boga osim Allaha i da je Muhammed Allahov poslanik, obavljanje namaza, davanje zekata, obavljanje hadža i post mjeseca ramazana.\" (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"section-subtitle\">UVJETI OBAVEZNOSTI ZEKATA</p>\n                <p class=\"lesson-text\">\n                    Obaveza zekata nastaje ukoliko se ispune sljedeći uvjeti:\n                </p>\n                <ol class=\"lesson-text\">\n                    <li>sloboda,</li>\n                    <li>stvarno vlasništvo nad imovinom,</li>\n                    <li>da imetak dostiže vrijednost nisaba,</li>\n                    <li>da određena zekatska imovina u vrijednosti nisaba bude u vlasništvu godinu dana.</li>\n                </ol>\n\n                <p class=\"section-subtitle\">IMOVINA NA KOJU SE DAJE ZEKAT</p>\n                \n                <table class=\"zekat-table lesson-text\">\n                    <tr>\n                        <th>VRSTA IMOVINE</th>\n                        <th>NISAB (VRIJEDNOST)</th>\n                        <th>IZNOS KOJI SE DAJE</th>\n                    </tr>\n                    <tr>\n                        <td>Zlato</td>\n                        <td>91,6 grama</td>\n                        <td>2,5%</td>\n                    </tr>\n                    <tr>\n                        <td>Srebro</td>\n                        <td>641,5 grama</td>\n                        <td>2,5%</td>\n                    </tr>\n                    <tr>\n                        <td>Novac i vrijednosni papiri</td>\n                        <td>vrijednost koju odredi Vijeće muftija</td>\n                        <td>2,5%</td>\n                    </tr>\n                    <tr>\n                        <td>Krupna stoka (krave)</td>\n                        <td>30 grla</td>\n                        <td>jedno grlo od dvije godine starosti</td>\n                    </tr>\n                    <tr>\n                        <td>Sitna stoka (ovce)</td>\n                        <td>40 grla</td>\n                        <td>jedno grlo</td>\n                    </tr>\n                </table>\n\n                <p class=\"lesson-text\">\n                    Zekat na poljoprivredne proizvode se izdvaja na dan žetve ili ubiranja plodova. Ukoliko su usjevi zalijevani isključivo kišom, izdvaja se 10%. Kada se ulažu trud i troškovi u zalijevanje, izdvaja se 5%. Ukoliko se jednom zalijevaju uz trud, a jednom prirodno, izdvaja se 7,5%.\n                </p>\n                <img src=\"/edu/assets/images/zekat.jpg\" style=\"float: right; width: 250px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"section-subtitle\">KOME SE DAJE ZEKAT?</p>\n                <p class=\"lesson-text\">\n                    Poslanikova, alejhis-selam, praksa je bila da se zekat sakuplja u jedan fond Bejtul-mal iz kojeg su se sredstva izdvajala potrebnim kategorijama navedenim u 60. ajetu sure Et-Tevbe. Takvu praksu slijedi Islamska zajednica u Bosni i Hercegovini, stoga mi zekat izdvajamo u fond Bejtul-mal pri Islamskoj zajednici, a nadalje se on dijeli shodno prioritetima među korisnicima.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\">MUDROST PROPISIVANJA ZEKATA</span><br><br>\n                        • čisti dušu od loših osobina škrtosti i pohlepe,<br>\n                        • čisti i povećava imetak (berićet),<br>\n                        • uspostavlja opće dobro i blagostanje,<br>\n                        • sprečava nagomilavanje imetka u rukama jedne skupine ljudi.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ZEKAT</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <p class=\"section-subtitle\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je zekat?</li>\n                    <li>Nabroj uvjete obaveznosti izdvajanja zekata?</li>\n                    <li>Šta je nisab?</li>\n                    <li>Na koju imovinu se daje zekat, koji je nisab za istu i koliko se izdvaja?</li>\n                    <li>U čemu se sastoji mudrost propisivanja zekata?</li>\n                </ol>\n\n                <p class=\"section-subtitle\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Razmisli o situaciji: Komšije izdvajaju zekat direktno siromašnoj osobi umjesto u Bejtul-mal. Da li je takav postupak opravdan prema propisima koje smo naučili?</li>\n                    <li>Pomoću zekat-kalkulatora izračunaj iznos zekata za 10.000 KM na bankovnom računu.</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":35,"is_published":true,"kviz_pitanja":[{"answer":"Zekat je četvrti islamski šart i farz","options":["Zekat je prvi šart od pet dužnosti islama","Zekat je četvrti islamski šart i farz","Zekat je drugi šart od šest dužnosti islama","Zekat je peti šart od sedam dužnosti islama"],"question":"Koliko je islamskih šarta i šta je zekat među njima?"},{"answer":"Imovina mora dosegnuti vrijednost nisaba","options":["Imovina mora biti u vlasništvu mjesec dana","Imovina mora dosegnuti vrijednost nisaba","Imovina mora biti od srebra ili zlata","Imovina mora biti samo novac ili zlato"],"question":"Koji je osnovni uvjet da bi se imovina zekotala?"},{"answer":"2,5 procenta od cijele imovine","options":["5 procenata od cijele imovine","10 procenata od cijele imovine","2,5 procenta od cijele imovine","1 procenat od cijele imovine"],"question":"Koliko procenata zekata se daje na zlato ili novac?"},{"answer":"91,6 grama zlata je nisab za zekat","options":["50 grama zlata je nisab za zekat","91,6 grama zlata je nisab za zekat","100 grama zlata je nisab za zekat","200 grama zlata je nisab za zekat"],"question":"Koliko grama zlata je potrebno da bi se dostigao nisab?"},{"answer":"30 grla krava je minimum za zekat","options":["20 grla krava je minimum za zekat","30 grla krava je minimum za zekat","40 grla krava je minimum za zekat","50 grla krava je minimum za zekat"],"question":"Koliko grla krupne stoke treba da bi se zekat obavezao?"}]},{"nivo":3,"slug":"sadekatul-fitr","naslov":"Sadekatul-fitr","content_html":"<div class=\"lesson-container\">\n        <h1>SADEKATUL-FITR</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sadaka.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Sadekatul-fitr (vitre)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema dijeljenju i radosti Bajrama za sve</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je sadekatul-fitr i kako se daje</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno daje vitre</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, prije Bajram-namaza svaki musliman daje sadekatul-fitr (vitre). Šta je to?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sadekatul-fitr (kod nas zvan \"vitre\") — vadžib koji se daje na kraju Ramazana, prije Bajram-namaza.</p><p>Daje se za svakog člana porodice — i muškog, i ženskog, i djecu, i posluge.</p><p>Vrijednost: sa‘ (cca 2,5-3 kg) osnovne hrane (žito, datule, riža) ili novčani ekvivalent.</p><p>Cilj: očišćenje posta od grešaka i da bi siromašni proslavili Bajram s ostalima.</p><p>Vrijeme: najbolje 1-2 dana prije Bajrama, da stigne onome kome je potrebno.</p><p>U BiH: vitre se daju Islamskoj zajednici ili direktno siromašnim porodicama.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta uraditi sa vitrama. Zaključak: vitre su radost Bajrama za siromašne.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":36,"is_published":true,"kviz_pitanja":[{"answer":"Čišćenje posta od nepromišljenih riječi i hranjenje siromašnih","options":["Čišćenje posta od nepromišljenih riječi i hranjenje siromašnih","Samo hranjenje bogatih članova društva","Kupovanje skupih darova za Bajram","Plaćanje duga Bejtul-malu"],"question":"Šta je glavni cilj sadekatul-fitra prema hadisu Ibn Abbasa?"},{"answer":"Druge godine po Hidžri","options":["Druge godine po Hidžri","Desete godine po Hidžri","Prvi dan ramazana","Dan Muhammeda, alejhis-selam"],"question":"Kada je sadekatul-fitr propisan?"},{"answer":"Musliman koji ima hrane više nego što mu treba","options":["Musliman koji ima hrane više nego što mu treba","Samo bogati muslimani","Samo odrasle žene","Samo muškarci koji rade"],"question":"Ko je obavezan da da sadekatul-fitr?"},{"answer":"Do pred klanjanje bajram-namaza","options":["Do pred klanjanje bajram-namaza","Tri dana nakon Bajrama","Tijekom cijelog mjeseca šavala","Nedjelju dana nakon Bajrama"],"question":"Do kada najkasnije treba dati sadekatul-fitr?"},{"answer":"Biće grešan i dužan je da je kasnije izdvoji","options":["Biće grešan i dužan je da je kasnije izdvoji","Nema nikakve greške jer je dobro djelo","Može je zamijeniti s drugim ibadetima","Allah će mu je automatski oprostiti"],"question":"Šta se dešava ako neko namjerno odgodi sadekatul-fitr?"}]},{"nivo":3,"slug":"hadz-propisi","naslov":"Hadž – propisi i odlike hadža","content_html":"<div class=\"lesson-container\">\n        <h1>HADŽ - PROPISI I ODLIKE HADŽA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/arefat.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Hadž – propisi i odlike hadža</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Mekki, Ka’bi i jedinstvu muslimana</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti propise (farzove, vadžibe, sunnete) i odlike (fadilete) hadža</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da razumije sve faze hadža</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je peti islamski šart? Hadž. Hajde da detaljno upoznamo njegove propise.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Farzovi hadža (3): <strong>1.</strong> Ihram (nijet i oblačenje); <strong>2.</strong> Vakfa na Arefatu (boravak na Arefatu na 9. zul-hidždžeta); <strong>3.</strong> Tavāf-i ifāda (obilazak Ka’be poslije Arefata).</p><p>Vadžibi: sa‘j (hodanje između Safe i Merve), bacanje kamenčića na Mini, klanje kurbana, brijanje/skraćivanje kose, oproštajni tavaf.</p><p>Sunneti: tavāful-kudum, dolazak ranije, učenje Kur’ana, dova na Multezemu, posjeta Medini.</p><p>Vrste hadža: <strong>Ifrad</strong> (samo hadž), <strong>Kıran</strong> (hadž i umra zajedno), <strong>Temettu‘</strong> (umra pa hadž).</p><p>Odlike: oprost svih grijeha — hadžija se vrati \"kao na dan kad ga je majka rodila\".</p><p>Uslov: punoljetstvo, zdravlje, mogućnost (materijalna i fizička).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju faze hadža. Zaključak: hadž je kruna ibadeta i susret cijelog ummeta.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                PUTOVANJE ŽIVOTA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite putovanje na koje krećete ne samo svojim tijelom, već cijelom svojom dušom. Putovanje koje vas vodi do samog srca islama, tamo gdje su hodali poslanici i gdje se milioni ljudi iz cijelog svijeta okupljaju kao jedno. To je hadž – kruna svih naših ibadeta i prilika da se vratimo čisti od grijeha, baš kao onoga dana kada smo rođeni.</p>\n                    <p>Danas učimo o petom islamskom šartu. Saznat ćemo ko je dužan obaviti hadž, šta su to ihrami koji nas čine jednakima pred Gospodarom, i koje sve obrede hadžija prolazi – od Arefata do Kabe. Ovo nije samo putovanje u daleku zemlju, već putovanje ka unutrašnjem miru i potpunoj predanosti Uzvišenom Allahu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š. kaže: Hadž i umru radi Allaha izvršavajte. (El-Bekare, 196)</p>\n                </div>\n\n                <p class=\"lesson-text\">Hadž je peti islamski šart koji je propisan svim muslimanima i muslimankama da obave jednom u životu ukoliko ispune uvjete.</p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\">HADIS</span><br>\n                        Ebu Hurejre, r.a., prenosi sljedeće riječi: \"Allahov Poslanik, alejhis-selam, nam je držao hutbu i rekao: 'O ljudi, Allah vam je propisao hadž, pa ga obavljajte.'\" (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">Hadž je ibadet koji označava posjetu Kabe i drugih svetih mjesta u propisanom vremenu.</p>\n\n                <p class=\"section-subtitle\">UVJETI OBAVEZNOSTI HADŽA</p>\n                <p class=\"lesson-text\">Da bi hadž muslimanu/muslimanki postao obaveza, moraju se ispuniti sljedeći uvjeti:</p>\n                <ol class=\"lesson-text\">\n                    <li>da je osoba punoljetna te fizički i mentalno zdrava,</li>\n                    <li>da posjeduje materijalne mogućnosti,</li>\n                    <li>sigurnost puta (mahrem).</li>\n                </ol>\n                <p class=\"lesson-text\">Pod drugim uvjetom se podrazumijeva da ima sredstva za putovanje i povratak s putovanja, te da je svoju porodicu osigurao da može živjeti do njegovog povratka.<br>Treći uvjet je da put bude siguran tj. da će na njemu hadžija biti siguran za svoj život i za svoj imetak. <br>Dodatni uvjet za žene je prisustvo mahrema, jer žena može putovati na hadž i umru samo pod uvjetom da s njom putuje muž ili neko od bliskih rođaka: otac, djed, brat, ili da putuje u društvu sa skupinom žena.</p>\n\n                <p class=\"section-subtitle\">PROPISI OBAVLJANJA FARZOVA HADŽA</p>\n                <p class=\"lesson-text\">Ranije smo govorili o farzovima i vadžibima hadža koji se moraju izvršiti da bi hadž bio ispravan. Kada se hadžije nađu u blizini Mekke na Mikatima, obavezni su zanijetiti i obući ihrame. Lijepo je da se prije oblačenja ihrama okupaju i namirišu. Za muškarce, ihrami, su dva bijela nešivena platna kojima se pokriva donji i gornji dio tijela. Za žene je ihram uobičajena nošnja ‒ hidžab. Nakon oblačenja ihrama hadžije će klanjati dva rekata te učeći telbiju nastaviti svoj put prema Mekki. Od trenutka kada učini ove radnje musliman i muslimanka su postali muhrimi i za njih važe sljedeće zabrane:</p>\n                <ul class=\"lesson-text\">\n                    <li>spolni odnos,</li>\n                    <li>bestidne riječi i djela,</li>\n                    <li>svađa i prepirke,</li>\n                    <li>lov, ubijanje insekata,</li>\n                    <li>mirisanje, rezanje nokata, brijanje i šišanje glave i drugih dijelova tijela, podrezivanje brade,</li>\n                    <li>korištenje mirisnih sapuna ili šampona prilikom kupanja,</li>\n                    <li>pokrivanje glave muškarcima i lica muškarcima i ženama,</li>\n                    <li>oblačenje bilo čega što nisu ihrami, odnosno bilo kakve šivene odjeće.</li>\n                </ul>\n                <p class=\"lesson-text\">Devetog dana zul-hidžeta, s izlaskom Sunca nastupa dan Arefata. Poslanik, alejhis-selam, je rekao: “Hadž je Arefat...” (Ahmed)</p>\n                \n                <p class=\"lesson-text\">Hadžije će podne-namaz i ikindija-namaz klanjati u podnevskom vremenu s učenjem jednog ezana i dva ikameta, te će vrijeme do zalaska Sunca provesti na Arefatu u ibadetu i dovi Allahu, dž.š. Nakon zalaska Sunca hadžije će se uputiti prema Muzdelifi (mjesto između Arefata i Mine), gdje će klanjati akšam i jaciju s učenjem jednog ezana i dva ikameta, te će poslije namaza skupiti kamenčiće za obred remj - gađanje šejtana na Mini.</p>\n                <p class=\"lesson-text\">Kada se klanja sabah-namaz 10. zul-hidžeta, hadžije će se zaputiti prema Velikom džemretu, gdje će učeći tekbire bacati kamenčiće.<br>\n                Nakon izvršenih obreda hadža na Mini hadžije će se zaputiti prema Mekki, gdje će obaviti treći farz hadža - tavaf. Tavaf počinje od Hadžerul-esveda (Crnog kamena) i to okrećući dlanove prema njemu ukoliko mu se ne mogu približiti kako bi ga poljubili. Tavaf se čini tako da Kaba bude s lijeve strane. Kada se završi obilazak oko Kabe sedam puta, hadžije će klanjati dva rekata iza Mekami-Ibrahima, te učiniti sa'j (ubrzani hod) između Safe i Merve.</p>\n                <img src=\"/edu/assets/images/kaba1.jpg\" style=\"float: right; width: 250px; margin-right: 10px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">Po završetku tavafa i sa'ja hadžije skidaju ihrame i prestaju važiti zabrane koje su imali dok su bili u obredima hadža. U danima tešrika (kada se uče tekbiri poslije farz-namaza) hadžije će obaviti i obred bacanja kamenčića na ostalim džemretima.<br>Nakon završetka hadžskih obreda, a prije nego što se upute u svoje mjesto stanovanja, hadžije su obavezne učiniti oproštajni tavaf nakon kojeg će napustiti Mekku. S ovim obredom su završili hadž.</p>\n                <p class=\"lesson-text\">Hadž je kruna vjerničkog ibadeta i srce svakog iskrenog muslimana i muslimanke čezne za danom kada će posjetiti sveta mjesta kojima je hodio posljednji Allahov poslanik Muhammed, alejhis-selam Obavljen hadž će vjernika učiniti još jačim u njegovom vjerovanju i dosljednijim u slijeđenju Muhammeda, alejhis-selam<br>\n                Zbog toga se muslimani i muslimanke trebaju kloniti i čuvati svih grijeha koji mogu narušiti ljepotu hadža.</p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Umra do umre je otkupljenje od grijeha počinjenih između njih, a za uredno obavljen i primljen hadž nema druge nagrade osim Dženneta.” (Buhari)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('UMRA', this)\">\n                UMRA - MALI HADŽ <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"UMRA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Umra je hodočašće Kabe u bilo kojem drugom vremenu izvan vremena hadža. Obredi umre su vezani samo za Haremi-šerif i sastoje se od: ihrama, tavafa i sa'ja. Budući da je manja gužva u Haremi-šerifu izvan hadžskih mjeseci, umra za vjernika predstavlja nezaboravan ibadet i priliku za detaljan obilazak svih svetih mjesta. Ovaj ibadet posebno je vrijedan u mjesecu ramazanu.</p>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        Poslanik, alejhis-selam, je rekao: “Kada nastupi ramazan, ti obavi umru, jer umra obavljena u ramazanu ravna je hadžu (po vrijednosti).” (Buhari)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - HADŽ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <p class=\"section-subtitle\">Pitanja</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je hadž?</li>\n                    <li>Koji su uvjeti obaveznosti hadža?</li>\n                    <li>Opišite propise obavljanja farzova hadža?</li>\n                    <li>Koja nagrada je obećana onome kome hadž bude primljen?</li>\n                </ol>\n                <p class=\"section-subtitle\">Zadatak</p>\n                <p class=\"lesson-text\">Pronađi osobu u svojoj porodici koja je obavila hadž te s njom razgovaraj o doživljaju obavljanja hadža. Najbitnije detalje zabilježi, pa o njima razgovaraj s muallimom/mualimom na času.</p>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":37,"is_published":true,"kviz_pitanja":[{"answer":"Jednom","options":["Dva puta","Jednom","Tri puta","Pet puta"],"question":"Koliko puta u životu musliman/muslimanka mora obaviti hadž?"},{"answer":"Bijela nešivena platna","options":["Zelena nešivena platna","Bijela nešivena platna","Crna jednodijelna haljina","Crvena šivena platna"],"question":"Koja su dva platna dio ihrама za muškarce?"},{"answer":"Prisustvo mahrema uz nju","options":["Da ima više od 30 godina","Prisustvo mahrema uz nju","Da ima vlastito vozilo","Dozvola školskog ravnatelja"],"question":"Koji je dodatni uvjet za žene da obave hadž?"},{"answer":"Brijanje i šišanje glave","options":["Čitanje Kurana","Brijanje i šišanje glave","Obavanje namaza","Konzumiranje vode"],"question":"Koji od sledećih postupaka je zabranjen za muhrima?"},{"answer":"Na Mikatima blizu Mekke","options":["U svojoj kući","Na Mikatima blizu Mekke","U Medini","Na putu prema Kabi"],"question":"Gdje se hadžije oblače ihramu prema lekciji?"}]},{"nivo":3,"slug":"et-tekassur","naslov":"Učenje sure Et-Tekasur","content_html":"<div class=\"lesson-container\">\n        <h1>UČENJE SURE ET-TEKASUR</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/tekasur.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure Et-Tekāsur</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Kur’anu i razumijevanja poruke sure Et-Tekāsur</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst, prijevod i osnovnu poruku sure Et-Tekāsur (102. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno uči i koristi suru Et-Tekāsur u namazu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, danas učimo suru Et-Tekāsur. Ima 8 ajeta i objavljena je u Mekkai. Šta nas Allah uči u njoj?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura Et-Tekāsur je 102. sura Kur’ana, ima 8 ajeta.</p><p>Objavljena je u Mekkai.</p><p>Glavna poruka: Ljudi su zauzeti gomilanjem dunjalučkih dobara dok ne odu u kabur — Allah upozorava da će ih ispitati za svaku blagodat.</p><p>Pišem suru na tabli (arapski + transkripcija + prijevod).</p><p>Učenici slušaju izgovor (sa snimka), zatim ponavljaju ajet po ajet u horu i pojedinačno.</p><p>Razgovor o značenju i poruci za naš svakodnevni život.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče cijelu suru zajedno. Zadaća: usavršiti učenje sure napamet i znati njen prijevod.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":38,"is_published":true,"kviz_pitanja":[{"answer":"U Mekki","options":["U Medini","U Mekki","U Jeruzalemu","U Kairu"],"question":"Gdje je objavljena sura Et-Tekasur?"},{"answer":"Osam ajeta","options":["Pet ajeta","Šest ajeta","Osam ajeta","Deset ajeta"],"question":"Koliko ajeta sadrži sura Et-Tekasur?"},{"answer":"O nastojanju biti što bogatiji","options":["O važnosti molitve","O nastojanju biti što bogatiji","O vrijednosti znanja","O poštovanju roditelja"],"question":"O čemu govori sura Et-Tekasur?"},{"answer":"Drugom će ostati","options":["Uzet će ga raj","Ostati će mu zauvijek","Drugom će ostati","Sagorit će u Džehenemu"],"question":"Što će se desiti sa stečenim imanjem nakon smrti čovjeka?"},{"answer":"Ono što pojede, obliječe ili prosljeđuje","options":["Sve što ima kuće","Ono što pojede, obliječe ili prosljeđuje","Samo dragocjeni predmeti","Sve osim zlata i srebra"],"question":"Prema hadisu, što od imetka čovjeku zaista pripada?"}]},{"nivo":3,"slug":"hadiske-zbirke","naslov":"Najpoznatije hadiske zbirke","content_html":"<div class=\"lesson-container\">\n        <h1>NAJPOZNATIJE HADISKE ZBIRKE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/hadiske_zbirke.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Najpoznatije hadiske zbirke</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema hadisima i sunnetu Poslanika, a.s.</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa najvažnijim hadiskim zbirkama i njihovim autorima</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike čitanja hadisa kao izvora znanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, gdje su sakupljeni hadisi Poslanika, a.s.? Postoje slavne knjige — hadiske zbirke. Koje?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Hadis — riječ, djelo ili odobrenje Poslanika, a.s.</p><p>Šest najpoznatijih (sahih) zbirki — \"Kutubu sitte\":</p><p><strong>1. Sahih Buhari</strong> — Imam Buhari (umro 256. h.), najautentičnija zbirka.</p><p><strong>2. Sahih Muslim</strong> — Imam Muslim (umro 261. h.).</p><p><strong>3. Sunen Ebu Davud</strong> — Imam Ebu Davud (umro 275. h.).</p><p><strong>4. Sunen Tirmizi</strong> — Imam Tirmizi (umro 279. h.).</p><p><strong>5. Sunen Nesai</strong> — Imam Nesai (umro 303. h.).</p><p><strong>6. Sunen Ibn Madže</strong> — Ibn Madže (umro 273. h.).</p><p>Postoje i druge zbirke: Muvetta Imam Malika, Musned Ahmed b. Hanbel.</p><p>Hadiski naučnici (muhaddisi) provjeravali su autentičnost svakog hadisa preko lanca prenosilaca (sened).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju 3-4 zbirke. Zaključak: hadis je drugi izvor islamske vjere poslije Kur’ana.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                ČUVARI POSLANIKOVE RIJEČI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite ljude koji su bili spremni putovati hiljadama kilometara, kroz pustinje i preko planina, samo da bi čuli i provjerili jednu jedinu rečenicu koju je izgovorio Muhammed, alejhis-selam Ti ljudi, poznati kao muhaddisi, bili su istinski čuvari mudrosti. Oni nisu dozvolili da se Poslanikove riječi zaborave ili pomiješaju s tuđim govorom.</p>\n                    <p>Danas ćemo saznati kako su nastale najvažnije knjige islama nakon Kur'ana. Otkrit ćemo zašto je pisanje hadisa u početku bilo zabranjeno, kako su ashabi pamtili svaku Poslanikovu radnju i ko su bili učenjaci koji su sastavili čuveni \"Kutubus-sitte\". Krenimo u istraživanje riznice koja nam već vijekovima pojašnjava kako živjeti vjeru na najljepši način.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Uzvišeni Allah je zadužio poslanika Muhammeda, alejhis-selam, da sljedbenicima dostavi i pojasni Kur'an. Allah, dž.š., kaže: Mi tebi objavljujemo Knjigu da bi im objasnio ono oko čega se razilaze. (En-Nahl, 64)</p>\n                <p class=\"lesson-text\">Muhammed, alejhis-selam, se zbog toga trudio da ashabima na najljepši način pojasni propise koji se nalaze u Božijoj knjizi ‒ Kur'anu. Ashabi su radi razumijevanja vjere bili stalni pratioci Allahovog Poslanika, alejhis-selam, družili se s njim i slušali šta je govorio. Na početku poslaničke misije Muhammed, alejhis-selam, je zabranio pisanje hadisa kako se tekst Kur'ana ne bi pomiješao s tekstom hadisa. U vremenu zabrane pisanja hadisa ashabi su pamtili i usmeno prenosili ono što je Muhammed, alejhis-selam, radio i govorio.</p>\n                <p class=\"lesson-text\">Kasnije je Allahov Poslanik, alejhis-selam, dozvolio pisanje hadisa, tako da su prvi hadisi zapisani još za njegova života. Bilježenje hadisa se nastavilo nakon Poslanikovog, alejhis-selam, preseljenja jer su uočeni slučajevi namjernog izmišljanja hadisa. Zbog toga su oni koji su se bavili sakupljanjem hadisa (muhaddisi), oprezno i precizno počeli sabirati hadise u hadiske zbirke. Bilježili su sve što je bilo vezano za život Muhammeda, alejhis-selam, a posebna pažnja obraćala se na Poslanikove, alejhis-selam, izreke ‒ hadise.<br>\n                Znajući za važnost hadisa u životu muslimana, muhaddisi nisu žalili ni truda ni vremena, tako su odlazili u daleka mjesta i gradove da bi provjerili istinitost i vjerodostojnost jednog ili više hadisa. Posebno su obraćali pažnju na sened (lanac prenosilaca hadisa), i ako bi samo jedna osoba bila nepouzdana, hadis ne bi bio zabilježen ili bi bio označen kao slab (daif). Najplodonosniji period sabiranja hadisa jeste kraj prvog i početak drugog stoljeća po Hidžri. U tom vremenu razvila se velika islamska naučna disciplina koja je imala za cilj sabiranje hadisa i njihovu selekciju, te podjelu po temama.</p>\n                <p class=\"lesson-text\">Među najpoznatijim i najvjerodostojnijim hadiskim zbirkama su:</p>\n                <ul class=\"lesson-text\">\n                    <li>Sahihul-Buhari</li>\n                    <li>Sahihu-Muslim.</li>\n                </ul>\n                <p class=\"lesson-text\">Sljedeće po vjerodostojnosti su: Sunen Ebu Davuda, Sunen Tirmizija, Sunen Nesaija i Sunen Ibn Madžea. Ove zbirke nazvane su jednim imenom El-Kutubus-sitte ‒ šest zbirki. Pored spomenutih, vrijedno je spomenuti i Muveta' zbirku hadisa Imama Malika.</p>\n                <p class=\"lesson-text\">Primjer velikog rada i zanimanja hadiskih učenjaka u pogledu hadisa su hadiske zbirke Buharija i Muslima. Imam Buhari je prvobitno u svom Sahihu spomenuo 600.000 hadisa, a Imam Muslim 300.000 hadisa. Nakon selekcije i provjere seneda, Imam Buhari je u svoju zbirku uvrstio oko 7.000 hadisa, a Imam Muslim oko 12.000 hadisa. To nam ukazuje s kolikom su pažnjom muhaddisi pristupali sakupljanju i bilježenju hadisa.</p>\n                <p class=\"lesson-text\">U posljednjim decenijama 20. i početkom 21. stoljeća pojavili su se i kompletni prijevodi najpoznatijih hadiskih zbirki na bosanskom jeziku. U tom projektu posebno su se istakli naši muhaddisi: Hasan-ef. Škapur, prof. Mahmut-ef. Karalić, prof. dr. Šefik Kurdić i drugi. Zahvaljujući njihovom trudu, danas svaki musliman i muslimanka u našoj domovini može izučavati i primjenjivati poruke hadisa u svom svakodnevnom životu.</p>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\">ZAPAMTI!</span><br>\n                        Sened je lanac poimeničnih prenosilaca hadisa koji seže do ashaba koji su hadis slušali i pamtili od Poslanika, alejhis-selam Uvjeti za ispravnost seneda su veoma strogi, tako da se vjerodostojnost hadisa očuvala do danas. Po vjerodostojnosti, hadise dijelimo na sahih ‒ vjerodostojne, hasen ‒ dobre i daif ‒ slabe.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - HADISKE ZBIRKE</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Kada je počelo zapisivanje hadisa?</li>\n                    <li>Koje su najpoznatije zbirke hadisa?</li>\n                    <li>Kako se jednim imenom naziva šest zbirki i koje su to?</li>\n                    <li>Kada su se pojavili prijevodi zbirki hadisa na bosanskom jeziku i koji muhaddisi su se posebno istakli u tom projektu?</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":39,"is_published":true,"kviz_pitanja":[{"answer":"Propise koji se nalaze u Kur'anu","options":["Propise koji se nalaze u Kur'anu","Samo arapski jezik","Cijene na tržištu","Graditeljske vještine"],"question":"Šta je Allahov Poslanik, alejhis-selam, trebao da pojasni ashabi?"},{"answer":"Kako se tekst Kur'ana ne bi pomiješao s tekstom hadisa","options":["Kako se tekst Kur'ana ne bi pomiješao s tekstom hadisa","Jer nisu imali papira","Jer je bilo previše vrućine","Jer ashabi nisu znali pisati"],"question":"Zašto je Muhammed, alejhis-selam, prvo zabranio pisanje hadisa?"},{"answer":"Sahihul-Buhari i Sahihu-Muslim","options":["Sahihul-Buhari i Sahihu-Muslim","Samo Muveta' Imama Malika","Samo Sunen Ebu Davuda","Samo Sunen Tirmizija"],"question":"Koji su najpoznatije i najvjerodostojnije hadiske zbirke?"},{"answer":"Hadis ne bi bio zabilježen ili bi bio označen kao slab","options":["Hadis ne bi bio zabilježen ili bi bio označen kao slab","Hadis bi bio odmah odbijen","Hadis bi bio smatran sasvim valjanim","Hadis bi bio učinjen obavezujućim"],"question":"Što je bilo ako bi u senedi bila nepouzdana osoba?"},{"answer":"Oko 7000 hadisa","options":["Oko 7000 hadisa","600.000 hadisa","300.000 hadisa","10.000 hadisa"],"question":"Koliko je hadisa Imam Buhari uključio u Sahih nakon selekcije?"}]},{"nivo":3,"slug":"mukellef","naslov":"Ef 'alu mukellefīn – postupci odraslih osoba","content_html":"<div class=\"lesson-container\">\n        <h1>EF 'ALU MUKELLEFIN - POSTUPCI ODRASLIH OSOBA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mukellefin.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ef‘alu mukellefīn – postupci odraslih osoba</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o pravnim kategorijama postupaka</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pet kategorija postupaka u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da klasificira postupke prema islamskim pravilima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li su sva djela ista pred Allahom? Ne! Postoji pet kategorija. Šta je to \"ef‘alu mukellefīn\"?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mukellef — punoljetna i razumna osoba kojoj je Allah dao šerijatske obaveze.</p><p>Pet kategorija postupaka:</p><p><strong>1. Farz/vadžib</strong> — obavezno (npr. namaz, post). Činiti se nagrađuje, ostaviti je grijeh.</p><p><strong>2. Mendub/sunnet</strong> — preporučeno (npr. nafila, miswak). Činiti se nagrađuje, ostaviti nije grijeh.</p><p><strong>3. Mubah</strong> — dozvoljeno/neutralno (npr. ići na izlet). Ni nagrada ni kazna.</p><p><strong>4. Mekruh</strong> — pokuđeno (npr. jesti bez Bismille). Ostavljanje se nagrađuje, činjenje umanjuje.</p><p><strong>5. Haram</strong> — zabranjeno (npr. krađa, alkohol). Ostavljanje se nagrađuje, činjenje je grijeh.</p><p>Naša obaveza: znati gdje je granica i ne prelaziti je.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici klasifikuju razne radnje (jedu, klanjaju, lažu, čitaju). Zaključak: živimo svjesno u Allahovom putu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":40,"is_published":true,"kviz_pitanja":[{"answer":"Punoljetna i umno zdrava muslimanka ili musliman","options":["Punoljetna i umno zdrava muslimanka ili musliman","Samo djecu koja su počela namaz","Osoba koja je bogata i ima mnogo novca","Onaj ko nije punoljetak"],"question":"Koja osoba se naziva mukellef?"},{"answer":"Na osam propisa","options":["Na osam propisa","Na pet propisa","Na tri propisa","Na deset propisa"],"question":"Na koliko dijelova se dijele Ef'alu mukellefin?"},{"answer":"Konzumiranje alkohola i svinjskog mesa","options":["Konzumiranje alkohola i svinjskog mesa","Učenje ezana i ikameta","Vitr-namaz","Namaz u džematu"],"question":"Koji od sljedećih primjera je HARAM?"},{"answer":"Kelimei-šehadet, namaz, post, zekat, hadž","options":["Kelimei-šehadet, namaz, post, zekat, hadž","Klanjanje dženaza-namaza","Vitr-namaz i bajram-namaz","Gradnja džamija i škola"],"question":"Koji su primjeri Fardi-'ajn dužnosti?"},{"answer":"Izgovoriti Kelimei-šehadet i učiniti tevbu","options":["Izgovoriti Kelimei-šehadet i učiniti tevbu","Samo moliti i postiti","Pokloniti se pred skupštinom","Dati većinu svog novca"],"question":"Šta mora učiniti osoba koja poriče farz ili haram?"}]},{"nivo":3,"slug":"gusul","naslov":"Gusul – vjersko kupanje","content_html":"<div class=\"lesson-container\">\n        <h1>GUSUL - VJERSKO KUPANJE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/gusul.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Gusul – vjersko kupanje</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike čistoće tijela i duše</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je gusul, kada je obavezan i kako se obavlja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da pravilno obave gusul</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, znamo abdest. A šta je gusul? Kada je obavezan? Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Gusul — potpuno kupanje cijelog tijela vodom, sa nijetom čišćenja od velike nečistoće.</p><p>Kada je obavezan (farz): poslije velike nečistoće (džunuba), poslije završetka hajza i nifasa, kod prelaska u islam.</p><p>Kada je sunnet/preporučen: prije džume, Bajrama, Arefe, ulaska u ihram.</p><p>Farzovi gusula: nijet (preporučen — formalno se ne traži za gusul nego za abdest u njemu); ispiranje usta i nosa; pranje cijelog tijela bez izostavljanja ijednog dijela kože i kose.</p><p>Postupak: izgovor \"Bismillāh\" → opranje stidnih dijelova → uzmemo abdest → polijemo glavu → desnu pa lijevu stranu tijela.</p><p>Gusul = potpuna čistoća — i tjelesna i duhovna spremnost za ibadet.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju kada je gusul obavezan. Zaključak: čist musliman je spreman za susret sa Allahom.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":41,"is_published":true,"kviz_pitanja":[{"answer":"Nakon spolnog odnosa, izlijevanja sjemene i hajza","options":["Samo prije namaza","Nakon spolnog odnosa, izlijevanja sjemene i hajza","Samo prije učenja Kur'ana","Prije svakog abdesta"],"question":"U kojim slučajevima je gusul obavezan?"},{"answer":"Tri farza","options":["Pet farzova","Dva farza","Tri farza","Četiri farza"],"question":"Koliko farzova ima gusul?"},{"answer":"Klanjati namaz i ulaziti u džamiju","options":["Jesti i piti","Klanjati namaz i ulaziti u džamiju","Hodati i raditi","Pričati i slušati"],"question":"Šta osoba u stanju džunuba NE smije činiti?"},{"answer":"Gargara, istinšak i gasli vudžud","options":["Gargara, istinšak i gasli vudžud","Abdest, sapun i miris","Voda, sapun i šampon","Nijet, gargara i šampon"],"question":"Koji su tri farza gusula?"},{"answer":"Prije džume, bajrama i ihrama","options":["Prije zuma, teravih i džume","Prije džume, bajrama i ihrama","Prije iftara, sahura i namaza","Prije zuma, bismile i džume"],"question":"Pred kojim vjerskim obavezama se čine tri sunnetska gusula?"}]},{"nivo":3,"slug":"hajz-nifas","naslov":"Hajz, nifas i istihaza","content_html":"<div class=\"lesson-container\">\n        <h1>HAJZ, NIFAS – ISTIHAZA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/drogerija.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Hajz, nifas i istihaza</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pravilnog razumijevanja ženskih propisa u islamu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pojmove hajz (mjesečnica), nifas (poslije porođaja) i istihaza (krvarenje)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti djevojčice/dječake da znaju propise koji se ih tiču</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco (s obzirom na uzrast), danas učimo o ženskim propisima koji su važni za poznavanje. Hajz, nifas, istihaza.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Hajz</strong> — mjesečno krvarenje žene; traje obično 3-10 dana. Žena u hajzu ne klanja, ne posti (post se naklanjava), ne tavafi, ne dotiče Mushaf.</p><p><strong>Nifas</strong> — krvarenje poslije porođaja; traje do 40 dana. Isti propisi kao hajz.</p><p><strong>Istihaza</strong> — krvarenje izvan vremena hajza/nifasa (npr. zbog bolesti). Ne sprječava ibadete — žena uzima abdest za svaki namaz i klanja.</p><p>Žena u hajzu/nifasu nije \"nečista\" duhovno — može učiti dove, slušati Kur’an, raditi sva druga dobra djela.</p><p>Poslije završetka hajza/nifasa — obavezan gusul, pa žena nastavlja sa svim ibadetima.</p><p>Naša obaveza prema majkama, sestrama, ženama: poštovati i razumjeti ove faze, ne praviti ih tabuom.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o važnosti znanja propisa. Zaključak: islam ima riješenja za sve životne situacije.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                POSEBNA STANJA I OLAKŠICE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da imate veoma važan zadatak koji morate obavljati svaki dan, ali vam vaš učitelj, jer vas voli i razumije, u određenim danima kaže: \"Sada se odmori, ne moraš raditi taj zadatak, a ja ću ti to ipak upisati kao da si uradio.\" Islam je upravo takav – on prepoznaje prirodna stanja kroz koja prolazi svaka žena i u tim trenucima joj daruje posebne olakšice.</p>\n                    <p>Danas ćemo naučiti o hajzu, nifasu i istihazi. Saznat ćemo šta ovi termini znače, koliko traju ta stanja i koje su vjerske dužnosti žene u tim periodima. Razumijevanje ovih propisa pomaže nam da pravilno obavljamo ibadete i cijenimo pažnju koju naš Stvoritelj pokazuje prema zdravlju i prirodi žene.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"section-subtitle\">HAJZ – MJESEČNICA</p>\n                <p class=\"lesson-text\">Hajz – mjesečnica (mjesečno krvarenje, mjesečno pranje, mjesečni ciklus) je mjesečno krvarenje iz maternice odrasle ženske osobe koje može trajati od tri do deset dana. Prva mjesečnica se najčešće pojavljuje u dobi od jedanaeste do petnaeste godine zavisno od klime, ishrane, zdravlja i gena.</p>\n                <p class=\"lesson-text\">Najkraći period između dva hajza je 15 dana, dok za najduži period nema granice.</p>\n                \n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Najkraći period hajza je tri, a najduži deset dana.” (Taberani)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">Ženi je u stanju hajza zabranjeno klanjati, postiti i imati spolni odnos. Propuštene namaze žena nije dužna naklanjati dok je propuštene dane posta dužna napostiti i najbolje je da to učini odmah nakon Ramazanskog bajrama ili do sljedećeg ramazana.</p>\n\n                <p class=\"section-subtitle\">NIFAS – POSLIJEPOROĐAJNO KRVARENJE</p>\n                <p class=\"lesson-text\">Nifas – poslijeporođajno krvarenje iz maternice (poslijeporođajna krv, poslijeporođajno pranje) je krvarenje kod žene odmah poslije poroda koje može trajati do 40 dana, to je najduži period nifasa dok za najkraći ne postoji granica.</p>\n                <p class=\"lesson-text\">Ženi u stanju nifasa je zabranjeno klanjati, postiti i imati spolni odnos. Propuštene namaze žena nije dužna naklanjati, dok je propuštene dane posta dužna napostiti i najbolje je da to učini odmah nakon Ramazanskog bajrama ili do sljedećeg ramazana.</p>\n\n                <p class=\"section-subtitle\">ISTIHAZA – KRVARENJE KOJE NIJE NI HAJZ NI NIFAS</p>\n                <p class=\"lesson-text\">Istihaza je krvarenje (bijelo pranje, bijeli cvijet, bijelo vrijeme) kod odrasle ženske osobe u periodu koji nije ni hajz ni nifas. Ako se pojavljuje u vremenu hajza, istihaza može trajati manje od tri dana ili više od 10 dana, a kod nifasa preko 40 dana. Ženska osoba u vrijeme istihaze smatra se sahibi-uzurom i dužna je pridržavati se propisa vezanih za sahibi-uzura.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - HAJZ, NIFAS I ISTIHAZA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\"> PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <p class=\"section-subtitle\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je hajz, a šta nifas?</li>\n                    <li>Koliko traje stanje hajza, a koliko stanje nifasa?</li>\n                    <li>Šta je zabranjeno ženama u stanju hajza i nifasa?</li>\n                    <li>Šta je istihaza?</li>\n                    <li>Kakav status ima žena u stanju istihaze?</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":42,"is_published":true,"kviz_pitanja":[{"answer":"Od tri do deset dana","options":["Od jedan do pet dana","Od tri do deset dana","Od pet do петнаest dana","Od deset do dvadeset dana"],"question":"Koliko dana može trajati hajz - mjesečnica?"},{"answer":"Od jedanaeste do petnaeste godine","options":["Od osme do desete godine","Od jedanaeste do petnaeste godine","Od šesnaeste do dvadeset godine","Od dvadesete godine naviše"],"question":"U kojem dobu se pojavljuje prva mjesečnica?"},{"answer":"Do 40 dana","options":["Do 20 dana","Do 30 dana","Do 40 dana","Do 50 dana"],"question":"Koliko dana može trajati nifas - poslijeporođajno krvarenje?"},{"answer":"Krvarenje koje nije ni hajz ni nifas","options":["Krvarenje samo tijekom posta","Krvarenje koje je najkraće od svih","Krvarenje koje nije ni hajz ni nifas","Krvarenje koje traje manje od tri dana"],"question":"Šta je istihaza?"},{"answer":"Ne klanjati, ne postiti i ne imati spolni odnos","options":["Klanjati samo zuhur i ažsr","Ne klanjati, ne postiti i ne imati spolni odnos","Postiti samo tijekom noći","Klanjati samo dve namaze dnevno"],"question":"Koja je glavna obaveza žene u stanju hajza?"}]},{"nivo":3,"slug":"sahibi-uzur","naslov":"Sahibi-uzur","content_html":"<div class=\"lesson-container\">\n        <h1>SAHIBI-UZUR</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sahibi_uzur.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Sahibi-uzur (osoba sa kroničnim opravdanjem)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat / Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pravilnog razumijevanja olakšica koje Allah daje bolesnima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pojam \"sahibi-uzur\" i njegove olakšice u namazu i abdestu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da razumije propise za hroničnu bolest</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta uraditi kad neko ima neku trajnu bolest koja prekida abdest (npr. stalno teče krv, bol)? Allah je dao olakšice — sahibi-uzur.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sahibi-uzur — osoba sa trajnim/hroničnim opravdanjem (npr. inkontinencija, stalno krvarenje, gnoj iz rane, žena sa istihazom).</p><p>Pravilo: Ako u cijelom vremenu jednog namaza nema momenat kad može uzeti abdest i klanjati bez prekida — postaje sahibi-uzur.</p><p>Olakšice: jedan abdest važi za jedan cijeli vrijeme namaza — može klanjati farz i sunnete čak i ako uzur nastupi tokom namaza.</p><p>Kad nastupi novo vrijeme namaza — uzima novi abdest.</p><p>Bolesnici klanjaju kako mogu: stojeći → sjedeći → ležeći; znacima ako ne mogu pokretima.</p><p>Allah u Kur’anu: \"Allah ne tereti dušu preko njene moći.\"</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o Allahovim olakšicama. Zaključak: islam je vjera milosti — niko nije izostavljen iz ibadeta.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                ALLAHOVA OLAKŠICA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamisliti da se nalaziti u situaciji u kojoj vaša iskrena želja da obavljati namaz biti otežana zbog zdravstvenih razloga koji ne prestajati. Allah, dž.š., koji znati sve naše poteškoće, ne željeti da nam vjera biti teret, već olakšanje. On nas učiti da svaki trud koji ulažiti u Njegovo ime, unatoč preprekama, imati posebnu vrijednost.</p>\n                    <p>Danas naučiti ko biti \"sahibi-uzur\" i kako islam rješavati situacije kada osoba imati stalnu fizičku nečistoću koju ne moći kontrolisati. Saznati kako pravilno uzimati abdest u takvim okolnostima i na koji način obavljati namaz bez straha da on neće biti primljen. Kroz ova pravila spoznati kolika biti Allahova milost prema svakom vjerniku koji se truditi da ostati u pokornosti.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Uvjet za ispravnost namaza je čistoća tijela, odijela i mjesta gdje se klanja, te posjedovanje abdesta. Međutim, postoje osobe koje zbog bolesti imaju stalni nedostatak koji kvari abdest (npr. stalno krvarenje iz nosa, rane koja stalno curi, nemogućnost zadržavanja vjetra ili mokraće). Takve osobe nazivamo SAHIBI-UZUR.</p>\n                \n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">PRAVILA ZA SAHIBI-UZURA</p>\n                <p class=\"lesson-text\">Osoba se smatra sahibi-uzurom ako joj nedostatak koji kvari abdest traje cijelo jedno namasko vrijeme, tako da u tom vremenu ne može uzeti abdest i klanjati namaz, a da se uzur ne pojavi. Da bi osoba i dalje zadržala ovaj status, dovoljno je da se u svakom narednom namaskom vremenu taj uzur pojavi makar jednom.</p>\n\n                <p class=\"lesson-text\">Pravila za abdest i namaz sahibi-uzura su:</p>\n                <ul>\n                    <li class=\"lesson-text\">Sahibi-uzur uzima abdest za svako namasko vrijeme posebno.</li>\n                    <li class=\"lesson-text\">Kada nastupi namasko vrijeme (npr. podne), osoba uzme abdest i s tim abdestom može klanjati farz, sunnete i učiti Kur'an sve dok to namasko vrijeme ne istekne.</li>\n                    <li class=\"lesson-text\">Abdest sahibi-uzura kvare sve uobičajene stvari koje inače kvare abdest, osim onog uzura zbog kojeg je osoba dobila taj status.</li>\n                    <li class=\"lesson-text\">Istekom namaskog vremena (npr. kada nastupi ikindija), abdest sahibi-uzura prestaje važiti i mora se uzeti novi.</li>\n                </ul>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">VAŽNA NAPOMENA</span><br>\n                        Islam je vjera olakšanja. Sahibi-uzur, unatoč svom nedostatku, ne smije ostavljati namaz, već koristi ove olakšice koje mu je Šerijat omogućio.\n                    </p>\n                </div>\n                \n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - SAHIBI-UZUR</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol>\n                    <li class=\"lesson-text\">Ko je sahibi-uzur?</li>\n                    <li class=\"lesson-text\">Nabroj neke primjere opravdanih razloga (uzura).</li>\n                    <li class=\"lesson-text\">Kada osoba dobija status sahibi-uzura?</li>\n                    <li class=\"lesson-text\">Kako sahibi-uzur postupa prilikom uzimanja abdesta?</li>\n                    <li class=\"lesson-text\">Kada sahibi-uzuru prestaje važiti abdest?</li>\n                    <li class=\"lesson-text\">ZADATAK: Razmisli o tome kako islam olakšava bolesnim osobama obavljanje ibadeta i zašto je važno ne ostavljati namaz čak i u bolesti.</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":43,"is_published":true,"kviz_pitanja":[{"answer":"Sahibi-uzur","options":["Sahibi-uzur","Muhalifun","Munafici","Ahlul-bidah"],"question":"Kako nazivamo osobe koje imaju stalni nedostatak koji kvari abdest?"},{"answer":"Za svako namasko vrijeme posebno","options":["Samo jednom","Za svako namasko vrijeme posebno","Dva puta dnevno","Prema potrebi kada želi"],"question":"Koliko puta sahibi-uzur mora uzeti abdest tijekom dana?"},{"answer":"Farz, sunnete i učenje Kur'ana","options":["Samo farz namaz","Farz, sunnete i učenje Kur'ana","Samo sunnete","Samo učenje Kur'ana"],"question":"Šta sahibi-uzur može činiti s abdestom tijekom jednog namaskog vremena?"},{"answer":"Istekom namaskog vremena","options":["Kada se pojavi uzur","Kada padne kiša","Istekom namaskog vremena","Kada izađe iz kuće"],"question":"Kada prestaje važiti abdest sahibi-uzura?"},{"answer":"Ostavljati namaz","options":["Izlaziti iz kuće","Ostavljati namaz","Raditi teške poslove","Piti vodu"],"question":"Što sahibi-uzur ne smije raditi unatoč svom nedostatku?"}]},{"nivo":3,"slug":"porodica","naslov":"Uloga i značaj porodice","content_html":"<div class=\"lesson-container\">\n        <h1>ULOGA I ZNAČAJ PORODICE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/porodica.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Uloga i značaj porodice u islamu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema porodici i osjećaja odgovornosti</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamsko viđenje porodice i njene uloge</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika koje jačaju porodičnu zajednicu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je porodica? Ko sve čini vašu porodicu? Šta islam kaže o porodici?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Porodica — temeljna ćelija društva u islamu, nastaje brakom muža i žene.</p><p>Funkcije porodice: ljubav, odgoj djece, ekonomska podrška, prenošenje vjere i tradicije, čuvanje časti.</p><p>Uloge: <strong>otac</strong> — vođa i izdrživalac; <strong>majka</strong> — srce porodice, prva učiteljica; <strong>djeca</strong> — radost i amanet; <strong>dede i nene</strong> — mudrost i blagoslov.</p><p>Poslanik, a.s.: \"Najbolji od vas je onaj ko je najbolji prema svojoj porodici.\"</p><p>Aktivnosti koje jačaju porodicu: zajednički obroci, klanjanje u džematu kod kuće, učenje Kur’ana zajedno, izleti, razgovor.</p><p>Razgovor: šta ja činim za svoju porodicu?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o svojoj porodici. Zaključak: porodica je naše najveće blago — čuvajmo je.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NAŠE SIGURNO GNIJEZDO <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Porodica je poput drveta čije je korijenje duboko u zemlji, a grane dosežu visoko prema nebu. Svaki list i svaka grana imaju svoje mjesto i ulogu, a zajedno čine drvo snažnim i lijepim. Od prvog čovjeka Adema, alejhis-selam, i hazreti Have, porodica je mjesto gdje učimo prve korake, prve riječi i prve lekcije o dobroti i ljubavi.</p>\n                    <p>Danas istražiti značaj porodice u islamu. Saznati zašto islam porodicu smatrati osnovnom ćelijom društva i na koji način možemo doprinijeti da u našem domu vladaju sloga i povjerenje. Naučiti koje su karakteristike muslimanske porodice i kako čuvati tu najvredniju riznicu koju imati.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: I jedan od dokaza Njegovih je to što za vas, od vrste vaše, stvara žene da se uz njih smirite, i što između vas uspostavlja ljubav i samilost; to su, zaista, pouke za ljude koji razmišljaju. (Er-Rum, 21)</p>\n                </div>\n                <p class=\"lesson-text\">Allahovim stvaranjem hazreti Have uz Adema, alejhis-selam, a nakon rađanja njihove djece, nastala je prva porodica na dunjaluku. Od tada, porodica je uvijek imala najvažnije mjesto u svakom vremenu i društvu. Učeni ljudi su rekli da je porodica temelj na kojem počiva kompletno društvo.</p>\n                <p class=\"lesson-text\">Islam na porodicu gleda kao na osnovnu ćeliju iz koje stasavaju najbolji pojedinci. Zbog toga islam poklanja posebnu pažnju zasnivanju i izgradnji porodice, te precizno određuje propise za očuvanje zdrave porodice.</p>\n                <p class=\"lesson-text\">Jedan od najbitnijih preduvjeta za zdravu porodicu jeste izbor supružnika, a islam preporučuje da se tom prilikom vodi računa o tome da osoba pri sebi ima vjeru, a nakon vjere i čestitost, blagost, ljubav, milost, ali i druge lijepe osobine.</p>\n                <p class=\"lesson-text\">Nemoguće je zamisliti skladan život bez porodice, a porodični život počinje stupanjem u brak. U tome se slažu sve religije i filozofije koje se temelje na moralu. Brak je osnova na kojoj počiva porodični život.</p>\n                <p class=\"lesson-text\">Porodica ima svoje osnovno i šire značenje. Osnovno značenje riječi porodica u islamu odnosi se samo na roditelje i djecu, a šire na ostale članove porodice kao što su djed, nana, a nakon njih tetke, daidže, amidže i njihova djeca. Dakle, islam teži ka uvezivanju većeg broja članova u porodici kako bi veze među njima bile što jače, a na taj način se ojačava društvo u cjelini.</p>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: A rođaci su, prema Allahovoj Knjizi, jedni drugima preči, Allah, zaista sve zna. (El-Enfal, 75)</p>\n                </div>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Allahovo zadovoljstvo je u zadovoljstvu roditelja, a Allahova srdžba je u srdžbi roditelja.” (Tirmizi)\n                    </p>\n                </div>\n                <img src=\"/edu/assets/images/porodica1.jpg\" style=\"float: right; width: 200px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">Stupanjem u brak supružnici su dužni očuvati porodicu, što je jedno od zaduženja od Allaha, dž.š. Porodica se kao i mnoge druge ljudske vrijednosti uvijek nalazi pred izazovima koji prijete da naruše njen sklad i harmoniju. Mnogo je faktora koji mogu narušiti porodične odnose te je dovesti do raspada. Prijetnje zdravoj porodici mogu doći izvana, međutim, ponajveća opasnost dolazi upravo od supružnika, i to zbog:</p>\n                <ul class=\"lesson-text\">\n                    <li>nesloge bračnih drugova,</li>\n                    <li>činjenja velikih ili teških grijeha,</li>\n                    <li>nasilja u porodici, te</li>\n                    <li>neispunjavanja bračnih i porodičnih obaveza.</li>\n                </ul>\n                <p class=\"lesson-text\">Čuvanje porodice je pojedinačna, ali i kolektivna obaveza. Zato roditelji i njihovo potomstvo, svako na svoj način, trebaju doprinositi očuvanju zdravog porodičnog ambijenta u kojem vladaju sloga, razumijevanje i saradnja. Roditelji to čine kroz međusobnu ljubav i poštovanje, a potomstvo pažnjom i poslušnošću prema roditeljima.</p>\n                <p class=\"lesson-text\">U osnovne karakteristike muslimanske porodice ubrajaju se:</p>\n                <ul class=\"lesson-text\">\n                    <li>vjerovanje u Allaha, dž.š.,</li>\n                    <li>poslušnost Allahu i Njegovom Poslaniku, alejhis-selam,</li>\n                    <li>izvršavanje islamskih dužnosti,</li>\n                    <li>pridržavanje propisa vjere,</li>\n                    <li>čuvanje od grijeha,</li>\n                    <li>lijepo ponašanje,</li>\n                    <li>radne navike te</li>\n                    <li>sloga i međusobno povjerenje.</li>\n                </ul>\n                <p class=\"lesson-text\">Porodica u kojoj se vjeruje u Allaha, dž.š., izvršava islamske dužnosti, čuva od svega što je Uzvišeni Allah zabranio i gdje se njeguje povjerenje, iskrenost, pravednost i lijepa riječ može imati poteškoća, ali će ih mnogo lakše rješavati.</p>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">ZAPAMTI!</span><br>\n                        Muslimansku porodicu karakteriziraju vrijednosti koje uvijek rezultiraju uspjehom i lijepom porodičnom atmosferom.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Kako islam posmatra porodicu?</li>\n                    <li>Koje je osnovno, a koje šire značenje porodice?</li>\n                    <li>Koje su prijetnje zdravlju porodice?</li>\n                    <li>Ko je zadužen za čuvanje porodice?</li>\n                    <li>Koje su osnovne karakteristike muslimanske porodice?</li>\n                </ol>\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">ZADATAK</p>\n                <ul class=\"lesson-text\">\n                    <li>Na malo većem papiru uradi porodično stablo svoje porodice. Neka ti u tome pomognu roditelji, djed i nana, te čuvaj svoje porodično stablo i proširuj ga novim članovima.</li>\n                    <li>U deset rečenica opiši svoju savršenu porodicu!</li>\n                    <li>Razmisli! Kako društvo može čuvati porodicu budući da je ona osnovna ćelija društva?</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":44,"is_published":true,"kviz_pitanja":[{"answer":"Porodica","options":["Škola","Porodica","State","Trgovina"],"question":"Šta je prema islamu temelj na kojem počiva kompletno društvo?"},{"answer":"Izbor supružnika","options":["Izbor supružnika","Bogato bogatstvo","Veliki dom","Mnogo djece"],"question":"Koji je jedan od najbitnijih preduvjeta za zdravu porodicu?"},{"answer":"Na roditelje i djecu","options":["Samo na vjernike","Na roditelje i djecu","Na sve susjede","Na cijelo selo"],"question":"Na koga se osnovno značenje porodice u islamu odnosi?"},{"answer":"Zadovoljstvo roditelja","options":["Bogatstvo","Zadovoljstvo roditelja","Lijjepe kuće","Skupo odijelo"],"question":"Šta je prema hadisu Allahovo zadovoljstvo vezano za?"},{"answer":"Vjera, čestitost, blagost, ljubav i milost","options":["Samo ljepota","Vjera, čestitost, blagost, ljubav i milost","Samo bogatstvo","Samo pametnost"],"question":"Koja su lijepa svojstva koja islam preporučuje kod izbora supružnika?"}]},{"nivo":3,"slug":"brak","naslov":"Islamski brak","content_html":"<div class=\"lesson-container\">\n        <h1>ISLAMSKI BRAK</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/brak_porodica.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Islamski brak (nikāh)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pravilnog razumijevanja braka kao Allahovog dara i ibadeta</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam nikāha, njegove uvjete i ciljeve</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike za buduće odgovorno bračno odlučivanje</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je brak? Zašto se ljudi ženu/udaju? U islamu je brak ibadet. Šta je nikāh?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Brak (nikāh) — ugovor između muškarca i žene da žive zajedno u ljubavi i poštovanju, sa ciljem osnivanja porodice.</p><p>Cilj: smiraj duše (\"sekīna\"), čuvanje časti, rađanje djece, jačanje društva.</p><p>Uvjeti nikāha: <strong>1.</strong> Pristanak oba supružnika, <strong>2.</strong> Mehr (poklon ženi), <strong>3.</strong> Dva svjedoka, <strong>4.</strong> Walī (zaštitnik djevojke).</p><p>Pravila nikāha: javnost (nije tajni), čistoća (oba supružnika su slobodni), poštovanje šerijata.</p><p>Sunneti: prosba (hitba), velima (svadbena gozba), dova za supružnike.</p><p>Brak je polovina vjere — Poslanik, a.s.: \"Ko se oženi — upotpunio je polovinu svoje vjere.\"</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o značaju ozbiljnog odabira supružnika. Zaključak: brak nije igra — to je trajna obaveza i blagoslov.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                DOM IZGRAĐEN NA LJUBAVI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Da li ste ikada razmišljali o tome kako se gradi dom u kojem vladaju samo osmijeh i podrška? Naša Merjem je često posmatrala svoje roditelje i pitala se u čemu je tajna njihove pažnje i mira koji se osjeti čim se prekorači njihov kućni prag. Shvatila je da porodica nije samo zajednički krov nad glavom, već sigurna tvrđava koju dvoje ljudi gradi s puno ljubavi i vjere u Allaha, dž.š.</p>\n                    <p>Danas ćemo, kroz Merjemina razmišljanja, otkriti zašto je brak u islamu mnogo više od običnog ugovora i zašto ga je naš Poslanik, alejhis-selam, nazvao \"polovinom vjere\". Naučit ćemo kako se postavljaju temelji za sretan život i kakvu ulogu imaju muž i žena u stvaranju toplog gnijezda koje nas vodi ka Allahovom zadovoljstvu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Čovjek je društveno biće koje se rađa i odrasta u porodici. Nakon što dostigne punoljetnost, dužnost čovjeka je da zasnuje svoju porodicu kojoj prethodi zasnivanje braka. Propisi islama od muslimana i muslimanki nalažu zasnivanje braka koji se temelji na Kur'anu i sunnetu Allahovog Poslanika.</p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: Udavajte neudate i ženite neoženjene, i čestite robove i robinje svoje; ako su siromašni, Allah će im iz obilja Svoga dati. Allah je neizmjerno dobar i sve zna. (En-Nur, 32)</p>\n                </div>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">Hadis</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Mladići! Ko od vas ima uvjeta da udovolji bračnim obavezama nek se oženi, jer je ženidba najbolje sredstvo da čovjek obori svoj pogled...” (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">Allahov poslanik Muhammed, alejhis-selam, je bio oženjen pa je brak ujedno i sunnet Muhammeda, alejhis-selam Osoba koja zasnuje brak imat će nagradu od Allaha, dž.š., zbog izvršavanja Njegove naredbe i također će imati nagradu za slijeđenje sunneta.</p>\n\n                <p class=\"lesson-text\">Brak prema šerijatskim propisima znači ženidbeni ugovor zaključen između dvije osobe suprotnog spola koje ispunjavaju i imaju uvjete za brak. Brak se zasniva njihovom slobodnom voljom, uz prisustvo dva svjedoka (muslimana muškarca ili jednog muškarca i dvije žene muslimanke), čime stječu pravo da žive u zajednici i dopuštenom intimnom odnosu. Shodno mišljenju islamskih učenjaka, brak može biti: farz, sunnet, mekruh i haram.</p>\n\n                <ul class=\"lesson-text\">\n                    <li>Brak je farz ‒ stroga dužnost osobi koja može izdržavati porodicu, a nije u stanju čuvati se bludnog i nemoralnog života.</li>\n                    <li>Brak je sunnet osobi koja ima uvjete za brak, a koja se može čuvati bludnog i nemoralnog života.</li>\n                    <li>Brak je mekruh osobi koja nije sigurna da će moći udovoljiti bračnim dužnostima.</li>\n                    <li>Brak je haram osobi koja je svjesna da neće moći udovoljiti bračnim dužnostima, (zbog nedostataka: materijalnih, fizičkih ili umnih).</li>\n                </ul>\n\n                <p class=\"lesson-text\">Sklapanje braka se obavlja u matičnim uredima, a nakon toga i pred imamom ‒ matičarem u medžlisu Islamske zajednice.</p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">Uloga i cilj bračne zajednice</p>\n                <p class=\"lesson-text\">Neki od ciljeva bračne zajednice su:</p>\n                <ul class=\"lesson-text\">\n                    <li>pokornost Allahovoj odredbi,</li>\n                    <li>usvajanje i slijeđenje sunneta Allahovog Poslanika,</li>\n                    <li>zbližavanje supružnika,</li>\n                    <li>osiguranje zajedničkog poroda,</li>\n                    <li>osiguranje zakonskih nasljednika,</li>\n                    <li>osiguranje moralnog života supružnika,</li>\n                    <li>odgajanje djece u islamu,</li>\n                    <li>materijalno zbrinjavanje porodice.</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('DUZNOSTI', this)\">\n                DUŽNOSTI U BRAKU <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"DUZNOSTI\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Prema islamskim propisima, sklapanjem braka muž i žena imaju svoje pojedinačne i zajedničke dužnosti.</p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">Dužnosti supruga u braku</p>\n                <ul class=\"lesson-text\">\n                    <li>da izdržava svoju suprugu shodno svojim materijalnim mogućnostima,</li>\n                    <li>da sa svojom suprugom postupa uljudno,</li>\n                    <li>da poštuje i čuva autoritet supruge,</li>\n                    <li>da što prije svojoj supruzi preda vjenčani dar,</li>\n                    <li>da ispunjava svoje obaveze koje je kao suprug dužan izvršavati,</li>\n                    <li>da se brine o ispravnom odgajanju i obrazovanju djece.</li>\n                </ul>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">Dužnosti supruge u braku</p>\n                <ul class=\"lesson-text\">\n                    <li>da čuva ugled i dostojanstvo svoga supruga,</li>\n                    <li>da čuva imetak svoga supruga i da ga ne rasipa,</li>\n                    <li>da savjesno obavlja svoje poslove kao supruga i majka,</li>\n                    <li>da izvršava svoje obaveze prema suprugu koje je dužna izvršavati,</li>\n                    <li>da vodi brigu o odgoju i obrazovanju svoje djece.</li>\n                </ul>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">Zajedničke dužnosti</p>\n                <ul class=\"lesson-text\">\n                    <li>da od prvih bračnih dana njeguju međusobnu ljubav, poštovanje i razumijevanje,</li>\n                    <li>da vode računa o svojim bračnim obavezama,</li>\n                    <li>da tokom čitavog bračnog života čuvaju i njeguju porodičnu intimu i toplinu,</li>\n                    <li>da svojoj djeci dadnu lijepa, islamska imena,</li>\n                    <li>da učestvuju u odgajanju i obrazovanju djece,</li>\n                    <li>da se međusobno podstiču na izvršavanje islamskih dužnosti,</li>\n                    <li>da jedno drugo pozivaju na dobro i odvraćaju od zla,</li>\n                    <li>da zajednički, prema mogućnostima, učestvuju u kućenju i materijalnom zbrinjavanju domaćinstva.</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('SMETNJE', this)\">\n                BRAČNE SMETNJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"SMETNJE\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Jedan od uvjeta za sklapanje braka je nepostojanje određenih smetnji koje se dijele na: 1. stalne i 2. privremene. U stalne smetnje se ubrajaju: srodstvo po krvi, mlijeku i tazbinstvu.</p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">Srodstvo po krvi</p>\n                <p class=\"lesson-text\">Osobe koje su u srodstvu po krvi ne mogu stupiti u bračnu zajednicu.</p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">Srodstvo po mlijeku</p>\n                <p class=\"lesson-text\">Pored srodstva po krvi, u trajne smetnje za sklapanje braka ubraja se i srodstvo po mlijeku.</p>\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: Zabranjuju vam se: matere vaše, i kćeri vaše, i sestre vaše i sestre očeva vaših, i sestre matera vaših i bratične vaše, i sestrične vaše. (En-Nisa, 23)</p>\n                </div>\n\n                <p class=\"lesson-text\">Žena koja je dojila tuđe dijete dok je bilo dojenče (u periodu od dvije godine), osim njegove majke, postaje mu majka po mlijeku. Srodstvo po mlijeku se proširuje i na dalje srodnike majke po mlijeku. Tako su:</p>\n                <ul class=\"lesson-text\">\n                    <li>njene kćeri i sinovi postali njegove sestre i braća po mlijeku,</li>\n                    <li>sva druga djeca koja su je zadojila postali su braća i sestre po mlijeku,</li>\n                    <li>njene sestre postaju njegove tetke po mlijeku,</li>\n                    <li>njezina majka postaje nana po mlijeku.</li>\n                </ul>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: ...i pomajke vaše koje su vas dojile i sestre vaše po mlijeku... (En-Nisa, 23)</p>\n                </div>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">Srodstvo po tazbinstvu</p>\n                <p class=\"lesson-text\">U trajne smetnje ubraja se i srodstvo po tazbinstvu koje nastaje prilikom udaje i ženidbe. Te osobe su spomenute u Kur'anu.</p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: ...i majke žena vaših, i pastorke vaše koje se nalaze pod vašim okriljem od žena vaših s kojima ste imali bračne odnose ‒ ali ako vi s njima niste imali bračne odnose, onda vam nije grijeh i žene vaših rođenih sinova... (En-Nisa, 23)</p>\n                </div>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">Privremene bračne smetnje</p>\n                <p class=\"lesson-text\">Privremene bračne smetnje se odnose na osobe s kojima je zbog postojanja nekog razloga zabranjeno sklapanje braka, pa kada nestane taj razlog, brak s tom osobom je dozvoljen. Privremene smetnje za sklapanje braka su:</p>\n                <ul class=\"lesson-text\">\n                    <li>Spojiti dvije sestre istovremeno u braku ‒ kada žena umre ili dođe do razvoda braka, dozvoljeno mu je sklopiti brak s njenom sestrom.</li>\n                    <li>Žena u iddetu ‒ period čekanja u kojem žena ne može sklopiti novi brak.</li>\n                    <li>Mnogoboškinja, Allah, dž.š., kaže: I ne ženite se mnogoboškinjama dok ne postanu vjernice... (El-Bekare, 221)</li>\n                    <li>Muškarac nemusliman ‒ sve dok ne prihvati islam.</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ISLAMSKI BRAK</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Šta je brak?</li>\n                    <li>Kome je brak farz, a kome haram?</li>\n                    <li>Koje su uloge bračne zajednice?</li>\n                    <li>Navedi zajedničke dužnosti u braku!</li>\n                    <li>Koje su stalne, a koje privremene smetnje za brak?</li>\n                    <li>Objasni srodstvo po mlijeku, kada nastupa i na koga se odnosi?</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":45,"is_published":true,"kviz_pitanja":[{"answer":"Ženidbeni ugovor između dvije osobe suprotnog spola","options":["Ženidbeni ugovor između dvije osobe suprotnog spola","Dozvola roditelja bez svjedoka","Samo želja mladića","Pisana potvrda od imama"],"question":"Šta je prema islamu preduslov za zasnivanje braka?"},{"answer":"Dva svjedoka","options":["Tri svjedoka","Četiri svjedoka","Dva svjedoka","Jedan svjedok"],"question":"Koliko svjedoka mora biti prisutno pri zasnivanju braka?"},{"answer":"Kada osoba ima mogućnost izdržavanja porodice","options":["Kada osoba ima mogućnost izdržavanja porodice","Kada su roditelji mlade osobe za to","Kada se živi u gradu","Kada osoba ima preko 30 godina"],"question":"Kada je brak farz - stroga dužnost?"},{"answer":"Allahin Poslanik Muhammed","options":["Hadrat Alija","Allahin Poslanik Muhammed","Hadrat Osmana","Hadrat Omera"],"question":"Ko je bio oženjen i postavio primjer o braku?"},{"answer":"U džamiji pred imamom-matičarem","options":["U džamiji pred imamom-matičarem","U kući neveste","U školi","U općini"],"question":"Gdje se nakon matičnog ureda obavlja sklapanje braka?"}]},{"nivo":3,"slug":"zenidba-udaja","naslov":"Ženidba i udaja","content_html":"<div class=\"lesson-container\">\n        <h1>ŽENIDBA I UDAJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/zenidba.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ženidba i udaja – izbor supružnika</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o važnosti pravilnog izbora bračnog druga</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti islamske kriterije za izbor supružnika</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti mlade za odgovorno donošenje bračnih odluka</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kad odrastete i razmišljate o braku — kako birati pravu osobu? Islam nam daje jasne kriterije.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanik, a.s.: \"Žena se uzima zbog četiri stvari: imetka, porijekla, ljepote i vjere. Izaberi onu koja je vjerna — bićeš sretan!\"</p><p>Glavni kriterij: <strong>vjera i ahlak</strong> — kod muškarca i kod žene.</p><p>Drugi kriteriji: poštenje, pamet, zdravlje, fizička kompatibilnost, slično porijeklo i obrazovanje.</p><p>Šta izbjegavati: izbor isključivo radi ljepote, novca, ili pritiska društva; brak bez upoznavanja u prisustvu mahrema; brak sa nemoralnom osobom.</p><p>Postupak: prosba (hitba) — gledanje budućeg supružnika u prisustvu mahrema, razgovor, istihara-namaz, savjet roditelja, donošenje odluke.</p><p>Roditelji imaju ulogu: pomažu, ne prisiljavaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome kakve kvalitete bi željeli kod budućeg supružnika. Zaključak: dobar izbor — sretan brak.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                KORACI KA ZAJEDNIČKOM ŽIVOTU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Započeti zajednički život s nekim koga volimo jedna je od najvažnijih odluka u životu. To nije samo trenutak slavlja, već putovanje koje zahtijeva iskrenost, upoznavanje i planiranje. Islam nas uči kako na častan i lijep način postaviti temelje bračne zajednice, poštujući dostojanstvo mladića i djevojke, ali i njihovih porodica.</p>\n                    <p>Danas istražiti obaveze koje imati mladić i djevojka prilikom upoznavanja i ciljeve tog procesa. Saznati šta značiti vjeridba, kako se odvijati čin ženidbe i udaje, te koje vrste mehra postojati kao vjenčani dar. Također naučiti o stavu islama prema razvodu braka kao krajnjem rješenju kada zajednički život postati nemoguć.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: Udavajte neudate i ženite neoženjene. (En-Nur, 32)</p>\n                </div>\n\n                <p class=\"lesson-text\">Jedna od dužnosti kojima su zaduženi punoljetni, pametni i zdravi muslimani i muslimanke, i koji pored navedenih uvjeta imaju i osnovnih materijalnih sredstava za život jeste stupanje u brak, odnosno ženidba i udaja.</p>\n\n                <p class=\"lesson-text\">Kada se dvije osobe, mladić i djevojka, zainteresiraju jedno za drugo s ciljem zasnivanja bračne zajednice, njihova obaveza je:</p>\n                <ul class=\"lesson-text\">\n                    <li>da se pridržavaju islamskog načina sastajanja i komuniciranja,</li>\n                    <li>da se upoznaju,</li>\n                    <li>da budu iskreni jedno prema drugom,</li>\n                    <li>da razmjenjuju svoja mišljenja i stavove,</li>\n                    <li>da razgovaraju o važnim životnim temama,</li>\n                    <li>da propituju narav jedno drugog.</li>\n                </ul>\n\n                <p class=\"lesson-text\">Cilj međusobnog upoznavanja mladića i djevojke je:</p>\n                <ul class=\"lesson-text\">\n                    <li>približavanje različitih stavova i mišljenja,</li>\n                    <li>usaglašavanje zajedničkog pogleda na život,</li>\n                    <li>planiranje bračne zajednice,</li>\n                    <li>zasnivanje porodice.</li>\n                </ul>\n\n                <p class=\"lesson-text\">Kada se usaglasi spomenuto, slijedi zasnivanje bračne zajednice uz obostrani pristanak i blagoslov ‒ dozvolu njihovih roditelja. Bračnoj zajednici prethodi vjeridba, a zatim građansko i šerijatsko vjenčanje.</p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">VJERIDBA</p>\n                <p class=\"lesson-text\">Vjeridba je po šerijatskim propisima preporučena, ali nije obavezna. Njena svrha je potvrđivanje ozbiljnih namjera o sklapanju braka, te bolje upoznavanje budućih mladenaca i njihovih porodica. Vjeridba se obično kruniše zarukom koja može biti određeni predmet (prsten) ili nešto drugo.</p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">ŽENIDBA I UDAJA</p>\n                <p class=\"lesson-text\">Ženidbom i udajom mladića i djevojke završavaju se njihovi samostalni životi, a istim činom počinje zajednički bračni život. Čin ženidbe i udaje naziva se svadba. To je svečanost koja podrazumijeva prelazak supruge, tj. mlade iz kuće njenih roditelja – staratelja u suprugovu kuću. Lijepo je da se svadba javno obznani i da što više ljudi sazna za njihovo sklapanje braka.</p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">VJENČANJE</p>\n                <p class=\"lesson-text\">Prilikom ženidbe i udaje obaveza mladenaca je da svoj brak potvrde vjenčanjem pred nadležnim državnim organom u matičnom uredu, a nakon toga trebaju obaviti i šerijatsko vjenčanje pred glavnim imamom ili osobom koja je ovlaštena za taj posao u prostorijama medžlisa ili džamije. Mladoženja nudi brak, a mlada prihvata ponuđeni brak. U toku vjenčanja ugovara se i mehr ‒ vjenčani dar koji mlada potražuje na dan vjenčanja. Postoje dvije vrste mehra:</p>\n                <ul class=\"lesson-text\">\n                    <li>mehru muadždžel ‒ prvi mehr, koji se daje odmah prilikom vjenčanja,</li>\n                    <li>mehru muedždžel ‒ drugi mehr, koji se daje u toku bračnog života, ili u slučaju razvoda braka ili smrti muža.</li>\n                </ul>\n\n                <p class=\"lesson-text\">Brak mladih osoba održiv je samo ukoliko supružnici budu ostvarivali svoja prava u braku i ako budu izvršavali svoje dužnosti.</p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">RAZVOD BRAKA</p>\n                <p class=\"lesson-text\">Prema islamskim propisima, razvod braka nije poželjan, ali je u opravdanim slučajevima dopušten.</p>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Od dozvoljenih stvari, najmrže djelo Allahu je razvod braka.” (Ebu Davud)\n                    </p>\n                </div>\n                <p class=\"lesson-text\">Ako supružnici nakon izvjesnog perioda zajedničkog života ne mogu živjeti zajedno niti ima nade da će se stanje u braku poboljšati, u tom slučaju dozvoljeno im je da se rastanu. Bolje im je da se u miru razvedu, nego da jedno drugom i ostalim članovima porodice zagorčavaju život.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ŽENIDBA I UDAJA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Koje obaveze imaju mladić i djevojka koji se upoznaju?</li>\n                    <li>Koji koraci prethode bračnoj zajednici?</li>\n                    <li>Šta je mehr i koje vrste mehra postoje?</li>\n                    <li>Je li u islamu dozvoljen razvod braka i u kojem slučaju?</li>\n                </ol>\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Opiši postupak šerijatskog vjenčanja – zaključenja braka. Obratite pažnju na sve činjenice koje se tom prilikom utvrđuju. Ukoliko nikada niste prisustvovali šerijatskom vjenčanju, zamolite muallima/muallimu da vam omogući prisustvo vjenčanju te da vam pomogne.</li>\n                    <li>Koji su to specifični običaji vjeridbe, udaje ili ženidbe muslimana u Bosni i Hercegovini, a bili su istaknuti posebno u ranijim vremenima? Razgovaraj s roditeljima i nastoj bilježiti i opisivati pojedinačne običaje!</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":46,"is_published":true,"kviz_pitanja":[{"answer":"Stupanje u brak","options":["Stupanje u brak","Putovanje u inozemstvo","Pohađanje škole","Rad cijeli život"],"question":"Šta je prema Qur'anu dužnost punoljetnih muslimana i muslimanki?"},{"answer":"Potvrđivanje ozbiljnih namjera o braku","options":["Potvrđivanje ozbiljnih namjera o braku","Obveza svih muslimana","Kupovanje poklona","Zabrana razgovora"],"question":"Koja je svrha vjeridbe prema šerijatskim propisima?"},{"answer":"Vjeridba","options":["Vjeridba","Put u inozemstvo","Izgradnja kuće","Rad cijelu godinu"],"question":"Što prethodi vjenčanju mladenika i mlade?"},{"answer":"Svadba","options":["Svadba","Igra","Putovanje","Rodjendan"],"question":"Kako se zove svečanost ženidbe i udaje?"},{"answer":"U suprugovu kuću","options":["U suprugovu kuću","U kuću svoje bake","Ostaje kod roditelja","U drugom gradu"],"question":"Gdje se mlada seli nakon ženidbe i udaje?"}]},{"nivo":3,"slug":"odijevanje-hidzab","naslov":"Kultura odijevanja, hidžab – smisao i značaj","content_html":"<div class=\"lesson-container\">\n        <h1>KULTURA ODIJEVANJA, HIDŽAB</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/hidzab1.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kultura odijevanja i hidžab</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ponosa na islamski način odijevanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti smisao i značaj hidžaba u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika pristojnog odijevanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta nosimo? Kako se oblačimo? Da li to ima veze sa našom vjerom? Da! Islam ima pravila o odijevanju.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Odijevanje u islamu nije samo izgled — to je čast, identitet i ibadet.</p><p><strong>Za muškarce</strong> — pokrivanje od pupka do koljena, ne nositi svilu, ne nositi žensku odjeću, izbjegavati uske ili providne stvari.</p><p><strong>Za žene</strong> — pokrivanje cijelog tijela osim lica i šaka pred ne-mahremima, odjeća nije uska niti providna, ne mirisanje pred strancima.</p><p><strong>Hidžab</strong> — više od marame; znači cijeli pristup pokrivanju, ali i ahlak, govor, ponašanje.</p><p>Smisao hidžaba: zaštita časti, izbjegavanje fitne, identitet vjernice, sloboda od pritiska modernog izgleda.</p><p>Allah u Kur’anu: \"O Vjerovjesniče, reci ženama svojim, kćerima svojim i ženama vjernika neka spuste haljine svoje niz tijela svoja...\"</p><p>Pristojnost se očekuje i od muškaraca i od žena — oboje obarjaju pogled, čuvaju jezik, pristojno se ponašaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o izazovima hidžaba u savremenom svijetu. Zaključak: hidžab je naš ponos i zaštita.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                MERJEMINA ODLUČNOST <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Jeste li ikada stajali ispred ogledala i pitali se koji je najbolji način da svijetu pokažete ko ste zapravo vi? Naša Merjem je danima razmišljala o tome. Gledala je svoju majku i stariju sestru kako s ponosom nose svoje mahrame, koje su izgledale poput najljepših kruna. Za Merjem, hidžab nije bio samo komad tkanine, već način da kaže: \"Ja pripadam Allahu i ponosna sam na svoju vjeru.\" Osjećala je da je to njen štit i njena sloboda.</p>\n                    <p>Danas ćemo, prateći Merjeminu priču, naučiti šta hidžab zapravo znači u islamu i koji su šerijatski uslovi za odijevanje muslimanke. Saznat ćemo kako se kroz historiju njegovala kultura pokrivanja i zašto hidžab predstavlja ponos, a ne prepreku. Kroz ove propise otkrit ćemo kako islamsko odijevanje čuva moral zajednice i uzdiže ženu na stepen poštovanja koji joj pripada.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: O Vjerovjesniče, reci ženama svojim, i kćerima svojim, i ženama vjernika neka spuste haljine svoje niza se. Tako će se najlakše prepoznati pa neće napastvovane biti. A Allah prašta i samilostan je. (El-Ahzab, 59)</p>\n                </div>\n\n                <p class=\"lesson-text\">Najvažniji preduvjet za sretan i uspješan život su vjera u Boga, odrastanje djece u lijepoj, zdravoj i harmoničnoj porodici i islamski odgoj. Djeca muslimana i muslimanki trebaju da budu lijepo odgojena, podučena islamskim propisima, te naviknuta na osnovni kodeks ponašanja u društvu i van njega. Posebnu pažnju treba posvetiti odgoju ženske djece koja pored ostalih moralnih vrlina trebaju imati posebno izraženo svojstvo stida. Kaže se: \"Stid je lijep, ali je još ljepši kada je kod žene.\"</p>\n\n                <p class=\"lesson-text\">Uzvišeni Allah je objavom Kur'ana propisao način ponašanja žene muslimanke. Pored ostalih dužnosti, njoj je propisan hidžab. Hidžab je način odijevanja žene muslimanke kojim se prekriva cijelo tijelo osim lica i šaka.</p>\n                \n                <p class=\"lesson-text\">Pored toga što je hidžab način odijevanja, on ima i simboličko značenje: čednosti, skromnosti, privatnosti i morala. Allah, dž.š., je ženi muslimanki naredio hidžab, stoga je hidžab odziv muslimanke na naredbu Uzvišenog Allaha. Muhammed, alejhis-selam, je svojim hadisima pojasnio koji dijelovi tijela kod žene trebaju biti pokriveni. Aiša, r.a., prenosi kako je jednom prilikom Esma, r.a., kćerka Ebu Bekra, r.a., ušla u prozirnoj odjeći kod Allahovog Poslanika, on se okrenuo u stranu i rekao: \"Esma, kada žena dostigne punoljetnost, nije dozvoljeno da otkrije bilo koji dio svog tijela osim ovog, a zatim pokaza na svoje lice i šake.\" (Ebu Davud)</p>\n\n                <p class=\"lesson-text\">Hidžab je sastavni dio vjerskih propisa o pristojnom odijevanju žene muslimanke, on je vanjski izraz njenog identiteta. Zato ne smije biti tijesan, kratak niti proziran.</p>\n                \n                <p class=\"lesson-text\">Islam je propisao hidžab kao dio pristojnosti i skromnosti u komunikaciji između osoba suprotnog spola. Žena muslimanka koja nosi hidžab ima preduvjete da se okiti lijepim svojstvom stida, što potvrđuje i izreka Omera, r.a.: \"Onaj ko se postidi, sakrit će se, onaj ko se sakrije pobojat će se, a onaj ko se poboji zaštitit će se.\"</p>\n\n                <p class=\"lesson-text\">Hidžab je zaštita žene od napadanja. On ženu usmjerava u pravcu čednosti i vjernosti svome suprugu, te joj čini zaštitu u svakodnevnom životu. Uzvišeni Allah je objavio: Tako će se najlakše prepoznati pa neće napastvovane biti. (El-Ahzab, 59)</p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Abdullah b. Abbas, r.a., je rekao: \"Allahov Poslanik, alejhis-selam, je prokleo muškarce koji oponašaju žene i žene koje oponašaju muškarce.\" (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">Odjeća je dar od Allaha, dž.š., zato je Allahov poslanik Muhammed, alejhis-selam, učio dovu: \"Hvala Allahu, Koji mi je dao lijepu odjeću da lijepo izgledam među ljudima i da pokrijem svoje stidno mjesto!\" (Ahmed)</p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Žena u svojoj porodici, ili u javnom životu, bila je i ostat će naša majka, sestra, supruga i kćerka. Zato treba da bude posebno poštovana i cijenjena.\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">RAZGOVOR S MUALLIMOM</p>\n                <ul class=\"lesson-text\">\n                    <li>Prvi februar se obilježava kao svjetski Dan hidžaba i u tom danu podsjećamo ženu muslimanku da je hidžab njena obaveza i njen spas i sreća.</li>\n                    <li>Allah, dž.š., nam je dao odjeću da bismo bili slobodniji i ljepši.</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - HIDŽAB</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je hidžab?</li>\n                    <li>Šta hidžab predstavlja za muslimanku?</li>\n                    <li>Od čega hidžab štiti muslimanku?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Stid je lijepa osobina koja treba da krasi svakog muslimana i muslimanku. Suprotno stidu je bestidnost u odijevanju, govoru, djelovanju i slično. Napiši u čemu se ogleda sloboda muslimanki kojima je hidžab propisan kao obaveza?</li>\n                    <li>Doima se da muslimanka nije slobodna, jer je hidžab obaveza. A hidžab joj daje mogućnost da sačuva svoju čednost i ljepotu za svoje ukućane. Napiši zašto hidžab ne dozvoljava izlaganje očima onih čiji pogledi mogu da naude.</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":47,"is_published":true,"kviz_pitanja":[{"answer":"Način odijevanja koji prekriva cijelo tijelo osim lica i šaka","options":["Način odijevanja koji prekriva cijelo tijelo osim lica i šaka","Samo šarena marama koju nose žene","Duga suknja sa cvijetnim uzorcima","Haljna koja se nosi samo na vjerskim praznicima"],"question":"Što je hidžab prema islamskom učenju?"},{"answer":"Čednost, skromnost, privatnost i moral","options":["Bogatstvo, moć i popularnost","Čednost, skromnost, privatnost i moral","Ljepotu, mladost i eleganciju","Moć, strahu i ozbiljnost"],"question":"Koja svojstva simbolizira hidžab kod žene muslimanke?"},{"answer":"Lice i šake","options":["Ruke, noge i glava","Samo lice i glava","Lice i šake","Sve osim trbuha"],"question":"Koji dijelovi tijela žene smiju biti otkriti prema hadisu?"},{"answer":"Za zaštitu, čednost i prepoznavanje vjernice","options":["Zbog hladnog vremena i bolesti","Jer su žene bile slabe","Za zaštitu, čednost i prepoznavanje vjernice","Jer su to htjeli njihovi očevi"],"question":"Zašto je Allah naredio hidžab ženama muslimanama?"},{"answer":"Tijesan, kratak ili proziran","options":["Tijesan, kratak ili proziran","Tamne boje ili jednostavne","Mek, topao ili udoban","Bez šara ili jednostavnog dizajna"],"question":"Kako hidžab ne smije biti prema islamskom učenju?"}]},{"nivo":3,"slug":"el-kariah","naslov":"Učenje sure El-Kari'ah","content_html":"<div class=\"lesson-container\">\n        <h1>UČENJE SURE EL-KARI'AH</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/karia.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure El-Kāri‘ah</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Kur’anu i razumijevanja poruke sure El-Kāri‘ah</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst, prijevod i osnovnu poruku sure El-Kāri‘ah (101. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da pravilno uči i koristi suru El-Kāri‘ah u namazu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, danas učimo suru El-Kāri‘ah. Ima 11 ajeta i objavljena je u Mekkai. Šta nas Allah uči u njoj?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura El-Kāri‘ah je 101. sura Kur’ana, ima 11 ajeta.</p><p>Objavljena je u Mekkai.</p><p>Glavna poruka: Allah opisuje smak svijeta — udaranje koje će izokrenuti ovaj poredak; lake i teške vage čovjekovih djela.</p><p>Pišem suru na tabli (arapski + transkripcija + prijevod).</p><p>Učenici slušaju izgovor (sa snimka), zatim ponavljaju ajet po ajet u horu i pojedinačno.</p><p>Razgovor o značenju i poruci za naš svakodnevni život.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče cijelu suru zajedno. Zadaća: usavršiti učenje sure napamet i znati njen prijevod.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":48,"is_published":true,"kviz_pitanja":[{"answer":"U Mekki","options":["U Medini","U Mekki","U Jerusalimu","U Egiptu"],"question":"Gdje je objavljena sura El-Kari'ah?"},{"answer":"11 ajeta","options":["9 ajeta","10 ajeta","11 ajeta","12 ajeta"],"question":"Koliko ajeta sadrži sura El-Kari'ah?"},{"answer":"Leptirima raštrkanih","options":["Zrnu pijeska","Leptirima raštrkanih","Zvijezdama na nebu","Kapljama vode"],"question":"Čemu će biti slični ljudi na Sudnjem danu?"},{"answer":"Boravište će mu bezdan biti","options":["Ući će u Raj","Živjeće ugodnom životom","Boravište će mu bezdan biti","Dobit će nagradu"],"question":"Šta će se desiti onom čija dobra djela budu lagana?"},{"answer":"Šarenoj vuni iščupanoj","options":["Čvrstom kamenju","Šarenoj vuni iščupanoj","Peskovitom pijesku","Gustoj magli"],"question":"Čemu će biti slične planine na Sudnjem danu?"}]},{"nivo":3,"slug":"odgovornost-zdravlje","naslov":"Odgovornost prema životu i zdravlju","content_html":"<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Odgovornost prema životu i zdravlju</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o životu kao Allahovom amanetu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamske propise o čuvanju života i zdravlja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje zdravih životnih navika</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, čiji je naš život? Naš ili Allahov? Allahov! On nam ga je dao kao amanet. Kako ga čuvati?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Život je Allahov dar — naša obaveza je čuvati ga, ne uništavati.</p><p>Allah u Kur’anu: \"I ne ubijajte sami sebe — Allah je doista milostiv prema vama.\"</p><p>Čuvanje života i zdravlja: zdrava ishrana, dovoljno sna, fizička aktivnost, izbjegavanje opasnosti (vožnja bez sigurnosti, ekstremni sport bez opreme), liječenje kad smo bolesni.</p><p>Zabranjeno: samoubistvo, eutanazija, sakaćenje tijela, droga, alkohol, prekomjerno gladovanje.</p><p>Mentalno zdravlje: učenje vjere (donosi smiraj), izbjegavanje pretjeranog stresa, dobro društvo, dova.</p><p>Razgovor: koje su moje zdrave/nezdrave navike?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na 2 zdrave navike ovaj tjedan. Zaključak: zdravo tijelo i duša — najbolji ibadet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->","audio_src":null,"redoslijed":49,"is_published":true,"kviz_pitanja":[{"answer":"Allahu je dato svemu onom što je stvorio ono što mu je potrebno","options":["Čini ono što ti se sviđa bez razmišljanja","Allahu je dato svemu onom što je stvorio ono što mu je potrebno","Nikada ne smiješ koristiti Allahove blagodati","Zdravlje je nevažno za muslimane"],"question":"Šta Allah, dž.š., kaže u ajetu iz sure Ta-Ha, 50?"},{"answer":"Naš život i zdravlje","options":["Samo naš novac i imovinu","Naš život i zdravlje","Samo naš izgled i odjeću","Samo naše knjige i igračke"],"question":"Koju od sljedećih stvari trebamo čuvati prema tekstnoj lekciji?"},{"answer":"Biti zahvalan i čuvati ih","options":["Trošiti ih bez razmišljanja","Biti zahvalan i čuvati ih","Dati ih svima bez iznimke","Nikad ih ne koristiti"],"question":"Koje su obaveze muslimana i muslimanke prema blagodatima života?"},{"answer":"Konzumiranje alkohola i droga","options":["Čuvanje se harama i zabrana","Zdravna ishrana i sport","Konzumiranje alkohola i droga","Održavanje čistoće tijela i mjesta"],"question":"Koji od ovih načina NIJE za čuvanje zdravlja?"},{"answer":"Metoda liječenja puštanjem krvi","options":["Vrsta hrane za zdravlje","Metoda liječenja puštanjem krvi","Vrsta namaza koji se obavlja","Tradicionalni odjevni predmet"],"question":"Šta je hidžama prema tekstualnoj lekciji?"}]},{"nivo":3,"slug":"rad-kultura","naslov":"Rad i radna kultura","content_html":"<div class=\"lesson-container\">\n        <h1>RAD I RADNA KULTURA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/rad.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Rad i radna kultura</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema radu i poštivanja tuđeg rada</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamski stav o radu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika urednosti, tačnosti i odgovornosti u radu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko volite raditi? Šta je vaš \"rad\" sad — učenje! A šta islam kaže o radu?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Rad u islamu je ibadet — ako se obavlja sa nijetom za halal opskrbu i korist drugima.</p><p>Poslanik, a.s.: \"Niko nije jeo bolju hranu od one koju je zaradio svojim rukama.\"</p><p>Vrste rada: fizički, intelektualni, kreativni — svi su časni ako su halal.</p><p>Radna kultura: tačnost, urednost, kvalitet, poštenje, briga za alate, poštovanje šefa i kolega.</p><p>Halal opskrba: poštena trgovina, plaćanje radnika na vrijeme, izbjegavanje kamate, prevare, krađe.</p><p>Lijenost je pokuđena. Poslanik je tražio od Allaha zaštitu od \"lijenosti i nemoći\".</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta je njihov \"rad\" danas. Zaključak: rad je čast, lijenost je sramota.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                GORNJA RUKA JE BOLJA OD DONJE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Da li ste ikada razmišljali o tome da li je bolje biti onaj koji prima pomoć ili onaj koji je pruža? Pobožnjak po imenu Šekik krenuo je na dug trgovački put, ali se vratio brže nego što je iko očekivao. Svom prijatelju Ibrahimu ispričao je čudnu scenu kojoj je prisustvovao u pustinji: vidio je slijepu i sakatu pticu kako nepomično stoji, a druga ptica joj je redovno donosila hranu. Šekik je tada zaključio: \"Ako Allah brine o ovoj ptici u pustinji, pobrinut će se i za mene bez mog truda!\"</p>\n                    <p>Međutim, Ibrahim mu je postavio pitanje koje je promijenilo njegov život: \"Zašto si izabrao da budeš slijepa ptica koja zavisi od tuđe pomoći? Zašto nisi htio da budeš ona druga ptica koja se trudi, pribavlja hranu i pomaže nemoćnima?\" Podsjetio ga je na važno pravilo – gornja ruka, ona koja daje i radi, bolja je od donje ruke koja samo prima. Danas ćemo naučiti zašto je rad u islamu najviši oblik ibadeta i kako radna kultura oblikuje našu odgovornost prema Allahu, dž.š., i ljudima oko nas.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I reci: \"Trudite se! Allah će trud vaš vidjeti, a i Poslanik Njegov i vjernici, i vi ćete biti vraćeni Onome koji zna nevidljivi i vidljivi svijet, pa će vas o onome što ste radili obavijestiti.\" (Et-Tevbe, 105)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Rad je ibadet, drago djelo Allahu, dž.š., a potreba za radom je urođena čovjekova osobina. Radom musliman i muslimanka nastoje osigurati sredstva sebi i svojoj porodici za život, zatim sredstva koja će im omogućiti da pomažu siromašne, svoju Zajednicu i šire društvo. Takav odnos prema radu ima vrijednost najvišeg ibadeta kojim se postižu Allahova, dž.š., milost i nagrada.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Muhammed, alejhis-selam, usmjerava pažnju svojih sljedbenika na važnost rada, trgovine, poljoprivrede i ostalih produktivnih vidova života. On lično je svojim životom oličenje požrtvovanosti i aktivnosti na putu postizanja halal-zarade za sebe i svoju porodicu. Još u ranoj mladosti svojim radom je doprinosio mnogobrojnoj porodici svog amidže Ebu Taliba kod kojeg je živio čuvajući stada imućnijih Mekelija. Kada je odrastao, počeo se baviti trgovinom, odlazeći u daleki Šam koji je od Mekke udaljen gotovo dvije hiljade kilometara. Poslanik islama je radio i pozivao sljedbenike svoga ummeta da rade i privređuju.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., nas je stvorio da se trudimo, jer bez truda i rada nema uspjeha ni na ovom ni na budućem svijetu - ahiretu. Radna kultura sastavni je dio naše odgovornosti prema Allahu, dž.š., ali i prema poslu kojim se bavimo i prema ljudima s kojima radimo. U radnu kulturu ubrajamo:\n                </p>\n\n                <ul class=\"lesson-text\">\n                    <li>moliti Allaha, dž.š., za uspjeh u poslu,</li>\n                    <li>na vrijeme doći na posao,</li>\n                    <li>biti vrijedan i aktivan u obavljanju povjerenih zadataka,</li>\n                    <li>voditi računa da posao obavimo temeljito i precizno,</li>\n                    <li>nastojati uraditi i više nego što smo zaduženi,</li>\n                    <li>na vrijeme izvršiti svaki zadatak,</li>\n                    <li>poštovati nadređene,</li>\n                    <li>biti na usluzi svojim radnim kolegama,</li>\n                    <li>lijepo i korektno se odnositi prema svakome na poslu itd.</li>\n                </ul>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">Hadis</span><br>\n                        Poslanik, alejhis-selam, je rekao: \"Nema bolje hrane od one koju čovjek pojede od rada svojih ruku.\" (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        \"Svaki musliman koji nešto posije ili posadi pa se od toga nahrani ptica, čovjek ili životinja, taj čin mu se smatra sadakom.\" (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">Zapamti!</span><br>\n                        Muhammed, alejhis-selam, je rekao: \"Allah voli da kada neko od vas radi neki posao da ga uradi temeljito.\" (Taberani)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - RAD I RADNA KULTURA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">Pitanja</p>\n                <ol class=\"lesson-text\">\n                    <li>Kako se rad tretira u islamu?</li>\n                    <li>Ko je najbolji primjer aktivnosti i požrtvovanosti za muslimane? Objasni!</li>\n                    <li>Šta podrazumijeva radna kultura?</li>\n                    <li>Koja je poruka priče o Šekiku i Ibrahimu?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">Zadatak</p>\n                <p class=\"lesson-text\">\n                    Neki mudrac je rekao da je dobro isplaniran posao završen do pola. Zato islam pridaje mnogo pažnje planiranju. Popunite tabelu dnevnih aktivnosti i nastojte je primjenjivati mjesec dana, a nakon toga napravite procjenu napretka koji ste ostvarili. Planirajte dovoljno vremena za rad i učenje, ali i zabavu i druženje. Precizno se držite planiranog rasporeda.\n                </p>\n\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":50,"is_published":true,"kviz_pitanja":[{"answer":"Da se trudimo i da će Allah vidjeti naš trud","options":["Da se trudimo i da će Allah vidjeti naš trud","Da ne radimo i samo se molimo","Da radimo samo za novac","Da ne pomagamo siromašnima"],"question":"Šta Allah, dž.š., kaže u ajetu iz Sure Et-Tevbe?"},{"answer":"Rad je ibadet i drago djelo Allahu","options":["Rad je ibadet i drago djelo Allahu","Rad je samo za bogate ljude","Rad je nešto loše i zabranjeno","Rad nije bitan u islamu"],"question":"Šta je rad prema islamu?"},{"answer":"Čuvao je stada imućnijih Mekelija","options":["Čuvao je stada imućnijih Mekelija","Nikada nije radio","Radio je samo kao učitelj","Radio je samo kao sudac"],"question":"Kako je Poslanik, alejhis-selam, radio u mladosti?"},{"answer":"Biti lijen i pasivan na poslu","options":["Biti lijen i pasivan na poslu","Moliti Allaha za uspjeh","Na vrijeme doći na posao","Biti vrijedan u obavljanju zadataka"],"question":"Koja od ovih radnji NIJE dio radne kulture?"},{"answer":"Nema bolje hrane od one zarade svojih ruku","options":["Nema bolje hrane od one zarade svojih ruku","Hrana koja se kupi je najbolja","Rad ne donosi dobru hranu","Samo bogati imaju dobru hranu"],"question":"Šta je rekao Poslanik, alejhis-selam, o hrani?"}]},{"nivo":3,"slug":"stjecanje-znanja","naslov":"Stjecanje znanja","content_html":"<div class=\"lesson-container\">\n        <h1>STJECANJE ZNANJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mekteb_znanje.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Stjecanje znanja</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema znanju i učenju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti vrijednost znanja u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Motiviranje učenika na stalno učenje</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, prva riječ Kur’ana bila je: \"Iqra’!\" — Čitaj! Šta to znači za nas? Učenje je naša obaveza.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah u Kur’anu uzdiže one koji znaju nad onima koji ne znaju.</p><p>Poslanik, a.s.: \"Traženje znanja je obaveza svakog muslimana i muslimanke.\"</p><p>Vrste znanja: <strong>fard ‘ajn</strong> (lično obavezno — vjera, abdest, namaz); <strong>fard kifaje</strong> (obaveza zajednice — medicina, inženjerstvo).</p><p>Vrijednost: melekī spuštaju krila pred onim ko traži znanje; ribe u moru moli za njega; kabur mu je svjetlost.</p><p>Postupak učenja: nijjet (radi Allaha, ne samo radi svjedočanstva), red, strpljivost, poštovanje učitelja, pomaganje drugima.</p><p>Najbolje znanje je ono koje vodi u dobro djelo.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta vole učiti. Zaključak: učenjem se diže čast i pred Allahom i pred ljudima.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                MOĆ UČENJA I SPOZNAJE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n            <p>Jeste li ikada hodali kroz šumu usred noći, pitajući se gdje se nalazi staza koja vodi kući? Naša Merjem se jednom našla u sličnoj situaciji kada je u cijelom naselju nestalo struje. Dok je sjedila u mraku, osjećala je nesigurnost jer nije mogla vidjeti ništa oko sebe. Ali, čim je njena majka upalila malu svijeću, cijela soba se promijenila – mrak je nestao, a Merjem je ponovo vidjela svaki predmet i siguran put do svojih knjiga. Tada je shvatila da je znanje za naš život upravo ono što je ta svijeća bila za mračnu sobu.</p>\n            <p>Danas ćemo, kroz Merjeminu radoznalost, istražiti zašto je prva objava Kur’ana počela upravo naredbom o čitanju i učenju. Saznat ćemo kako nam znanje pomaže da jasnije vidimo svijet oko sebe i zašto nas svaki naučeni harf ili lekcija čine jačima i boljima. Otkrit ćemo zašto islam učenje smatra putovanjem koje traje cijeli život i kako nas ta staza znanja, korak po korak, vodi ka Allahovom zadovoljstvu i Džennetu.</p>\n        </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: Čitaj, u ime Gospodara tvoga koji stvara. Stvara čovjeka od ugruška! Čitaj, plemenit je Gospodar tvoj, koji poučava peru, koji čovjeka poučava onome što ne zna. (El-Alek, 1-5)</p>\n                </div>\n\n                <p class=\"lesson-text\">Prve kur’anske riječi objavljene Muhammedu, alejhis-selam, odnosile su se na čitanje, učenje i stjecanje znanja. Nabrojano su odlike koje jedino čovjek može izvršavati i s tim je uzdignut iznad svih ostalih stvorenja. Čovjek može vjerovati i bez znanja, ali je takvo vjerovanje često stranputica. Samo istinskim znanjem čovjek može shvatiti pravi smisao vjerovanja i ovog prolaznog života na dunjaluku.</p>\n                \n                <p class=\"lesson-text\">Slijedeći prvu objavu, muslimani i muslimanke su dužni oplemeniti svoju dušu znanjem i lijepim ponašanjem. Znanje ima veliku motivacijsku snagu na ponašanje i djelovanje, ali u isto vrijeme podrazumijeva i čovjekovu odgovornost. Stečeno znanje se primjenjuje u praksi i postupa po njemu, ali pomoću njega i druge upućuje na dobro, a odvraća od zla. Također, stečeno znanje musliman je dužan da prenosi drugim ljudima. Uzvišeni Allah prvom objavom naređuje Ikre’ – čitanje – učenje, studiranje, uvećavanje znanja, neprestano do kraja života. Nažalost, današnji muslimani su zanemarili ovu kur’ansku naredbu, pa zaostaju u pismenosti širom svijeta.</p>\n                <img src=\"/edu/assets/images/ucenje2.jpg\" style=\"float: left; width: 250px; margin-right: 10px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">Posebno je važno koristiti mladost za učenje. Jedna mudrost kaže da je učenje u mladosti kao klesanje u kamenu, ono ostaje do kraja života da nam pomaže u svim životnim situacijama.</p>\n\n                <p class=\"lesson-text\">Allah, dž.š., i na drugim mjestima u Kur’anu potencira znanje i vrijednost učenih ljudi. Uzvišeni Allah pita i skreće našu pažnju na vrijednost učenih:</p>\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">On daruje znanje onome kome On hoće, a onaj kome je znanje darovano – darovan je blagom neizmjernim. A shvatiti mogu samo oni koji su razumom obdareni. (El-Bekare, 269)</p>\n                </div>\n\n                <p class=\"lesson-text\">Uzvišeni Allah nas poučava dovi i naređuje nam da je učimo kako bismo povećali svoje znanje. Allah, dž.š., kaže: ...i reci: “Gospodaru moj, Ti znanje moje proširi!” (Ta-Ha, 114)</p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\" style=\"background-color: #fff9c4; display: inline-block;\">HADIS</span><br>\n                        Traženje znanja Muhammed, alejhis-selam, opisuje kao put prema Džennetu. Poslanik, alejhis-selam, kaže: “Ko god traži da upotpuni svoje znanje, Allah mu olakša put do Dženneta.” (Muslim)\n                    </p>\n                </div>\n\n                <div class=\"info-box\" style=\"background-color: #fff9c4;\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span class=\"section-subtitle\">ZAPAMTI!</span><br>\n                        Cjeloživotna je obaveza stjecati znanje koje koristi njegovom nositelju, a preko njega svim ljudima, i ona podrazumijeva odricanje, rad, trud, strpljivost i žrtvu.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - STJECANJE ZNANJA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol>\n                    <li class=\"lesson-text\">Koja je prva naredba čovjeku od Allaha, dž.š.?</li>\n                    <li class=\"lesson-text\">Kakva je uloga znanja u životu muslimana?</li>\n                    <li class=\"lesson-text\">Koje je najbolje životno doba za učenje?</li>\n                    <li class=\"lesson-text\">Šta je cjeloživotno obrazovanje?</li>\n                    <li class=\"lesson-text\">RAZGOVOR: Okvirno isplaniraj svoj put kroz obrazovanje. Koje discipline te zanimaju i kojim poslom imaš namjeru da se baviš?</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":51,"is_published":true,"kviz_pitanja":[{"answer":"Čitaj, u ime Gospodara tvoga koji stvara","options":["Čitaj, u ime Gospodara tvoga koji stvara","Vjeruj u jednoga Allaha","Obavlja namazu pet puta dnevno","Dajem ti Desetericu zakona"],"question":"Šta je bila prva objava Muhammedu, alejhis-selam?"},{"answer":"U mladosti, jer znanje ostaje do kraja","options":["U starosti kada imaš iskustvo","U mladosti, jer znanje ostaje do kraja","Samo tijekom školskog vremena","Kada postaneš odrasla osoba"],"question":"Prema lekciji, kada je najbolje vrijeme za učenje i stjecanje znanja?"},{"answer":"Allah daruje znanje onome kome On hoće","options":["Znanje je samo za bogatashe","Allah daruje znanje onome kome On hoće","Žene ne trebaju znanje","Znanje se stiče samo iz knjiga"],"question":"Šta Allah nalaže u Sure El-Bekare o znanju?"},{"answer":"Prema Džennetu","options":["Prema bogatstvu i slavi","Prema Džennetu","Prema svjetskoj moći","Prema poznatosti među ljudima"],"question":"Po hadisu, traženje znanja je put prema čemu?"},{"answer":"Primjenjivati ga i prenositi drugima","options":["Čuvati ga za sebe","Primjenjivati ga i prenositi drugima","Prodavati ga skupo","Skrivati ga od neznalica"],"question":"Koja je dužnost muslimana prema stečenom znanju?"}]},{"nivo":3,"slug":"roditelji","naslov":"Poslušnost i briga prema roditeljima","content_html":"<div class=\"lesson-container\">\n        <h1>POSLUŠNOST I BRIGA PREMA RODITELJIMA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/roditelji.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Poslušnost i briga prema roditeljima</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje duboke ljubavi i poštovanja prema roditeljima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamske propise o pravima roditelja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika svakodnevnog dobročinstva prema roditeljima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko su naši najbliži? Roditelji. A šta su sve oni za nas? Allah je njihova prava posebno naglasio.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah u Kur’anu: \"I Gospodar tvoj zapovijeda da samo Njemu ibadet činite i da roditeljima dobročinstvo iskazujete.\"</p><p>Poslušnost roditeljima — odmah poslije pokornosti Allahu (osim u grijehu).</p><p>Naše obaveze: pažljivo ih slušati, ne dizati glas, ne reći im \"uf!\", brinuti se kad ostare, obilaziti ih, učiti dovu za njih, davati im sadaku.</p><p>Posebno majka: Poslanik, a.s., je tri puta rekao \"Tvoja majka\", pa onda \"Tvoj otac\" (kad ga je čovjek pitao kome najviše dobra činiti).</p><p>Džennet je pod nogama majki — ko zadovolji majku, zadovoljio je Allaha.</p><p>Dova za roditelje: <em>\"Rabbi-rhamhumā kemā rabbejānī sagīrā.\"</em></p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na 1 dobro djelo prema roditeljima ovaj dan. Učimo dovu zajedno.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NAJSIGURNIJA LUKA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Jeste li ikada razmišljali o tome ko vas je volio i prije nego što ste se rodili, ko je bdio nad vašim snom i čija je ruka uvijek bila tu da vas pridrži kada padnete? Naša Merjem je jednog popodneva posmatrala svoje roditelje i shvatila da su oni njena najsigurnija luka. Sjetila se svih onih noći kada je bila bolesna, a majka nije sklapala oči, i svih onih dana kada je otac radio s osmijehom samo da bi njoj bilo lijepo. Merjem je tada spoznala da je Allah, dž.š., u srca roditelja spustio dio Svoje neizmjerne milosti.</p>\n                    <p>Danas ćemo naučiti zašto se dobročinstvo prema roditeljima smatra jednim od najvrjednijih djela u islamu. Otkrit ćemo kako su poslanici i dobri ljudi pazili svoje majke i očeve, te zašto naša poslušnost i pažnja prema njima nikada ne prestaju. Kroz priče i hadise otkrit ćemo kako izgraditi odnos pun poštovanja koji će nam otvoriti vrata Dženneta.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL_1', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL_1\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: Mi smo naredili čovjeku da bude poslušan roditeljima svojim. Majka ga nosi, a njeno zdravlje trpi, i odbija ga u toku dvije godine. Budi zahvalan Meni i roditeljima svojim, Meni će se svi vratiti. (Lukman, 14)</p>\n                </div>\n\n                <p class=\"lesson-text\">Kada bi nas neko upitao: ko vas najviše voli, ko je sretan kada ste vi sretni i tužan kada ste vi tužni, ko je brižan kada ste bolesni i ko je zabrinut kada niste tu, ko vam je svoj život posvetio i ko vas je najviše poželio? Bez sumnje bi naš zajednički odgovor bio da su to naši roditelji. Roditelji su nama najbliže i najdraže osobe, Allahovom voljom, od njih smo postali, jer su nas rodili, oni nas paze i njeguju, pomažu i bodre, na njih se oslanjamo, najviše nas vole i zato im najviše dugujemo.</p>\n                \n                <p class=\"lesson-text\">Roditelji i djeca su najpreči jedni drugima, oni paze na svoju djecu dok su djeca dužna slušati i poštovati svoje roditelje. Jedna od najljepših osobina karakternih ljudi je na dobročinstvo drugih uzvratiti još većim dobročinstvom. Posebno se na dobročinstvo roditelja treba uzvratiti daleko većim dobročinstvom jer su nam učinili neizmjerno dobro. Allah, dž.š., od djece zahtijeva da poštuju svoje roditelje, a naredio im je i da im poslušni budu.</p>\n\n                <p class=\"lesson-text\">Dobročinstvo prema roditeljima podrazumijeva svako dobro koje možemo učiniti prema njima. Roditelji ne traže mnogo, zahvalni su kada im se osmjehnemo, blagonaklono ih pogledamo, poljubimo ih i lijepo im se obratimo. Često smo u prilici činiti dobro drugim ljudima, međutim, nijedno dobročinstvo se ne može porediti s dobročinstvom prema roditeljima.</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('MAJKA', this)\">\n                MAJKA JE NAJPREČA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"MAJKA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Pripovijeda se da je Abdullah ibn Omer, r.a., bio kod Kabe, pa je primijetio čovjeka kako tavafi i na leđima nosi svoju majku. Čovjek mu se obrati: \"Abdullahu, sine Omerov: Šta misliš jesam li se ja odužio svojoj majci, vidiš, nosim je na leđima, da bi ona tavafila.\" \"Nisi, prijatelju moj, nisi joj se odužio ni za jedan porođajni bol\" - odgovori Abdullah ibn Omer. U spomenutom hadisu majka je spomenuta tri puta jer svoju djecu nosi, rađa i doji.</p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">Hadis</span><br>\n                        Ebu Hurejre, r.a., prenosi da je Allahovom Poslaniku, alejhis-selam, došao jedan čovjek i upitao ga: \"O Allahov Poslaniče! Ko je najpreči za moje lijepo druženje i ponašanje prema njemu? On reče: 'Tvoja majka.' Čovjek tada upita: 'Ko poslije nje?' 'Tvoja majka', odgovori on. 'Ko poslije nje?', ponovo upita čovjek. 'Tvoja majka', ponovo odgovori Poslanik, alejhis-selam Čovjek ponovo upita: 'Ko poslije nje?', a on tek tada reče: 'Tvoj otac.'\" (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">Allah, dž.š., kaže: Gospodar tvoj zapovijeda da se samo Njemu klanjate i da roditeljima dobročinstvo činite. Kad jedno od njih dvoje, ili oboje, kod tebe starost dožive, ne reci im ni: \"Uh\" - i ne podvikni na njih, i obraćaj im se riječima poštovanja punim. Budi prema njima pažljiv i ponizan i reci: \"Gospodaru moj, smiluj im se, oni su mene, kad sam bio dijete, njegovali.\" (El-Isra, 23-24)</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('DUZNOSTI', this)\">\n                DUŽNOSTI I BRIGA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"DUZNOSTI\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Briga o roditeljima je obaveza djece koja traje sve do kraja njihova života, a posebno treba da bude izražena u vremenu kada roditelji dožive svoju starost i iznemoglost. Pored pokornosti Uzvišenom Allahu, u ajetu su pobrojane dužnosti prema našim roditeljima. Dužnosti prema roditeljima su:</p>\n                <ul class=\"lesson-text\">\n                    <li>roditeljima dobročinstvo činiti,</li>\n                    <li>poslušan im biti tokom života, posebno kada starost dožive,</li>\n                    <li>obraćati im se riječima punim poštovanja, i</li>\n                    <li>činiti dovu Uzvišenom Allahu za svoje roditelje.</li>\n                </ul>\n\n                <p class=\"lesson-text\">Onog momenta kada naši roditelji presele s ovog svijeta ni tada ne prestaju naše dužnosti prema njima. Na upit jednog čovjeka o dobročinstvu prema roditeljima poslije smrti, Poslanik, alejhis-selam, odgovori: \"Da, uči im dovu i traži oprosta za njih, izvrši ono što su oporukom oporučili, posjećuj rodbinu koja se tiče samo njih i ugosti i na plemenit način postupaj prema njihovim prijateljima.\" (Ebu Davud)</p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">Razgovor s muallimom</span><br>\n                        Interesantno je kako jedna majka može brinuti o desetero svoje djeca, a njih desetero ne mogu brinuti o jednoj majci.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PRICA', this)\">\n                ZAPAMTI! (PRIČA O PEĆINI) <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PRICA\" class=\"lesson-content\">\n                <p class=\"lesson-text\">Abdullah ibn Omer prenosi kako su trojica ljudi putovali i sklonili se u jednu pećinu da se odmore. U vremenu njihovog boravka u pećini, stijena s drugog brda se skotrljala i zatvorila ulaz u pećinu u kojoj su se zatekli. Kada su ujutro krenuli da nastave put, nisu mogli izaći pa su molili Allaha, dž.š., da im pomogne u toj situaciji. Odlučili su da čine dovu Allahu, dž.š., a uz dovu spomenu najbolje djelo koje su učinili u životu.</p>\n                <p class=\"lesson-text\">Tako je jedan od njih spomenuo dobročinstvo prema svojim roditeljima i rekao: \"Moj Allahu, Ti znaš da sam ja imao stare i iznemogle roditelje i da sam im svake noći donosio mlijeko od svojih ovaca. Jedne večeri sam zakasnio, i kad sam došao, oni su već zaspali, a moja djeca su plakala od gladi. Stajao sam sve dok se nisu probudili da ih nahranim i tako dočekah zoru. Kada su se probudili, nahranio sam ih, a zatim sam nahranio svoju djecu. Gospodaru moj, Ti znaš da sam ja to uradio iz straha prema Tebi, pa ukloni stijenu s ulaza pećine.\"</p>\n                <p class=\"lesson-text\">I stijena se pomakla, ali ne toliko da izađu. Nakon njega dovu su činila i druga dvojica spomenuvši svoje najbolje djelo, pa je i njima Uzvišeni uslišao dovu, stijena se pomjerila i izašli su iz pećine nastavivši svoj put. (Buhari i Muslim)</p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - POSLUŠNOST RODITELJIMA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Šta podrazumijeva dobročinstvo prema roditeljima?</li>\n                    <li>Zašto je Poslanik, alejhis-selam, u hadisu tri puta spomenuo majku, pa onda oca?</li>\n                    <li>Koje su dužnosti prema roditeljima?</li>\n                    <li>Smrt roditelja je teška, a da li s njom prestaju i obaveze prema njima?</li>\n                    <li>Kakav odnos treba da vlada prema roditeljima od onog trenutka kad musliman i muslimanka zasnuju svoju porodicu?</li>\n                    <li>ZADATAK: Razmisli i napiši čija prava su preča, roditeljska ili prava supružnika, i kako uskladiti njihovo izvršavanje?</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":52,"is_published":true,"kviz_pitanja":[{"answer":"Da bude poslušan i brizan prema njima","options":["Da bude poslušan i brizan prema njima","Da im daje samo novac","Da ih posjećuje samo subotama","Da im se javno protivi"],"question":"Šta Allah nareduje čovjeku prema roditeljima?"},{"answer":"Dvije godine","options":["Dvije godine","Tri godine","Četiri godine","Godinu dana"],"question":"Koliko godina majka nosi dijete prema Kuranu?"},{"answer":"Mnogo stvari i luksuz","options":["Osmijeh, lijepu reč i poljubac","Mnogo stvari i luksuz","Poštovanje i poslušnost","Brigu i ljubav"],"question":"Što roditelji ne traže od svoje djece?"},{"answer":"Nisi se odužio ni za jedan porođajni bol","options":["Nisi se odužio ni za jedan porođajni bol","Odužio si se svojoj majci","Trebao si je nositi ranije","Zadovoljio si je dovoljno"],"question":"Šta je Abdullah ibn Omer rekao čovjeku koji nosi majku?"},{"answer":"Tri puta jer nosi, rađa i doji","options":["Tri puta jer nosi, rađa i doji","Dva puta jer rađa i doji","Pet puta zbog njene važnosti","Samo jednom na početku"],"question":"Koliko puta je majka spomenuta u hadisu?"}]},{"nivo":3,"slug":"rodbinske-veze","naslov":"Čuvanje rodbinskih veza","content_html":"<div class=\"lesson-container\">\n        <h1>ČUVANJE RODBINSKIH VEZA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/rodbina.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Čuvanje rodbinskih veza (silaturahim)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema rodbini i čuvanja porodičnih veza</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam silaturahima i njegove vrijednosti</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike posjećivanja i pomaganja rodbini</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je rodbina? Daidže, tetke, amidže, dede, nene, rođaci... Šta islam kaže o vezi sa njima?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Silaturahim — održavanje veza sa rodbinom; jedna od najvažnijih dužnosti muslimana.</p><p>Poslanik, a.s.: \"Ko želi opskrbu i dug život — neka održava veze sa rodbinom.\"</p><p>Naše dužnosti: posjećivati, čestitati Bajram, pomoći u nevolji, pomiriti svađe, obići bolesnog, prisustvovati dženazi i svadbama.</p><p>Prekidanje veza (kit‘a-rahim) je veliki grijeh — Allah ne prima djela onoga ko prekida vezu sa rodbinom.</p><p>Posjete ne moraju biti česte — telefonski poziv, poruka, finansijska pomoć — sve je silaturahim.</p><p>Posebno: djeca koja su ostala bez roditelja — naša naročita briga.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici planiraju jedan poziv ili posjetu rodbini. Zaključak: silaturahim donosi bereket.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                MOSTOVI KOJI NAS SPAJAJU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da gradite jedan veliki, snažan most koji povezuje mnogo različitih ostrva u jedno prelijepo kraljevstvo. Naša Merjem je shvatila da je svaki put kada posjeti tetku, amidžu ili se igra sa svojim rođacima, zapravo dodala jednu čvrstu ciglu tom nevidljivom mostu ljubavi. Bez tih veza, mi bismo bili kao usamljena, tužna ostrva, ali s njima smo dio velike i snažne porodice koja nas uvijek podržava.</p>\n                    <p>Danas ćemo, kroz Merjemine doživljaje, istražiti zašto se održavanje rodbinskih veza izjednačava s našom vezom s Uzvišenim Allahom. Saznat ćemo ko sve čini našu širu rodbinu i kako svakodnevnim sitnicama, poput zajedničke igre ili posjete tokom odmora, možemo zaslužiti Allahovo zadovoljstvo. Naučit ćemo da svaki trenutak proveden u krugu rodbine donosi bereket u naš život i otvara nam puteve radosti koje nismo mogli ni zamisliti.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I Allahu se klanjajte i nikoga Njemu ravnim ne smatrajte, a roditeljima dobročinstvo činite, rođacima, siročadi... (En-Nisa, 36)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Ranije smo naučili da razlikujemo užu i širu porodicu i ko se ubraja u užu a ko u širu porodicu. Pored dobročinstva prema roditeljima, dužnost muslimana je da pazi i čuva svoju rodbinu. Posjećivanje i obilaženje rodbine je najbolji način čuvanja i održavanja rodbinskih veza. Pored naših roditelja, braće i sestara, u rodbinu se ubrajaju i djedovi i nane te braća i sestre naših roditelja, tetke, daidže i amidže i njihova djeca. Čuvanje rodbinskih veza jedna je od posebno važnih vjerničkih dužnosti koja je naređena Kur'anom, u hadisi-kudsijima Allaha, dž.š., i u hadisima Muhammeda, alejhis-selam\n                </p>\n\n                <p class=\"lesson-text\">\n                    Muhammed, alejhis-selam, je prenio da je Allah, dž.š., rekao: \"Ja sam Milostivi, Ja sam stvorio rodbinske veze i izveo ih iz Svog imena, pa ko ih održava i Ja ću s njim vezu održavati, a ko ih prekida i Ja ću s njim vezu prekinuti.\" (Tirmizi) Iz ovog hadisa učimo sljedeće:\n                </p>\n\n                <ul class=\"lesson-text\">\n                    <li>održavanje rodbinskih veza je izjednačeno s održavanjem veze s Uzvišenim Allahom, koja će donijeti dobro i ovoga i budućega svijeta,</li>\n                    <li>prekidanje rodbinskih veza izjednačeno je s prekidanjem veze s Allahom, dž.š., koje odnosi mnoge životne vrijednosti.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Čuvanje rodbinskih veza važno je zbog njegovanja međurodbinske ljubavi, koja nastaje u vremenu djetinjstva. Zato je važno da u toku djetinjstva sa svojim roditeljima posjećujemo rodbinu i da se upoznajemo s njihovom djecom. Da bi se djeca rođaka voljela i da bi ljubav među njima ostala, potrebno je činiti sljedeće:\n                </p>\n\n                <ul class=\"lesson-text\">\n                    <li>upoznati svoje rođake,</li>\n                    <li>što više vremena provoditi zajedno,</li>\n                    <li>družiti se i igrati,</li>\n                    <li>u toku odmora boraviti u gostima jedni kod drugih,</li>\n                    <li>pomagati se u školskim, mektebskim i drugim obavezama.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Čuvanje i održavanje rodbinskih veza donosi mnoge koristi, a između ostalih:\n                </p>\n\n                <ul class=\"lesson-text\">\n                    <li>zadovoljstvo Allaha, dž.š.,</li>\n                    <li>nagradu za slijeđenje sunneta,</li>\n                    <li>međurodbinsku komunikaciju,</li>\n                    <li>povećanje međurodbinske ljubavi,</li>\n                    <li>olakšavanje dunjalučkih poslova,</li>\n                    <li>lakše podnošenje iskušenja itd.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Rodbinske veze treba održavati i s rođacima koji ne uzvraćaju druženje i posjete. Prekidanje rodbinskih veza ima velike posljedice na ovome svijetu a posebno će biti teške posljedice na Sudnjem danu na što je upozoravao i Poslanik a.s.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - RODBINSKE VEZE</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA_BOX', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA_BOX\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Ko se pored roditelja ubraja u našu rodbinu?</li>\n                    <li>Kakve posljedice ima čuvanje, a kakve prekidanje rodbinskih veza?</li>\n                    <li>Koje su koristi čuvanja rodbinskih veza?</li>\n                    <li>Šta je održavanje rodbinskih veza prema hadisu Muhammeda, alejhis-selam?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">RAZGOVOR S MUALLIMOM</p>\n                <p class=\"lesson-text\">\n                    Prisjeti se nekih od najljepših trenutaka provedenih kod svojih rođaka. Opiši ih i pokušaj odgovoriti zašto je taj osjećaj bio takav, lijep i ugodan!\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Razgovaraj s roditeljima o rodbini koja vašu porodicu posjećuje rijetko ili nikako - dogovorite se da vi njih posjetite.</li>\n                    <li>Razgovaraj sa svojim djedom i nanom kakve su porodice nekada bile. Kako i koliko često se posjećivalo, te koliko su brojne porodice tada bile?</li>\n                    <li>Popuni tabelu članova svoje uže i šire porodice navodeći ih poimenično. U trećoj koloni zapiši kakav odnos tvoja porodica ima prema tom srodniku: - POZNAJEMO SE, - POSJEĆUJEMO SE, - VOLIMO SE.</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":53,"is_published":true,"kviz_pitanja":[{"answer":"Da trebamo dobročinstvo prema roditeljima i rođacima","options":["Da je rodbina važnija od roditelja","Da trebamo dobročinstvo prema roditeljima i rođacima","Da trebamo samo posjećivati djedove","Da rodbina nije bitna za vjeru"],"question":"Šta Allah, dž.š., kaže o čuvanju rodbinskih veza u ajetu En-Nisa 36?"},{"answer":"Djedovi, nane, tetke, daidže i amidže","options":["Samo braća i sestre","Djedovi, nane, tetke, daidže i amidže","Samo roditelji i djeca","Samo prijatelji i susjedi"],"question":"Koji su članovi šire porodice prema lekciji?"},{"answer":"Allah održava vezu s njim i donosi dobro","options":["Allah prekida vezu s njim","Allah održava vezu s njim i donosi dobro","Allah ga kažnjava u dunjaluku","Rodbina ga napušta zauvijek"],"question":"Šta se dešava ako nekog čuva rodbinske veze?"},{"answer":"Posjećivanje i obilaženje rodbine","options":["Razgovor po telefonu samo za blagdane","Posjećivanje i obilaženje rodbine","Pisanje pisama dva puta godišnje","Slušanje priča o rodbini od drugih"],"question":"Koja je najbolja aktivnost za održavanje rodbinskih veza?"},{"answer":"Druženjem djece rodbine od djetinjstva zajedno","options":["Izbjegavanjem rodbine kada je moguće","Druženjem djece rodbine od djetinjstva zajedno","Govorenjem samo o veri bez igre","Čuvanjem djece kod kuće bez posjetiteljstva"],"question":"Kako se međurodbinska ljubav najbolje njeguje?"}]},{"nivo":3,"slug":"komsije","naslov":"Dužnosti prema komšijama","content_html":"<div class=\"lesson-container\">\n        <h1>DUŽNOSTI PREMA KOMŠIJAMA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/komsije.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dužnosti prema komšijama</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i odgovornosti prema komšijama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamske propise o pravima komšija</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika dobrog komšijstva</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko su nam najbliži ljudi nakon porodice? Komšije! Šta islam kaže o njima?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanik, a.s.: \"Stalno mi je Džibril preporučivao komšiju toliko da sam mislio da će ga učiniti naslednikom.\"</p><p>Vrste komšija: <strong>1.</strong> Komšija sa pravom Islama i rodbine (musliman i rodbina), <strong>2.</strong> Komšija sa pravom Islama (musliman), <strong>3.</strong> Komšija sa pravom komšiluka (čak i nemusliman).</p><p>Naše dužnosti: pozdraviti, pomoći, obići bolesnog, čestitati radost, izraziti saučešće u tuzi, ne uznemiravati bukom, dijeliti hranu.</p><p>Loše prema komšiji: glasna muzika, parkiranje pred njegovim vratima, ogovaranje, krađa.</p><p>Poslanik, a.s.: \"Nije vjernik onaj čije komšije nisu sigurne od njegovog zla.\"</p><p>Razgovor: kako se ponašate prema svojim komšijama?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju da pozdrave komšiju ili pomognu mu. Zaključak: dobar komšija — bereket u kući.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":54,"is_published":true,"kviz_pitanja":[{"answer":"Komšije","options":["Komšije","Rođaci","Prijatelji","Učitelji"],"question":"Kako se nazivaju osobe koje žive blizu naše kuće ili ulice?"},{"answer":"Poštovati ih i pozdraviti","options":["Poštovati ih i pozdraviti","Izbjegavati ih","Ignorisati ih","Biti grubi prema njima"],"question":"Šta trebamo učiniti starije komšije pri susretu?"},{"answer":"En-Nisa, 36","options":["En-Nisa, 36","El-Fatiha, 1","Jaseen, 82","En-Nahl, 90"],"question":"Koje sura i ajet govore o dobročinstvu prema komšijama?"},{"answer":"Onaj koji se najljepše odnosi prema komšiji","options":["Onaj koji se najljepše odnosi prema komšiji","Najstariji komšija","Najbogatiji komšija","Komšija koji je sam"],"question":"Ko je najbolji od svih komšija po Poslaniku, alejhis-selam?"},{"answer":"Pomognemo mu","options":["Pomognemo mu","Odbijemo ga","Pozovemo druge","Ignore"],"question":"Šta trebamo činiti kada nam komšija zatraži pomoć?"}]},{"nivo":3,"slug":"prijateljstvo","naslov":"Prijateljstvo i drugarstvo","content_html":"<div class=\"lesson-container\">\n        <h1>PRIJATELJSTVO I DRUGARSTVO</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/prijateljstvo.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Prijateljstvo i drugarstvo</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti pravilnog izbora prijatelja i čuvanja prijateljstva</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamski stav o prijateljstvu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika dobrog drugarstva</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koga zovete prijateljem? Šta čini dobrog prijatelja? Da li su svi prijatelji isti?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanik, a.s.: \"Čovjek je na dini svog prijatelja — neka svako pažljivo bira sa kim se druži.\"</p><p>Dobar prijatelj: vodi te ka Allahu, čuva tvoju tajnu, opominje te kad griješiš, raduje se tvojoj sreći, tuguje za tvojom tugom.</p><p>Loš prijatelj: vodi te u grijeh, ogovara te, koristi te, navodi na lošu naviku.</p><p>Vrijednost dobrog prijatelja: Poslanik, a.s.: \"Najbolji prijatelj je onaj koji te kad ga vidiš, podsjeti na Allaha.\"</p><p>Naše obaveze prema prijatelju: lojalnost, čuvanje tajne, pomoć, oprost, iskrenost.</p><p>Allah u Kur’anu: \"Bliski prijatelji na taj dan biće jedni drugima neprijatelji — osim onih koji su se Allaha bojali.\"</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o svojim prijateljima. Zaključak: bolje malo dobrih nego mnogo loših prijatelja.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":55,"is_published":true,"kviz_pitanja":[{"answer":"Imati prijatelje","options":["Imati bogatstvo i moć","Imati prijatelje","Biti sam cijeli dan","Putovati po svijetu"],"question":"Šta je urođena potreba svakog čovjeka prema lekciji?"},{"answer":"U vrtiću, mektebu ili školi","options":["Na poslu","U vrtiću, mektebu ili školi","U bolnici","Na pijacu"],"question":"Gdje prvi put upoznajemo svoje drugare i prijatelje?"},{"answer":"Primjerom mirisa i kovača","options":["Primjerom vode i boje","Primjerom mirisa i kovača","Primjerom stabla i voća","Primjerom sunca i mjeseca"],"question":"Kojim primjerom Muhammed, alejhis-selam, prikazuje utjecaj prijatelja?"},{"answer":"Na iskrenosti, praštanju i povjerenju","options":["Na bogatstvu i zlatu","Samo na zabavi i igrama","Na iskrenosti, praštanju i povjerenju","Na lažima i prevari"],"question":"Na čemu treba biti zasnovano prijateljstvo među ljudima?"},{"answer":"Laž, prevaru, nasilje i loše navike","options":["Znanje i mudrost","Lijep miris","Laž, prevaru, nasilje i loše navike","Ponos i pravdu"],"question":"Što loš prijatelj prenosi na svog pratioca?"}]},{"nivo":3,"slug":"stariji","naslov":"Poštivanje starijih","content_html":"<div class=\"lesson-container\">\n        <h1>POŠTIVANJE STARIJIH</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/briga_stariji.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Poštivanje starijih</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje poštovanja prema starijima i mudrosti njihovog iskustva</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamski stav o pravima starijih</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika poštovanja i pomaganja starijima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako se ponašate prema dedi i neni? A prema starijim ljudima na ulici? Islam ima jasne propise.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanik, a.s.: \"Nije od nas onaj ko se ne smiluje našim mladima i ne poštuje naše starije.\"</p><p>Naše obaveze: ustati pri njihovom dolasku, pustiti im da prvi govore, dati im najbolja mjesta, pomoći im, slušati njihove savjete.</p><p>Kod kuće: ne dizati glas pred starijima, donositi im stvari, pomoći im sjesti i ustati, posjetiti ih.</p><p>U džamiji: ustupiti im mjesto u prvim safovima, ne pretjecati ih.</p><p>Stariji su naša mudrost — iskustvo koje knjige nemaju. Slušati ih znači učiti.</p><p>Razgovor: kako pomažem dedi/neni? Kako se ponašam prema starijima u komšiluku?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na 1 dobro djelo prema starijem ovaj dan. Zaključak: poštovati stare = blagoslov u životu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                DRAGOCJENO ISKUSTVO <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da sjedite pored starog drveta koje je preživjelo stotine oluja i sunčanih dana, a svaka njegova grana priča neku važnu priču. Naša Merjem je shvatila da su stariji ljudi u njenom okruženju baš poput tog drveta – njihovo lice možda ima bore, a korak im je sporiji, ali u sebi nose blago koje se ne može kupiti novcem, a to je životno iskustvo. Kada god Merjem pomogne baki s kesama iz prodavnice ili pažljivo sasluša dedine savjete, ona osjeća da postaje bogatija za jednu veliku životnu lekciju o poštovanju i dobroti.</p>\n                    <p>Danas ćemo istražiti zašto nas naš Poslanik, alejhis-selam, uči da onaj ko ne poštuje starije ne pripada njegovom ummetu. Saznat ćemo kako jedan mali gest, poput ustupanja mjesta u autobusu ili toplog pozdrava, može donijeti ogroman blagoslov u naš život. Naučit ćemo konkretne načine kako se ponašati prema onima koji su nas zadužili svojim znanjem i godinama, te zašto je poštivanje starijih zapravo ogledalo naše vlastite plemenitosti i vjere.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: \"Ko ne bude milostiv prema mlađima i ne bude poštovao starije i priznavao pravo učenih ne pripada nama.\" (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Poštivanje starijih i međusobno uvažavanje čini životnu sredinu ugodnom i oplemenjuje porodični i društveni ambijent. Kontakt između ljudi različitih dobi vrlo često rezultira nesporazumima i svađama. Zlatno je pravilo postavio Muhammed, alejhis-selam, upućujući nas na najbolje rješenje da budemo milostivi prema mlađima i poštujemo starije.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ovaj vjerski princip nas obavezuje da postupajući po njemu poštujemo starije i on važi za sva vremena i sve generacije.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Svako udaljavanje od lijepog ponašanja i poštivanja starijih rezultira lošijim stanjem u samoj porodici. Interesantno je da je ovo stanje Poslanik, alejhis-selam, najavio kao mali predznak Sudnjeg dana. Muhammed, alejhis-selam, je rekao:\n                </p>\n\n                <p class=\"lesson-text\">\n                    \"Neće nastupiti Kijametski dan sve dok: djeca ne postanu srdita (ljuta), kiša ne bude vruća i topla, poveća se broj nevaljalih i nepoštenih, smanji se broj plemenitih ljudi, mlađi se (bespravno i neuljudno) usprotive starijima, a nevaljali i nepošteni se usprotive plemenitim ljudima.\" (Taberani)\n                </p>\n\n                <p class=\"lesson-text\">\n                \tDužnost svakog muslimana i muslimanke je da poštuju i uvažavaju starije osobe, učene, one koji su na položaju i sve one koji na neki način zaslužuju poštovanje.\n                </p>\n                \n                <p class=\"lesson-text\">\n                    Muhammed, alejhis-selam, nas praktično podučava ovim vrijednostima. Kada su muslimani oslobodili Mekku, među onima koji su došli da prihvate islam bio je i otac Ebu Bekra, r.a., oronuli starac zvani Ebu Kuhafe koji je lično došao do Muhammeda, alejhis-selam Tada Muhammed, alejhis-selam, reče Ebu Bekru: \"Zašto ga nisi pustio da sjedi u svojoj kući pa da mi odemo njemu,\" želeći time ukazati na poštivanje starijih.\n                </p>\n            <img src=\"/edu/assets/images/stariji1.jpg\" style=\"float: right; width: 250px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">\n                    Poštivanje starijih, zbog njihovih godina, iskustva i znanja je odlika vjernika i oni koji to ne prihvataju, nisu kompletni vjernici i ne postupaju po sunnetu Muhammeda, alejhis-selam Neki od postupaka koje ubrajamo u poštivanje starijih su:\n                </p>\n\n                <ul class=\"lesson-text\">\n                    <li>starije prvi selamimo, pozdravimo,</li>\n                    <li>u džamiji im ustupimo mjesto u prvim safovima,</li>\n                    <li>ako im je potrebna pomoć, pomognemo im,</li>\n                    <li>kad stariji govore, ne prekidamo ih nego pažljivo saslušamo,</li>\n                    <li>u sredstvima javnog prijevoza i na javnim mjestima ustupimo im mjesto da sjednu,</li>\n                    <li>ako se igramo, prekinemo igru dok stariji ne prođu,</li>\n                    <li>ne idemo ispred njih,</li>\n                    <li>kada idemo s njima, propustimo ih na desnu stranu.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Pridržavajući se ovih savjeta sprečavamo nered, neželjene istupe i bilo kakve druge situacije koje na bilo koji način ugrožavaju prava starijih osoba.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - POŠTIVANJE STARIJIH</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Kako je Poslanik, alejhis-selam, pokazivao poštivanje prema starijima?</li>\n                    <li>Koje postupke smatramo postupcima poštivanja starijih?</li>\n                    <li>Zašto je važno lijepo ponašanje i poštivanje starijih?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Nastojte u svakom danu učiniti neko dobro djelo prema starijima, a to djelo evidentirajte i podijelite sa svojim drugovima i muallimom. Pamtite i djela koja čine vaši drugovi prema starijima (poput: ustupanja mjesta u autobusu, pomoć pri nošenju namirnica i slično).</li>\n                    <li>U slobodno vrijeme posjetite nanu i djeda (ili starije osobe u svom komšiluku), razgovarajte s njima, ponudite im pomoć i pitajte ih šta je to što bi ih najviše usrećilo od vaših postupaka.</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":56,"is_published":true,"kviz_pitanja":[{"answer":"Biti milostivi prema mlađima i poštovati starije","options":["Biti milostivi prema mlađima i poštovati starije","Samo slušati njihove savjete","Izbjegavati razgovore sa njima","Dati im sve što posjedujemo"],"question":"Šta je Muhammed, alejhis-selam, rekao da trebamo raditi prema starijima?"},{"answer":"Djeca postanu srdita, mlađi se neuljudno suprotstavljaju starijima","options":["Djeca postanu srdita, mlađi se neuljudno suprotstavljaju starijima","Više će padati kiša","Svi će postati bogatiji","Svi će govoriti isti jezik"],"question":"Koje ponašanje je Muhammed, alejhis-selam, najavio kao predznak Sudnjega dana?"},{"answer":"Jer su stariji i iskusniji i zaslužuju poštovanje","options":["Jer su stariji i iskusniji i zaslužuju poštovanje","Jer su bogatiji od mlađih","Jer često izlaze iz kuće","Jer imaju više vremena"],"question":"Šta čini poštivanje starijih prema islamu važnim?"},{"answer":"Sve starije osobe bez izuzetka","options":["Samo svoje bake i djedove","Samo učene i plemenite ljude","Sve starije osobe bez izuzetka","Samo bogate starce"],"question":"Koliko starih osoba trebamo poštovati prema islamskom učenju?"},{"answer":"Rezultira lošijim stanjem u porodici","options":["Porodica biva sretna i mirna","Rezultira lošijim stanjem u porodici","Djeca bolje uče u školi","Nema nikakve razlike"],"question":"Šta se dešava u porodici ako se udaljimo od poštivanja starijih?"}]},{"nivo":3,"slug":"poboznost","naslov":"Pobožnost i bogobojaznost","content_html":"<div class=\"lesson-container\">\n        <h1>POBOŽNOST I BOGOBOJAZNOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/poboznost.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Pobožnost i bogobojaznost (takvaluk)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje takvaluka — svijesti o Allahu u svemu što radimo</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam takvaluka i kako se postiže</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike svjesnog ibadeta i čuvanja od grijeha</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je najbolji čovjek pred Allahom? Najpobožniji, najbogobojazniji. Šta je takvaluk?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Takva (bogobojaznost) — stalna svijest o Allahu i bojazan da ne učinimo nešto što bi Ga rasrdilo.</p><p>Allah u Kur’anu: \"Najugledniji kod Allaha je onaj ko Ga se najviše boji.\"</p><p>Bogobojazan čovjek: izvršava farzove, izbjegava harame, čuva čak i mekruhe.</p><p>Definicija (Alija, r.a.): \"Takva je: bojati se Uzvišenog, raditi po objavi, biti zadovoljan malim, pripremati se za odlazak.\"</p><p>Postupak: stalna dova, redovni ibadet, sjećanje na smrt, druženje sa pobožnima, čitanje Kur’ana.</p><p>Plod takvaluka: Allahova ljubav, smirenost srca, oprost, izlaz iz nevolje, opskrba odakle se ne nada.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome kako mogu povećati svoj takvaluk. Zaključak: takvaluk je najveće blago.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NEVIDLJIVI SVJEDOK <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da se nalazite u prostoriji u kojoj nema nikoga, a ispred vas stoji kutija puna najslađih bombona koje niko ne čuva. Naš Haris se jednom našao u sličnoj situaciji u prodavnici kada je prodavac nakratko izašao. Iako ga niko od ljudi nije gledao, on je osjetio da nije sam. Sjetio se mamine priče o tome da nas Allah vidi čak i tamo gdje se sunčeva svjetlost ne probija. Taj osjećaj učinio je da Haris mirno sačeka prodavca, osjećajući neopisiv mir u srcu.</p>\n                    <p>Danas ćemo istražiti šta to zapravo znači biti pobožan i bogobojazan u svakom trenutku našeg života. Naučit ćemo da bogobojaznost nije samo strah, već stalna svijest o Allahovom prisustvu koja nas čuva od loših postupaka. Otkrit ćemo kako snaga vjere pobjeđuje iskušenja i zašto je važno svoditi račun sa samim sobom. Bogobojaznost nam daruje unutrašnje svjetlo koje nam osvjetljava put u svim životnim situacijama.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: \"Čuvaj se harama onoga što je zabranjeno - bit ćeš najpobožniji čovjek...\" (Tirmizi)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Ihsan je stalna svijest o Allahu, dž.š., koja podrazumijeva da obožavamo Allaha, dž.š., kao da Ga vidimo jer iako mi Njega ne vidimo, On nas uistinu vidi.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Suština pobožnosti i bogobojaznosti je u čuvanju od harama i sumnjivih stvari, te svođenju računa sa samim sobom u pogledu svakog učinjenog djela. Ko ne postupa tako nema potpune pobožnosti i bogobojaznosti!\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: O vjernici, bojte se Allaha onako kako se treba bojati i umirite samo kao muslimani. (Alu Imran, 102)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Bogobojaznost je sastavni dio vjerovanja i ona ga upotpunjava, pa bi se trebala naći kod svakog muslimana i muslimanke. Ovo svojstvo čuva od svih negativnih postupaka, i u svakom trenutku podsjeća da Allah, dž.š., sve vidi, čuje i zna. Onaj ko se Allaha, dž.š., boji neće se prepustiti željama i prohtjevima, nego će se okrenuti ibadetu i pokornosti svome Gospodaru.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., je rekao: I Allaha se bojte, i znajte da je Allah na strani onih koji se grijeha klone. (El-Bekare, 194)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., nam u navedenom ajetu naređuje da se samo Njega bojimo i da govorimo istinu. Oni koji se istinski boje svoga Gospodara govore istinu makar bila i na njihovu štetu. Takve ljude Allah, dž.š., će nagraditi i grijehe im oprostiti.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: O vi koji vjerujete, Allaha se bojte i u Poslanika Njegova vjerujte, On će vam dvostruku milost Svoju darovati, i daće vam svjetlo pomoću kog ćete ići. (El-Hadid, 28)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; display: inline-block; text-transform: uppercase;\">Primjer pobožnosti i bogobojaznosti</p>\n\n                <p class=\"lesson-text\">\n                    Supruga upravitelja Egipta tražila je od Jusufa, alejhis-selam, da počini blud, a on je odbio. Bila je mlada i lijepa i pripremila se za taj čin, a i Jusuf, alejhis-selam, je bio mlad, lijepog izgleda, i njen sluga. Kad joj se ukazala prilika da se osami s njim, zaključala je vrata dvorca i rekla mu: \"...hodi...\"\n                </p>\n\n                <p class=\"lesson-text\">\n                    Jusuf, alejhis-selam, joj je odgovario: \"Sačuvaj Bože! - uzviknu on - vlasnik me moj lijepo pazi; a oni koji sami sebi nepravdu čine neće nikad uspjeti.\" (Jusuf, 23)\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - POBOŽNOST I BOGOBOJAZNOST</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Ko je najpobožniji čovjek prema hadisu?</li>\n                    <li>Šta je ihsan i kako on utiče na bogobojaznost?</li>\n                    <li>U čemu je suština pobožnosti i bogobojaznosti?</li>\n                    <li>Kako nas bogobojaznost čuva od negativnih postupaka?</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":57,"is_published":true,"kviz_pitanja":[{"answer":"Čuvanje od harama i sumnjivih stvari","options":["Čuvanje od harama i sumnjivih stvari","Samo čitanje Kur'ana svaki dan","Nošenje lijepih odjeće","Govljenje sa glasnom vrstom"],"question":"Šta je prema lekciji osnova pobožnosti i bogobojaznosti?"},{"answer":"Stalna svijest o Allahu kao da Ga vidimo","options":["Stalna svijest o Allahu kao da Ga vidimo","Često putovanje u druga mjesta","Davanje samo novca siromašnima","Razgovaranje sa drugim ljudima"],"question":"Šta znači ihsan prema Poslaniku, alejhis-selam?"},{"answer":"Govore istinu makar bila na njihovu štetu","options":["Govore istinu makar bila na njihovu štetu","Kriju svoje greške od drugih","Izmišljaju priče kada im odgovara","Slijede samo želje bez razmišljanja"],"question":"Kako se ponašaju oni koji se Allaha istinski boje?"},{"answer":"Odbijanju bluда i čuvanju časti","options":["Odbijanju bluда i čuvanju časti","Zavodenju lijepe žene","Bogatstvu i moći","Kraljevskoj poziciji"],"question":"Koju ibadetu je Jusuf, alejhis-selam, dao prednost?"},{"answer":"Nagrajuje ih i opraštа im grijehe","options":["Nagrajuje ih i opraštа im grijehe","Kažnjava ih svaki dan","Čini ih siromašnima","Oduzima im obitelj"],"question":"Šta Allah, dž.š., čini onima koji se Njega boje i govore istinu?"}]},{"nivo":3,"slug":"iskrenost-pravednost","naslov":"Iskrenost i pravednost","content_html":"<div class=\"lesson-container\">\n        <h1>ISKRENOST I PRAVEDNOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/iskrenost.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Iskrenost i pravednost</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje iskrenosti i pravednosti u svim postupcima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojmove ihlas i adl u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike iskrenog i pravednog ponašanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta znači biti iskren? A pravedan? Po čemu prepoznajemo takvog čovjeka?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Iskrenost (ihlas)</strong> — raditi sva djela samo radi Allaha, bez želje za pohvalom.</p><p><strong>Pravednost (adl)</strong> — dati svakome ono što mu pripada, bez razlikovanja.</p><p>Allah u Kur’anu: \"O vjernici, budite uvijek pravedni i svjedočite ako i protiv vas samih ili roditelja i rodbine bilo, bio bogat ili siromašan.\"</p><p>Iskrenost se vidi: u djelima koja niko ne vidi — namaz u tami, sadaka u tajnosti, ibadet u samoći.</p><p>Pravednost se vidi: u sudu, u trgovini, u dijeljenju među djecom, u svjedočenju.</p><p>Suprotnosti: rijaluk (pokazivanje pred ljudima) i nepravda (zulum) — dva najveća zla.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o iskrenom i pravednom ponašanju. Zaključak: iskrenost i pravda — temelji časnog života.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":58,"is_published":true,"kviz_pitanja":[{"answer":"Ispoljavanje vjerovanja i činjenja dobra samo za Allahovog zadovoljstva","options":["Ispoljavanje vjerovanja i činjenja dobra samo za Allahovog zadovoljstva","Govaljenje dobrim riječima iz ljubavi prema sebi","Učinjenje dobrih djela samo pred drugim ljudima","Proslava vlastitih uspjeha i dostignuća"],"question":"Šta je iskrenost prema učenju islama?"},{"answer":"Djela","options":["Novac i bogatstvo koje čovjek posjeduje","Djela","Количина molilačkih ruku i sujeda","Haljine i odjeća koju nosimo"],"question":"Šta se vrednuje prema namjerama prema hadisu?"},{"answer":"Ka dobročinstvu, a dobročinstvo u Džennet","options":["Ka usamljenosti i tugu","Ka dobročinstvu, a dobročinstvo u Džennet","Ka bogatstvu i moći","Ka zavisti i zavidnosti"],"question":"Gdje vodi iskrenost prema hadisu Muhammeda, alejhis-selam?"},{"answer":"Licemjerje i laž","options":["Istina i čestost","Licemjerje i laž","Poštenje i čistoća","Vjera i molitve"],"question":"Što je suprotno iskrenosti prema lekciji?"},{"answer":"Uvodi ga u iskrenost u djelima i ispravnost u postupcima","options":["Čini ga tužnim i samotnim","Vodi ga ka laži i pretvaranju","Uvodi ga u iskrenost u djelima i ispravnost u postupcima","Čini ga bolesnim i slabim"],"question":"Kako iskrenost u riječima utiče na čovjeka?"}]},{"nivo":3,"slug":"strpljivost","naslov":"Predanost i strpljivost","content_html":"<div class=\"lesson-container\">\n        <h1>PREDANOST I STRPLJIVOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/strpljivost.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Predanost i strpljivost (sabr)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje strpljivosti u nevoljama i predanosti Allahu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam sabra i njegove vrste</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti strpljivog podnošenja izazova</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta uraditi kad nas zadesi nešto teško? Plakati, ljutiti se, ostaviti? Ne — strpiti se. Šta je sabr?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sabr — strpljenje; izdržati teško sa smirenošću, bez pritužbi protiv Allahove odredbe.</p><p>Tri vrste sabra: <strong>1.</strong> sabr u ibadetu (ustrajati), <strong>2.</strong> sabr od grijeha (odoljeti), <strong>3.</strong> sabr u nevolji (strpljivo podnositi).</p><p>Allah u Kur’anu: \"Allah je sa strpljivima.\"</p><p>Strpljivi imaju veliku nagradu — bez računa.</p><p>Kad nas zadesi nesreća, kažemo: <em>\"Inna lillāhi ve innā ilejhi rādži‘ūn.\"</em></p><p>Sabr ne znači pasivnost — radimo sve što možemo, a ostalo predajemo Allahu (tevekkul).</p><p>Plodovi sabra: oprost grijeha, uzdizanje stepena, izlaz iz nevolje.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako su prošli kroz neku tešku situaciju. Zaključak: sabr je ključ Dženneta.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":59,"is_published":true,"kviz_pitanja":[{"answer":"Potpunu predanost, povinovanost i poniznost Allahu","options":["Potpunu predanost, povinovanost i poniznost Allahu","Samo svakodnevno klanjanje u džamiji","Strogo poštovanje samo svjetskih zakona","Izbjeggavanje svih težinskih situacija u životu"],"question":"Šta Islam znači prema tekstu lekcije?"},{"answer":"Odvratiti ljude od robovanja stvorenjima i usmjeriti ih Allahu","options":["Odvratiti ljude od robovanja stvorenjima i usmjeriti ih Allahu","Da se bogati postanu još bogatiji","Da se ne obavlja nikakav rad","Samo da se čita Kuran cijeli dan"],"question":"Koji je prvenstveni cilj islama?"},{"answer":"Dostojanstveno podnošenje životnih neprijatnosti bez straha","options":["Dostojanstveno podnošenje životnih neprijatnosti bez straha","Ignorisvanje svih problema i težina","Samo pasivno čekanje bez aktivnosti","Izbjegavanje svih ljudskih odnosa"],"question":"Šta je strpljivost prema tekstu?"},{"answer":"Kada su u skladu s Božijim zakonom i cilj je Allahovo zadovoljstvo","options":["Kada su u skladu s Božijim zakonom i cilj je Allahovo zadovoljstvo","Samo kada se obavlja namaz pet puta dnevno","Samo kada se izbjegavaju svi problemi","Samo noću prije spavanja"],"question":"Kada su sve aktivnosti muslimana u predanosti Allahu?"},{"answer":"Allahovi poslanici, zatim najbolji, pa bolji","options":["Allahovi poslanici, zatim najbolji, pa bolji","Samo siromašni ljudi u društvu","Samo žene koje rade","Samo starije osobe koje žive sama"],"question":"Koji će biti najviše iskušavani prema hadisu?"}]},{"nivo":3,"slug":"istinoljubivost","naslov":"Istinoljubivost i pouzdanost","content_html":"<div class=\"lesson-container\">\n        <h1>ISTINOLJUBIVOST I POUZDANOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/istinoljubivost.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Istinoljubivost i pouzdanost (sıdk i emanet)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike istinoljubivosti i čuvanja amaneta</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojmove sıdk i emanet u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje karaktera povjerljive osobe</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta znači biti istinoljubiv? A pouzdan? Te dvije osobine su odlike Poslanika, a.s.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Sıdk (istinoljubivost)</strong> — uvijek govoriti istinu, čak i kad je teška.</p><p><strong>Emanet (pouzdanost)</strong> — čuvanje povjerene stvari ili tajne.</p><p>Poslanik, a.s., je još prije poslanstva nazivan \"El-Emīn\" (Pouzdani) i \"Es-Sādiq\" (Istinoljubivi).</p><p>Allah u Kur’anu: \"O vjernici, bojte se Allaha i budite sa istinitima.\"</p><p>Lažov gubi povjerenje, čast i prijatelje. Poslanik je laž nazvao putem licemjerstva.</p><p>Vrste amaneta: novac koji nam je povjeren, tajna prijatelja, povjereni posao, naš jezik (čuvati ga od ružnih riječi), tijelo (čuvati ga od grijeha).</p><p>Razgovor: kad sam zadnji put rekao laž? Da li čuvam tajne?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na 1 dan bez laži. Zaključak: istina je svjetlo, laž je tama.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":60,"is_published":true,"kviz_pitanja":[{"answer":"Isticanje istine i ljubavi prema njoj","options":["Isticanje istine i ljubavi prema njoj","Prikazivanje se boljim nego što se jeste","Skrivanje loših informacija od drugih","Govorenje samo kada je istina zgodna"],"question":"Šta je istinoljubivost prema tekstu lekcije?"},{"answer":"El-Ahzab","options":["El-Me'aridž","El-Ahzab","El-Bakara","En-Nisa"],"question":"Koju suru Kur'ana tekst citira o istini?"},{"answer":"Ispunjavanje obaveza i čuvanje povjerenih stvari","options":["Ispunjavanje obaveza i čuvanje povjerenih stvari","Govoreće samo lijepe stvari","Pokazivanje bogatstva drugima","Izbjegavanje teških situacija"],"question":"Šta je pouzdanost?"},{"answer":"El-Emin - povjerljivi","options":["El-Emin - povjerljivi","El-Aziz - moćni","El-Amin - bogati","El-Hakim - mudraci"],"question":"Kako je Muhammed, alejhis-selam, bio poznat kao mladić?"},{"answer":"Nema vjere onaj ko nema pouzdanosti","options":["Nema vjere onaj ko nema pouzdanosti","Trebao bi pokušati ponovno","Može se popraviti vremenom","To je normalno za sve ljude"],"question":"Šta Muhammed, alejhis-selam, kaže o čovjeku bez pouzdanosti?"}]},{"nivo":3,"slug":"dobrota","naslov":"Dobrota i ustrajnost","content_html":"<div class=\"lesson-container\">\n        <h1>DOBROTA I USTRAJNOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dobrota.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dobrota i ustrajnost (ihsan i istikamet)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje stalne težnje ka dobru i ustrajnosti u istini</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojmove ihsan i istikamet</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike činjenja dobra svakog dana</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je dobrota? Šta znači biti ustrajno dobar? Hajde da naučimo ihsan i istikamet.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Ihsan</strong> — savršenstvo u svemu; raditi tako kao da vidiš Allaha, a ako ne vidiš — On vidi tebe.</p><p><strong>Istikamet</strong> — ustrajnost na pravom putu, bez skretanja.</p><p>Allah u Kur’anu: \"Doista oni koji govore: Naš Gospodar je Allah, a zatim ostanu ustrajni — meleki će im se spuštati: Ne bojte se, ne tugujte...\"</p><p>Dobrota se pokazuje u svemu: u namazu (skrušenost), u poslu (kvalitet), u govoru (lijepa riječ), u susretu (osmjeh).</p><p>Istikamet se postiže: redovnim ibadetom, učenjem Kur’ana, druženjem sa dobrima, izbjegavanjem grijeha.</p><p>Najteže je biti dobar uvijek — kad smo umorni, ljuti, izazvani. Tu je istinski iman.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta je za njih izazov u dobroti. Zaključak: bolje malo ali stalno, nego mnogo a povremeno.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                DRAGULJI KOJI UVIJEK SJAJE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite da nosite u džepu male, nevidljive dragulje koje možete podijeliti svakome koga sretnete, a da ih kod vas nikada ne nestane. Naša Merjem je danas naučila da su ti dragulji zapravo selam, lijepa riječ i osmijeh. Vidjela je jednu stariju gospođu koja je izgledala tužno, i samo joj se toplo nasmiješila i nazvala selam. Gospođi se lice odmah ozarilo. Merjem je shvatila da dobrota ne mora uvijek biti velika i skupa – nekada je najljepši poklon upravo naša pažnja prema drugima.</p>\n                    <p>Danas ćemo istražiti zašto nas Allah, dž.š., poziva da sa svakim postupamo lijepo i zašto su dobri ljudi poput dragulja koji sjaje bez obzira na okolnosti. Naučit ćemo šta znači biti ustrajan na Pravom putu i zašto je važno da naša dobra djela ne budu samo povremena, već stalna navika. Otkrit ćemo kako nas Poslanik, alejhis-selam, poredi s jednim tijelom u kojem svi organi osjećaju istu bol i radost, te kako naša ustrajnost u vjeri otvara vrata Dženneta koji nam je obećan.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Ti sa svakim lijepo! I traži da se čine dobra djela, a neznalica se kloni! (El-Aʻraf, 199)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    U vremenu sebičnosti, uskogrudnosti, egoizama i nedostatka solidarnosti, prava je sreća susresti nekoga ko je dobar i ko ima osjećaj za tuđe probleme. Takve osobe su pravi dragulji koji uvijek sjaje, bez obzira na situaciju i okolnosti.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Selam, lijepa riječ i osmijeh upućen drugom je dobro djelo – sadaka. Od muslimana i muslimanki se traže ljubaznost i dobrota prema svim ljudima, kako u riječima tako i u djelima. Uzvišeni Allah vjernike opisuje kao dobre i samilosne, koji pomažu drugima u svemu:\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4;\">\n                    Pa, zašto on na blagodatima zahvalan bio nije? – A šta ti misliš: kako se može na blagodatima zahvalan biti? – roba ropstva osloboditi, ili, kad glad hara, nahraniti siroče bliska roda ili ubogoga nevoljnika, a uz to da je od onih koji vjeruju, koji jedni drugima izdržljivost preporučuju i koji jedni drugima milosrđe preporučuju; oni će biti – sretnici. (El-Beled, 11-18)\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Vjernici su u svojoj međusobnoj ljubavi, milosti i blagosti poput jednog tijela: ako jedan njegov organ oboli i svi drugi organi osjećaju bol i groznicu.” (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Cilj pokazivanja dobrote prema drugima je da poboljšamo život ljudi oko nas. To možemo postići samo ako budemo osjećajni, ako prema drugima budemo imali razumijevanja, te ako budemo brinuli o drugima jednako kao i o nama samima.\n                </p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">USTRAJNOST</p>\n\n                <p class=\"lesson-text\">\n                    Iman u srcu potvrđujemo ustrajnim izvršavanjem naređenih dužnosti, a ostavljanjem zabranjenih. Uzvišeni Allah je rekao: Onima koji govore: “Naš Gospodar je Allah” , pa poslije ustraju pri tome – dolaze meleki: “Ne bojte se i ne žalostite se, i radujte se Džennetu koji vam je obećan.” (Fussilet, 30)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Neprestano se preispitivati o ustrajnosti na Pravom putu je dužnost svakog vjernika. Na ustrajnosti treba zahvaljivati Uzvišenom Allahu i moliti Ga da nas sačuva na Pravom putu. Također, potrebno je popravljati korake kojima koračamo prema Allahu, dž.š.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ustrajnošću se postiže spas od zla, približava Džennetu i ostvaruju želje.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Jedan od ashaba je upitao Muhammeda, alejhis-selam: “Allahov Poslaniče, reci mi nešto o islamu, o čemu poslije tebe više nikoga neću morati pitati?” Allahov Poslanik, alejhis-selam, reče mu: “Reci: ‘Vjerujem u Allaha’ a zatim ustraj u tome!” (Muslim)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Zbog toga je neophodno ustrajavati u iskrenim namjerama, korisnim riječima i dobrim djelima.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Dobrota i ustrajnost u činjenju dobrih djela potvrđuju vjerovanje i pokornost Allahu, dž.š.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - DOBROTA I USTRAJNOST</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Šta se u ponašanju muslimana smatra sadakom?</li>\n                    <li>Kako je Poslanik, alejhis-selam, opisao odnose među muslimanima?</li>\n                    <li>Šta je cilj dobrote prema drugim ljudima?</li>\n                    <li>Šta podrazumijeva ustrajnost u vjeri?</li>\n                </ol>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM</span><br>\n                        • Neka ustrajnost je korisna, a neka štetna.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":61,"is_published":true,"kviz_pitanja":[{"answer":"Da činimo dobra djela i budemo ljubazni","options":["Da budemo sebični i egoistični","Da činimo dobra djela i budemo ljubazni","Da izbegavamo ljude i brinemo samo sebe","Da se ljutimo na sve oko nas"],"question":"Šta Allah traži od nas prema drugim ljudima?"},{"answer":"Selam, lijepa riječ i osmijeh upućen drugom","options":["Samo davanje novca siromašnima","Selam, lijepa riječ i osmijeh upućen drugom","Samo molenje Allaha dan i noć","Samo učenje Kur'ana"],"question":"Šta je prema tekstu primjer dobroga djela - sadake?"},{"answer":"Poput jednog tijela - ako boli jedan, bole svi","options":["Kao neprijatelje jedni drugima","Poput jednog tijela - ako boli jedan, bole svi","Kao ljude koji se međusobno mrzе","Kao osobe koje nemaju veze"],"question":"Kako je Poslanik, alejhis-selam, opisao vjernike?"},{"answer":"Ustrajnim izvršavanjem naređenih dužnosti","options":["Samo moljenjem Allaha","Ustrajnim izvršavanjem naređenih dužnosti","Ignorisanjem dužnosti prema drugima","Samo čitanjem Kur'ana"],"question":"Kako potvrđujemo iman u srcu?"},{"answer":"Oni koji govore da je Gospodar Allah i ustraju pri tome","options":["Oni koji napuštaju vjeru","Oni koji govore da je Gospodar Allah i ustraju pri tome","Oni koji rade samo zlo","Oni koji nisu vjernici"],"question":"Ko će dobiti radosnu vijest od meleka po ajetu iz Fussileta?"}]},{"nivo":3,"slug":"samilost","naslov":"Samilost i praštanje","content_html":"<div class=\"lesson-container\">\n        <h1>SAMILOST I PRAŠTANJE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/samilost.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Samilost i praštanje (rahmet i afv)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje samilosnog srca i sposobnosti praštanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti vrijednost samilosti i praštanja u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike samilosnog ponašanja prema svemu živom</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta uraditi kad nas neko povrijedi? Vratiti istom mjerom ili oprostiti? Allah voli one koji opraštaju.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Rahmet (samilost)</strong> — milo srce, suosjećanje sa stvorenjima Allahovim.</p><p><strong>Afv (oprost)</strong> — opraštanje onima koji su nas povrijedili.</p><p>Poslanik, a.s.: \"Ko se ne smiluje — njemu se neće smilovati.\"</p><p>Allah u Kur’anu: \"Neka opraštaju i pređu — zar ne želite da Allah vama oprosti?\"</p><p>Samilost: pomoć siromašnom, briga za životinje (Poslanik je opomenuo onu koja je gladnu mačku zatvorila), milost prema biljkama.</p><p>Oprost: kad nam neko nepravdu učini, oprostimo; ne nositi mržnju u srcu — to čini srce teškim.</p><p>Najveća samilost: roditelja prema djeci, učitelja prema učeniku, jakeg prema slabome.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju da oproste nekome ko ih je povrijedio. Zaključak: praštati je hrabrost, a ne slabost.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":62,"is_published":true,"kviz_pitanja":[{"answer":"Er-Rahman Milostivi i Er-Rahim Samilosni","options":["Er-Rahman Milostivi i Er-Rahim Samilosni","El-Aziz i El-Hakim","Es-Selam i El-Mu'min","El-Gaffar i El-Alim"],"question":"Koja su prva Allahova imena spomenuta u Kur'anu?"},{"answer":"Kao milost za svjetove","options":["Da prokinje i preklinje idolopoklonike","Kao milost za svjetove","Da brani islam ratom","Da bira samo vjernike"],"question":"Za šta je Allah poslao Muhammeda, alejhis-selam?"},{"answer":"Prema samilosnima Allah je milostiv","options":["Prema samilosnima Allah je milostiv","Allah ne voli prokinjače","Islam je samo za arapske zemlje","Griješiti je dozvoljeno svakodnevno"],"question":"Prema kom ayetu se od muslimana traži samilost?"},{"answer":"Prema roditeljima, braći, prijateljima i komšijama","options":["Samo prema bogatim ljudima","Samo prema strancima","Samo prema vladama","Prema roditeljima, braći, prijateljima i komšijama"],"question":"Prema kojima osobama trebamo pokazati samilost?"},{"answer":"Svi su primili islam nakon nekoliko dana","options":["Još jače su odbili islam","Svi su primili islam nakon nekoliko dana","Izdali su islam","Postali su Muhammadovi neprijatelji"],"question":"Šta se dogodilo s plemenom Devs nakon Muhammadove dove?"}]},{"nivo":3,"slug":"skrtost","naslov":"Škrtost i zavidnost","content_html":"<div class=\"lesson-container\">\n        <h1>ŠKRTOST I ZAVIDNOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/skrtost.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Škrtost i zavidnost (buhul i hased)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje plemenitosti i čistog srca bez zavisti</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojmove buhul i hased kao bolesti srca</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike dijeljenja i radovanja tuđim uspjesima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je škrtost? A zavidnost? Da li su to lijepe osobine? Ne — to su bolesti srca.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Buhul (škrtost)</strong> — izbjegavanje davanja onoga što treba dati (zekat, sadaka, pomoć).</p><p><strong>Hased (zavist)</strong> — željeti da druga osoba izgubi blagodat koju ima; loše osjećanje zbog tuđe sreće.</p><p>Poslanik, a.s.: \"Čuvajte se zavisti — ona uništava dobra djela kao što vatra uništava drva.\"</p><p>Razlika: ako kažem \"I ja bih htio kao on\" — to je gibta (hvale vrijedna želja). Ako kažem \"Da on to izgubi\" — to je hased.</p><p>Škrti ne uživa u svojoj imovini — strah ga je da ne nestane. Plemeniti uživa i u svojoj i u tuđoj sreći.</p><p>Liječenje: dova za onoga kome zavidimo, sadaka, podsjećanje da je sve od Allaha.</p><p>Iskreni vjernik raduje se tuđem uspjehu kao svom — to je čisto srce.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome kome bi mogli pomoći (suprotstaviti se škrtosti). Zaključak: čisto srce — sretan život.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                KRADLJIVCI UNUTRAŠNJEG MIRA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Jeste li ikada osjetili onaj neugodan pritisak u prsima kada vidite da neko drugi ima ljepšu igračku ili bolju ocjenu? Ili onaj nagon da čvrsto stisnete šaku i ne date nikome ni mrvicu svog slatkiša? To su trenutci kada nas posjećuju dva nevidljiva kradljivca sreće: škrtost i zavidnost. Oni nam šapuću da ćemo biti sretniji ako sve imamo samo za sebe, ali istina je potpuno drugačija. Srce koje ne dijeli i srce koje mrzi tuđi uspjeh postaje sivo i teško kao kamen. Danas ćemo naučiti kako prepoznati te bodljikave osjećaje i kako ih zamijeniti dobrotom koja srce čini lahkim i svijetlim. Pravi heroj nije onaj ko ima najviše, nego onaj ko se zna radovati tuđoj sreći kao da je njegova vlastita.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Šejtan vas plaši neimaštinom i navraća vas da budete škrti, a Allah vam obećava oprost i nagradu Svoju; Allah je neizmjerno dobar i sve zna. (El-Bekare, 268)\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “…Škrtac je daleko od Allaha, i daleko od ljudi; daleko od Dženneta, a blizu Džehennema. Neuki darežljivac je Allahu draži od učena škrca.” (Tirmizi)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Škrtost se ubraja u najlošije ljudske osobine, a škrta osoba se ubraja među najomraženije osobe. Škrtost se može pojavljivati u različitim segmentima ljudskog života, a pod pojmom škrtosti najprije se misli na škrtost u dijeljenju imetka. Škrtariti u imetku znači zadržavati imetak za sebe, uskraćujući ga ljudima oko sebe, a često i svojim najbližim – onima koje smo dužni hraniti i izdržavati. Škrtost proizlazi iz egoizma i straha od siromaštva.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ova ljudska osobina ima dalekosežne posljedice, kako za čovjeka tako i za njegov imetak:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>nema povjerenja u ono što je Allah, dž.š., rekao,</li>\n                    <li>ne slijedi ono što je Muhammed, alejhis-selam, preporučio,</li>\n                    <li>ne vjeruje u odredbu o nafaki,</li>\n                    <li>uskraćuje dobročinstvo svojoj porodici,</li>\n                    <li>ne čini dobro drugima,</li>\n                    <li>ne dijeli imetak dajući sadaku,</li>\n                    <li>ne ulaže imetak u dobrotvorne svrhe,</li>\n                    <li>živi u strahu da će osiromašiti,</li>\n                    <li>njegov imetak se umanjuje,</li>\n                    <li>nestaje bereketa u imetku itd.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Jedna od stvari za koju će se polagati račun na Sudnjem danu jeste i imetak, kako je stečen i u šta je potrošen.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, kaže: “Neće se pokrenuti stopala Allahovog roba na Sudnjem danu sve dok ne bude pitan o životu – u šta ga je utrošio, o znanju – šta je po njemu radio, o imetku – kako ga je stekao i u šta ga je potrošio i o tijelu, u čemu ga je trošio.” (Tirmizi)\n                    </p>\n                </div>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAVIDNOST</p>\n\n                <p class=\"lesson-text\">\n                    Škrtost i zavidnost su vezane uzročno-posljedičnom vezom jedna za drugu, pa najčešće škrta osoba postaje zavidnik, a zavidnik škrtari.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Zavidnost je loša ljudska osobina koja se izražava u negativnom odnosu prema drugoj osobi koja posjeduje nešto što zavidnik nema. Postoje različite vrste zavidnosti koje se mogu pojavljivati od zlobe u duši, preko blagog neprijateljstva, do otvorene agresivnosti pa i sreće koja obuzima zavidnika, kada to dobro ode od druge osobe.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Zavidnost je opasna bolest i ona je poznata od vremena kada je Allah, dž.š., stvorio Adema, alejhis-selam, kojem je pozavidio prokleti šejtan. Prisutna je u svakom, pa i u našem vremenu, a nje se svaki iskreni vjernik mora dobro čuvati. Ona uništava povjerenje kod ljudi i prekida njihovu međusobnu komunikaciju te uzrokuje pojavu drugih velikih grijeha. Nažalost, ima mnogo ljudi koji se raduju tuđoj nesreći, a tužni su kada musliman uznapreduje i dođe do položaja ili imetka.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Ako kakvo dobro dočekate, to ih ozlojedi, a zadesi li vas kakva nevolja, obraduju joj se. Ako budete strpljivi i ono što vam se zabranjuje izbjegavali, njihovo lukavstvo vam neće nimalo nauditi. Allah uistinu dobro zna ono što oni rade. (Alu Imran, 120)\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Na lijep i slikovit način Poslanik, alejhis-selam, ukazuje na veliku opasnost koja dolazi od zavidnosti: “Čuvajte se zavidnosti, jer zavidnost uništava dobra djela kao što vatra uništava drva.” (Ebu Davud)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Uzroci zbog kojih osoba počinje zavidjeti su: mržnja, neprijateljstvo, oholost, strah od gubljenja položaja, skrivena škrtost i pokvarenost. Ovakva zavidnost se ne ubraja u loše osobine, nego se opisuje kao želja da i mi posjedujemo imetak koji bismo trošili u svrhe kojima je zadovoljan Allah, dž.š.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Nema zavidnosti izuzev dvojici: čovjeku kojem je Allah podario imetak, pa ga on troši na putu istine i čovjeku kojem je Allah darovao mudrost, pa on po njoj sudi i podučava druge.” (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Obaveza svakog muslimana i muslimanke je da traži utočište kod Allaha, dž.š., od raznih zlih osobina, među kojima su škrtost i zavidnost. Vjernik želi, a munafik zavidi.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ŠKRTOST I ZAVIDNOST</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je škrtost?</li>\n                    <li>Koje su posljedice škrtarenja?</li>\n                    <li>Šta je zavidnost?</li>\n                    <li>Kome se smije zavidjeti?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">RAZGOVOR S MUALLIMOM</p>\n                <ul class=\"lesson-text\">\n                    <li>Jedna predaja kaže: Vjernik želi, a munafik zavidi!</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":63,"is_published":true,"kviz_pitanja":[{"answer":"Oprost i nagradu Svoju","options":["Oprost i nagradu Svoju","Samo bogatstvo i zlato","Samo zdravlje i sreću","Samo dugu i moć"],"question":"Šta Allah obećava umjesto straha od neimaštine?"},{"answer":"Egoizam i strah od siromaštva","options":["Egoizam i strah od siromaštva","Bolest i starost","Nedostatak edukacije","Loše vrijeme"],"question":"Šta je glavni uzrok škrtosti prema lekciji?"},{"answer":"Škrtac","options":["Škrtac","Darežljiv čovjek","Bogat čovjek","Mlad čovjek"],"question":"Ko je po Poslaniku daleko od Allaha i Dženneta?"},{"answer":"O životu, znanju, imetku i tijelu","options":["O životu, znanju, imetku i tijelu","Samo o imetku","Samo o znanju","Samo o lošim dijelima"],"question":"O čemu će se čovjek morati odgovarati na Sudnjem danu?"},{"answer":"Bereket u imetku","options":["Bereket u imetku","Samo vrijeme","Samo prijatelji","Samo zdravlje"],"question":"Što se gubi zbog škrtosti prema lekciji?"}]},{"nivo":3,"slug":"ogovaranje","naslov":"Ogovaranje","content_html":"<div class=\"lesson-container\">\n        <h1>OGOVARANJE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ogovaranje.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ogovaranje (gibet) i potvora (buhtan)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje čuvanja jezika i izbjegavanja ogovaranja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti razliku između gibeta i buhtana, te njihovu opasnost</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike pristojnog govora</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je ogovaranje? A laganje na nekoga? To su veliki grijesi. Šta o tome kaže islam?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Gibet (ogovaranje)</strong> — spomenuti svoga brata po nečemu što on ne voli, makar to bila istina.</p><p><strong>Buhtan (potvora)</strong> — pripisati nekome nešto što nije učinio; još veći grijeh od gibeta.</p><p>Allah u Kur’anu: \"I ne ogovarajte jedni druge! Da li bi neko od vas volio jeo meso svoga umrlog brata? Vama bi to bilo odvratno!\"</p><p>Liječenje: kad neko počne ogovarati, prekinemo ili promijenimo temu; tražimo oprost od osobe koju smo ogovarali.</p><p>Šta nije gibet: spominjanje pred sucem (svjedočenje), upozorenje na zlo (npr. da se neko ne uda za nasilnika), opisivanje gdje znamo (Hasan ćelavi).</p><p>Razgovor: koliko se često ogovara u našem društvu? Kako prekinuti tu naviku?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju da neće ogovarati ovaj tjedan. Zaključak: čuvati jezik = čuvati Džennet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                SJENE NA SRCU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Ponekad mislimo da su riječi samo zvuk koji nestane čim ga izgovorimo, ali one su zapravo mnogo moćnije. Zamislite da svaka ružna riječ o nekome ko nije tu ostavlja malu mrlju na našem srcu. Često zaboravljamo da čast drugog čovjeka treba čuvati kao najvrjednije blago. Danas ćemo naučiti zašto je ogovaranje jedna od najopasnijih zamki za našu dušu i kako nas vjera uči da budemo čuvari tuđeg ugleda, čak i kada nas niko ne gleda. Otkrit ćemo kako snaga šutnje ili lijepa riječ mogu donijeti mir koji ogovaranje uvijek pokvari.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: ... i ne ogovarajte jedni druge! Zar bi nekome od vas bilo drago da jede meso umrlog brata svoga,- a vama je to odvratno - zato se Allaha bojte, Allah, zaista, prima pokajanje i samilostan je. (El-Hudžurat, 12)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Jedna od pojava koja je bila raširena i kod prijašnjih generacija a zadržala se i do danas je ogovaranje ljudi. Ova ružna navika ne samo da predstavlja grijeh kod Uzvišenog Allaha nego dovodi i do mržnje, nesuglasica i neprijateljstva među muslimanima i muslimankama.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Naš Gospodar Allah, dž.š., ogovaranje upoređuje s jedenjem mesa umrlog brata. Upuštajući se u ogovaranje, čovjek ne razmišlja o grijehu, a često smatra da ima pravo govoriti o drugome ono što je istina.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Međutim, Poslanik, alejhis-selam, je jednom prilikom upitao ashabe: \"Znate li šta je ogovaranje?\", prisutni rekoše: \"Allah i Njegov Poslanik najbolje znaju.\" \"Ogovaranje je da svoga brata muslimana spomeneš po onome što on ne voli\", odgovori Muhammed, alejhis-selam\n                </p>\n\n                <p class=\"lesson-text\">\n                    \"A šta ako pri njemu bude ono što spominjemo?\", upitaše ashabi. \"Ako pri njemu bude ono što spominješ, ogovorio si ga, a ako ne bude, potvorio si ga.\" (Muslim)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ogovaranje je povezano s drugim grijesima, poput zavidnosti, jer rijetko se o nekome priča loše bez određene zavidnosti. Za ogovaranje najčešće postoje određeni uzroci, a oni su:\n                </p>\n\n                <ul class=\"lesson-text\">\n                    <li>nepodnošenje ljudi,</li>\n                    <li>omalovažavanje nečijeg uspjeha i</li>\n                    <li>zavidnost na tuđim blagodatima.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Najbolji način da se sačuvamo jeste shvatanje da ljudi imaju mahane u svom ponašanju i da su s određenim nedostacima, pa je normalno očekivati da griješe. Istraživanje vlastitih nedostataka i mahana treba da bude polje našeg djelovanja.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Allahov poslanik Muhammed, alejhis-selam, je na Oproštajnom hadžu rekao: \"Zaista su vam vaši životi i vaši imeci i vaša čast sveti kao što vam je svet ovaj dan u ovome gradu i u ovom mjesecu.\" (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        \"Ko vjeruje u Allaha i u Sudnji dan neka govori dobro ili neka šuti.\"\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - OGOVARANJE</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Šta je ogovaranje?</li>\n                    <li>S čime Allah, dž.š., upoređuje ogovaranje?</li>\n                    <li>Koji su uzroci ogovaranja?</li>\n                </ol>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM</span><br>\n                        • Ko vjeruje u Allaha i u Sudnji dan neka govori dobro ili neka šuti.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":64,"is_published":true,"kviz_pitanja":[{"answer":"Sa jedenjem mesa umrlog brata","options":["Sa jedenjem mesa umrlog brata","Sa kradjom imovine","Sa lažima","Sa tuđim tajnama"],"question":"Sa čim Allah, dž.š., upoređuje ogovaranje u ajetu?"},{"answer":"Govorenje o bratu ono što on ne voli","options":["Govorenje o bratu ono što on ne voli","Samo lažne stvari o nekome","Govorenje pred većim brojem ljudi","Pisanje loših stvari o drugima"],"question":"Kako je Poslanik, alejhis-selam, objasnio šta je ogovaranje?"},{"answer":"Nepodnošenje, omalovažavanje i zavidnost","options":["Nepodnošenje, omalovažavanje i zavidnost","Dosada, gladan i umor","Ljutnja, strah i tugu","Ponos, mrznja i ljubomora"],"question":"Koja su glavna tri uzroka za ogovaranje prema lekciji?"},{"answer":"Razumijevanjem da svi imaju nedostatke","options":["Razumijevanjem da svi imaju nedostatke","Izbjegavanjem razgovora sa drugima","Čuvanjem tajnih stvari","Govorenjem samo laski drugim ljudima"],"question":"Kako se možemo zaštititi od ogovaranja prema lekciji?"},{"answer":"Ako je prisutan, ogovaraš; ako nije, povjeruješ","options":["Ako je prisutan, ogovaraš; ako nije, povjeruješ","Ogovaranje je javno, povjerivanje je tajno","Ogovaranje je sve, povjerivanje nije ništa","Nema nikakve razlike između njih"],"question":"Koja je razlika između ogovaranja i povjerivanja prema hadisu?"}]},{"nivo":3,"slug":"oholost","naslov":"Oholost","content_html":"<div class=\"lesson-container\">\n        <h1>OHOLOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/oholost.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Oholost (kibr)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje skromnosti i odbacivanje oholosti</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam kibra i njegovu opasnost</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike skromnog ponašanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je bio prvi koji je odbio Allahovu naredbu zbog oholosti? Iblis. Šta je oholost?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kibr (oholost) — smatrati sebe boljim od drugih i odbijati istinu.</p><p>Poslanik, a.s.: \"U Džennet neće ući onaj ko ima trun oholosti u srcu.\"</p><p>Iblis je odbio sedždu Ademu jer je rekao: \"Ja sam bolji od njega — stvoren sam od vatre, a on od zemlje.\" To je bila prva oholost.</p><p>Znaci oholosti: omalovažavanje drugih, odbijanje savjeta, ponižavanje slabijih, odbijanje istine kad je iznese neko ko nam nije po srcu.</p><p>Liječenje: razmišljati o tome odakle smo (zemlja), gdje idemo (kabur), šta jesmo (slabi pred Allahom); družiti se sa siromašnima i poniženima; učiti od svakog.</p><p>Suprotnost: <strong>tevadu‘ (skromnost)</strong> — Poslanik, a.s., je sjedio sa siromasima, sam sebi krpao odjeću, smijao se sa djecom.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o znacima oholosti u sebi. Zaključak: skromnost je put u Džennet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                ZAMKA LAŽNE VELIČINE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Dragi moji, zamislite srce kao kristalnu posudu. Dok god je ono ispunjeno skromnošću, kroz njega prolazi svjetlost. Ali, ponekad se u čovjeka uvuče jedan opasan osjećaj – onaj koji mu šapuće da vrijedi više od drugih samo zato što ima ljepšu odjeću, više novca ili bolje ocjene. To je oholost, nevidljivi zid koji nas odvaja od prijatelja i, što je najgore, od Allahove milosti. Danas ćemo naučiti kako prepoznati taj trenutak kada pomislimo da smo \"bolji\" i zašto je važno ostati čvrsto na zemlji, znajući da je sve što imamo dar od našeg Gospodara. Otkrit ćemo tajnu istinske ljepote koja ne dolazi iz ogledala, već iz načina na koji poštujemo svako biće oko nas.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Zaista, čovjek se uzoholi čim se neovisnim osjeti. (El-Alek, 6-7)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Jedna od najgorih ljudskih osobina koja se nikako ne smije naći kod vjernika muslimana jeste oholost.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Muhammed, alejhis-selam, kaže: “Neće ući u Džennet onaj u čijem srcu bude i koliko trun oholosti.” Neki čovjek reče: “Zaista čovjek voli da mu odjeća i obuća budu lijepi.” Na to mu Poslanik, alejhis-selam, reče: “Zaista je Allah lijep i voli ljepotu. Oholost je odbijanje istine i ponižavanje ljudi.” (Muslim)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Čovjek postaje ohol onog momenta kada napušta istinu koja je od Allaha, dž.š., i Njegovog poslanika Muhammeda, alejhis-selam, te kada ponižava druge. Prvi koji se uzoholio bio je Iblis kada je rekao: “Ja sam bolji od njega, mene si od vatre stvorio, a njega od ilovače” – odgovori on. (El-Aʻraf, 12)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Čovjek se uzoholi onog trenutka kada se osjeti neovisnim o drugima pa i o Allahu, dž.š.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Pored spomenutih, mnogo je razloga zbog kojih se ljudi ohole, a neki su:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>dunjalučko bogatstvo,</li>\n                    <li>porijeklo,</li>\n                    <li>stečeno znanje,</li>\n                    <li>ljepota,</li>\n                    <li>brojno potomstvo itd.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Vjernik zna da je dunjalučko bogatstvo prolazno, porijeklo na Sudnjem danu neće značiti ništa, znanje ne vrijedi ako nije u ime Allaha, ljepota je prolazna, a potomci nas kad-tad ostave. Mnogo je primjera u Kur‘anu koji govore o ljudima koji su se uzoholili, poput faraona, Hamana, Karuna – iz vremena Musaa, alejhis-selam, i Nemruda za vrijeme Ibrahima, alejhis-selam\n                </p>\n\n                <p class=\"lesson-text\">\n                    Oholost koja je bila prisutna kod njih vrlo je opasna osobina. Takva oholost je bila uzrokom Iblisovog istjerivanja iz Dženneta, Karuna i njegovo ogromno bogatstvo utjerala je u zemlju, faraona i Hamana potopila u Crvenom moru, a njih i sve ohole će na Sudnjem danu ponižene uvesti u Džehennem.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Vjernik se mora čuvati oholosti jer ona ne donosi dobro ni na ovom ni na budućem svijetu. Svi Allahovi robovi su posebni i dostojni pažnje i poštovanja!\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS: TROJICA ISKUŠANIH!</span><br>\n                        Allahov poslanik Muhammed, alejhis-selam, je rekao: “Allah, dž.š., je htio da iskuša trojicu Izraelćana, od kojih je jedan bio gubavac, drugi ćelavac, a treći slijep, pa im je poslao jednog meleka... (cijela priča o gubavcu, ćelavcu i slijepcu)... Melek mu na to reče: “Zadrži svoj imetak! Samo si bio iskušan. Allah je zadovoljan tobom, a nije zadovoljan tvojim drugovima.” (Buhari)\n                    </p>\n                </div>\n            </div>\n        </div>\n<div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('HADIS_ISKUŠANI', this)\">\n                HADIS: TROJICA ISKUŠANIH! <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"HADIS_ISKUŠANI\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allahov poslanik Muhammed, alejhis-selam, je rekao: \"Allah, dž.š., je htio da iskuša trojicu Izraelćana, od kojih je jedan bio gubavac, drugi ćelavac, a treći slijep, pa im je poslao jednog meleka. Melek je došao gubavcu i upitao ga:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Šta bi ti najviše želio?\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Najviše bih želio imati lijepu boju i lijepu kožu, i da se oslobodim ovog od čega se svijet zgraža na mene – odgovori on. Melek pređe rukom preko njegova tijela, te od njega sva guba spade, i dobi lijepu boju kože. Zatim ga melek upita:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – A koji ti je imetak najdraži?\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Deve – reče on. Allah mu tada dade jednu lijepu devu, koja je u stomaku nosila mladunče, a melek mu reče:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Allah ti dao berićet u njoj.\n                    </p>\n                    <p class=\"lesson-text\">\n                        Zatim je melek došao onome bez kose i upitao ga:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Šta bi ti najviše volio?\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Lijepu kosu, i da se oslobodim ovog od čega se svijet zgraža na mene – odgovori on. Melek ga pomilova po glavi, te ga bolest prođe i on dobi lijepu kosu. Melek ga upita:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – A koji bi imetak najviše volio?\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Krave – odgovori on. Allah mu tada dade jednu lijepu steonu kravu i reče:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Allah ti dao berićet u njoj.\n                    </p>\n                    <p class=\"lesson-text\">\n                        Zatim je melek došao slijepcu i upitao ga:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Šta bi ti najviše volio?\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Da mi Allah povrati vid kako bih mogao vidjeti ljude – odgovori on. Melek ga pomilova po očima i Allah mu povrati vid. Melek ga upita:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – A koji ti je imetak najdraži?\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Ovce – odgovori on. Allah mu dade jednu plodnu ovcu.\n                    </p>\n                    <p class=\"lesson-text\">\n                        Sva trojica su se ubrzo obogatila, tako da je prvi imao puno brdo deva, drugi brdo krava, a treći brdo ovaca. Nakon nekog vremena, melek je u svom prijašnjem liku i obliku došao gubavcu i rekao mu:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Ja sam siromašan čovjek, i ostao sam odsječen na svom putovanju, i niko mi nije u stanju danas pomoći osim Allah, pa onda ti. Zato te molim Onim Koji ti je dao tako lijepu boju i lijepu kožu, i toliki imetak, da mi dadneš jednu devu kako bih mogao nastaviti put. On mu na to reče:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Obaveze i izdaci su mi mnogobrojni. (Ne mogu ti pomoći.) Melek mu reče:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Kao da te ja odnekud znam. Da ti nisi bio onaj gubavac što se svijet zgražavao na njegov izgled i bijedu, pa ti je Allah podario (zdravlje i bogatstvo)? On mu tada odgovori:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Naprotiv, ja sam ovo naslijedio od svojih predaka. Melek mu tada reče:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Ako si mi slagao, neka te Allah vrati u ono stanje u kojem si bio.\n                    </p>\n                    <p class=\"lesson-text\">\n                        Zatim je melek u svom prijašnjem liku i obliku došao ćelavcu i rekao mu isto ono što je rekao i gubavcu, a ovaj mu je odgovorio isto kao i prvi. Melek mu reče:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Ako si mi slagao, neka te Allah vrati u ono stanje u kojem si bio.\n                    </p>\n                    <p class=\"lesson-text\">\n                        Zatim je melek u svom prijašnjem liku i obliku došao slijepcu i rekao mu:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Ja sam siromašan čovjek, i ostao sam odsječen na svom putovanju, i niko mi nije u stanju danas pomoći osim Allah, pa onda ti. Zato te molim Onim Koji ti je podario tvoj vid da mi daš jednu ovcu, kako bih se njome pomogao na svome putu. On mu odgovori:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – I ja sam bio slijep, pa mi je Allah povratio vid. Bio sam siromašan, pa me je Allah obogatio. Uzmi šta god želiš i ostavi šta god želiš! Tako mi Allaha, ja ti danas neću braniti da uzmeš bilo šta u ime Allaha, dž.š. Melek mu na to reče:\n                    </p>\n                    <p class=\"lesson-text\">\n                        – Zadrži svoj imetak! Samo si bio iskušan. Allah je zadovoljan tobom, a nije zadovoljan tvojim drugovima.\" (Buhari)\n                    </p>\n                </div>\n            </div>\n        </div>\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - OHOLOST</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Šta je oholost?</li>\n                    <li>Kako čovjek posrne u osobinu oholosti?</li>\n                    <li>Zbog čega se ljudi ohole?</li>\n                    <li>Koje primjere oholosti navodi Kur’an?</li>\n                </ol>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK!</span><br>\n                        Pročitajte i razgovarajte o hadisu: Trojica iskušanih.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":65,"is_published":true,"kviz_pitanja":[{"answer":"Odbijanje istine i ponižavanje ljudi","options":["Odbijanje istine i ponižavanje ljudi","Voljenje lijepe odjeće i obuće","Briga o svom izgledu i zdravlju","Želja za znanjem i obrazovanjem"],"question":"Šta je oholost prema Poslaniku, alejhis-selam?"},{"answer":"Iblis","options":["Faraon","Iblis","Nemrud","Karon"],"question":"Ko je bio prvi koji se uzoholio?"},{"answer":"Bogatstvo, porijeklo, znanje, ljepota, potomstvo","options":["Bogatstvo, porijeklo, znanje, ljepota, potomstvo","Samo bogatstvo i moć","Samo ljepota i mladost","Samo znanje i obrazovanje"],"question":"Koje su glavne uzroke oholosti kod ljudi?"},{"answer":"Potopljeni su u Crvenom moru","options":["Postali su bogatiji i moćniji","Potopljeni su u Crvenom moru","Ostali su u Džennetu","Dobili su još veću moć"],"question":"Što se dogodilo faraonu i Hamanu zbog oholosti?"},{"answer":"Bogatstvo je prolazno i nestaje","options":["Bogatstvo je vječno i trajno","Bogatstvo je prolazno i nestaje","Bogatstvo je najbolje na Sudnjem danu","Bogatstvo nikada ne postoji"],"question":"Koja je poruka za vjernike o dunjalučkom bogatstvu?"}]},{"nivo":3,"slug":"mrznja","naslov":"Mržnja i ljubomora","content_html":"<div class=\"lesson-container\">\n        <h1>MRŽNJA I LJUBOMORA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mrznja.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Mržnja i ljubomora</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje čistog srca, oslobođenog mržnje</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti opasnost mržnje i ljubomore</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika koje osvjetljavaju srce</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je mržnja? Da li je dobro nositi mržnju u srcu? Šta islam kaže?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mržnja je teška bolest srca — čini čovjeka nesretnim, ne dozvoljava mu mira.</p><p>Ljubomora (negativna) — sumnjičenje bez razloga, kontrolisanje drugih, ne želeći im sreću.</p><p>Allah u Kur’anu: \"...nemoj ostaviti ni najmanju mržnju u našim srcima prema onima koji vjeruju...\"</p><p>Posljedice: razdor u porodici, prekid prijateljstva, raspad zajednice.</p><p>Kako iskorijeniti mržnju: dova, oprost, sjećanje na zajedničke trenutke, dobra djela prema toj osobi.</p><p>Pravilna ljubomora: muž koji čuva ženu od harama, žena koja čuva muža — to nije bolesna ljubomora nego briga.</p><p>Poslanik, a.s.: \"Ne mrzite jedni druge, ne zavidite, ne okrećite leđa — budite, robovi Allahovi, braća.\"</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta uraditi da iskorijene mržnju. Zaključak: čisto srce = sretan život.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                OTROV KOJI NAGRIZA SRCE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Dragi moji, zamislite da u svom srcu nosite mali plamen ljubavi koji osvjetljava vaš put i grije ljude oko vas. Ali, ponekad se pojave dva hladna, mračna oblaka – mržnja i ljubomora – koji žele ugasiti to svjetlo. Mržnja je poput teškog tereta koji nas umara, a ljubomora je kao sjena koja nam ne dopušta da vidimo ljepotu u drugima. Danas ćemo naučiti kako prepoznati te kradljivce mira i zašto je važno čuvati čistoću svoje duše. Otkrit ćemo tajnu mudrog Lukmana o jeziku i srcu i naučiti kako toplim selamom i međusobnom ljubavlju možemo pobijediti svako zlo koje šejtan pokuša unijeti među nas.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Od zla šejtana napasnika koji zle misli unosi u srca ljudi. (En-Nas, 4-5)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Mržnja je jedna od negativnih ljudskih osobina koja se prvo javlja u srcima ljudi, a zatim se manifestira kroz ponašanje i usmjerena je ka onim osobama prema kojima se osjeća mržnja.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Mržnja je rezultat dugotrajne srdžbe prema nekoj osobi i želje da joj se učini zlo, bilo da se radi o rušenju njene časti i ugleda ili da se materijalno ošteti. Ona se obično javlja kada nismo u mogućnosti da nad tom osobom iskalimo svoju srdžbu. Često se dešava da nekoga mrzimo bez ikakva razloga i povoda što nikako nije dobro.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Šejtanova namjera i jeste da u srce vjernika ubaci mržnju i druge negativne osobine koje mogu biti povod lošeg odnosa prema drugima i koje narušavaju jedinstvo i slogu muslimana. Dužnost svakog muslimana je osujetiti došaptavanje šejtana i iz svog srca izbaciti i najmanji osjećaj mržnje. Radeći na čistoći duše i srca možemo se očuvati od bolesti mržnje.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: \"Dvije su bolesti ranijih naroda dopuzale do vas, a to su: zavidnost i mržnja. Mržnja je britva, ali ne britva koja brije dlaku, nego britva koja brije (tj. uništava) vjeru (onome koji druge ljude mrzi).\" (Tirmizi)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Mržnja može ovladati srcem pojedinca, ali i srcima zajednice muslimana. U prvom slučaju ona upropaštava vjeru pojedinca, a u drugom narušava slogu cijele zajednice. Posljedice mržnje su mnogobrojne, a tri su najčešće:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>uništava vjeru,</li>\n                    <li>unosi neslogu i razdor među muslimane – nešto najgore i najopasnije za zajednicu je da musliman od drugog muslimana okreće glavu,</li>\n                    <li>narušava zdravlje - kada osoba vođena mržnjom ne može ostvariti željeno, to se negativno odrazi na njeno zdravlje.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Vjernik se ne smije radovati tuđoj nesreći i govoriti kako mu je drago što je nekoga zadesilo nešto loše. Muhammed, alejhis-selam, savjetuje i kaže: \"Nećete ući u Džennet sve dok ne budete vjerovali, a nećete vjerovati sve dok se ne budete međusobno voljeli. Želite li da vas uputim šta da činite pa da se međusobno volite?! Nazivajte selam jedni drugima.\" (Muslim)\n                </p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">LJUBOMORA</p>\n\n                <p class=\"lesson-text\">\n                    Pored mržnje, veliku opasnost po čovjekov iman predstavlja i ljubomora. Ljubomora je ne samo grijeh, nego i jedna vrsta veoma opake duševne bolesti. Rađa se u srcu, a ako joj se da povoda uvodi čovjeka u djela koja su islamom zabranjena.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI: JEZIK I SRCE</span><br>\n                        Pripovijeda se da je mudri Lukman bio sluga kod nekog bogataša, te mu je naredio da zakolje ovcu i da iz nje izvadi dva najbolja organa. Kad ju je zaklao, Lukman je izvadio jezik i srce. Nakon toga ponovo mu je naredio da zakolje ovcu, ali da sada izvadi njena dva najgora organa, pa je Lukman ponovo zaklao ovcu i ponovo izvadio jezik i srce. Čudeći se njegovom postupku bogataš mu je rekao: \"Ja sam ti naredio da mi iz jedne ovce izvadiš dva najbolja organa i ti si izvadio jezik i srce, pa sam ti naredio da mi iz druge ovce izvadiš dva najgora organa, pa si opet izvadio jezik i srce - zašto si u oba slučaja izvadio jezik i srce?\" Lukman mu odgovori: \"Uistinu, nema ništa bolje od jezika i srca ako su dobri, niti ima išta gore od njih kada su pokvareni.\"\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - MRŽNJA I LJUBOMORA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Šta je mržnja?</li>\n                    <li>Koje su posljedice mržnje?</li>\n                    <li>Šta je ljubomora?</li>\n                    <li>Gdje nastaje ljubomora?</li>\n                </ol>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK:</span><br>\n                        Upiši riječi koje te asociraju na mržnju!\n                    </p>\n                </div>\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        • Osobine povezane s mržnjom i ljubomorom.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":66,"is_published":true,"kviz_pitanja":[{"answer":"Zle misli i napasti","options":["Dobre misli i ljubav","Zle misli i napasti","Vjeru i znanje","Radost i sreću"],"question":"Šta Allah kaže da unosi šejtan u srca ljudi?"},{"answer":"Uništava vjeru, unosi neslogu, narušava zdravlje","options":["Bogatstvo, bolest, tugu","Uništava vjeru, unosi neslogu, narušava zdravlje","Ljepotu, moć, ponos","Učenje, mudrost, rad"],"question":"Koja su tri najčešće posljedice mržnje prema Poslaniku?"},{"answer":"Britva koja uništava vjeru","options":["Britva koja brije dlaku","Britva koja uništava vjeru","Oštro mačem","Jakim zamrzavanjem"],"question":"Šta Poslanik, alejhis-selam, kaže da je mržnja?"},{"answer":"Radom na čistoći duše i srca","options":["Ignoriranjem drugih","Radom na čistoći duše i srca","Nošenjem amajlija","Često ljutnjom"],"question":"Kako se možemo zaštititi od bolesti mržnje?"},{"answer":"Kada vjeruju i međusobno se vole","options":["Samo kroz mnogo dua","Samo ako budu bogatim","Kada vjeruju i međusobno se vole","Ako budu najmudniji"],"question":"Kako će muslimani ući u Džennet prema Muhammadu, alejhis-selam?"}]},{"nivo":3,"slug":"neprijateljstvo","naslov":"Neprijateljstvo","content_html":"<div class=\"lesson-container\">\n        <h1>NEPRIJATELJSTVO</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/neprijateljstvo.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Neprijateljstvo i njegovo prevladavanje</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti pomirenja i izbjegavanja sukoba</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti štetnost neprijateljstva i kako ga prevladati</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje vještina pomirenja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta učinimo kad imamo svađu sa nekim? Nastavimo se mrzjeti ili se pomirimo? Islam preporučuje pomirenje.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Neprijateljstvo (‘adavet) — stalno loše osjećanje prema nekome, sa željom da mu se desi zlo.</p><p>Posljedice: razdor, gubitak prijatelja, mržnja se prenosi na djecu, gubi se Allahov bereket.</p><p>Allah u Kur’anu: \"Vjernici su braća — pomirite svoje dvije braće.\"</p><p>Pomirenje (sulh): inicijativa od jakeg, izvinjenje, oprost, zajednička dova, posjeta.</p><p>Poslanik, a.s.: \"Ne dozvoljava se muslimanu da prekida sa svojim bratom više od tri dana — ko prvi pozdravi, najbolji je.\"</p><p>Posebno opasno: neprijateljstvo u porodici, među komšijama, u džematu — kvari sve.</p><p>Najveće zlo neprijateljstva: srce zaboravlja Allaha jer je puno gnjeva.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju da pokušaju pomirenje sa nekim sa kim su u svađi. Zaključak: ko opraša prvi — pobjeđuje.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                MOSTOVI UMJESTO ZIDOVA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Dragi moji, zamislite da su naše riječi poput sjemenki koje sijemo u srca ljudi oko nas. Ako sijemo lijepe riječi, iz njih će izrasti cvijeće ljubavi i prijateljstva. Ali, šejtan uvijek vreba u sjeni, pokušavajući nas nagovoriti da posijemo sjeme ružnih riječi, sumnje i mržnje. To sjeme stvara zidove koje nazivamo neprijateljstvom. Danas ćemo naučiti kako prepoznati te šejtanske zamke i zašto je važno čuvati jedinstvo naše zajednice. Otkrit ćemo kako blagost i lijepa komunikacija mogu srušiti i najtvrđe zidove, čineći nas pravom braćom i sestrama koji se međusobno podržavaju i vole radi Allaha.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Reci robovima Mojim da govore samo lijepe riječi – jer bi šejtan mogao posijati neprijateljstvo među njima... (El-Isra, 53)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., je muslimane učinio zajednicom sredine, koja na Pravi put upućuje i opominje. Zbog te svoje uloge u društvu, zadaće od Uzvišenog Allaha, muslimani su izloženi stalnim napadima i neprijateljstvu jer je šejtanov naum da naudi onima koji nastoje živjeti islam. Neki od načina kojima šejtan unosi nemir i neprijateljstvo spomenuti su u suri El-Maide, u 91. ajetu: Šejtan želi da pomoću vina i kocke unese među vas neprijateljstvo i mržnju i da vas od sjećanja na Allaha i obavljanja molitve odvrati...\n                </p>\n\n                <p class=\"lesson-text\">\n                    Neprijateljstvo je izraz koji definira negativan odnos između dva ili više pojedinaca ili skupina. Onaj ko u svom srcu ima neprijateljstva nastoji obezvrijediti i poniziti drugoga i pred ljudima ga osramotiti, te istaknuti svoju prednost.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., odnos među muslimanima uređuje sljedećim kur’anskim ajetom: A vjernici i vjernice su prijatelji jedni drugima... (Et-Tevbe, 71). Taj odnos treba da bude pun samilosti i pažnje, strpljenja i potpomaganja. Allahova je mudrost i da muslimane međusobno učini braćom i sestrama, jer ljubav proistekla iz krvne veze s našim najbližima je obrazac ponašanja i prema našoj braći i sestrama u vjeri.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Međusobno neprijateljstvo je karakteristika onih koji su se Allahovim zakonima usprotivili i Allah, dž.š., će sve dok oni ne promijene svoj odnos, takvo stanje ostaviti. Međutim, musliman i muslimanka su svjesni šejtanskih napada, ali i napada ljudi koji im ne žele dobro i napredak. Mnogo opasniji problem jeste neprijateljstvo i nemir koji neki muslimani unose u zajednicu – džemat. Allah, dž.š., kaže: A zlostavljanje je teže od ubijanja. (El-Bekare, 191)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Velikom broju problema u zajednici uzrok je slaba ili nedorečena komunikacija, te nerazumijevanje, koji dodatno pogoršavaju stanje međuljudskih odnosa u džematu i zajednici.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Muslimani su dobri i plemeniti prema onima koji su prema njima takvi, neprijateljstvo ne pokazuju ni prema kome, a strogoću pokazuju prema onima koji to zaslužuju. Poštuju tuđe stavove i uvjerenja, ali brane i štite svoje vjerovanje i bratsku ljubav.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - NEPRIJATELJSTVO</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I RAZGOVOR <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je uzrok neprijateljstva prema muslimanima?</li>\n                    <li>Šta je neprijateljstvo?</li>\n                    <li>U čemu se ogleda odnos muslimana prema muslimanima i prema nemuslimanima?</li>\n                    <li>Koja vrsta neprijateljstva je najopasnija?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">RAZGOVOR S MUALLIMOM</p>\n                <ul class=\"lesson-text\">\n                    <li>“Drži prijatelje blizu, a neprijatelje još bliže.” (Sun Cu)</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":67,"is_published":true,"kviz_pitanja":[{"answer":"Govori samo lijepe riječi jer šejtan širi neprijateljstvo","options":["Govori samo lijepe riječi jer šejtan širi neprijateljstvo","Zabrana je govoriti o šejtanu i его djelima","Muslimani trebaju biti strogi prema svima","Vino i kocka su dozvoljeni u малим količinama"],"question":"Šta Allah, dž.š., kaže u ajetu iz sure El-Isra?"},{"answer":"Zajednicom sredine koja upućuje na Pravi put","options":["Zajednicom sredine koja upućuje na Pravi put","Najpametnijom grupom u svijetu","Narodom koji ne treba drugima","Ljudima koji se ne trebaju brinuti o drugima"],"question":"Kako je Allah učinio muslimane prema tekstu?"},{"answer":"Neprijateljstvo i mržnju kroz vino i kocku","options":["Neprijateljstvo i mržnju kroz vino i kocku","Čitanje knjiga i učenje","Molitve i sjećanje na Allaha","Mir i mir između braće i sestara"],"question":"Što šejtan želi da unese među muslimane?"},{"answer":"Puni samilosti, pažnje, strpljenja i potpomaganja","options":["Puni samilosti, pažnje, strpljenja i potpomaganja","Puni mržnje i zavisti prema drugima","Ozbiljni i strogi bez emocija","Samo među bogatim i moćnim ljudima"],"question":"Kako bi trebali biti međusobni odnosi muslimana?"},{"answer":"Slaba komunikacija i nerazumijevanje","options":["Slaba komunikacija i nerazumijevanje","Previše molitvi i čitanja Kur'ana","Previše ljubavi između braće i sestara","Nedostatak razvratnih utjecaja"],"question":"Šta je često uzrok problema u džematu?"}]},{"nivo":3,"slug":"droga","naslov":"Droga – štetnost i posljedice","content_html":"<div class=\"lesson-container\">\n        <h1>DROGA – ŠTETNOST I POSLJEDICE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/droga.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Droga – štetnost i posljedice</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje gnušanja prema drogama i navika izbjegavanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti štetnost droge sa zdravstvene, vjerske i društvene strane</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike da se odupru pritisku da uzmu drogu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je droga? Da li je dozvoljena u islamu? Apsolutno ne. Zašto?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Droga — sve supstance koje opijaju, mijenjaju svijest, stvaraju ovisnost (heroin, kokain, marihuana, ekstazi, sintetičke droge).</p><p>Islamski propis: <strong>haram</strong> — sve što opija je zabranjeno, kao i alkohol.</p><p>Hadis: \"Sve što opija u velikoj količini — i mala količina je haram.\"</p><p>Štetnost: <strong>zdravstvena</strong> (uništava mozak, pluća, jetru, srce); <strong>psihička</strong> (ovisnost, depresija, samoubistvo); <strong>društvena</strong> (gubitak posla, kriminal, raspad porodice); <strong>vjerska</strong> (ne klanja, sve više grijeha, smrt bez tevbe).</p><p>Pritisak: vršnjaci nude, pričaju da je \"cool\". Pravi prijatelj — onaj koji ne nudi haram.</p><p>Reakcija: jasno i odlučno NE; nema sredine; ne probati ni jednom.</p><p>Pomoć: roditelji, učitelji, doktor, zajednica — nikad ne sakrivati problem.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome kako reagirati ako neko ponudi drogu. Zaključak: NE drogi — DA životu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NAJVEĆI DAR KOJI TREBAMO ČUVATI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Dragi moji, zamislite da ste na poklon dobili najsavršeniji i najbrži računar na svijetu, koji može riješiti svaki zadatak i stvoriti najljepše slike. Taj \"računar\" je zapravo vaš mozak i vaše tijelo. To je blagodat koju nam je Allah, dž.š., darovao da bismo mogli istraživati svijet, učiti i pomagati drugima. Međutim, postoje stvari koje su poput opasnih virusa – jednom kada uđu u naš sistem, počnu kvariti sve što je lijepo, brišući naše misli i kradući nam snagu. Danas ćemo razgovarati o jednom takvom velikom zlu koje se zove droga. Naučit ćemo zašto je važno reći \"ne\" svemu što nam muti razum i kvari zdravlje, te kako čuvajući sebe zapravo zahvaljujemo našem Gospodaru na divnom životu koji nam je podario.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: O vjernici, vino (hamr) i kocka i kumiri i strelice za gatanje su odvratne stvari, šejtanovo djelo; zato se toga klonite da biste postigli što želite. (El-Maide, 90)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Općepoznato načelo islama jeste da zabranjuje sve što ima negativan utjecaj na ljudsko, fizičko i psihičko zdravlje. Budući da su medicina i iskustvo dokazali da upotreba različitih vrsta droga šteti ljudskom razumu i tijelu, zatim, da uzrokuje bolest ovisnosti te da dovodi do različitih oblika neislamskog i kriminalnog ponašanja, kategorički se zaključuje da je upotreba droge u bilo kojoj količini u islamu najstrožije zabranjena.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Drogom se smatraju razne materije koje čovjeka dovode u stanje opijenosti i nemogućnosti zdravog rasuđivanja. Razlog zabrane narkotičkih sredstava (naziv za sve vrste droga) je zbog njihove štetnosti i zato su izričito po islamskom učenju zabranjena.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Na upit o pojedinim vrstama nedopuštenih pića Poslanik, alejhis-selam, je odgovorio: “Sve što opija je hamr, a svaki hamr je haram.” (Muslim)\n                    </p>\n                    <p class=\"lesson-text\">\n                        Muhammed, alejhis-selam, je pojašnjavajući pojam hamr, rekao i ovo: “Hamr je ono što muti razum.” (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Mnogo raširenije korištenje droge danas u svijetu jeste veliko zlo. Islamsko učenje kaže da je ona haram – veliki grijeh, čije posljedice će se osjetiti na dunjaluku i na ahiretu. Dunjalučka kazna ogleda se u šteti koju onaj ko konzumira drogu nanosi u svim segmentima društva, a posebno sebi i svojoj porodici jer dovodi do:\n                </p>\n\n                <ul class=\"lesson-text\">\n                    <li>štetnosti po svoje i zdravlje porodice,</li>\n                    <li>uništavanja porodice,</li>\n                    <li>nanošenja štete psihičkom i fizičkom zdravlju potomstva,</li>\n                    <li>uništavanja porodičnog imetka,</li>\n                    <li>ulazak u kriminalni svijet iz kojeg se teško izbaviti bez posljedica,</li>\n                    <li>bavljenja kriminalnim radnjama,</li>\n                    <li>krivične sankcije za zloupotrebu droge, te druge kriminalne radnje itd.</li>\n                </ul>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Uzvišeni Allah kaže: ...i sami sebe u propast ne dovodite... (El-Bekare, 195)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Onaj ko krene putem zla konzumiranjem droge napravio je prvi korak ka ovisnosti. Život, od Allaha, dž.š., darovanu blagodat, moramo čuvati i u skladu s Njegovim uputama postupati. Svako nanošenje štete tijelu, životu, razumu, potomstvu, imetku, predstavlja zloupotrebu slobode koja nam je darovana kao jedna od najvećih blagodati.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Dimenzije ahiretske kazne nama nisu u detalje poznate, ali ono što sigurno znamo jeste da iskreno pokajanje (tevba) briše grijehe, pa time smanjuje i ahiretsku kaznu.\n                </p>\n                <img src=\"/edu/assets/images/droga1.jpg\" style=\"float: right; width: 250px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">\n                    Za razliku od savremenog zakonodavstva koje je uglavnom usmjereno na liječenje, islamsko pravo mnogo više pažnje posvećuje prevenciji konzumiranja droge, prije nego što dođe do bolesti ovisnosti. Ukoliko se zapadne u ovisnost, čovjekova obaveza je da se liječi. Izloženost upotrebi droge stvara kod čovjeka ovisnost koja ga tjera putem ponovnog konzumiranja ovog zla, tako da je taj proces moguće zaustaviti samo aktivnim liječenjem u ustanovama koje se bave tim slučajevima.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Sve rašireniju upotrebu droge danas u svijetu možemo posmatrati s aspekta cijene koju plaća savremeno čovječanstvo, a zbog pokušaja smanjenja uloge vjere i duhovnosti u životu čovjeka, zbog kršenja Allahovih propisa i nemarnog odnosa prema životu na dunjaluku, smatrajući ga prilikom za užitak i kušanje svega. Međutim, bavljenje posljedicama koje su nastale teško će biti iskorijenjena ova pošast. Onoga trenutka kad čovječanstvo shvati uzroke svih devijantnih ponašanja i počne poštivati vrijednosti vjere i Allahovih, dž.š., propisa, lakše će se nositi s ovakvim i sličnim problemima.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        Diler će pokušati da vam ponudi da probate drogu besplatno. Kasnije će vam skupo naplaćivati svaku dozu, samo da bi zaradio novac, i uništio tvoj život.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - DROGA: ŠTETNOST I POSLJEDICE</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Šta se smatra drogom?</li>\n                    <li>Koji je razlog zabrane upotrebe droge za muslimane?</li>\n                    <li>U kojem slučaju droga može biti dozvoljena muslimanu?</li>\n                    <li>U čemu se ogleda štetnost konzumiranja droge za pojedinca i zajednicu?</li>\n                </ol>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK:</span><br>\n                        Istražite i primjerima objasnite posljedice konzumiranja droge!\n                    </p>\n                </div>\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        • Preventivno djelovanje i kako se zaštititi od narkotika.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":68,"is_published":true,"kviz_pitanja":[{"answer":"Vino, kocka, kumiri i strelice za gatanje","options":["Vino, kocka, kumiri i strelice za gatanje","Samo vino i alkoholna pića","Samo kocka i igre na sreću","Samo kumir i religijske ceremonije"],"question":"Šta Allah kaže je šejtanovo djelo u ajetu El-Maide 90?"},{"answer":"Sve što opija i muti razum","options":["Sve što opija i muti razum","Samo vino od grožđa","Samo jaka alkoholna pića","Samo medicinska sredstva"],"question":"Što znači riječ 'hamr' prema islamu?"},{"answer":"Štetnost za zdravlje i razum","options":["Štetnost za zdravlje i razum","Skupoća droge na tržištu","Samo zabrana mladima i djeci","Samo u mjesecu Ramazanu"],"question":"Koja je glavna razina zabrane droge u islamu?"},{"answer":"Šteta zdravlju, uništenje porodice i kriminalni svijet","options":["Šteta zdravlju, uništenje porodice i kriminalni svijet","Samo financijske probleme","Samo osjetljive oči i glavobolju","Samo društvenu neprihvaćenost"],"question":"Koje posljedice donosi upotreba droge prema lekciji?"},{"answer":"Haram – najstrože zabranjena","options":["Haram – najstrože zabranjena","Makruh – nepoželjna ali dozvoljena","Halal – dozvoljeno sa ograničenjima","Mubah – slobodno dozvoljena"],"question":"Što je prema islamu upotreba droge u bilo kojoj količini?"}]},{"nivo":3,"slug":"alkohol","naslov":"Alkohol i alkoholna pića","content_html":"<div class=\"lesson-container\">\n        <h1>ALKOHOL I ALKOHOLNA PIĆA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/alkohol.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Alkohol i alkoholna pića</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje gnušanja prema alkoholu i navika potpunog izbjegavanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamski stav o alkoholu i njegovu štetnost</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike da se odupru pritisku da konzumiraju alkohol</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je alkohol? Da li je u islamu dozvoljen? Ne — Allah ga je apsolutno zabranio. Zašto?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Alkohol (hamr) — sve što opija; vino, pivo, žestoka pića.</p><p>Allah u Kur’anu: \"O vjernici, doista su vino, kockanje, idoli i strelice za gatanje gnusno djelo šejtanovog posla — sklanjajte se od toga, da biste uspjeli!\"</p><p>Haram je: piti, prodavati, kupovati, prevoziti, posluživati, sjediti za stolom gdje se pije.</p><p>Štetnost: <strong>zdravlje</strong> (jetra, mozak, srce); <strong>porodica</strong> (nasilje, razvodi); <strong>društvo</strong> (saobraćajne nesreće, kriminal); <strong>vjera</strong> (zaboravlja se Allah, izostavlja namaz).</p><p>Hadis: \"Vino je majka svih grijeha — ko ga pije, neka mu Allah ne primi namaz 40 dana.\"</p><p>Pritisak društva: nemoralna kultura kaže da je piće \"normalno\" — mi znamo da nije.</p><p>Reakcija: jasno NE, prijateljski objasniti zašto, ne osuđivati ali ne miješati se.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome kako se odupru pritisku. Zaključak: čisto srce + čista glava = jasna budućnost.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                MAJKA SVIH ZALA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Postoji jedna stara mudrost koja kaže da je alkohol poput ključa koji otvara vrata svakom drugom grijehu. Kada čovjek dozvoli da mu piće pomuti razum, on gubi kontrolu nad svojim riječima i postupcima, a ono što je gradio godinama može srušiti u samo jednoj noći. Zamislite bistru planinsku rijeku koja odjednom postane mutna i prljava – tako alkohol djeluje na ljudsku svijest. Naš Poslanik, alejhis-selam, nije ga uzalud nazvao \"majkom svih zala\", jer tamo gdje uđe alkohol, izlaze stid, pamet i mir. Danas ćemo istražiti kako je Kur'an, korak po korak, čistio društvo od ove opasne ovisnosti i zašto je potpuna sloboda zapravo život u kojem nam razum ostaje čist i spreman za dobra djela.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: O vjernici, vino i kocka i kumiri i strelice za gatanje su odvratne stvari, šejtanovo djelo; zato se toga klonite da biste postigli što želite. Šejtan želi da pomoću vina i kocke unese među vas neprijateljstvo i mržnju i da vas od sjećanja na Allaha i od obavljanja molitve odvrati. Pa, hoćete li se okaniti? (El-Maide, 90-91)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Svim šerijatskim propisima je jedan od ciljeva formiranje umno i fizički zdravih pojedinaca, kao i društva u cjelini. Ovaj cilj definiran je i zaštitom nepovredivih vrijednosti u islamu: vjere, života, razuma, časti i potomstva, te imovine. S obzirom na to da alkohol, kao i većina drugih savremenih pošasti ima negativan utjecaj na sve ove vrijednosti, Poslanik, alejhis-selam, ga je nazvao \"majkom svih zala\".\n                </p>\n\n                <p class=\"lesson-text\">\n                    Konzumiranje vina i alkoholnih pića bilo je veoma rašireno kod predislamskih Arapa, pa je Allah, dž.š., iz svoje neizmjerne mudrosti, poznavajući kakvo je alkohol zlo, objavljujući Kur'an, postepeno ukidao upotrebu alkohola. Ova činjenica nam govori o njegovoj raširenosti i ukorijenjenosti, te težini liječenja od ovog zla. Zbog toga nam ovaj kur'anski princip može pomoći ne samo u liječenju od alkoholizma (bolest nastala kao rezultat ovisnosti o alkoholu), nego i drugih pošasti s kojima se suočava naše društvo.\n                </p>\n                <img src=\"/edu/assets/images/alkohol3.jpg\" style=\"float: left; width: 250px; margin-left: 10px; margin-right: 10px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">\n                    Kur'anska postepenost nas uči da je bilo koja ovisnost teško zdravstveno stanje i da joj se mora s velikom pažnjom pristupiti. A s obzirom na to da nam je namjera liječenje, koristit ćemo kur'anske upute koje su dovele do liječenja predislamskih Arapa od ovisnosti alkoholizma.\n                </p>\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">KUR'ANSKE FAZE UKIDANJA ALKOHOLA:</p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">a) Pretpripremna faza</span><br>\n                    U ajetu koji slijedi, alkoholna pića se odvojeno spominju od \"hrane prijatne\", što mudro ukazuje na izdvajanje iz dozvoljenog, te da nisu dobra. Allah, dž.š., kaže: A od plodova palmi i loze pripremate piće i hranu prijatnu. (En-Nahl, 67)\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">b) Prva faza</span><br>\n                    Pripreme terena za sljedeću fazu zabrane upotrebe alkohola, kojom se alkohol stavlja u ravan sa štetnim stvarima, te utječe na svijest čovjeka koji misli o svom zdravlju: Pitaju te o vinu i kocki. Reci: \"Oni donose veliku štetu, a i neku korist ljudima, samo je šteta od njih veća od koristi.\" (El-Bekare, 219)\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">c) Druga faza</span><br>\n                    Ova faza zabrane alkohola se tiče obavljanja namaza, ali i pored toga što sadrži izričitu zabranu, ne radi se o apsolutnoj zabrani alkohola nego samo o uvodu u sljedeću fazu zabrane: O vjernici, pijani nikako molitvu ne obavljajte, sve dok ne budete znali šta izgovarate... (En-Nisa, 43)\n                </p>\n\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4;\">d) Treća faza</span><br>\n                    Apsolutna zabrana konzumiranja alkohola koja je naređena i istaknuta u 90. i 91. ajetu sure El-Maide. Allah, dž.š., kaže: O vjernici, vino i kocka i kumiri i strelice za gatanje su odvratne stvari, šejtanovo djelo; zato se toga klonite da bistepostigli što želite. Šejtan želi da pomoću vina i kocke unese među vas neprijateljstvo i mržnju i da vas od sjećanja na Allaha i od obavljanja molitve odvrati. Pa, hoćete li se okaniti? (El-Maide, 90-91)\n                    <img src=\"/edu/assets/images/alkohol_10.jpg\" style=\"float: right; width: 100%; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                </p>\n                </br>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allahov Poslanik, alejhis-selam, je prokleo deset osoba koje imaju doticaja s opojnim pićima: proizvođača, naručioca proizvodnje, konzumenta, distributera, skladištara, poslužitelja, prodavca, korisnika zarade, onoga ko ga kupuje i kome se kupuje. (Tirmizi)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Kako je svaki doticaj s alkoholom zabranjen, tako se muslimanu savjetuje da izbjegava sve skupove i mjesta u kojima se poslužuje ili nalazi alkohol. Muhammed, alejhis-selam, je rekao: \"Ko vjeruje u Allaha i Sudnji dan neka ne sjeda za stol na kome kruže čaše s alkoholnim pićima.\" (Ahmed)\n                </p>\n                <img src=\"/edu/assets/images/alkohol2.jpg\" style=\"float: right; width: 250px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">\n                    Nije rijedak slučaj među muslimanima u Bosni i Hercegovini da, iako ne konzumiraju alkoholna pića, ista prodaju i drže u svojim kućama, prodavnicama, hotelima, te hraneći porodice sredstvima stečenim na haram način uzrokuju da ih zahvati prokletstvo shodno navedenom hadisu Poslanika, alejhis-selam\n                </p>\n\n                <p class=\"lesson-text\">\n                    Također, zabrana je kategorična i kad je u pitanju upotreba alkohola u svrhu liječenja. Poslanik, alejhis-selam, je rekao: \"Allah je dao i bolest i lijek, pa se liječite, ali ne zabranjenim stvarima.\" (Ebu Davud)\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Alkohol je veliko zlo i veliki grijeh i zato izbjegavaj sve što ima veze s alkoholom.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ALKOHOL I ALKOHOLNA PIĆA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Koje vrijednosti islam štiti, a alkohol na njih štetno djeluje?</li>\n                    <li>Opiši kur'anske faze zabrane alkohola!</li>\n                    <li>Kojih deset osoba je Poslanik, alejhis-selam, prokleo u vezi s alkoholom?</li>\n                    <li>Da li je alkohol dozvoljeno koristiti kao lijek?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ul class=\"lesson-text\">\n                    <li>Pozvani ste na zabavu svojih prijatelja, a svjesni ste da će biti posluživano alkoholno piće. Kako postupiti? Napišite svoj odgovor i posavjetujte se s muallimom.</li>\n                    <li>U svojoj bližoj porodici ste uočili nekoga ko konzumira alkohol. Šta ćete učiniti i kako postupiti? Kako i kojim riječima s njima razgovarati? Opišite svoj postupak.</li>\n                    <li>Šta učiniti kada te roditelj pošalje da kupiš alkoholno piće? Napiši i obrazloži!</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":69,"is_published":true,"kviz_pitanja":[{"answer":"Majkom svih zala","options":["Majkom svih zala","Zlo od šejtana","Bolest duše","Zabranjeno pće"],"question":"Kako je Poslanik, alejhis-selam, nazvao alkohol?"},{"answer":"Unese neprijateljstvo i mržnju među ljude","options":["Unese neprijateljstvo i mržnju među ljude","Učini nas bogatima","Ojača našu vjeru","Nauči nas mudrostima"],"question":"Šta Šejtan želi da učini pomoću vina i kocke?"},{"answer":"Vjera, život, razum, čast i potomstvo","options":["Vjera, život, razum, čast i potomstvo","Novac, kuća, auto, hljeб i voda","Znanje, zdravlje, porodica, rad i mir","Boja, oblik, zvuk, miris i okus"],"question":"Kojih pet nepovredivih vrijednosti štiti šerijat?"},{"answer":"Postepeno kroz Kur'an","options":["Postepeno kroz Kur'an","Odjednom početkom islama","Nigdje ga nije zabranjivao","Preko svetih žena"],"question":"Kako je Allah, dž.š., ukidao upotrebu alkohola?"},{"answer":"Alkoholizam","options":["Alkoholizam","Groznica","Astma","Šećerna bolest"],"question":"Koja je bolest nastala kao rezultat ovisnosti o alkoholu?"}]},{"nivo":3,"slug":"duhan","naslov":"Duhan – upotreba i njegova štetnost","content_html":"<div class=\"lesson-container\">\n        <h1>DUHAN – UPOTREBA I NJEGOVA ŠTETNOST</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/duhan.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Duhan – upotreba i njegova štetnost</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o štetnosti duhana i navike izbjegavanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti štetnost cigareta sa zdravstvene i vjerske strane</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike da nikad ne počnu pušiti</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li ste vidjeli ljude koji puše? Kako izgledaju? Šta islam kaže o duhanu?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Duhan/cigarete sadrže nikotin (otrov) i preko 4000 štetnih supstanci.</p><p>Islamski propis: <strong>haram</strong> ili u najmanju ruku <strong>mekruh tahrimi</strong> (jako pokuđeno) — uništava zdravlje i baca novac uludo.</p><p>Pravilo: \"Sve što šteti tijelu i imetku — Allah ne dozvoljava.\"</p><p>Štetnost: rak pluća, srčane bolesti, prerana smrt, žute zube, smradan dah, smradna odjeća, šteta porodici (pasivno pušenje).</p><p>Ekonomska šteta: pušač potroši hiljade KM godišnje na cigarete — taj novac mogao bi ići za hadž, sadaku, edukaciju.</p><p>Začarani krug: počne se \"iz znatiželje\", brzo postane ovisnost, teško se ostavlja.</p><p>Najbolji način: <strong>nikad ne početi</strong>. Ako neko puši — odmah ostaviti, makar uz pomoć doktora i dove.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju da nikad neće početi pušiti. Zaključak: bistre pluća = jasan život.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                DIM KOJI KRADE ZDRAVLJE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Svi volimo osjećaj svježeg zraka u plućima nakon kiše ili u gustoj šumi. Naše tijelo je savršen mehanizam koji nam je povjeren na čuvanje, a pluća su motor koji pokreće svaki naš pokret. Ipak, čovjek često iz čiste dosade ili želje da izgleda \"odraslije\" posegne za nečim što taj mehanizam kvari – duhanom. Ono što počne kao jedna cigareta, brzo se pretvara u lanac ovisnosti koji guši i tijelo i novčanik. Danas ćemo istražiti zašto islam, iako se duhan ne spominje direktno imenom u Kur'anu, jasno upozorava na štetne navike koje nas vode u propast. Naučit ćemo da naša odgovornost nije samo prema sebi, već i prema ljudima oko nas koji nezasluženo udišu naš dim.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I imetak na Allahovom putu žrtvujte, i sami sebe u propast ne dovodite, i dobro činite – Allah, zaista, voli one koji dobra djela čine. (El-Bekare, 195)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Savremena medicinska otkrića dokazuju da duhan u velikoj mjeri šteti ljudskom zdravlju i ugrožava njegovu okolinu.\n                    </p>\n                    \n                <p class=\"lesson-text\">\n                    Općepriznato islamsko načelo je da zabranjuje sve što šteti ljudskom organizmu, a za duhan kao i za droge, ne postoji imenična kur'anska zabrana, pa se zabrana njegovog konzumiranja izvodi iz štete koju nanosi. Nadalje, medicina potvrđuje da duhan izaziva bolest ovisnosti koja je u suprotnosti s islamskim principima.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Štetne posljedice izazvane duhanom su mnogobrojne za pojedinca, a i za zajednicu. Neke od štetnih posljedica za zdravlje su:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>skraćuje životni vijek,</li>\n                    <li>gubitak kose,</li>\n                    <li>bolesti očiju (mrena),</li>\n                    <li>ubrzano starenje,</li>\n                    <li>slabljenje sluha,</li>\n                    <li>teža oboljenja kože,</li>\n                    <li>kvarenje zuba i loša higijena usta,</li>\n                    <li>bolesti srca, kostiju i želuca i mnoge druge.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Pušač nanosi ogromu štetu zdravlju onih u čijem društvu konzumira duhan. Što je vrijeme provedeno u konzumaciji duhana duže, to je i štetnost djelovanja veća. Posebno ukazujemo na štetu koja se nanosi porodici, prvenstveno djeci dok roditelji pušači vrijeme tokom dana provode sa svojom djecom.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Istraživanjima se došlo do zaključaka da takozvano pasivno pušenje (boravak u društvu pušača) nanose istu, ako ne i veću, štetu nepušaču nego onome ko konzumira duhan. Posebno velika šteta se nanosi djetetu u utrobi majke ukoliko se nađe u stanju aktivnog, ali i pasivnog pušača.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Islam dozvoljava uživanje u granicama šerijatskih propisa, međutim korištenje duhana se može protumačiti i kao luksuziranje – odnosno prelaženje granica normalnog uživanja u životu. Konzumiranje duhana, pored zdravstvene, uglavnom nanosi i materijalnu štetu pojedincu i samoj porodici. Luksuz u životu muslimana je nešto što treba izbjeći, pogotovo ukoliko je čovjek u potrebi da zadovolji osnovne životne i porodične potrebe, poput kupovine zdrave hrane za prehranu porodice.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Što se tiče boravka u društvu ili dolaska u džemat osoba koje konzumiraju duhan, pokuđeno je dolaziti na takve skupove ukoliko je neugodan miris duhana intenzivan da uznemirava prisutne ili klanjače.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Muslimani i muslimanke se trebaju kloniti svega što šteti njihovom zdravlju, porodici, imetku i časti. Stoga, ukoliko ih zadesi bolest ovisnosti o duhanu, oni moraju tražiti lijeka. Zbog toga je bitno poznavati štetne posljedice koje duhan nanosi kako bismo preventivno djelovali na sebe i svoju okolinu.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Duhan šteti zdravlju pušača i onih koji su u njihovom društvu. Istraživanja pokazuju da je život pušača kraći od života nepušača.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - DUHAN I NJEGOVA ŠTETNOST</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Na osnovu čega se izvodi zabrana konzumiranja duhana?</li>\n                    <li>Koje su štetne posljedice konzumiranja duhana za pojedinca?</li>\n                    <li>Navedite neke od štetnih posljedica pušenja po okolinu (djeca, porodica)!</li>\n                    <li>Kakav je stav islama o prisustvu pušača u džematu i društvu?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADATAK</p>\n                <ul class=\"lesson-text\">\n                    <li>U oblačiće upišite riječi koje vas asociraju na duhan!</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":70,"is_published":true,"kviz_pitanja":[{"answer":"Islam ih zabranjuje jer štete organizmu","options":["Naredba je da ih konzumiramo","Islam ih zabranjuje jer štete organizmu","Kur'an kaže da su korisne","Samo stariji ljudi smiju ih koristiti"],"question":"Šta Kur'an kaže o stvarima koje štete našem zdravlju?"},{"answer":"Skraćuje životni vijek i nanosi bolesti","options":["Čini nas pametnijima","Skraćuje životni vijek i nanosi bolesti","Poboljšava vid i sluh","Jača kosti i zube"],"question":"Koja je glavna štetna posljedica duhana za ljudski organizam?"},{"answer":"Djeca i trudnice","options":["Samo odrasle osobe","Djeca i trudnice","Samo pušači","Nitko nije oštećen"],"question":"Ko je posebno oštećen pasivnim pušenjem po lekciji?"},{"answer":"Trebamo izbjeći luksuz u životu","options":["Naredba je da luksuziramo","Trebamo izbjeći luksuz u životu","Luksuz je najbolji dio vjere","Nema granica za uživanje"],"question":"Šta Islam kaže o luksuziranju i prelasku granica uživanja?"},{"answer":"Materialnu štetu","options":["Nikakvu štetu","Samo duhovnu štetu","Materialnu štetu","Samo emocionalnu štetu"],"question":"Kakvu štetu duhan nanosi porodici osim zdravstvene?"}]},{"nivo":3,"slug":"nemoral","naslov":"Nemoral – blud, čuvanje i posljedice","content_html":"<div class=\"lesson-container\">\n        <h1>NEMORAL – BLUD, ČUVANJE I POSLJEDICE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/nemoral.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Nemoral – blud, čuvanje i posljedice</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o čuvanju časti i izbjegavanju nemorala</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamski stav o nemoralu (zinā) i čuvanju časti</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike da čuvaju čast u savremenom svijetu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco (s obzirom na uzrast), danas učimo o jednoj važnoj temi — čuvanju časti. Allah nas je naučio kako se čuvati nemorala.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Zinā (blud) — vanbračni intimni odnos; jedan od najvećih grijeha u islamu.</p><p>Allah u Kur’anu: \"I ne približavajte se bludu — to je odvratno djelo i loš put!\"</p><p>Allah ne kaže \"Ne činite blud\" nego \"Ne približavajte se\" — sve što vodi ka njemu je zabranjeno: pogled na haram, sumnjivo druženje, intimni razgovori, gledanje pornografije.</p><p>Štete: <strong>vjerska</strong> (veliki grijeh, gubi se iman); <strong>društvena</strong> (raspad porodice, vanbračna djeca); <strong>zdravstvena</strong> (polno prenosive bolesti); <strong>psihička</strong> (krivica, depresija).</p><p>Čuvanje časti: spuštanje pogleda, izbjegavanje samoće sa suprotnim spolom (osim mahrema), pristojno odijevanje, izbjegavanje sumnjivih mjesta i sadržaja, post i ibadet.</p><p>Brak je legitimno mjesto za intimne odnose — Allah je dao halal način.</p><p>Pokajanje: ako se desio grijeh, vrata tevbe su otvorena — Allah prima iskreno pokajanje.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o izazovima čuvanja časti danas. Zaključak: čista čast — najveće blago.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                ČEDNOST KAO ŠTIT <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>U svijetu koji često briše granice između onoga što je pristojno i onoga što je razvrat, očuvanje vlastitog dostojanstva i čestitosti postaje najveći izazov. Islam ne posmatra moral samo kao skup pravila, već kao tvrđavu koja štiti srce, porodicu i cijelo društvo od propadanja. Svaki korak, pogled ili riječ koju uputimo, gradi put ka našoj budućnosti – ili onaj koji donosi mir i poštovanje, ili onaj koji vodi u nemir i gubljenje ljudskosti. Danas ćemo istražiti zašto nas vjera upozorava na opasnosti bluda i kako preventivnim djelovanjem možemo sačuvati čistoću duše u vremenu velikih iskušenja.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I što dalje od bluda, jer je to razvrat, kako je to ružan put. (El-Isra, 32)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., je ranije narode uništavao zbog grijeha koje su činili, a neke od njih zbog grijeha nemorala i bluda. Kur'ansko kazivanje o Lutu, alejhis-selam, nam govori da je njegov narod uništen zbog moralne izopačenosti u koju su zalutali.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Svi Allahovi poslanici su živjeli čednim i moralnim životom i nas su učili tome. Allah, dž.š., je u Kur'anu objavio nekoliko šerijatskih propisa koji štite moralni život i potomstvo, propisujući kazne za one koji ih se ne pridržavaju. Tako je Allah, dž.š., propisao brak, a Poslanik, alejhis-selam, ga ustanovio kao svoju pritvrđenu praksu, koja garantira moralan i čedan život, te dobro i odgojeno potomstvo.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Blud (arapski: zinaluk) je svaki vid zabranjenog spolnog odnosa između muškarca i žene. A teži oblik nemoralnosti od bluda, je prostitucija koja predstavlja organizirani oblik vanbračnih spolnih odnosa pri čemu osobe uključene u taj grijeh stječu materijalnu (novčanu) korist.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Osim što je zabranio blud u svim njegovim oblicima i formama, islam je zabranio i sve predradnje i djela koja mogu voditi ovome grijehu ili poticati na njega. Jedan od mehanizama zaštite od nemoralnog života jesu Poslanikove, alejhis-selam, riječi: “Ko vjeruje u Allaha i Sudnji dan neka se nipošto ne osamljuje sa ženom bez njezina pratioca (mahrema), jer je onda s njima u društvu šejtan.” (Ahmed)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Također, Poslanik, alejhis-selam, je upozorio na sve korake koji vode činjenju bluda, poput pogleda i riječi koje mogu izazvati buđenje strasti: “Oči mogu činiti blud, ruke i noge također, a sve to potvrdit će spolni organ.” (Buhari)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Posebno teški oblici nemorala koji datiraju još iz davnih vremena, a danas doživljavaju svoju ponovnu promociju, su javno činjenje nemorala i homoseksualizam. Musliman treba znati da je svaki oblik nemorala zabranjen i da ga se mora kloniti, drugima ukazivati na njegovu štetnost, te riječima osuditi takve postupke.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Islam nas upozorava na štetne posljedice nemoralnog života koje će se osjetiti na ovom i na budućem svijetu. Kazna na budućem svijetu će biti mnogo teža, te se stoga treba pokajati za svaki ružan postupak koji se može povezati s nemoralom.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Klonite se bluda, jer on donosi šest posljedica: tri na ovome svijetu, a tri na ahiretu. Na ovome svijetu blud uklanja ozarenost i produhovljenost, donosi siromaštvo i smanjuje životni vijek. A posljedice bluda na ahiretu su: Allahova srdžba, težak obračun i vječna džehennemska vatra.” (Bejheki)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Posljedice nemorala se protežu na kompletno društvo, zato je uloga svih nas da odgajamo moralne potomke, a nemoral koji vidimo da sprečavamo. Zakonodavstvo (i društvo u cjelini) koje dozvoljava blud, tolerira pornografiju, zabranjuje ali blago kažnjava silovanje i prostituciju ne može biti uspješno u borbi protiv ovih društvenih zala i velikih grijeha. Zbog toga islam oštro osuđuje svaki oblik nemorala i djeluje preventivno na svaku pojavu nemoralnog života. Jedino na takav način se društvo može izboriti s ovim zlom koje nanosi ogromne štete čovječanstvu.\n                </p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">TAKOĐER, TREBA ZNATI I SLJEDEĆE:</p>\n                <ol class=\"lesson-text\">\n                    <li>Kazna za blud na dunjaluku regulirana je šerijatskim propisima, a na ahiretu je to isključivo Allahovo pravo, osim ako se On ne smiluje.</li>\n                    <li>Borba protiv prostitucije, silovanja i sličnih negativnosti ne može biti uspješna ukoliko se ovom problemu pristupi jednostrano i nesistematično.</li>\n                    <li>Posebno značajnu ulogu u borbi protiv nemorala imaju mediji, školske ustanove, vjerske zajednice, zakonodavni organi, sudstvo i tužilaštvo, policija i drugi državni organi.</li>\n                    <li>Društvo mora početi osuđivati nemoralno ponašanje u svakom njegovom i najmanjem obliku, a promicati moral i moralno ponašanje.</li>\n                </ol>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Islam zabranjuje sve što vodi bludu, a roditelji su dužni da svoju djecu lijepo odgajaju i usmjeravaju islamskom moralu. Zato, mladiću i djevojko, vodite računa o čednosti i moralu!\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - NEMORAL I BLUD</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <ol class=\"lesson-text\">\n                    <li>Kojom institucijom islam štiti muslimana od nemoralnog života?</li>\n                    <li>Šta takav moralni život osigurava?</li>\n                    <li>Koje su to dunjalučke i ahiretske kazne za nemoralan život?</li>\n                    <li>Kakav odnos musliman treba imati prema nemoralu? Opišite!</li>\n                    <li>Na koji način nas islam štiti od nemoralnog života?</li>\n                </ol>\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK:</span><br>\n                        Svijet se suočava s problemom nemorala, ali ne može pronaći način kako da mu se odupre. Koji su razlozi velikog broja silovanja u svijetu?\n                    </p>\n                </div>\n                <div class=\"info-box\" style=\"margin-top: 20px;\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        • Preventivno djelovanje protiv nemorala.<br>\n                        • Šerijatske kazne za blud.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":71,"is_published":true,"kviz_pitanja":[{"answer":"Svaki zabranjen spolni odnos između muškarca i žene","options":["Svaki zabranjen spolni odnos između muškarca i žene","Samo brak bez dozvole roditelja","Razgovor sa nepoznatom osobom","Nošenje lijepe odjeće"],"question":"Šta je blud prema islamskom učenju?"},{"answer":"Garantira moralan i čedan život i dobro potomstvo","options":["Garantira moralan i čedan život i dobro potomstvo","Omogućava bogatstvo i moć","Oslobađa od obaveza prema roditeljima","Dozvoljava slobodno ponašanje"],"question":"Koja je glavna svrha braka u islamu?"},{"answer":"Organizirani oblik vanbračnih odnosa radi zarade novca","options":["Organizirani oblik vanbračnih odnosa radi zarade novca","Rad u ugostiteljskoj industriji","Nošenje ukrasnog nakita","Putovanje u strane zemlje"],"question":"Šta je prostitucija prema tekstu?"},{"answer":"Sve predradnje i djela koja mogu voditi grijehu","options":["Sve predradnje i djela koja mogu voditi grijehu","Samo čitanje knjiga","Samo slušanje muzike","Samo putovanje"],"question":"Koje radnje islam zabranjuje pored samog bluda?"},{"answer":"Kloniti se je, upozoriti druge i osuditi je riječima","options":["Kloniti se je, upozoriti druge i osuditi je riječima","Ignorisati je i ne razgovarati o njoj","Prihvatiti je kao dio života","Pomagati drugima da je čine"],"question":"Kako se musliman treba ponašati prema nemoralnosti?"}]},{"nivo":3,"slug":"internet-ovisnost","naslov":"Ovisnost o internetu","content_html":"<div class=\"lesson-container\">\n        <h1>OVISNOST O INTERNETU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/internet.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ovisnost o internetu i ekranima</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje umjerenosti u korištenju tehnologije</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti opasnost prekomjernog korištenja interneta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike pravilnog korištenja tehnologije</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko vremena dnevno provodite na telefonu, igricama, društvenim mrežama? Da li smo svjesni opasnosti?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Internet i tehnologija su Allahova blagodat — ali kao i sve, mogu biti i blagodat i kletva, ovisno o korištenju.</p><p>Ovisnost o internetu — kad ne možemo bez ekrana, kad se nervira ako nas isključi, kad gubimo vrijeme na bezvrijedni sadržaj.</p><p>Štetnosti: gubljenje vremena (vrijeme = život), pad učenja, oslabljen vid, nedostatak fizičke aktivnosti, izolacija od porodice, izloženost neprimjernom sadržaju (pornografija, nasilje, ateistička propaganda).</p><p>Posebne opasnosti: cyberbullying, kontakt sa nepoznatima, dijeljenje ličnih podataka, prevara.</p><p>Zdravo korištenje: ograničiti vrijeme (npr. 1 sat dnevno za zabavu), birati korisni sadržaj (Kur’an, predavanja, znanost), nikad u krevetu prije spavanja, telefon na \"do not disturb\" tokom učenja i namaza.</p><p>Test: ako ne možeš jedan dan bez telefona — to je problem.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici planiraju \"digitalni detoks\" za jedan dan. Zaključak: vladaj telefonom, ne dozvoli da telefon vlada tobom.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NEVIDLJIVE MREŽE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Živimo u vremenu kada nam je cijeli svijet na dlanu, udaljen samo jedan klik. Internet nam omogućava da učimo, istražujemo i ostanemo u kontaktu s ljudima širom planete. Međutim, ta ista mreža može postati nevidljiva zamka ako nismo oprezni. Jeste li ikada primijetili kako sati prolete dok gledate video snimke ili igrate igrice, dok pravi život prolazi pored vas? Kada nam Wi-Fi postane važniji od razgovora s prijateljem koji sjedi pored nas, to je znak da digitalni svijet počinje upravljati nama. Danas ćemo naučiti kako koristiti tehnologiju kao alat, a ne kao gospodara, i zašto je važno sačuvati svoje vrijeme i zdravlje za stvari koje zaista vrijede.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Iskoristi pet stvari prije nego dođe drugih pet: mladost prije starosti, zdravlje prije bolesti, bogatstvo prije siromaštva, slobodno vrijeme prije zauzetosti i život prije smrti.” (El-Hakim)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Savremeno doba je sa sobom donijelo mnoštvo korisnih stvari, ali i onih koje donose štetu pojedincu i zajednici. Jedna od njih je ovisnost o internetu, posebno društvenim mrežama.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ovisnost se definira kao pojava pretjeranog korištenja interneta koje narušava fizičko i/ili psihičko zdravlje te uzrokuje poteškoće u društvenom funkcioniranju čovjeka. Sve je učestalija pojava komunikacije putem interneta, tako da se direktna govorna komunikacija izbjegava, a nije rijetkost vidjeti ljude kako zajedno sjede i razgovaraju uz korištenje mobitela.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Svakodnevno smo svjedoci da prilikom posjete ugostiteljskim objektima prvo što interesira današnje generacije jeste šifra za Wi-Fi. Navedeni su mnogobrojni primjeri koji nam ukazuju na međusobnu udaljenost te kako internet, čija je funkcija olakšavanje životne aktivnosti, pojedinim osobama postaje glavna preokupacija i sastavni dio života. Kada takvo ponašanje poprimi dimenzije nezamjenjive i svakodnevne preokupacije, to nazivamo ovisnošću o internetu.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Štetne posljedice svih poroka pa i prekomjerne upotrebe interneta su velike. Kao alkohol i droga, tako i ovisnost o internetu štetno djeluje na fizičko i na psihičko zdravlje čovjeka. Još opasnije je to što se mladi prilikom korištenja interneta na ovaj, neprihvatljiv, način lažno predstavljaju (npr. otvarajući lažne Facebook i druge profile) ne razmišljajući o posljedicama.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ZNAKOVI KOJI NAM UKAZUJU NA TO DA JE NEKO OVISNIK O INTERNETU SU SLJEDEĆI:</p>\n                <ul class=\"lesson-text\">\n                    <li>gubitak kontrole vremena,</li>\n                    <li>planira jedno, ali ga internet okupira i uradi drugo,</li>\n                    <li>osjeća tjeskobu i napetost ako se zadesi u situaciji da nema dostupnog interneta,</li>\n                    <li>pokušava da se promijeni, ali se ne trudi dovoljno na tom putu,</li>\n                    <li>u školi, porodici i općenito u društvu sve više koristi internet na različite načine.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Internet ne može biti zamjena za stvarne društvene kontakte, nije dobro ako zbog njega zanemarimo normalne životne navike ili osnovne životne potrebe, a ako smo primijetili da stvari više nismo u stanju kontrolirati, ako nam naša okolina sve češće prigovara zbog korištenja interneta ili smo počeli osjećati krivnju zbog toliko vremena provedenog na internetu, svakako bismo trebali potražiti pomoć, a u ovom slučaju razgovor je najbolja pomoć.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., je čovjeku zabranio sve što štetno djeluje na njegovo psihičko i fizičko zdravlje, a analogno medicinskim zaključcima da se prekomjerna upotreba interneta dijagnosticira kao bolest ovisnosti, možemo zaključiti da je šteta prekomjerne upotrebe interneta velika. Za vjernika je Allahovo zadovoljstvo, i psihičko i fizičko zdravlje koje je potrebno za ibadet i redovne životne aktivnosti, prioritet, a stoga je to i najbolja prevencija ovisnosti o internetu.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">METODE KOJE NAM MOGU POMOĆI DA SE OD NAJRANIJIH FAZA SPASIMO OVE POŠASTI:</p>\n                <ol class=\"lesson-text\">\n                    <li>samostalno praćenje vremena koje provodimo na internetu (prekomjerna upotreba interneta je ona koja nema svoje svrhe i koristi),</li>\n                    <li>posjeta seminara i grupnih aktivnosti (ukoliko je osoba izrazito stidna i povučena, u potrazi za alternativnom komunikacijom poželjno je uključivanje u društvene aktivnosti),</li>\n                    <li>jačati i širiti mrežu prijatelja i više vremena provoditi u društvu (što više vremena budemo provodili družeći se s prijateljima i porodicom, manje vremena ćemo provoditi na internetu).</li>\n                </ol>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Internet treba da bude sredstvo kojim ćemo se koristiti u obrazovanju, bržoj komunikaciji, dobijanju informacija, a nikako sredstvo koje će od nas načiniti ovisnike kojima internet i društvene mreže upravljaju.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - OVISNOST O INTERNETU</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je ovisnost o internetu?</li>\n                    <li>Kako pretjerano korištenje interneta utječe na zdravlje?</li>\n                    <li>Koliko vremena dnevno provodiš na internetu (za računarom ili koristeći mobilni telefon)?</li>\n                    <li>Da li se tvoja potreba za internetom može smatrati i najmanjim dijelom ovisnosti?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Da li u našoj domovini postoje centri za odvikavanje od ovisnosti od interneta? Koliko su oni prisutni kod nas, a koliko u svijetu?</li>\n                    <li>Primijeni tabelu dnevnih aktivnosti i planiraj svoje vrijeme. To je najbolji način zaštite i prevencije prekomjerne upotrebe interneta.</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":72,"is_published":true,"kviz_pitanja":[{"answer":"Pretjerano korištenje interneta koje narušava zdravlje","options":["Korištenje interneta za učenje","Pretjerano korištenje interneta koje narušava zdravlje","Korištenje društvenih mreža svaki dan","Čitanje vijesti na internetu"],"question":"Šta je ovisnost o internetu prema lekciji?"},{"answer":"Olakšavati životne aktivnosti","options":["Biti glavna preokupacija","Zamjenjivati stvarnu komunikaciju","Olakšavati životne aktivnosti","Biti dostupan 24 sata dnevno"],"question":"Koju funkciju bi internet trebao imati?"},{"answer":"Gubitak kontrole vremena provedenog na internetu","options":["Korištenje mobilnog telefona samo za pozive","Gubitak kontrole vremena provedenog na internetu","Čitanje jedne knjige mjesečno","Igranje fudbal sa prijateljima"],"question":"Koji je jedan znak ovisnosti o internetu?"},{"answer":"Na fizičko i psihičko zdravlje čovjeka","options":["Na školske rezultate","Na fizičko i psihičko zdravlje čovjeka","Na izbor odjeće","Na ljubav prema sportu"],"question":"Na šta štetno djeluje prekomjerna upotreba interneta?"},{"answer":"Lažno se predstavljaju bez razmišljanja o posljedicama","options":["Igraju puno video igara","Lažno se predstavljaju bez razmišljanja o posljedicama","Čitaju previše članaka","Gledaju edukativne sadržaje"],"question":"Šta mladih posebno čini opasnom u ovisnosti o internetu?"}]},{"nivo":3,"slug":"horoskop","naslov":"Horoskop i savremena idolatrija","content_html":"<div class=\"lesson-container\">\n        <h1>HOROSKOP I SAVREMENA IDOLATRIJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/horoskop.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Horoskop i savremena idolatrija</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje čvrstog tevhida i odbacivanje svih oblika modernog širka</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti zašto je horoskop, vidovnjaštvo i sl. zabranjeno</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da prepoznaju savremenu idolatriju</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li ste čuli za horoskop? \"Po znaku si vaga, danas ćeš...\" Šta islam kaže o tome?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Horoskop — vjerovanje da zvijezde i planete utiču na našu sudbinu i karakter prema datumu rođenja. To je šejtanska prevara.</p><p>Islamski propis: <strong>haram</strong> — to je oblik gajba, a gajb zna samo Allah.</p><p>Hadis: \"Ko ode kod gatara i pita ga o nečemu, neće mu se primiti namaz 40 dana. Ko mu povjeruje — napustio je vjeru objavljenu Muhammedu.\"</p><p>Druge vrste savremene idolatrije: vidovnjaci, gatare, talismani, amajlije, vjerovanje u brojeve sreće, vjerovanje da neki dan donosi nesreću (\"petak 13.\"), kafe-čitanje.</p><p>Sve ovo je <strong>širk</strong> — pripisivanje Allahovih moći nekome drugom.</p><p>Naša vjera: sve je od Allaha — On zna budućnost, On određuje, On daje sreću i nesreću; mi se trudimo i pouzdamo u Njega.</p><p>Reakcija: ne čitati, ne slušati, ne uplašiti se onoga što kažu; učiti dovu zaštite, ne pridavati pažnju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome gdje se susreću sa horoskopom. Zaključak: tevhid je naš ponos — samo Allah zna sve.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                POGLED U ZVIJEZDE ILI U SRCE? <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Često možemo čuti ljude kako se pitaju: \"Šta si u horoskopu?\" ili kako s nestrpljenjem otvaraju novine da vide šta im \"zvijezde poručuju\" za taj dan. Na prvi pogled to izgleda kao nevina zabava, ali ako malo bolje razmislimo, vidjet ćemo da se iza toga krije nešto mnogo dublje. Traženje odgovora o našoj sudbini u položaju zvijezda zapravo je okretanje leđa Onome Koji je te zvijezde stvorio. Danas ćemo istražiti zašto je oslanjanje na horoskop i moderne idole opasno za našu vjeru i kako da prepoznamo savremene oblike obožavanja koji nam se svakodnevno nude kroz ekrane i društvene mreže.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik a.s., je rekao: “Ko god ode gataru (posjeti ga) i povjeruje u ono što kaže, zanijekao je (postao nevjernik) u ono što je objavljeno Muhammedu, alejhis-selam” (Tirmizi)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Pisanje horoskopa, njihovo crtanje i vjerovanje u ono što piše u horoskopu spada pod ono što je nevedeno u prethodnom hadisu.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Osoba koja piše horoskope, proričući budućnost, time direktno poriče značenje ajeta u kome Allah, dž.š., govori da niko mimo Njega ne poznaje skriveno (gajb):\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Reci: “Niko, osim Allaha, ni na nebu ni na Zemlji, ne zna šta će se dogoditi, i oni ne znaju kad će oživljeni biti.” (En-Neml, 65)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Mnogi kažu da horoskop čitaju iz zabave, sumnjajući ili ne vjerujući. Još gore i opasnije od ovoga je iskreno povjerovati u horoskop. Vjerovati onome ko tvrdi da posjeduje znanje o budućnosti jeste čin nevjerstva.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ako analiziramo ljude koji prate horoskop, vidjet ćemo da koliko god neko tvrdio da ne vjeruje u ono što čita, kad pročita u horoskopu nešto što mu odgovara, obraduje se, ili ako pročita nešto negativno, uplaši se.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">IDOLATRIJA DANAS</p>\n\n                <p class=\"lesson-text\">\n                    Za ispravno razumijevanje ovog pojma, potrebno je napomenuti kako je nastala ova riječ. Korijeni ove riječi nalaze se u grčkim izrazima: eidwlon (eidolon) što znači slika, a druga riječ je latreia (latreia) koja ima značenje obožavati. To bismo u našem jeziku mogli prevesti kao obožavanje idola ili idolopoklonstvo.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ljudi govore, svjesno ili nesvjesno, da obožavaju hranu, TV-emisije, filmove, glumce, igrače itd., i to se promiče kao nešto što je uredu, a u smislu ljubavi prema navedenom. Musliman i muslimanka u vezi s tim u svakom trenutku trebaju biti svjesni da se i riječima i djelom obožava samo i isključivo Allah, dž.š., kao i da se prethodno navedenim primjerima obožavanja nekog ili nečeg drugog mimo Uzvišenog Allaha može napustiti vjera islam.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Danas imamo i različite oblike idolatrije koje nazivamo sujevjerjem, kao npr.: prelazak crne mačke ispred nas što “donosi nesreću”, razbijanje ogledala donosi nesreću, kuckanje u drvo da se “ne urekne i bude sretno” itd. Međutim, to su samo pokušaji opravdavanja onih koji nemaju potpunu vjeru u Allaha, dž.š.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - HOROSKOP I IDOLATRIJA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je Poslanik, alejhis-selam, rekao o proricanju sudbine?</li>\n                    <li>Šta poriču oni koji čitaju i vjeruju u horoskope?</li>\n                    <li>Šta je idolatrija?</li>\n                    <li>Koji savremeni oblici idolatrije danas postoje?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADACI</p>\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK 1:</span> Danas u svijetu živi oko 7 milijardi ljudi. Na ovu brojku se odnosi 12 horoskopskih znakova kao preslikavanje njihovih sudbina. Podijelimo li ova dva broja, doći ćemo do tačnog, ali malo vjerovatnog rezultata da svakih 500 miliona ljudi ima identičnu sudbinu. Oni koji prave horoskop će reći da namjerno pogrešno prezentiramo njihov rad. Kazat će da od ovih 12 znakova svaki od njih ima svoje podznake, koji pobliže određuju ličnost čovjeka.\n                </p>\n                <p class=\"lesson-text\">\n                    Uzmemo li da se ovi znakovi šire do brojke od 100.000, i ako taj broj ponovo podijelimo sa brojem stanovnika, doći ćemo do rezultata od najmanje 6.000 ljudi koji imaju iste sudbine. Razmisli o naprijed navedenom i odgovori da li je moguće da trenutno 6.000 ljudi ima istu sudbinu?\n                </p>\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK 2:</span> U oblačiće napiši odredbe ljudske sudbine koje su određene i zapisane prije čovjekovog rođenja!\n                </p>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":73,"is_published":true,"kviz_pitanja":[{"answer":"Samo Allah zna šta će se desiti","options":["Samo Allah zna šta će se desiti","Svi ljudi mogu znati budućnost","Gatari znaju budućnost bolje od ostalih","Budućnost je poznata svima"],"question":"Šta Kuran kaže o znanju o budućnosti?"},{"answer":"Obožavanje idola ili idolopoklonstvo","options":["Obožavanje idola ili idolopoklonstvo","Čitanje knjiga o bogovima","Skupljanje slike svetaca","Posjeća mečetu svaki dan"],"question":"Šta je idolatrija po značenju tej riječi?"},{"answer":"To je čin nevjerstva prema Islamu","options":["To je čin nevjerstva prema Islamu","To je sasvim dozvoljeno u Islamu","To je samo zabava bez opasnosti","To je preporučeno od Proroka"],"question":"Šta znači ako netko vjeruje u horoskop?"},{"answer":"Sujevjerja kao prelazak crne mačke","options":["Sujevjerja kao prelazak crne mačke","Čitanje knjiga i učenje","Obavljanje molitve pet puta dnevno","Posjećivanje Meke na hadž"],"question":"Kako se nazivaju savremeni oblici idolatrije?"},{"answer":"Napolju obraduje ili uplaši nas, pa počinjemo vjerovati","options":["Napolju obraduje ili uplaši nas, pa počinjemo vjerovati","Nije nikakva opasnost ako ne vjeruješ","Samo je škodljivo ako ga čitaš noću","Opasno je samo za odrasle ljude"],"question":"Šta je opasno kod čitanja horoskopa iz zabave?"}]},{"nivo":3,"slug":"kockanje","naslov":"Kockanje, igre na sreću i sportske kladionice","content_html":"<div class=\"lesson-container\">\n        <h1>KOCKANJE, IGRE NA SREĆU I SPORTSKE KLADIONICE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/kocka.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kockanje, igre na sreću i sportske kladionice</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje gnušanja prema kockanju i navike pravičnog sticanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti zašto je kockanje haram i njegovu štetnost</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike da se odupru pritisku kockanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li ste čuli za kladionice? Lutriju? Casino? Šta islam kaže o tome?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kockanje (mejsir) — svaka igra ili oblik sticanja gdje se dobitak postiže slučajno, a ne radom; gdje neko gubi a neko dobija bez pravnog osnova.</p><p>Allah u Kur’anu: \"O vjernici, doista su vino, kockanje, idoli i strelice za gatanje gnusno djelo šejtanovog posla.\"</p><p>Vrste: lutrija, kladionice (sportske, online), casino, automati, nagradne igre koje traže ulog, pokerski turniri, kockanje na hercegovačkim svadbama.</p><p>Štetnost: <strong>vjerska</strong> (veliki grijeh, ne primaju se dove); <strong>finansijska</strong> (gubi se imovina porodice); <strong>društvena</strong> (svađe, razvodi, dugovi, suicidi); <strong>psihička</strong> (ovisnost, depresija).</p><p>Dobitak: slučajan, brzo se potroši, ne donosi sreću — tako Allah kažnjava nezakonito sticanje.</p><p>Halal alternative: rad, ulaganje, štednja, halal trgovina.</p><p>Pritisak: \"Samo jedan tiket, šta ti smeta?\" — nemoj početi! Ovisnost se brzo razvija.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako se odupru pritisku. Zaključak: novac sticanjem rada — bereket; kockanjem — kletva.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                ILUZIJA BRZE ZARADE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Šetajući našim gradovima i selima, nemoguće je ne primijetiti blještava svjetla objekata koji obećavaju brzu sreću i bogatstvo bez truda. Kocka je poput udice koja nudi mamac lagodnog života, ali iza tog mamca krije se opasna oštrice koja razara porodice, prijateljstva i ljudsko dostojanstvo. Mnogi misle da je jedna marka na loto-listiću ili jedna posjeta kladionici samo bezazlena igra, ne sluteći da šejtan upravo tako gradi nevidljive okove ovisnosti. Danas ćemo istražiti zašto nas Kur'an tako odlučno upozorava na opasnosti kockanja i kako da prepoznamo zamke koje vrebaju na svakom ćošku, podsjećajući se da prava sreća dolazi iz rada, truda i Allahovog blagoslova, a ne iz bubnja ili sportskog rezultata.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: O vjernici, vino, kocka, kumiri i strelice za gatanje su odvratne stvari i šejtanovo djelo; zato se toga klonite da biste postigli što želite. (El-Maide, 90)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Raširenost i popularnost igara na sreću u Bosni i Hercegovini prisutna je već duže vrijeme. Visoki iznosi novca i rekordne uplate za loto i bingo pokazuju da stotine hiljada ljudi, među njima, nažalost, mnogi muslimani i muslimanke, svakodnevno učestvuju u ovim igrama. Posebno je zabrinjavajuća pojava koliko se mladih ljudi može vidjeti u sportskim kladionicama.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Uzvišeni Allah je iz Svoje sveopće mudrosti zabranio kocku jer:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>se ubraja u šejtanski posao i ona je zlo koje uzrokuje brojne štetne posljedice,</li>\n                    <li>uzrokuje neprijateljstvo i mržnju među ljudima,</li>\n                    <li>odvraća od spominjanja Allaha, dž.š.,</li>\n                    <li>odvraća od namaza,</li>\n                    <li>kockari prisvajaju tuđu imovinu i žive u iluziji da će lahko i bez ulaganja truda doći do bogatstva.</li>\n                </ul>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “I ko kaže svome drugu: ‘Hajde da se kockamo!’, neka podijeli sadaku”! (Muslim)\n                    </p>\n                </div>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ONO ŠTO SE UBRAJA U KOCKU</p>\n                <p class=\"lesson-text\">\n                    U kocku se ubraja svaka igra koja se igra u novac, opkladu ili neku drugu vrijednost gdje samo jedan učesnik dobija, a svi drugi gube. Zatim, tu se ubrajaju igre na sreću, kao što su: loto, bingo, razne srećke i kladionice. Tu se ubrajaju i igre, kao šah, tavla, karte i slično, ako se igraju u novac i uzrokuju psovku i ružne riječi i ako zbog njih ljudi zapostavljaju namaz i druge obaveze.\n                </p>\n                <p class=\"lesson-text\">\n                    U kocku se ne ubrajaju kvizovi, jer se oni baziraju na znanju, a ne na sreći, kao i nagradne igre u prodavnicama, u kojima uz račun prilažemo i nagradni kupon, jer u ovim vidovima igara niko ne gubi, bez obzir na to što samo pojedinci dobijaju.\n                </p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">POSLJEDICE KOCKANJA</p>\n                <p class=\"lesson-text\">\n                    Psiholozi su utvrdili da kocka kod čovjeka uzrokuje uzbuđenje, pa razočarenje, te na kraju mržnju i neprijateljstvo.\n                </p>\n                <p class=\"lesson-text\">\n                    Strast za kockom uništava čovjekov život i brak, razara u čovjeku sve ljudske vrline i vrijednosti, uništava razum, ponos i dostojanstvo, tako da osoba koja je ovisna o kocki spremna je prevariti, slagati, ukrasti, pa i ubiti, samo da bi došla do sredstava za kockanje.\n                </p>\n                <p class=\"lesson-text\">\n                    Lijepo je to opisao jedan imam, hatib i muallim kazavši: “Uplaćivati svake sedmice po marku, dvije ili tri i čekati sreću iz bubnja je maštoviti šejtanski projekat kojim on čovjeka drži u svijetu iluzije i mašte koji prestaje kada nasmiješena voditeljica s TV-ekrana utješno poželi gubitnicima više sreće idući put. No, ne treba se čuditi što se pojam sreće sve više poistovjećuje s posjedovanjem novca, tako da su sretni – bogati i oni kojima se “sreća” nasmiješi.\n                </p>\n                <p class=\"lesson-text\">\n                    Lijep moral, dobar odgoj, zdravlje, to više nisu vrline sreće, već zaostavština gubitnicima. Sve dok svoju sreću budemo tražili križajući loto-listiće i prognozirajući rezultate sportskih dešavanja kako se bude povećavao fond dobitaka tako će se umanjivati broj onih koji su uistinu sretni. Uprkos onoj čuvenoj reklami kako i lutrija “ima srce.”\n                </p>\n                <p class=\"lesson-text\">\n                    Posebno opasna i štetna igra na sreću jesu sportske kladionice. Prema neslužbenim podacima, Bosna i Hercegovina je prva u Evropi po broju kladionica u odnosu na broj stanovnika. Kao što su prije nekoliko stoljeća jedan pored drugog stajale zanatske radnje i dućani, danas jedna do druge stoje kladionice. Skoro svako selo u Bosni i Hercegovini ima barem jednu kladionicu, a procjenjuje se da pola miliona stanovnika Bosne i Hercegovine svakodnevno igra igre na sreću, što je otprilike jedan od osam stanovnika. Na samo nekoliko metara od osnovnih ili srednjih škola strateški su raspoređene kladionice koje ne biraju konzumente.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - KOCKANJE I KLADIONICE</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta Allah, dž.š., kaže o kocki?</li>\n                    <li>Zašto je Allah, dž.š., zabranio kocku?</li>\n                    <li>Šta se ubraja u kocku?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADACI</p>\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK 1:</span> Kako ćeš svome prijatelju koji misli da kocka nije ništa loše objasniti negativnosti ovog poroka? Napiši u mektebsku svesku!\n                </p>\n                <p class=\"lesson-text\">\n                    <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK 2:</span> Ako poznaješ nekoga ko igra neku od navedenih igara na sreću, tj. ko se kocka, nastoj djelovati na njega koristeći se saznanjima koje smo naučili te mu ukaži na štetne posljedice. Pričaj o tome i budi uporan jer ako ga nagovoriš da izbjegne samo jedan odlazak u kockarnicu/kladionicu, postigao/la si veliko djelo.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        • U sreću se uzda lud, a pametan, uz Allahovu pomoć, u svoj trud.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":74,"is_published":true,"kviz_pitanja":[{"answer":"Kocka je šejtanovo djelo i trebamo je izbjeći","options":["Kocka je šejtanovo djelo i trebamo je izbjeći","Kocka je dozvoljena ako se igra sa prijateljima","Kocka je dobra za zabavu i druženje","Kocka nema nikakve veze sa šejtanom"],"question":"Šta Allah, dž.š., kaže o kocki u Kur'anu?"},{"answer":"Loto, bingo i razne srećke","options":["Loto, bingo i razne srećke","Kvizovi gdje se testira znanje","Nagradne igre u prodavnicama","Igre sa prijateljima bez novca"],"question":"Koje od navedenih stvari se UBRAJA u kocku?"},{"answer":"Uzrokuje mržnju, odvraća od namaza i Allaha","options":["Uzrokuje mržnju, odvraća od namaza i Allaha","Jer je skupna i skupa","Jer je dosadna i nepopularna","Jer je dozvoljeno samo u nekim zemljama"],"question":"Zašto je Allah zabranio kocku?"},{"answer":"Kvizovi koji se baziraju na znanju","options":["Kvizovi koji se baziraju na znanju","Šah kad se igra u novac","Kartaške igre u novac","Kladionice za sportske utakmice"],"question":"Šta se NE ubraja u kocku po islamu?"},{"answer":"Igra gdje jedan dobija, a ostali gube novac","options":["Igra gdje jedan dobija, a ostali gube novac","Slobodno vrijeme sa prijateljima","Način da lako zaradiš bez truda","Samo igra šaha i tavle"],"question":"Šta je kockanje prema lekciji?"}]},{"nivo":3,"slug":"ekologija","naslov":"Čuvanje okoline – ekologija","content_html":"<div class=\"lesson-container\">\n        <h1>ČUVANJE OKOLINE – EKOLOGIJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ekologija.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Čuvanje okoline – ekologija u islamu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje odgovornog odnosa prema okolini</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamski stav o čuvanju okoline</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ekoloških navika</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je naša okolina? Šuma, rijeke, zrak, životinje. Šta islam kaže o čuvanju svega toga?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah je čovjeka učinio halifom (namjesnikom) na Zemlji — to je velika odgovornost, a ne dozvola za uništavanje.</p><p>Allah u Kur’anu: \"Ne pravite nered na Zemlji nakon njenog uređenja.\"</p><p>Poslanik, a.s.: \"Ko zasadi sadnicu i ona donese plod koji čovjek, ptica ili životinja pojede — to je za njega sadaka.\"</p><p>Ekološke obaveze: ne bacati smeće, štedjeti vodu (čak i pri abdestu kraj rijeke), štedjeti električnu energiju, sortirati otpad, sadditi drveće, ne uništavati zelenilo.</p><p>Štetnosti: zagađenje vode, zraka, krčenje šuma, prekomjerna potrošnja, nepotrebno bacanje hrane.</p><p>Hadis: \"Čistoća je polovina vjere.\" — odnosi se i na ličnu i na javnu čistoću.</p><p>Razgovor: kako pomažem okolini? Da li bacam smeće na pravo mjesto?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici planiraju jednu ekološku akciju (sadnja, čišćenje). Zaključak: čuvati zemlju = ibadet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                AMANET KOJI NAS OKRUŽUJE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Svijet u kojem živimo nije samo prostor koji koristimo, već veličanstvena bašta koju nam je Stvoritelj povjerio na čuvanje. Svaki list, izvor čiste vode i svako biće koje sretnemo u prirodi, nose poruku o ljepoti i skladu koji trebamo održavati. Često zaboravljamo da čistoća naše avlije ili šume nije samo pitanje estetike, već odraz naše vjere i zahvalnosti na blagodatima. Danas ćemo istražiti kako nas islam uči da budemo istinski čuvari okoline i zašto je sadnja jednog drveta djelo koje donosi nagradu čak i kada nas više ne bude. Otkrit ćemo da ekologija nije samo moderna nauka, već način života svakog muslimana koji poštuje red i ljepotu koju je Allah, dž.š., uspostavio na Zemlji.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Onaj koji je nebesa i Zemlju stvorio i koji vam spušta s neba kišu pomoću koje Mi dajemo da ozelene bašče prekrasne – nemoguće je da vi učinite da izraste drveće njihovo. – Zar pored Allaha postoji drugi Bog? Ne postoji, ali su oni narod koji druge s Njim izjednačuje. (En-Neml, 60)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., nam je dao nebrojene blagodati, a jedna od njih je okolina koja nas okružuje. Uzvišeni nas obavještava i kaže: On vas je stvorio iz zemlje, i za vas namijenio njezinu površinu. (Hud, 61)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Sunce koje nam daje toplotu i svjetlost, drveće, planine i ravnice, kratko rečeno čitav biljni ali i životinjski svijet su ljepote koje su nam date na korištenje. Osim što okolinu koristimo i u njoj živimo, također je čuvamo da bi ostala lijepa, vodeći se riječima Božijeg Poslanika, alejhis-selam: “Zaista je Allah lijep, i voli ljepotu.” (Muslim)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ljepota okoline koja nas okružuje ogleda se kroz našu ekološku svijest. Musliman i muslimanka su najbolji ekolozi i imaju najbolju svijest o tome da čuvaju prirodu koju je Allah, dž.š., stvorio.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ekologija se definira kao nauka koja proučava odnose između živih bića, pa na osnovu toga možemo reći da musliman i muslimanka:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>koriste blagodati prirode s mjerom i na razuman način,</li>\n                    <li>sa životinjama postupaju pažljivo i ne muče ih,</li>\n                    <li>životinje koje su dozvoljene u ishrani koriste na propisan način,</li>\n                    <li>čuvaju prirodna dobra (izvore, rijeke, šume, potoke itd.) i ne uništavaju ih,</li>\n                    <li>čuvaju i uređuju zelene površine, svoje avlije (dvorišta) i džamijske hareme,</li>\n                    <li>nastoje obnoviti zemljište i šume koje koriste kao prirodni resurs.</li>\n                </ul>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">OBRAĐIVANJE ZEMLJIŠTA KAO DIO EKOLOGIJE</p>\n                <p class=\"lesson-text\">\n                    Obrađivanje neobrađenog zemljišta preporučeno je od Poslanika, alejhis-selam, i svih njegovih ashaba. To je sastavni dio islama koji su ashabi razumjeli i prakticirali. Mudrost koja se krije u podsticanju na sadnju i obradu zemljišta je zbog proizvodnje hrane, pročišćavanja zraka i sprečavanja erozije tla. U tome se krije još jedan vrlo važan razlog – da se Zemlja učini što ljepšom.\n                </p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">SADITI, A NE UNIŠTAVATI</p>\n                <p class=\"lesson-text\">\n                    Iako znamo da čovjek ima potrebu za prirodnim resursima, poput drveta, to ne znači da u potpunosti i nekontrolirano treba sjeći drveće. Treba nastojati što je moguće više saditi, kako bi se priroda obnavljala. Osim toga, za sve što učinimo u prirodi imamo višestruku korist.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Kad god musliman zasadi biljku, imat će nagradu za sve što bude jelo s te biljke, poput ptica ili životinja. Ova nagrada će stalno teći do Sudnjeg dana.” (Nesai)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., nas podstiče da razmislimo o ljepoti prirode tako što nam u Kur'anu nabraja neke od ljepota biljnog i životinjskog svijeta. Jedan od takvih primjera je i sljedeći ajet: Neka čovjek pogleda u hranu svoju; Mi obilno kišu prolivamo, zatim zemlju pukotinama rasijecamo i činimo da iz nje žito izrasta i grožđe i povrće, i masline i palme, i bašče guste, i voće i pića, na uživanje vama i stoci vašoj. (Abese, 24-32)\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        U Kur’anu se spominje:<br>\n                        ‒ drvo i riječi sličnog značenja ‒ 26 puta,<br>\n                        ‒ sadnica – 26 puta,<br>\n                        ‒ vrt i riječi sličnog značenja 3 puta.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - EKOLOGIJA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je ekologija?</li>\n                    <li>Koje je značenje riječi ekologija?</li>\n                    <li>Šta sve obuhvata ekologija?</li>\n                    <li>Kako musliman i muslimanka postaju najbolji ekolozi?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADATAK</p>\n                <p class=\"lesson-text\">\n                    Napiši u mektebsku svesku i nauči neke kur’anske ajete i hadise Poslanika, alejhis-selam, koji se vežu za ekologiju!\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        “Kada bi nastupio Sudnji dan, a u ruci nekog od vas bila sadnica, ako bude u mogućnosti da je zasadi, neka to učini.” (Buhari)\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":75,"is_published":true,"kviz_pitanja":[{"answer":"Okolinu koja nas okružuje","options":["Samo drveće i vode","Okolinu koja nas okružuje","Samo ljepotu neba","Samo životinje"],"question":"Šta je Allah, dž.š., dao kao blagodati oko nas?"},{"answer":"Trebaju ih čuvati i ne muče ih","options":["Trebaju ih mučiti","Trebaju ih zaustavljati","Trebaju ih čuvati i ne muče ih","Trebaju ih bacati"],"question":"Kako se musliman i muslimanka trebaju ponašati prema životinjama?"},{"answer":"Nauka o odnosima između živih bića","options":["Uništavanje prirode","Nauka o odnosima između živih bića","Gradnja kuća","Samo proizvodnja hrane"],"question":"Šta znači pojam ekologija?"},{"answer":"Proizvodnja hrane, čišćenje zraka, ljepota Zemlje","options":["Samo zabava","Proizvodnja hrane, čišćenje zraka, ljepota Zemlje","Samo sprječavanje buke","Samo украšavanje"],"question":"Koji su razlozi za sadnju i obradu zemljišta?"},{"answer":"Allah voli ljepotu i on je lijep","options":["Allah ne voli ljepotu","Allah voli ljepotu i on je lijep","Ljepota nije važna","Samo žene trebaju biti lijepe"],"question":"Šta je Poslanik, alejhis-selam, rekao o ljepoti?"}]},{"nivo":3,"slug":"biljke-zivotinje","naslov":"Odnos prema biljnom i životinjskom svijetu","content_html":"<div class=\"lesson-container\">\n        <h1>ODNOS PREMA BILJNOM I ŽIVOTINJSKOM SVIJETU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/biljke_zivotinje.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Odnos prema biljnom i životinjskom svijetu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje samilosti prema svim Allahovim stvorenjima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti islamski stav o pravima životinja i biljaka</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika brige za žive stvore</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li životinje imaju prava u islamu? A biljke? Da! Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sve je Allahovo stvorenje — i biljke, i životinje, i ljudi. Sve ima svoje pravo.</p><p>Životinje imaju prava: <strong>1.</strong> da budu nahranjene i napojene, <strong>2.</strong> da im se ne nanosi suvišna patnja, <strong>3.</strong> da se kolju samo za hranu (i to po šerijatskim pravilima — brzo, oštrim nožem), <strong>4.</strong> da se ne tovare iznad mogućnosti.</p><p>Hadis: Žena koja je zatvorila mačku do smrti otišla je u Džehennem; čovjek koji je napojio žednog psa otišao je u Džennet.</p><p>Lov: dozvoljen je za hranu, ne iz zabave; zabranjeno je masovno uništavanje vrsta.</p><p>Biljke: ne uništavati ih bez razloga; sadditi je sadaka tekuća.</p><p>Hadis: \"Čak i ako Sudnji dan nastupi a vi imate sadnicu u ruci — zasadite je.\"</p><p>Eksperimenti: na životinjama dozvoljeni samo radi velike koristi, sa minimumom patnje.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome kako pomažu životinjama. Zaključak: samilost prema svemu živom — znak imana.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                SUSTANOVRE PLANETE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite svijet bez pjeva ptica u zoru, bez hladovine drveća u vrelim ljetnim danima ili bez boja cvijeća koje ukrašava naše livade. Biljke i životinje nisu samo ukras naše planete, već živa bića koja imaju svoje mjesto u savršenom poretku koji je Stvoritelj uspostavio. Često zaboravljamo da način na koji se odnosimo prema jednoj maloj biljci ili nezaštićenoj životinji govori najviše o našoj ljudskosti i vjeri. Danas ćemo naučiti zašto je pažnja prema prirodi put ka Božijoj milosti i kako su čak i cijela poglavlja Kur'ana dobila imena po životinjama, podsjećajući nas na njihovu važnost. Otkrit ćemo da biti musliman znači biti onaj ko donosi mir i zaštitu svakom stvorenju koje dijeli ovaj svijet s nama.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: On je za vas sve što postoji na Zemlji stvorio, zatim je Svoju volju prema nebu usmjerio i kao sedam nebesa ga uredio; On sve zna. (El-Bekare, 29)\n                    </p>\n                    <p class=\"lesson-text\">\n                        On vam je Zemlju pogodnom učinio, pa hodajte predjelima njezinim i hranite se onim što On daje, Njemu ćete poslije oživljenja odgovarati. (El-Mulk, 15)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Jedna od najvažnijih karakteristika islama jeste da je to vjera koja posvećuje jednaku pažnju dunjaluku – ovom svijetu kao i ahiretu – budućem svijetu. Islam poziva muslimane da rade na uspostavi humanije civilizacije, i istovremeno da se trude kako bi Božijom milošću bili uvedeni u Džennet.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Na tom putu pažljiv i odgovoran odnos prema biljnom i životinjskom svijetu, koje nam je Uzvišeni Allah potčinio, treba da uvijek bude prisutan.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Najveći pomoćnik u borbi sa štetnim gasovima jeste biljni svijet. Zelene površine pozitivno utječu na uravnotežavanje režima vjetrova i djeluju na smanjenje buke.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ekonomski napredak i razvoj usko su vezani za prirodu, gdje se sve odvija skladno i gdje sve posljedice imaju svoj uzrok.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Prije nego što krenemo u prirodu valja naučiti osnovna pravila ponašanja u prirodnom okruženju. Ljudi često svoje loše navike iz mjesta stanovanja prenose i na izletišta, parkove, u šume i na planine. Kad se nađu daleko od svoje sredine, nekad nema mjesta za odlaganje smeća. Kante za smeće po parkovima i na izletištima u blizini gradova često su pretrpane. Na muslimanu i muslimanki je da budu primjeri ispravnog odnosa prema okolini u svakoj situaciji u kojoj se nađu.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Šest sura u Kur’anu nazvano je po životinjama, i to:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>El-Bekare (Krava),</li>\n                    <li>El-En’am (Stoka),</li>\n                    <li>En-Nahl (Pčele),</li>\n                    <li>En-Neml (Mravi),</li>\n                    <li>El-Ankebut (Pauk) i</li>\n                    <li>El-Fil (Slon),</li>\n                </ul>\n                <p class=\"lesson-text\">\n                    a životinjski svijet se u Kur’anu i hadisima spominje u različitim kontekstima.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Brojne su mudrosti spominjanja životinja u Kur’anu i hadisima Allahovog Poslanika, alejhis-selam One uključuju i kvalitet šerijatskih normi budući da se za status životinja vežu određeni propisi, počev od konzumiranja njihovog mesa, korištenja životinja u svrhe lova, držanja u vlasništvu itd.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Zabranjeno nam je nanositi bol drugim živim bićima, izuzev u stanju nužde i potrebe. U načela naše vjere u ovom smislu ubrajamo i to da štetočine smijemo ubijati, ali ne i mučiti i niti jednu životnju ne smijemo na vatri spaljivati, jer je to veliki grijeh.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Prenosi se da je jedan od ashaba rekao: “Ušao sam jednom sa svojim djedom Enesom ibn Malikom, r.a., u kuću El-Hakima ibn Ejuba. Vidjesmo tu neke ljude kako kao metu gađaju kokoške. Enes im reče: “Božiji Poslanik, alejhis-selam, zabranio je da se (kao meta) postavi neka domaća životinja i da se gađa.” (Muslim)\n                    </p>\n                </div>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Onaj ko se smiluje živom biću njemu će se smilovati Stvoritelj.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ODNOS PREMA PRIRODI</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Koju praktičnu ulogu ima biljni svijet?</li>\n                    <li>Kakav primjer musliman treba biti drugima kada je u pitanju odnos prema okolišu?</li>\n                    <li>Po kojim životinjama su nazvane kur'anske sure?</li>\n                    <li>Da li je dozvoljeno ukloniti biljke i životinje koje nanose štetu?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Koja je svrha stvaranja biljnog i životinjskog svijeta?</li>\n                    <li>Kakav odnos trebamo imati prema biljnom i životinjskom svijetu?</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":76,"is_published":true,"kviz_pitanja":[{"answer":"Sve što postoji na Zemlji","options":["Samo životinje","Sve što postoji na Zemlji","Samo biljke","Samo vode"],"question":"Šta je Allah stvorio za nas na Zemlji?"},{"answer":"Zelene površine","options":["Samo cvijeće","Samo drveće","Zelene površine","Samo trava"],"question":"Koji biljni svijet pomaže u borbi protiv štetnih gasova?"},{"answer":"Šest sura","options":["Tri sure","Četiri sure","Šest sura","Deset sura"],"question":"Koliko sura u Kur'anu je nazvano po životinjama?"},{"answer":"Slon","options":["Krava","Slon","Pčela","Pauk"],"question":"Koja životinja je spomenuta u nazivu sure El-Fil?"},{"answer":"Primjeri ispravnog odnosa","options":["Ravnodušni","Primjeri ispravnog odnosa","Nezainteresirani","Neodgovorni"],"question":"Što bi muslimani trebali biti u odnosu prema okolini?"}]},{"nivo":3,"slug":"poslanici-kuran","naslov":"Božiji poslanici spomenuti u Kur'anu","content_html":"<div class=\"lesson-container\">\n        <h1>BOŽIJI POSLANICI SPOMENUTI U KUR’ANU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/poslanici_kuran.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Božiji poslanici spomenuti u Kur’anu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema svim Allahovim poslanicima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti imena 25 poslanika koji se spominju u Kur’anu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti razlikovanja poslanika i njihovih kazivanja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko poslanika se po imenu spominje u Kur’anu? 25. Hajde da ih nabrojimo i podsjetimo se na njihova kazivanja.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>25 poslanika spomenutih po imenu u Kur’anu:</p><p>Ādem, Idrīs, Nūh, Hūd, Sālih, Lūt, Ibrāhīm, Ismā‘īl, Ishāk, Ja‘kūb, Jūsuf, Šu‘ajb, Ejjūb, Mūsa, Hārūn, Zul-Kifl, Dāwud, Sulejmān, Iljās, El-Jese‘, Jūnus, Zekerijja, Jahjā, Īsa, Muhammed (alejhimus-selām).</p><p>Petorica \"Ulul-‘azm\" (poslanici sa najvećim teretom): Nūh, Ibrāhīm, Mūsa, Īsa, Muhammed.</p><p>Svaki poslanik je donio istu poruku: <strong>Lā ilāhe illallāh</strong> — nema boga osim Allaha.</p><p>Poslanici se razlikuju po šerijatu (zakonu) — različiti propisi za različite narode i vremena, ali isti tewhid.</p><p>Najveći među njima: <strong>Muhammed, a.s.</strong> — pečat svih poslanika, posljednji.</p><p>Naša obaveza: vjerovati u sve, voljeti ih, slijediti Muhammeda, a.s.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju što više poslanika. Zaključak: lanac poslanika — Allahova milost prema čovječanstvu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                SVJETILJKE NA PUTU ČOVJEČANSTVA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Kroz čitavu historiju, ljudski rod nikada nije bio ostavljen bez upute. Kao što putnik u mraku treba svjetiljku da ne bi zalutao, tako su ljudi trebali odabrane pojedince koji će im pojasniti svrhu života i put ka Stvoritelju. Ti odabranici su Božiji poslanici – ljudi koji su svojom iskrenošću, hrabrošću i moralom bili uzori svojim narodima. Od prvog čovjeka Adema, alejhis-selam, pa sve do posljednjeg Muhammeda, alejhis-selam, svaki od njih nosio je istu poruku mira i vjere. Danas ćemo naučiti imena onih koji su posebno spomenuti u Kur'anu i otkriti zašto su neki od njih dobili počasnu titulu \"odlučnih\", podsjećajući nas na snagu vjere koja može promijeniti svijet.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Svaki narod je imao poslanika... (Junus, 47)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Allahov, dž.š., poklon ljudima izražen u slanju poslanika ubraja se među najveće blagodati koje je Uzvišeni Allah podario ljudskom rodu. Svaki poslanik predstavlja Allahovu, dž.š., milost koja se nudi ljudima. Prvi čovjek na Zemlji i prvi poslanik bio je Adem, alejhis-selam, a Muhammed, alejhis-selam, je Hatemul-enbija – pečat poslanika, tj. posljednji i najodabraniji poslanik. Zbog važnosti poslanika u životima ljudi, a posebno u pojašnjavanju Božije objave, Uzvišeni Allah je svakom narodu poslao poslanika.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Tačan broj Božijih poslanika je poznat samo Allahu, dž.š., a ranije smo naučili da ih je u Kur'anu poimenično spomenuto 25, a to su: Adem, Idris, Nuh, Hud, Salih, Ibrahim, Ishak, Ismail, Lut, Jakub, Jusuf, Ejub, Šuajb, Musa, Harun, Zulkifl, Davud, Sulejman, Iljas, Eljesea, Junus, Zekerija, Jahja, Isa i Muhammed, alejhis-selam\n                </p>\n\n                <p class=\"lesson-text\">\n                    Među najodabranijim su: Nuh, Ibrahim, Musa, Isa i Muhammed, alejhis-selam, jednim imenom su nazvani Ulul-ʻazm ‒ Odlučni poslanici.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Brojni su ajeti u kojima se spominju imena Allahovih poslanika. Međutim, nekoliko ajeta iz sure En-Nisa i El-Enʻam sadrže većinu imena Božijih poslanika.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Mi objavljujemo tebi kao što smo objavljivali Nuhu i vjerovjesnicima poslije njega, a objavljivali smo i Ibrahimu, i Ismailu, i Ishaku, i Jakubu i unucima, i Isau, i Ejubu, i Junusu, i Harunu, i Sulejmanu, a Davudu smo dali Zebur, i poslanicima o kojima smo ti prije kazivali i poslanicima o kojima ti nismo kazivali – a Allah je, sigurno, s Musaom razgovarao – o poslanicima koji su radosne vijesti i opomene donosili, da ljudi poslije poslanika ne bi nikakva opravdanja pred Allahom imali. – A Allah je silan i mudar. (En-Nisa, 163-165)\n                    </p>\n                </div>\n\n\t\t\t\t<div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        To su dokazi naši koje dadosmo Ibrahimu za narod njegov. Mi više stepene dajemo onima kojima Mi hoćemo. Gospodar tvoj je, uistinu, Mudri i Sveznajući. I Mi mu poklonismo i Ishaka i Jakuba; i svakog uputismo – a Nuha smo još prije uputili – i od potomaka njegovih Davuda, i Sulejmana, i Ejuba, i Jusufa, i Musaa, i Haruna – eto, tako Mi nagrađujemo one koji dobra djela čine, i Zekerijaa, i Jahjaa, i Isaa, i Iljasa – svi su oni bili dobri, i Ismaila i Eljese‘a i Junusa i Luta – i svima smo prednost nad svijetom ostalim dali, i neke pretke njihove i potomke njihove i braću njihovu – njih smo odabrali i na Pravi put im ukazali. (El-En’am, 83-87)\n                    </p>\n                </div>\n                <p class=\"lesson-text\">\n                    Preostali poslanici koji nisu spomenuti u ova dva ajeta spomenuti su na drugim mjestima u Kur’anu:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>I pouči On Adema nazivima svih stvari… (El-Bekare, 31)</li>\n                    <li>I Ismailu i Idrisu i Zulkiflu, a svi su oni bili strpljivi. (El-Enbija, 85)</li>\n                    <li>O narode moj, neka vas neslaganje sa mnom nikako ne dovede do toga da vas zadesi ono što je zadesilo Nuhov narod ili Hudov narod ili Salihov narod… (Hud, 89)</li>\n                    <li>Muhammed je samo poslanik, a i prije njega je bilo poslanika. (Alu Imran, 144)</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Pored spomenutih Božijih poslanika, Allah, dž.š., u Kur’anu spominje i trojicu svojih odabranih robova, a to su Lukman, Uzeir i Zulkarnejn.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        „Ko na mene donese jedan salavat Allah na njega donese deset salavata i upiše mu deset dobrih djela.” (Ahmed)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - BOŽIJI POSLANICI</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Kako Kur’an naziva posljednjeg Allahovog Poslanika?</li>\n                    <li>Koliko je ukupno bilo poslanika?</li>\n                    <li>Koje poslanike spominje Kur’an poimenično?</li>\n                    <li>Šta su ulul-azm poslanici i koji su?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>U Kur'anu pronađi sve sure koje su nazvane po Allahovim poslanicima!</li>\n                    <li>Koliko je puta posljednji Allahov poslanik spomenut u Kur'anu?</li>\n                    <li>U tabelu upiši imena Božijih poslanika čije ime počinje slovom I ili J!</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":77,"is_published":true,"kviz_pitanja":[{"answer":"Adem, alejhis-selam","options":["Adem, alejhis-selam","Nuh, alejhis-selam","Ibrahim, alejhis-selam","Muhammed, alejhis-selam"],"question":"Ko je bio prvi čovjek i prvi poslanik na Zemlji?"},{"answer":"25 poslanika","options":["15 poslanika","25 poslanika","30 poslanika","50 poslanika"],"question":"Koliko je Božijih poslanika poimenično spomenuto u Kur'anu?"},{"answer":"Ulul-ʻazm - Odlučni poslanici","options":["Amini poslanici","Ulul-ʻazm - Odlučni poslanici","Mubashshiruni poslanici","Naziri poslanici"],"question":"Kako se nazivaju pet najodabranijih poslanika?"},{"answer":"Muhammed, alejhis-selam","options":["Isa, alejhis-selam","Musa, alejhis-selam","Muhammed, alejhis-selam","Ibrahim, alejhis-selam"],"question":"Koji poslanik je Hatemul-enbija ili pečat poslanika?"},{"answer":"Sure En-Nisa i El-Enʻam","options":["Sure Jahsin i Marjem","Sure En-Nisa i El-Enʻam","Sure Taha i Enbija","Sure Rahman i Furkan"],"question":"U kojoj suri se nalazi većina imena Božijih poslanika?"}]},{"nivo":3,"slug":"nuh-as","naslov":"Nuh, a.s.","content_html":"<div class=\"lesson-container\">\n        <h1>NUH, A.S.</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/nuh.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Nūh, a.s. – život i poslanstvo</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i poštovanja prema poslaniku Nūh, a.s., te slijeđenje njegovog primjera</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa životom, poslanstvom i poukama iz života Nūh, a.s.</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti izvlačenja pouka iz kazivanja o poslanicima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je Nūh, a.s.? Šta o njemu znamo iz Kur’ana? Hajde da naučimo više o njegovom životu i poruci.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Nūh, a.s. je jedan od Allahovih poslanika kojeg Kur’an spominje.</p><p>Nūh, a.s., je 950 godina pozivao svoj narod u tewhid, ali su ga oni odbijali. Allah ga je naredio da napravi lađu, i potom je na narod poslao potop. Spasili su se Nūh i oni koji su povjerovali, sa parovima životinja u lađi.</p><p>Allah ga je poslao da pozove svoj narod u tewhid – obožavanje samo jednog Allaha.</p><p>Nailazio je na poteškoće i odbijanje, ali je strpljivo nastavljao Allahov poziv.</p><p>Iz njegovog života učimo: strpljivost, iskrenost u pozivu, oslanjanje na Allaha (tevekkul) i ustrajnost u istini.</p><p>Razgovor: koja pouka iz života Nūh, a.s. nam je posebno bliska?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju ključne događaje. Zaključak: poslanici su uzori koje slijedimo u životu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                STRPLJENJE KOJE JE POBIJEDILO TALASE <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Postoje trenuci u historiji kada se čitav svijet nađe na prekretnici, a spas zavisi od snage vjere jednog čovjeka. Zamislite graditelja koji na suhom kopnu, daleko od vode, uporno gradi ogromnu lađu dok ga svi prolaznici ismijavaju. Taj čovjek bio je Nuh, alejhis-selam, poslanik čije je strpljenje trajalo stoljećima. On nije gradio samo lađu od drveta, već lađu spasa za sve one koji su sačuvali čisto srce. Danas ćemo istražiti dramatično kazivanje o velikom potopu, o trenutku kada je Zemlja postala more i o tome kako istinska predanost Bogu pronalazi luku spasa čak i tamo gdje se čini da je sve izgubljeno. Otkrit ćemo zašto se sjećanje na brdo Džudi i danas čuva kao pouka o pobjedi istine nad ohološću.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I kad je zapovijed Naša pala i voda s površine Zemlje pokuljala, Mi smo rekli: “Ukrcaj u lađu od svake životinjske vrste po jedan par, i čeljad svoju – osim onih o kojima je bilo govora – i vjernike!” – a malo je bilo onih koji su s njim vjerovali. (Hud, 40)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Nuh, alejhis-selam, je jedan od najodabranijih Allahovih poslanika koji je poslan svom narodu. Allah, dž.š., ga često spominje u Kur’anu. On je misiju poslanstva ponio nakon Idrisa, alejhis-selam U tom vremenu narod se umnožio tako da je postojala potreba slanja novog poslanika koji je imao isti zadatak, da ljude poziva u Allahovu vjeru, da ih opominje, te da im naređuje dobro, a odvraća ih od zla. Allahovom voljom bio je to Nuh, alejhis-selam\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ljudi njegovog doba su živjeli stotinama godina, a Nuh, alejhis-selam, živio je kako Kur’an kaže: “Hiljadu manje pedeset godina.“ Kako tradicija navodi, Nuh, alejhis-selam, je djelovao na području današnje Sirije, Jordana, Palestine i Iraka. Nuhov, alejhis-selam, narod je postepeno napuštao vjeru svojih roditelja koji su vjerovali u Jednog Boga te se neposredno prije samog njegovog dolaska u narodu raširilo idolopoklonstvo i sujevjerje.\n                </p>\n\n                <p class=\"lesson-text\">\n                    U vremenu u kojem je Nuh, alejhis-selam, bio poslanik, narodom je vladao vladar nevjernik koji je od svojih podanika tražio da ne slušaju Nuha, alejhis-selam, da ga ne slijede i da ne napuštaju klanjanje kipovima.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Većina njegovog naroda, osim malo njih, nije se osvrtala na ono što je Nuh, alejhis-selam, govorio, nego su ustrajavali u griješenju, a pored toga su vrijeđali i napadali Allahovog poslanika. Teškoće su se javljale jedna za drugom, počeli su ga smatrati ludim i nisu se odazivali njegovom pozivu.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Allah, dž.š., nas obavještava o tome kako se Nuh, alejhis-selam, obraćao Njemu zbog neuspjeha svog pozivanja i njihove reakcije na njegove pozive i opominjanja.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Nakon dugotrajnog pozivanja vjeri u Jednoga Boga, Nuh, alejhis-selam, je stekao veoma malo sljedbenika, te je učio dovu svome Gospodaru da na Zemlji ne ostavi nijednog nevjernika. Gospodar mu objavljuje da osim njegovih sljedbenika, niko od njegovog naroda više vjernik neće postati. Nakon Allahovog odgovora, a po Njegovoj zapovijedi, Nuh, alejhis-selam, je počeo praviti lađu na kopnu, a narod ga je ismijavao i rugao mu se. Pitali su: “O Nuhu, šta to praviš, pa gdje ti je voda, Nuhu?” On nije slušao njihove riječi i uporno je radio na gradnji lađe. Kada je završio, došlo je vrijeme obistinjenja Allahove prijetnje.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Tada je nastupio opći potop. S Nuhom, alejhis-selam, spašeni su samo oni koji su bili u lađi. Spasa nije bilo za nevjernike među kojima je bio i Nuhov, alejhis-selam, sin koji nije slijedio uputu svoga oca. Kada je Nuh, alejhis-selam, vidio da će s nevjernicima nastradati i njegov sin, zamolio je Allaha, dž.š., da ga spasi, ali na dovu Svoga poslanika, Allah, dž.š., odgovara: “O Nuhu, on nije čeljade tvoje” – rekao je On – “jer radi ono što ne valja, zato Me ne moli za ono što ne znaš! Savjetujem ti da neznalica ne budeš.” (Hud, 46)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Potop je potrajao izvjesno vrijeme, a nakon što se ispunila Allahova odredba, Gospodar svjetova je naredio vodi da se povuče i lađa se zaustavila na brdu Džudi. Uzvišeni Allah kaže: I bî rečeno: “O Zemljo, gutaj vodu svoju, a ti, o nebo, prestani.” I voda se povuče i ispuni se odredba, a lađa pristade na planini El-Džudi, i bi rečeno: “Daleko nek je narod nevjernički.” (Hud, 44)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Tako se završila sudbina naroda Nuha, alejhis-selam, koji je snašla kazna i nestali su s ovoga svijeta kao da ih nikada nije ni bilo. Nama, sljedbenicima Kur’ana i poslanika Muhammada, alejhis-selam, ostaje da se poučimo kazivanjem o plemenitom poslaniku Nuhu, alejhis-selam, i njegovom narodu.\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Za vrijeme Nuha, alejhis-selam, desio se veliki potop, a s Nuhom, alejhis-selam, spašeni su oni koji su ga slijedili – vjernici.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - NUH, A.S.</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Koji poslanik je bio prije i zašto je poslan Nuh, alejhis-selam?</li>\n                    <li>Koju naredbu je dobio Nuh, alejhis-selam, a zbog čega je bio izložen izrugivanju?</li>\n                    <li>Kako je kažnjen Nuhov, alejhis-selam, narod?</li>\n                    <li>Ko je od porodice Nuha, alejhis-selam, bio potopljen?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADATAK</p>\n                <ul class=\"lesson-text\">\n                    <li>Istražite gdje se prema savremenim arheološkim istraživanjima nalazi brdo Džudi na kojem je zaustavljena Nuhova, alejhis-selam, lađa? Prema procjenama, koje godine je živio Nuh, alejhis-selam?</li>\n                </ul>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        • Putnici na lađi spasa.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":78,"is_published":true,"kviz_pitanja":[{"answer":"Hiljadu manje pedeset godina","options":["Hiljadu godina","Hiljadu manje pedeset godina","Petsto godina","Tri stotine godina"],"question":"Koliko je godina živio Nuh, alejhis-selam, prema Kur'anu?"},{"answer":"Lađu","options":["Džamiju","Lađu","Kuću","Grad"],"question":"Šta je Nuh, alejhis-selam, počeo da gradi po Allahovu naredbi?"},{"answer":"Sirija, Jordan, Palestina i Irak","options":["Grčka i Turska","Sirija, Jordan, Palestina i Irak","Egipat i Libija","Mađarska i Hrvatska"],"question":"Na kojem je području djelovao Nuh, alejhis-selam?"},{"answer":"Ismijavali su ga i vrijeđali ga","options":["Odmah su vjerovali","Ismijavali su ga i vrijeđali ga","Odobravali su njegov rad","Pomagali su mu"],"question":"Kako se narod odnosio prema Nuhovu, alejhis-selam, pozivu?"},{"answer":"Veoma malo","options":["Veoma malo","Većinu naroda","Sve stanovnike","Polovinu naroda"],"question":"Koliko je vjernika Nuh, alejhis-selam, stekao iz svoga naroda?"}]},{"nivo":3,"slug":"ibrahim-as","naslov":"Ibrahim, a.s.","content_html":"<div class=\"lesson-container\">\n        <h1>IBRAHIM, A.S.</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ibrahim.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ibrāhīm, a.s. – život i poslanstvo</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i poštovanja prema poslaniku Ibrāhīm, a.s., te slijeđenje njegovog primjera</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa životom, poslanstvom i poukama iz života Ibrāhīm, a.s.</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti izvlačenja pouka iz kazivanja o poslanicima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je Ibrāhīm, a.s.? Šta o njemu znamo iz Kur’ana? Hajde da naučimo više o njegovom životu i poruci.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ibrāhīm, a.s. je jedan od Allahovih poslanika kojeg Kur’an spominje.</p><p>Ibrāhīm, a.s., je razbio kipove svog naroda, bio bačen u vatru koja mu je Allahovom moći postala hladna. Sa sinom Ismā‘īlom je sagradio Ka’bu. Spreman je bio žrtvovati sina po Allahovoj naredbi, što je i ispitanje koje označava Kurban-bajram.</p><p>Allah ga je poslao da pozove svoj narod u tewhid – obožavanje samo jednog Allaha.</p><p>Nailazio je na poteškoće i odbijanje, ali je strpljivo nastavljao Allahov poziv.</p><p>Iz njegovog života učimo: strpljivost, iskrenost u pozivu, oslanjanje na Allaha (tevekkul) i ustrajnost u istini.</p><p>Razgovor: koja pouka iz života Ibrāhīm, a.s. nam je posebno bliska?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju ključne događaje. Zaključak: poslanici su uzori koje slijedimo u životu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                TRAGANJE ZA ISTINOM <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Ibrahim, alejhis-selam, odrastao je u narodu koji je klanjanje kipovima smatrao normalnim, ali on je od djetinjstva osjećao da kamen i drvo ne mogu biti bogovi. Njegova potraga za istinom nije počela u hramovima, već pod otvorenim nebom, posmatrajući zvijezde, mjesec i sunce. Kroz te znakove u prirodi, spoznao je moć Stvoritelja koji ne nestaje i ne zalazi. Danas ćemo naučiti kako je njegova hrabrost da se suprotstavi zabludi i njegova potpuna predanost Bogu postala temelj vjere za sve generacije koje su došle poslije njega. Ibrahimova historija je priča o čudima – od vatre koja nije pržila, do vrela Zemzema koje je poteklo usred pustinje.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    Kazivanje o jednom od odabranih Božijih poslanika Ibrahimu, alejhis-selam, sadrži pouku svim narodima i ljudima koji će biti sve do propasti ovoga svijeta dunjaluka. Ibrahim, alejhis-selam, potječe iz naroda koji je obožavao kipove, ali i pored toga, od samog djetinjstva znao je da se kipovi ne mogu obožavati niti im se treba klanjati, nego je razmišljao o svome Gospodaru, posmatrajući prirodu koja ga okružuje.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Jedne večeri, dok je bio dječak, izašao je vani i divio se zvijezdi koja je na nebu posebno zasjala. Ushićen njenom ljepotom povikao je da je ona njegov Gospodar, međutim, kada je zvijezda nestala, kazao je da on ne voli one koji nestaju. Nakon toga ugledao je Mjesec u punom sjaju, povikao je: \"Ovo je moj Gospodar\", a kada je i Mjesec nestao rekao je: \"Ako me Gospodar moj ne uputi, ostat ću među onima koji su zalutali.\" Razmišljajući tako, nije ni primijetio da je svanulo jutro novog dana u kome se u punom sjaju pojavilo Sunce sa svom svojom ljepotom i blještavilom, te je Ibrahim povikao: \"Ovo je moj Gospodar\", međutim, kada je i Sunce zašlo, rekao je: \"Ja nemam ništa s tim što Njemu druge ravnim smatraju, ja okrećem lice svoje, kao pravi vjernik Onome ko je stvorio nebesa i Zemlju.\" Čudio se Ibrahim, alejhis-selam, i svom ocu Azeru govoreći mu: \"Zar kumire smatraš bogovima. Ti i tvoj narod ste u očitoj zabludi.\"\n                </p>\n\n                <p class=\"lesson-text\">\n                    Jednog dana dok su njegovi sunarodnjaci bili zauzeti slavljenjem, Ibrahim, alejhis-selam, se približio kipovima i sve ih porušio, osim jednog, najvećeg. Kada su došli i vidjeli da su kipovi porušeni, prisjetili su se ko je o njima pogrdno govorio, pa su pretpostavili ko je porušio njihova božanstva. Pitali su ga: \"Ibrahime, da li si ti ovo uradio?\" On im je pokazao na najvećeg kipa govoreći im da njega pitaju. Oni mu rekoše: \"On ne umije govoriti.\" \"Pa zašto ih obožavate\", reče im Ibrahim. \"Jesam, ja sam ih porazbijao, eto vidite, sebi nisu mogli pomoći pa kako da vama budu od pomoći.\" Odlučili su da ga kazne tako što će ga baciti u vatru, naložili su veliku vatru i bacili ga u nju. Allah, dž.š., je naredio vatri da bude hladna i spasonosna za Ibrahima, tako da on nije izgorio.\n                </p>\n                <img src=\"/edu/assets/images/kipovi.jpg\" style=\"float: left; width: 250px; margin-right: 10px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">\n                    Nakon što je odrastao, Ibrahim, alejhis-selam, se oženio Sarom, najljepšom ženom tog vremena. Allah, dž.š., im je podario sreću i bogatstvo, međutim Ibrahim, alejhis-selam, i Sara nisu imali djecu pa je molio Allaha, dž.š., da mu ih podari, što mu je kasnije uslišano.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Kada je Ibrahim, alejhis-selam, dobio naređenje od Allaha, dž.š., da se preseli, on i njegova supruga Sara, Lut, alejhis-selam, i vjernici napustili su Mezopotamiju i zaputili se ka blagoslovljenoj zemlji - Kudsu (Jerusalem). Živjeli su nomadskim životom, tako da su zajedno sa svojom stokom išli od pašnjaka do pašnjaka, pa ih je put naveo i do Egipta. Tada je Egiptom vladao nepravedni vladar, koji je poželio Ibrahimovu suprugu Saru za sebe, jer je bio očaran njenom ljepotom. Ibrahim, alejhis-selam, nije mogao odbiti vladarev zahtjev da se njegova supruga Sara pojavi na dvoru, ali je mogao činiti dovu Allahu, dž.š., da ih spasi nepravednog vladara. Kada bi vladar krenuo prema Sari, i kad god bi pružio svoje ruke prema njoj da je dodirne, Allah, dž.š., bi učinio da se njegove ruke ukoče. Zamolio bi Saru da moli svoga Gospodara da mu ruke ozdrave, uz obećanje da to više neće činiti. Sara bi učila dovu i ruke bi se vratile u prvobitno stanje. Nakon nekoliko pokušaja vladar se uplašio, pa je nagradivši Saru sluškinjom Hadžerom ipak naredio da se Ibrahim, alejhis-selam, i Sara protjeraju.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Sara je dopustila Ibrahimu, alejhis-selam, da se oženi njenom sluškinjom Hadžerom koja je Ibrahimu, alejhis-selam rodila sina Ismaila. Ibrahim, alejhis-selam, je, po Allahovoj naredbi poveo suprugu Hadžeru i sina Ismaila i krenuo prema području današnje Mekke. Zaustavili su se u mjestu gdje nije bilo vode, niti plodnog tla. Oslanjajući se na Allaha, dž.š., Ibrahim, alejhis-selam, je na tom mjestu ostavio Hadžeru i Ismaila s malo vode i hurmi. Kada je nestalo vode, Hadžera je neprestano trčala između brežuljaka Safe i Merve tražeći vodu za sebe i svoje dijete. Kada je izgubila svaku nadu da će pronaći vodu i zastala kraj Ismaila, ispod njegovih nogu ugledala je kako voda izvire. Hadžera, plašeći se jačine vode koja je izvirala i praveći branu od pijeska da se voda ne razliva uzviknu “Zem-Zem! (Stani-Stani!).” Od tada se dolina Mekke poče naseljavati.<br>\n                    Nakon što je Ismail porastao toliko da mu je u poslu počeo pomagati, Allah, dž.š., je Ibrahimu, alejhis-selam, u snu naredio da žrtvuje svoga sina Ismaila. To je ustvari bilo obećanje Ibrahimovo, alejhis-selam, kada je molio Uzvišenog da mu podari sina. Kada se san ponovio i treći put Ibrahim, alejhis-selam, kazuje svome sinu za svoje obećanje i Allahovu naredbu, a sin Ismail ponizno pristade da bude žrtvovan i reče ocu da učini onako kako je obećao Uzvišenom Allahu i kako mu je u snu naređeno. “Ja ću uistinu biti strpljiv” – reče Ismail.<br>Kada ga je čelom prema zemlji položio, čvrsto odlučivši da ga prinese kao žrtvu, Allah, dž.š., ih obradova velikim kurbanom koji je donio melek Džibril. Ibrahimu, alejhis-selam, je naređeno od Uzvišenog Allaha da sagradi Kabu. U toku gradnje pomagao mu je sin Ismail, a u istočnom uglu Kabe Ibrahim, alejhis-selam, je ugradio jedan kamen posebno interesantan i važan, poznat pod imenom “Hadžerul-esved – Crni kamen”. Događaji i kazivanja o Allahovim poslanicima su od velike važnosti za nas, jer možemo učiti na primjerima njih i njihovih naroda.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - IBRAHIM, A.S.</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Kome se Ibrahim, alejhis-selam, divio tražeći svoga Gospodara?</li>\n                    <li>Ko je bio Azer?</li>\n                    <li>Šta je Ibrahim, alejhis-selam, uradio s kipovima?</li>\n                    <li>Kojim putem su se zaputili Ibrahim, alejhis-selam, i Sara napustivši Mezopotamiju?</li>\n                    <li>Kako se zvao sin Ibrahima, alejhis-selam, i Hadžere?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADATAK</p>\n                <ul class=\"lesson-text\">\n                    <li>Istražite kako se zove voda koja je potekla ispod nogu Ismaila, alejhis-selam!</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":79,"is_published":true,"kviz_pitanja":[{"answer":"Od kipova","options":["Od kipova","Od zvijezda","Od mjeseca","Od sunca"],"question":"Od čega je Ibrahim, a.s., od djetinjstva znao da se ne smiju obožavati?"},{"answer":"Zvijezda, mjesec i sunce","options":["Zvijezda, mjesec i sunce","Samo mjesec i sunce","Samo zvijezde","Samo planete"],"question":"Koji nebeski objekti su Ibrahim vidio dok je razmišljao o svom Gospodaru?"},{"answer":"Ih je porazbijao osim najvećeg","options":["Ih je porazbijao osim najvećeg","Ih je sveporazbijao","Ih je prenio drugdje","Ih je bolje dekorisao"],"question":"Šta je Ibrahim uradio sa kipovima kada su njegovi sunarodnjaci bili zauzeti?"},{"answer":"Vatru je učinio hladnom i spasonosnom","options":["Vatru je učinio hladnom i spasonosnom","Izvukao ga je prije nego što padne","Dao mu je magičnu zaštitu","Stvario je maglu oko njega"],"question":"Kako je Allah, dž.š., zaštitio Ibrahima kada su ga bacili u vatru?"},{"answer":"Najljepša žena tog vremena","options":["Najljepša žena tog vremena","Kćerka njegovog oca","Njegova rodbina iz drugog mjesta","Žena которa je vjerovala u kipove"],"question":"Tko je bila Saora koju se Ibrahim, a.s., oženio?"}]},{"nivo":3,"slug":"musa-as","naslov":"Musa, a.s.","content_html":"<div class=\"lesson-container\">\n        <h1>MUSA, A.S.</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/musa.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Mūsa, a.s. – život i poslanstvo</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i poštovanja prema poslaniku Mūsa, a.s., te slijeđenje njegovog primjera</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa životom, poslanstvom i poukama iz života Mūsa, a.s.</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti izvlačenja pouka iz kazivanja o poslanicima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je Mūsa, a.s.? Šta o njemu znamo iz Kur’ana? Hajde da naučimo više o njegovom životu i poruci.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mūsa, a.s. je jedan od Allahovih poslanika kojeg Kur’an spominje.</p><p>Mūsa, a.s., je odgojen u Faraonovom dvoru, ali se Allah okrenuo k njemu kao poslaniku. Sukobio se sa Faraonom — sa štapom koji se pretvarao u zmiju kao mudžizom. Sa Allahovom pomoći je razdvojio more i izveo Beni-Israil. Na Tūru je razgovarao sa Allahom i primio Tevrat.</p><p>Allah ga je poslao da pozove svoj narod u tewhid – obožavanje samo jednog Allaha.</p><p>Nailazio je na poteškoće i odbijanje, ali je strpljivo nastavljao Allahov poziv.</p><p>Iz njegovog života učimo: strpljivost, iskrenost u pozivu, oslanjanje na Allaha (tevekkul) i ustrajnost u istini.</p><p>Razgovor: koja pouka iz života Mūsa, a.s. nam je posebno bliska?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju ključne događaje. Zaključak: poslanici su uzori koje slijedimo u životu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                ČUDO NA RIJECI NIL <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite dječaka koji svoju životnu avanturu započinje u maloj košari na velikoj, moćnoj rijeci Nil. Dok je opasni vladar faraon tražio dječake, Allah je imao poseban plan za malog Musaa. Od kraljevske palate u kojoj je odrastao, preko susreta sa gorućim grmom na gori Sinaj, pa sve do trenutka kada se more pred njim razdvojilo kao zid, život Musaa, alejhis-selam, je ispunjen čudima koja oduzimaju dah. Danas ćemo naučiti kako je on, uz pomoć svog brata Haruna, stao pred najmoćnijeg čovjeka tog vremena sa samo jednim štapom i nepokolebljivom vjerom u Stvoritelja. Otkrit ćemo zašto je istina uvijek jača od svake vradžbine i kako je jedan narod pronašao put ka slobodi kroz morske talase.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    Kada je Jusuf, alejhis-selam, preselio na bolji i vječni svijet, položaj sinova Israilovih bivao je sve teži, tako da su nakon izvjesnog vremena porobljeni od strane faraona i njegovog naroda. \n                </p>\n                <p class=\"lesson-text\">\n                    Jedne noći faraon je usnio san u kojem je vidio vatru koja iz Jerusalema dolazi u Egipat i spaljuje ga, ali pošteđuje sinove Israilove. Ujutro je faraon sazvao svoje tumače snova i tražio od njih da mu protumače spomenuti san. Rekli su mu da će se među potomcima Israilovim roditi dječak koji će ga svrgnuti s vlasti. Faraon je odmah naredio da se svako muško novorođenče ubije. \n                </p>\n                <p class=\"lesson-text\">\n                    U tom periodu rođen je jedan od odabranih Božijih poslanika – Musa, alejhis-selam Kada je majka Musaa, alejhis-selam, osjetila porođajne bolove, sklonila se pored rijeke Nil kako bi ga rodila daleko od očiju drugih ljudi. Istovremeno je osjećala radost i strah. Radost zbog rođenja sina, a strah zbog faraonove naredbe. \n                </p>\n                <p class=\"lesson-text\">\n                    U tom stanju dobila je nadahnuće od Allaha, dž.š., da stavi sina u košaru koju je isplela od pruća i da ga pusti niz rijeku Nil. Njena kćerka je išla obalom rijeke i pratila košaricu. Allahovom odredbom košarica je stigla do faraonova dvora. Vidjevši je, faraonova žena Asija naredila je da joj se košarica donese, što je i učinjeno. \n                </p>\n                <p class=\"lesson-text\">\n                    Vidjela je dijete prema kome joj se pojavi velika ljubav, pa predloži svome mužu da ga prihvate i da ne strahuje od njega, jer će ga oni odgajati na svome dvoru. \n                </p>\n                <p class=\"lesson-text\">\n                    Kada je trebalo prvi put nahraniti dječaka, on nije htio prihvatiti nijednu dojilju sve dok nije dovedena njegova majka. \n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Opisujući djetinjstvo Musaa, alejhis-selam, Allah, dž.š, kaže: I vratismo ga majci njegovoj da se raduje i da ne tuguje, i da se uvjeri da je Allahovo obećanje istinito; ali većina njih ne zna. (El-Kasas, 13)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Musa, alejhis-selam, je rastao na faraonovom dvoru kao član njihove porodice okružen ljepotom i lagodnim životom. Faraonovu porodicu je smatrao svojom, a rođenu majku je znao kao majku po mlijeku. Asija ga je prihvatila kao vlastito dijete i voljela ga svim svojim bićem. \n                </p>\n                <p class=\"lesson-text\">\n                    Musa, alejhis-selam, je porastao u mladića velike snage, umijeća, znanja i mudrosti. Zapravo su to bili darovi od Allaha, dž.š.:\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        I kad se on opasa snagom i stasa, dadosmo mu mudrost i znanje; tako Mi nagrađujemo one koji dobra djela čine. (El-Kasas, 14)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Nakon nemilog događaja sa čovjekom iz faraonovog naroda, Musa, alejhis-selam, je Allahovom dozvolom napustio Egipat i uputio se u Medjen. Prilazeći izvorima vode medjenske primijetio je da se oko nje okupilo mnogo pastira koji su napajali svoju stoku. Primijetio je i dvije djevojke koje su bile podalje od ostalih pastira i pazile na svoju stoku, odbijajući je od vode. “Zašto to radite?”, upita ih Musa, alejhis-selam ''Ne napajamo stoku dok se ostali pastiri ne udalje od pojilišta, naš otac je veoma star, tako da se nema ko za nas zauzeti i štititi nas u ovakvim momentima.” \n                </p>\n                <p class=\"lesson-text\">\n                    Musa, alejhis-selam, je napojio njihovu stoku i smjestio se u hlad jednog stabla da se odmori. Bio je iscrpljen i gladan pa je uputio dovu Allahu, dž.š., da mu podari hranu koja mu je bila neophodna. Nedugo poslije došla je jedna od dvije djevojke i pozvala ga govoreći da njihov otac želi da ga nagradi zbog toga što je učinio za njih. Njihov otac se zvao Šu'ajb, alejhis-selam Musa, alejhis-selam, se oženio mlađom sestrom i radio na imanju punca Šuʻajba a kada se navršilo deset godina, svoju porodicu je poveo preko Sinajske gore. Idući kroz tamu planine primijetio je svjetlo u daljini, odvojio se od porodice s namjerom da dobije baklju vatre. Tog momenta je primio prvu objavu od Allaha, dž.š., i postao Allahov poslanik. \n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: A da li je do tebe doprla vijest o Musau, kada je vatru ugledao pa čeljadi svojoj rekao: “Ostanite vi tu, ja sam vatru vidio, možda ću vam nekakvu glavnju donijeti ili ću pored vatre naći nekoga ko će mi put pokazati.” A kad do nje dođe, neko ga zovnu: “O Musa, Ja sam, uistinu, Gospodar tvoj! Izuj, zato, obuću svoju, ti si, doista, u blagoslovljenoj dolini Tuva. Tebe sam izabrao, zato ono što ti se objavljuje slušaj.” (Ta-Ha, 9-13)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Kao poslanika, Allah ga je poslao faraonu s jasnim dokazima, štapom koji se pretvarao u zmiju i rukom koja je postajala bijela, koji potvrđuju da je poslan od Allaha, dž.š. Uz to, Musa, alejhis-selam, je molio Allaha da mu podari brata Haruna za pomagača, pa mu je dova uslišana. Faraon se uzoholio nad ljudima, te njima i svojim velikodostojnicima rekao: \n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        “Ja sam gospodar vaš najveći.” (En-Naziʻat, 24)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Kada mu je Musa, alejhis-selam, pokazao dokaze poslanstva i pozvao ga da vjeruje u Jedinog Boga, Allaha, dž.š., Stvoritelja nebesa i Zemlje, faraon je odbio negirajući istinu koja je došla od Allaha, dž.š., preko poslanika Musaa, alejhis-selam \n                </p>\n                <p class=\"lesson-text\">\n                    Faraon je sakupio svoje podanike i narod na dogovorenom mjestu, a na čelu su bili čarobnjaci sve vještiji od vještijeg koji su pomagali faraonu da vlada narodom i da ih drži u zabludi i nevjerovanju. \n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        “O Musa” , ‒ rekoše oni – “hoćeš li ti ili ćemo najprije mi baciti?” “Bacite vi!” – reče on – i odjednom mu se pričini da se konopi njihovi i štapovi njihovi, zbog vradžbine njihove, kreću, i Musa u sebi osjeti zebnju. “Ne boj se!” – rekosmo Mi – “ti ćeš, doista, pobijediti! Samo baci to što ti je u desnoj ruci, progutat će ono što su oni napravili, jer je ono što su oni napravili samo varka čarobnjaka, a čarobnjak neće, ma gdje došao, uspjeti.” (Ta-Ha, 65-69)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Kada su čarobnjaci vidjeli istinitost mudžiza Musaa, alejhis-selam, i pored faraonove prijetnje i kazne kojom ih je kaznio, oni povjerovaše i učiniše sedždu Gospodaru svjetova. \n                </p>\n                <p class=\"lesson-text\">\n                    Po Allahovoj zapovijedi, Musa, alejhis-selam, u okrilju noći povede svoj narod iz faraonovog zatočeništva, a za petama su im bili faraon i vojska njegova. Ispred Musaa, alejhis-selam, i njegovog naroda se ispriječilo more. Tada Allah naredi Musau, alejhis-selam, da udari štapom po moru, što je on i učinio, a Allahovom odredbom more se razdvojilo. Musa, alejhis-selam, i vjernici su prešli, a faraon i njegova vojska se utopili jer se more vratilo u prvobitno stanje. Allah, dž.š., u Kur’anu spominje pokajanje faraonovo koje je izrečeno kasno, a nakon što su ga morski talasi zapljusnuli: \n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        “Ja vjerujem da nema boga osim Onoga u kojeg vjeruju sinovi Israilovi i ja se pokoravam!” – “Zar sada, a prije si neposlušan bio i razdor sijao? – Danas ćemo izbaviti samo tijelo tvoje da bi bio poučan primjer onima poslije tebe.” (Junus, 90-92)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Tako je spašen Musa, alejhis-selam, i njegov narod, a faraonovo tijelo sačuvano kao pouka onima koji se ohole prema Allahu, dž.š., i druge Mu ravnim smatraju.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - MUSA, A.S.</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Gdje je rođen Musa, alejhis-selam?</li>\n                    <li>U kojem vremenu je rođen Musa, alejhis-selam?</li>\n                    <li>Šta je Musaova majka učinila sa njim?</li>\n                    <li>Gdje je odrastao Musa, alejhis-selam, i kako je Allah, dž.š., spojio njega i njegovu majku?</li>\n                    <li>Kako je spašen Musa, alejhis-selam, i njegov narod?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADATAK</p>\n                <p class=\"lesson-text\">\n                    Kur’an navodi da će tijelo faraonovo biti sačuvano kao opomena svim ljudima do Sudnjeg dana. Istražite gdje je pronađeno faraonovo tijelo te gdje se danas nalazi?\n                </p>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":80,"is_published":true,"kviz_pitanja":[{"answer":"Vatru koja dolazi iz Jerusalema i spaljuje Egipat","options":["Vatru koja dolazi iz Jerusalema i spaljuje Egipat","Veliku poplavu rijeke Nil","Vojsku koja napada njegov dvor","Zvijezde kako padaju sa neba"],"question":"Šta je faraon vidio u svojoj noći kada je usnuo san?"},{"answer":"Pored rijeke Nil","options":["Pored rijeke Nil","U faraonovom dvoru","U šumi daleko od grada","Na planini uz more"],"question":"Gdje je majka Muse rodila proroka Musu, a.s.?"},{"answer":"Faraonova žena Asija","options":["Faraonova žena Asija","Faraon i njegovi vojnici","Ribari na rijeci","Trgovci od robe"],"question":"Tko je prvu košaricu sa malim Musom, a.s., pronašao?"},{"answer":"Dok nije dovedena njegova prava majka","options":["Dok nije dovedena njegova prava majka","Jer je bio jako gladan","Jer je bio bolestan","Jer je volio samo vodu"],"question":"Zašto je mali Musa, a.s., odbio sve dojillje?"},{"answer":"Kao član njihove porodice okružen ljepotom","options":["Kao član njihove porodice okružen ljepotom","Kao rob koji je morao da radi","Kao časnik u faraonovoj vojski","Kao učenik trgovačkog zanata"],"question":"Kako je Musa, a.s., rastao u faraonovom dvoru?"}]},{"nivo":3,"slug":"isa-as","naslov":"Isa, a.s.","content_html":"<div class=\"lesson-container\">\n        <h1>ISA, A.S.</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/isa.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Īsa, a.s. – život i poslanstvo</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i poštovanja prema poslaniku Īsa, a.s., te slijeđenje njegovog primjera</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa životom, poslanstvom i poukama iz života Īsa, a.s.</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti izvlačenja pouka iz kazivanja o poslanicima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je Īsa, a.s.? Šta o njemu znamo iz Kur’ana? Hajde da naučimo više o njegovom životu i poruci.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Īsa, a.s. je jedan od Allahovih poslanika kojeg Kur’an spominje.</p><p>Īsa, a.s., je rođen čudesno, bez oca, od majke Merjem. Govorio je u kolijevci, liječio bolesne, oživljavao mrtve uz Allahovu dozvolu. Donijeo je Indžil. Allah ga je uzdigao k Sebi prije nego što su ga uspjeli ubiti — vratit će se pred Sudnji dan.</p><p>Allah ga je poslao da pozove svoj narod u tewhid – obožavanje samo jednog Allaha.</p><p>Nailazio je na poteškoće i odbijanje, ali je strpljivo nastavljao Allahov poziv.</p><p>Iz njegovog života učimo: strpljivost, iskrenost u pozivu, oslanjanje na Allaha (tevekkul) i ustrajnost u istini.</p><p>Razgovor: koja pouka iz života Īsa, a.s. nam je posebno bliska?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju ključne događaje. Zaključak: poslanici su uzori koje slijedimo u životu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                ZAGONETNA LIČNOST KUR'ANA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Postoje događaji u historiji koji prkose svemu što smatramo običnim. Jedan od takvih događaja je dolazak Isaa, alejhis-selam, na ovaj svijet. Rođen bez oca, od plemenite majke Merjeme, on je od samog trenutka rođenja bio znak Allahove moći. Dok su drugi sumnjali i napadali, on je još kao novorođenče progovorio iz bešike, braneći čast svoje majke i najavljujući svoju veliku misiju. Njegov život ispunjen je čudima – od iscjeljivanja bolesnih do vraćanja mrtvih u život Allahovom voljom. Danas ćemo istražiti istinu o Isau, alejhis-selam, onako kako je zapisana u Kur'anu, i naučiti zašto je on bio jedan od najodabranijih Allahovih poslanika čija priča i danas fascinira svijet.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    Posebno zagonetna ličnost koja se spominje kroz cijeli Kur'an jeste ličnost odabranog poslanika Isaa, alejhis-selam, sina Merjemina. Cijeli život Isaa, alejhis-selam, je interesantan, posebno njegovo začeće jer je rođen bez oca, njegov govor dok je bio dojenče, njegove mudžize, život i odlazak s ovoga svijeta. To su nesvakidašnji događaji o kojima nas Uzvišeni Allah detaljno obavještava, a koje trebamo prvenstveno vjerovati onako kako je navedeno ili spomenuto u Kur’anu.\n                </p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PORIJEKLO I ROĐENJE ISAA, A.S.</p>\n                <p class=\"lesson-text\">\n                    Porijeklo Isaa, alejhis-selam, vezuje se za jednu od najodabranijih porodica, porodicu Imranovu iz koje potječe njegova majka hazreti Merjema. \n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I Gospodar njezin primi je lijepo i učini da uzraste lijepo, i da se o njoj brine Zekerija. Kad god bi joj Zekerija u hram ušao, kod nje bi hrane našao. “Odakle ti ovo, o Merjema?” – on bi upitao, a ona bi odgovorila: “Od Allaha, Allah onoga koga hoće opskrbljuje bez muke. (Alu Imran, 37)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Isaov, alejhis-selam, dolazak na ovaj svijet je poseban i jedinstven jer je Allahovom odredbom rođen bez oca. Melek Džibril je udahnuo u Merjem, majku Isaa, alejhis-selam, te je postala noseća. Zbog toga što Merjema nije imala muža, njena porodica i okolina su je napadali, te ona po Allahovom određenju ode iz svog mjesta i zaustavi se pored stabla jedne palme ispod kojeg je potok tekao. O njenom povratku svojoj porodici Kur'an kaže:\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        I dođe ona s njim porodici svojoj, noseći ga. “O Merjemo” , – rekoše oni – “učinila si nešto nečuveno! Ej ti, koja u čednosti ličiš Harunu, otac ti nije bio nevaljao, a ni mati tvoja nije bila nevaljalica.” A ona im na njega pokaza. “Kako da govorimo djetetu u bešici?” – rekoše. “Ja sam Allahov rob” – ono reče – “meni će On Knjigu dati i vjerovjesnikom me učiniti i učinit će me, gdje god budem, blagoslovljenim, i naredit će mi da dok sam živ molitvu obavljam i milostinju udjeljujem, i da majci svojoj budem dobar, a neće mi dopustiti da budem drzak i nepristojan. I neka je mir nada mnom na dan kada sam se rodio i na dan kada budem umro i na dan kada budem iz mrtvih ustajao!” To je Isa, sin Merjemin – to je prava istina o njemu – onaj u koga oni sumnjaju. (Merjem, 27-34)\n                    </p>\n                </div>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">MUDŽIZE ISAA, A.S.</p>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Kad Allah rekne: “O Isa, sine Merjemin, sjeti se blagodati Moje prema tebi i majci tvojoj: kada sam te Džibrilom pomogao pa si s ljudima, u bešici i kao zreo muž, razgovarao; i kada sam te pismenosti i mudrosti, i Tevratu i Indžilu naučio; i kada si, voljom Mojom, od blata nešto poput ptice napravio i u nju udahnuo, i kada je ona, voljom Mojom, postala ptica; i kada si, voljom Mojom, od rođenja slijepa i gubavca iscijelio; i kada si, voljom Mojom, mrtve dizao; i kada sam od tebe sinove Israilove odbio, kad si im ti jasne dokaze donio, pa su oni među njima koji nisu vjerovali – povikali: ‘Ovo nije ništa drugo do prava vradžbina!’” (El-Maide, 110)\n                    </p>\n                </div>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ISA, A.S., NIJE BOŽIJI SIN NITI JE UBIJEN</p>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        O sljedbenici Knjige, ne zastranjujte u svome vjerovanju i o Allahu govorite samo istinu! Mesih, Isa, sin Merjemin, samo je Allahov poslanik, i Riječ Njegova koju je Merjemi dostavio, i Duh od Njega; zato vjerujte u Allaha i Njegove poslanike i ne govorite: “Trojica su!” Prestanite, bolje vam je! Allah je samo jedan Bog – hvaljen neka je On! – zar On da ima dijete?! Njegovo je ono što je na nebesima i ono što je na Zemlji, i Allah je dovoljan kao zaštitnik. (En-Nisa, 171)\n                    </p>\n                    <p class=\"lesson-text\">\n                        I zbog riječi njihovih: “Mi smo ubili Mesiha, Isaa, sina Merjemina, Allahovog poslanika!” A nisu ga ni ubili ni raspeli, već im se pričinilo. Oni koji su se o njemu u mišljenju razilazili, oni su sami o tome u sumnji bili; o tome nisu ništa pouzdano znali, samo su nagađali; a sigurno je da ga nisu ubili, već ga je Allah uzdigao Sebi. A Allah je silan i mudar. (En-Nisa, 157-158)\n                    </p>\n                </div>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ISA, A.S., I LJUDI KOJI SU GA SMATRALI “BOŽIJIM SINOM”</p>\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        A kada Allah rekne: “O Isa, sine Merjemin, jesi li ti govorio ljudima: ‘Prihvatite mene i majku moju kao dva boga uz Allaha!’” – on će reći: “Hvaljen neka si Ti! Meni nije priličilo da govorim ono što nemam pravo. Ako sam ja to govorio, Ti to već znaš; Ti znaš šta ja znam, a ja ne znam šta Ti znaš; Samo Ti jedini sve što je skriveno znaš. Ja sam im samo ono govorio što si mi Ti naredio: ‘Klanjajte se Allahu, i mome i svome Gospodaru!’ I ja sam nad njima bdio dok sam među njima bio, a kad si mi Ti dušu uzeo, Ti si ih jedini nadzirao.” (El-Maide, 116-117)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Bez kur’anskog kazivanja o Isau, alejhis-selam, mi ne bismo ništa znali ili bismo samo nagađali, zato hvala Allahu Gospodaru svjetova.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ISA, A.S.</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>U kojoj porodici je rođen Isa, alejhis-selam?</li>\n                    <li>Šta je specifično u Isaovom, alejhis-selam, rođenju?</li>\n                    <li>Po čemu je on bio specifično dijete?</li>\n                    <li>Koga Kur’an spominje od Isaove porodice?</li>\n                    <li>Koje su mudžize Isaa, alejhis-selam?</li>\n                    <li>Koji odgovor biste dali onima koji tvrde da je Isa, alejhis-selam, “Božiji sin”?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Istraži šta su u svom vjerovanju kršćani iskrivili kada je u pitanju Isa, alejhis-selam?</li>\n                    <li>Gdje se nalazi Isa, alejhis-selam, i kada će doći na Zemlju?</li>\n                </ol>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\" style=\"text-align: center;\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        Isa, alejhis-selam, je velika nepoznanica onima koji ne čitaju Kur’an.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":81,"is_published":true,"kviz_pitanja":[{"answer":"Hazreti Merjema","options":["Hazreti Merjema","Hazreti Asija","Hazreti Aisha","Hazreti Fatima"],"question":"Ko je bila majka Isaa, a.s.?"},{"answer":"Bez oca, po Allahovoj odredbi","options":["Sa ocem i majkom","Bez oca, po Allahovoj odredbi","Sa dvoje očeva","Sa više браće"],"question":"Na koji način je Isa, a.s., rođen?"},{"answer":"Porodica Imranovna","options":["Porodica Hashimova","Porodica Imranovna","Porodica Umayyadska","Porodica Kureševa"],"question":"Ko je bila porodica iz koje potječe Merjema?"},{"answer":"Ja sam Allahov rob","options":["Nisam siguran","Ja sam Allahov rob","Pozovite mi oca","Tražim mliko"],"question":"Šta je Isa, a.s., rekao kao dojenče?"},{"answer":"Melek Džibril","options":["Arkanđeo Mikailo","Melek Džibril","Anđeo Izrailo","Melek Azrailo"],"question":"Ko je udahnuo u Merjem majku Isaa, a.s.?"}]},{"nivo":3,"slug":"muhammed-as-djetinjstvo","naslov":"Djetinjstvo Muhammeda, a.s.","content_html":"<div class=\"lesson-container\">\n        <h1>DJETINJSTVO MUHAMMEDA, A.S.</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/djetinjstvo.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Djetinjstvo Muhammeda, a.s.</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje duboke ljubavi prema Poslaniku, a.s., kroz upoznavanje njegovog djetinjstva</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti glavne događaje iz djetinjstva Poslanika, a.s.</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti slijeđenja Poslanikovog primjera od najmlađih dana</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kakvo je bilo djetinjstvo našeg Poslanika, a.s.? Da li je imao oca i majku? Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Muhammed, a.s., rođen je u Mekki, 12. rebiul-evvela, godine slona (570.), kao siroče — otac Abdullah umro prije njegovog rođenja.</p><p>Po običaju Mekke, dijete je dato dojilji u pustinju — Halīma Sa‘dijja, sa kojom je proveo prve godine.</p><p>Sa 6 godina umrla mu je majka Āmina — postao je potpuno siroče.</p><p>Brigu o njemu preuzeo djed Abdul-Muttalib, koji je umro kad mu je bilo 8 godina.</p><p>Potom o njemu vodi brigu amidža Ebu Tālib, koji ga je vodio na trgovačka putovanja u Šam.</p><p>Već kao dijete bio je iskren, povjerljiv, čuvao stoku — narod ga je nazivao \"El-Emīn\" (Pouzdani).</p><p>Sa 25 godina oženio se časnim Hadidžom, prvom svojom suprugom.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju ključne događaje. Zaključak: i kao siroče, Allah je čuvao i spremao Svog Poslanika.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                DJETINJSTVO POD ALLAHOVOM ZAŠTITOM <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Život posljednjeg Božijeg poslanika, Muhammeda, alejhis-selam, počeo je iskušenjima koja bi malo ko mogao izdržati, ali je svaki njegov korak bio praćen posebnom pažnjom Stvoritelja. Od ranog djetinjstva u mirisnoj pustinji kod dojilje Halime, preko gubitka majke i djeda, pa sve do putovanja karavanima kroz vrelu pustinju, Muhammed, alejhis-selam, je stasao u osobu izuzetnog karaktera i snage. Čak i kao dječak, on je privlačio pažnju svojom ozbiljnošću i blagoslovom (bereketom) koji bi donosio svakome ko bi se o njemu brinuo. Danas ćemo naučiti kako je on proveo svoje prve godine, ko ga je odgajao i koji su to znakovi još tada najavljivali da će upravo taj dječak postati milost svim svjetovima.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    Allahov poslanik Muhammed, alejhis-selam, potječe iz porodice Hašim iz plemena Kurejš koje je u to vrijeme bilo jedno od najpoznatijih i najuglednijih plemena u Mekki. Njegov otac Abdullah, sin Abdulmuttalibov, umro je dva mjeseca prije njegovog rođenja. Majka Amina ga je donijela na svijet 12. rebi'ul-evvela/20. aprila 571. godine u gradu Mekki.\n                </p>\n                \n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Godine 571. n.e. etiopski vladar Ebreha krenuo je s vojskom i slonovima. Ta godina se naziva Godina slona. Te godine se rodio Poslanik, alejhis-selam\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    U vremenu kada je rođen posljednji Allahov poslanik Muhammed, alejhis-selam, ugledne porodice iz Mekke su svoju mušku djecu davale na dojenje u sela kako bi u pustinji proveli dio svog djetinjstva. Spomenuti običaj činio se iz nekoliko razloga:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>djecu je trebalo skloniti iz Mekke od raznih zaraznih bolesti koje su često harale gradovima,</li>\n                    <li>muška djeca su lakše i brže odrastala na čistom pustinjskom zraku, a uz to bili bi jači i čvršći,</li>\n                    <li>djeca su lakše učila čisti arapski jezik kojim su govorila pustinjska arapska plemena,</li>\n                    <li>boraveći među nomadima naučili bi se i raznim vještinama poput hrvanja, jahanja i gađanja lukom i strijelom.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Tako je Amina svoga dječaka dala u pleme Benu Saʻd kod Halime, koja je uživala veliki ugled kod mekanskih porodica iz razloga što se dobro brinula o djeci koju bi preuzela na dojenje. Godina u kojoj je rođen posljednji poslanik, alejhis-selam, prema priči Halime, bila je dosta sušna i oskudna. Halima pripovijeda da je iz svog sela krenula s mužem Harisom, jahala je na magarcu, a muž je vodio staru devu, među posljednjima su stigli u Mekku. \n                </p>\n                <p class=\"lesson-text\">\n                    Kaže Halima: “Svakoj od žena je nuđen Muhammed, alejhis-selam, ali su žene odbile da ga uzmu jer se nisu nadale da će majka i djed moći dobro platiti. U međuvremenu, žene su uzele djecu iz bogatih porodica, a meni nije ostalo nijedno dijete. Bilo me stid da se kući vratim bez dojenčeta pa sam odlučila da uzmem Muhammeda. Rekla sam mužu: ‘Ipak ću otići do onog siročeta i uzeti ga, možda će nam u njemu Allah dati bereket (blagoslov).’ ‘Kada sam ga uzela i primakla sebi, osjetila sam kako mi mlijeko navire u moja prsa, nadojio se i zaspao, a nakon njega nadojio se i moj sin koji je prethodne noći plakao od gladi jer u mojim prsima nije bilo mlijeka pa je i on zaspao. Moj muž je primijetio da je u naše stare i oronule deve nadošlo mlijeko pa smo je pomuzli i oboje se dobro nahranili i zaspali.’”\n                </p>\n                <p class=\"lesson-text\">\n                    Tada mi je muž rekao: “Znaš, Halima, uzela si blagoslovljeno stvorenje.” Kada su Halima i njen muž stigli kući, primijetili su da njihove ovce daju dosta više mlijeka i tako danima poslije toga. Muhammed, alejhis-selam, je odrastao na čistom zraku arapske pustinje i kada je navršio dvije godine Halima ga je odbila od dojenja jer je već bio napredan. S obzirom na to da je završeno dojenje, Halima je vratila Muhammeda, alejhis-selam, njegovoj majci, ali je i nagovarala njegovu majku Aminu da ga ponovo vrati na selo zbog blagostanja koje su uživali uz Muhammeda, alejhis-selam Amina je pristala da se dječak vrati na selo gdje je boravio još dvije godine. \n                </p>\n                <p class=\"lesson-text\">\n                    Kada je Muhammed, alejhis-selam, napunio četiri godine, desio se jedan događaj koji je bio povod da Halima vrati Muhammeda, alejhis-selam, njegovoj majci Amini. Naime, jednog dana dok je Poslanik, alejhis-selam, boravio iza šatora majke po mlijeku, dotrčao je njen sin i rekao da su dvojica ljudi u bijelom otvorili prsa i isprali srce Muhammedu, alejhis-selam Halima i njen muž su, bojeći se za njegovu sigurnost, nerado odlučili vratiti Muhammeda, alejhis-selam, Amini u Mekku.\n                </p>\n                <p class=\"lesson-text\">\n                    Muhammed, alejhis-selam, je petu godinu svoga života proveo s majkom Aminom, a kada je nastupila šesta godina Amina je odlučila da posjeti svoju rodbinu u Medini i da svom sinu pokaže gdje je ukopan njegov otac Abdullah. U povratku, Amina se u mjestu Ebva iznenada razboljela a nakon toga i umrla. Muhammeda, alejhis-selam, je preuzeo djed Abdulmuttalib, koji je već tada bio u poznim godinama. Vodio ga je sa sobom i nije se od njega odvajao. Druženje s djedom je trajalo kratko jer je u osmoj godini Poslanikova, alejhis-selam, života umro i djed Abdulmuttalib, a brigu o Muhammedu, alejhis-selam, je preuzeo amidža Ebu Talib i njegova supruga Fatima. Ebu Talib se bavio trgovinom, a često je vodio Muhammeda, alejhis-selam, sa sobom. Imao je dosta djece tako da je siromašno živio, zato je Muhammed, alejhis-selam, samovoljno čuvao stada mekanskih porodica kako bi amidži pomogao da izdržava porodicu.\n                </p>\n                <p class=\"lesson-text\">\n                    Kada je jedne prilike Ebu Talib pošao u Šam radi trgovine, poveo je sa sobom svoga bratića. Odsjeli su kod jednog kršćanskog monaha zvanog Behira kako bi odmorili. Monah je primijetio na dječaku znakove poslanstva, jer je iz svojih vjerskih knjiga znao da se približilo vrijeme slanja poslanika iz arapskog naroda. Nakon razgovora s Ebu Talibom Behira se dodatno uvjerio da će dječak biti budući Božiji poslanik pa je savjetovao Ebu Talibu da ga vrati u Mekku jer ako ga židovi primijete, mogli bi mu nauditi.\n                </p>\n                \n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        Muhammedu, alejhis-selam, je oblak pravio hlad na putovanju s amidžom, Behira je to primijetio i zaključio da je posebno dijete.\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Nakon što je Muhammed, alejhis-selam, napunio dvadeset godina počeo se baviti trgovinom tako što je od bogatih ljudi Mekke uzimao karavane, i za određen procenat zarade prodavao robu.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - DJETINJSTVO MUHAMMEDA, A.S.</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Iz koje porodice je potjecao Muhammed, alejhis-selam, i kako se zovu njegovi roditelji?</li>\n                    <li>Navedi neke od razloga Muhammedovog odrastanja na selu?</li>\n                    <li>Koji su se zanimljivi događaji dogodili njegovoj dojilji?</li>\n                    <li>Kada je Muhammed, alejhis-selam, ostao bez oca i majke?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADATAK</p>\n                <p class=\"lesson-text\">\n                    Opiši događaj koji se dogodio prilikom Poslanikovog putovanja u Šam s amidžom Ebu Talibom!\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        Prvo Poslanikovo, alejhis-selam, ispiranje srca dogodilo se za vrijeme njegovog boravka kod dojilje Halime. Da li je još nekada Poslaniku, alejhis-selam, očišćeno srce, a ako jeste, kada se to dogodilo?\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":82,"is_published":true,"kviz_pitanja":[{"answer":"Iz plemena Kurejš","options":["Iz plemena Kurejš","Iz plemena Benu Saʻd","Iz plemena Hašim","Iz plemena Etiopije"],"question":"Iz kojeg plemena je potjecao Poslanik Muhammed, a.s.?"},{"answer":"Godina 571.","options":["Godina 570.","Godina 571.","Godina 572.","Godina 573."],"question":"Koja godina se naziva Godina slona?"},{"answer":"Halima","options":["Amina","Halima","Harise","Ebreha"],"question":"Kako se zvala dojilja koja je odgajala Muhammeda, a.s.?"},{"answer":"Zaštita od bolesti i bolji razvoj","options":["Već što se djeca igraju","Zaštita od bolesti i bolji razvoj","Djeca nisu željeli biti u Mekki","Roditelji su bili previše bogati"],"question":"Šta je bila GLAVNA svrha davanja djece na dojenje u sela?"},{"answer":"12. rebi'ul-evvela 571. godine","options":["12. rebi'ul-evvela 570. godine","12. rebi'ul-evvela 571. godine","20. aprila 570. godine","20. aprila 572. godine"],"question":"Kada je rođen Poslanik Muhammed, a.s.?"}]},{"nivo":3,"slug":"muhammed-as-porodica","naslov":"Porodica poslanika Muhammeda, a.s.","content_html":"<div class=\"lesson-container\">\n        <h1>PORODICA POSLANIKA MUHAMMEDA, A.S.</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/medina.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Porodica poslanika Muhammeda, a.s.</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i poštovanja prema Ehlul-bejtu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa porodicom Poslanika, a.s.</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike učenja salavata na Poslanika i njegovu porodicu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko su bili u porodici našeg Poslanika, a.s.? Supruge, djeca? Hajde da ih upoznamo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Otac: Abdullah ibn Abdul-Muttalib (umro prije Poslanikovog rođenja). Majka: Āmina bint Vehb (umrla kad je Poslaniku bilo 6 godina).</p><p>Supruge — \"Majke vjernika\":  Hadidža (prva, najljubljenija), Sevda, Aiša, Hafsa, Zejneb bint Huzejma, Ummu Selema, Zejneb bint Džahš, Džuvejrija, Ummu Habiba, Safijja, Mejmuna, Marija el-Kibtijja.</p><p>Djeca: Sa Hadidžom — Kasim, Zejneb, Rukajja, Ummu Kulsum, Fatima, Abdullah. Sa Marijom el-Kibtijjom — Ibrahim. Sva djeca su umrla u djetinjstvu osim Fatime.</p><p><strong>Fatima, r.a.</strong> — najmlađa kćer; udala se za Aliju, r.a.; iz njenog potomstva su Hasan i Husein, r.a.</p><p>Ehlul-bejt — Poslanikova porodica: Ali, Fatima, Hasan, Husein, r.a.</p><p>Naša obaveza: voljeti ih, učiti za njih salavat, slijediti njihove primjere.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju Poslanikove kćeri i unuke. Zaključak: Ehlul-bejt — naša najljepša porodica.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":83,"is_published":true,"kviz_pitanja":[{"answer":"Hatidža bint Huvejlid","options":["Hatidža bint Huvejlid","Asija bint Muzahim","Merjem bint Imran","Ummu Kulsum"],"question":"Kako se zvala prva supruga Poslanika Muhammeda, a.s.?"},{"answer":"Sedmero djece","options":["Troje djece","Četvero djece","Sedmero djece","Petero djece"],"question":"Koliko je djece imao Muhammed, a.s.?"},{"answer":"Desete godine po poslanstvu","options":["Devete godine po poslanstvu","Desete godine po poslanstvu","Jedanaeste godine po poslanstvu","Osme godine po poslanstvu"],"question":"Koje godine je umrla Hatidža, supruga Poslanika?"},{"answer":"Zejneb","options":["Rukaja","Zejneb","Fatima","Ummu Kulsum"],"question":"Kako se zvala najstarija kćer Muhammeda, a.s.?"},{"answer":"Onaj bez repa – bez muškog potomstva","options":["Onaj koji je bošta","Onaj bez repa – bez muškog potomstva","Onaj koji je siroče","Onaj koji je ljubomoran"],"question":"Šta znači pogrdni nadimak 'ebter' koji su mušrici dali Muhammedu, a.s.?"}]},{"nivo":3,"slug":"hidzra","naslov":"Hidžra – prelazak iz Mekke u Medinu","content_html":"<div class=\"lesson-container\">\n        <h1>HIDŽRA – PRELAZAK IZ MEKKE U MEDINU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/hidzra.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Hidžra – prelazak iz Mekke u Medinu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje hrabrosti i odlučnosti u istini, te razumijevanje žrtve za vjeru</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti razloge i tok Hidžre i njenu važnost</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti zašto je Hidžra početak islamskog kalendara</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, zašto se musliman seli iz svog grada? Šta je Hidžra? Šta se desilo i zašto je tako važna?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Hidžra — preseljenje Poslanika, a.s., i muslimana iz Mekke u Medinu, 622. godine.</p><p>Razlog: Mekkanski mušrici su žestoko progonili muslimane, neki su ubijeni, drugi mučeni.</p><p>Allah je dozvolio Hidžru — Poslanik je sa Ebu Bekrom putovao 3 dana, sakrivajući se u pećini Sevr.</p><p>Mušrici su za njegovu glavu obećali nagradu od 100 deva, ali Allah ih je sačuvao.</p><p>U Medini su muslimani primljeni od strane \"ensarija\" (medinskih pomagača); došljaci se zovu \"muhādžiri\" (preseljeni).</p><p>Posljedice: prva islamska država, izgradnja Mesdžid en-Nebevi, bratimljenje između muhādžira i ensārija, prvi Ustav (Medinska povelja).</p><p>Hidžra je početak islamskog kalendara (Hidžretska godina) — odluka Omera, r.a.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju Hidžru. Zaključak: Hidžra je hrabrost, žrtva i početak nove epohe.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":84,"is_published":true,"kviz_pitanja":[{"answer":"Mjesec juli godine 620.","options":["Mjesec juli godine 620.","Mjesec види godine 622.","Mjesec oktober godine 619.","Mjesec april godine 621."],"question":"U kojem mjesecu i godini se Muhammed, alejhis-selam, susreo s prvom grupom iz Jesriba?"},{"answer":"Šest osoba","options":["Dvanaest osoba","Šest osoba","Dvadeset osoba","Tri osobe"],"question":"Koliko je bilo članova u prvoj grupi koja je susrela Muhammeda, alejhis-selam, kod Akabe?"},{"answer":"Jesrib","options":["Jesrib","Mekka","Taif","Khajbar"],"question":"Koji grad je bio predislamski naziv za Medinu?"},{"answer":"Ebu Bekr","options":["Ebu Bekr","Alija","Uthman","Umar"],"question":"Ko je bio Muhammadov vjerni drug koji je ostao s njim do kraja u Mekki?"},{"answer":"Jer će im pružiti zaštitu koju nemaju u Mekki","options":["Jer će im pružiti zaštitu koju nemaju u Mekki","Jer je bilo više tla u Jesribu","Jer su htjeli da budu vojnici","Jer je Muhammed to naredio"],"question":"Zašto su stanovnici Jesriba pozvali muslimane da se sele iz Mekke?"}]},{"nivo":3,"slug":"bitka-bedr","naslov":"Bitka na Bedru","content_html":"<div class=\"lesson-container\">\n        <h1>BITKA NA BEDRU</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/bedr.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Bitka na Bedru</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje povjerenja u Allahovu pomoć i vrijednost iskrene namjere</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tok i značaj prve velike bitke islama</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti vrijednost ashaba koji su učestvovali u bitki</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta se desilo u prvoj velikoj bitki muslimana? Bedru. Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Bitka na Bedru — 17. ramazana 2. h. (624. g.); između muslimana (313 ljudi) i mušrika iz Mekke (oko 1000).</p><p>Razlog: muslimani su pošli da presretnu mekkansku karavanu (kao odmazda za oduzeti imetak); mušrici su poslali vojsku da je odbrane.</p><p>Mjesto: Bedr — bunari južno od Medine.</p><p>Ishod: Allahova pomoć — meleki su se borili uz muslimane; pobjeda velika; ubijeni mnogi vođe mušrika (Ebu Džehl, ‘Utba, Šejba).</p><p>Vrijednost ashaba sa Bedra (\"ehlu-Bedr\"): Poslanik, a.s., rekao je da im Allah oprasta sve buduće grijehe.</p><p>Posljedice: muslimani postaju prepoznata vojna sila; jača njihov moral i vjera.</p><p>Pouka: Allah pomaže one koji se na Njega oslone, ma koliko bilo malo.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o pouci. Zaključak: snaga ne leži u broju nego u imanu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":85,"is_published":true,"kviz_pitanja":[{"answer":"U mjesecu ramazanu","options":["U mjesecu šaabanu","U mjesecu ramazanu","U mjesecu muhareму","U mjesecu džumadi"],"question":"U kojem mjesecu se dogodila Bitka na Bedru?"},{"answer":"314 boraca","options":["Oko 500 boraca","Oko 1000 boraca","314 boraca","Oko 200 boraca"],"question":"Koliko muslimana je učestvovalo u Bici na Bedru?"},{"answer":"Presretanje mušričke trgovačke karavane","options":["Osvajanje Mekke","Presretanje mušričke trgovačke karavane","Osvajanje Sirije","Odbrana Medine od napada"],"question":"Šta je bio glavni povod Bitke na Bedru?"},{"answer":"Ebu Sufjan","options":["Utbe","Šejba","Ebu Sufjan","Velid"],"question":"Koji je vođa trgovačke karavane pozvao pomoć iz Mekke?"},{"answer":"Hamza, Alija i Ubejd ibn Haris","options":["Alija i Ubejd ibn Haris","Hamza, Alija i Ubejd ibn Haris","Samo Hamza","Samo Alija"],"question":"Ko je izašao ispred muslimanske vojske na dvoboj?"}]},{"nivo":3,"slug":"oprostajni-hadz","naslov":"Oproštajni hadž","content_html":"<div class=\"lesson-container\">\n        <h1>OPROŠTAJNI HADŽ</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/oprostajni_hadz.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Oproštajni hadž</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Poslanikovim, a.s., posljednjim porukama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta se desilo na oproštajnom hadžu i koje su glavne poruke</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti i živjeti po porukama oproštajnog hutbe</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je bio posljednji veliki događaj u Poslanikovom životu? Oproštajni hadž. Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Oproštajni hadž — Poslanikov, a.s., jedini i posljednji hadž, 10. h.g. (632. g.).</p><p>Sa Poslanikom su bila preko 100.000 muslimana — najveći skup do tada.</p><p>Na Arefatu Poslanik je održao oproštajni hutbu — temelj islamskog moralnog kodeksa.</p><p>Glavne poruke: <strong>1.</strong> Sva ljudska krv i imovina su sveti; <strong>2.</strong> Kamata je ukinuta; <strong>3.</strong> Žene imaju prava — pazite na njih; <strong>4.</strong> Svi ste vi od Adema, Adem od zemlje — nema razlike Arap-nearap, bijelac-crnac osim po takvaluku; <strong>5.</strong> Ostavljam vam dvije stvari kojih se držite — Kur’an i moj sunnet.</p><p>Tu je objavljen ajet: \"Danas sam vam vjeru vašu upotpunio i blagodat Svoju prema vama dovršio i zadovoljan sam da vam islam bude vjera.\"</p><p>Tri mjeseca poslije, Poslanik je preselio na ahiret.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o porukama oproštajnog hutbe. Zaključak: ovo su Poslanikovi testament i naša obaveza.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":86,"is_published":true,"kviz_pitanja":[{"answer":"U mjesecu Zul-kade","options":["U mjesecu Muharram","U mjesecu Zul-kade","U mjesecu Ramazanu","U mjesecu Ševalu"],"question":"U kojem mjesecu je Muhammed, alejhis-selam, odlučio obaviti oproštajni hadž?"},{"answer":"Između 124 i 144 hiljade","options":["Između 50 i 70 hiljada","Između 90 i 110 hiljada","Između 124 i 144 hiljade","Između 150 i 170 hiljada"],"question":"Koliko je približno muslimana bilo na oproštajnom hadžu?"},{"answer":"Sve vrste kamata","options":["Obaveznost molitve","Sve vrste kamata","Mjesečni post","Prikupljanje милостinje"],"question":"Šta je Muhammed, alejhis-selam, poništio na Oproštajnom hadžu?"},{"answer":"Na Arefatu","options":["Kod Kaabe","Na Arefatu","Na Muni","U Medini"],"question":"Na kojem mjestu je Muhammed, alejhis-selam, održao čuveni govor?"},{"answer":"Samo jedan hadž - oproštajni","options":["Pet hadža","Tri hadža","Dva hadža","Samo jedan hadž - oproštajni"],"question":"Koliko je hadža obavio Muhammed, alejhis-selam, prema lekciji?"}]},{"nivo":3,"slug":"preseljenje-ahiret","naslov":"Preseljenje na ahiret – smrt Božijeg Poslanika","content_html":"<div class=\"lesson-container\">\n        <h1>PRESELJENJE NA AHIRET - SMRT BOŽIJEG POSLANIKA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/preseljenje.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Preseljenje na ahiret – smrt Božijeg Poslanika</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje duboke ljubavi prema Poslaniku, a.s., i svijesti o smrti</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti okolnosti smrti Poslanika, a.s., i reakciju ashaba</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti vrijednost Poslanikovih posljednjih riječi</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako je preselio naš Poslanik, a.s.? Hajde da naučimo o ovom velikom događaju.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanik, a.s., razbolio se nakon povratka iz oproštajnog hadža.</p><p>Njegova posljednja bolest trajala je oko 2 sedmice; nije bio u stanju voditi namaz, pa je naredio Ebu Bekru da imam-namaz vodi.</p><p>Posljednje riječi: \"Allahumme, er-Refīkul-A‘lā\" (Allahu, Najuzvišeniji Druže) — preselio je u krilu Aiše, r.a.</p><p>Datum: ponedjeljak, 12. rebiul-evvela, 11. hidžretske godine (632. g.); imao je 63 godine.</p><p>Reakcija ashaba: tuga, zbunjenost, neki nisu htjeli prihvatiti vijest. Omer, r.a., izvukao sablju.</p><p>Ebu Bekr, r.a., je istupio: \"Ko je obožavao Muhammeda — Muhammed je preselio. Ko obožava Allaha — Allah je vječan i ne umire.\" Učio ajet: \"Muhammed je samo poslanik...\"</p><p>Ukop: u Aišinoj sobi (gdje je preselio); danas u Mesdžid en-Nebeviju u Medini.</p><p>Posljednja velika briga: ostavljanje Kur’ana i sunneta kao vodiča do Sudnjeg dana.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče salavat. Zaključak: Poslanik je preselio, ali je njegov sunnet među nama.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":87,"is_published":true,"kviz_pitanja":[{"answer":"Više od dva mjeseca","options":["Više od dva mjeseca","Točno jedan mjesec","Tri mjeseca","Šest mjeseci"],"question":"Koliko mjeseci je Poslanik, alejhis-selam, živio nakon povratka iz hadža?"},{"answer":"Ebu Bekru","options":["Ebu Bekru","Omeru","Alijiu","Osmanu"],"question":"Kojem sahabi je Poslanik naredio da predvodi namaz tijekom njegove bolesti?"},{"answer":"Trinaest ili četrnaest dana","options":["Trinaest ili četrnaest dana","Sedam dana","Dvadeset dana","Deset dana"],"question":"Koliko dana je trajala Poslanikova, alejhis-selam, posljednja bolest?"},{"answer":"Danas sam vam vjeru vašu usavršio","options":["Danas sam vam vjeru vašu usavršio","Kada Allahova pomoć dođe","Muhammed je samo poslanik","Nema sile osim Allahove"],"question":"Koji je ajet bio posljednji koji je Allah objavio Poslaniku?"},{"answer":"Njegova kćerka Fatima","options":["Njegova kćerka Fatima","Njegova žena Aiša","Njegova majka Aminah","Njegova sestra Safija"],"question":"Ko je doišla da posjeti Poslanika, alejhis-selam, u ponedjeljak ujutro?"}]},{"nivo":3,"slug":"kulidullahe","naslov":"Kulid'ullahe","content_html":"<div class=\"lesson-container\">\n        <h1>KULID'ULLAHE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ucenje_kuran.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Kulid’ullāhe – Reci: Allah je Onaj koji je proslavljen</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike spominjanja Allaha kroz tesbih</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst i značenje sure En-Naml ajet 59 ili sličnih kratkih ajeta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da koriste ovaj zikr u svakodnevnom životu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, naučit ćemo jedan kratki ajet/zikr koji se često uči — \"Kulid’ullāhe\". Šta to znači?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ovo je dio ajeta gdje Allah naređuje Poslaniku, a.s.: \"Reci: Hvala Allahu i mir Njegovim odabranim robovima.\"</p><p>Glavna poruka: stalno spominjanje Allaha (zikr) i salavata na poslanike i odabrane.</p><p>U svakodnevnom životu: spominjati Allaha pri svemu (Bismillah pri jelu, Elhamdulillah poslije, SubhanAllah pri čudu, Estagfirullah poslije grijeha).</p><p>Zikr donosi: smirenost srca, oprost grijeha, Allahovu blizinu, blagoslov.</p><p>Allah u Kur’anu: \"Doista se srca smiruju spominjanjem Allaha.\"</p><p>Postupak: učenici uče ajet, ponavljaju ga.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na 33 puta SubhanAllah, Elhamdulillah, Allāhu ekber poslije svakog namaza. Zaključak: zikr je hrana duše.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NAJLJEPŠA IMENA PRIPADAJU ALLAHU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite trenutak kada se osjećate preplavljeni veličinom svijeta oko sebe, a vaše srce traži riječi kojima bi se obratilo Stvoritelju svega toga. Kako Ga nazvati? Milostivi? Silni? Tvorac? Sura El-Isra nam donosi odgovor koji smiruje dušu: kako god Ga zvali, Njegova imena su najljepša. Ova dva kratka, ali moćna ajeta, poznata kao \"Kulid'ullahe\", uče nas kako da se obraćamo Allahu s poštovanjem i ljubavlju, podsjećajući nas na Njegovu savršenost – Onoga koji nema djeteta, nema sudruga i kome ne treba zaštitnik. Danas ćemo naučiti ove riječi koje se često uče nakon namaza, riječi koje potvrđuju Allahovu veličinu i našu zahvalnost Njemu.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <p class=\"lesson-text\">\n                    Posljednja dva ajeta sure El-Isra, koja je objavljena u Mekki, sadrži 111 ajeta.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Reci: \"Zovite: 'Allah', ili zovite: 'Milostivi', a kako god Ga budete zvali, Njegova su imena najljepša. Ne izgovaraj na sav glas Kur'an kad molitvu obavljaš, a i ne prigušuj ga, traži sredinu između toga\", i reci: \"Hvaljen Allah, koji Sebi nije uzeo djeteta i koji u vlasti nema ortaka, i kome ne treba zaštitnik zbog nemoći, i hvaleći Ga veličaj!\" (El-Isra, 110-111)\n                </p>\n\n                <p class=\"lesson-text\">\n                    U posljednja dva ajeta sure El-Isra Allah, dž.š., govori o svojim lijepim imenima i ističe da su Njegova imena najljepša. Lijepim imenima Allaha, dž.š., možemo dozivati, hvaliti i veličati. On, Allah, dž.š., nema djeteta, u vlasti nema ortaka i Njemu ne treba zaštitnik.\n                </p>\n\n                <div class=\"arabic-card\" style=\"text-align: center;\">\n                    <p class=\"arabic-text\" style=\"font-size: 24px; direction: rtl; line-height: 2;\">\n                        بسمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ<br>\n                        قُلِ ادْعُوا اللَّهَ أَوِ ادْعُوا الرَّحْمَنَ ۖ أَيًّا مَّا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَىٰ ۚ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا (110)<br>\n                        وَقُلِ الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُن لَّهُ وَلِيٌّ مِّنَ الذُّلِّ ۖ وَكَبِّرْهُ تَكْبِيرًا (111)\n                    </p>\n                </div>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\" style=\"font-weight: bold;\">TRANSKRIPCIJA:</p>\n                    <p class=\"lesson-text\">\n                        BISMILLAHIR-RAHMANIR-RAHIM\n                    </p>\n                    <p class=\"lesson-text\">\n                        KULI-D 'ULLAHE EVI-D'UR-RAHMANE, EJJEN MMĀ TED'Ū FE-LEHUL-ESMÄUL-HUSNA, VE LĀ TEDŽHER BI-SALĀTIKE VE LĀ TUHAFIT BIHĀ VE-BTEĠI BEJNE ZÄLIKE SEBILĀ.<br>\n                        VE KULIL-HAMDU LILLÄHIL-LEZI LEM JETTEHIZ VELEDEN VVE LEM JEKU(N) LLEHŪ ŠERĪKUN FIL-MULKI VE LEM JEKU(N) LLEHŪ VELIJJUN MMINE-ZULLI VE KEBIRHU TEKBĪRĀ.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - KULID'ULLAHE</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":88,"is_published":true,"kviz_pitanja":[{"answer":"Sure El-Isra","options":["Sure El-Fatiha","Sure El-Isra","Sure El-Ahkaf","Sure El-Zumar"],"question":"Koja sura sadrži posljednja dva ajeta poznata kao 'Kulid'ullahe'?"},{"answer":"111 ajeta","options":["99 ajeta","105 ajeta","111 ajeta","120 ajeta"],"question":"Koliko ajeta ima sura El-Isra?"},{"answer":"Da su Njegova imena najljepša","options":["Da su teška za učenje","Da su Njegova imena najljepša","Da ih ne smijemo izgovarati","Da postoje samo 5 imena"],"question":"Šta Allah, dž.š., ističe o Svojim imenima u ovim ajetima?"},{"answer":"Da nema djeteta i ortaka u vlasti","options":["Da ima djecu i ortake","Da nema djeteta i ortaka u vlasti","Da ima više bogova","Da mu treba zaštitnik"],"question":"Kako Allah, dž.š., u ajetimagovori o Svom jedinstvu?"},{"answer":"Traži sredinu između glasnosti i tišine","options":["Izgovori ga što glasnije","Izgovori ga prigušeno i tiho","Traži sredinu između glasnosti i tišine","Nikada ne izgovaraj Kur'an"],"question":"Šta Allah, dž.š., naređuje oko izgovaranja Kur'ana u molitvi?"}]},{"nivo":3,"slug":"muslimanska-imena","naslov":"Lijepa muslimanska imena","content_html":"<div class=\"lesson-container\">\n        <h1>LIJEPA MUSLIMANSKA IMENA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/lijepa_imena.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Lijepa muslimanska imena</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kultura i tradicija</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ponosa na muslimanski identitet kroz lijepa imena</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti važnost biranja lijepih imena u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da prepoznaje i poštuje muslimanska imena</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kakvo je vaše ime? Šta znači? Da li je važno koja imena dajemo djeci?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanik, a.s.: \"Vi ćete na Sudnjem danu biti prozvani vašim imenima i imenima vaših očeva — pa lijepa imena birajte.\"</p><p>Najljepša imena: <strong>Abdullah</strong> (Allahov rob) i <strong>Abderrahman</strong> (Sveopće Milostivog rob).</p><p>Imena poslanika: Muhammed, Ahmed, Ibrahim, Ismail, Yusuf, Adam, Davud, Sulejman, Musa, Isa, Yahya, Zekerija, Yunus.</p><p>Imena ashaba: Ebu Bekr, Omer, Osman, Ali, Hamza, Bilal, Halid, Selman, Mu‘az, Hasan, Husein.</p><p>Ženska: Hatidža, Aiša, Fatima, Zejneb, Hafsa, Merjem, Asija, Sara, Hava, Sumejja.</p><p>Bošnjačka tradicija: Sabahudin, Fadil, Mirsada, Aida, Selma, Adnan...</p><p>Imena koja je Poslanik mijenjao: imena koja su značila ružne stvari (npr. Asija — Grešna; promijenio je u Džemila — Lijepa).</p><p>Naša obaveza: dati djeci lijepa imena sa lijepim značenjem; ne stidjeti se svog imena.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o značenju svojih imena. Zaključak: lijepo ime — početak lijepog života.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                NAJLJEPŠI POKLON ZA POČETAK ŽIVOTA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite poklon koji traje vječno, koji nosite sa sobom gdje god krenete i po kojem će vas prozvati čak i na Sudnjem danu. To nije skupocjeni nakit niti odijelo, već vaše ime. Ono je prvi emanet koji roditelji preuzimaju, pečat vašeg identiteta i dova koju ljudi izgovaraju svaki put kad vas pozovu. Danas ćemo naučiti zašto je odabir lijepog muslimanskog imena jedna od najvažnijih dužnosti roditelja, šta je akika i kako nas islam uči da poštujemo jedni druge, izbjegavajući ružne nadimke koji bole dušu. Otkrit ćemo ljepotu imena koja su krasila najbolje generacije i naučiti kako da svoje ime nosimo s ponosom.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: “Vi ćete na Sudnjem danu biti prozivani po vašim imenima i po imenima vaših očeva. Zato nadijevajte svojoj djeci lijepa muslimanska imena.” (Buhari)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Među prvim pravima djece kod svojih roditelja, a ujedno i roditeljske dužnosti jeste da im se nadije lijepo muslimansko ime. Ko ima mogućnosti najbolje je da istovremeno s učenjem: ezana, ikameta, nadijevanja imena i učenjem dove za zdravlje i sreću novorođenčeta, zakolje kurbane – akike. O klanju kurbana po rođenju djeteta Poslanik, alejhis-selam, kaže: “Za svako novorođeno dijete, zalog je njegova akika koja se kolje sedmi dan po njegovom rođenju, kad mu se daje ime i šiša kosa.” (Ebu Davud)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Meso od kurbana akike treba u cijelosti podijeliti ili prirediti sohbet i pojesti ga. Ništa ne treba zadržavati od tog mesa za sebe. S obzirom na to da se novorođenčetu prilikom akike podrezuje kosa, za to se po islamskim propisima podijeli sadaka u novcu, srebru ili zlatu za zdravlje i sreću djeteta “jer je sadaka najbolji štit od svih nesreća”, kako je govorio Poslanik, alejhis-selam\n                </p>\n\n                <p class=\"lesson-text\">\n                    Lijepo je, a kod nas je to i običaj, da se pozove imam da nadije ime djetetu. Prilikom nadijevanja imena imam prouči ezan na desno, a ikamet na lijevo uho djetetu, okrenuvši se prema Kibli. Nakon ezana i ikameta imam će sjesti, proučiti odlomak iz Kur’ana, zatim učiniti dovu, a po završetku dove će, po roditeljima ranije, odabrano ime glasno izgovoriti, pomilovati dijete po glavi poželivši mu dug i hairli, u islamu, život i čestitati roditeljima sina ili kćerku na ponos ummeta islama. Buhari bilježi da bi ashabi svoju novorođenčad donosili u kuću Poslanika, alejhis-selam, da im on prouči ezan, ikamet, učini dovu i nadije ime njihovom djetetu.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Da ne bismo pri odabiru imena djetetu pogriješili, te mu nadjenuli ime koje nema lijepo značenje, ili čak nije muslimansko, treba uvijek imati na umu imena koja su vezana za našeg Poslanika, alejhis-selam, i njegovu porodicu i prijatelje, a ovdje ćemo i nabrojati neka.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Posljednji Allahov poslanik Muhammed, alejhis-selam, je imao sedmero djece, tri sina: Kasima, Abdullaha i Ibrahima i četiri kćeri: Zejneb, Rukaju, Ummu Kulsum i Fatimu. Njegovom ocu je bilo ime Abdullah, a majci Amina. Njegove najpoznatije supruge, po Kur’anu majke svih muslimana, su h. Hatidža, h. Aiša i h. Hafsa.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Neki od prvih i najpoznatijih ashaba: Ebu Bekr, Omer, Osman, Alija, Talha, Zubejr, Hamza, Bilal, Halid, Zejd, Hasan, Husejn itd.\n                </p>\n\t\t\t\t\n\t\t\t\t<div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, kaže: “Allahu su od vaših imena, najmilija: Abdullah i Abdurrahman.” (Muslim)\n                    </p>\n                </div>\n                \n                <p class=\"lesson-text\">\n                    Posebno treba obratiti pažnju da svojoj djeci ne bismo trebali nadijevati imena koja su skraćena verzija imena (npr. Abdullah – Avdo, Husejn – Huso, Ibrahim – Ibro, Mustafa – Mujo), niti smiju jedni drugima davati pogrdne nadimke.\n                </p>\n\t\t\t\t\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: O vjernici, neka se muškarci jedni drugima ne rugaju, možda su oni bolji od njih, a ni žene drugim ženama, možda su one bolje od njih. I ne kudite jedni druge i ne zovite jedni druge ružnim nadimcima! O, kako je ružno da se vjernici spominju podrugljivim nadimcima! A oni koji se ne pokaju – sami sebi čine nepravdu. (El-Hudžurat, 11)\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - LIJEPA IMENA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        • Uloga i važnost imena sa lijepim značenjem\n                    </p>\n                </div>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA I ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Koje su obaveze roditelja prema djetetu u prvim danima njegovog života?</li>\n                    <li>Šta je akika?</li>\n                    <li>Navedite nekoliko pohvalnih muških i ženskih imena?</li>\n                    <li>Kakva imena roditelji trebaju nadijevati djeci?</li>\n                    <li>Kako ćemo biti prozivani na Sudnjem danu?</li>\n                    <li><span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZADATAK:</span> Pronađi značenje svoga imena i imena članova svoje porodice!</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":89,"is_published":true,"kviz_pitanja":[{"answer":"Sedmi dan nakon rođenja","options":["Tri dana nakon rođenja","Sedmi dan nakon rođenja","Četrnaesti dan nakon rođenja","Trideset dana nakon rođenja"],"question":"Kada se prema hadisu klanja akika za novorođenče?"},{"answer":"Podijeliti ga ili prirediti sohbet","options":["Zadržati ga samo za sebe","Podijeliti ga ili prirediti sohbet","Poslati ga musavama","Zakopati ga"],"question":"Šta treba učiniti s mesom od kurbana akike?"},{"answer":"Trojicu","options":["Dvojicu","Trojicu","Četvoricu","Peroricu"],"question":"Koliko sinova je imao Poslanik, alejhis-selam?"},{"answer":"Amina","options":["Hatidža","Amina","Aiša","Ummu Kulsum"],"question":"Kako se zove majka Poslanika, alejhis-selam?"},{"answer":"Imama","options":["Doktora","Baku","Imama","Susjedina"],"question":"Koga treba pozvati da nadije ime novorođenčetu?"}]},{"nivo":3,"slug":"lijepa-rijec","naslov":"Lijepa riječ","content_html":"<div class=\"lesson-container\">\n        <h1>LIJEPA RIJEČ</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/lijepa_rijec.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Lijepa riječ</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike lijepog govora i izbjegavanja ružnih riječi</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti vrijednost lijepe riječi u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje vještine lijepog komuniciranja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kakvim se riječima služimo? Lijepim ili ružnim? Allah je u Kur’anu naročito naglasio važnost lijepe riječi.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah u Kur’anu: \"Lijepa riječ je kao lijepo drvo — korijen mu je čvrst, a granje na nebu — daje plodove svaki čas.\"</p><p>Poslanik, a.s.: \"Lijepa riječ je sadaka.\"</p><p>Vrste lijepih riječi: pozdrav (Esselamu alejkum), zahvala (Hvala, Allah te nagradio), čestitka, pohvala, zikr, dova za druge, salavat.</p><p>Suprotne — ružne riječi: psovka, kletva, vrijeđanje, ismijavanje, ogovaranje, laž.</p><p>Poslanik, a.s.: \"Ko vjeruje u Allaha i Sudnji dan — neka govori dobro ili neka šuti.\"</p><p>Naša jezik je veliki amanet — može uvesti i u Džennet i u Džehennem.</p><p>Razgovor: kako se kontrolirati kad smo ljuti? (zikr, abdest, šutnja, brojati do 10).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na 1 dan bez ružne riječi. Zaključak: lijepa riječ — most ka svakom srcu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                SJEME KOJE RASTE DO NEBA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Jeste li ikada razmišljali o tome da je svaka riječ koju izgovorite poput malenog sjemena? Kada posijemo sjeme dobrote, iz njega izraste predivno drvo čije grane dotiču nebo, pružajući hlad i utjehu drugima. Ali, jedna ružna riječ je poput korova koji guši sve lijepo oko sebe. Naše riječi imaju moć da grade mostove prijateljstva ili da ruše kule povjerenja. One su kao strijele – jednom odapete, ne mogu se vratiti. Danas ćemo naučiti kako da naši jezici budu ključevi Dženneta, kako da biramo riječi koje mirišu na ljubav i poštovanje, i zašto je ponekad tišina najglasniji i najmudriji govor.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Reci robovima Mojim da govore samo lijepe riječi. (El-Isra, 53)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Svaka izgovorena riječ nosi veliku odgovornost i na ovom i na budućem svijetu. Spominjanje Uzvišenog Allaha, učenje Kur'ana, davanje savjeta, pružanje utjehe, podučavanje znanju i obveseljavanje drugih samo su neki od načina za postizanje uspjeha, izgrađivanje pozitivnih odnosa među ljudima i stjecanje velike nagrade na budućem svijetu. S druge strane, prenošenje tuđih riječi, ogovaranje, potvaranje, lažno svjedočenje i slična djela stvaraju neprijateljstva i mržnju, te izgrađuju loše odnose među ljudima.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Uzvišeni Stvoritelj lijepu i ružnu riječ poredi s lijepim i ružnim drvetom: Zar ne vidiš kako Allah navodi primjer - lijepa riječ kao lijepo drvo: korijen mu je čvrsto u zemlji, a grane prema nebu. Ono plod svoj daje u svako doba koje Gospodar njegov odredi, a Allah ljudima navodi primjere da bi pouku primili. A ružna riječ je kao ružno drvo: iščupanom drvetu s površine zemlje nema opstanka. (Ibrahim, 24-26)\n                </p>\n\n                <p class=\"lesson-text\">\n                    Karakteristika plemenitih ljudi čija je životna vodilja islam jeste da se u njihovom društvu drugi lijepo i prijatno osjećaju ili da se u najmanju ruku ne boje zla njihovih riječi i djela. Ne vole kada se o drugom ružno priča niti to rade, ne naslađuju se kada se neko omalovažava i dobro razmišljaju prije nego što nešto kažu, jer se izgovorena riječ ne može vratiti, baš kao što se ne može vratiti odapeta strijela. Uzvišeni Allah nam poručuje da se klonimo beskorisnog govora, da govorimo samo lijepe riječi, a ogovaranje poredi s jedenjem mesa mrtvog brata.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Ružne riječi, pogotovo one kojima se drugi vrijeđaju i ponižavaju, ne smiju biti u rječniku vjernika. Naizgled bezazlene riječi mogu biti toliko prljave da bi svojom prljavštinom zamutile more. A koliko puta takve ili slične riječi pređu preko naših jezika, a da na to i ne obratimo pažnju.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Kur'an nas upućuje na konkretne primjere o kojima treba voditi računa kada je u pitanju lijep i koristan govor:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>Allah, dž.š., naređuje lijepu komunikaciju s roditeljima i zabranjuje podizanje tona na njih. Ovo pravilo se odnosi i na cijelu porodicu u kojoj trebaju vladati mir i harmonija.</li>\n                    <li>Zabranjuje se podizanje glasa na prosjaka.</li>\n                    <li>Kada se neznalice obrate vjernicima ružnim govorom, Kur'an naređuje da se uzvrati lijepim i blagim riječima.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Zbog toga nam je Poslanik, alejhis-selam, postavio univerzalno pravilo lijepog i korisnog govora.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: \"Ko vjeruje u Allaha i u Sudnji dan, neka govori dobro ili neka šuti.\" (Tirmizi)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Shodno ovom hadisu, svaka naša riječ treba da bude promišljena i korisna, a ako neće od nje biti koristi, bolje je prešutjeti.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - LIJEPA RIJEČ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Od kojeg govora čovjek ima koristi, a od kojeg štetu?</li>\n                    <li>S čim Allah, dž.š., poredi lijep govor?</li>\n                    <li>Koji su kur'anski primjeri upućenosti na lijep govor?</li>\n                    <li>Koji je Poslanikov univerzalni princip lijepog govora?</li>\n                </ol>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">RAZGOVOR S MUALLIMOM:</span><br>\n                        Čovjek je vladar riječi dok je ne izgovori, a kad je izgovori, ona postaje njegov vladar.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":90,"is_published":true,"kviz_pitanja":[{"answer":"Da govorimo samo lijepe riječi","options":["Da govorimo samo lijepe riječi","Da učimo samo Kur'an","Da se ne družimo s drugima","Da molimo samo u džamiji"],"question":"Šta Allah naređuje u ajetu iz Sure El-Isra?"},{"answer":"S lijepim drvetom","options":["S rijekom","S lijepim drvetom","S cvjetom","S pticом"],"question":"S čim Kur'an poredi lijepu riječ?"},{"answer":"Iščupano drvo nema opstanka","options":["Vraća se govoritelju","Nije važna","Iščupano drvo nema opstanka","Donosi dobro drugima"],"question":"Što se prema Kur'anu dešava s ružnom riječju?"},{"answer":"S jedenjem mesa mrtvog brata","options":["S krađom","S jedenjem mesa mrtvog brata","S lažima","S brzim govorom"],"question":"S čime Allah poredi ogovaranje drugoga?"},{"answer":"Ljubazno bez podizanja glasa","options":["Sa podizanjem tona","Ljubazno bez podizanja glasa","Kratkim riječima","Samo kada trebamo"],"question":"Kako trebamo komunicirati s roditeljima prema Kur'anu?"}]},{"nivo":3,"slug":"iz-historija","naslov":"Islamska zajednica – historijski nastanak i razvoj","content_html":"<div class=\"lesson-container\">\n        <h1>ISLAMSKA ZAJEDNICA U BOSNI I HERCEGOVINI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/iz_bih.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Islamska zajednica – historijski nastanak i razvoj</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ponosa na bošnjačku islamsku tradiciju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti historiju Islamske zajednice u Bosni i Hercegovini</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pripadnosti vlastitoj zajednici</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako je nastala Islamska zajednica u BiH? Ko je njen vrhovni vjerski poglavar? Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Islam je u BiH došao za vrijeme Osmanskog carstva (od 15. v.) — dolaskom Osmanlija u Bosnu.</p><p>Islamska zajednica BiH je organizirana kao zasebna zajednica 1882. godine — odlukom austrougarskih vlasti.</p><p>Poglavar Islamske zajednice je <strong>reisul-ulema</strong> (vjerski poglavar).</p><p>Prvi reis: Mustafa Hilmi Hadžiomerović. Tokom historije bilo ih je više: Čaušević, Spahić, Cerić, Kavazović (sadašnji).</p><p>Struktura: muftijstva, medžlisi, džemati. Svaki bošnjački grad ima svoj medžlis i muftijstvo.</p><p>Institucije: Fakultet islamskih nauka (Sarajevo), Gazi Husrev-begova medresa, mektebi, džamije, vakufi.</p><p>Funkcija: organizacija vjerskih obreda, vjeronauke, hadža, izdavanje fetvi, briga o vakufima.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju funkcije IZ. Zaključak: naša zajednica je naša snaga.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                ČUVARI EMANETA KROZ STOLJEĆA <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite jedno veliko, stoljetno stablo koje je pustilo duboko korijenje u našu bosansku zemlju. Kroz historiju su puhali strašni vjetrovi, mijenjala su se carstva i kraljevstva, dolazile su oluje koje su lomile grane, ali to stablo je uvijek ostajalo uspravno i ponosno. To stablo je naša Islamska zajednica. Od vremena kada su se prvi ezani začuli našim dolinama, pa kroz teška vremena kada su nam oduzimali prava i imovinu, pa sve do današnjih dana, naši preci su se borili da sačuvaju svoju vjeru i institucije. Danas ćemo krenuti na putovanje kroz vrijeme da vidimo kako je nastala, kako se razvijala i kako je danas uređena ta naša zajednička kuća koja brine o svakom muslimanu, od vašeg džemata pa sve do vrha Rijaseta.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">HISTORIJSKI NASTANAK I RAZVOJ</p>\n                <p class=\"lesson-text\">\n                    Islamska zajednica u Bosni i Hercegovini je jedna i jedinstvena zajednica muslimana u Bosni i Hercegovini i Sandžaku, Hrvatskoj, Sloveniji i Srbiji, muslimana Bošnjaka izvan domovinskih zemalja i drugih muslimana koji je prihvataju kao svoju.\n                </p>\n                <p class=\"lesson-text\">\n                    Prava i obaveze pripadnici i članovi Islamske zajednice ostvaruju u džematu, te organima i ustanovama Islamske zajednice u Bosni i Hercegovini.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">FORMIRANJE ISLAMSKE ZAJEDNICE U BOSNI I HERCEGOVINI</p>\n                <p class=\"lesson-text\">\n                    Dolaskom Turaka Osmanlija u Bosnu i Hercegovinu, 1463. godine, stanovništvo ovih prostora se upoznalo s islamom, a nakon toga pojedinačno i grupno su prelazili na islam. Već tada se javlja potreba za institucionalnim uređenjem vjerskog života muslimana. Vjerske poslove u ime halife obavljali su muftije, šerijatske sudije, muderisi i imami.\n                </p>\n                <p class=\"lesson-text\">\n                    Dolaskom Austro-Ugarske u Bosnu i Hercegovinu, 1878. godine, vijekovima ustaljeni oblici organiziranja vjerskih poslova se raspadaju, a islam više nije državna religija koju država pomaže kao što je to bio slučaj u vrijeme osmanske uprave. Austro-Ugarska sistemski nastoji potpuno odvojiti muslimane u Bosni i Hercegovini od Istanbula kao njihove duhovne matice.\n                </p>\n                <p class=\"lesson-text\">\n                    Tako se Carskom naredbom iz oktobra 1882. u Sarajevu osniva vrhovna vjerska vlast muslimana pod imenom Ulema-medžlis na čelu s reisul-ulemom.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">POKRET ZA VAKUFSKO-MEARIFSKU SAMOSTALNOST</p>\n                <p class=\"lesson-text\">\n                    Zemaljska vlada sa sjedištem u Beču je imenovala Zemaljsko vakufsko povjerenstvo koje je upravljalo vakufskim poslovima. Borba za vjersku i vakufsku autonomiju dovela je do usvajanja prvog ustava Islamske zajednice pod nazivom Štatut za autonomnu upravu islamskih vjerskih i vakufsko-mearifskih poslova u Bosni i Hercegovini 1909. godine.\n                </p>\n                <p class=\"lesson-text\">\n                    Usvajanje ovakvog ustava muslimani u Bosni i Hercegovini su dobili pravni okvir koji im je garantirao njihova vjerska prava i štitio vakufsku imovinu.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ISLAMSKA ZAJEDNICA U VRIJEME KRALJEVINE SHS (SRBA, HRVATA I SLOVENACA)</p>\n                <p class=\"lesson-text\">\n                    Uspostavom Kraljevine SHS, 1918. godine, nastupila je veoma složena situacija za muslimane kad je riječ o vjerskom životu, a posebno vakufskoj imovini. Kraljevina SHS preuzela je prema muslimanima tri obaveze:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>porodični i lični status regulira se po muslimanskim običajima,</li>\n                    <li>bit će zaštićeni objekti koji pripadaju Islamskoj zajednici, poput džamija, mezarluka, vakufa itd.,</li>\n                    <li>vlada se obavezala da će preuzeti korake da se imenuje reisul-ulema za cijelu zemlju.</li>\n                </ul>\n                <p class=\"lesson-text\">\n                    Nijednu od navedenih obaveza Vlada Kraljevine SHS nije ispoštovala do kraja.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ISLAMSKA ZAJEDNICA U KRALJEVINI JUGOSLAVIJI</p>\n                <p class=\"lesson-text\">\n                    Ukidanjem Štatuta za autonomiju i usvajanjem novog ustava Islamske zajednice, 1930. godine, Kraljevina Jugoslavija je nastojala staviti pod jedinstvenu organizaciju Islamsku zajednicu u cijeloj državi i sve njene poslove staviti pod svoju kontrolu. Tokom provođenja Agrarne reforme oduzet je značajan dio vakufskog zemljišta.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ISLAMSKA ZAJEDNICA U VRIJEME SFRJ</p>\n                <p class=\"lesson-text\">\n                    Najteže vrijeme za Islamsku zajednicu nastupilo je poslije Drugog svjetskog rata jer je nova vlast ukinula muftijstva, oduzela veliki dio vakufske imovine i zabranila rad u svim odgojno-obrazovnim ustanovama Islamske zajednice osim Gazi Husrev-begove medrese.\n                </p>\n                <p class=\"lesson-text\">\n                    I pored represivnih mjera, vjerski život muslimana se nastavio. Gradile su se džamije, osnovan je Fakultet islamskih nauka u Sarajevu, te pokrenuta izdavačka djelatnost islamskih edicija. Školovali su se alimi vjerski službenici na Fakultetu u Sarajevu i na univerzitetima u islamskom svijetu.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ISLAMSKA ZAJEDNICA U TOKU AGRESIJE NA BOSNU I HERCEGOVINU</p>\n                <p class=\"lesson-text\">\n                    Poslije raspada SFRJ i međunarodnog priznanja Republike Bosne i Hercegovine, 1992. godine, Islamska zajednica je ponovo stekla punu samostalnost i slobodu djelovanja.\n                </p>\n                <p class=\"lesson-text\">\n                    Međutim, iste godine je izvršena agresija na Bosnu i Hercegovinu u toku koje je Islamska zajednica preživjela teške napade na njene pripadnike, vjerske službenike i vakufsku imovinu (srušeno je 614 džamija, 218 mesdžida, 69 mekteba, 405 drugih vakufskih objekata) i ubijeno 97 imama.\n                </p>\n                <p class=\"lesson-text\">\n                    U takvim okolnostima, 28. aprila 1993, održana je sjednica Obnoviteljskog sabora IZ u Sarajevu na kojoj je donesena Ustavna odluka kao privremeni ustavnopravni dokument kojim se uređuje ustrojstvo Islamske zajednice.\n                </p>\n                <p class=\"lesson-text\">\n                    U skladu s Ustavnom odlukom, na ovom zasjedanju su izabrani: naibu-reis dr. Mustafa-ef. Cerić i zamjenik naibu-reis hfz. Ismet-ef. Spahić. Ovom odlukom stavljen je van snage jugoslovenski zakon o Islamskoj zajednici iz 1930. godine.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">USTROJSTVO ISLAMSKE ZAJEDNICE U BOSNI I HERCEGOVINI</p>\n                <p class=\"lesson-text\">\n                    Islamska zajednica u Bosni i Hercegovini na temelju Ustava Islamske zajednice organizirana je kroz vjersku i administrativnu upravu.\n                </p>\n                \n                <p class=\"lesson-text\">\n                    Vjersku upravu/nosioce vjerskog autoriteta čine:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li><strong>Reisu-l-ulema</strong>, poglavar i vrhovni muftija Islamske zajednice koji predsjedava Rijasetom i Vijećem muftija,</li>\n                    <li><strong>Vijeće muftija</strong>, organ Islamske zajednice za pitanja vjere, a čine ga sve muftije u Islamskoj zajednici,</li>\n                    <li><strong>muftija</strong>, glavni vjerski autoritet na području muftiluka, odnosno mešihata koji predsjedava muftijstvom, odnosno mešihatom.</li>\n                    <li><strong>glavni imam</strong>, nadležan i odgovoran za organizaciju i izvršavanje vjerskih poslova i aktivnosti na području medžlisa,</li>\n                    <li><strong>imam</strong>, brine o vjerskom životu u džematu, vodi matične knjige džemata i predstavlja džemat u pitanjima vjere.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Administrativnu upravu/strukturu Islamske zajednice čine:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li><strong>Sabor</strong> - najviše predstavničko i zakonodavno tijelo Islamske zajednice,</li>\n                    <li><strong>Rijaset</strong>, najviši izvršni organ za vjerske, obrazovne, ekonomske, finansijske, pravne i druge poslove Islamske zajednice u Bosni i Hercegovini,</li>\n                    <li><strong>mešihat</strong>, vjerski i administrativno-upravni organ kojim predsjedava predsjednik mešihata,</li>\n                    <li><strong>muftijstvo</strong>, upravni organ na području muftiluka, a čine ga muftija i rukovodioci službi,</li>\n                    <li><strong>medžlis</strong>, organizaciona jedinica Islamske zajednice koja u pravilu obuhvata sve džemate na teritoriji jedne općine ili najmanje sedam džemata koji čine povezanu cjelinu,</li>\n                    <li><strong>džemat</strong>, osnovna organizaciona jedinica Islamske zajednice koju u pravilu sačinjava skupina od najmanje 200 muslimanskih domaćinstava.</li>\n                </ul>\n\n                <p class=\"lesson-text\">\n                    Ustavni sud je vrhovni organ Islamske zajednice za ocjenu ustavnosti akata i rada ustanova i organa Islamske zajednice\n                </p>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Menšura je ovlaštenje reisu-l-ulemi za vršenje vjerskih poslova i pravo da daje ovlaštenja drugim licima. Do 1930. menšure su izdavane u Carigradu, a od 1930. na temelju Ustava Islamske zajednice izdavane su u Bosni i Hercegovini.\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    <strong>Reisu-l-uleme u Bosni i Hercegovini i bivšoj Jugoslaviji:</strong><br>\n                    Mustafa Hilmi-ef. (Hadži) Omerović, Mehmed Teufik-ef. Azabagić, hafız Sulejman-ef. Šarac, Mehmed Džemaludin-ef. Čaušević, hafız Ibrahim-ef. Maglajlić, Fehim-ef. Spaho, Ibrahim-ef. Fejić, Sulejman-ef. Kemura, Naim-ef. Hadžiabdić, hafiz Husein-ef. Mujić, Jakub-ef. Selimoski, početkom 1990. postao vršilac dužnosti reisa, a od 1991. do 1993. reisul-ulema, Mustafa-ef. Cerić od 1993. do 1998. naibu-reis, i od 1998. do 15. novembra 2012. reisul-ulema Islamske zajednice u Bosni i Hercegovini, Husein-ef. Kavazović od 15. novembra 2012. reisu-l-ulema Islamske zajednice u Bosni i Hercegovini.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ISLAMSKA ZAJEDNICA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA I ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je Islamska zajednica?</li>\n                    <li>Šta se dogodilo 1882. godine?</li>\n                    <li>Islamska zajednica za vrijeme rata u Bosni i Hercegovini!</li>\n                    <li>Opiši ustrojstvo Islamske zajenice u Bosni i Hercegovini!</li>\n                    <li>Kako se zove tvoj muftija, a kako glavni imam?</li>\n                    <li>ZADATAK: Koji su organi rada u džematu? Nabroj ih i raspitajte se o članovima tih organa!</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":91,"is_published":true,"kviz_pitanja":[{"answer":"1463. godine","options":["1463. godine","1878. godine","1882. godine","1909. godine"],"question":"Koje godine su Turci Osmanlije došli u Bosnu i Hercegovinu?"},{"answer":"Ulema-medžlis","options":["Ulema-medžlis","Vakufsko povjerenstvo","Šaria-vijeće","Islamski sabor"],"question":"Kako se zvala vrhovna vjerska vlast muslimana osnovana 1882. godine?"},{"answer":"Vijekovima ustaljeni oblici organiziranja se raspadaju","options":["Islam je postao državna religija","Vijekovima ustaljeni oblici organiziranja se raspadaju","Osnovan je prvi ustav islamske zajednice","Muslimani su dobili veća prava"],"question":"Što se dogodilo dolaskom Austro-Ugarske 1878. godine?"},{"answer":"Štatut za autonomnu upravu islamskih poslova","options":["Štatut za autonomnu upravu islamskih poslova","Carska naredba iz Istanbula","Austro-ugarski zakon o religiji","Osmanski zakon o vjerskom životu"],"question":"Koji je dokument usvajan 1909. godine za islamsku zajednicu?"},{"answer":"Muftije, sudije, muderisi i imami","options":["Muftije, sudije, muderisi i imami","Samo imami i mulahi","Samo muftije i reisuli","Samo šerijatske sudije"],"question":"Koji su vjerski službenici obavljali vjerske poslove pod osmanskom upravom?"}]},{"nivo":3,"slug":"dan-dzamija","naslov":"Dan džamija i džemata","content_html":"<div class=\"lesson-container\">\n        <h1>DAN DŽAMIJA I DŽEMATA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dan_dzamija.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dan džamija i džemata</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kultura i tradicija</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema džamiji kao centru zajednice</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti značaj džamije u životu muslimana</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike redovnog odlaska u džamiju</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je džamija? Samo zgrada za namaz? Mnogo više od toga! Hajde da razgovaramo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Džamija (mesdžid) — Allahova kuća; mjesto okupljanja muslimana za ibadet, učenje i druženje.</p><p>Funkcije: dnevni namazi, džuma-namaz, teravije, dženaze, mektebska nastava, predavanja, savjetovanja, dženazski poslovi.</p><p>U historiji: džamije su bile i škole, biblioteke, sudnice, savjetnička mjesta — centar zajednice.</p><p>Najvažnije džamije: <strong>El-Haram</strong> u Mekki, <strong>El-Aksa</strong> u Jerusalemu, <strong>En-Nebevi</strong> u Medini.</p><p>U BiH: Begova džamija (Sarajevo), Aladža (Foča, srušena 1992., obnovljena), Ferhadija (Banja Luka, srušena 1993., obnovljena), mnoge druge.</p><p>Naša obaveza: posjećivati, čuvati čistoću, donirati vakufe, ne pričati glasno, ne unositi nečisto.</p><p>Hadis: \"Najdraža Allahu su tri mjesta — džamije; najmrža Mu su tri mjesta — pijace.\"</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o svojoj lokalnoj džamiji. Zaključak: bez džamije, zajednica nema srca.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                SJECANJE NA RANJENU LJEPOTICU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Postoje datumi koji nisu samo brojke u kalendaru, već rane na duši jednog naroda. Jedan takav datum je 7. maj. Zamislite prelijepu džamiju, biser arhitekture, koja je stoljećima krasila Banja Luku, a onda u jednoj mračnoj noći nestala u prahu i dimu. Ali, priča o Ferhadiji nije priča o kraju, već o neuništivosti. Iako su je srušili i njene ostatke bacili na deponiju, ona se ponovo digla, kamen po kamen, ljepša i ponosnija nego ikad. Danas ćemo naučiti zašto je džamija srce svakog džemata, šta znači riječ \"džemat\" i zašto nikada ne smijemo zaboraviti dan kada su pokušali ubiti naše bogomolje, ali su samo ojačali našu ljubav prema njima.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Allahove džamije održavaju oni koji u Allaha i u onaj svijet vjeruju i koji namaz obavljaju i zekat daju i koji se nikoga osim Allaha ne boje; oni su, nadati se, na pravom putu. (Et-Tevbe, 18)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Riječ džamija je arapskog porijekla i nastala je od korijena džeme'a, što znači: sastaviti, spojiti, skupiti, (po)staviti zajedno itd.\n                </p>\n                <p class=\"lesson-text\">\n                    Od iste riječi je nastala i riječ džemat u značenju: skup, zajednica, grupa, okupljenost.\n                </p>\n                <p class=\"lesson-text\">\n                    Džamije su mjesta gdje se muslimani okupljaju radi obavljanja zajedničkog namaza, edukacije i drugih vjerskih programa i manifestacija.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: \"Ko se kod svoje kuće očisti, a zatim ode u jednu od džamija da obavi jedan od Allahovih farzova, jednim korakom mu se oprašta grijeh, a drugim podiže stepen (u Džennetu).\" (Muslim)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Prva džamija na Zemlji je Kaba u Mekki. Prva džamija koju je utemeljio Poslanik, alejhis-selam, je džamija u Kuba'u, mjestu tri kilometra daleko od Medine, u septembru 622. godine.\n                </p>\n                \n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">RUŠENJE FERHADIJE DŽAMIJE</p>\n                <p class=\"lesson-text\">\n                    U noći 7. maja 1993. godine, nakon 414 godina postojanja, minirana je jedna od najznačajnijih džamija u Bosni i Hercegovini, po svojoj ljepoti čuvena banjalučka Ferhadija, vakuf Ferhat-paše Sokolovića.\n                </p>\n                <p class=\"lesson-text\">\n                    Ubrzo zatim, minirani kameni ostaci odvezeni su na deponiju smeća, čime je nedvojbeno potvrđena planska i sistematska aktivnost realizacije zločina urbicida.\n                </p>\n                <p class=\"lesson-text\">\n                    Ferhat-pašina džamija je izgrađena 1579. godine i predstavljala je jedno od najuspješnijih arhitektonskih ostvarenja bosanske arhitekture u vrijeme Osmanlija u 16. stoljeću.\n                </p>\n                <p class=\"lesson-text\">\n                    Ferhadija je 1950. godine uvrštena u kulturnu baštinu Bosne i Hercegovine, a potom i na listu spomenika svjetske baštine pri UNESCO-u.\n                </p>\n                <p class=\"lesson-text\">\n                    Ali, Ferhadija je bila samo jedna od 16 banjalučkih džamija koje su tokom agresije na Bosnu i Hercegovinu od 1992. do 1995. godine do temelja porušene.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">DAN DŽAMIJA</p>\n                <p class=\"lesson-text\">\n                    Odlukom Rijaseta Islamske zajednice u Bosni i Hercegovini, 7. maj se obilježava kao Dan džamija, koji simbolički podsjeća na stradanje, potpuno rušenje ili oštećenje više od 1.000 džamija, 218 mesdžida, 69 mekteba, četiri tekije, 37 turbeta i 405 drugih vakufskih objekata tokom posljednje agresije na Bosnu i Hercegovinu.\n                </p>\n                <p class=\"lesson-text\">\n                    Na ovaj dan se prisjećamo Ferhadije džamije, ali i svih drugih porušenih džamija koje su u proteklom periodu obnovljene i izgrađene.\n                </p>\n                <p class=\"lesson-text\">\n                    Podsjećamo se također da muslimani koji posjećuju džamije održavaju ih i čine ih živima.\n                </p>\n                <p class=\"lesson-text\">\n                    Svrha džamija i jeste okupljanje i džemat, pa je dužnost svih muslimana i muslimanki da budu od onih koji posjećuju džamije i brinu o svojim džematima.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">HADIS</span><br>\n                        Poslanik, alejhis-selam, je rekao: \"Kad god neko ode u džamiju - jutrom ili navečer Allah mu pripremi mjesto u Džennetu, koliko god puta ode ujutro i navečer.\" (Buhari)\n                    </p>\n                </div>\n\n                <div class=\"info-box\">\n                    <p class=\"lesson-text\">\n                        <span style=\"background-color: #fff9c4; text-transform: uppercase;\">ZAPAMTI!</span><br>\n                        Datum 7. maj 1993. godine podsjeća na dan kada su agresori srušili Ferhadiju džamiju u Banjoj Luci. Na ovaj datum 2016. godine svečano je otvorena obnovljena Ferhadija džamija. Također, 7. maja 2001. godine, Cazinjanin Murat Badić u Banjoj Luci je zadobio smrtne rane od srpskih ekstremista koji su izazvali velike nerede i onemogućili polaganje kamena temeljca za obnovu Ferhadije džamije.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - DAN DŽAMIJA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta znači riječ džamija?</li>\n                    <li>Koja je prva džamija na Zemlji?</li>\n                    <li>Šta se desilo 7. maja u Banjoj Luci?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Zašto je Poslanikov, alejhis-selam, prvi postupak po dolasku u Medinu bio izgradnja džamija? Šta je džamija predstavljala u životu muslimana?</li>\n                    <li>Istraži koliko su muslimani danas praktični vjernici i koliko ih redovno posjećuje džamije! Polje istraživanja neka ti bude područje Bosne i Hercegovine.</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":92,"is_published":true,"kviz_pitanja":[{"answer":"Mjesto gdje se muslimani okupljaju za namaz","options":["Mjesto gdje se muslimani okupljaju za namaz","Sveta knjiga muslimana","Mjesto gdje se čuva novac","Kuća učitelja vjere"],"question":"Šta znači riječ džamija?"},{"answer":"Džamija u Kuba'u","options":["Džamija u Kuba'u","Džamija u Mekki","Ferhadija džamija","Džamija u Jerusalemu"],"question":"Koja je bila prva džamija koju je utemeljio Poslanik?"},{"answer":"1579. godine","options":["1579. godine","1593. godine","1622. godine","1950. godine"],"question":"Koje godine je izgrađena Ferhadija džamija?"},{"answer":"7. maja 1993. godine","options":["7. maja 1993. godine","16. maja 1992. godine","7. aprila 1994. godine","14. decembra 1995. godine"],"question":"Kada je minirana Ferhadija džamija?"},{"answer":"414 godina","options":["414 godina","300 godina","500 godina","250 godina"],"question":"Koliko godina je Ferhadija džamija postojala prije nego što je minirana?"}]},{"nivo":3,"slug":"prava-dzematlija","naslov":"Prava i dužnosti džematlija","content_html":"<div class=\"lesson-container\">\n        <h1>PRAVA I DUŽNOSTI DŽEMATLIJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/rijaset.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Prava i dužnosti džematlija</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kultura i tradicija</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje osjećaja pripadnosti džematu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti prava i dužnosti svakog člana džemata</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje aktivnog učešća u životu džemata</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta znači biti dio džemata? Imamo li samo prava ili i obaveze?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Džematlija — član lokalne muslimanske zajednice (džemata).</p><p>Prava džematlije: korištenje džamije i mekteba, vjerske usluge (vjenčanje, sahrana, akika), pomoć u nevolji, prisustvo na okupljanjima, savjet od imama.</p><p>Dužnosti džematlije: <strong>1.</strong> redovan odlazak u džamiju (džuma), <strong>2.</strong> davanje članarine, <strong>3.</strong> učešće u vakufima i sadakama, <strong>4.</strong> pomaganje pri akcijama (čišćenje džamije, organizacija ifrara), <strong>5.</strong> slanje djece u mekteb, <strong>6.</strong> poštovanje imama i komšija.</p><p>Aktivni džematlija — dušu i tijelo daje za svoju zajednicu; pasivni samo \"trose\" zajednicu.</p><p>Naša djeca treba da rastu uz džemat — zajedno s drugom djecom u mektebu, ramazanskim aktivnostima.</p><p>Razgovor: koliko sam ja aktivan u svom džematu?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta mogu doprinijeti džematu. Zaključak: jak džemat — jaki muslimani.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                CIGLA U ČVRSTOJ ZGRADI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite jednu veliku, snažnu zgradu koja prkosi svim olujama. Ta zgrada nije napravljena od jednog ogromnog kamena, već od hiljada malih cigli koje se čvrsto drže jedna za drugu. Ako samo jedna cigla popusti ili ispadne, cijeli zid postaje slabiji. Na isti način, naš džemat je poput te zgrade, a svako od nas je jedna važna cigla. Islam nas uči da nismo sami i da je naša snaga u zajedništvu. Biti dio džemata ne znači samo klanjati zajedno; to znači biti dio tijela koje osjeća bol svakog svog dijela. Danas ćemo naučiti koja su to naša prava u džematu, ali i koje važne dužnosti imamo kako bi naša zajednička kuća ostala čvrsta i sretna.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I doista, ovo je pravi put Moj, pa se njega držite i druge puteve ne slijedite, pa da vas odvoje od puta Njegova; - eto, to vam On naređuje, da biste se grijeha klonili. (El-En'am, 153)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Kako god je islam vjera koju pojedinac nosi u srcu, tako je i vjera koja podstiče na zajednicu, vodeći je vječnoj sreći. Po kur'anskom ajetu: Vjernici su samo braća (El-Hudžurat, 10), islamska zajednica je vjerskim bratstvom čvrsto vezana zajednica, u kojoj svaki pojedinac sliči jednoj cigli u čvrsto zidanoj zgradi.\n                </p>\n                <p class=\"lesson-text\">\n                    Islamska zajednica treba da bude kao jedno tijelo, da jednom dušom svi dišu, jer Poslanik, alejhis-selam, kaže: \"Muslimani u međusobnoj ljubavi i milosti izgledaju kao jedno tijelo; kada mu oboli jedan dio, i ostali dijelovi trpe od nespavanja i temperature.\" (Buhari)\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ISLAMSKE INSTITUCIJE</p>\n                <p class=\"lesson-text\">\n                    Da bi se muslimani u ovakvoj zajednici mogli održati, islam je postavio pravila i institucije koje će podržavati zajednicu muslimana. Među islamske institucije kojima je cilj održavanje zajednice spadaju: džemat, džuma, bajrami, hadž, Kur'an, mekteb, kao i svoj društveni život.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">DŽEMAT</p>\n                <p class=\"lesson-text\">\n                    Džemat za muslimane predstavlja temeljnu, osnovnu i najmanju organizacionu jedinicu. Kroz džemat muslimani ostvaruju osnovna vjerska prava, obaveze i provode različite aktivnosti. Džemat u pravilu sačinjava skupina od najmanje 200 muslimanskih domaćinstava koja žive na jednom području i koja su međusobno povezana u izvršavanju zajedničkih islamskih dužnosti.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PRAVA I DUŽNOSTI DŽEMATLIJA</p>\n                <p class=\"lesson-text\">\n                    Treba biti svjestan da kao džematlija, osim svojih prava, imamo i dužnosti koje trebamo ispunjavati. Jednom rečenicom možemo opisati prava džematlija, a to je da svaki džematlija u džematu ima pravo na organiziran vjerski život i aktivnosti u džematu, te da aktivno učestvuje u istim.\n                </p>\n                <p class=\"lesson-text\">\n                    Neke od dužnosti jednog džematlije su:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>da vodi brigu o stanju džamije i pomogne održavanju koliko je u mogućnosti,</li>\n                    <li>da finansijski i na druge načine potpomaže Zajednicu,</li>\n                    <li>da redovno plaća članarinu,</li>\n                    <li>da učestvuje u vjerskim programima,</li>\n                    <li>da čuva dostojanstvo i ugled Islamske zajednice i muslimana,</li>\n                    <li>da poštuje autoritete u Islamskoj zajednici,</li>\n                    <li>da čuva jedinstvo Islamske zajednice i isto ne narušava.</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - PRAVA I DUŽNOSTI</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA</p>\n                <ol class=\"lesson-text\">\n                    <li>Kako Poslanik, alejhis-selam, opisuje džemat muslimana?</li>\n                    <li>Kojim se institucijama održava zajednica?</li>\n                    <li>Koja su prava i dužnosti članova zajednice?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ul class=\"lesson-text\">\n                    <li>Džematlija u džematu osim prava ima i dužnosti. Razmisli o svakoj od nabrojanih dužnosti i pokušaj svaku obrazložiti!</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":93,"is_published":true,"kviz_pitanja":[{"answer":"Vjernici su samo braća","options":["Vjernici su samo prijatelji","Vjernici su samo braća","Vjernici su samo susjedi","Vjernici su samo kolege"],"question":"Šta Islam naučava o odnosu između vjernika prema Kur'anskom ajetu?"},{"answer":"200 domaćinstava","options":["100 domaćinstava","150 domaćinstava","200 domaćinstava","250 domaćinstava"],"question":"Koliko domaćinstava najmanje čini jedan džemat?"},{"answer":"Džemat","options":["Bajram","Džemat","Hadž","Mekteb"],"question":"Koja je temeljnoj organizacijska jedinica za muslimane?"},{"answer":"Organiziran vjerski život i aktivnosti","options":["Samo moliti kod kuće","Organiziran vjerski život i aktivnosti","Samo plaćati članarinu","Samo čitati Kur'an"],"question":"Šta ima pravo da radi svaki džematlija u džematu?"},{"answer":"Sa jednim tijelom","options":["Sa gradom","Sa voćem","Sa jednim tijelom","Sa branom"],"question":"Šta Poslanik poredbi sa Muslimane koji se međusobno vole?"}]},{"nivo":3,"slug":"temelji-odgoja","naslov":"Mekteb, džamija i škola – temelji odgoja i obrazovanja","content_html":"<div class=\"lesson-container\">\n        <h1>MEKTEB, DŽAMIJA I ŠKOLA – TEMELJI ODGOJA I OBRAZOVANJA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mekteb_dzamija.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Mekteb, džamija i škola – temelji odgoja i obrazovanja</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kultura i tradicija</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje poštovanja prema svim mjestima odgoja i obrazovanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti ulogu i međusobnu vezu mekteba, džamije i škole</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike aktivnog korištenja svih ovih ustanova</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, gdje učite? U školi, mektebu, kod kuće, u džamiji. Sva ova mjesta zajedno čine vaš odgoj.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Porodica</strong> — prva i najvažnija škola; roditelji su prvi učitelji.</p><p><strong>Mekteb</strong> — vjerska škola; uči vjeru, Kur’an, ahlak. Tradicija u BiH duga vijekovima.</p><p><strong>Džamija</strong> — mjesto ibadeta i predavanja; tu se susrećemo sa cijelom zajednicom.</p><p><strong>Škola</strong> — opće obrazovanje; znanje za ovaj svijet.</p><p>Sve tri (porodica, mekteb/džamija, škola) treba da rade zajedno — uče istom moralu i vrijednostima.</p><p>Naša obaveza: aktivno učestvovati u svim, poštovati sve učitelje (i vjerske i opće), donositi naučeno kući i u zajednicu.</p><p>Razlika obrazovanja i odgoja: obrazovanje je znanje, odgoj je karakter; pravi musliman ima oboje.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako rade ove ustanove zajedno u njihovom životu. Zaključak: tri stuba — porodica, mekteb, škola.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                TRI STUPA TVOJE BUDUĆNOSTI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamisli da gradiš kuću u kojoj ćeš živjeti cijeli život. Ta kuća ne može stajati na samo jednom stubu; potrebna su joj tri snažna temelja da bi izdržala sve oluje i godine. U tvom odrastanju, ta tri temelja su mekteb, džamija i škola. Škola ti daje znanje o svijetu, mekteb ti otvara vrata vjere i uči te kako biti plemenit čovjek, a džamija je mjesto susreta gdje to znanje i vjeru živiš s drugima. Ako samo jedan od ovih temelja nedostaje, tvoja \"kuća\" neće biti potpuna. Danas ćemo naučiti kako ova tri mjesta rade zajedno da bi tebi pružila najbolju varijantu života i učinila te ponosom tvojih roditelja i zajednice.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: I doista, ovo je pravi put Moj pa se njega držite i druge puteve ne slijedite, pa da vas odvoje od puta Njegova; - eto tako vam On naređuje, da biste se grijeha klonili. (El-En'am, 153)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Poslanik, alejhis-selam, nas uči da je vjera savjet. Kur'an nas opominje da život nije igra i zabava nego ozbiljna stvar. Za kvalitetan život savjet je neophodan, a najbolji savjet za kvalitetan život je vjera. Da imamo dva života bilo bi lahko. Jedan bi mogao biti generalna proba na kojoj bi se isprobale mnoge varijante života i izabrala najbolja. Međutim, život je jedan, šansa je jedna, nema probe niti nove šanse.\n                </p>\n                <p class=\"lesson-text\">\n                    Kako god su prve riječi Kur'ana objavljene kao naredba da se uči: Uči u ime Gospodara tvoga koji stvara (El-Alek, 1), tako i našu djecu odmah od malena treba učiti. Našoj djeci u ranom djetinjstvu je potreban savjet. Treba im objasniti najbolju varijantu života.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">MEKTEB</p>\n                <p class=\"lesson-text\">\n                    Mekteb je najznačajnija institucija u našoj zemlji koja djecu na vrijeme uči ono šta vjera traži. Mekteb na odgovarajući način servira djeci sve savjete koje život treba i bez generalne probe nudi najbolju varijantu života. Onu koja život čuva, a ne uništava; onu koja život iskoristi, a ne upropasti; onu koja vodi uspjehu, sreći, ljepoti na ovom svijetu i u vječnosti.\n                </p>\n                <p class=\"lesson-text\">\n                    Mekteb u Bosni i Hercegovini stotinama godina podiže generacije ljudi na temeljima vjere. Iz njega su kroz historiju izrasli mnogi alimi, muftije, sudije, vojskovođe, veziri, ali ono najvažnije jeste da se u mektebu uči biti čovjek u skladu s vjerom. Mekteb razvija lijepe osobine koje treba da krase čovjeka i približavaju ga stepenu meleka, a čuva ga od ružnih osobina.\n                </p>\n                <p class=\"lesson-text\">\n                    Muallimi podučavanjem učenika kelimei-šehadetu, harfovima i surama su u ibadetu i dok god njihovi učenici izgovaraju šehadet, uče sure, klanjaju, oni imaju dobro djelo od toga.\n                </p>\n                <p class=\"lesson-text\">\n                    Roditelji imaju obavezu da lijepo odgoje svoju djecu i da ih poduče vjeri. Mekteb im pomaže u tome, a roditelji i rodbina će šaljući i podstičući djecu da idu u mekteb, za svoj trud, odgovornost i ustrajnost, ako Bog da, imati i dunjalučku i ahiretsku korist.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">DŽAMIJA I ŠKOLA</p>\n                <p class=\"lesson-text\">\n                    Pored mekteba, temelji odgoja i obrazovanja su džamije i škole. Dovoljno nam je uzeti za primjer da je Poslanik, alejhis-selam, džamiju koristio ne samo za namaz nego kao mjesto gdje su se ashabi i on okupljali. U džamiji je Poslanik, alejhis-selam, odgajao najhrabrije, najčasnije, najmoralnije ljude pa ne čudi da su oni u Kur'anu nazvani najboljom generacijom.\n                </p>\n                <p class=\"lesson-text\">\n                    Kada vidimo ciljeve koji su u školi postavljeni kao najznačajniji, shvatit ćemo da je upravo škola, uz mekteb i džamiju, temelj odgoja i obrazovanja. Neki od ciljeva odgoja i obrazovanja u mektebu i školi su:\n                </p>\n                <ul class=\"lesson-text\">\n                    <li>osigurati sistemski način poučavanja učenika, podsticati i unapređivati njihov intelektualni, tjelesni, estetski, društveni, moralni i duhovni razvoj u skladu s njihovim sposobnostima i sklonostima,</li>\n                    <li>razvijati svijest o nacionalnoj pripadnosti, očuvanju historijsko-kulturne baštine i nacionalnog identiteta,</li>\n                    <li>odgajati i obrazovati učenike da znaju za opće kulturne i civilizacijske vrijednosti, ljudska prava i prava djece, osposobiti ih za življenje u multikulturalnom svijetu, za poštivanje različitosti i za toleranciju te za aktivno i odgovorno djelovanje u razvoju društva,</li>\n                    <li>osigurati učenicima stjecanje temeljnih i stručnih sposobnosti, osposobiti ih za život i rad u promjenjivom društveno-kulturnom pogledu prema zahtjevima tržišta rada, savremenih informacijsko-komunikacijskih tehnologija i naučnih spoznaja i dostignuća,</li>\n                    <li>osposobiti učenike za cjeloživotno učenje,</li>\n                    <li>odgojiti i osposobiti učenike da budu praktični vjernici i korisni članovi svoje zajednice.</li>\n                </ul>\n                <p class=\"lesson-text\">\n                    Mekteb, džamija i škola tri su temelja odgoja i obrazovanja i ukoliko bilo koji nedostaje, odgoj i obrazovanje nisu potpuni.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - TEMELJI ODGOJA</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA I ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je mekteb, a šta džamija?</li>\n                    <li>Koja je obaveza roditelja prema mektebu?</li>\n                    <li>Koji su ciljevi odgoja i obrazovanja?</li>\n                    <li>ZADATAK: U datoj tabeli napiši čemu te uče mekteb, džamija i škola!\n                        <ul style=\"list-style-type: none; margin-top: 10px;\">\n                            <li>1. Mekteb me uči...</li>\n                            <li>2. Džamija me uči...</li>\n                            <li>3. Škola me uči...</li>\n                        </ul>\n                    </li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":94,"is_published":true,"kviz_pitanja":[{"answer":"Institucija koja djecu uči ono što vjera traži","options":["Institucija koja djecu uči ono što vjera traži","Mjesto gdje se igraju samo igre","Zgrada za sport i vježbanje","Mesto gdje se kupuje knjige"],"question":"Šta je mekteb u našoj zemlji?"},{"answer":"Samo jednu šansu","options":["Nekoliko šansi za isprobavanje","Samo jednu šansu","Tri važne šanse","Bezbroj šansi"],"question":"Koliko šansi imamo u životu?"},{"answer":"El-Alek","options":["El-Fatiha","El-Alek","El-En'am","Ja-Sin"],"question":"Koja je prva sura Kur'ana objavljena kao naredba?"},{"answer":"Lijepe osobine koje krase čovjeka","options":["Samo matematičke vještine","Samo sportske sposobnosti","Lijepe osobine koje krase čovjeka","Samo pisanje i čitanje"],"question":"Šta mekteb razvija kod djece?"},{"answer":"Lijepo ih odgojiti i podučiti vjeri","options":["Kupovati im igračke i gadžete","Lijepo ih odgojiti i podučiti vjeri","Dopustiti im sve što žele","Samo ih nahraniti"],"question":"Koja je glavna obaveza roditelja prema djeci?"}]},{"nivo":3,"slug":"iz-ustanove","naslov":"Odgojno-obrazovne ustanove Islamske zajednice","content_html":"<div class=\"lesson-container\">\n        <h1>ODGOJNO-OBRAZOVNE USTANOVE ISLAMSKE ZAJEDNICE</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ustanove.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Odgojno-obrazovne ustanove Islamske zajednice</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kultura i tradicija</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ponosa na obrazovne ustanove IZ</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa glavnim obrazovnim ustanovama IZ u BiH</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje motivacije za obrazovanje u tim ustanovama</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koje obrazovne ustanove ima Islamska zajednica BiH? Hajde da ih upoznamo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Mektebi</strong> — osnovna vjerska škola; pohađaju je djeca starosti od 7 do 14 godina; uče Kur’an, ilmihal, lijepa ponašanja.</p><p><strong>Medrese</strong> — srednje vjerske škole. Najpoznatije: Gazi Husrev-begova medresa (Sarajevo, osnovana 1537.), Behram-begova (Tuzla), Karađoz-begova (Mostar), Elči Ibrahim-pašina (Travnik), Osman-ef. Redžovića (Velika Kladuša), Cazinska medresa.</p><p><strong>Fakultet islamskih nauka u Sarajevu</strong> — visoko islamsko obrazovanje; obrazuje imame, mualime, profesore vjeronauke.</p><p><strong>Pedagoški fakulteti</strong> — odsjeci za islamsku vjeronauku.</p><p><strong>Drugi seminari i obuke</strong> — za hatibe, učitelje, učenice mekteba.</p><p>Cilj svih ovih ustanova: obrazovati novu generaciju koja zna vjeru i može je prenijeti dalje.</p><p>Naša obaveza: pomagati ove ustanove (vakufima, donacijama), upisati djecu u mekteb, podržati medrese.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o svojim planovima za obrazovanje. Zaključak: islamsko obrazovanje je naš dragocjeni biser.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                PUT ZNANJA I PLEMENITOSTI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Put stjecanja znanja u islamu sliči putovanju kroz prelijepi vrt koji se stalno širi. Počinje malim koracima u mektebu, gdje učimo prve harfove i dove, a nastavlja se kroz medrese i fakultete, gdje znanje postaje duboko poput okeana. Islamska zajednica je poput brižnog vrtlara koji je posadio ove ustanove kako bi svaki mladi čovjek mogao uzrasti u snažno i plemenito stablo. Danas ćemo istražiti sve nivoe obrazovanja koje nam nudi naša Zajednica – od onih prvih dana u obdaništu, preko slavnih medresa koje čuvaju tradiciju stoljećima, pa sve do fakulteta koji obrazuju buduće predvodnike. Ovo je put na kojem se uči kako biti koristan sebi i drugima, i kako osvijetliti svijet svjetlošću znanja i vjere.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">\n                    Islamska zajednica u Bosni i Hercegovini posredstvom svojih uprava pri Rijasetu Islamske zajednice ima zadatak da se brine o organizaciji i procesu odgojno-obrazovnog djelovanja.\n                </p>\n                <p class=\"lesson-text\">\n                    Cilj odgojno-obrazovnih ustanova je učenike upoznati i poučiti osnovama islamskog vjerovanja i učenja, osposobiti ih za praktično življenje islama, shodno islamskim propisima, propisima sadržanim u Kur’anu i hadisu, te da Islamska zajednica ispuni preuzeti emanet i pokaže odgovornost prema svojoj osnovnoj misiji poučavanja svojih pripadnika.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">NIVOI ODGOJNO-OBRAZOVNIH USTANOVA</p>\n                <p class=\"lesson-text\">\n                    Nivoi odgojno-obrazovnih ustanova Islamske zajednice u Bosni i Hercegovini su:\n                </p>\n                <ol class=\"lesson-text\">\n                    <li><strong>predškolske odgojno-obrazovne ustanove</strong>,</li>\n                    <li><strong>mektebi</strong> – osnovne odgojno-obrazovne ustanove koje djeluju u svakom džematu,</li>\n                    <li><strong>medrese</strong> – škole srednjoškolskog tipa:\n                        <ul>\n                            <li>Gazi Husrev-begova medresa u Sarajevu,</li>\n                            <li>Medresa “Osman ef. Redžović” u Visokom,</li>\n                            <li>Elči Ibrahim-pašina medresa u Travniku,</li>\n                            <li>Karađoz-begova medresa u Mostaru,</li>\n                            <li>Behram-begova medresa u Tuzli,</li>\n                            <li>Medresa “Džemaludin-ef. Čaušević” u Cazinu,</li>\n                            <li>Medresa “Gazi Isa-beg” u Novom Pazaru,</li>\n                        </ul>\n                    </li>\n                    <li><strong>fakulteti</strong> – visokoškolske ustanove koje obrazuju buduće imame i vjeroučitelje:\n                        <ul>\n                            <li>Fakulet islamskih nauka u Sarajevu,</li>\n                            <li>Islamski pedagoški fakultet u Zenici,</li>\n                            <li>Islamski pedagoški fakultet u Bihaću i</li>\n                            <li>Fakultet za islamske studije u Novom Pazaru.</li>\n                        </ul>\n                    </li>\n                </ol>\n\n                \n\n                <p class=\"lesson-text\">\n                    Islamska zajednica u Bosni i Hercegovini kroz mekteb i druge odgojno-obrazovne ustanove nudi odgovarajući sistem odgojno-obrazovnog rada koji uz stručne kadrove predstavlja snažnu, ali i neophodnu pomoć u ispunjavanju roditeljske obaveze islamskog odgajanja djece.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - USTANOVE IZ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA I ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je cilj rada odgojno-obrazovnih ustanova IZ?</li>\n                    <li>Koje medrese djeluju u Bosni i Hercegovini?</li>\n                    <li>Na kojim fakultetima se stječe islamsko obrazovanje?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li><strong>ZADATAK 1:</strong> Nekada su medrese obrazovale isključivo vjerske službenike – imame. Kakva je situacija danas i koje mogućnosti se otvaraju pred onim ko završi medresu?</li>\n                    <li><strong>ZADATAK 2:</strong> Opiši svoj put kroz islamsko obrazovanje u ustanovama IZ počevši od mekteba. Ukoliko planiraš upisati medresu, opiši svoj stav o tome kako će to obrazovanje izgledati i šta očekuješ! Ako planiraš upisati neku drugu srednju školu, prezentiraj nastavak svog neformalnog islamskog obrazovanja.</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">RAZGOVOR S MUALLIMOM</p>\n                <ul class=\"lesson-text\">\n                    <li>Gazi Husrev-begova medresa u Sarajevu.</li>\n                    <li>Medresa koja je najbliža mom džematu.</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":95,"is_published":true,"kviz_pitanja":[{"answer":"Učenike upoznati sa osnovama islamskog vjerovanja i učenja","options":["Učenike upoznati sa osnovama islamskog vjerovanja i učenja","Učenike pripremiti samo za pismene testove","Učenike naučiti samo arabski jezik","Učenike pripremiti samo za igre i sport"],"question":"Koji je osnovni cilj odgojno-obrazovnih ustanova Islamske zajednice?"},{"answer":"Četiri nivoa","options":["Četiri nivoa","Dva nivoa","Pet nivoa","Tri nivoa"],"question":"Koliko nivoa odgojno-obrazovnih ustanova postoji u Islamskoj zajednici?"},{"answer":"U Sarajevu","options":["U Sarajevu","U Mostaru","U Visokom","U Tuzli"],"question":"Gdje se nalazi Gazi Husrev-begova medresa?"},{"answer":"Osnovne odgojno-obrazovne ustanove koje djeluju u džemat","options":["Osnovne odgojno-obrazovne ustanove koje djeluju u džemat","Vrhunske škole za odrasle","Tečajeve za učenje stranih jezika","Fakulteti za buduće imame"],"question":"Što su mektebi u Islamskoj zajednici?"},{"answer":"Fakultet islamskih nauka, pedagoški fakulteti i fakulteti za studije","options":["Fakultet islamskih nauka, pedagoški fakulteti i fakulteti za studije","Samo medicinski fakulteti","Samo ekonomski fakulteti","Samo tehnički fakulteti"],"question":"Koji fakulteti educiraju buduće imame i vjeroučitelje?"}]},{"nivo":3,"slug":"halife","naslov":"Pravedne halife: hazreti Ebu Bekr, Omer, Osman i Alija, r.a.","content_html":"<div class=\"lesson-container\">\n        <h1>PRAVEDNE HALIFE</h1>\n        <p class=\"section-subtitle\">hazreti Ebu Bekr, Omer, Osman i Alija, r.a.</p>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/halife.jpg\">\n        \n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Pravedne halife: Ebu Bekr, Omer, Osman, Alija, r.a.</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi i poštovanja prema četvorici pravednih halifa</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti glavne crte života i djela četvorice halifa</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti slijeđenja primjera halifa</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko su bili prvi muslimanski vladari nakon Poslanika, a.s.? Pravedne halife. Ko su oni?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Ebu Bekr es-Siddik, r.a.</strong> (632-634) — prvi halifa, \"najistinitiji\"; podržao Poslanika u Hidžri; konsolidirao islam (ratovi protiv otpadnika); počeo sakupljanje Kur’ana.</p><p><strong>Omer ibn el-Hattab, r.a.</strong> (634-644) — drugi halifa, \"el-Faruk\"; veliki osvajač (Šam, Egipat, Perzija); osnovao islamski kalendar (od Hidžre); poznat po pravednosti.</p><p><strong>Osman ibn Affan, r.a.</strong> (644-656) — treći halifa, \"Zun-Nūrejn\" (Posjednik dva svjetla — oženio dvije Poslanikove kćerke); standardizirao Kur’an u jedan mushaf; veliki dobrotvor.</p><p><strong>Alija ibn Ebi Talib, r.a.</strong> (656-661) — četvrti halifa; Poslanikov amidžić i zet (oženio Fatimu, r.a.); poznat po znanju, hrabrosti i pobožnosti.</p><p>Sva četvorica: ashabi Poslanika, a.s.; pravedni vladari; svi su preselili kao šehidi (osim Ebu Bekra).</p><p>Naša obaveza: voljeti ih, slijediti ih, ne pričati ružno o njima.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju četvoricu halifa. Zaključak: zlatno doba islama — primjer pravednog vladanja.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":96,"is_published":true,"kviz_pitanja":[{"answer":"Hulefair-rašidin","options":["Hulefair-rašidin","Hulefair-umavijadi","Hulefair-abbasijadi","Hulefair-fatimiyadi"],"question":"Kako se zovu četverica halifa koje su muslimani sami izabrali?"},{"answer":"Savladao je sve pobune i uveo red","options":["Savladao je sve pobune i uveo red","Osvojio je Jerusalem bez borbe","Sakupio je Kur'an u jednu zbirku","Osvojio je čitavo Perzijsko carstvo"],"question":"Koja je bila hauptna akcija Ebu Bekra u prvoj godini vladavine?"},{"answer":"Sakupljen je u jednu zbirku","options":["Sakupljen je u jednu zbirku","Preveden je na arapski","Podjeljen je u dijelove","Poslan je u sve zemlje"],"question":"Šta je učinjeno sa Kur'anom za vrijeme Ebu Bekreve vladavine?"},{"answer":"Deset godina","options":["Deset godina","Pet godina","Dvanaest godina","Osam godina"],"question":"Koliko godina je vladao halifa Omer, sin Hattabov?"},{"answer":"Osvojen je bez borbe","options":["Osvojen je bez borbe","Osvažen je nakon tešké borbe","Bio je napušten","Nikada nije osvojen"],"question":"Šta je posebno bilo vezano za Jerusalem tijekom Omerove vladavine?"}]},{"nivo":3,"slug":"odabrane-zene","naslov":"Odabrane žene spomenute u Kur'anu i hadisima","content_html":"<div class=\"lesson-container\">\n        <h1>ODABRANE ŽENE SPOMENUTE U KUR’ANU I HADISIMA</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/odabrane_zene.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Odabrane žene spomenute u Kur’anu i hadisima</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Historija islama</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje poštovanja prema ženama u islamu i njihovoj ulozi</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa najvažnijim ženama u islamskoj historiji</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti uzimanja primjera od velikih žena islama</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koje su žene posebno spomenute u Kur’anu? Koje su bile uz Poslanika, a.s.? Hajde da ih upoznamo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Hava</strong> — supruga Adema, a.s., majka čovječanstva.</p><p><strong>Asija</strong> — supruga Faraona; vjerovala u Mūsau, a.s., usprkos prijetnji smrću; zatražila kuću u Džennetu kraj Allaha.</p><p><strong>Merjem (Marija), bint Imran</strong> — majka Īsaa, a.s.; čista djevica; jedna od najboljih žena svih vremena.</p><p><strong>Hatidža bint Huvejlid, r.a.</strong> — prva supruga Poslanika, a.s.; prva vjernica; podržavala ga u svemu; majka većine Poslanikove djece.</p><p><strong>Aiša bint Ebi Bekr, r.a.</strong> — najmlađa supruga Poslanika; velika učenjakinja, prenjela mnoge hadise; poznata po znanju.</p><p><strong>Fatima bint Muhammed, r.a.</strong> — najmlađa Poslanikova kćer; supruga Alije, r.a.; majka Hasana i Huseina, r.a.; \"gospodarica žena Dženneta\".</p><p><strong>Sumejja, r.a.</strong> — prva muslimanska šehidkinja; ubijena od strane mušrika.</p><p>Naša obaveza: poštovati žene; ne potcjenjivati njihovu ulogu; učiti od ovih primjera majkama, suprugama, kćerima.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju žene i njihove odlike. Zaključak: islam diže ženu visoko — slijedimo te primjere.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                SVJETILJKE DOBROTE I HRABROSTI <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamislite četiri žene čija imena već stoljećima odjekuju kao najljepša inspiracija svim ljudima svijeta. One nisu bile samo supruge ili kćerke velikih poslanika; one su bile nepokolebljive planine snage, vjere i plemenitosti. Jedna se suprotstavila najmoćnijem tiraninu svog vremena, druga je s potpunim pouzdanjem u Boga postala majka bez oca, treća je bila prvi i najčvršći oslonac islama kada niko drugi nije vjerovao, a četvrta je svojim strpljenjem i moralom postala uzor svakom djetetu. Danas ćemo upoznati Asiju, Merjemu, Hatidžu i Fatimu. Njihovi životi su poput bisera koji nam pokazuju da prava vrijednost čovjeka leži u čistoći srca i snazi karaktera. Zakoračimo u njihove priče i otkrijmo zašto ih je naš Poslanik nazvao najodabranijim ženama dunjaluka.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">\n                    Nakon što je stvoren Adem, alejhis-selam, Allah, dž.š., je stvorio i njegovu suprugu, prvu ženu na dunjaluku h. Havu. Uloga žene u islamu je nemjerljiva, a naša obaveza je da shvatimo koliko je važno da ženu kao majku volimo i pazimo, kao suprugu i kćerku volimo i odgajamo, kao sestru volimo i poštujemo. Osim ovih osnovnih uloga kojima je Uzvišeni Allah obradovao ženu, ona je i prijateljica, njegovateljica, savjetnica, državnica i dr. Koliko islam pridaje značaj ženi koja je u mnogim društvima danas obespravljena i ugrožena, pokazuje i činjenica da od 114 kur'anskih sura jedna nosi naziv En-Nisa – Žene, a u isto vrijeme nema kur'anske sure koja nosi naziv muškarac.\n                </p>\n                <p class=\"lesson-text\">\n                    Četiri odabrane žene spomenute u Kur’anu i hadisima motiv su i obrazac ponašanja svim drugim ženama.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ASIJA, SUPRUGA FARAONOVA</p>\n                <p class=\"lesson-text\">\n                    <strong>Primjer Asijine hrabrosti u vjeri</strong>\n                </p>\n                <p class=\"lesson-text\">\n                    Asija, supruga faraonova, krila je iman od svog muža. Kada je faraon za to saznao, odmah je naredio da je kazne, ne prezajući ni od čega. Mučili su je na razne načine. Faraon bi je ubjeđivao: “Odreci se svoje vjere!” Međutim, ona je bila postojana u imanu. Ponovo bi joj faraon govorio: “Odreci se svoje vjere!” Ona mu je odgovarala: “Imaš vlast nad mojim tijelom, ali moje srce je u zaštiti moga Gospodara!” Potom je pored nje prošao Musa, alejhis-selam, koga Asija zovnu: “Obavjesti me, Musa, je li moj Gospodar sa mnom zadovoljan ili je na mene srdit!” Musa, alejhis-selam, joj odgovori: “Asija, meleki na nebesima te čekaju, čeznu za tobom. A Allah se tobom ponosi! Traži šta želiš, bit će ti udovoljeno!”\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: A onima koji vjeruju – Allah kao pouku navodi ženu faraonovu, kad je rekla: Gospodaru moj, sagradi mi kod Sebe kuću u Džennetu i spasi me od faraona i mučenja njegova, i izbavi me od naroda nepravednog. (Et-Tahrim, 11)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">MERJEM, KĆI IMRANOVA I MAJKA ISAA, A.S.</p>\n                <p class=\"lesson-text\">\n                    Merjem, kćerka Imrana, je žena koju Kur’an navodi kao majku poslanika Isaa. Jedina je žena imenom spomenuta u Kur’anu, a cijela kur'anska sura nazvana je po njoj. Posljednji Allahov Poslanik ju je spomenuo kao jednu od četiri najbolje žene koje će prve ući u Džennet. Islam, međutim, poriče božanstvenost Merjeme i Isaa, kao i tvrdnju da je Isa sin Božiji. U Kur’anu je ona nazvana “sestrom Harunovom”. Smatra se da se misli na Haruna, Musaovog brata, na temelju toga što Merjemin položaj u odnosu na objavu Isau možemo uporediti s Harunovim položajem u odnosu na Musaa.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Allah, dž.š., kaže: Kada Imranova žena reče: “Gospodaru moj, ovo što je u trbuhu mome ja zavjetujem samo na službu Tebi, pa primi od mene, jer Ti, zaista, sve čuješ i znaš!” Poslije ona, kada je rodila, reče: “Gospodaru moj, rodila sam žensko” , ‒ a Allah dobro zna šta je rodila, “a žensko nije kao muško; nadjela sam joj ime Merjema, i ja nju i porod njezin stavljam pod Tvoje okrilje od prokletog šejtana.” (Alu Imran, 35-36)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">HATIDŽA, KĆI HUVEJLIDA I SUPRUGA MUHAMMEDA, A.S.</p>\n                <p class=\"lesson-text\">\n                    Primjer čestitosti, ljepote, poštenja, staloženosti, povjerenja jeste Hatidža, prva supruga Muhammeda, alejhis-selam Hazreti Hatidža ostat će osnovni dunjalučki i duhovni oslonac Muhammedu, alejhis-selam, i tada a naročito u danima početka posljednje Božije objave i u danima prvih progona muslimana. Ona je ujedno i prva vjernica koja je vjerovala u Uzvišenog Allaha i istinitost Muhammedovog, alejhis-selam, poslanstva.\n                </p>\n                <p class=\"lesson-text\">\n                    Jedne prilike je Džibril došao Muhammedu, alejhis-selam, i rekao mu: “Allahov Poslaniče, ovo je Hatidža, kod nje je posuda u kojoj su hrana i piće. Kada ti dođe, prenesi joj od njenoga Gospodara selam, i od mene.” (Buhari)\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">FATIMA, KĆI MUHAMMEDA, A.S.</p>\n                <p class=\"lesson-text\">\n                    Fatima kći Poslanika Muhammeda, alejhis-selam, posjedovala je osobine strpljivosti i tolerantnosti. Osim toga, njen život krasili su moral, kultura i lijepo ponašanje. Ona je učila sve to od najodabranijeg Allahovog stvorenja, poslanika Muhammeda, alejhis-selam Životni put Fatime, kćerke Muhammeda, alejhis-selam, nije samo primjer za žene, ona je živjela tako da je primjer i muškarcima i ženama.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - ODABRANE ŽENE</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA I ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Koje su to odabrane žene?</li>\n                    <li>Koje su osobine koje su krasile te četiri odabrane žene?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADATAK</p>\n                <p class=\"lesson-text\">\n                    U ovoj lekciji naučili smo imena četiri najodabranije žene. Pronađi još informacija vezanih za spomenute osobe! (Napomena: U istraživanju ti može pomoći knjiga Odabrane žene ummeta autorice Fatime Mušinović.)\n                </p>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Opiši i prenesi svojim prijateljima/cama nekoga u tvom životu, a ko ima lijepe osobine koje smo naučili iz ove lekcije?</li>\n                    <li>Napiši rad na temu “Majka je nabolji prijatelj”!</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">RAZGOVOR S MUALLIMOM</p>\n                <ul class=\"lesson-text\">\n                    <li>Zanimljivi događaji u životu odabranih žena.</li>\n                </ul>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":97,"is_published":true,"kviz_pitanja":[{"answer":"Hava","options":["Asija","Hava","Merjem","Fatima"],"question":"Ko je bila prva žena stvorena na dunjaluku?"},{"answer":"En-Nisa","options":["En-Nisa","Et-Tahrim","El-Imran","El-Ankebut"],"question":"Koja kur'anska sura nosi naziv 'Žene'?"},{"answer":"Moje srce je u zaštiti Gospodara!","options":["Odreci se vjere!","Moje srce je u zaštiti Gospodara!","Pusti me, molim te!","Ponos je u vjeri!"],"question":"Šta je Asija odgovorila faraonu kada ju je mučio?"},{"answer":"Majka poslanika Isaa","options":["Sinova poslanika","Majka poslanika Isaa","Supruga faraona","Sestra Muse"],"question":"Čiji je dijete bila Merjem, kćerka Imrana?"},{"answer":"Četiri žene","options":["Dvije žene","Tri žene","Četiri žene","Pet žena"],"question":"Koliko odabranih žena iz Kur'ana se spominje u lekciji?"}]},{"nivo":3,"slug":"vakufi-bih","naslov":"Najpoznatiji vakufi i vakufske građevine u Bosni i Hercegovini","content_html":"<div class=\"lesson-container\">\n        <h1>NAJPOZNATIJI VAKUFI I VAKUFSKE GRAĐEVINE U BOSNI I HERCEGOVINI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/vakuf1.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Najpoznatiji vakufi i vakufske građevine u BiH</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kultura i tradicija</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ponosa na bošnjačku vakufsku tradiciju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa najvažnijim vakufima u BiH</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje motivacije za uvakufljenje vlastite imovine</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je vakuf? To je trajno dobro djelo — imovina koju neko ostavi za zajednicu, koja vječno daje korist. Koji su poznati vakufi u BiH?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Vakuf — trajno uvakufljena imovina (zemlja, zgrada, kuća, šuma) čija korist ide u dobre svrhe (džamija, mekteb, siromasi, putnici).</p><p>Vakif — onaj ko uvakufljuje. Najveća sadaka tekuća — donosi nagrade i poslije smrti.</p><p>Najveći vakif u BiH: <strong>Gazi Husrev-beg</strong> (16. v.) — uvakufio: Begovu džamiju, Hanikah, Bezistan, Tašlihan, Imaret, Daru-l-mualimine — sve u Sarajevu. Njegovi vakufi i danas funkcionišu!</p><p>Drugi poznati vakifi: <strong>Ferhad-paša</strong> (Banja Luka — Ferhadija), <strong>Karađoz-beg</strong> (Mostar), <strong>Behram-beg</strong> (Tuzla), <strong>Aladža</strong> (Foča).</p><p>Vakufske građevine: džamije, medrese, mekteb, hamami, mostovi (Stari most u Mostaru), karavansaraji, biblioteke.</p><p>Vakufska direkcija — institucija IZ koja upravlja vakufima u BiH danas.</p><p>Pouka: i mi možemo uvakufiti — imovinu, knjige, vodu, drveće, novac za džamiju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta bi voljeli uvakufiti. Zaključak: vakuf je vječna sadaka.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                TRAG KOJI OSTAJE POSLIJE NAS <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Zamišljaš li ikada kako bi bilo ostaviti nešto što će koristiti ljudima i stotinama godina nakon što tebe ne bude? U našoj Bosni i Hercegovini postoje mostovi preko kojih i danas prelazimo, česme s kojih i danas pijemo vodu i škole u kojima se i danas uči, a sve to zahvaljujući ljudima koji su odlučili dio onoga što imaju dati za opće dobro. To je tajna vakufa – djela koja ne umiru. Danas ćemo prošetati kroz historiju i upoznati najveće bosanske dobročinitelje, od Isa-bega koji je udario temelje Sarajevu, do Gazi Husrev-bega čije srce i danas kuca u središtu naše čaršije. Otkrit ćemo kako su naši preci gradili gradove srcem i imetkom, ostavljajući nam u emanet ljepotu koja traje stoljećima.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">\n                    Vjera islam uči čovjeka da život na ovom svijetu ne prestaje smrću, nego da se nastavlja i na budućem svijetu. Isto tako, islam nas uči da i dobra djela koja uradimo, ne prestaju nego donose sevape sve dok ta dobra koriste ljudima. Jedan od načina da naša djela žive i nakon našeg preseljenja na ahiret jeste uvakufiti dio svoje imovine.\n                </p>\n                <p class=\"lesson-text\">\n                    Vakuf je zadužbina koju neka osoba svojevoljno izdvoji iz svoje imovine u ime Allaha, dž.š., a u korist zajednice muslimana. Vakif je osoba koja je uvakufila dio svoje imovine a vakufnama je dokument kojim se izražava volja vakifa.\n                </p>\n                <p class=\"lesson-text\">\n                    Vakuf je put kojim se približava Allahu Uzvišenom i stječe Njegovo zadovoljstvo.\n                </p>\n\n                <div class=\"arabic-card\">\n                    <p class=\"lesson-text\">\n                        Nećete zaslužiti nagradu sve dok ne udijelite dio od onoga što vam je najdraže, a bilo šta vi udijelili, Allah će sigurno za to znati. (Alu Imran, 92)\n                    </p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Uvakufljavanje datira od vremena Ibrahima, alejhis-selam, koji je sagradio Kabu sa svojim sinom Ismailom. Istu praksu nastavio je i Muhammed, alejhis-selam, te je prenio i na svoje sljedbenike. Omer, r.a., je prvi od ashaba uvakufio dio svoje imovine. Tako je uvakufljavanje nastavljeno kroz sve generacije muslimana.\n                </p>\n                <img src=\"/edu/assets/images/vakuf.jpg\" style=\"float: right; width: 250px; margin-left: 20px; margin-bottom: 10px; border-radius: 10px;\">\n                <p class=\"lesson-text\">\n                    U izgradnji institucije vakufa u Bosni i Hercegovini učestvovali su svi slojevi muslimanske zajednice, pa čak i siromasi koji su sa skromnim sredstvima ili radnom snagom u vidu: kopanja bunareva, izgradnjom česama, pravljenjem puteva, kalemljenjem voća i slično, učestvovali u izgradnji institucije vakufa.\n                </p>\n                <p class=\"lesson-text\">\n                    Vakifi su kroz bogatu bosanskohercegovačku historiju gradili: džamije, mektebe, medrese, mostove, česme, hamame, hanove, kuće, mlinove, pekare i dr.\n                </p>\n                <p class=\"lesson-text\">\n                    Najznamenitiji vakifi u Bosni i Hercegovini pojavili su se u periodu osmanske vladavine kada nastaju i najveći vakufi: vakuf Isa-bega Ishakovića, vakuf Gazi Husrev-bega, vakuf Rustem-paše Opukovića, vakuf Mehmed-paše Sokolovića, vakuf Ferhad-bega Sokolovića, vakuf Mehmed-bega Karađoza, vakuf Ali-paše Rizvanbegovića i drugi.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">VAKUF ISA-BEGA ISHAKOVIĆA</p>\n                <p class=\"lesson-text\">\n                    Godine 1457. Isa-beg Ishaković je u Sarajevu izgradio džamiju, u narodu zvana Careva džamija. Osim toga, izgradio je i dvor Begluk-saraj, tekiju na Bentbaši, ćupriju preko Miljacke, hamam, izvjestan broj dućana i mlinove na Miljacki. Gradnja mosta omogućila je povezivanje najstarijeg naselja oko Careve džamije s novim centrom na drugoj obali tako da su na njegovom vakufu udareni temelji grada Sarajeva.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">VAKUF GAZI HUSREV-BEGA</p>\n                <p class=\"lesson-text\">\n                    Gazi Husrev-beg je nekoliko puta izabran za namjesnika u Bosni. Godine 1531. izgradio je džamiju, a pored nje 1537. dovršava izgradnju čuvene medrese Kuršumlije. Osim medrese i džamije, Gazi Husrev-beg podiže i biblioteku, bezistan, imaret, mekteb, više hanova, musafirhana, hanikah – žensku školu i banju.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">VAKUF RUSTEM-PAŠE OPUKOVIĆA</p>\n                <p class=\"lesson-text\">\n                    U rodnom Sarajevu podigao je Brusa-bezistan, most preko Željeznice na Ilidži i han pored mosta.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">VAKUF MEHMED-PAŠE SOKOLOVIĆA</p>\n                <p class=\"lesson-text\">\n                    U rodnom selu Sokolovići sagradio je džamiju. Najveće arhitektonsko djelo jeste njegov most s jedanaest lukova, izgrađen u Višegradu 1571. godine.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">VAKUF FERHAD-BEGA SOKOLOVIĆA</p>\n                <p class=\"lesson-text\">\n                    U Banjoj Luci Ferhad-beg je podigao 216 javnih objekata, od kojih je najznačajnija Ferhadija džamija. U neposrednoj blizini dao je da se podigne 200 dućana, karavansaraj, hamam, saraj-dvor te još neki objekti.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">VAKUF MEHMED-BEGA KARAĐOZA</p>\n                <p class=\"lesson-text\">\n                    Karađoz-beg je u Mostaru 1557. godine sagradio džamiju pod kupolom i uz nju mekteb, medresu, biblioteku, imaret i musafirhanu. Pored ovih zadužbina, on je podigao i mesdžid u Potocima, dva mekteba u Konjicu i Potocima, četiri mosta, hamam u Blagaju. Za izdržavanje navedenih ustanova uvakufio je 42 trgovačka dućana u mostarskoj čaršiji. Godine 1889. godine ovaj vakuf je imao u svome posjedu 271 dućan, deset magaza, jednu pekaru i pet mezaristana.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">VAKUF ALI-PAŠE RIZVANBEGOVIĆA</p>\n                <p class=\"lesson-text\">\n                    Ali-paša je najveći vakif Stoca. On je 1836. godine uvakufio sljedeće: stupe u kasabi Stolac, pekaru i pet dućana u velikoj čaršiji, tri dućana i magazu.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - VAKUFI U BIH</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA I ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta je vakuf?</li>\n                    <li>Nabroj najpoznatije vakufe u Bosni i Hercegovini!</li>\n                    <li>Koji značaj imaju vakufi za zajednicu muslimana?</li>\n                    <li>ZADATAK: Koja vakufska imovina iz perioda procvata vakufa u Bosni i Hercegovini se nalazi u vašem ili obližnjem gradu? Ko je osnivač tih vakufa i u kakvom su stanju danas?</li>\n                </ol>\n\n                <p class=\"section-subtitle\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">IZABERI ZADATAK!</p>\n                <ol class=\"lesson-text\">\n                    <li>Veliki vakufi koji su podizani npr. u Sarajevu, pored opće koristi za zajednicu imali su još mnogo koristi, koje su to?</li>\n                    <li>Istraži koliko je procentualno vakufske zemlje imala Bosna i Hercegovina po dolasku Austro-Ugarske, a koliko ima danas?</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":98,"is_published":true,"kviz_pitanja":[{"answer":"Zadužbina koju osoba izdvoji za zajednicu muslimana","options":["Zadužbina koju osoba izdvoji za zajednicu muslimana","Novac koji se daje siromasima","Григоорис мешхиђ Се дарлезо ажан","Dio nasljeđa koji se dijeli između nasljednika"],"question":"Šta je vakuf?"},{"answer":"Omer, r.a.","options":["Omer, r.a.","Muhammed, alejhis-selam","Ibrahim, alejhis-selam","Ali, r.a."],"question":"Ko je bio prvi ashaba koji je uvakufio imovinu?"},{"answer":"Džamije, mostove, mektebe, medrese i druge","options":["Džamije, mostove, mektebe, medrese i druge","Samo vojne utvrde i tvrđave","Samo trgovine i kancelarije","Samo restorane i kafane"],"question":"Koje građevine su vakifi gradili u Bosni i Hercegovini?"},{"answer":"Tijekom osmanske vladavine","options":["Tijekom osmanske vladavine","Za vrijeme francuske revolucije","U vrijeme austrougarske okupacije","Tijekom rimskog carstva"],"question":"U kojem periodu se pojavili najveći vakifi u Bosni i Hercegovini?"},{"answer":"Ibrahim sa svojim sinom Ismailom","options":["Ibrahim sa svojim sinom Ismailom","Muhammed sa Alijem","Omer sa Utmanom","Abbas sa Fatimom"],"question":"Ko je sagradio Kabu i počeo tradiciju vakufa?"}]},{"nivo":3,"slug":"bosnjacki-pjesnici","naslov":"Bošnjački pjesnici i književnici","content_html":"<div class=\"lesson-container\">\n        <h1>BOŠNJAČKI PJESNICI I KNJIŽEVNICI</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/bosna.jpg\">\n        </div>\n\n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Bošnjački pjesnici i književnici</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kultura i tradicija</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ponosa na bošnjačku književnu tradiciju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa najpoznatijim bošnjačkim pjesnicima i piscima</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike čitanja bošnjačke književnosti</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko su naši bošnjački pjesnici i pisci? Šta su nam ostavili?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Mak Dizdar</strong> (1917-1971) — najveći bošnjački pjesnik 20. v.; \"Kameni spavač\" — slavna poema o stećcima i bošnjačkoj duši.</p><p><strong>Meša Selimović</strong> (1910-1982) — romanopisac; \"Derviš i smrt\" i \"Tvrđava\" — vrhunska djela; prevedena na mnoge jezike.</p><p><strong>Skender Kulenović</strong> (1910-1978) — pjesnik; \"Stojanka majka Knežopoljka\" i \"Sonetni vijenac\".</p><p><strong>Nedžad Ibrišimović</strong> (1940-2011) — pisac; \"Knjiga Adema Kahrimana\" — vrhunska duhovna proza.</p><p><strong>Abdulah Sidran</strong> — pjesnik i scenarist; \"Otac na službenom putu\" i druga djela.</p><p><strong>Dževad Karahasan</strong> — savremeni pisac; nagrađivan u Evropi.</p><p>Stariji vakat (osmanski period): pisali su na orijentalnim jezicima — Hasan Kafi Pruščak, Sabit Užičanin, Hadži Jusuf Livnjak; poezija na arebici (bosanski jezik arapskim pismom).</p><p>Bošnjačka usmena književnost: sevdalinke, balade, narodne pjesme, mevludi, ilahije, kasside.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta su čitali. Zaključak: čitajmo naše pisce — to je naša duša.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">\n                RIJEČ KAO ODBRANA I AMANET <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Jeste li se ikada zapitali kako su naši preci čuvali svoju dušu i glas u vremenima kada su se nad Bosnom smjenjivale velike sile? Odgovor se krije u pisanoj riječi. Bošnjački pjesnici i književnici nisu pisali samo o ljepoti prirode; njihova pera bila su oružje protiv zaborava i izraz otpora svakoj nepravdi. Od ljetopisa Mula Mustafe Bašeskije, koji je bilježio svakodnevni život Sarajeva, do potresnih kasida Abdulvehaba Ilhamije i modernih djela velikana poput Meše Selimovića, naša književnost je ogledalo naše historije. Danas ćemo upoznati te čuvare naše tradicije i jezika, ljude koji su u najtežim trenucima ratova i stradanja stvarali djela koja i danas žive i uče nas ko smo i kuda idemo.</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">\n                NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ILMIHAL\" class=\"lesson-content\">\n                \n                <p class=\"lesson-text\">\n                    Najznačajnija djela u sferi književnosti i umjetnosti uopće nastala su poslije velikih i burnih historijskih događaja, najčešće ratova praćenih masovnim stradanjima ljudi. Bošnjačka književnost svakako je obilježena ovom društveno-historijskom karakteristikom jer je Bosna i Hercegovina rijetko bila samostalna. Uglavnom je bila pod utjecajem većih sila, pa su i književna djela izraz otpora, protivljenja i neslaganja s vlašću. Od najpoznatijih bosanskohercegovačkih pjesnika i književnika izdvajamo sljedeće:\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">MULA MUSTAFA BAŠESKIJA ‒ ŠEVKI</p>\n                <p class=\"lesson-text\">\n                    Bošnjački ljetopisac, rođen je u Sarajevu 1731. ili 1732. godine u Mimar-Sinanovoj mahali. O Bašeskiji znamo samo ono što je on o sebi zabilježio u svom Ljetopisu, pa je, prema tome, to i jedini izvor za upoznavanje njegova života i rada.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ABDULVEHAB ILHAMIJA</p>\n                <p class=\"lesson-text\">\n                    Rođen je 1773. godine u Žepču. Jedan je od rijetkih koji je u onom vremenu pisao na bosanskom jeziku. Ono po čemu je bio i ostao prepoznatljiv jeste njegova pjesma (kasida) “Čudan zeman nastade.”\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">EDHEM MULABDIĆ</p>\n                <p class=\"lesson-text\">\n                    Rođen je u Maglaju 1862. godine, gdje je završio mekteb i ruždiju, a nakon toga zaposlio se kao činovnik. Danas je Mulabdić lektirni pisac i pomalo mu se vraća značaj koji je imao u razvoju bošnjačke kulture i prosvjete.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">SAFVET-BEG BAŠAGIĆ</p>\n                <p class=\"lesson-text\">\n                    Rođen je 1870. godine i jedna je od najmarkantnijih ličnosti moderne bosanske i bošnjačke književnosti i začetnik bošnjačkog nacionalnog preporoda početkom 20. stoljeća.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">MUSA ĆAZIM ĆATIĆ</p>\n                <p class=\"lesson-text\">\n                    Rođen je u Odžaku 1878. godine. Umro je u aprilu 1915. godine. Mnoge škole u Bosni i Hercegovini nose njegovo ime.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">REŠAD KADIĆ</p>\n                <p class=\"lesson-text\">\n                    (Sarajevo, 1912 – Sarajevo, 1988), bosanskohercegovački književnik i novinar. Radio je u Tešnju. Jedna osnovna škola u Tešnju nosi njegovo ime.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ENVER ČOLAKOVIĆ</p>\n                <p class=\"lesson-text\">\n                    Rođen je 27. maja 1913. u Budimpešti a umro 18. augusta 1976. u Zagrebu. Bio je bosanskohercegovački pjesnik i prevodilac.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">DERVIŠ SUŠIĆ</p>\n                <p class=\"lesson-text\">\n                    Rođen je u Vlasenici 3. juna 1925. godine. Umro je u Sarajevu 1. septembra 1990. godine.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">NEDŽAD IBRIŠIMOVIĆ</p>\n                <p class=\"lesson-text\">\n                    Rođen je 20. oktobra 1940. u Sarajevu, a umro 15. septembra 2011. također u Sarajevu. Bio je istaknuti bosanskohercegovački književnik.\n                </p>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">ISNAM TALJIĆ</p>\n                <p class=\"lesson-text\">\n                    Rođen je 1954. godine u Vlasenici, gdje je živio do srpske oružane agresije 1992. godine. Umro je 12. oktobra 2017. Dugo se bavio novinarstvom. Isnam Taljić živio je u Sarajevu, radeći kao profesionalni književnik.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Pored spomenutih, istaknut ćemo i sljedeće bosanskohercegovačke pisce i pjesnike: Mehmedalija Mak Dizdar, Meša Selimović, Skender Kulenović, Alija Nametak, Hamza Humo, Ćamil Sijarić, Ahmed Muradbegović, Alija Isaković i drugi.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">\n                PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ - BOŠNJAČKI KNJIŽEVNICI</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">\n                PITANJA I ZADACI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"PITANJA\" class=\"lesson-content\">\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase;\">PITANJA I ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li>Šta karakterizira bosanskohercegovačku književnost općenito?</li>\n                    <li>Koji su istaknuti bosanskohercegovački književnici?</li>\n                    <li>Koje godine se prvi put pojavljuju književna djela na bosanskom jeziku?</li>\n                </ol>\n\n                <p class=\"lesson-text\" style=\"background-color: #fff9c4; text-transform: uppercase; margin-top: 20px;\">ZADACI</p>\n                <ol class=\"lesson-text\">\n                    <li><strong>ZADATAK 1:</strong> Od navedenih pjesnika ili književnika, pronađi neko djelo, a zatim razgovaraj o istom na mektebskoj nastavi.</li>\n                    <li><strong>ZADATAK 2:</strong> Izaberi jedno književno djelo navedenih autora, pročitaj ga, prepričaj i napiši zašto si to djelo odabrao!</li>\n                </ol>\n            </div>\n        </div>\n    </div>","audio_src":null,"redoslijed":99,"is_published":true,"kviz_pitanja":[{"answer":"U Sarajevu","options":["U Sarajevu","U Žepču","U Maglaju","U Odžaku"],"question":"U kojem gradu je rođen Mula Mustafa Bašeskija?"},{"answer":"Čudan zeman nastade","options":["Veliki Sarajevo","Čudan zeman nastade","Bosna moja","Pjesma od bola"],"question":"Koja je poznata kasida Abdulvehaba Ilhamije?"},{"answer":"U Maglaju","options":["U Sarajevu","U Žepču","U Maglaju","U Tešnju"],"question":"Gdje je Edhem Mulabdić završio mekteb i ruždiju?"},{"answer":"Početkom 20. stoljeća","options":["Krajem 19. stoljeća","Sredinom 19. stoljeća","Početkom 20. stoljeća","Sredinom 20. stoljeća"],"question":"Kada je Safvet-beg Bašagić započeo bošnjački nacionalni preporod?"},{"answer":"Osnovna škola Rešada Kadića","options":["Škola Muse Ćatića","Škola Edema Mulabdića","Osnovna škola Rešada Kadića","Škola Safveta-bega"],"question":"Koja osnovna škola u Tešnju nosi ime Rešada Kadića?"}]},{"nivo":21,"slug":"adem-as","naslov":"Adem, a.s.","content_html":"<div class=\"lesson-container\">\n        <h1>ADEM, A.S.</h1>\n        \n        <div class=\"hero-box\">\n            <img src=\"/edu/assets/images/adem_as.jpg\">\n        </div>\n\n        \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Adem, a.s. – prvi čovjek i Allahov poslanik</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Allahu Stvoritelju i poštovanja prema poslanicima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti učenike o stvaranju Adema, a.s., i njegovoj ulozi prvog čovjeka i poslanika</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti zaključivanja o Allahovoj milosti i mudrosti u stvaranju</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, znate li ko je bio prvi čovjek? Kako je nastao? Allah nam u Kur’anu kazuje priču o Ademu, a.s. Hajde da je danas naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Adem, a.s., je prvi čovjek kojeg je Allah stvorio od zemlje i potom u njega udahnuo dušu.</p><p>Allah ga je smjestio u Džennet zajedno sa suprugom Havvom, dao im sve blagodati, a zabranio im samo jedno drvo.</p><p>Šejtan ih je obmanuo, jeli su sa zabranjenog drveta i učinili su grešku. Iskreno su se pokajali, Allah im je oprostio i poslao ih na Zemlju.</p><p>Adem, a.s., bio je i prvi Allahov poslanik – učio je svoje potomstvo o Allahu, ibadetu i lijepom ponašanju.</p><p>Razgovor: Šta nas uči ova kazivanja? (Allah voli pokajanje, šejtan je naš neprijatelj, Allah je Stvoritelj svega.)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici prepričavaju ključne tačke kazivanja. Naglašavamo važnost tevbe i izbjegavanja šejtanskih našaptavanja.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> PRIČA O PRVOM ČOVJEKU <span class=\"section-icon\">▼</span>\n            </button>\n            <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n                <div class=\"lesson-text\">\n                    <p>Draga djeco, zamislite jedan prelijepi vrt, prepun rijeka, najukusnijih plodova i mirisnog cvijeća. To je Džennet, mjesto koje je naš Gospodar pripremio za svoje iskrene robove. Ali, jeste li se ikada zapitali ko je bio prvi stanovnik tog predivnog vrta? Ko je bio prvi čovjek koga je Uzvišeni Allah stvorio?</p>\n                    <p>Danas ćemo putovati kroz vrijeme, skroz do samog početka svijeta! Upoznat ćemo prvog čovjeka, našeg praoca Adema, alejhis-selam Saznat ćemo od čega je stvoren, ko mu je pravio društvo i zašto danas mi živimo na Zemlji, a ne u Džennetu. Jeste li spremni za ovu nevjerovatnu priču o početku ljudskog roda?</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ilmihal\" class=\"lesson-content\" style=\"display: none;\">\n                \n                <div class=\"arabic-card\">\n                    \n                    <p class=\"lesson-text\"><i>Allah, dž.š., kaže: To je Onaj koji zna i nevidljivi i vidljivi svijet, Silni i Milostivi, koji sve savršeno stvara, koji je prvog čovjeka stvorio od ilovače... (Es-Sedžda, 6-7)</i></p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Čovjek je najljepše Allahovo stvorenje. Prvi čovjek nema roditelje, niti se razvio iz majmunske vrste kako tvrdi teorija evolucije, već je Uzvišeni Allah stvorio Adema, alejhis-selam, u Džennetu od zemlje. Zatim je Allah, dž.š., naredio melekima da mu učine sedždu, što su oni i učinili. S njima je bio Iblis, koji je to odbio, uzoholio se i postao neposlušnik.\n                </p>\n\n                <div class=\"arabic-card\">\n                    \n                    <p class=\"lesson-text\"><i>Zašto se nisi poklonio kad sam ti naredio? upita On.<br>\n                    \"Ja sam bolji od njega; mene si od vatre stvorio, a njega od ilovače\" - odgovori on. (El-A'raf, 12)</i></p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Prvo boravište Adema i hazreti Have bio je Džennet. U Džennetu su imali sve što im je bilo potrebno, samo im je bilo zabranjeno približavati se jednom stablu kako ne bi postali grješnici i kako ne bi bili od onih koje je šejtan odveo u zabludu. Šejtan ih ne ostavlja na miru i nastoji ih nagovoriti da se približe zabranjenom stablu.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Govorio im je da je stablo zabranjeno samo zato kako oni ne bi postali meleki, vječni i kako ne bi dobili vječnu vlast. Šejtan im je obećavao besmrtnost, postajanje melekima i vlast koja nikada neće propasti, samo ako se približe tom stablu.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Kada su se približili zabranjenom stablu i uzeli njegov plod, Adem i Hava nisu postali ni meleki ni besmrtni, niti su zadobili neprolaznu vlast, nego su grijeh učinili i izgubili one blagodati koje su imali i nisu dobili ono što im je šejtan obećavao, jer su prekršili Allahovu naredbu i prekoračili dozvoljene granice.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Po Kur'anu, šejtan ih je oboje zaveo i na grijeh naveo, ali su se odmah pokajali.\n                </p>\n\n                <div class=\"arabic-card\">\n                    \n                    <p class=\"lesson-text\"><i>Gospodaru naš - rekoše oni - sami smo sebi krivi, i ako nam Ti ne oprostiš i ne smiluješ nam se, sigurno ćemo biti izgubljeni. (El- A'raf, 23)</i></p>\n                </div>\n\n                <p class=\"lesson-text\">\n                    Zbog počinjenog grijeha Adem i Hava su izvedeni iz Dženneta. Nakon dolaska na Zemlju, Allah je rastavio Adema i Havu. Dugo su se tražili i upućivali Allahu dove da se nađu. Znak da im je Allah oprostio bio je njihov ponovni susret.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Od Adema kao prvog čovjeka, prvog vjerovjesnika i njegove žene Have, razvio se kasnije cijeli ljudski rod. Kroz kur'ansko kazivanje o Ademu, alejhis-selam, naučili smo da će nas šejtan uvijek pokušavati navesti na grijeh.\n                </p>\n\n                <p class=\"lesson-text\">\n                    Muslimani i muslimanke, pored čvrste vjere u Allaha i činjenja dobrih djela, da bi bili spašeni od prokletog šejtana, trebaju stalno učiti Euzubillu.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"quiz\" class=\"lesson-content\" style=\"display: none;\">\n                <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">KVIZ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                    <p id=\"unlock-msg\" style=\"display: none;\">⭐ MAŠAALLAH! Uspješno ste savladali lekciju. Sada možete označiti naučeno!</p>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('ponovi', this)\"> PONOVI I ODGOVORI <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"ponovi\" class=\"lesson-content\" style=\"display: none;\">\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">PONOVI I ODGOVORI!</span></p>\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Kako je nastalo čovječanstvo?</li>\n                    <li>Ko je prvi čovjek na Zemlji?</li>\n                    <li>Ko je njegova žena?</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"lesson-accordion\">\n            <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaca', this)\"> IZABERI ZADAĆU <span class=\"section-icon\">▶</span>\n            </button>\n            <div id=\"zadaca\" class=\"lesson-content\" style=\"display: none;\">\n                <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">IZABERI ZADAĆU!</span></p>\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Razmisli i napiši u mektebsku svesku koje su štetnosti i posljedice šejtanovog djelovanja?!</li>\n                    <li>Razmisli i napiši u mektebsku svesku kako postupiti u situaciji kada te šejtan nagovara učiniti loše i šta poduzeti ako te uspije nagovoriti?</li>\n                </ul>\n            </div>\n        </div>\n\n    </div>","audio_src":null,"redoslijed":0,"is_published":true,"kviz_pitanja":[{"answer":"Od ilovače","options":["Od vode","Od ilovače","Od vatre","Od zraka"],"question":"Od čega je Allah stvorio prvog čovjeka Adema, alejhis-selam?"},{"answer":"Da mu učine sedždu","options":["Da ga poduce","Da mu učine sedždu","Da ga čuvaju","Da ga nauče"],"question":"Šta je Allah naredio melekima da učine Ademu?"},{"answer":"U Džennetu","options":["U kavama","Na planinama","U Džennetu","U pustinjama"],"question":"Gdje su boravili Adem i Hava prije grijeha?"},{"answer":"Besmrtnost i da budu meleki","options":["Bogatstvo i novac","Besmrtnost i da budu meleki","Djecu i porodicu","Znanje i mudrost"],"question":"Šta je šejtan obećavao Ademu i Havi ako se približe zabranjenom stablu?"},{"answer":"Odmah su se pokajali","options":["Nastavili su sa grijehom","Okrivili su šejtana","Odmah su se pokajali","Pokušali su bjeći od Alaha"],"question":"Kako se Adem i Hava ponašali nakon što su počinili grijeh?"}]},{"nivo":21,"slug":"mentu-billahi","naslov":"Prvi imanski šart - Āmentu billāhi","content_html":"<div class=\"lesson-container\">\n<h1>PRVI IMANSKI ŠART – AMENTU BILLAHI</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/amentu_billahi.jpg\" alt=\"Amentu billahi\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Prvi imanski šart – Āmentu billāhi (Vjerovanje u Allaha)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje vjere u Allaha i osjećaja stalne povezanosti sa Stvoriteljem</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta znači vjerovati u Allaha kao prvi imanski šart</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti svjedočenja Allahove jednoće u svakodnevnom životu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko ima imanskih šarta? Šest. Koji je prvi i najvažniji? Vjerovanje u Allaha. Šta to znači? Hajde da otkrijemo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Āmentu billāhi znači: <em>\"Vjerujem u Allaha.\"</em> To je prvi i najvažniji imanski šart.</p><p>Vjerovati u Allaha znači biti čvrsto uvjeren da postoji jedan jedini Allah, dž.š., Stvoritelj svega, bez sudruga.</p><p>Allah je Vječan, nema početka ni kraja. Sve drugo Allah je stvorio – nebo, zemlju, ljude, meleke.</p><p>Allah je sve čuo, sve vidi, sve zna – nikad nije umoran, nikad ne spava.</p><p>Postupak: Pišem na tabli \"Āmentu billāhi\" sa značenjem. Razgovor: kako se vjera u Allaha pokazuje (kroz ibadet, lijepa djela, čuvanje srca od grijeha).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici izgovaraju \"Āmentu billāhi\" zajedno. Pitam: po čemu vidimo da postoji Allah? (po stvaranju, po blagodatima, po redu u prirodi).</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> TAJANSTVENI PUTNIK <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Zamislite da sjedite u krugu sa prijateljima, a iznenada se pojavi putnik kakvog niko nikada nije vidio. Odjeća mu je bila bijela poput snijega, a kosa crna kao noć. Na njemu se nije vidio ni trun prašine, iako niko nije znao odakle dolazi.</p><p>Taj čovjek sjeo je ispred našeg Poslanika, alejhis-selam, i počeo mu postavljati najvažnija pitanja o našoj vjeri. Ashabi su slušali sa velikim čuđenjem, a kasnije su saznali da je taj tajanstveni gost bio melek Džibril, koji je došao podučiti nas najvažnijim temeljima vjere. Prvo i najvažnije o čemu su razgovarali bio je upravo iman – vjerovanje u Allaha, dž.š. Saznajmo zajedno šta znači vjerovati i kako možemo spoznati našeg Stvoritelja!</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Prvi imanski šart glasi: <strong>AMENTU BILLAHI - Ja vjerujem u Allaha</strong>.</p><p>Dužnost svakog muslimana i muslimanke je vjerovati u Allaha, dž.š. Vjerovanje u Allaha, dž.š., podrazumijeva srcem vjerovati a jezikom izgovarati da nema drugog Boga osim Allaha, dž.š. Allah je Gospodar i Stvoritelj svega. Allah je jedino dostojan da Ga vjerujemo i obožavamo, da se samo Njemu klanjamo i da samo Njemu robujemo. On ima 99 imena a vlastito Božije ime je Allah.</p><div class=\"arabic-card\"><p><em>Allah, dž.š., kaže: I znaj da nema Boga osim Allaha... (Muhammed, 19)</em></p></div><p>Allaha možemo spoznati na više načina, dva su ključna:</p><ol><li><p>na osnovu objave - Allah, dž.š., je objavio Kur'an u kojem su sadržani ajeti koje trebamo iščitavati,</p></li><li><p>učenjem i proučavanjem onoga što je stvorio - Allah, dž.š., je stvorio prirodu u kojoj su očigledni dokazi Njegovog postojanja: čovjek, planeta Zemlja, nebo, biljni i životinjski svijet i sve ostalo što vidimo.</p></li></ol><div class=\"arabic-card\"><p><em>Poslanik, alejhis-selam, je rekao: \"Allah ima 99 imena, 100 manje jedno, ko ih postigne ući će u Džennet.\" (Buhari)</em></p></div><p>Allaha, dž.š., vjerujemo na osnovu Njegovih svojstava, dijele se na:</p><ul><li><p>Es-sifatuz-zatijje - svojstva Allahovog bića i</p></li><li><p>Es-sifatus-subutijje - svojstva Allahovog savršenstva.</p></li></ul><p style=\"text-align: center;\"><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">ČOVJEK JE ALLAHOVO NAJSAVRŠENIJE I NAJPOTPUNIJE STVORENJE.</mark></strong></p><p>Mnogo je kur'anskih ajeta koji govore o Božijem postojanju i Njegovoj jednoći. Sura Ihlas u cijelosti govori o tome:</p><div class=\"arabic-card\"><p><em>Reci: On je Allah jedan, Allah je utočište svakom, nije rodio i rođen nije i niko Mu ravan nije. (El-Ihlas, 1-4)</em></p></div><p style=\"text-align: center;\">BOŽIJE IME U KUR'ANU JE SPOMENUTO 2698 PUTA.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"quiz\" class=\"lesson-content\">\n            <h2>KVIZ</h2><p></p><p>⭐ MAŠAALLAH! Uspješno ste savladali lekciju. Sada možete označiti naučeno!</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ponovi', this)\"> PONOVI I ODGOVORI <span class=\"section-icon\">▶</span></button>\n        <div id=\"ponovi\" class=\"lesson-content\">\n            <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">PONOVI I ODGOVORI!</span></p>\n                <ul class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Kako glasi prijevod sure Ihlas?</li>\n                    <li>Kako ćemo spoznati Uzvišenog Allaha i na osnovu čega?</li>\n                </ul>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaca', this)\"> IZABERI ZADAĆU <span class=\"section-icon\">▶</span></button>\n        <div id=\"zadaca\" class=\"lesson-content\">\n            <p class=\"lesson-text\"><span style=\"background-color: #fff9c4;\">IZABERI ZADAĆU!</span></p>\n                <ol class=\"lesson-text\" style=\"padding-left: 40px; list-style-type: decimal;\">\n                    <li>Napiši pouku iz sljedećeg ajeta:\n                        <div class=\"arabic-card\" style=\"margin-top: 10px;\">\n                            \n                            <p class=\"lesson-text\"><i>A kada te robovi Moji za Mene upitaju, Ja sam, sigurno blizu: odazivam se molbi molitelja kad Me zamoli. Zato, neka oni pozivu Mome udovolje i neka vjeruju u Mene, da bi bili na Pravome putu. (El-Bekare, 186)</i></p>\n                        </div>\n                    </li>\n                    <li style=\"margin-top: 15px;\">Napiši svoju dovu kojom moliš Allaha, dž.š.!</li>\n                </ol>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":1,"is_published":true,"kviz_pitanja":[{"answer":"Ja vjerujem u Allaha","options":["Ja vjerujem u Allaha","Ja se molim Allahu","Ja se klanjam učitelju","Ja čitam Kur'an"],"question":"Šta znači Prvi imanski šart \"Āmentu billāhi\"?"},{"answer":"99 imena","options":["50 imena","99 imena","150 imena","200 imena"],"question":"Koliko imena ima Allah prema hadisu Poslanika, alejhis-selam?"},{"answer":"Kroz objavu i kroz svemir","options":["Kroz objavu i kroz svemir","Kroz libru i mešetarenje","Kroz knjige i pjesme","Kroz trgovinu i rad"],"question":"Na koja dva ključna načina možemo spoznati Allaha?"},{"answer":"Sura Ihlas","options":["Sura Fatiha","Sura Ihlas","Sura Jasin","Sura Noor"],"question":"Koja je sura u Kur'anu posebno o Allahovoj jednoći?"},{"answer":"Čovjek","options":["Anđeli","Čovjek","Životinje","Biljke"],"question":"Koje je stvorenje Allahovog najsavršenije i najpotpunije?"}]},{"nivo":21,"slug":"sifatuz-zatijje","naslov":"Es-sifatuz-zatijje, općenito","content_html":"<div class=\"lesson-container\">\n<h1>ES-SIFATUZ-ZATIJJE, OPĆENITO</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sifatuz_zatijje.jpg\" alt=\"Es-sifatuz-zatijje\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Es-sifatuz-zatijje – Allahove osobine bića (uopćeno)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pravilne predstave o Allahu i Njegovoj veličini</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pojam \"es-sifatuz-zatijje\" i razumjeti Allahove osobine bića</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti razlikovanja Allahovih osobina od osobina stvorenja</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kakav je naš Allah? Postoje li riječi kojima Ga opisujemo? Učeni ljudi su Allahove osobine podijelili u dvije grupe – jedna od njih su es-sifatuz-zatijje. Šta to znači?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Es-sifatuz-zatijje su Allahove osobine bića, tj. one koje pripadaju samoj Allahovoj suštini i bez kojih On ne bi bio Allah.</p><p>Allah ima šest takvih osobina: <strong>Vudžud</strong> (postojanje), <strong>Kidem</strong> (vječnost u prošlosti), <strong>Beka</strong> (vječnost u budućnosti), <strong>Vahdanijjet</strong> (jedinstvenost), <strong>Muhalefetun lil-havadis</strong> (različitost od stvorenja), <strong>Kijam binefsihi</strong> (samoopstojnost).</p><p>Te osobine pripadaju samo Allahu i nijedno stvorenje ih nema u istom obliku.</p><p>Postupak: Na tabli pišem listu osobina sa kratkim objašnjenjem za svaku. Učenici prepisuju i ponavljaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju šest osobina bića. Razgovor: po čemu se Allah razlikuje od svega što je stvorio.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":2,"is_published":true,"kviz_pitanja":[{"answer":"Šest svojstava","options":["Tri svojstva","Šest svojstava","Devet svojstava","Dvanaest svojstava"],"question":"Koliko ima es-sifatuz-zatijje, svojstava Allahovog bića?"},{"answer":"Allah je oduvijek","options":["Allah je zauvijek","Allah je Jedan","Allah je oduvijek","Allah nikome ne sliči"],"question":"Šta znači Kidem kao svojstvo Allaha?"},{"answer":"Na dva dijela","options":["Na tri dijela","Na četiri dijela","Na dva dijela","Na pet dijelova"],"question":"Na koliko dijelova se dijele Allahova svojstva?"},{"answer":"Njegovu veličinu i savršenost","options":["Njegovu ljubav prema nama","Njegovu veličinu i savršenost","Njegove zapovijedi","Njegove kazne"],"question":"Što svojstva Allaha nama objašnjavaju?"},{"answer":"Allah je zauvijek","options":["Allah je Jedan","Allah je postojan","Allah je zauvijek","Allah se ne mijenja"],"question":"Šta znači svojstvo Beka?"}]},{"nivo":21,"slug":"sifatus-subutijje","naslov":"Es-sifatus-subutijje, općenito","content_html":"<div class=\"lesson-container\">\n<h1>ES-SIFATUS-SUBUTIJJE, OPĆENITO</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sifatus_subutijje.jpg\" alt=\"Es-sifatus-subutijje\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Es-sifatus-subutijje – Allahove osobine svojstva (uopćeno)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o Allahovim savršenim svojstvima i Njegovoj uzvišenosti</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti osam Allahovih osobina svojstva (es-sifatus-subutijje)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje sposobnosti spominjanja Allaha kroz Njegova svojstva</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, juče smo učili o Allahovim osobinama bića. Danas ćemo o drugoj grupi – osobinama svojstva. To su osobine kojima Allah djeluje i koje vidimo u svemu oko nas.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Es-sifatus-subutijje su Allahove osobine svojstva. Ima ih osam.</p><p>To su: <strong>Hajat</strong> (život), <strong>Ilm</strong> (znanje), <strong>Sem‘</strong> (sluh), <strong>Besar</strong> (vid), <strong>Iradet</strong> (volja), <strong>Kudret</strong> (moć), <strong>Kelam</strong> (govor), <strong>Tekvin</strong> (stvaranje).</p><p>Allah je živ vječno, sve zna, sve čuje, sve vidi, sve hoće, sve može, govori (kroz Kur’an i objavu), i sve stvara.</p><p>Postupak: Pišem osobine na tabli; uz svaku dajem primjer iz života kako je vidimo (npr. Allah čuje i tihu dovu, Allah vidi šta radimo i nasamo).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju osam osobina svojstva. Razgovor: kako nas svijest o Allahovim osobinama čini boljim ljudima.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":3,"is_published":true,"kviz_pitanja":[{"answer":"Osam svojstava","options":["Pet svojstava","Osam svojstava","Deset svojstava","Tri svojstva"],"question":"Koliko ima svojstava Es-sifatus-subutijje?"},{"answer":"'Ilm","options":["Hajat","'Ilm","Sem'","Besar"],"question":"Koje od navedenih svojstava znači 'Znanje'?"},{"answer":"Allah sve čuje","options":["Allah sve vidi","Allah sve čuje","Allah sve zna","Allah je svemoćan"],"question":"Šta znači svojstvo 'Sem'' kod Allaha, dž.š.?"},{"answer":"Hajat","options":["Kudret","Kelam","Hajat","Iradet"],"question":"Koje svojstvo govori o Allahovu vječnom životu?"},{"answer":"Allah je svemoćan","options":["Allah sve voli","Allah je svemoćan","Allah sve čuje","Allah sve zna"],"question":"Šta znači svojstvo 'Kudret'?"}]},{"nivo":21,"slug":"ve-melaikethi","naslov":"Drugi imanski šart - ve melāiketihī","content_html":"<div class=\"lesson-container\">\n<h1>DRUGI IMANSKI ŠART - VE MELAIKETIHI</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ve_melaiketihi.jpg\" alt=\"Ve melaiketihi\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Drugi imanski šart – ve melāiketihī (Vjerovanje u meleke)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti da nas meleki čuvaju i bilježe naša djela</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta su meleki, koje vrste postoje i njihove glavne funkcije</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje takvaluka kroz svijest o stalnom prisustvu meleka</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li nas neko gleda kad smo sami u sobi? Allah, ali i Njegovi čuvari – meleki. Ko su oni, šta rade?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Meleki su Allahova bića stvorena od svjetla (nūra). Pokorni su Allahu i nikada ne griješe.</p><p>Mi ih ne vidimo, ali oni postoje i izvršavaju Allahove naredbe.</p><p>Najpoznatiji meleki: <strong>Džibril</strong> (donosi objavu), <strong>Mikāil</strong> (raspoređuje opskrbu), <strong>Israfil</strong> (puhat će u sūr), <strong>Azrail</strong> (uzima duše), <strong>Kirāmen Kātibīn</strong> (pišu naša djela), <strong>Munker i Nekīr</strong> (ispituju u kaburu).</p><p>Vjerovati u meleke znači biti uvjeren u njihovo postojanje i u to da rade ono što im Allah naredi.</p><p>Razgovor: Kako se ponaša onaj ko zna da meleki bilježe svako njegovo djelo?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju neke meleke i njihove funkcije. Zaključak: kad znamo da nas meleki čuvaju i pišu naša djela, lakše ćemo biti dobri.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\"> NEVIDLJIVI ČUVARI <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Draga djeco, jeste li znali da nismo sami na ovom svijetu? Uzvišeni Allah stvorio je i posebna, nevidljiva bića koja nas prate, štite i bez prestanka veličaju Njegovo ime. Ta bića nikada ne spavaju, ne jedu i nikada ne griješe. Stvorena su od čiste svjetlosti.</p><p>Danas ćemo naučiti ko su oni, kako se zovu i koja su njihova važna zaduženja. Neki od njih zaduženi su za kišu i vjetar, neki donose Objavu, a neki čak zapisuju svako naše dobro i loše djelo. Jeste li spremni upoznati meleke?</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\"> NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p><em>Allah, dž.š., kaže: O vjernici, vjerujte u Allaha, i Poslanika Njegova, i u Knjigu koju On Svome Poslaniku objavljuje, i u Knjigu koju je objavio prije. A onaj ko ne bude vjerovao u Allaha, i u meleke Njegove, i u knjige Njegove, i u poslanike Njegove, i u onaj svijet - daleko je zalutao. (En-Nisa', 136)</em></p></div><p>Drugi imanski šart glasi:<br><strong>VE MELAIKETIHI</strong> - I vjerujem Allahove meleke.</p><p>Meleki su nevidljiva duhovna bića, stvoreni od svjetlosti i u stalnoj su službi i pokornosti Allahu, dž.š. Oni ne jedu, ne piju, ne spavaju, nisu ni muškog ni ženskog roda.</p><p>Allah, dž.š., je stvorio meleke kao bezgrješna bića samo da bi Ga obožavali i ibadet Mu činili. Meleka ima mnogo, o njima znamo samo ono što je objavljeno u Kur'anu ili što je rečeno u hadisima Muhammeda, alejhis-selam</p><p>Meleki imaju zaduženja koja izvršavaju bez pogovora.<br><strong>Imena nekih meleka i njihove dužnosti:</strong></p><ul><li><p><strong>DŽIBRIL (DŽEBRAIL)</strong> - Dostavljao je Božije objave svim Božijim poslanicima.</p></li><li><p><strong>MIKAIL</strong> - Zadužen je za prirodne pojave.</p></li><li><p><strong>ISRAFIL</strong> - Zadužen je da puhanjem u sur najavi Kijametski i Sudnji dan.</p></li><li><p><strong>MUNKIR I NEKIR</strong> - Zaduženi su za ispitivanje osoba u kaburu.</p></li><li><p><strong>KIRAMUN-KATIBUN</strong> - Prate osobe i pišu njihova dobra i loša djela.</p></li><li><p><strong>MELEKUL-MEVT (AZRAIL)</strong> - Rastavlja dušu od tijela u času smrti.</p></li><li><p><strong>RIDVAN</strong> - Zadužen je za Džennet, čuvar Dženneta.</p></li><li><p><strong>MALIK</strong> - Zadužen za Džehennem, čuvar Džehennema.</p></li></ul><p>Meleki nisu jedina nevidljiva bića, Allah je stvorio i džine i šejtane. Džini mogu biti dobri i loši, vjernici i nevjernici i pristalice različitih vjera. Shodno svojim potrebama i osobinama slični su ljudima.</p><p>Nepokorni džini zovu se šejtani, a njihov vođa je Iblis koji je prvi odbio biti poslušan Allahu, dž.š. Šejtani ljudima donose loše misli i navode ih da čine loša djela.</p><div class=\"info-card\"><p style=\"text-align: center;\">ZAPAMTI!</p><p style=\"text-align: center;\">Allahovu zaštitu od prokletog šejtana tražimo riječima:<br><strong>E'UZU BILLAHI MINEŠ-ŠEJTANIR-RADŽIM</strong>,<br>što znači,<br>TRAŽIM ALLAHOVU ZAŠTITU OD PROKLETOG ŠEJTANA</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('quiz', this)\"> PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"quiz\" class=\"lesson-content\">\n            <h2>KVIZ</h2><p></p><p>⭐ MAŠAALLAH! Uspješno ste savladali lekciju. Sada možete označiti naučeno!</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('razgovor', this)\"> RAZGOVOR S MUALLIMOM <span class=\"section-icon\">▶</span></button>\n        <div id=\"razgovor\" class=\"lesson-content\">\n            <ul><li><p><em>Razmišljaju li ljudi da se svako njihovo djelo piše i da će za loša djela odgovarati?</em></p></li><li><p><em>Zašto je važno da smo toga svjesni?</em></p></li></ul><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('zadaca', this)\"> ZA DOMAĆI ZADATAK <span class=\"section-icon\">▶</span></button>\n        <div id=\"zadaca\" class=\"lesson-content\">\n            <p>Napiši u svoju mektebsku svesku imena meleka koja smo naučili u lekciji i objasni koja su njihova zaduženja?</p><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":4,"is_published":true,"kviz_pitanja":[{"answer":"Od svjetlosti","options":["Od vode","Od svjetlosti","Od zemlje","Od zraka"],"question":"Od čega su meleki stvoreni?"},{"answer":"Obožavati Allaha i činiti ibadet","options":["Jesti i piti","Obožavati Allaha i činiti ibadet","Spavati cijeli dan","Biti muškog roda"],"question":"Koja je glavna svrha meleka?"},{"answer":"Džibril","options":["Mikail","Israfil","Džibril","Azrail"],"question":"Koji meleka dostavljar Božije objave poslanicima?"},{"answer":"Iblis","options":["Malik","Iblis","Ridvan","Munkir"],"question":"Ko je vođa nepokornih džina - šejtana?"},{"answer":"Prate i pišu dobra i loša djela","options":["Čuvaju Džehennem","Prate i pišu dobra i loša djela","Ispituju u kaburu","Rastvaraju dušu od tijela"],"question":"Šta čine Kiramun-katibun meleki?"}]},{"nivo":21,"slug":"ve-kutubihi","naslov":"Treći imanski šart - ve kutubihī","content_html":"<div class=\"lesson-container\">\n<h1>VE KUTUBIHI – 3. IMANSKI ŠART</h1>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Treći imanski šart – ve kutubihī (Vjerovanje u objavljene knjige)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Kur’anu i poštovanja prema svim Allahovim objavama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti koje su sve knjige Allah objavio i kome</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike čitanja i učenja iz Kur’ana</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koju knjigu kao muslimani najviše volimo? Kur’an. A znate li da je Allah objavio i druge knjige prije Kur’ana? Hajde da naučimo o tome.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah je svojim poslanicima slao knjige – upute ljudima.</p><p>Četiri velike objavljene knjige su: <strong>Tevrat</strong> (Mūsau, a.s.), <strong>Zebūr</strong> (Dāvudu, a.s.), <strong>Indžil</strong> (Īsau, a.s.) i <strong>Kur’an</strong> (Muhammedu, a.s.).</p><p>Pored ovih, postoje i listovi (suhuf) koji su objavljeni nekim poslanicima (npr. Ibrāhīmu, a.s., i Mūsau, a.s.).</p><p>Sve prijašnje knjige su tokom vremena izmijenjene od strane ljudi. Kur’an je posljednja Allahova knjiga, sačuvana je u izvornom obliku do Sudnjega dana.</p><p>Vjerovati u objavljene knjige znači biti uvjeren da su one od Allaha i da je Kur’an konačna i potpuna uputa.</p><p>Razgovor: Zašto se Kur’an često uči i čuva napamet?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju četiri velike Allahove knjige i njihove poslanike. Razgovor o važnosti svakodnevnog učenja Kur’ana.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Zamislite da imate prijatelja koji živi daleko i s kojim se ne možete sresti, ali vam šalje pisma puna savjeta i uputa koje vam pomažu da vodite sretan život. Tako nam je i Allah, dž.š., slao Svoje knjige – pisma upute – kroz cijelu ljudsku povijest od Adema, a.s., do Muhammeda, a.s.</p><p>On je naš Stvoritelj i najbolje zna šta je za nas najbolje. Izsvoje milosti i ljubavi prema nama nije nas ostavio da lutamo, nego nam je preko svojih poslanika slao svoje objave.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Treći imanski šart glasi: <strong>VE KUTUBIHI – I vjerujem u Allahove knjige.</strong></p><p>Allahove knjige su objave koje je Uzvišeni Allah slao Svojim poslanicima preko meleka Džibrila. U njima su sadržane upute, savjeti i propisi o životu i radu ljudi. Dužnost svakog muslimana i muslimanke je da vjeruje u Allahove knjige koje se dijele na velike – kitabe i male – suhufe.</p><p>Četiri su velika kitaba:</p><ol><li><p><strong>TEVRAT</strong> – objavljen Musau, alejhis-selam,</p></li><li><p><strong>ZEBUR</strong> – objavljen Davudu, alejhis-selam,</p></li><li><p><strong>INDŽIL</strong>– objavljen Isau, alejhis-selam, i</p></li><li><p><strong>KUR'AN</strong> – objavljen Muhammedu, alejhis-selam.</p></li></ol><p>U Kur'anu se spominju suhufi Ibrahima, a.s., i Musa, a.s. Ibn Hibban navodi u svom <em>Sahihu</em>:</p><blockquote><p>\"Objavio je Šitu pedeset listova, Idrisu trideset, Ibrähimu deset i Musau - prije Tevrata - deset listova.\"</p></blockquote><p>Dakle, suhufi su objavljeni sljedecim poslanicima:</p><ul><li><p>Šitu, alejhis-selam – 50 suhufa,</p></li><li><p>Idrisu, alejhis-selam – 30 suhufa,</p></li><li><p>Ibrahimu, alejhis-selam – 10 suhufa i</p></li><li><p>Musau, alejhis-selam – 10 suhufa.</p></li></ul><p><strong>KUR'AN</strong></p><p>Kur'an je posljednja Allahova objava objavljena posljednjem Allahovom poslaniku Muhammedu, alejhis-selam Objava Kur'ana je započela u Lejletul-kadru, u mjesecu ramazanu 610. godine, u pećini Hira na brdu Nur. Objavljivanje Kur'ana trajalo je 23 godine – 13 godina u Mekki i 10 u Medini. Kur'an sadrži 114 sura i 6236 ajeta. Podijeljen je na 30 džuzova.</p><p>Kur'an se u odnosu na prethodne objave razlikuje u sljedećem:</p><ul><li><p>sačuvan je u originalu,</p></li><li><p>objavljen je cijelom čovječanstvu,</p></li><li><p>potvrđuje sve prethodne Allahove objave i</p></li><li><p>posljednja je Allahova objava.</p></li></ul><div class=\"info-box\"><p style=\"text-align: center;\"><strong>LIJEPO JE ZNATI ZNAČENJE RIJEČI:</strong> <strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Harf</mark></strong> – slovo, <strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Ajet</mark></strong> – rečenica, <strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Sura</mark></strong> – poglavlje, <strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Džuz</mark></strong> – dio od 20 stranica.</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">MINI KVIZ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <p>IZABERI ZADAĆU!</p><ol><li><p>Uradi pano na kome ćeš predstaviti posljednju Allahovu objavu – Kur'an!</p></li><li><p>Od 114 sura pronađi i nauči imena posljednjih 10 sura redoslijedom na arapskom i na bosanskom!</p></li><li><p>Pokazat ću muallimu/mi i roditeljima da sam vrijedan/na i uradit ću oba zadatka.</p></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":5,"is_published":true,"kviz_pitanja":[{"answer":"Ve kutubihi - vjerujem u Allahove knjige","options":["Ve kutubihi - vjerujem u Allahove knjige","Ve rusilihi - vjerujem u Allahove poslanike","Ve bi-llahi - vjerujem u Allaha","Ve bi-yaumil-akhiri - vjerujem u Dan sudnjega"],"question":"Koji je treći imanski šart?"},{"answer":"Tevrat, Zebur, Indžil i Kur'an","options":["Tevrat, Zebur, Indžil i Kur'an","Tevrat, Zabur, Tora i Biblija","Indžil, Kur'an, Talmud i Tora","Zebur, Indžil, Šaria i Sunnah"],"question":"Koliko je četiri velika Allahova kitaba?"},{"answer":"Muhammedu, alejhis-selam","options":["Muhammedu, alejhis-selam","Musau, alejhis-selam","Davudu, alejhis-selam","Isau, alejhis-selam"],"question":"Kome je objavljen Kur'an?"},{"answer":"114 sura i 6236 ajeta","options":["114 sura i 6236 ajeta","120 sura i 7000 ajeta","100 sura i 5000 ajeta","114 sura i 5000 ajeta"],"question":"Koliko je surah i ajeta u Kur'anu?"},{"answer":"23 godine - 13 u Mekki i 10 u Medini","options":["23 godine - 13 u Mekki i 10 u Medini","20 godina - 10 u Mekki i 10 u Medini","25 godina - 15 u Mekki i 10 u Medini","23 godine - 10 u Mekki i 13 u Medini"],"question":"Koliko je godina trajalo objavljivanje Kur'ana?"}]},{"nivo":21,"slug":"ve-rusulihi","naslov":"Četvrti imanski šart - ve rusulihī","content_html":"<div class=\"lesson-container\">\n<h1>VE RUSULIHI – 4. IMANSKI ŠART</h1>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Četvrti imanski šart – ve rusulihī (Vjerovanje u poslanike)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema svim Allahovim poslanicima, posebno prema Muhammedu, a.s.</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam poslanstva i ulogu poslanika u životu ljudi</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike slijeđenja sunneta Poslanika, a.s.</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako bismo znali kako trebamo živjeti da nismo imali poslanike? Allah je iz milosti svome stvorenju slao poslanike. Šta o njima znamo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Poslanici (resūli) su odabrani ljudi koje je Allah slao da poučavaju ljude vjeri i pravom putu.</p><p>U Kur’anu se poimence spominje 25 poslanika, ali ih je bilo mnogo više – Allah najbolje zna njihov broj.</p><p>Prvi poslanik je bio Adem, a.s., a posljednji Muhammed, a.s. – pečat svih poslanika.</p><p>Pet velikih poslanika (Ulul-‘azm) su: Nūh, Ibrāhīm, Mūsa, Īsa i Muhammed (alejhimus-selam).</p><p>Vjerovati u poslanike znači vjerovati da su svi oni govorili istinu, pozivali u jednog Allaha i pokazivali ljudima pravi put.</p><p>Razgovor: Po čemu slijedimo Muhammeda, a.s., u svakodnevnom životu?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju neke poslanike. Zaključak: poslanici su naš najljepši uzor; slijedimo ih kroz njihova djela i poruke.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Zamisli da živiš u gradu u kome niko ne zna kako se ponašati, nema pravila ni uputa. Kako bi izgledao takav grad? Haos, zar ne? Allah, dž.š., je iz Svoje milosti uvijek slao poslanike koji su ljude učili kako živjeti i kako slijediti Pravi put.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p>Allah, dž.š., kaže: <em>O vjernici, vjerujte u Allaha i Poslanika Njegova, i u Knjigu koju On Svome Poslaniku objavljuje, i u Knjigu koju je objavio prije</em>. <strong>(En-Nisa', 136)</strong></p></div><p>Četvrti imanski šart glasi: <strong>Ve rusulihi – I vjerujem Allahove poslanike.</strong><br>Allahovi poslanici su odabrani ljudi kojima je Allah, dž.š., slao Svoje objave. Allahovom, dž.š., voljom su odgajani i poučeni za misiju poslanstva.<br>Dužnost svakog muslimana i muslimanke je da vjeruje Božije poslanike. Prvi čovjek na Zemlji adem, a.s., je bio ujedno i prvi Božiji poslanik. To znači da je Allah, dž.š., poučio Adema, a.s., a preko njega i ostale ljude kako da žive na ovome svijetu. Allah, dž.š., je nakon Adema, a.s., povremeno ljudima slao poslanike koji su imali zadatak da prenose Njegove objave. Oni su ljudima pojašnjavali objave i pozivali ih na dobro a odvraćali od zla.<br>Božijih poslanika bilo je mnogo – u predajama se spominje broj od 124 hiljade. U Kur'anu se spominje 25 poslanika: Adem, Idris, Nuh, Hud, Salih, Ibrahim, Ishak, Ismail, Lut, Jakub, Jusuf, Ejub, Šu'ajb, Musa, Harun, Zulkifl, Davud, Sulejman, Iljas, El-Jesa, Junus, Zekerija, Jahja, Isa i Muhammed, alejhis-selam Među njima najodabraniji su: Nuh, Ibrahim, Musa, Isa i Muhammed, alejhis-selam – jednim imenom nazvani <strong>Ulul-'azm</strong> - Odlučni poslanici.</p><p>Isto tako iz Kurʼana saznajemo da je svaki narod imao svoga poslanika. Iako su bili Božiji poslanici, oni su živjeli skromno od svoga rada i truda. Naprimjer: Muhammed, a.s., je u djetinjstvu bio pastir a kasnije trgovac. Davud, a.s., je pravio pancire; Sulejman, a.s., je bio graditelj raznih građevina; Isa, a.s., je bio tesar; Idris, a.s., je bio krojač.</p><div class=\"info-box\"><p><strong>Među Božijim poslanicima bilo je i srodnika:</strong></p><ul><li><p>Ibrahim, a.s., je bio otac Ismailu, a.s., i Ishaku, a.s.</p></li><li><p>Ibrahim, a.s., je bio amidža Lutu, a.s.</p></li><li><p>Ishak, a.s., je bio otac Jakubu, a.s., a</p></li><li><p>Jakub, a.s., je bio otac Jusufu, a.s.</p></li><li><p>Zekerija je bio otac Jahjau, a.s.</p></li><li><p>Davud, a.s., je bio otac Sulejmanu, a.s.</p></li><li><p>Musa, a.s., i Harun, a.s., su bili braća</p></li><li><p>Jahja, a.s., i Isa, a.s., su bili tetići</p></li></ul></div><p>Posljednji Allahov poslanik je Muhammed, alejhis-selam, od oca Abdullaha i majke Amine. Otac mu je umro dva mjeseca prije njegovog rođenja a majka kada je imao šest godina. Nakon smrti roditelja brigu o njemu preuzeo je djed Abdulmutalib, a nakon djeda amidža Ebu Talib. U četrdesetoj godini života postao je poslanik i Allah, dž.š., mu je počeo objavljivati Kur'an. Trinaeste godine od početka objave učinio je Hidžru – preselio iz Mekke u Medinu. Na ahiret je preselio 632. godine u svojoj 63. godini života.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('section-1774971447364', this)\">MUHAMMED, A.S. <span class=\"section-icon\">▶</span></button>\n        <div id=\"section-1774971447364\" class=\"lesson-content\">\n            <h3><strong>Muhammed, a.s. – posljednji i najodabraniji Allahov poslanik (571-632)</strong></h3><p>Posljednji Allahov poslanik je Muhammed, a.s., od oca Abdullaha i majke Amine. Otac mu je umro dva mjeseca prije njegovog rođenja a majka kada je imao šest godina. Nakon smrti roditelja brigu o njemu preuzeo je djed Abdulmutalib, a nakon djeda amidža Ebu Talib. Kod amidže je ostao do svoje 25. godine kada se oženio uglednom udovicom hazreti Hatidžom. U četrdesetoj godini života postao je poslanik i Allah, dž.š., mu je počeo objavljivati Kurʼan. U početku, tri godine je tajno pozivao u islam a potom, u daljem toku poslaničke misije, pozivanje je bilo javno. Trinaeste godine od početka objave sa muslimanima je učinio Hidžru – preselio je iz Meke u Medinu. Na ahiret je preselio 632. godine u svojoj 63. godini života.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">IZABERI ZADAĆU <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol><li><p>Nauči imena 25 poslanika spomenutih u Kur'anu!</p></li><li><p>Napiši i nauči imena Božijih poslanika koja znaš a počinju sa slovom \"I\" i \"J\"!</p></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":6,"is_published":true,"kviz_pitanja":[{"answer":"Vjerujem Allahove poslanike","options":["Vjerujem u Allaha","Vjerujem Allahove poslanike","Vjerujem u anđele","Vjerujem u Sudnji dan"],"question":"Što znači četvrti imanski šart 'Ve rusulihî'?"},{"answer":"25 poslanika","options":["15 poslanika","25 poslanika","50 poslanika","100 poslanika"],"question":"Koliko poslanika se spominje u Kur'anu?"},{"answer":"Nuh, Ibrahim, Musa, Isa i Muhammed","options":["Adem, Idris, Nuh, Hud i Salih","Nuh, Ibrahim, Musa, Isa i Muhammed","Jusuf, Ejub, Šu'ajb, Musa i Harun","Davud, Sulejman, Iljas, El-Jesa i Junus"],"question":"Koji su poslanici zvani Ulul-'azm?"},{"answer":"U 40. godini života","options":["U 40. godini života","U 13. godini života","U 63. godini života","U 25. godini života"],"question":"U kojoj godini je Muhammed, alejhis-selam, učinio Hidžru?"},{"answer":"Pravio je pancire","options":["Bio je pastir","Pravio je pancire","Bio je trgovac","Bio je krojač"],"question":"Koji je posao imao Davud, alejhis-selam?"}]},{"nivo":21,"slug":"vel-jevmil-ahiri","naslov":"Peti imanski šart - vel-jevmil āhiri","content_html":"<div class=\"lesson-container\">\n<h1>VEL-JEVMIL ÃHIRI – 5. IMANSKI ŠART</h1>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Peti imanski šart – vel-jevmil āhiri (Vjerovanje u Sudnji dan)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje takvaluka i odgovornosti za vlastita djela kroz svijest o ahiretu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je Sudnji dan, šta se na njemu dešava i šta su Džennet i Džehennem</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Motiviranje učenika na činjenje dobrih djela i izbjegavanje grijeha</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li ovaj svijet traje vječno? Hoće li nešto biti poslije njega? Allah u Kur’anu obavještava o Sudnjem danu. Šta se tada dešava?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sudnji dan (jevmu-l-āhir) je dan kada će ovaj svijet prestati postojati i kada će svi ljudi biti proživljeni.</p><p>Israfil će puhnuti u sūr – sve će umrijeti, pa drugi puhnut će opet u sūr i ljudi će ustati iz kabura.</p><p>Bit će postavljena vaga (mizan) i svaki čovjek dobit će svoju knjigu djela. Ko bude imao više dobrih djela, ići će u Džennet, a ko bude imao više loših, u Džehennem.</p><p>Džennet je vječna nagrada – vrtovi, rijeke, sve što duša poželi i susret sa Allahom.</p><p>Džehennem je vječna kazna – vatra, patnja i odvojenost od Allahove milosti.</p><p>Vjerovati u Sudnji dan motiviše čovjeka da čini dobro i izbjegava zlo.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razmišljaju: šta od onoga što danas radimo bi nam donijelo dobra djela? Zaključak: svaki dan nam je prilika da skupimo dobra djela za ahiret.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Svaka škola ima kraj – ispit, ocjene, svjedodžbu. Naš život na ovom svijetu je poput škole, a Sudnji dan je najveći ispit koji nas sve čeka. Peti imanski šart je vjerovanje u Sudnji dan, i to je jedan od najvažnijih temelja islamskog vjerovanja. Dunjaluk – ovaj svijet – je prolazan, a ahiret – budući svijet – je vječan. Smrt nije kraj, nego samo prelazak u drugi oblik života: iz kabura, kroz proživljenje, do vage dobrih i loših djela, pa do Dženneta ili Džehennema. Na Sudnjem danu svako će sam odgovarati za svoja djela – niko neće moći nositi tuđa bremena. Dobra vijest je da onaj ko ima više dobrih djela ide u Džennet Allahovom milošću, a vjernici koji budu kažnjeni na kraju će izaći iz Džehennema. Ova lekcija treba da nas motivira da svaki dan činimo što više dobrih djela, jer meleki sve bilježe.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Peti imanski šart glasi: <strong>Vel-jevmil ahiri – I vjerujem u Sudnji dan</strong>.</p><p>Nakon što smo potvrdili vjerovanje u Allaha, dž.š., Njegove meleke, Njegove knjige, Njegove poslanike, naša dužnost je da vjerujemo u Sudnji dan. Vjerovanje u Allaha, dž.š., i Sudnji dan su dva imanska šarta najčešće spominjana u Kurʼanu ‒ jedan nakon drugog.</p><p>Uzvišeni Allah je stvorio dva svijeta: ovaj svijet koji se zove dunjaluk i budući svijet ahiret. Ovaj svijet je prolazan, a budući svijet je vječan. Na ovom svijetu živimo, radimo i dunjalučki život završavamo smrću. Smrt nije kraj života, nego samo promjena načina života. Na budućem svijetu bit ćemo proživljeni i nakon toga živjet ćemo vječno.</p><p>Sudnjem danu prethodi: </p><ul><li><p>smrt i boravak u berzahu – zagrobni život, </p></li><li><p>Israfilovo puhanje u sur i propast ovoga svijeta, </p></li><li><p>Israfilovo drugo puhanje u sur i proživljenje, </p></li><li><p>okupljanje na mjestu konačnog suda </p></li><li><p>pojedinačno primanje knjiga u kojima su ispisana naša dobra i loša djela.</p></li></ul><div class=\"arabic-card\"><p>Allah, dž.š., kaže: Onaj ko bude uradio koliko trun dobra, vidjet će ga, a onaj ko bude uradio koliko trun zla, vidjet će ga. (Ez-Zilzal, 7-8)</p></div><p>Na Sudnjem danu Allah, dž.š., će suditi ljudima za njihova dobra i loša djela. Svaka osoba pojavit će se pojedinačno radi polaganja računa pred Allahom, dž.š. Čovjekova djela bit će stavljena na vagu, pa u koga pretegnu dobra djela, njega će Allah, dž.š., nagraditi i njegovo mjesto će, Allahovom milošću, biti u Džennetu. U koga pretegnu loša djela, bit će kažnjen, a njegovo mjesto bit će u Džehennemu iz kojeg će vjernici, Allahovom milošću, kasnije biti izvedeni.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">MINI KVIZ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PONOVI I ODGOVORI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol><li><p>Šta prethodi Sudnjem danu?</p></li><li><p>Kome će se suditi na Sudnjem danu i zašto?</p></li><li><p>Tokom života na dunjaluku meleki pišu naša dobra i loša djela koja radimo. Napiši listu dobrih djela koje svakodnevno radiš u životu.</p></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":7,"is_published":true,"kviz_pitanja":[{"answer":"Vjerovanje u Sudnji dan","options":["Vjerovanje u Sudnji dan","Vjerovanje u Allaha","Vjerovanje u Kuran","Vjerovanje u anđele"],"question":"Šta je peti imanski šart?"},{"answer":"Dva svijeta","options":["Tri svijeta","Četiri svijeta","Dva svijeta","Pet svjetova"],"question":"Koliko svjetova je Allah, dž.š., stvorio?"},{"answer":"Smrt, berzah i Israfilovo puhanje u sur","options":["Samo smrt","Smrt, berzah i Israfilovo puhanje u sur","Samo Israfilovo puhanje","Samo okupljanje ljudi"],"question":"Šta prethodi Sudnjem danu?"},{"answer":"U Džehennemu","options":["U Džennetu","U Džehennemu","Na zemlji","U svemiru"],"question":"Gdje će biti mjesto onih koji imaju loša djela?"},{"answer":"Prema njihovim dobrima i lošim djelima","options":["Prema njihovom bogatstvu","Prema njihovim dobrima i lošim djelima","Prema njihovoj boji kože","Prema njihovoj porodici"],"question":"Kako će Allah, dž.š., suditi ljudima na Sudnjem danu?"}]},{"nivo":21,"slug":"ve-bil-kaderi","naslov":"Šesti imanski šart - ve bil-kaderi","content_html":"<div class=\"lesson-container\">\n<h1>VE BIL-KADERI – 6. IMANSKI ŠART</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ve_bil_kaderi.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Šesti imanski šart – ve bil-kaderi (Vjerovanje u Allahovo određenje)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje strpljenja, povjerenja u Allaha i prihvatanja Njegovog određenja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam kadera (Allahovog određenja) i da je sve od Allaha</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje pouzdanja u Allaha (tevekkul) i strpljenja u svim životnim okolnostima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li se nešto u svemiru dešava bez Allahovog znanja? Ne! Allah sve zna unaprijed i sve određuje. To zovemo kader. Kako da to razumijemo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kader znači da Allah, dž.š., zna sve što će biti i da je sve određeno Njegovom mudrošću.</p><p>Vjerovanje u kader uči nas da se ono što nas zadesi (i dobro i loše) dešava sa Allahovim znanjem.</p><p>Ali to ne znači da smo bez slobode izbora! Allah nam je dao razum i volju – mi biramo svoja djela i odgovorni smo za njih.</p><p>Kad nas zadesi nešto teško, kažemo: <em>\"Inna lillāhi ve innā ilejhi rādži‘ūn\"</em> – Allahovi smo i Njemu se vraćamo. Strpimo se i tražimo Njegovu pomoć.</p><p>Kad nas zadesi nešto lijepo, zahvaljujemo: <em>\"El-hamdu lillāh\"</em>.</p><p>Razgovor: Kako se ponaša musliman u nesreći? A kako u radosti?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju primjere strpljenja i zahvalnosti. Zaključak: kad imamo iman u kader, srce nam je smireno.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Ima li smisla u svemu što nam se dešava? Zašto se neke stvari dešavaju, a druge ne? Islam daje odgovor kroz 6. imanski šart – vjerovanje u Allahovo određenje (kader). Sve je u Allahovoj odredbi, ali nas to ni na koji način ne ograničava u postupcima. Mi imamo slobodnu volju i odgovorni smo za svoja djela.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Šesti imanski šart glasi: <strong>VE BIL-KADERI HAJRIHI VE ŠERRIHI MINELLAHI TE‘ALA – I vjerujem da sve što se događa, biva s Allahovom voljom i određenjem</strong>.</p><p>Allahovu volju i određenje treba razumije- vati na sljedeći način: Allah, dž.š., je Stvori- telj svega. On određuje kako, kada, gdje i šta će se dogoditi. Šta Allah hoće, to biva, a šta neće, to ne može biti.</p><p>Kada kažemo da vjerujemo u Božije određenje, u tom slučaju vjerujemo:</p><p><strong>• da je sve davno zapisano u Levhi-mahfuzu,</strong></p><p><strong>• da se ništa ne dešava mimo Njegovog znanja,</strong></p><p><strong>• da se ništa ne dešava mimo Allahovog određenja.</strong></p><p>U Levhi-mahfuzu ‒ Pomno čuvanoj ploči, zapisano je sve što se dešava na nebesima i Zemlji. Isto tako, u Levhi-mahfuzu je zapisana sudbina svakog čovjeka i svih ostalih dešavanja koja mogu utjecati na ljudsku sudbinu. Mimo zapisanog neće se niti se bilo šta može dogoditi.</p><p>Čovjeku je prije njegovog rođenja određeno kada i gdje će se roditi, ko će mu biti roditelji, kojeg će spola biti, kakva će mu sudbina biti, kolika će mu nafaka biti, kada će i gdje umrijeti. Čovjek nije odgovoran za spomenuto. Njegova odgovornost isključivo se odnosi na izbor djela koja čini. On je potpuno slobodan da odabere hoće li živjeti u skladu sa Božijim propisima ili neće. Ostavljeno mu je na volju hoće li izvršavati islam- ske dužnosti ili neće. Isto tako slobodan je da odabere hoće li raditi dobro ili zlo. Zbog slobodne volje čovjek je odgovoran za svoja djela i na ovom i budućem svijetu.</p><div class=\"arabic-card\"><p>Poslanik, a.s., je rekao: “Ti nećeš osjetiti slast imana sve dok ne budeš vjerovao da sve ono što te zadesilo, nije te moglo mimoići i sve ono što te mimoišlo, nije te moglo snaći.” (Muslim)</p></div><p>Mi znamo šta je naređeno, a ne znamo šta je određeno i po naređenom trebamo postupati.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <p>1. Koja dobra djela želiš učiniti, a nisi imao/ imala priliku do sada?</p><p>2. Na šta te asocira riječ “SLOBODA” kada su u pitanju osobe koje nisu svjesne Božijeg postojanja – na koji način one koriste slobodu?</p><p>3. Na šta te asocira riječ “SLOBODA” kada su u pitanju osobe koje su svjesne Božijeg postojanja – na koji način oni slobodu koriste?</p><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('section-1774974489106', this)\">RAZGOVOR S MUALLIMOM <span class=\"section-icon\">▶</span></button>\n        <div id=\"section-1774974489106\" class=\"lesson-content\">\n            <p>Mi znamo šta nam je naređeno, ali ne znamo šta je određeno.</p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":8,"is_published":true,"kviz_pitanja":[{"answer":"Pomno čuvana ploča gdje je sve zapisano","options":["Pomno čuvana ploča gdje je sve zapisano","Knjiga koja se čita u džamiji","Molitev koju molimo","Sveto mjesto u Mekki"],"question":"Što je Levhi-mahfuz?"},{"answer":"Za izbor djela koju čini","options":["Za izbor djela koju čini","Za vrijeme kad je rođen","Za svoje roditelje","Za gdje će umrijeti"],"question":"Za šta je čovjek odgovoran prema šestom imanskom šartu?"},{"answer":"Da je sve zapisano i ništa se ne dešava mimo Njegovog znanja","options":["Da se sve dešava mimo Allahovog znanja","Da je sve zapisano i ništa se ne dešava mimo Njegovog znanja","Da čovjek određuje svoju sudbinu","Da se ništa ne može dogoditi"],"question":"Šta znači vjerovanje u Allahovo određenje?"},{"answer":"Sve tri opcije su točne","options":["Sve tri opcije su točne","Da je sve zapisano, znanje i određenje Allahovog","Da čovjek zna što je određeno","Da se ništa ne dešava u Levhi-mahfuzu"],"question":"Koja tri stvari trebamo vjerovati kada govorimo o Allahovom određenju?"},{"answer":"Da, potpuno je slobodan da odabere","options":["Ne, jer je sve već određeno","Da, potpuno je slobodan da odabere","Slobodan je samo za dobro","Slobodan je samo za zlo"],"question":"Je li čovjek slobodan da bira između dobra i zla?"}]},{"nivo":21,"slug":"el-kafirun","naslov":"Učenje sure El-Kāfirūn","content_html":"<h1>UČENJE SURE EL-KĀFIRŪN S PRIJEVODOM</h1>\n\n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure El-Kāfirūn</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje čvrste vjere i ponosa na islamski identitet</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst i značenje sure El-Kāfirūn (109. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da pravilno i melodično uče suru</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koja sura govori o tome da musliman čvrsto stoji u svojoj vjeri i ne miješa se sa nevjerstvom? To je sura El-Kāfirūn. Hajde da je naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura El-Kāfirūn (Nevjernici) je 109. sura Kur’ana, ima 6 ajeta.</p><p>Objavljena je u Mekki, kao odgovor mušricima koji su tražili od Poslanika, a.s., da naizmjenično obožava njihove kipove i Allaha.</p><p>Tekst: <em>\"Kul jā ejjuhel-kāfirūn. Lā a‘budu mā ta‘budūn...\"</em> – Reci: O nevjernici, ja ne obožavam ono što vi obožavate...</p><p>Poruka: musliman ima svoju vjeru i ne miješa je sa nevjerstvom. Vjera u Allaha je čvrsta, jasna i potpuna.</p><p>Postupak: Pišem suru na tabli arapski + transkripcija. Učenici slušaju izgovor (sa snimka), ponavljaju ajet po ajet u horu i pojedinačno.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče prva tri ajeta zajedno. Zadaća: učiti suru svaki dan dok se ne nauči napamet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">O SURI EL-KĀFIRŪN <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content\">\n            <p>U vrijeme Muhammeda, a.s., mekanski idolopoklonici su mu jednom predložili neobičan dogovor. Htjeli su da on jednu godinu obožava njihove kipove, a drugu godinu bi oni obožavali Allaha. Naravno, to je bio nemoguć prijedlog – istina se ne može miješati sa zabludom. Allah, dž.š., je tada objavio ovu kratku ali snažnu suru koja daje jasan odgovor.</p><p>Hajdemo zajedno naučiti suru El-Kāfirūn, njen izgovor na arapskom i prijevod na bosanski jezik.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p style=\"text-align: center;\">Objavljena u Mekki, sadrži 6 ajeta.</p><div class=\"arabic-card\"><p style=\"text-align: center;\">بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ</p><p style=\"text-align: center;\">BISMILLĀHIR-RAHMĀNIR-RAHĪM</p></div><div class=\"arabic-card\"><p style=\"text-align: center;\">قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ</p><p style=\"text-align: center;\">KUL JĀ EJJUHEL-KĀFIRŪN.</p><p style=\"text-align: center;\">لَآ أَعْبُدُ مَا تَعْبُدُونَ</p><p style=\"text-align: center;\">LĀ E'ABUDU MĀ TA'BUDŪN.</p><p style=\"text-align: center;\">وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ</p><p style=\"text-align: center;\">VE LĀ ENTUM 'ĀBIDŪNE MĀ E'ABUD.</p><p style=\"text-align: center;\">وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمْ</p><p style=\"text-align: center;\">VE LĀ ENE 'ĀBIDUN MMĀ 'ABE(D)TTUM.</p><p style=\"text-align: center;\">وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ</p><p style=\"text-align: center;\">VE LĀ ENTUM 'ĀBIDŪNE MĀ E'ABUD.</p><p style=\"text-align: center;\">لَكُمْ دِينُكُمْ وَلِىَ دِينِ</p><p style=\"text-align: center;\">LEKUM DĪNUKUM VE LIJE DĪN.</p></div><div class=\"info-box\"><p style=\"text-align: center;\">Prijevod:</p><p style=\"text-align: center;\"><em>U ime Allaha, Milostivog, Samilosnog!</em></p><p style=\"text-align: center;\"><em>Reci: 'O vi nevjernici,</em></p><p style=\"text-align: center;\"><em>Ja se neću klanjati onima kojima se vi klanjate,</em></p><p style=\"text-align: center;\"><em>A ni vi se nećete klanjati Onome kome se ja klanjam;</em></p><p style=\"text-align: center;\"><em>Ja se nisam klanjao onima kojima ste se vi klanjali,</em></p><p style=\"text-align: center;\"><em>A i vi se niste klanjali Onome kome se ja klanjam,</em></p><p style=\"text-align: center;\"><em>Vama – vaša vjera, a meni – moja!'</em></p></div><p style=\"text-align: center;\">Ova kratka mekanska sura govori o jednom prijedlogu koji su idolopoklonici predložili Muhammedu, a.s. Rekli su mu: 'O Muhammede, predlažemo, da ti jednu godinu dana obožavaš naše kipove, a drugu godinu ćemo mi obožavati Allaha.' Nakon njihovog prijedloga Allah, dž.š., je objavio ovu suru.</p><div class=\"info-card\"><p style=\"text-align: center;\">Poruka sure:<br>Muhammed, a.s., nije nikada obožavao kipove, nego je poručio nevjernicima: 'Vama vaša vjera, a meni moja.'</p></div><p style=\"text-align: center;\"></p>\n        </div>\n    </div>\n","audio_src":null,"redoslijed":9,"is_published":true,"kviz_pitanja":[{"answer":"U Mekki","options":["U Medini","U Mekki","U Jerusalemu","U Egiptu"],"question":"Gdje je objavljena sura El-Kāfirūn?"},{"answer":"6 ajeta","options":["3 ajeta","4 ajeta","6 ajeta","10 ajeta"],"question":"Koliko ajeta ima sura El-Kāfirūn?"},{"answer":"Godinu dan klanja njihove kipove, godinu dan Allaha","options":["Da ide u Medinu","Godinu dan klanja njihove kipove, godinu dan Allaha","Da napusti Mekku","Da se vrati svojoj porodici"],"question":"Šta su idolopoklonici predložili Muhammadu, alejhis-selam?"},{"answer":"Vama vaša vjera, meni moja","options":["Moraju prihvatiti his vjeru","Vama vaša vjera, meni moja","Svi moraju zajedno moliti","Nema vijere ni boga"],"question":"Koju poruku Muhammed, alejhis-selam, poručuje nevjernicima?"},{"answer":"Četvrtina Kurʼana","options":["Najkraća sura Kurʼana","Četvrtina Kurʼana","Polovica Kurʼana","Najduža sura Kurʼana"],"question":"Šta je rekan Poslanik, alejhis-selam, o suri El-Kāfirūn?"}]},{"nivo":21,"slug":"islamski-sarti","naslov":"Prvi islamski šart - Kelimei-šehadet","content_html":"<h1>ISLAMSKI ŠARTI</h1>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Prvi islamski šart – Kelimei-šehadet</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje vjere u Allaha i Poslanika, a.s., kroz svjedočenje šehadeta</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst i značenje Kelimei-šehadeta i razumjeti njegovu važnost</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da svjesno i ispravno izgovara šehadet</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koja je prva i najvažnija rečenica koju musliman izgovara? Šta čini čovjeka muslimanom? To je šehadet. Šta on znači?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kelimei-šehadet je prvi islamski šart. Tekst: <em>Ešhedu en lā ilāhe illallāh, ve ešhedu enne Muhammeden ‘abduhu ve resūluhu.</em></p><p>Značenje: <em>\"Svjedočim da nema drugog boga osim Allaha i svjedočim da je Muhammed Njegov rob i poslanik.\"</em></p><p>Šehadet ima dva dijela: svjedočenje o Allahovoj jednoći i svjedočenje o poslanstvu Muhammeda, a.s.</p><p>Onaj ko iskreno izgovori šehadet i radi po njemu – musliman je.</p><p>Postupak: Pišem šehadet na tabli arapski + transkripcija. Razgovaramo o značenju riječ po riječ. Učenici ga uče i ponavljaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici izgovaraju šehadet. Zadaća: učiti ga svaki dan napamet.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">PET STUBOVA ISLAMA <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content\">\n            <p>Islam počiva na pet stubova, kao što kuća stoji na pet čvrstih temelja. Ako jedan stub oslabi, cijela građevina je ugrožena. Ti stubovi su islamski šarti – pet glavnih dužnosti koje svaki musliman i muslimanka trebaju poznavati i izvršavati. Prvi i najvažniji od njih je Kelimei-šehadet – svjedočenje vjere kojim postajemo muslimani.</p><p>U ovoj lekciji ponovit ćemo svih pet islamskih šartova i detaljnije naučiti o prvom – šehadetu.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <p>Islamski šarti su glavne islamske dužnosti i ima ih pet.</p><p>Prvi islamski šart i prva glavna islamska dužnost je – <strong>IZGOVARATI KELIMEI-ŠEHADET.</strong></p><p>Kelimei-šehadet se sastoji iz dva dijela. Prvim potvrđujemo svoje vjerovanje u Allahovo, dž.š., postojanje i Njegovu jednoću. Drugim dijelom šehadeta potvrđujemo vjerovanje da je Muhammed, a.s., Njegov rob i poslanik.</p><p>Izgovaranjem prvog dijela iskazujemo pokornost Allahu, dž.š., a drugim dijelom poslušnost Poslaniku, a.s. Od trenutka kada prvi put kažemo šehadet, uzimamo obavezu da ćemo raditi što je Allah, dž.š., naredio, a kloniti se onoga što je zabranio i da ćemo slijediti sunnet Poslanika, a.s.</p><p>Čestim ponavljanjem šehadeta jačamo svoju vjeru i pokornost Allahu, dž.š., i Njegovom Poslaniku, a.s.</p><div class=\"info-card\"><p style=\"text-align: center;\">ŠEHADET</p><p style=\"text-align: center;\">NEMA BOGA OSIM ALLAHA,</p><p style=\"text-align: center;\">NEKA MU JE VJEČNA HVALA,</p><p style=\"text-align: center;\">A MUHAMMED MILJENIK,</p><p style=\"text-align: center;\">ALLAHOV JE POSLANIK.</p><p style=\"text-align: center;\">R. Kadić</p></div><p>Kelimei-šehadet glasi:</p><div class=\"arabic-card\"><p style=\"text-align: center;\"><strong>EŠHEDU EN LĀ ILĀHE ILLALLĀH<br>VE EŠHEDU ENNE MUHAMMEDEN<br>'ABDUHŪ VE RESŪLUHŪ</strong></p><p style=\"text-align: center;\"><strong>Ove riječi znače:<br>SVJEDOČIM DA NEMA DRUGOG BOGA OSIM ALLAHA I SVJEDOČIM DA JE MUHAMMED, A.S., BOŽIJI ROB I POSLANIK.</strong></p></div><p></p><div class=\"info-card\"><p style=\"text-align: center;\"><strong>ZAPAMTI!<br>Sunnet je sve ono što je Muhammed, a.s., rekao, radio ili šuteći odobrio da se radi.</strong></p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p><strong>RAZGOVOR S MUALLIMOM</strong></p><ul><li><p>Šehadet u mome srcu, na jeziku i u djelima</p></li></ul><p><strong>IZABERI ZADAĆU!</strong></p><ol><li><p>Napiši pjesmu ili sastav o temi: Šehadet – radost srca moga – sastav će se čitati na času.</p></li><li><p>Poduči riječima šehadeta neko dijete u porodici – brata, sestru, rođaka... i snimi kako izgovara šehadet, pa prezentiraj u mektebu.</p></li></ol><p></p>\n        </div>\n    </div>\n","audio_src":null,"redoslijed":10,"is_published":true,"kviz_pitanja":[{"answer":"Pet","options":["Tri","Pet","Sedam","Deset"],"question":"Koliko islamskih šarti postoji?"},{"answer":"Izgovaranje Kelimei-šehadeta","options":["Namaz","Zekat","Izgovaranje Kelimei-šehadeta","Hadž"],"question":"Šta je prvi islamski šart?"},{"answer":"Iz dva dijela","options":["Iz jednog dijela","Iz dva dijela","Iz tri dijela","Iz četiri dijela"],"question":"Iz koliko dijelova se sastoji Kelimei-šehadet?"},{"answer":"Vjerovanje u Allahovo postojanje i jednoću","options":["Vjerovanje u Poslanika","Vjerovanje u Allahovo postojanje i jednoću","Vjerovanje u raj","Vjerovanje u Anđele"],"question":"Šta potvrđujemo prvim dijelom šehadeta?"},{"answer":"Raditi što Allah naredi i slijediti Sunnet","options":["Samo moliti se kući","Raditi što Allah naredi i slijediti Sunnet","Prestati poštovati roditelje","Zaboraviti na Islam"],"question":"Što trebamo raditi nakon što kažemo šehadet?"}]},{"nivo":21,"slug":"namaz","naslov":"Drugi islamski šart - namaz","content_html":"<h1>DRUGI ISLAMSKI ŠART – NAMAZ</h1>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Drugi islamski šart – namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema namazu kao stupu vjere</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti zašto je namaz drugi islamski šart i šta je njegovo značenje</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Jačanje navike redovnog klanjanja pet dnevnih namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koliko ima islamskih šarta? Pet. Koji je drugi? Namaz. Zašto je namaz tako važan? Hajde da otkrijemo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Namaz je drugi islamski šart i naša svakodnevna obaveza – klanja se pet puta dnevno.</p><p>Poslanik, a.s., je rekao: <em>\"Namaz je stub vjere. Ko ga uspravi – uspravio je vjeru, ko ga sruši – srušio je vjeru.\"</em></p><p>Pet dnevnih namaza su: <strong>sabah</strong> (prije izlaska sunca), <strong>podne</strong>, <strong>ikindija</strong> (popodne), <strong>akšam</strong> (poslije zalaska sunca), <strong>jacija</strong> (kad se smrkne).</p><p>Namaz nas povezuje sa Allahom 5 puta dnevno – to je nemogućno biti pravi vjernik bez namaza.</p><p>Razgovor: Kako se osjećate kad klanjate? Šta vam pomaže da se sjetite namaza?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju imena pet dnevnih namaza. Zaključak: čuvajmo namaz, on čuva nas.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('story', this)\">NAMAZ – SUSRET SA ALLAHOM <span class=\"section-icon\">▼</span></button>\n        <div id=\"story\" class=\"lesson-content\">\n            <p>Svaki dan imamo pet prilika da razgovaramo sa svojim Stvoriteljem. Pet prilika da stanemo pred Allaha, zahvalimo Mu se na svemu i zamolimo Ga za pomoć. To je namaz – najljepši i najpotpuniji način iskazivanja pokornosti i ljubavi prema Allahu, dž.š.</p><p>Naviku obavljanja namaza treba stjecati od ranog djetinjstva, jer namaz nije samo dužnost – on je dar i privilegija.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ilmihal', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ilmihal\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p>Allah, dž.š., kaže: Kazuj Knjigu koja ti se objavljuje i obavljaj molitvu, molitva, zaista, odvraća od razvrata i od svega što je ružno, obavljanje molitve je najveća poslušnost! – A Allah zna šta radite. (El-'Ankebut, 45)</p></div><p>Drugi islamski šart i druga glavna islamska dužnost je <strong>NAMAZ</strong>.</p><p>Namaz je najpotpuniji način iskazivanja pokornosti i zahvalnosti Allahu, dž.š. Naređen je Kur'anom i praktično pokazan sunnetom Muhammeda, a.s.</p><p>Svaki musliman je dužan da u toku 24 sata klanja pet namaza, koji se moraju obavljati u tačno određeno vrijeme:</p><ul><li><p><strong>SABAH</strong> – od zore do izlaska Sunca,</p></li><li><p><strong>PODNE</strong> – kada Sunce pređe polovinu neba,</p></li><li><p><strong>IKINDIJU</strong> – na sredini vremena između podne i zalaska Sunca,</p></li><li><p><strong>AKŠAM</strong> – kada Sunce zađe,</p></li><li><p><strong>JACIJU</strong> – kada noć potpuno padne.</p></li></ul><p>Namazom se zahvaljujemo Uzvišenom Allahu na svim blagodatima koje nam je darovao u životu na ovom svijetu – dunjaluku i želimo steći Njegovu milost i nagradu na budućem svijetu, ahiretu.</p><p>Musliman zna da je svaki namaz susret sa Allahom, dž.š., i da nas namaz podsjeća na polaganje računa na Sudnjem danu. Svrha namaza je i da nas čuva od grijeha.</p><div class=\"arabic-card\"><p>\"Prva obaveza za koju će čovjek na Sudnjem danu polagati račun jeste namaz, pa ako mu namaz bude dobar, bit će dobra i ostala djela, a ako on bude loš, bit će loša i ostala djela\". (Taberani)</p></div><p>Naviku obavljanja namaza treba stjecati od ranog djetinjstva a obavezni smo obavljati namaz od momenta punoljetnosti pa do kraja života. Isplaniraj svoje sedmične aktivnosti tako što ćeš voditi računa o tome da namaz bude na prvom mjestu.</p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong><br>TRI VREMENA KADA SE NE SMIJE KLANJATI SU:<br>1. KADA SUNCE IZLAZI<br>2. KADA SUNCE ZALAZI<br>3. KADA JE SUNCE NA SREDINI NEBA<br><br>Pokuđeno (mekruh) je klanjati: otprilike 45 minuta poslije izlaska Sunca, 45 minuta prije zalaska i 5-10 minuta dok je Sunce u zenitu.</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('pitanja', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"pitanja\" class=\"lesson-content\">\n            <p><strong>RAZGOVOR S MUALLIMOM</strong></p><ul><li><p>Namaz – radost života moga.</p></li></ul><p><strong>PRIMIJENI NAUČENO!</strong></p><ol><li><p>Svoj dan započet ću klanjanjem sabah-namaza od zore do izlaska sunca.</p></li><li><p>Pripremi se i praktično pokaži svojim prijateljima i prijateljicama u mektebu kako se klanjaju dva rekata.</p></li></ol><p></p>\n        </div>\n    </div>\n","audio_src":null,"redoslijed":11,"is_published":true,"kviz_pitanja":[{"answer":"Pet namaza","options":["Tri namaza","Pet namaza","Četiri namaza","Šest namaza"],"question":"Koliko namaza je musliman dužan da klanja u toku 24 sata?"},{"answer":"Sabah namaz","options":["Sabah namaz","Podne namaz","Ikindija namaz","Akšam namaz"],"question":"Koji namaz se klanja od zore do izlaska Sunca?"},{"answer":"Od punoljetnosti","options":["Od djetinjstva","Od punoljetnosti","Od završetka škole","Od braka"],"question":"Od kojeg vremena je musliman dužan obavljati namaz?"},{"answer":"45 minuta poslije","options":["45 minuta prije","45 minuta poslije","2 sata poslije","Odmah poslije"],"question":"Kada je klanjati pokuđeno (mekruh) za vrijeme izlaska Sunca?"},{"answer":"Zahvaliti Allahu i čuvati se od grijeha","options":["Satati vrijeme","Zahvaliti Allahu i čuvati se od grijeha","Družiti se sa prijateljima","Pokazati bogatstvo"],"question":"Koja je glavna svrha namaza prema tekstu lekcije?"}]},{"nivo":21,"slug":"sta-kvari-namaz","naslov":"Šta kvari namaz","content_html":"<div class=\"lesson-container\">\n<h1>ŠTA KVARI NAMAZ – SEHVI-SEDŽDA</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sta_kvari_namaz.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Šta kvari namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje pažnje i poštivanja u namazu kao razgovoru sa Allahom</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti djela i postupke koji kvare namaz</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da izbjegavaju greške koje kvare namaz</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta da uradimo ako tokom namaza neko zazove naše ime, ako počnemo kihati ili se nasmijati? Postoje stvari koje kvare namaz. Koje su to?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Namaz se kvari sljedećim postupcima:</p><p><strong>1.</strong> Govor (osim učenja Kur’ana i zikra namaza)</p><p><strong>2.</strong> Smijeh naglas</p><p><strong>3.</strong> Jelo i piće</p><p><strong>4.</strong> Veliki suvišni pokreti koji nisu dio namaza</p><p><strong>5.</strong> Okretanje prsima od kible</p><p><strong>6.</strong> Gubljenje abdesta (npr. nužda)</p><p><strong>7.</strong> Plač i jecaj zbog dunjalučkog razloga (ne radi Allaha)</p><p>Ako se desi nešto od ovoga – namaz se prekida i ponavlja iz početka.</p><p>Postupak: Razgovor: šta uraditi ako se desi nehotice? (npr. komarac proleti) – takav slučaj ne kvari namaz ako je mali pokret.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju 3-4 stvari koje kvare namaz. Zaključak: u namazu smo pred Allahom, treba biti potpuno usmjeren.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":12,"is_published":true,"kviz_pitanja":[{"answer":"Naknadna sedžda za ispravljanje greške u namazu","options":["Naknadna sedžda za ispravljanje greške u namazu","Prva sedžda u svakom namazu","Sedžda koja se čini samo u petkovu namazu","Sedžda koja se čini prije početka namaza"],"question":"Šta je sehvi-sedžda?"},{"answer":"Moramo vratiti se i učiniti sehvi-sedždu","options":["Namaz je nevažeći i moramo ga ponavljati","Moramo vratiti se i učiniti sehvi-sedždu","Nastavljamo namaz normalno bez greške","Imam mora završiti namaz za nas"],"question":"Šta se dešava ako zaboravimo sjesti na prvo sjedenje?"},{"answer":"Smatramo da smo klanjali manji broj rekata","options":["Smatramo da smo klanjali veći broj rekata","Smatramo da smo klanjali manji broj rekata","Odmah prekidamo namaz i počinjemo ispočetka","Pitamo imama da nam kaže točan broj"],"question":"Kada se dvoumimo oko broja rekata, šta trebamo učiniti?"},{"answer":"Nakon predaje selama na desnu stranu","options":["Na početku namaza prije fatihe","Nakon predaje selama na desnu stranu","Između drugog i trećeg rekta","Prije nego što stanemo na noge"],"question":"Na kojem mjestu se čini sehvi-sedžda?"},{"answer":"Ne, ali učini je zajedno s imamom kada on to učini","options":["Da, svaka osoba mora učiniti svoju sehvi-sedždu","Ne, ali učini je zajedno s imamom kada on to učini","Da, ali samo na kući nakon namaza","Ne, ni u kom slučaju nije dužna"],"question":"Je li osoba iza imama dužna učiniti sehvi-sedždu ako sam napravi grešku?"}]},{"nivo":21,"slug":"naklanjavanje","naslov":"Naklanjavanje namaza","content_html":"<div class=\"lesson-container\">\n<h1>PROPUŠTENI NAMAZ – KAZA NAMAZ</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/propusteni_namaz.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Naklanjavanje propuštenih namaza</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o vrijednosti svakog namaza i obavezi nadoknade</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti kako se naklanjavaju propušteni farz-namazi (kaza)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da obavi kaza-namaz kada propusti farz</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta da uradi onaj ko je iz nekog razloga propustio namaz? Da li ga treba samo ostaviti? Ne! Klanja ga naknadno – to zovemo naklanjavanje (kaza).</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Kaza-namaz je naknadno klanjanje propuštenog farz-namaza.</p><p>Svaki propušteni farz-namaz mora se naklanjati kad bude prilike – on ostaje dug Allahu dok se ne klanja.</p><p>Klanja se na isti način kao i redovni farz-namaz – isti broj rekata.</p><p>Redoslijed: ako su propušteni više namaza, naklanjavaju se istim redom kojim su trebali biti klanjani.</p><p>Lijepo je nakon spavanja prvo klanjati propušteni sabah, ako je već prošlo vrijeme sabaha.</p><p>Postupak: Demonstracija – kako se klanja propušteni podne-namaz. Razgovor: zašto je važno odmah naklanjati?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici odgovaraju: Šta je kaza-namaz? Kada se klanja? Zaključak: bolje na vrijeme nego naknadno – ali ako se desi, obavezno naklanjati.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":14,"is_published":true,"kviz_pitanja":[{"answer":"Samo farzove i vitr-namaz","options":["Samo farzove i vitr-namaz","Samo sunnete namaze","Sve namaze bez razlike","Samo sabah-namaz"],"question":"Koje namaze naklanjavamo od propuštenih namaza?"},{"answer":"Istim redoslijedom kako smo ih trebali klanjati","options":["Nasumičnim redoslijedom","Istim redoslijedom kako smo ih trebali klanjati","Obrnutim redoslijedom","Najduljim namazima prvo"],"question":"Kojim redoslijedom se naklanjavaju propušteni namazi?"},{"answer":"Umjesto EDÃEN kažemo K̇AḊÃEN","options":["Broj raka'ata namaza","Umjesto EDÃEN kažemo K̇AḊÃEN","Vrijeme klanjanja namaza","Fizijske pokrete u namazu"],"question":"Šta se mijenja kada naklanjavamo propušteni namaz?"},{"answer":"Prvo izostavljen redovni namaz","options":["Prvo redovni namaz","Prvo izostavljen redovni namaz","Samo redovni namaz","Samo propuštene namaze"],"question":"Ako je propuštenih namaza manji broj od šest, šta prvo klanjamo?"},{"answer":"U tri slučaja","options":["U jednom slučaju","U dva slučaja","U tri slučaja","U četiri slučaja"],"question":"U koliko slučajeva se ne moramo pridržavati redoslijeda naklanjavanja?"}]},{"nivo":21,"slug":"namaz-u-dzematu","naslov":"Namaz u džematu","content_html":"<div class=\"lesson-container\">\n<h1>NAMAZ U DŽEMATU</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dzemat.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Namaz u džematu</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema zajedničkom namazu i jedinstvu muslimana</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti vrijednost klanjanja u džematu i pravila ponašanja u njemu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike odlaska u džamiju i klanjanja u zajednici</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li ste klanjali u džamiji u džematu? Kako je to? Poslanik, a.s., je rekao da namaz u džematu ima posebnu vrijednost. Koliku?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Namaz u džematu znači klanjati zajedno sa drugim muslimanima, iza imama.</p><p>Poslanik, a.s., je rekao: <em>\"Namaz u džematu vredniji je 27 puta od namaza u samoći.\"</em></p><p>Pravila: stati u redove (saffove), pravo i blizu jedni drugima, slijediti imama, ne pretjecati ga, ne izostajati.</p><p>Imam pred svima nosi odgovornost – treba biti učen i ispravnog akhlaka.</p><p>Klanjanje u džematu jača jedinstvo muslimana, povezuje ih i podsjeća da smo svi jednaki pred Allahom.</p><p>Postupak: Demonstracija pravljenja saffa, slijeđenja imama. Razgovor: zašto je važno doći ranije i zauzeti prvi saff?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici opisuju kako se osjećaju u džematu. Zaključak: zajedno klanjati znači zajedno biti jači i bliži Allahu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":15,"is_published":true,"kviz_pitanja":[{"answer":"25 ili 27 puta","options":["25 ili 27 puta","10 ili 15 puta","50 ili 60 puta","5 ili 7 puta"],"question":"Koliko puta je namaz u džematu vredniji od pojedinačnog namaza?"},{"answer":"Najmanje dvije osobe","options":["Najmanje dvije osobe","Najmanje tri osobe","Najmanje pet osoba","Najmanje deset osoba"],"question":"Koliko najmanje osoba je potrebno da bi se namaz klanjao u džematu?"},{"answer":"Džuma, bajram i dženaza namaz","options":["Džuma, bajram i dženaza namaz","Vitr i teravih namaz","Subh i asr namaz","Magrib i isha namaz"],"question":"Koji se namazi klanjaju ISKLJUČIVO u džematu?"},{"answer":"Muktedija","options":["Muktedija","Imam","Muezzin","Hafiz"],"question":"Ko je osoba koja klanja namaz za imamom u džematu?"},{"answer":"Ništa ne učiti osim Subhaneke","options":["Ništa ne učiti osim Subhaneke","Slijediti imama","Stajati iza imama","Sadržati se učenja"],"question":"Šta muktedije NE trebaju činiti tijekom klanjanja na kijamu?"}]},{"nivo":21,"slug":"post","naslov":"Treći islamski šart - post","content_html":"<div class=\"lesson-container\">\n<h1>POST U RAMAZANU</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/post.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Treći islamski šart – post (sijam)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje strpljenja, samokontrole i empatije prema gladnim i žednim</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je post, kada se posti i koji su uslovi posta</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike za vlastiti post u Ramazanu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je naš najmubarekniji mjesec? Ramazan! A šta posebno radimo u Ramazanu? Postimo. Šta je post?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Post (sijam) je suzdržavanje od jela, pića i drugih stvari koje kvare post od zore (sabaha) do zalaska sunca (akšama), uz nijet posta.</p><p>Post u mjesecu Ramazanu je farz – obavezan svakom punoljetnom i zdravom muslimanu.</p><p>Šarti posta: nijet, suzdržavanje od jela i pića, suzdržavanje od loših djela (psovke, laži, ogovaranja).</p><p>Post nas uči strpljenju, samokontroli i osjećaju za one koji nemaju.</p><p>Olakšice: bolesnici, putnici, trudnice, dojilje i osobe koje fizički ne mogu postiti – mogu odgoditi post ili dati fidju (otkup).</p><p>Razgovor: Kako se vi pripremate za Ramazan?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju koristi posta. Zaključak: post je škola karaktera i dar od Allaha.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":17,"is_published":true,"kviz_pitanja":[{"answer":"Svjesno sustezanje od jela, pića i tjelesnih užitaka do zalaska Sunca","options":["Svjesno sustezanje od jela, pića i tjelesnih užitaka do zalaska Sunca","Čitanje Kurʼana cijeli dan bez prestanka","Klanjanje samo noćnih namaza tijekom mjeseca","Dijeljenje novca siromašnima cijeli dan"],"question":"Šta je post u mjesecu ramazanu?"},{"answer":"Iftar","options":["Sehur","Imsak","Iftar","Mukabela"],"question":"Kako se zove vrijeme završetka posta?"},{"answer":"Prilika čisti post od ružnog i besmislenog govora","options":["Poseban namaz koji se klanja noću","Prilika čisti post od ružnog i besmislenog govora","Zajedno učenje Kurʼana u džamiji","Boravak u džamiji zadnjih deset dana"],"question":"Šta je sadekatul-fitr koju daje postač na kraju ramazana?"},{"answer":"Hurmу, a ako nema vodu","options":["Hljeb i vodu","Hurmу, a ako nema vodu","Samo voće i povrće","Samo toplu vodu"],"question":"Što je Poslanik savjetovao da jede postač pri iftaru?"},{"answer":"Allãhumme innĩ leke s̱umtu, ve bike ãmentu","options":["Nijet za post Ferĩḋaten min šehri ramaḋãne","Allãhumme innĩ leke s̱umtu, ve bike ãmentu","Subhanallahu ve bihamdih subhanallahu alazim","Allãhumme innaka afuvvun tuhibbul afva"],"question":"Koju dovu govorimo pri završetku posta za iftar?"}]},{"nivo":21,"slug":"zekat","naslov":"Četvrti islamski šart - zekat","content_html":"<div class=\"lesson-container\">\n<h1>ZEKAT</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/zekat.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Četvrti islamski šart – zekat</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje plemenitosti, brige za siromašne i zahvalnosti na bogatstvu</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta je zekat, ko ga daje, kome se dijeli i koliko se izdvaja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da razumije ulogu zekata u islamskom društvu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta uraditi sa nazafalim novcem? Allah od bogatih traži da dio daju siromašnima – to je zekat. Šta o njemu znamo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Zekat je obavezno izdvajanje dijela imovine za one kojima je potrebno – farz svakom muslimanu koji ima dovoljno imetka.</p><p>Daje se 2,5% od imovine koja godinu dana stoji iznad nisaba (određene granice).</p><p>Zekat se dijeli: siromašnim, ubogim, sakupljačima zekata, srcima koje se osvajaju, robovima radi oslobođenja, dužnicima, na Allahovom putu i putnicima u nuždi.</p><p>Zekat čisti imetak i dušu davaoca, smanjuje socijalne razlike i jača solidarnost u zajednici.</p><p>Onaj ko ne daje zekat – njegov imetak nije čist i bit će kažnjen na Sudnjem danu.</p><p>Razgovor: Šta ti možeš dati od svog (igračka, hrana, vrijeme za pomoć)?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju kako pomoći siromašnom djetetu u svojoj okolini. Zaključak: dijeljenje donosi bereket.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Bogastvo je Allahov dar – ali u njemu postoji i udio za siromašne. Zekat je četvrti islamski šart i jedan od najljepših principa u islamu – bogatiji dijele s onima kojima je pomoć potrebna. To čisti dušu i imovinu, i gradi pravednije društvo.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Pored šehadeta, namaza i posta Allah, dž.š., je sljedbenike islama zadužio četvrtom islamskom dužnošću – ZEKATOM. Zekat je izdvajanje određenog dijela imovine od strane imućne osobe, naređen je Kurʼanom a detaljno pojašnjen u hadisima poslanika Muhammeda, alejhis-selam.</p><div class=\"arabic-card\"><p>Allah, dž.š., kaže: I molitvu obavljajte i zekat dajite... (El-Bekare, 110)</p></div><p>Poslanik Muhammed, alejhis-selam, je rekao: “Osigurajte svoju imovinu izdvajanjem zekata.” (Ebu Davud)</p><p>Zekat je propisan druge godine po Hidžri. </p><p><strong>Ko je dužan izdvojiti zekat?</strong></p><p>Zekat je dužan dati svaki pametan i puno- ljetan musliman i muslimanka koji posje- duje imovinu u vrijednosti nisaba ili više od toga.</p><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Nisab je određena količina imovine koju ako osoba posjeduje, smatra se imućnom i dužna je izdvojiti zekat.</mark></strong></p><p>Imovina na koju se izdvaja zekat:</p><ul><li><p>zlato, srebro, novac, vrijednosni papiri,</p></li><li><p>krupna i sitna stoka,</p></li><li><p>poljoprivredni proizvodi,</p></li><li><p>trgovačka roba.</p></li></ul><p>Zekat se izdvaja u fond Bejtul-mal, a organizirano ga prikuplja Islamska zajednica u Bosni i Hercegovini. Fondom Bejtul-mal upravlja Rijaset Islamske zajednice u Bosni i Hercegovini.</p><p>Svi trebamo svoj zekat dati u Bejtul-mal. Osoba koja je obavezna izvršiti dužnost zekata a ne čini to, čini veliki grijeh, a ako zaniječe dužnost davanja zekata, postaje nevjernik.</p><div class=\"info-card\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong></p><p style=\"text-align: center;\"><strong>Bejtul-mal</strong> je fond Islamske zajednice u Bosni i Hercegovini u koji se izdvajaju sredstva zekata, sadekatul-fitra i drugi prihodi koji se raspoređuju shodno kurʼanskoj odredbi. </p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <p>1. Zašto je važno poznavati propise zekata?</p><p>2. Na koju imovinu se daje zekat?</p><p>3. Kako se zove fond u koji muslimani u Bosni i Hercegovini daju zekat?</p><p>4. ZADATAK 1: Dopuni: Osoba koja je obavezna izvršiti dužnost zekata, a ne izvrši – čini _____________; a osoba koja negira zekat u potpunosti postaje ___________________.</p><p>5. ZADATAK 2: Uz pomoć muallima objasni sljedeće: Sadaku dajem samostalno, a zekat organizirano u fond Bejtul-mal!</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('section-1774989141228', this)\">IZABERI ZADAĆU <span class=\"section-icon\">▶</span></button>\n        <div id=\"section-1774989141228\" class=\"lesson-content\">\n            <p>1. Na interentu pronađi stranicu: <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"http://www.zekat.ba\">www.zekat.ba</a> i pripremi se da je prezentiraš u mektebu.</p><p>2. Na stranici <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"http://www.zekat.ba\">www.zekat.ba</a> pronađi zekat-kalkulator i s muallimom nauči kako se koristi.</p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":18,"is_published":true,"kviz_pitanja":[{"answer":"Pet islamskih šarta","options":["Tri islamska šarta","Četiri islamska šarta","Pet islamskih šarta","Šest islamskih šarta"],"question":"Koliko ima islamskih šarta koje je Allah nametao vjernicima?"},{"answer":"Vrsta novca koji se koristi za zekat","options":["Vrsta novca koji se koristi za zekat","Određena količina imovine za plaćanje zekata","Naziv za islamsku molitvu","Vrsta životinje koja se koristi za zekat"],"question":"Šta je nisab u islamu?"},{"answer":"U Bejtul-mal kroz Islamsku zajednicu","options":["U lokalnu ljekarnu","U Bejtul-mal kroz Islamsku zajednicu","U lokalnu školsku bolnicu","U gradsku banku"],"question":"U koju instituciju muslimani u Bosni daju zekat?"},{"answer":"Zlato, srebro, novac i poljoprivredne proizvode","options":["Samo kuće i stanove","Zlato, srebro, novac i poljoprivredne proizvode","Samo automobile","Samo odjeću i obuću"],"question":"Koje vrste imovine podliježu zekat obavezi?"},{"answer":"Nevjernik","options":["Bogatija","Požaljenja","Nevjernik","Bolesnija"],"question":"Šta postaje osoba koja zaniječe dužnost davanja zekata?"}]},{"nivo":21,"slug":"hadz","naslov":"Peti islamski šart - hadž","content_html":"<div class=\"lesson-container\">\n<h1>HADŽ</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/hadz.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Peti islamski šart – hadž</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Mekki, Ka’bi i jedinstvu muslimana cijelog svijeta</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je hadž, kada i kako se obavlja, i ko je obavezan</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti redoslijed obreda hadža i njegov značaj</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je peti islamski šart? Hadž. Šta je hadž? Ko ga je vidio na televiziji? Što sve hadžije rade?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Hadž je posjeta Ka’bi u Mekki u određeno vrijeme (mjesec Zul-hidždže), uz obavljanje propisanih obreda.</p><p>Farz je svakom muslimanu koji je punoljetan, zdrav i ima materijalnih mogućnosti – jednom u životu.</p><p>Glavni obredi: oblačenje ihrama, tavaf (obilazak Ka’be), sa‘j (hodanje između Safe i Merve), boravak na Arefatu, bacanje kamenčića na Mini, klanje kurbana.</p><p>Na hadžu su svi muslimani jednaki – oblače istu jednostavnu odjeću (ihram), zaboravljaju razlike i predaju se Allahu.</p><p>Hadž je kruna ibadeta – Poslanik, a.s., je rekao: <em>\"Ko obavi hadž bez grijeha i ružnih riječi, vrati se kao na dan kad ga je majka rodila.\"</em></p><p>Postupak: Pokazivanje slike Ka’be. Razgovor o tome šta hadžije rade dan po dan.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome želje da odu na hadž. Zaključak: hadž je susret muslimana iz cijelog svijeta i najljepše putovanje srca.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Svake godine milioni muslimana IZ cijelog svijeta putuju na jedno te isto mjesto – Mekku – odgovarajući na Allahov poziv. Hadž je peti islamski šart i jedno od najdubljih duhovnih iskustava u životu muslimana. To je putovanje tijela i duše prema Allahu.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Peta islamska dužnost je <strong>HADŽ</strong>.</p><p>Pored ostalih islamskih dužnosti, Allah, dž.š., je muslimane i muslimanke obavezao na izvršavanje hadža. Peta islamska dužnost podrazumijeva posjetu Kabe i drugih svetih mjesta u tačno određeno vrijeme. Obredi hadža obavljaju se od 9. do 13. zul-hidžeta, tj. dan uoči i u danima Hadžijskog ili Kurban-bajrama.</p><p>Hadž su dužni obaviti svaki musliman i muslimanka, jednom u životu, ako su u mogućnosti osigurati sredstva za putovanje te izdržavanje porodice dok se ne vrate s hadža.</p><p>Obred hadža se sastoji od tri farza:</p><p>1. <strong>Ihram</strong> – zanijetiti ulazak u hadžske obrede zajedno sa izgovaranjem telbije,</p><p>2. <strong>Boravak na Arefatu</strong> – hadžije borave na brdu Arefat 9. zul-hidžeta,</p><p>3. <strong>Tavaf oko Kabe</strong> – obilazak oko Kabe sedam puta nakon pojave zore prvi dan Kurban-bajrama, tj. tavafuz-zijare/tavafu-ifada.</p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>HADIS</strong><br>Poslanik, alejhis-selam, je rekao: “Za primljen hadž ne postoji druga nagrada izuzev Dženneta.” (Tirmizi)</p></div><p>Vrijeme obavljanja hadža je i vrijeme Kurban-bajrama kada oni koji nisu na hadžu prinose kurban – žrtvu Allahu, dž.š.</p><p>Hadžije tokom putovanja na hadž posjete i džamiju poslanika Muhammeda, alejhis-selam, u Medini te druga sveta mjesta.</p><div class=\"info-card\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong><br>U toku hadža i hadžskih obreda, hadžije uče <strong>TELBIJU:</strong><br><strong>LEBBEJKEL-LAHUMME LEBBEJK. LEBBEJKE LA ŠERIKE LEKE LEBBEJK.</strong><br><strong>INNEL-HAMDE, VEN-NI'METE LEKE VEL-MULK. LA ŠERIKE LEK</strong>..”</p></div><p>Hadžije, tokom boravka na Arefatu, odjeveni su u bijele ihrame. Ihrami su čista, bijela, nešivena hadžska odjeća koja se sastoji iz dva dijela za muškarce, a ihram za žene je njena uobičajena nošnja.</p><p><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">RAZGOVOR S HADŽIJOM</mark><br>Razgovaraj sa osobom koja je obavila hadž, zapiši i prepričaj u mektebu doživljaje i osjećaje hadžije ili hadžinice s kojim/om si razgovarao/la?</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <p>1. Šta je hadž?</p><p>2. Koji su farzovi hadža?</p><p>3. Uz pomoć muallima/e napiši prijevod telbije na bosanskom jeziku i nauči je i na arapskom i bosanskom!</p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":19,"is_published":true,"kviz_pitanja":[{"answer":"Jednom u životu ako je sposoban","options":["Jednom u životu ako je sposoban","Pet puta u životu","Tri puta u životu","Koliko god puta želi"],"question":"Koliko puta tijekom života musliman mora obaviti hadž?"},{"answer":"Ihram, boravak na Arefatu, tavaf oko Kabe","options":["Ihram, boravak na Arefatu, tavaf oko Kabe","Molitve, post, žrtva","Putovanje, boravak, povratak","Čitanje Kurana, dua, molitve"],"question":"Koja su tri farza hadža navedena u lekciji?"},{"answer":"Zul-hidžeta od 9. do 13. dana","options":["Zul-hidžeta od 9. do 13. dana","Muharama tijekom cijelog mjeseca","Džumade druge polovice","Rajaba tijekom cijelog mjeseca"],"question":"U kojem mjesecu islamskog kalendara se obavlja hadž?"},{"answer":"Bijela, nešivena hadžska odjeća","options":["Bijela, nešivena hadžska odjeća","Posebna molitva za hadž","Namer za putovanje","Zavet koji se čini"],"question":"Što je ihram u hadžu?"},{"answer":"Sedam puta","options":["Sedam puta","Pet puta","Tri puta","Deset puta"],"question":"Koliko puta hadžije trebaju obići Kabu tijekom obaveznog tavafa?"}]},{"nivo":21,"slug":"urednost","naslov":"Urednost muslimana","content_html":"<div class=\"lesson-container\">\n<h1>UREDNOST I ČISTOĆA U ISLAMU</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/urednost.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Urednost muslimana</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike urednosti u odjeći, izgledu i okolini</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta islam kaže o urednosti i ličnom izgledu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svakodnevnih navika urednosti</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kako izgleda uredan čovjek? A neuredan? Po čemu prepoznajemo urednog muslimana?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Islam mnogo cijeni urednost – Poslanik, a.s., je bio uvijek uredan, čist i lijepo obučen.</p><p>Urednost obuhvata: čistu i složenu odjeću, počešljanu kosu, oprane ruke i lice, podrezane nokte, svježi miris, urednu sobu i stvari.</p><p>Poslanik, a.s., je rekao: <em>\"Allah je lijep i voli ljepotu.\"</em></p><p>Urednost se vidi i u našim stvarima: knjige na mjestu, krevet pospremljen, igračke složene.</p><p>Razgovor: Šta od svojih stvari ja sam pospremam? Kakva je moja soba?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na konkretnu naviku urednosti za ovaj tjedan (npr. svakodnevno sređivati krevet).</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":20,"is_published":true,"kviz_pitanja":[{"answer":"Čistoća, uljepšavanje i skladnost u odijevanju i ponašanju","options":["Samo čistoća kuće i dvorišta","Čistoća, uljepšavanje i skladnost u odijevanju i ponašanju","Samo čistoća odjeće i tijela","Samo češljanje kose i mazanje uljem"],"question":"Šta je urednost prema islamu?"},{"answer":"Čistoća tijela, uredna odjeća, pristojnost i čuvanje od nepristojnog","options":["Samo čistoća tijela i skupa odjeća","Čistoća tijela, uredna odjeća, pristojnost i čuvanje od nepristojnog","Samo pristojno ponašanje pri jelu","Samo čuvanje od svega nepristojnog"],"question":"Koji su zahtjevi islamskog bontona za urednost?"},{"answer":"Nikada ga nije vidjela neurednog i koristio je ulje za kose","options":["Poslanik je bio neuredan i prljav","Nikada ga nije vidjela neurednog i koristio je ulje za kose","Poslanik se nikada nije česljao","Poslanik nije vodio računa o urednosti"],"question":"Šta je rekla Aiša, r.a., o Poslaniku, alejhis-selam?"},{"answer":"Alkohol, krv, gnoj, urin, izmet i drugo","options":["Samo krv i izmet","Samo alkohol i krv","Alkohol, krv, gnoj, urin, izmet i drugo","Samo urin i gnoj"],"question":"Koje osnovne nečistoće moramo se čuvati?"},{"answer":"Od djetinjstva ako želimo biti uredni","options":["Samo u školi i mektebу","Samo kao odrasli ljudi","Od djetinjstva ako želimo biti uredni","Samo prije namaza i posta"],"question":"Kada se trebamo navikavati na urednost?"}]},{"nivo":21,"slug":"zdravlje","naslov":"Dužnost čuvanja zdravlja","content_html":"<div class=\"lesson-container\">\n<h1>ZDRAVLJE – ALLAHOVA BLAGODAT</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/zdravlje.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dužnost čuvanja zdravlja</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje odgovornog odnosa prema vlastitom zdravlju kao Allahovoj blagodati</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti da je čuvanje zdravlja obaveza muslimana</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje zdravih životnih navika (sport, ishrana, san, higijena)</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta je najveće blago koje smo dobili od Allaha? Zdravlje! A šta činimo da ga sačuvamo? Da li ga ponekad uzimamo zdravo za gotovo?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Tijelo je amanet od Allaha – moramo ga čuvati i koristiti za dobro.</p><p>Poslanik, a.s., je rekao: <em>\"Snažan vjernik je draži Allahu od slabog vjernika.\"</em></p><p>Zdravlje čuvamo: zdravom ishranom, pijenjem dovoljno vode, redovnim spavanjem, fizičkom aktivnošću, ličnom higijenom, izbjegavanjem štetnih navika (alkohol, droga, cigarete).</p><p>Mentalno zdravlje: učenje, dova, dobro društvo, izbjegavanje svađa i stresa.</p><p>Razgovor: Koji je moj jutarnji ritual? Koliko vremena provodim na ekranima?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju 3 navike koje su zdrave i 3 koje su štetne. Zaključak: zdravlje je Allahov dar – čuvajmo ga zahvalnošću i pažnjom.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":22,"is_published":true,"kviz_pitanja":[{"answer":"Velika Allahova blagodati koju trebamo čuvati","options":["Velika Allahova blagodati koju trebamo čuvati","Nešto što nije važno za životu","Samo za odrasle ljude","Blagodati koju svi imaju"],"question":"Šta je zdravlje prema ovoj lekciji?"},{"answer":"Alkohol i droge","options":["Alkohol i droge","Voće i povrće","Spavanje i odmaranje","Sport i rekreacija"],"question":"Koje od navedenih stvari trebamo izbjegavati za zdravlje?"},{"answer":"Umjereno spavanje i redovito vrijeme","options":["Umjereno spavanje i redovito vrijeme","Spavati što više je moguće","Nikad ne spavati","Spavati samo tokom dana"],"question":"Šta je važno za čuvanje zdravlja kada je u pitanju spavanje?"},{"answer":"Zdravo i raznovrsno sa svim potrebnim sastojcima","options":["Zdravo i raznovrsno sa svim potrebnim sastojcima","Samo slatkiše i gazirane sokove","Samo meso i kruh","Jesti samo jednu vrstu hrane"],"question":"Kako trebamo se hraniti prema učenju iz lekcije?"},{"answer":"Otići liječniku i liječiti se","options":["Otići liječniku i liječiti se","Ignorirati bolest i čekati","Nikad ne ići liječniku","Samo se moliti bez liječenja"],"question":"Što trebamo učiniti ako se razbolimo?"}]},{"nivo":21,"slug":"ljubav-poslusnost-roditelji","naslov":"Ljubav i poslušnost prema roditeljima","content_html":"<div class=\"lesson-container\">\n<h1>LJUBAV I POSLUŠNOST PREMA RODITELJIMA</h1>\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ljubav i poslušnost prema roditeljima</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje duboke ljubavi, zahvalnosti i poštovanja prema roditeljima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti islamske propise o pravima roditelja i obavezama djece</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike svakodnevnog činjenja dobra prema roditeljima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko vas najviše voli na svijetu? Roditelji. A šta su sve oni za vas učinili? Allah je u Kur’anu posebno naglasio prava roditelja.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Allah je u Kur’anu rekao: <em>\"Gospodar tvoj zapovijeda da Njemu samom ‘ibadet činite i da roditeljima dobročinstvo iskazujete.\"</em></p><p>Poslušnost i ljubav prema roditeljima je odmah poslije ljubavi prema Allahu.</p><p>Naša djela: pomagati im, pažljivo ih slušati, ne dizati glas, ne reći im \"uf\", brinuti se kad ostare, učiti dovu za njih.</p><p>Posebno je važna majčina prava – Poslanik, a.s., je rekao da je Džennet pod nogama majki.</p><p>Razgovor: Kako pomažem roditeljima? Šta sam danas uradio za njih?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici se obavezuju na jedno konkretno dobro djelo prema roditeljima ovaj tjedan. Zajedno učimo dovu: <em>\"Rabbi-rhamhuma kemā rabbejānī sagīrā.\"</em></p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->","audio_src":null,"redoslijed":26,"is_published":true,"kviz_pitanja":[{"pitanje":"Šta Allah, dž.š., zapovjeda u suri El-Isra u vezi sa roditeljima?","odgovori":["Da im dobročinstvo činimo","Da ih se bojimo","Da im kupujemo poklone","Da ih slušamo samo kad hoćemo"],"tacanOdgovor":0},{"pitanje":"Koliko puta je Poslanik, a.s., spomenuo majku prije oca u poznatom hadisu?","odgovori":["Jednom","Dva puta","Tri puta","Četiri puta"],"tacanOdgovor":2},{"pitanje":"Kako se na arapskom kaže neposlušnost prema roditeljima?","odgovori":["Ihsan","Ukuk","Tawba","Birr"],"tacanOdgovor":1},{"pitanje":"Šta je Poslanik, a.s., naveo kao jedan od tri najveća grijeha uz širk i lažno svjedočenje?","odgovori":["Krađa","Neposlušnost prema roditeljima","Ogovaranje","Laž"],"tacanOdgovor":1},{"pitanje":"Kako glasi dova za roditelje?","odgovori":["Subhanallah","Rabbi-rhamhumā kemā rabbejānī sagīrā","La ilahe illallah","Alhamdulillah"],"tacanOdgovor":1}]},{"nivo":21,"slug":"rodbina","naslov":"Dužnosti prema rodbini","content_html":"<div class=\"lesson-container\">\n<h1>RODBINA, BRAĆA I SESTRE</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/rodbina.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Dužnosti prema rodbini</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema rodbini i čuvanje porodičnih veza</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam silaturahima (čuvanja rodbinskih veza) u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike posjećivanja i pomaganja rodbini</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko je rodbina? Daidže, tetke, amidže, dede, nene, rođaci... Koliko često ih vidimo? Šta islam kaže o čuvanju veza sa rodbinom?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Čuvanje veza sa rodbinom u islamu zovemo <strong>silaturahim</strong> – jedna od najvažnijih dužnosti muslimana.</p><p>Poslanik, a.s., je rekao: <em>\"Ko želi da mu se poveća opskrba i produži život, neka održava rodbinske veze.\"</em></p><p>Naše dužnosti: posjetiti, čestitati Bajram, pomoći u nevolji, oprostiti i izgladiti svađe, obići bolesnog, prisustvovati dženazi.</p><p>Prekidanje veza sa rodbinom (kit‘a-rahim) je veliki grijeh – Allah ga teško kažnjava.</p><p>Razgovor: Koju rodbinu nismo dugo vidjeli? Kako možemo obnoviti vezu (telefon, posjeta)?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici planiraju posjetu ili poziv jednoj rodbini ovaj tjedan. Zaključak: rodbinske veze su bereket života.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":28,"is_published":true,"kviz_pitanja":[{"answer":"Druživanje, igru, pažnju i pomoć","options":["Druživanje, igru, pažnju i pomoć","Samo novac i poklone","Samo stroge naredbe","Samo kritiku i zamjerke"],"question":"Šta nam braća i sestre daju tokom djetinjstva?"},{"answer":"Da ih slušamo, poštujemo i pitamo","options":["Da ih slušamo, poštujemo i pitamo","Da ih ignorirajmo","Da se svađamo s njima","Da ih učimo"],"question":"Koja je naša obaveza prema starijoj braći i sestrama?"},{"answer":"Paziti ih, štititi i učiti ih","options":["Paziti ih, štititi i učiti ih","Ih odbijati i izbjegavati","Ih tjeskobiti i vređati","Ih zanemarivati"],"question":"Šta trebamo činiti za mlađu braću i sestre?"},{"answer":"Svađati se s njima stalno","options":["Svađati se s njima stalno","Posjećivati ih redovno","Materijalno ih pomagati","Suosjećati s njima"],"question":"Koja od sljedećih nije obaveza prema braći i sestrama?"},{"answer":"Dvije vrste: po krvi i po mlijeku","options":["Dvije vrste: po krvi i po mlijeku","Tri vrste srodstva","Samo jedno srodstvo","Pet vrsta srodstva"],"question":"Koliko vrsta srodstva postoji po islamu?"}]},{"nivo":21,"slug":"halal-haram","naslov":"Pojam i smisao halala i harama","content_html":"<div class=\"lesson-container\">\n<h1>HALAL I HARAM</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/halal_haram.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Pojam i smisao halala i harama</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Fikh</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o granicama koje je Allah postavio i o lakoći življenja u njima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojmove halal i haram, te primjere za svaki</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da razlikuje halal od harama u svakodnevnom životu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta znači reći \"ovo je halal\", a šta \"ovo je haram\"? Da li sve smijemo jesti, raditi, gledati? Allah nam je propisao šta jeste, a šta nije dozvoljeno.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p><strong>Halal</strong> znači dozvoljeno – sve što je Allah dozvolio muslimanima.</p><p><strong>Haram</strong> znači zabranjeno – sve što je Allah zabranio.</p><p>Primjeri halala: voće, povrće, riba, meso zaklane stoke, mlijeko, čista voda, lijep govor, dobra djela.</p><p>Primjeri harama: svinjsko meso, krv, alkohol, droga, krađa, laž, varanje, nepokrivanje (kod odraslih).</p><p>Allah je halal učinio puno, a haram malo – jer voli olakšice za nas.</p><p>Onaj ko se kloni harama – ima bereket u svemu. Onaj ko jede haram – njegove dove se ne primaju.</p><p>Razgovor: Kako provjeravamo da li je nešto halal? (etikete, pitanje znalca, pravila ishrane)</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju neke primjere halala i harama. Zaključak: živimo u halalu – donosi mir i bereket.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":29,"is_published":true,"kviz_pitanja":[{"answer":"Sve ono što je Allah dozvolio","options":["Sve ono što je Allah dozvolio","Sve ono što je Allah zabranio","Hrana koja nije zdrava","Djelo koje Allah ne voli"],"question":"Šta je halal?"},{"answer":"U Kurʼanu","options":["U hadisima Poslanika","U Kurʼanu","U knjigama nastavnika","U običajima naroda"],"question":"Gdje se nalaze propisi o halalu i haramu?"},{"answer":"Sve što šteti čovjeku od ružnih djela i hrane","options":["Sve što je skupo i skupo","Sve što šteti čovjeku od ružnih djela i hrane","Samo meso životinja","Samo hladne napitke"],"question":"Što Allah zabranjuje zabranom harama?"},{"answer":"Snosi posljedice na dunjaluku i ahiretu","options":["Postaje bogatiji i jači","Nema nikakvih posljedica","Snosi posljedice na dunjaluku i ahiretu","Dobija nagradu od Boga"],"question":"Šta se dešava kada musliman čini haram?"},{"answer":"Jer štiti našu vjeru, zdravlje i život","options":["Jer je to skupo","Jer štiti našu vjeru, zdravlje i život","Jer je to zabavno","Jer svi to rade"],"question":"Zašto je važno da pazimo na halal i haram?"}]},{"nivo":21,"slug":"podne-namaz","naslov":"Podne-namaz","content_html":"<div class=\"lesson-container\">\n<h1>PODNE-NAMAZ</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/podne_namaz.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Podne-namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike redovnog klanjanja podne-namaza</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti broj rekata i način klanjanja podne-namaza</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da samostalno klanjaju podne-namaz</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je drugi dnevni namaz po redu? Podne. Kada se klanja? Koliko ima rekata? Hajde da naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Podne-namaz se klanja kad sunce krene da pada sa zenita, do otprilike sredine vremena prije ikindije.</p><p>Ima ukupno 10 rekata: 4 sunneta + 4 farza + 2 sunneta.</p><p>Klanja se sufar tako što prvo klanjamo prva 4 sunneta, zatim 4 farza, na kraju 2 sunneta.</p><p>Petkom se umjesto podne klanja džuma-namaz u džamiji.</p><p>Postupak: Demonstracija – sa učenicima ponavljamo nijete za sunnet i farz. Razgovor: zašto je važno klanjati i sunnete.</p><p>Vrijednost: Sunneti su <em>nafila</em>; nadoknađuju propuste u farzima i podižu naš rang kod Allaha.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju strukturu podne-namaza (4+4+2). Zadaća: klanjati podne-namaz svaki dan ovaj tjedan.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":31,"is_published":true,"kviz_pitanja":[{"answer":"Sunnet, farz, sunsunnet","options":["Farz, sunnet, sunsunnet","Sunnet, farz, sunsunnet","Sunsunnet, farz, sunnet","Farz, sunsunnet, sunnet"],"question":"Koji je redoslijed klanjanja podne-namaza?"},{"answer":"10 rekata","options":["8 rekata","10 rekata","12 rekata","6 rekata"],"question":"Koliko rekata ima podne-namaz?"},{"answer":"Kada Sunce pređe polovinu neba","options":["Prije podne","Kada Sunce pređe polovinu neba","Uveče","Ujutro"],"question":"Kada je vrijeme podne-namaza?"},{"answer":"Četiri sunneta","options":["Dva sunsunneta","Četiri sunsunneta","Četiri sunneta","Tri sunneta"],"question":"Koliko sunneta ima podne-namaz?"},{"answer":"Bismilla, Fatiha i sura","options":["Bismilla, Fatiha i sura","Subhaneke, Euzubilla, Bismilla","Et-Tehijatu","Salavati i dove"],"question":"Šta čitamo u trećem rekatu farja?"}]},{"nivo":21,"slug":"tejemum","naslov":"Tejemum - simbolično čišćenje","content_html":"<div class=\"lesson-container\">\n<h1>TEJEMUM – SIMBOLIČNO ČIŠĆENJE</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/tejemum.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Tejemum – simbolično čišćenje</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o Allahovim olakšicama i prilagodljivosti islama svim okolnostima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je tejemum, kada se uzima i kako se izvodi</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da uzmu tejemum kada nema vode</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta da uradi musliman koji nema vode, a vrijeme namaza je nastupilo? Allah je dao olakšicu – tejemum. Šta je to, danas učimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Tejemum je čišćenje suhom čistom zemljom (ili pijeskom) kao zamjena za abdest ili gusul kada nema vode ili je voda štetna za zdravlje.</p><p>Tejemumski šarti su:</p><p><strong>1.</strong> nijet (namjera) za tejemum,</p><p><strong>2.</strong> udariti dlanovima po čistoj zemlji i potrati lice,</p><p><strong>3.</strong> ponovo udariti dlanovima i potrati ruke do iznad laktova.</p><p>Postupak: Demonstriram tejemum praktično. Učenici ponavljaju pokrete. Naglašavam da se tejemum uzima samo kad nema vode ili je voda nedostupna/štetna.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Pitam: Šta je tejemum? Kada se uzima? Učenici odgovaraju i pokazuju pokrete.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":32,"is_published":true,"kviz_pitanja":[{"answer":"Simbolično čišćenje radi klanjanja namaza","options":["Simbolično čišćenje radi klanjanja namaza","Voda za pranje ruku","Poseban obred u džamiji","Zemlja za piće"],"question":"Šta je tejemum?"},{"answer":"Kada nema vode ili je nepristupačna","options":["Jer nam se ne dopada voda","Kada nema vode ili je nepristupačna","Jer je brže od abdesta","Samo na putovanju"],"question":"Koji je GLAVNA razloga da uzimamo tejemum?"},{"answer":"Srcem zanijetimo i učimo Euzubillu i Bismillu","options":["Srcem zanijetimo i učimo Euzubillu i Bismillu","Direktno se dotičemo zemlje","Izgovaramo du'u za putovanje","Molimo Allaha da nam pomogne"],"question":"Kako počinjemo uzimanje tejemuma?"},{"answer":"Jednom","options":["Dva puta","Tri puta","Jednom","Četiri puta"],"question":"Koliko puta taramo lice tijekom tejemuma?"},{"answer":"Do iza laktova","options":["Do prsta","Do iza laktova","Do ramena","Do pazuha"],"question":"Do čega taramo ruke pri uzimanju tejemuma?"}]},{"nivo":21,"slug":"el-kevser","naslov":"Učenje sure El-Kevser","content_html":"<div class=\"lesson-container\">\n<h1>SURA EL-KEVṢER</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sura_el_kevser.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure El-Kevser</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje zahvalnosti Allahu na svim blagodatima koje nam je dao</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst i značenje sure El-Kevser (108. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da pravilno uče suru El-Kevser u namazu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koja je najkraća sura u Kur’anu? El-Kevser! Ima samo tri ajeta. Hajde da je danas naučimo i razumijemo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura El-Kevser je 108. sura Kur’ana, najkraća je – ima tri ajeta.</p><p>Tekst: <em>Inna a‘tajnāke-l-kevser. Fesalli li-rabbike vanher. Inne šānieke huvel-ebter.</em></p><p>Značenje: <em>\"Doista smo ti Mi Kevser dali. Zato namaz svome Gospodaru obavljaj i kurban kolji. Onaj koji tebe mrzi sigurno će bez spomena ostati.\"</em></p><p>Kevser je rijeka u Džennetu obećana Poslaniku, a.s.</p><p>Sura nas uči zahvalnosti, namazu i žrtvi za Allaha.</p><p>Postupak: Pišem suru na tabli, učimo izgovor riječ po riječ. Učenici slušaju i ponavljaju u horu i pojedinačno.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče cijelu suru zajedno. Zadaća: učiti suru u svakom namazu dok se ne usavrši.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":34,"is_published":true,"kviz_pitanja":[{"answer":"U Mekki","options":["U Medini","U Mekki","U Jerusalimu","U Egiptu"],"question":"Gdje je objavljena sura El-Kevser?"},{"answer":"Tri ajeta","options":["Dva ajeta","Pet ajeta","Tri ajeta","Četiri ajeta"],"question":"Koliko ajeta sadrži sura El-Kevser?"},{"answer":"Rijeka u Džennetu","options":["Vrsta oružja","Rijeka u Džennetu","Planina u Arabiji","Vrste blagodati"],"question":"Šta je El-Kevser prema hadisu Poslanika, alejhis-selam?"},{"answer":"Jer su njegova muška djeca pomrla","options":["Jer je bio siromaš","Jer je bio star","Jer su njegova muška djeca pomrla","Jer je bio bolestan"],"question":"Zašto su Muhammeda, alejhis-selam, prozvali 'ebter'?"},{"answer":"Allah daje blagodati i onaj koji mrzi Muhammeda će biti zaboravljen","options":["Allah voli samo bogatstvo","Allah daje blagodati i onaj koji mrzi Muhammeda će biti zaboravljen","Trebamo se odreći blagodati","Svi će biti zapamćeni u historiji"],"question":"Koja je glavna poruka sure El-Kevser?"}]},{"nivo":21,"slug":"mali-grijesi","naslov":"Vrste grijeha - Mali grijesi","content_html":"<div class=\"lesson-container\">\n<h1>GRIJEH – VRSTE I POSLJEDICE</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/grijeh.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Vrste grijeha – Mali grijesi</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti da nijedan grijeh nije sitan ako se ponavlja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti razliku između velikih i malih grijeha i kako se mali grijesi opraštaju</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike izbjegavanja i tih sitnih grijeha</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li su svi grijesi isti? Postoje veliki, ali postoje i mali grijesi. Da li su mali grijesi bezopasni?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mali grijesi (segāir) su prekršaji koji nisu spomenuti kao veliki grijesi i za koje nije obećana posebna kazna.</p><p>Primjeri: pogled na haram, mala laž, sitna ljutnja, blago prekoračenje granice u govoru, zaboravljanje učenja Bismille.</p><p>Mali grijesi se opraštaju kroz: namaz, post, abdest, dobra djela i izbjegavanje velikih grijeha.</p><p>Poslanik, a.s., je rekao: <em>\"Pet dnevnih namaza, džuma do džume, Ramazan do Ramazana – brišu grijehe između sebe, ako se klone velikih.\"</em></p><p>Opasnost: Mali grijeh ako se često ponavlja – postaje navika, a navika kvari srce. Tada može postati teži od velikog grijeha koji se učini jednom i pokaje za njega.</p><p>Razgovor: Koje sitne grijehe ja činim ne razmišljajući?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razmišljaju o sitnim grijesima i kako ih izbjegavati. Učimo Estagfirullah – traženje oprosta.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":35,"is_published":true,"kviz_pitanja":[{"answer":"Sve što je Allah zabranio i prelaženje Njegovih granica","options":["Sve što je Allah zabranio i prelaženje Njegovih granica","Samo loše misli koje imamo u glavi","Samo vidljivi grijesi koje čine ruke i noge","Samo grijesi koje čine druge osobe prema nama"],"question":"Šta je grijeh prema islamskoj vjeri?"},{"answer":"Na male, velike i teške","options":["Na vidljive i nevidljive","Na male, velike i teške","Na javne i tajne","Na one prema Allahu i prema stvorenjima"],"question":"Kako se dijele grijesi prema njihovoj veličini?"},{"answer":"Razgovarati tijekom učenja ezana i ikameta","options":["Razgovarati tijekom učenja ezana i ikameta","Ubijanje nevinog čovjeka","Napuštanje namaza zauvijek","Shirk - davati partnjera Allahu"],"question":"Koji od sljedećih primjera je mali grijeh?"},{"answer":"Tevbom ili činjenjem dobrih dijela","options":["Samo moljenjem u džamiji","Tevbom ili činjenjem dobrih dijela","Ne mogu se obrisati nikada","Samo činjenjem velesnažnih dela"],"question":"Kako se brišu mali grijesi?"},{"answer":"Postaju veliki grijehi jer se potcjenjuju","options":["Ostaju mali zauvijek i nisu važni","Direktno ide u Džehennem","Postaju veliki grijehi jer se potcjenjuju","Automatski se brišu časem"],"question":"Šta se dešava ako čovjek čini male grijehe stalno?"}]},{"nivo":21,"slug":"tevba","naslov":"Tevba - pokajanje","content_html":"<div class=\"lesson-container\">\n<h1>TEVBA – POKAJANJE</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/tevba.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Tevba – pokajanje</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid/Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje nade u Allahovu milost i navike kajanja nakon grijeha</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti šta je tevba, koji su njeni uslovi i kako se čini</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da iskreno čine tevbu nakon svake greške</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta uraditi kada smo pogriješili? Ostaviti to pa nastaviti dalje? Ne! Allah nas voli kad se vraćamo Njemu – to je tevba.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Tevba znači iskreno pokajanje – vraćanje Allahu od grijeha.</p><p>Allah u Kur’anu kaže: <em>\"Allah doista voli one koji se često kaju...\"</em></p><p>Uslovi iskrene tevbe (nasūh):</p><p><strong>1.</strong> Iskreno priznati grijeh u srcu,</p><p><strong>2.</strong> Pokajati se i osjetiti tugu zbog učinjenog,</p><p><strong>3.</strong> Prekinuti činjenje tog grijeha,</p><p><strong>4.</strong> Čvrsto se odlučiti da se nikad više ne vrati,</p><p><strong>5.</strong> Ako je u pitanju pravo drugog čovjeka – vratiti mu njegovo pravo ili tražiti oprost.</p><p>Vrata tevbe su uvijek otvorena – Allah prima tevbu sve dok duša ne stigne do grla (sa smrću).</p><p>Razgovor: Šta je grijeh za koji se trebam pokajati? Kako ću to uraditi?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče dovu tevbe (Estagfirullah el-‘azīm). Zaključak: nakon svakog grijeha – tevba; Allah voli kajnike.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Svaki čovjek griješi – ali pravi vjernik prepoznaje grešku i pokaje se. Tevba su vrata Allahove milosti koja su uvijek otvorena. Allah, dž.š., voli one koji se kaju i uvijek im je spreman oprostiti. Naučimo o čudesnoj moći pokajanja.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Tevba je pokajanje za učinjeni grijeh. Ona je sastavni dio svakodnevnog vjerničkog života. Tevba je poznata još od vremena kada su prvi čovjek Adem, alejhis-selam, i njegova supruga Hava živjeli u Džennetu, gdje su učinili prvi grijeh. Nakon grijeha, oni su se prvi pokajali Allahu, dž.š., i učinili tevbu.</p><p>Osoba koja učini grijeh dužna se pokajati učinivši tevbu. Po islamskom učenju tevba se upućuje samo Allahu, dž.š., i to odmah nakon učinjenog grijeha.</p><p>Da bi tevba bila primljena, potrebno je da osoba:</p><ul><li><p>prestane sa činjenjem grijeha,</p></li><li><p>srcem se pokaje,</p></li><li><p>više se ne vraća na taj grijeh.</p></li></ul><p>Ako je grijeh učinjen prema drugoj osobi, prije spomenutih uvjeta grješnik se treba izviniti, odnosno zatražiti halal. Ako je prema drugoj osobi učinjena neka materijalna šteta, treba je nadoknaditi.</p><p>Grješnik se može pokajati izgovarajući sljedeće riječi:</p><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">ESTAGFIRULLAH MIN KULLI ZENBIN VE ETUBU ILEJH.<br>TRAŽIM ALLAHOV OPROST I POKAJANJE ČINIM ZA SVE GRIJEHE KOJE SAM POČINIO/LA.</mark></strong></p><div class=\"arabic-card\"><p>Allah, dž.š., kaže: I svi se Allahu pokajte, o vjernici, da biste postigli ono što želite. (En-Nur, 31)</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol><li><p>Šta je tevba?</p></li><li><p>Je li dovoljno pokajati se za grijeh Allahu, dž.š., ukoliko smo nekome nanijeli materijalnu štetu? Zašto?</p></li><li><p>Da bi tevba bila primljena, šta je potrebno?</p></li><li><p><strong>ZADATAK</strong>: U pjesmi Tevbei-nesuh bosanskog pjesnika Muse Ćazima Ćatića, izdvoji pouke povezane sa pokajanjem. Na mektebskoj pouci zajednički pročitajte napisano, a muallim/a neka vam objasni manje poznate riječi.</p></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">RAZGOVOR S MUALLIMOM</mark></strong><br>Tevba u svakodnevnom životu! Nije li to spremnost da sebi i drugima priznamo grešku, da budemo iskreni, da se učimo ispravljati i izvinjavati za greške!?</p><div class=\"info-card\"><p style=\"text-align: center;\"><strong>TEVBEI-NESUH</strong></p><p style=\"text-align: center;\">Gospode, evo na sedždu Ti padam,<br>Pred vječnom Tvojom klanjam se dobrotom<br>I molitvu Ti u stihove skladam,<br>Proseć: “Oh, daj mi smisao za ljepotom!”<br>Gospode, evo, na sedždu Ti padam.</p><p style=\"text-align: center;\">Ti znaš da bijah nevin poput rose<br>I poput lijera u proljeću ranom;<br>Al’ ljudi, med što pod jezikom nose,<br>Otrov mi dadoše u bokalu pjanom,<br>Mada sam bio nevin poput rose.</p><p style=\"text-align: center;\">I tada s Tvoga skrenuo sam puta<br>I zatrtao kroz pustoš i tamu<br>Ah, strast mi razum u okove sputa,</p><p style=\"text-align: center;\">... </p><p style=\"text-align: center;\">Vjeru i nadu iz srca izgubih,<br>I moju ljubav pomrč’o je grijeh -<br>Postadoh sarhoš oholi i grubi,<br>Sav ideal mu što je vinski mijeh<br>Ah, svoju vjeru i nadu izgubih!... </p><p style=\"text-align: center;\">...</p><p style=\"text-align: center;\">Svačiji prezir pratio je mene,<br>Od sjene moje druzi mi bježahu<br>Vaj! Teško mi je bilo siromahu,<br>Jer ljudski prezir pratio je mene. </p><p style=\"text-align: center;\">Ja sada bježim pod okrilje Tvoje<br>I Tvog Kurʼana, Tvoje vječne riječi,<br>Gospode, grijehe odriješi moje<br>I bolesnu mi dušu izliječi -<br>Ta ja se sklanjam pod okrilje Tvoje.</p><p style=\"text-align: center;\">Gospode, razum prosvijetli mi sada<br>I daj mi snage, daj mi volju jaku<br>Demone sve što može da savlada...<br>Nek Tvoja milost svijetli mi u mraku<br>Gospode, razum prosvijetli mi sada!</p><p style=\"text-align: center;\">Raspiri moje stare vjere plamen,<br>Vrati mi ljubav i sve stare dare,</p><p style=\"text-align: center;\">...</p><p style=\"text-align: center;\">Gospode, evo na sedždu Ti padam,<br>I kajem grijehe pred Tvojom dobrotom -<br>I molitvu Ti u stihove skladam,<br>Proseć: “Ah, daj mi smisao za ljepotom!” -<br>Gospode, evo na sedždu Ti padam!...</p><p style=\"text-align: center;\">Musa Ćazim Ćatić</p></div><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":39,"is_published":true,"kviz_pitanja":[{"answer":"Pokajanje za učinjeni grijeh","options":["Pokajanje za učinjeni grijeh","Molitev koju čitamo pet puta dnevno","Dio Kurана о životu Muhameda","Zaboravljanje svih greški"],"question":"Šta je tevba?"},{"answer":"Adem i Hava u Džennetu","options":["Adem i Hava u Džennetu","Nuh alejhis-selam","Ibrahim alejhis-selam","Muhamad, a.s."],"question":"Ko je prvi učinio tevbu u islamskoj istoriji?"},{"answer":"Prestati sa grijehom, pokajati se srcem i ne vratiti se na njega","options":["Prestati sa grijehom, pokajati se srcem i ne vratiti se na njega","Samo izgovoriti tevbu jednom","Dati novac u milostnju","Reći ljudima da se pokajamo"],"question":"Šta se MORA učiniti da bi tevba bila primljena?"},{"answer":"Nadoknaditi štetu pored tevbe","options":["Nadoknaditi štetu pored tevbe","Samo se pokajati Allahu","Čekati da nas prosti Allahu","Ništa, tevba je dovoljna"],"question":"Ako smo nekome nanijeli materijalnu štetu, šta moramo učiniti?"},{"answer":"Odmah nakon što učinimo grijeh","options":["Odmah nakon što učinimo grijeh","Samo na kraju godine","Kada nas neko upozori","Nikada nije kasno"],"question":"Kada se trebamo pokajati za grijeh?"}]},{"nivo":21,"slug":"iskrenost","naslov":"Iskrenost i saosjećajnost","content_html":"<div class=\"lesson-container\">\n<h1>ISKRENOST I SAOSJEĆAJNOST</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/iskrenost_saosjecajnost.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Iskrenost i saosjećajnost</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje iskrenosti u namjeri, govoru i djelu te samilosti prema drugima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojmove ihlas (iskrenost) i rahmet (samilost)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika iskrenog ponašanja i pomaganja drugima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta znači biti iskren? A šta znači biti saosjećajan? Po čemu prepoznajemo iskrenog i samilosnog čovjeka?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Iskrenost (ihlas) znači raditi sva djela samo radi Allaha, bez želje za pohvalom ili nagradom od ljudi.</p><p>Saosjećajnost (rahmet) znači imati milo srce – tugovati za tugom drugog, radovati se njegovoj radosti, pomagati u nevolji.</p><p>Poslanik, a.s., je rekao: <em>\"Ko se ne smiluje – njemu se neće smilovati.\"</em></p><p>Iskrenost se vidi: kad činimo dobro djelo i nikom ne pričamo o tome, kad pomažemo bez očekivanja zahvale, kad smo isti pred ljudima i nasamo.</p><p>Saosjećajnost se vidi: kad pomognemo bolesnom, kad damo komšiji, kad utješimo tužnog.</p><p>Razgovor: Koje dobro djelo si učinio iskreno? Kako pokazuješ samilost?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici opisuju jedan iskren postupak i jednu situaciju samilosti. Zaključak: iskreno srce i samilosno djelo Allah najviše voli.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":41,"is_published":true,"kviz_pitanja":[{"answer":"Ispoljavanje vjerovanja i činjenja dobra radi Allaha","options":["Ispoljavanje vjerovanja i činjenja dobra radi Allaha","Govorenje lazi kada je korisna","Rad samo da te drugi ljudi vide","Ignorisanje obaveza prema drugima"],"question":"Šta je iskrenost po učenju islama?"},{"answer":"Džennet i Allahova milost","options":["Samo novac i bogatstvo","Džennet i Allahova milost","Samo pohvala od ljudi","Samo zdravlje i dugačak život"],"question":"Koja Allahova nagrada čeka iskrene vjernika?"},{"answer":"Lažanje, prevara, varanje i dvoličnost","options":["Govorenje istine i ispunjavanje obećanja","Lažanje, prevara, varanje i dvoličnost","Briga za siromašne i siroče","Rad sa čistim i otvorenim srcem"],"question":"Što je suprotno iskrenosti po islamu?"},{"answer":"Ostaje bez Allahove nagrade","options":["Daje mu nagradu i ponos","Učini da ga drugi još više vide","Ostaje bez Allahove nagrade","Udeljuje mu Džennet odmah"],"question":"Šta Allah čini onome koji radi djelo samo da ga drugi vide?"},{"answer":"Onoga ko zbrinava siroče","options":["Onoga ko laže i vara druge","Onoga ko zbrinava siroče","Onoga ko radi samo za nagradu","Onoga ko ignoriše siromašne"],"question":"Prema hadisu, koga Poslanik posebno grli u Džennetu?"}]},{"nivo":21,"slug":"skromnost","naslov":"Skromnost i umjerenost","content_html":"<div class=\"lesson-container\">\n<h1>SKROMNOST I UMJERENOST</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/skromnost.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Skromnost i umjerenost</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ahlak</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje skromnosti, izbjegavanja oholosti i zadovoljstva onim što imamo</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojmove skromnost (tevadu‘) i umjerenost (i‘tidāl) u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navika skromnog ponašanja u govoru, oblačenju i trošenju</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koga više volite – onoga ko se hvali svime ili onoga ko je skroman i tih? Po čemu prepoznajemo skromnog čovjeka?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Skromnost (tevadu‘) je suprotnost ohologa – znači ne dizati se iznad drugih, biti dostupan svakome, ne hvaliti se.</p><p>Umjerenost (i‘tidāl) znači u svemu ići srednjim putem – ni previše ni premalo.</p><p>Poslanik, a.s., je bio najskromniji čovjek – sjedio sa siromasima, sam sebi krpao odjeću, smijao se sa djecom.</p><p>Suprotnost skromnosti je oholost (kibr) – Allah ohola ne voli. Ko ima trun oholosti u srcu, neće u Džennet.</p><p>Skromnost u oblačenju, govoru, životnom stilu, jelu, trošenju – sve je to dio islamskog ahlaka.</p><p>Razgovor: Da li volim novim stvarima više nego drugovima koji ih nemaju? Da li se hvalim?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici razgovaraju o tome šta je skromnost u njihovom životu. Zaključak: skroman je onaj ko zna ko je pred Allahom – malo, slabo i potrebno Njegove milosti.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Jednom je jedan čovjek bio pohvaljen pred drugima zbog svojih dobrih djela, pa je počeo misliti da je bolji od ostalih. Nedugo zatim upoznao je ljude koji su činili još više dobra, ali su o sebi govorili skromno i tiho. Tada je shvatio da prava vrijednost čovjeka nije u tome koliko ga drugi uzdižu, nego koliko on ostaje ponizan pred Allahom.</p><p>I mi često stojimo između dvije krajnosti: nekada želimo više nego što nam treba, a nekada zaboravimo na ono što je zaista važno. Zato nas islam uči da budemo skromni i umjereni – da znamo svoju vrijednost, ali da ne pretjerujemo ni u čemu. Upravo te osobine čine čovjeka stabilnim, smirenim i dragim među ljudima.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Skromnost</mark></strong></p><p>Skromnost je svojstvo koje podrazumijeva uljudno ponašanje – bez oholosti, ali i bez poniženja. Vjernik nije ni uobražen ni slab, nego stamen, dostojanstven i svakome drag i poželjan.</p><p>Skromnost je osobina svih poslanika i ukras islamskih učenjaka i velikana.</p><div class=\"info-box\"><p>Muhammed, a.s., kaže: “Imetak se sadakom ne umanjuje, a Allah čovjeku koji oprašta drugima samo čast povećava, i nema nikoga ko se radi Allaha ponizi, a da ga Allah neće uzdići.” (Muslim)</p></div><p>Muhamed, a.s., je pokazao najsnažnije i najupečatljivije primjere skromnosti. Neki od tih primjera su:</p><ul><li><p>u hodu je stalno gledao ispred sebe</p></li><li><p>prvi je nazivao selam, i djeci i odraslima</p></li><li><p>rukovao se sa svima</p></li><li><p>sjedio je i jeo sa siromašnim muslimanima</p></li><li><p>sa siromasima je razgovarao i dopuštao im da ga posjećuju</p></li><li><p>ušivao je svoju odjeću i obuću</p></li></ul><p>Kada je Muhammed, a.s., jednom prilikom bio na putovanju i kada mu je dovedena ovca da je zakolje, jedan njegov ashab je rekao: “Ja ću je zaklati i oguliti!” Drugi je rekao: “Ja ću isjeći njezino meso i ispeći ga!“, a on je rekao: “A ja ću sakupiti drva!” izabravši za sebe ono što je u svemu tome bilo najteže, a mogao je da sjedi i da ga svi služe; srdačno i s ljubavlju.</p><p><strong>Međutim, treba imati na umu da Allah, dž.š., traži i preporučuje skromnost.</strong></p><div class=\"arabic-card\"><p>Allah, dž.š., kaže: “I budi ljubazan prema vjernicima koji te slijede!” (Eš-Šu‘ara’, 215)</p></div><hr><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">Umjerenost</mark></strong></p><p>Pored skromnosti, lijepo je da musliman i muslimanka posjeduju i osobinu umjerenosti.</p><p>Umjerenost je sredina između dvije krajnosti – pretjerivanja i nemara a vjera islam je vjera srednjeg puta.</p><p>Umjerenost je zastupljena u svim sferama Muhammedovog, a.s., života: u ibadetu, govoru i u svakodnevnom životu.</p><div class=\"info-box\"><p><strong>ZAPAMTI!</strong></p><ul><li><p>Umjerenost muslimana utemeljena je u Kurʼanu i hadisu Muhammeda, a.s.</p></li><li><p>Umjerenost nas čini sretnim i zadovoljnim u životu.</p></li><li><p>Umjerenost nas čini dragim među našim prijateljima.</p></li><li><p>Za umjerenost ćemo biti nagrađeni od Allaha, dž.š., na ovom i budućem svijetu.</p></li></ul></div><p>Muhammed, a.s., je prakticirao umjerenost podstičući na nju i osuđujući svako pretjerivanje i nemar.</p><p>Musliman se na ovom svijetu ne odriče prava i dozvoljenih ljepota koja mu pripadaju.</p><div class=\"arabic-card\"><p>Allah, dž.š., kaže: I ne drži svoju ruku stisnutu, a ni posve otvorenu, da ne bi prijekor zaslužio i bez ičeg ostao. Gospodar tvoj pruža obilnu opskrbu kome hoće, a i ograničava je, jer zna i vidi robove Svoje. (El-Israʼ, 29-30)</p></div><p>U isto vrijeme dok radi na ovom svijetu, on ne zaboravlja obaveze prema budućem svijetu. On ne krši Allahove zabrane i ne ponaša se rasipnički.</p><p>Put muslimana je srednji put, koji mu je odredio Allah, dž.š., kazavši u Kurʼanu: <em>O vjernici, ne uskraćujte sebi lijepe stvari koje vam je Allah dozvolio, samo ne prelazite mjeru, jer Allah ne voli one koji pretjeruju</em>. (El-Maʼide, 87)</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <p>1. Šta podrazumijeva skromnost?</p><p>2. U čemu se ogleda Poslanikova, a.s., skromnost?</p><p>3. Šta je umjerenost!</p><p>4. Kako je Poslanik, a.s., ashabe podučavao umjerenosti?</p><p>5. ZADATAK: Budi iskren prema sebi pa ćeš naučiti biti iskren i prema drugima. U svojoj bilježnici nacrtaj tabelu i odgovori najiskrenije na pitanja o sebi.</p><table style=\"width: 796px;\"><colgroup><col style=\"width: 365px;\"><col style=\"width: 431px;\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"365\"><p>Koje su tvoje dobre osobine?</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"431\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"365\"><p>Koje su tvoje loše osobine?</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"431\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"365\"><p>Šta tvoji prijatelji u mektebu misle o tebi?</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"431\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"365\"><p>Po čemu se razlikuješ od drugih?</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"431\"><p></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" colwidth=\"365\"><p>Koje je najbolje djelo koje si učinio/la?</p></td><td colspan=\"1\" rowspan=\"1\" colwidth=\"431\"><p></p></td></tr></tbody></table><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":42,"is_published":true,"kviz_pitanja":[{"answer":"Uljudno ponašanje bez oholosti i poniženja","options":["Uljudno ponašanje bez oholosti i poniženja","Odbijanje svih dozvoljenih ljepota","Pretjerivanje u svim stvarima","Sjedenje samo sa bogatim ljudima"],"question":"Šta je skromnost prema lekciji?"},{"answer":"Prakticirao je skromnost i umjerenost","options":["Odbijao je rukovanje sa drugima","Prakticirao je skromnost i umjerenost","Nikada nije radio fizičke poslove","Nije se pozdravljao sa djecom"],"question":"Koja je osobina bila karakteristična za Muhammeda, alejhis-selam?"},{"answer":"Sredina između pretjerivanja i nemara","options":["Odbacivanje svih poslova","Sredina između pretjerivanja i nemara","Pretjerivanje u svim stvarima","Zanemarivanje obaveza prema Allahu"],"question":"Šta je umjerenost?"},{"answer":"U ibadetu, govoru i svakodnevnom životu","options":["Samo u ibadetu","U ibadetu, govoru i svakodnevnom životu","Samo u novčanim stvarima","Samo u hrani"],"question":"U kojim sferama života se prakticira umjerenost?"},{"answer":"Dozvoljene ljepote bez pretjerivanja","options":["Sve stvari bez ograničenja","Samo tugu i teškoće","Dozvoljene ljepote bez pretjerivanja","Zanemarivanje obaveza"],"question":"Šta je Allah dozvolio muslimanima?"}]},{"nivo":21,"slug":"ikindija-namaz","naslov":"Ikindija-namaz","content_html":"<div class=\"lesson-container\">\n<h1>IKINDIJA-NAMAZ</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/ikindija_namaz.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Ikindija-namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike redovnog klanjanja ikindije</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti broj rekata i način klanjanja ikindije-namaza</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da samostalno klanjaju ikindiju</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je treći dnevni namaz? Ikindija. Kada se klanja? Koliko ima rekata?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Ikindija se klanja popodne, kad sjenka stvari postane veća od same stvari, do nešto prije zalaska sunca.</p><p>Ima ukupno 8 rekata: 4 sunneta + 4 farza.</p><p>Sunneti su <em>gajri-mu’ekkede</em> (ne potvrđeni) – nisu obavezni kao podnenovi, ali se preporučuju.</p><p>Najvažniji su 4 farza – njih obavezno klanjamo na vrijeme.</p><p>Postupak: Demonstracija nijeta i klanjanja. Razgovor o važnosti čuvanja ikindije usred zauzetog dana.</p><p>Vrijednost: Poslanik, a.s., je rekao: <em>\"Kome propusti ikindija – kao da mu je propala porodica i imanje.\"</em></p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju strukturu ikindije (4+4). Zadaća: ne propuštati ikindiju ovaj tjedan.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":43,"is_published":true,"kviz_pitanja":[{"answer":"Treći namaz","options":["Prvi namaz","Drugi namaz","Treći namaz","Četvrti namaz"],"question":"Koji je redoslijed namaza ikindija-namaz tijekom dana?"},{"answer":"Osam rekata","options":["Šest rekata","Osam rekata","Četiri reketa","Deset rekata"],"question":"Koliko rekata ima ikindija-namaz ukupno?"},{"answer":"Četiri sunneta i četiri farza","options":["Pet sunneta i tri farza","Četiri sunneta i četiri farza","Tri sunneta i pet farza","Dva sunneta i šest farza"],"question":"Kako se dijele rekati ikindija-namaza?"},{"answer":"Na sredini između podneva i zalaska","options":["Na zalazu sunca","Na kraju dana","Na sredini između podneva i zalaska","Prije podneva"],"question":"Kada se klanja ikindija-namaz tokom dana?"},{"answer":"Subhaneke, Bismilla i Fatiha","options":["Subhaneke, Bismilla i Fatiha","Bismilla, Fatiha i sura","Et-Tehijatu i Salavati","Samo Fatiha bez sure"],"question":"Šta se uči u trećem reketu farz ikindija-namaza?"}]},{"nivo":21,"slug":"namaz-putnika","naslov":"Namaz putnika","content_html":"<div class=\"lesson-container\">\n<h1>NAMAZ PUTNIKU I BOLESNIKU – OLAKŠICE</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/namaz_putnik_bolesnik.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Namaz putnika (kasr-namaz)</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o Allahovim olakšicama putnicima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti pravila kraćenja namaza za vrijeme putovanja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenika da klanja kraćeni namaz na putu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, šta uraditi kad smo na putovanju – ostaviti namaz? Allah je dao olakšicu – kasr (kraćenje). Kako se to radi?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Putnik (musafir) je onaj koji prelazi udaljenost od oko 90 km i namjerava ostati manje od 15 dana na jednom mjestu.</p><p>Olakšice za musafira: kratiti četverorekatni farz na dva (podne, ikindija, jacija) – sabah i akšam ostaju isti.</p><p>Sunneti se ostavljaju (osim sabahskog sunneta i sunneta poslije akšama i jacije, što je preporučeno).</p><p>Putnik koji klanja iza imama-mukima – klanja kao on (nema kraćenja).</p><p>Olakšica je i u abdestu – mesh može trajati 72 sata na mestvama.</p><p>Postupak: Razgovor o tome kako su naši djedovi klanjali na putovanjima. Demonstracija kraćenog jacije-namaza (2 farza umjesto 4).</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju koje namaze putnik krati. Zaključak: Allah je islam učinio lahkim – samo trebamo znati pravila.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Jedan čovjek je krenuo na dugo putovanje. Spakovao je sve što mu treba – odjeću, hranu, dokumente – ali dok je putovao, shvatio je da nešto ipak ne smije zaboraviti: svoju vezu s Allahom. Iako je bio daleko od kuće, umoran i zauzet, došlo je vrijeme za namaz. Pogledao je oko sebe, pronašao mirno mjesto i klanjao – skraćeno, kako mu je Allah olakšao.</p><p>Tada je shvatio da islam ne otežava čovjeku, nego mu olakšava. Čak i na putu, kada se sve mijenja i postaje neizvjesno, Allah ostaje blizu, a namaz ostaje oslonac. Namaz putnika nas uči da vjera nije vezana za mjesto, nego za srce – i da nas prati gdje god krenemo.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Jedno od najvrjednijih djela kod Allaha, dž.š., jeste potpun i skrušen namaz klanjan u njegovo vrijeme. Ponekad, životne situacije od muslimana zahtijevaju olakšice u obavljanju namaza. Jedna od tih situacija jeste i vrijeme dok se musliman nalazi na putovanju.</p><p>Musafir je putnik koji iz svog mjesta stanovanja krene na put udaljenosti najmanje 80 kilometara. Musafir će prilikom klanjanja primjenjivati sljedeće propise ‒ olakšice:</p><ul><li><p>Četverorekatne farzove će skraćivati na dva rekata ‒ sabahski i akšamski farz se ne skraćuju,</p></li><li><p>Vitr-namaz će klanjati bez skraćivanja,</p></li><li><p>Sunnete nije obavezan klanjati, a ukoliko bude imao slobodnog vremena, klanjat će ih bez skraćivanja.</p></li></ul><p><strong>Putnikov namaz u džematu</strong></p><p>Putnik će svoje namaze, ukoliko je u mogućnosti, obavljati u džematu. Ako se zadesi u mjestu gdje klanja kao muktedija, slijedit će imama bez skraćivanja namaza. Treba izbjegavati biti imam onima koji nisu putnici, ali ako bi se to desilo, onda će skraćivati svoj namaz a muktedije koji nisu putnici samostalno će nastaviti klanjati treći i četvrti rekat.</p><div class=\"arabic-card\"><p>Allah, dž.š., kaže: Allah želi da vam olakša, a ne da poteškoće imate. (El-Bekare, 185)</p></div><p><strong>Namaz u prijevoznom sredstvu</strong></p><p>Musliman treba na putovanju planirati pauze i obavljati namaze u njihovom vremenu, koristeći olakšice koje mu je dao Allah, dž.š. Ukoliko nije u mogućnosti praviti pauze, namaz će obaviti u prijevoznom sredstvu na način kako mu to uvjeti dozvoljavaju. Po mogućnosti okrenut će se prema Kibli i klanjati sjedeći, čineći ruku‘ i sedždu išaretom. Ako je moguće, klanjat će stojeći. Ukoliko putnik propusti neki namaz, naklanjat će ga kada bude u mogućnosti ‒ onako kako je bio obavezan klanjati ih tokom putovanja uz skraćivanje četverorekatnih namaza.</p><p></p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong><br>Nafila-namazi se mogu klanjati u sjedećem položaju ukoliko nam stojeći položaj predstavlja poteškoću.</p></div><p><strong>Vrijeme trajanja olakšica putniku</strong></p><p>Ukoliko se putnik u mjestu putovanja namjerava zadržati do 15 dana, sve vrijeme boravka će koristiti olakšice. Ako pri polasku na put ima nijet da se zadrži duže od 15 dana, olakšice koristi samo u vrijeme dok je u putu, a po dolasku u mjesto putovanja, olakšice prestaju važiti.</p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>HADIS</strong><br>Poslanik, a.s., je rekao: “Alla­ hu su najdraža djela: klanjanje namaza na vrijeme, pokornost roditeljima i borba na Allahovom putu.” (Buhari)</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol><li><p>Ko se smatra musafirom – putnikom?</p></li><li><p>Koje olakšice prilikom klanjanja namaza ima putnik?</p></li><li><p>Opiši način klanjanja namaza u prijevoznom sredstvu!</p></li><li><p>ZADATAK 1: Na putovanju putnik je svratio u džamiju da klanja podne-namaz. Priključio se džematu i klanjao za mjesnim imamom. Opišite kako će klanjati podne-namaz!</p></li><li><p>ZADATAK 2: Zamisli da ti planiraš putovanje u neki grad. Odaberi grad i pomoću aplikacije na mobitelu pronađi broj kilometara od mjesta u kojem stanuješ do tog grada i napiši da li se ubrajaš u kategoriju musafira ili ne? Koliko dana planiraš ostati u tom gradu! Napiši i imaš li olakšice u obavljanju namaza i koje.</p></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">IZABERI ZADAĆU!</mark></strong></p><ol><li><p>Kako će se ponašati putnik kojem je ponuđeno da bude imam džematu koji nema status musafira?</p></li><li><p>Koje olakšice će koristiti putnik koji je na put krenuo iza klanjanja sabah-namaza i namjerava se zadržati deset dana kod prijatelja?</p></li><li><p>Koje olakšice će koristiti putnik kada namjerava ostati duže od petnaest dana?</p></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":44,"is_published":true,"kviz_pitanja":[{"answer":"Najmanje 80 kilometara","options":["Najmanje 50 kilometara","Najmanje 80 kilometara","Najmanje 100 kilometara","Najmanje 120 kilometara"],"question":"Koliko kilometara od mjesta stanovanja mora biti put da bi se musliman smatrao musafirom?"},{"answer":"Četverorekatne farzove","options":["Sabahski i podnevni namaz","Podnevni, afternoon i akšamski","Četverorekatne farzove","Samo akšamski namaz"],"question":"Koje farzove namaze putnik skraćuje na dva rekata?"},{"answer":"Klanja sjedeći sa rukom' i sedždom išaretom","options":["Ne klanja namaz tijekom putovanja","Klanja sjedeći sa rukom' i sedždom išaretom","Čeka dok ne stigne do kuće","Klanja bez ruku'a i sedžde"],"question":"Kako klanja putnik namaz ako je u prijevoznom sredstvu i ne može da stoji?"},{"answer":"Do 15 dana","options":["Do 7 dana","Do 10 dana","Do 15 dana","Do 20 dana"],"question":"Koliko dana putnik koristi olakšice ako se zadržava na mjestu putovanja?"},{"answer":"Putnik klanja bez skraćivanja","options":["Putnik nastavlja s olakšicama","Putnik klanja bez skraćivanja","Putnik ne klanja namaz","Putnik traži drugog imama"],"question":"Šta se dešava kada putnik u džematu klanja za imamom koji nije putnik?"}]},{"nivo":21,"slug":"jacija-namaz","naslov":"Jacija-namaz","content_html":"<div class=\"lesson-container\">\n<h1>JACIJA-NAMAZ I VITR</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/jacija_namaz.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Jacija-namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike klanjanja jacije i vitra prije spavanja</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti broj rekata i način klanjanja jacije-namaza i vitra</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da samostalno klanjaju jaciju i vitr</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je peti, posljednji dnevni namaz? Jacija. Kada se klanja? Koliko ima rekata? I šta se klanja poslije jacije?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Jacija se klanja kad se potpuno smrkne (nakon nestanka crvenila na zapadu) do pred zoru.</p><p>Struktura: 4 sunneta + 4 farza + 2 sunneta + 3 vitra (vadžib).</p><p>Vitr-namaz je vadžib (skoro kao farz) – klanja se 3 rekata, na trećem rekatu uči se Kunut-dova.</p><p>Najbolje je vitr klanjati pred spavanje, kao posljednji namaz dana.</p><p>Vrijednost: Poslanik, a.s., nikad nije ostavljao vitr-namaz, čak ni na putovanju.</p><p>Postupak: Demonstracija strukture jacije i vitra. Naglasak na ne propuštanje vitra prije spavanja.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju strukturu jacije (4+4+2+3 vitr). Zadaća: klanjati jaciju i vitr svaku večer.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":46,"is_published":true,"kviz_pitanja":[{"answer":"13 rekata","options":["9 rekata","13 rekata","11 rekata","15 rekata"],"question":"Koliko rekata ima jacija-namaz?"},{"answer":"Kada noć potpuno nastupi","options":["Kada počne zora","Kada noć potpuno nastupi","Kada bude podne","Nakon zalaska sunca"],"question":"Kada se klanja jacija-namaz?"},{"answer":"Četiri suneta, četiri farza, dva sunsunneta, tri vitr","options":["Tri suneta, dva farza, tri vitr","Četiri suneta, četiri farza, dva sunsunneta, tri vitr","Pet sunneta, pet farza, tri vitr","Dva suneta, tri farza, dva vitr"],"question":"Kako se dijele rekati jacija-namaza?"},{"answer":"Tri rekata","options":["Dva rekata","Tri rekata","Četiri rekata","Jedan rekat"],"question":"Koliko rekata ima vitr-namaz?"},{"answer":"Jacija","options":["Ikindija","Magrib","Jacija","Fajr"],"question":"Koji namaz je peti namaz tijekom dana?"}]},{"nivo":21,"slug":"el-maun","naslov":"Učenje sure El-Māūn","content_html":"<div class=\"lesson-container\">\n<h1>SURA EL-MÃ'ŨN</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sura_el_maun.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure El-Māūn</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje milosti prema siromašnima, siročadima i potrebnima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst i značenje sure El-Māūn (107. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da pravilno uče suru El-Māūn</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, znate li suru koja Allah ukorava one koji griješe siromašne i siročad? Sura El-Māūn. Hajde da je danas naučimo.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura El-Māūn je 107. sura Kur’ana, ima 7 ajeta.</p><p>Tekst (početak): <em>Eraejtelleđī jukezzibu bid-dīn. Fezālikelleđī jedu‘ul-jetīm. Ve lā jehuddu ‘alā ta‘āmil-miskīn...</em></p><p>Značenje: <em>\"Vidiš li onoga koji poricanje sudnjeg dana smatra? To je onaj koji odbija siroče i koji druge ne sokoli da nahrane potrebnoga...\"</em></p><p>Poruka: prava vjera nije samo namaz nego i briga za siromašne, siročad i potrebne. Ko se klanja, a ne pomaže drugima – njegov namaz nije primljen.</p><p>Postupak: Pišem suru na tabli arapski + transkripcija. Učenici slušaju izgovor, ponavljaju ajet po ajet.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče prva tri ajeta. Razgovor: kako možemo pomoći siromašnima u našoj okolini?</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":49,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Koji je redni broj sure El-Ma'un u Kur'anu?\",\"odgovori\":[\"105\",\"106\",\"107\",\"108\"],\"tacanOdgovor\":2},{\"pitanje\":\"Koliko ajeta ima sura El-Ma'un?\",\"odgovori\":[\"3\",\"5\",\"7\",\"10\"],\"tacanOdgovor\":2},{\"pitanje\":\"Šta znači riječ 'ma'un'?\",\"odgovori\":[\"Veliko blago\",\"Mala pomoć, uobičajeno\",\"Namaz\",\"Post\"],\"tacanOdgovor\":1},{\"pitanje\":\"Koga Allah upozorava u suri El-Ma'un?\",\"odgovori\":[\"One koji klanjaju iskreno\",\"One koji su nemarni u namazu i ne pomažu drugima\",\"Učene ljude\",\"Djecu\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta radi onaj ko poriče Sudnji dan prema ovoj suri?\",\"odgovori\":[\"Klanja namaz\",\"Grubo odbija siroče\",\"Pomaže siromašnima\",\"Daje sadaku\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta znači 'jura'un' u kontekstu ove sure?\",\"odgovori\":[\"Iskreno klanjaju\",\"Pretvaraju se\",\"Poste\",\"Uče Kur'an\"],\"tacanOdgovor\":1}]"},{"nivo":21,"slug":"dzuma-namaz","naslov":"Džuma-namaz","content_html":"<div class=\"lesson-container\">\n<h1>DŽUMA-NAMAZ</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/dzuma_namaz.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Džuma-namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema petku i jedinstvu zajednice na džumi</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti šta je džuma, kada se klanja i koja su njena pravila</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti dječake da redovno odlaze na džumu</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, koji je dan u sedmici poseban za muslimane? Petak! A šta posebno radimo petkom u podne? Klanjamo džumu. Šta je džuma?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Džuma-namaz je farz svakom punoljetnom, zdravom muslimanu (muškarcu) – klanja se petkom u vrijeme podne, u džamiji u džematu.</p><p>Sastoji se od dvije hutbe (govora) imama i 2 rekata farza koja se klanjaju iza imama.</p><p>Pravila: očistiti se (kupanje – gusul preporučen petkom), obući lijepu odjeću, namirisati se, doći ranije u džamiju, slušati hutbu pažljivo.</p><p>Vrijednost: Poslanik, a.s., je rekao: <em>\"Petak je najbolji dan u sedmici – tada je Adem stvoren, tada je on uveden u Džennet i tada će biti Sudnji dan.\"</em></p><p>Žene nisu obavezne klanjati džumu, ali im je dozvoljeno da prisustvuju.</p><p>Postupak: Razgovor o tome šta sve uradimo prije polaska na džumu.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici opisuju svoj odlazak na džumu. Zaključak: džuma je susret muslimana, ne propuštajmo je.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Jednog dana muallim je došao na čas i upitao učenike:</p><p>- Djeco, recite mi – koji je najposebniji dan u sedmici za muslimane?</p><p>- Petak.</p><p>- A šta se tada posebno klanja?</p><p>- Džuma-namaz. </p><p>Danas ćemo naučiti zašto je džuma toliko važna, ko je dužan da je klanja i kako se ona obavlja. Vidjet ćete da džuma nije samo namaz, nego i posebno okupljanje muslimana i prilika da nešto novo naučimo kroz hutbu.</p><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Džuma-namaz je sedmični namaz koji se klanja petkom u vrijeme podne-namaza, a dužni su ga klanjati svi punoljetni i umno zdravi muslimani. Muslimanke mogu klanjati džuma-namaz, ali nisu obavezne.</p><p>Da bi se džuma-namaz mogla klanjati, potrebne su najmanje četiri osobe: imam i tri muške osobe ‒ muktedije.</p><p>Džuma-namaz se sastoji od šesnaest rekata: četiri rekata sunneta, dva rekata farza, četiri rekata sunneta, četiri rekata ahiriz-zuhra i dva rekata sunnetil-vakta.</p><p><strong>Način klanjanja džuma-namaza:</strong></p><ul><li><p>Prouči se prvi ezan i to je poziv džematlijama da dođu na džuma-namaz.</p></li><li><p>Nakon ezana klanjaju se četiri rekata sunneta ‒ na isti način kako se klanjaju i sunneti podne-namaza. Nijet za sunnet džuma-namaza glasi:</p></li></ul><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">NEVEJTU EN USALLIJE LILLĀHI TEĀLĀ SALĀTE SUNNETIL-DŽUMUATI EDĀEN MUSTAKBILEL-KIBLETI ALLĀHU EKBER!</mark></strong></p><ul><li><p>Prouči se drugi ezan, a nakon ezana imam održi hutbu.</p></li><li><p>Nakon hutbe klanjaju se dva rekata farza koji se moraju klanjati u džematu za imamom. Nijet za farz džuma-namaza glasi:</p></li></ul><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">NEVEJTU EN USALLIJE LILLĀHI TEĀLĀ SALĀTE FARDIL-DŽUMUATI EDĀEN MUSTAKBILEL-KIBLETI IKTEDEJTU BIHĀZEL-IMĀMI ALLĀHU EKBER!</mark></strong></p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong><br>Hutba je obraćanje imama, tj. predavanje koje imam održi prisutnim, a džematlije su obavezni saslušati hutbu imama.</p></div><ul><li><p>Nakon klanjanja džumanskog farza, klanja se deset rekata: četiri rekata sunneta, četiri rekata ahiriz-zuhri i dva rekata sunnetil-vakti.</p></li><li><p>Četiri rekata sunneta klanjaju se kao podnevski sunnet, a nijet glasi:</p></li></ul><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">NEVEJTU EN USALLIJE LILLĀHI TEĀLĀ SALĀTE SUNNETIL-DŽUMUATI EDĀEN MUSTAKBILEL-KIBLETI ALLĀHU EKBER!</mark></strong></p><ul><li><p>Četiri rekata ahiriz-zuhri klanjaju se kao farzi podne-namaza, a nijet glasi:</p></li></ul><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">NEVEJTU EN USALLIJE LILLĀHI TEĀLĀ SALĀTE ĀHIRIZ-ZUHRI EDĀEN MUSTAKBILEL-KIBLETI ALLĀHU EKBER!</mark></strong></p><ul><li><p>Dva rekata sunnetil-vakti se klanjaju kao sabahski sunnet, a nijet glasi:</p></li></ul><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">NEVEJTU EN USALLIJE LILLĀHI TEĀLĀ SALĀTE SUNNETIL-VAKTI EDĀEN MUSTAKBILEL-KIBLETI ALLĀHU EKBER.</mark></strong></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol><li><p>Šta je džuma-namaz?</p></li><li><p>Ko je dužan klanjati džuma-namaz?</p></li><li><p>Koliko je najmanje osoba potrebno za džuma-namaz?</p></li><li><p>Koliko rekata ima džuma-namaz i kako se dijele?</p></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">IZABERI ZADAĆU!</mark></strong></p><ol><li><p>Napravi pano, uporedi podne-namaz i džuma-namaz koristeći slike i nacrtano u kvadratima.</p></li><li><p>Pronađi i napiši na listu bloka ajet koji govori o obaveznosti klanjanja džuma-namaza. Uz dogovor sa muallimom, postavi ga na oglasnu ploču svoga džemata. Neka svake sedmice to uradi drugi učenik.</p></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":52,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Koji dan se klanja džuma-namaz?\",\"odgovori\":[\"Ponedjeljak\",\"Srijeda\",\"Petak\",\"Nedjelja\"],\"tacanOdgovor\":2},{\"pitanje\":\"Koliko rekata farza ima džuma-namaz?\",\"odgovori\":[\"2\",\"3\",\"4\",\"6\"],\"tacanOdgovor\":0},{\"pitanje\":\"Šta je hutba?\",\"odgovori\":[\"Dova\",\"Propovijed prije farza\",\"Sura\",\"Namaz\"],\"tacanOdgovor\":1},{\"pitanje\":\"Koliko dijelova ima hutba?\",\"odgovori\":[\"1\",\"2\",\"3\",\"4\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta treba raditi za vrijeme hutbe?\",\"odgovori\":[\"Pričati\",\"Šutjeti i slušati\",\"Klanjati\",\"Učiti Kur'an\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta se dešava ko izostavi 3 džume uzastopno?\",\"odgovori\":[\"Ništa\",\"Srce mu se zapečati\",\"Mora platiti kaznu\",\"Mora napostiti\"],\"tacanOdgovor\":1},{\"pitanje\":\"U kojoj suri Allah naređuje da se pohita na džumu?\",\"odgovori\":[\"El-Fatiha\",\"El-Bekare\",\"El-Džumu'a\",\"En-Nas\"],\"tacanOdgovor\":2}]"},{"nivo":21,"slug":"bajram-namaz","naslov":"Bajram-namaz","content_html":"<div class=\"lesson-container\">\n<h1>BAJRAM-NAMAZ</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/bajram_namaz.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Bajram-namaz</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje radosti zbog Bajrama i ljubavi prema zajedničkom slavlju</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti kada se klanja Bajram-namaz i kako se obavlja</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike za pravilno obavljanje Bajram-namaza</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, kakav je Bajram dan? Najradosniji u godini! Šta radimo na Bajram ujutro? Klanjamo Bajram-namaz. Kako se on klanja?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Bajram-namaz je vadžib, klanja se dva puta u godini: na Ramazanski Bajram (poslije mjeseca posta) i na Kurban Bajram.</p><p>Vrijeme: ujutro, otprilike 30 minuta nakon izlaska sunca, do tačnog podne.</p><p>Struktura: 2 rekata, klanja se u džematu sa dodatnim tekbirima – po 3 dodatna na svakom rekatu (ukupno 6 dodatnih).</p><p>Nakon namaza imam drži hutbu – objašnjava značaj Bajrama i podsjeća na obaveze.</p><p>Bajram-namaz se klanja u džamiji ili na otvorenom mušalli. Žene i djeca mogu prisustvovati.</p><p>Postupak: Demonstracija dodatnih tekbira. Razgovor o tradiciji klanjanja Bajram-namaza u našim krajevima.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici opisuju svoj posljednji Bajram. Zaključak: Bajram je dar od Allaha – proslavimo ga ibadetom i lijepim druženjem.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":53,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Koliko bajrama slave muslimani?\",\"odgovori\":[\"1\",\"2\",\"3\",\"4\"],\"tacanOdgovor\":1},{\"pitanje\":\"Koliko rekata ima bajram-namaz?\",\"odgovori\":[\"2\",\"3\",\"4\",\"6\"],\"tacanOdgovor\":0},{\"pitanje\":\"Bajram-namaz je:\",\"odgovori\":[\"Farz\",\"Sunnet\",\"Vadžib\",\"Mubah\"],\"tacanOdgovor\":2},{\"pitanje\":\"Koliko dodatnih tekbira se izgovori na svakom rekatu bajram-namaza?\",\"odgovori\":[\"1\",\"2\",\"3\",\"5\"],\"tacanOdgovor\":2},{\"pitanje\":\"Šta je sunnet na Ramazanski bajram prije namaza?\",\"odgovori\":[\"Ne jesti ništa\",\"Pojesti nešto\",\"Klanjati 4 rekata\",\"Učiti Kur'an\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta je sunnet na Kurban-bajram prije namaza?\",\"odgovori\":[\"Pojesti nešto\",\"Ne jesti ništa\",\"Okupati se dva puta\",\"Klanjati nafilu\"],\"tacanOdgovor\":1},{\"pitanje\":\"Kako se čestita bajram?\",\"odgovori\":[\"Selam alejkum\",\"Bajram šerif mubarek olsun\",\"Mašallah\",\"Eid Mubarak\"],\"tacanOdgovor\":1}]"},{"nivo":21,"slug":"el-kurejs","naslov":"Učenje sure El-Kurejš","content_html":"<div class=\"lesson-container\">\n<h1>SURA EL-KUREJŠ</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/sura_el_kurejsh.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Učenje sure El-Kurejš</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje zahvalnosti Allahu na sigurnosti i opskrbi</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti tekst i značenje sure El-Kurejš (106. sura Kur’ana)</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da pravilno uče suru El-Kurejš</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko su bili Kurejšije? Pleme Poslanika, a.s., u Mekki. Allah im je dao posebne blagodati. O njima govori sura El-Kurejš.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Sura El-Kurejš je 106. sura Kur’ana, ima 4 ajeta.</p><p>Tekst: <em>Liīlāfi Kurejš. Īlāfihim rihleteš-šitāi ves-sajf. Felja‘budū rabbe hāzel-bejt. Ellezī at‘amehum min džū‘in ve āmenehum min havf.</em></p><p>Značenje: <em>\"Zbog navike Kurejšija, navike njihove na putovanje zimi i ljeti, neka oni samo Gospodara ovoga Hrama obožavaju, koji ih hrani od gladi i sigurnošću ih obasipa, mjesto straha.\"</em></p><p>Poruka: Kurejšije su imale dvije velike blagodati – sigurnost i opskrbu. Trebali su za to biti zahvalni Allahu.</p><p>Sura nas uči zahvalnosti za blagodati koje često uzimamo zdravo za gotovo: zdravlje, hrana, sigurnost.</p><p>Postupak: Pišem suru na tabli, učenici slušaju i ponavljaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici uče suru zajedno. Razgovor: koje blagodati ja imam danas za koje trebam biti zahvalan?</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":54,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Koji je redni broj sure El-Kurejš u Kur'anu?\",\"odgovori\":[\"104\",\"105\",\"106\",\"107\"],\"tacanOdgovor\":2},{\"pitanje\":\"Koliko ajeta ima sura El-Kurejš?\",\"odgovori\":[\"3\",\"4\",\"5\",\"7\"],\"tacanOdgovor\":1},{\"pitanje\":\"Ko su Kurejšije?\",\"odgovori\":[\"Narod u Medini\",\"Pleme Poslanika, čuvari Kabe\",\"Stanovnici Taifa\",\"Ashabi\"],\"tacanOdgovor\":1},{\"pitanje\":\"Kuda su Kurejšije putovali zimi?\",\"odgovori\":[\"U Šam\",\"U Jemen\",\"U Medinu\",\"U Egipat\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta Allah kaže da je dao Kurejšijama?\",\"odgovori\":[\"Bogatstvo i slavu\",\"Hranu i sigurnost\",\"Vojsku i oružje\",\"Znanje i mudrost\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta Allah traži od Kurejšija u zamjenu?\",\"odgovori\":[\"Da putuju više\",\"Da obožavaju Gospodara Kabe\",\"Da grade gradove\",\"Da ratuju\"],\"tacanOdgovor\":1}]"},{"nivo":21,"slug":"elif-lam-mim","naslov":"Elif-lām-mīm","content_html":"<div class=\"lesson-container\">\n<h1>ELIF-LÃM-MĨM – PRVIH 5 AJETA SURE EL-BEKARE</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/elif_lam_mim.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Elif-lām-mīm – početak sure El-Bekare</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Kur’an</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema Kur’anu i poštovanja prema njegovim tajnama</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razumjeti pojam mukatte‘a-harfova (skraćenih harfova) i naučiti tekst početka sure El-Bekare</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da pravilno izgovaraju i uče početak sure El-Bekare</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li ste znali da su neke sure Kur’ana počinju misterioznim slovima koje samo Allah razumije? Jedan od takvih je \"Elif-lām-mīm\". Šta to znači?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>\"Elif-lām-mīm\" su slova koja se nalaze na početku 29 sura u Kur’anu. Zovemo ih <strong>mukatte‘a</strong> (rastavljena slova) ili <strong>hurūfu-l-mukatte‘a</strong>.</p><p>Njihovo pravo značenje zna samo Allah – ona su jedna od mu’džiza (čuda) Kur’ana.</p><p>U suri El-Bekare prvi ajet je \"Elif-lām-mīm\", drugi ajet glasi: <em>\"Zālikel-kitābu lā rejbe fīhi, hudel-lil-muttekīn\"</em> – Ova knjiga, u koju nema sumnje, uputa je onima koji se boje Allaha.</p><p>Učimo prvih 5 ajeta sure El-Bekare gdje se opisuju vjernici i njihova svojstva.</p><p>Postupak: Pišem ajete arapskim pismom + transkripcija. Učimo izgovor i značenje. Učenici ponavljaju.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici proučavaju ajete. Zaključak: u Kur’anu ima mnogo tajni koje samo Allah zna – mi učimo i izvršavamo ono što razumijemo.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Kada čovjek traži uputu u životu, često se pita gdje može pronaći siguran i ispravan put. Ljudi traže savjete, pravila i smjernice, ali nijedna knjiga ne može dati ono što daje Kur’an – jasnu i sigurnu uputu.</p><p>U ovoj lekciji upoznat ćemo prve ajete najduže sure u Kur’anu, koji govore o tome ko su pravi vjernici i kakve osobine imaju. Ovi ajeti nam pokazuju put kojim trebamo ići kako bismo uspjeli i na ovom i na budućem svijetu.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Prvih pet ajeta sure El-Bekare, najduže sure u Kurʼanu, objavljene u Medini, sadrži 286 ajeta.</p><div class=\"arabic-card\"><p style=\"text-align: center;\"><strong>BISMILLAHIR-RAHMANIR-RAHIM</strong></p><p style=\"text-align: center;\"><strong>ELIF LAM MIM</strong></p><p style=\"text-align: center;\"><strong>ZALIKEL-KITABU LA REJBE, FIHI, HUDEN LIL-MUTTEKIN</strong></p><p style=\"text-align: center;\"><strong>ELLEZINE JU’MINUNE BIL-GAJBI VE JUKIMUNES-SALATE VE MIMMA REZAKNA HUM JUNFIKUN</strong></p><p style=\"text-align: center;\"><strong>VELLEZINE JU’MINUNE BIMA UNZILE ILEJKE VE MA UNZILE MIN KABLIKE, VE BIL-AHIRETI HUM JUKINUN</strong></p><p style=\"text-align: center;\"><strong>ULA’IKE ‘ALA HUDEN MIR-RABBIHIM VE ULA’IKE HUMUL-MUFLIHUN</strong></p></div><p></p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>Prijevod</strong>:</p><p style=\"text-align: center;\">U ime Allaha, Milostivog, Samilosnog!</p><p style=\"text-align: center;\">Elif Lām Mīm.</p><p style=\"text-align: center;\">Ova Knjiga, u koju nema nikakve sumnje, uputstvo je svima onima koji se budu Allaha bojali;</p><p style=\"text-align: center;\">Onima koji u nevidljivi svijet budu vjerovali i molitvu obavljali i udjeljivali dio od onoga što im Mi budemo davali.</p><p style=\"text-align: center;\">I onima koji budu vjerovali u ono što se objavljuje tebi i u ono što je objavljeno prije tebe, i onima koji u onaj svijet budu čvrsto vjerovali.</p><p style=\"text-align: center;\">Njima će Gospodar njihov na Pravi put ukazati i oni će ono što žele ostvariti.</p></div><p>U prvim ajetima ove sure Allah, dž.š., govori o svojoj knjizi Kurʼanu u koju vjernici vjeruju bez ikakve sumnje i koja je uputstvo bogobojaznima. Bogobojazni su oni koji vjeruju u neviđeno, klanjaju namaz, dijele od onoga što im je Allah, dž.š., dao, zatim vjeruju u objavu koja je data Muhammedu, a.s., i objave koje su objavljene prije Muhammeda, a.s., te čvrsto vjeruju u budući svijet.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PROSIRIMO', this)\">PROŠIRIMO ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"PROSIRIMO\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p class=\"lesson-text\">Allah, dž.š., kaže: \"Ovo je Knjiga u kojoj nema sumnje; uputa je za one koji se Allaha boje – koji vjeruju u nevidljivo, koji molitvu obavljaju i koji od onoga što im Mi dajemo udjeljuju.\" (El-Bekare, 2-3)</p></div>\n                <div class=\"arabic-card\"><p class=\"lesson-text\">Poslanik, alejhis-selam, je rekao: \"Ko prouči dva ajeta s kraja sure El-Bekare, dovoljna mu je zaštita.\" (Buhari)</p></div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">MINI KVIZ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol class=\"lesson-text\">\n                <li>Šta su tajanstvena slova i što znamo o njima?</li>\n                <li>Ko su muttekini opisani u ovim ajetima?</li>\n                <li>Šta su obilježja pravog vjernika prema ovim ajetima?</li>\n                <li>Zašto je sura El-Bekare posebno važna?</li>\n                </ol>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":59,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Šta su huruf-i mukattaat?\",\"odgovori\":[\"Ajeti\",\"Odvojena slova na početku nekih sura\",\"Hadisi\",\"Dove\"],\"tacanOdgovor\":1},{\"pitanje\":\"Na početku koliko sura se nalaze huruf-i mukattaat?\",\"odgovori\":[\"10\",\"19\",\"29\",\"50\"],\"tacanOdgovor\":2},{\"pitanje\":\"Kako se čitaju huruf-i mukattaat?\",\"odgovori\":[\"Spojeno kao riječ\",\"Pojedinačno, svako slovo zasebno\",\"Šapatom\",\"Ne čitaju se\"],\"tacanOdgovor\":1},{\"pitanje\":\"Koja sura počinje sa Elif-Lam-Mim?\",\"odgovori\":[\"El-Fatiha\",\"El-Bekare\",\"El-Ihlas\",\"En-Nas\"],\"tacanOdgovor\":1},{\"pitanje\":\"Ko zna pravo značenje huruf-i mukattaat?\",\"odgovori\":[\"Učenjaci\",\"Hafizi\",\"Samo Allah\",\"Poslanici\"],\"tacanOdgovor\":2}]"},{"nivo":21,"slug":"mubarek-noci","naslov":"Važnost mubarek-noći","content_html":"<div class=\"lesson-container\">\n<h1>MUBAREK-NOĆI</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/mubarek_noci.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Važnost mubarek-noći</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Akaid/Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema mubarek-noćima i navike pojačanog ibadeta u njima</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti koje su mubarek-noći u islamu i njihov značaj</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Pripremiti učenike za ibadet u mubarek-noćima</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, da li su sve noći iste? Postoje noći u kojima je dovi posebno primljena, ibadet posebno nagrađen. Zovemo ih mubarek-noći. Koje su to noći?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Mubarek-noći su posebne, blagoslovljene noći u kojima Allah daje posebnu nagradu za ibadet.</p><p>Najvažnije mubarek-noći su:</p><p><strong>Lejletul-Kadr</strong> – Noć Kadra (u zadnjih 10 noći Ramazana, najvjerovatnije 27. noć) – vrednija od hiljadu mjeseci.</p><p><strong>Lejletul-Berāet</strong> – 15. noć ša‘bana – noć opraštanja grijeha.</p><p><strong>Lejletul-Mi‘rāj</strong> – 27. noć redžeba – noć Poslanikovog uzdizanja na nebo.</p><p><strong>Lejletur-Regāib</strong> – prvi petak u noći redžeba – noć blagoslova.</p><p>U ovim noćima se uče dove, klanjaju nafile, čita Kur’an, uči zikr i traži oprost.</p><p>Najveće blago: u Noći Kadra Allah oprašta sve grijehe onome ko klanja i moli iskreno.</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju mubarek-noći. Zaključak: ove noći su Allahov dar – iskoristimo ih za bliskost sa Njim.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>U toku godine postoje posebni dani i noći koje ljudi posebno iščekuju i pamte. I u islamu postoje odabrani trenuci koji imaju posebnu vrijednost i u kojima se Allahova milost posebno spušta na ljude. To su mubarek-noći – noći u kojima se vjernici više okreću ibadetu, dovi i razmišljanju o svom odnosu prema Allahu.</p><p>U ovoj lekciji upoznat ćemo najvažnije mubarek-noći i njihovu vrijednost, kao i način na koji ih muslimani obilježavaju.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Mubarek-noći su noći koje, kao odabrano vrijeme, prema hidžretskom kalendaru, imaju značajniju vrijednost od drugih noći. Za neke noći i njihovu izuzetnu vrijednost postoji potvrda u Kurʼanu i vjerodostojnim hadisima Muhammeda, a.s. One su i izraz velike Božije milosti prema ljudima.</p><p>Mubarek noći su:</p><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">LEJLETUL-KADR</mark></strong></p><p>Lejletul-kadr je noć utemeljena na Kurʼanu i hadisu.</p><div class=\"arabic-card\"><p>Allah, dž.š., kaže: Mi smo ga (Kurʼan) počeli objavljivati u noći Kadr. A šta ti misliš šta je noć Kadr? Noć Kadr je bolja od hiljadu mjeseci, meleki i Džibril, s dozvolom Gospodara svoga, spuštaju se u njoj zbog odluke svake. Sigurnost je u njoj sve dok zora ne svane. (El-Kadr, 1-5)</p></div><p>Ovo je najznačajnija noć u godini zbog toga što je u njoj počela objava Kurʼana. Nije precizno naznačeno kada ona nastupa, ali se, na osnovu Kurʼana i hadisa, pretpostavlja da je to 27. noć mjeseca ramazana.</p><p>Poslanik, a.s., nas uči: “Tražite noć Kadr u neparnim noćima posljednjih deset dana ramazana.” (Buhari)</p><p>Vrijednost od hiljadu mjeseci koja se spominje u Kurʼanu za tu noć približno iznosi 83 godine ‒ što je veći vremenski period od jednog prosječnog ljudskog života.</p><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">LEJLETUL-MI‘RADŽ</mark></strong></p><p>Ova mubarek-noć je spomenuta i u Kurʼanu i hadisu. U Kurʼanu Uzvišeni Allah kaže:</p><p>Hvaljen neka je Onaj koji je u jednom času noći preveo Svoga roba iz Hrama časnog (Kabe) u Hram daleki (Kuds), čiju smo okolinu blagoslovili kako bismo mu neka znamenja Naša pokazali. On, uistinu, sve čuje i sve vidi. (El-Isrãʼ, 1)</p><p>U ovoj noći, 27. redžeba 621. desila su se dva putovanja Muhammeda, a.s.: Isra i Mi‘radž. Isra je putovanje od Kabe u Mekki do džamije El-Aksa u Jerusalemu.</p><p>Mi‘radž je putovanje u kome je Muhammed, a.s., uzdignut kroz sedam nebesa do Sidretul-muntehaa. Tada je Muhammed, a.s., razgovarao sa Allahom, dž.š., vidio Džennet i Džehennem.</p><p>Posebna blagodat ove noći je namaz.</p><p>Mevludski programi u našim džamijama su najčešće svečanosti u mubarek-noćima.</p><div class=\"info-card\"><p style=\"text-align: center;\"><strong>MEVLUD – MI‘RADŽ</strong></p><p style=\"text-align: center;\">Hodi amo koji žudi i želi, da je ašik i sam sebi što veli.</p><p style=\"text-align: center;\">Slušaj miradž pejgamberski golemi, za ašikluk tebi srce što gori.</p><p style=\"text-align: center;\">Ponedeljnik večer dođe jedan glas, noć je blaga i hairli baš za nas.</p><p style=\"text-align: center;\">Oni što su s njime Božije pomoći, Ummihani ode kući po noći.</p><p style=\"text-align: center;\">Muhammedu dobar ta’zim kod Boga, Džebrailu emer dođe od Boga.</p><p style=\"text-align: center;\">Kat haljina iz dženneta prihvati, i buraka najboljega uhvati.</p><p style=\"text-align: center;\">Mome milom Muhamedu odvedi, Mene i Arš on da vidi, dovedi.</p></div><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">LEJLETUL-BERAT</mark></strong></p><p>Lejletul-berat je petnaesta noć mjeseca ša‘bana. U ovoj noći se izvrši raspored događanja za narednu godinu, a u Lejletul-kadru melekima bude naređeno da to izvrše.</p><p>Noć Lejletul-berat ima više imena: Noć polovine ša‘bana, Noć oprosta, Noć oslobođenja, Noć izlaganja djela, Noć rasporeda i odluke.</p><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">LEJLETUR-REGAIB</mark></strong></p><p>Lejletur-regaib se obilježava uoči prvog petka u mjesecu redžebu. Ona se obilježava kao Noć želja. Spominje se da je Amina, majka Muhammeda, a.s., u toj noći osjetila trudnoću.</p><p>U svim mubarek-noćima preporučuju se dobrovoljni ibadeti: nafila-namazi, dove, zikr, učenje Kurʼana. Kod nas, u Bosni i Hercegovini, je običaj da se povodom navedenih odabranih noći u džematima pripreme mevludi i prigodni svečani programi.</p><p>Kako god kandilji na džamijama u odabranim noćima obasjavaju džamiju i okolinu, isto tako zikr, dobrovoljni namaz, ibadet, dova i istigfar obasjavaju čovjekovu dušu.</p><div class=\"info-box\"><p style=\"text-align: center;\"><strong>ZAPAMTI!</strong></p><p style=\"text-align: center;\">Poslanik, a.s., nas uči da učimo sljedeću dovu: “Bože, blagoslovi nas u redžebu i ša‘banu i daj nam da dočekamo ramazan.” (Taberani)</p></div><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PROSIRIMO', this)\">PROŠIRIMO ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"PROSIRIMO\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p class=\"lesson-text\">Allah, dž.š., kaže: \"Noć kadr je bolja od hiljadu noći.\" (El-Kadr, 3)</p></div>\n                <div class=\"arabic-card\"><p class=\"lesson-text\">Poslanik, alejhis-selam, je rekao: \"Tražite Noć kadr u neparnim noćima posljednjih deset dana ramazana.\" (Buhari)</p></div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">MINI KVIZ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol><li><p>Koliko ima mubarek-noći i koje su?</p></li><li><p>U kojoj mubarek-noći je počela objava Kurʼana?</p></li><li><p>Koja mubarek-noć je u mjesecu redžebu, a koja u mjesecu ša‘banu?</p></li><li><p>ZADATAK: Sa muallimom izvježbaj način učenja mevludskog teksta!</p></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">IZABERI ZADAĆU!</mark></strong></p><ol><li><p>Napiši sastav ‒ Ljepota mubarek-noći!</p></li><li><p>Nauči koje su mubarek-noći i prezentiraj svoje znanje o njima u mektebu.</p></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">RAZGOVOR S MUALLIMOM</mark></strong></p><ul><li><p>Mevludski program za mubarek-noć.</p></li></ul><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":60,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Koliko mubarek noći ima u islamu?\",\"odgovori\":[\"3\",\"4\",\"5\",\"7\"],\"tacanOdgovor\":2},{\"pitanje\":\"Koja je najvrjednija noć u godini?\",\"odgovori\":[\"Lejletul-Regaib\",\"Lejletul-Mi'radž\",\"Lejletul-Berat\",\"Lejletul-Kadr\"],\"tacanOdgovor\":3},{\"pitanje\":\"Šta je propisano na Lejletul-Mi'radž?\",\"odgovori\":[\"Post\",\"Namaz\",\"Zekat\",\"Hadž\"],\"tacanOdgovor\":1},{\"pitanje\":\"Koliko mjeseci ibadeta vrijedi Lejletul-Kadr?\",\"odgovori\":[\"100\",\"500\",\"1000\",\"10000\"],\"tacanOdgovor\":2},{\"pitanje\":\"Šta je počelo u noći Kadra?\",\"odgovori\":[\"Hidžra\",\"Objavljivanje Kur'ana\",\"Rođenje Poslanika\",\"Osvajanje Mekke\"],\"tacanOdgovor\":1},{\"pitanje\":\"U kojem mjesecu je Lejletul-Mi'radž?\",\"odgovori\":[\"Ramazan\",\"Šaban\",\"Redžeb\",\"Muharrem\"],\"tacanOdgovor\":2},{\"pitanje\":\"Kada se obilježava Lejletul-Kadr?\",\"odgovori\":[\"1. ramazana\",\"15. šabana\",\"27. ramazana (najvjerovatnije)\",\"1. muharrema\"],\"tacanOdgovor\":2}]"},{"nivo":21,"slug":"nafila","naslov":"Vrste nafila-namaza","content_html":"<div class=\"lesson-container\">\n<h1>NAFILA-NAMAZI</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/nafila_namaz.jpg\">\n        \n\n\n\n\n\n\n\n\n\n\n\n\n<!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Vrste nafila-namaza</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Ibadat</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema dobrovoljnim ibadetima i bliskosti sa Allahom</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Naučiti koje vrste nafila-namaza postoje u islamu</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Osposobiti učenike da klanjaju neke nafile (tehijjetul-mesdžid, duha)</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, znamo farz-namaze. A da li postoje namazi koji nisu obavezni, ali ih klanjamo iz ljubavi prema Allahu? To su nafile. Koje su sve?</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Nafila je dobrovoljni namaz, koji nije obavezan, ali nosi veliku nagradu.</p><p>Vrste nafila:</p><p><strong>Sunneti</strong> – uz farz-namaze (kao 4 prije i 2 poslije podne)</p><p><strong>Tehijjetul-mesdžid</strong> – 2 rekata kad uđeš u džamiju</p><p><strong>Duha-namaz</strong> – između izlaska sunca i podne, 2 do 12 rekata</p><p><strong>Tehedždžud</strong> – noćni namaz, posljednja trećina noći</p><p><strong>Istihara</strong> – namaz pri donošenju važne odluke</p><p><strong>Hādže-namaz</strong> – namaz potrebe</p><p><strong>Šukr-namaz</strong> – namaz zahvale za blagodat</p><p>Vrijednost: Poslanik, a.s., je rekao: <em>\"Moj rob mi se ne približava ničim dražim od onoga što sam mu propisao kao farz, a Mene približava dobrovoljnim ibadetom dok ga ne zavolim.\"</em></p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici biraju jednu nafilu koju će klanjati ovaj tjedan. Zaključak: nafile su znak ljubavi prema Allahu.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n</div>","audio_src":null,"redoslijed":61,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Šta su nafila-namazi?\",\"odgovori\":[\"Obavezni namazi\",\"Dobrovoljni namazi\",\"Zabranjeni namazi\",\"Pokuđeni namazi\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta je tehijjetul-mesdžid?\",\"odgovori\":[\"Noćni namaz\",\"Dva rekata pri ulasku u džamiju\",\"Bajram-namaz\",\"Džuma sunnet\"],\"tacanOdgovor\":1},{\"pitanje\":\"Kada se klanja duha-namaz?\",\"odgovori\":[\"U zoru\",\"Nakon izlaska sunca do pred podne\",\"Pred akšam\",\"U ponoć\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta je teheddžud-namaz?\",\"odgovori\":[\"Jutarnji namaz\",\"Popodnevni namaz\",\"Noćni namaz poslije ponoći\",\"Podnevni namaz\"],\"tacanOdgovor\":2},{\"pitanje\":\"Šta je istihara-namaz?\",\"odgovori\":[\"Namaz za oprost\",\"Namaz za donošenje odluke\",\"Namaz zahvalnosti\",\"Namaz putnika\"],\"tacanOdgovor\":1},{\"pitanje\":\"Klanjanje nafila je:\",\"odgovori\":[\"Farz\",\"Haram\",\"Mustehab (pohvaljeno)\",\"Mekruh\"],\"tacanOdgovor\":2}]"},{"nivo":21,"slug":"alimi","naslov":"Poznati alimi u BiH","content_html":"<div class=\"lesson-container\">\n<h1>POZNATI ALIMI U BOSNI I HERCEGOVINI</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/poznati_alimi.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Poznati alimi u BiH</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka/Historija</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ponosa na bošnjačku islamsku tradiciju i alime</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa najpoznatijim bosanskim alimima i njihovim doprinosom</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje motivacije za sticanje znanja po uzoru na bosanske alime</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, ko su alimi? Učeni ljudi vjere. A da li smo mi u Bosni imali svoje alime? Mnogo! Hajde da upoznamo neke od njih.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Bosna je kroz historiju imala mnogo poznatih alima koji su ostavili veliko djelo iza sebe.</p><p><strong>Hasan Kafi Pruščak</strong> (16. v.) – pisac mnogih djela na arapskom, jedan od najučenijih ljudi svog vremena.</p><p><strong>Husein Đozo</strong> (20. v.) – profesor, urednik, autor brojnih djela; oživio bošnjačku ulemu nakon II. svj. rata.</p><p><strong>Mehmed Handžić</strong> (20. v.) – muhaddis, mufessir; jedan od osnivača Mladih muslimana.</p><p><strong>Muhamed Tajib Okić</strong> (20. v.) – islamski pravnik i alim koji je predavao u Turskoj.</p><p><strong>Mustafa Cerić</strong> (suvremeni) – bivši reisul-ulema, autor mnogih knjiga.</p><p>Današnji alimi nastavljaju ovu tradiciju – mufesiri, hatibi, profesori, muallimi.</p><p>Razgovor: Šta nas alimi uče? Kako da pratimo njihov put?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju neke alime. Zaključak: znanje je naš najveći ponos – učimo i mi po njihovom uzoru.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Nakon Poslanika, a.s., više nije bilo novih poslanika koji bi ljudima prenosili Allahovu objavu. Ipak, uputa nije prestala – ona se nastavila kroz učenjake koji su čuvali i prenosili znanje Kur’ana i sunneta.</p><p>U ovoj lekciji upoznat ćemo neke od istaknutih alima iz Bosne i Hercegovine i vidjeti koliko je njihova uloga važna u očuvanju vjere i identiteta muslimana. Svako drvo ima korijen. Bosanski muslimani imaju svoja duhovna stabla – alime koji su proučavali islam, prevodili Kurʼan i brinuli o zajednici vijekovima. Naučit ćemo o nekim od najistaknutijih alima koji su ostavili trag u historiji Bosne i Hercegovine.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Muhammed, a.s., je posljednji Allahov poslanik i poslije njega nije bilo, niti će biti poslanika. Ipak, odgovornost prenošenja uputa Pravoga puta poslije njega trebaju preuzeti učenjaci ili alimi.</p><p>Također, kurʼanski tekst nam daje do znanja da su alimi na visokim stepenima među ljudima:</p><p>…i Allah će na visoke stepene uzdignuti one među vama koji vjeruju i one kojima je dato znanje. (El-Mudžadele, 11)</p><p>Vjernici su dužni poštovati i uvažavati ulemu i pokoravati im se jer im to Allah, dž.š., naređuje:</p><div class=\"arabic-card\"><p>Allah, dž.š., u Kurʼanu spominje alime ili učene: Allah svjedoči da nema drugog boga osim Njega, a i meleki i učeni, i da On postupa pravedno. Nema boga osim Njega, Silnog i Mudrog. (Alu ‘Imran, 18)</p></div><p>O vjernici, pokoravajte se Allahu i pokoravajte se Poslaniku i predstavnicima vašim. (En-Nisaʼ, 59)</p><p>Mi u Bosni i Hercegovini u svakom periodu imamo istaknute alime, Bošnjake, pa i u ovom današnjem u kome živimo. U nastavku navest ćemo neke od poznatih bosanskohercegovačkih alima.</p><p></p><p><strong>1. REIS DŽEMALUDIN-EF. ČAUŠEVIĆ (1870–1938)</strong></p><p>Rođen je 28. decembra 1870. u Arapuši kraj Bosanske Krupe. Medresu je završio u Bihaću, a Pravni fakultet 1887. godine u Istanbulu. Radio je i kao nastavnik arapskog jezika u Velikoj sarajevskoj gimnaziji u periodu od 1903. do 1905. kada je izabran za člana Ulema-medžlisa. Bio je i profesor na Šerijatskoj sudačkoj školi, a 1913. izabran je za reisul-ulemu.</p><p>Na položaju reisul-uleme u teškom ratnom i poratnom razdoblju Džemaludin Čaušević se predano i dostojanstveno borio za ravnopravnost islama i muslimana.</p><p>S hafizom Muhamedom Pandžom preveo je Kurʼan na bosanski sa sadržajnim uvodom, tumačenjem i bilješkama. Prilagodio je arebicu za potrebe pisanja bosanskim jezikom. Objavio je djela Kratka povijest islama, Bergivija i Tedžvid.</p><p>Hadži Mehmed Džemaludin-ef. Čaušević umro je 28. marta 1938. u Sarajevu i pokopan je u haremu Gazi Husrev-begove džamije.</p><p><strong>2. DERVIŠ-EF. SPAHIĆ (1893–1978)</strong></p><p>Godine 1893. u Pojskama, u porodici Spahića, rođen je Derviš koji će postati najglasovitiji izdanak ove porodice. Derviš-ef. je do svoje 11. godine živio u Pojskama, a u naredne tri decenije biva vezan za Travnik, njegovu medresu i glasovitu ulemu.</p><p>U medresi je bio deset godina, a 1914. se zapošljava kao imam u džamiji Kahvica. U svom rodnom mjestu 1934. godine osniva medresu i taj poduhvat ga je uzdigao među istaknute ličnosti. Godine 1947. vlasti su među mnogobrojnim medresama zatvorile i pojščansku medresu. Derviš-ef. biva osuđen na osam godina zatvora.</p><p>Nakon dolaska iz zatvora, povlači se u svoje Pojske i bavi se pisanjem. Napisao je dvije knjige: Imanski i islamski šarti i Pouka o moralu i bogobojaznosti. Derviš-ef. je na bolji svijet preselio 1978. godine u 85. godini života.</p><p><strong>3. BESIM EF. KORKUT (1904–1975)</strong></p><p>Besim Korkut rođen je 25. novembra 1904. Pohađao je Ruždiju u Travniku, a Okružnu medresu završio je u Sarajevu. Upisao je i Šerijatsko-sudačku školu, a po njenom završetku 1925. otišao je u Kairo.</p><p>Na El-Azharu je studirao islamske nauke. Diplomirao je 1931. i potom se vraća u domovinu gdje radi kao nastavnik u Šerijatsko-sudačkoj školi u Sarajevu.</p><p>Izradio je udžbenik “Istorija islama”, ali i “Gramatiku arapskog jezika”. Preveo je Kurʼan na bosanski jezik i njegov prijevod je najčitaniji u Bosni i Hercegovini. Na prevođenju Časnog Kurʼana radio je više od jedne decenije, ali nije dočekao njegovo štampanje. Preselio je na bolji svijet novembra 1975. godine.</p><p><strong>4. HUSEIN-EF. ĐOZO (1912–1982)</strong></p><p>Hadži Husein-ef. Đozo rođen je 1912. godine u Barama kod Goražda. Pohađao je Medresu “Mehmed-paše Kukavice” u Foči, a potom Gazi Husrev-begovu medresu u Sarajevu.</p><p>Nakon medrese završio je Šerijatsko-sudačku školu 1933. godine. Sljedeće, 1934. godine otišao je u Kairo i upisao El-Azhar na kojem je diplomirao 1939. godine.</p><p>Po povratku u Sarajevo radio je kao profesor arapskog jezika, a 1941. godine postavljen je za vjersko-prosvjetnog referenta u Uredu reisul-uleme. Po osnivanju Islamskog teološkog fakulteta u Sarajevu, Husein-ef. Đozo biva postavljen za profesora.</p><p>Duži niz godina radio je na projektu osnivanja islamskih informativnih novina “Preporod”, ali i na projektu Prijevoda Kurʼana s komentarom i tumačenjem.</p><p><strong>5. HASAN-EF. ŠKAPUR (1913–1975)</strong></p><p>Hasan Škapur rođen je u Tešnju 1913. godine, a Gazi Husrev-begovu medresu završio je 1935. Na Višoj islamskoj šerijatsko-teološkoj školi diplomirao je 1939.</p><p>Predavao je u Bihaćkoj medresi, zatim u Državnoj realnoj gimnaziji u Banjaluci i Trgovačkoj akademiji. Obavljao je i dužnost kustosa Zavičajnog muzeja u Prijedoru.</p><p>Radom u toj ustanovi počeo se baviti historijom Bosne i Hercegovine. Preveo je i komentarisao prva tri toma Buharijine zbirke hadisa.</p><p>Umro je 1975. godine u Prijedoru. Od 2005. godine Medžlis IZ Tešanj dodjeljuje priznanje “Hasan Škapur” za doprinos u razvoju hadiske znanosti.</p><p><strong>6. KASIM-EF. HADŽIĆ (1917–1990)</strong></p><p>Hadži Kasim-ef. Hadžić rođen je u Zaostru kod Priboja 19. decembra 1917. godine. Nakon mekteba i osnovne škole završio je medresu u Skoplju 1937. godine.</p><p>Iste godine upisuje Višu islamsku šerijatsko-teološku školu u Sarajevu. Godine 1947. osuđen je na dvanaest godina zatvora.</p><p>Vraća se u Islamsku zajednicu i to u Gazi Husrev-begovu medresu 1967. godine. Pokrenuo je list za učenike medrese “Zem-Zem”.</p><p>Kao profesor medrese radio je do odlaska u penziju 1978. godine. Kasim-ef. Hadžić preselio je na ahiret, nakon kraće i teške bolesti, 1990. godine.</p><p><strong>7. DR. AHMED SMAJLOVIĆ (1938–1988)</strong></p><p>Rođen je 17. juna 1938. godine u selu Tokoljak kod Srebrenice kao najmlađe od sedmoro djece. Završio je Gazi Husrev-begovu medresu u Sarajevu.</p><p>Godine 1962. odlazi u Kairo gdje se upisuje na Univerzitet El-Azhar i predstavlja prvu grupu poslijeratnih bosanskohercegovačkih studenata na tom univerzitetu.</p><p>Na Univerzitetu El-Azhar 1968. diplomirao je arapski jezik i književnost, nakon čega nastavlja dalje obrazovanje na magistarskom studiju na istom univerzitetu.</p><p>Jedan je od rijetkih bosanskohercegovačkih studenata koji je sva tri ciklusa visokoškolskog obrazovanja završio u Kairu, gdje je 1974. godine odbranio i doktorsku disertaciju. Bio je prvi doktor nauka u Islamskoj zajednici.</p><p>Godine 1978. pokrenuo je časopis “Islamska misao”. Zbog velikog doprinosa u izgradnji Islamskog centra u Zagrebu, današnja bošnjačka gimnazija u Zagrebu nosi njegovo ime.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PROSIRIMO', this)\">PROŠIRIMO ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"PROSIRIMO\" class=\"lesson-content\">\n            <div class=\"arabic-card\"><p class=\"lesson-text\">Allah, dž.š., kaže: \"Allah svjedoči da nema drugog boga osim Njega, a i meleki i učeni.\" (Ali Imran, 18)</p></div>\n                <div class=\"arabic-card\"><p class=\"lesson-text\">Poslanik, alejhis-selam, je rekao: \"Učenjaci su nasljednici vjerovjesnika.\" (Ebu Davud)</p></div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <div class=\"quiz-container\" id=\"quiz-box\">\n                    <h2 class=\"quiz-title\">MINI KVIZ</h2>\n                    <div id=\"question-container\">\n                        <p class=\"quiz-question\" id=\"q-text\"></p>\n                        <div class=\"quiz-options\" id=\"q-options\"></div>\n                    </div>\n                    <div id=\"quiz-res\" class=\"quiz-results\"></div>\n                </div>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol><li><p>Ko su alimi i kakav je njihov značaj?</p></li><li><p>Navedi neke od poznatih bosanskih alima.</p></li><li><p>Šta je Besim Korkutov doprinos islamskoj nauci?</p></li><li><p>Zašto trebamo znati o bosanskim alimima?</p></li></ol><p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">IZABERI ZADAĆU!</mark></strong></p><p>Predstavi jednog alima koji potiče iz tvog rodnog mjesta ili rodnog kraja koji nije spomenut.</p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":62,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Ko su alimi?\",\"odgovori\":[\"Ratnici\",\"Islamski učenjaci\",\"Trgovci\",\"Hafizi\"],\"tacanOdgovor\":1},{\"pitanje\":\"Čiji su nasljednici alimi prema hadisu?\",\"odgovori\":[\"Kraljeva\",\"Halifa\",\"Poslanika\",\"Ashaba\"],\"tacanOdgovor\":2},{\"pitanje\":\"Koji mezheb slijedimo u BiH?\",\"odgovori\":[\"Malikijski\",\"Šafijski\",\"Hanbelijski\",\"Hanefijski\"],\"tacanOdgovor\":3},{\"pitanje\":\"Ko je osnivač hanefijskog mezheba?\",\"odgovori\":[\"Imam Malik\",\"Imam Šafija\",\"Imam Ebu Hanifa\",\"Imam Ahmed\"],\"tacanOdgovor\":2},{\"pitanje\":\"Koliko pravnih škola (mezheba) postoji u islamu?\",\"odgovori\":[\"2\",\"3\",\"4\",\"5\"],\"tacanOdgovor\":2},{\"pitanje\":\"Šta alimi rade u zajednici?\",\"odgovori\":[\"Samo klanjaju\",\"Podučavaju, tumače i savjetuju\",\"Samo pišu knjige\",\"Samo putuju\"],\"tacanOdgovor\":1}]"},{"nivo":21,"slug":"bih","naslov":"Moja domovina - BiH","content_html":"<div class=\"lesson-container\">\n<h1>BOSNA I HERCEGOVINA – NAŠA DOMOVINA</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/bosna_hercegovina.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Moja domovina – Bosna i Hercegovina</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka/Kultura</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema domovini i odgovornosti prema njoj</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa BiH kao njihovom domovinom – njena historija, simboli, vrijednosti</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje svijesti o pripadnosti i obavezi izgradnje BiH</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, gdje živimo? U kojoj zemlji? Šta volite kod naše Bosne? Hajde da razgovaramo o našoj domovini.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Bosna i Hercegovina je naša domovina – zemlja u srcu Balkana, sa bogatom historijom dužom od 1000 godina.</p><p>Glavni grad je Sarajevo – grad poznat po toleranciji, gdje su džamija, crkva, sinagoga i katedrala blizu jedna drugoj.</p><p>BiH je multikulturna i multireligijska – u njoj žive Bošnjaci, Srbi, Hrvati i drugi, muslimani, pravoslavni, katolici, jevreji.</p><p>Naša obaveza prema domovini: poštovati, čuvati, raditi za njeno dobro, učiti i biti dobar građanin.</p><p>Poslanik, a.s., je rekao: <em>\"Ljubav prema domovini je dio imana.\"</em></p><p>Razgovor: Šta volim u svom gradu? Šta bih volio promijeniti?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici opisuju jedno mjesto u BiH koje vole. Zaključak: domovinu treba voljeti i raditi za nju – to je naša ljepota.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Svaki čovjek ima mjesto kojem pripada – mjesto gdje se rodio, odrastao i gdje su njegovi korijeni. To mjesto zovemo domovina. Domovina nije samo zemlja u kojoj živimo, nego i osjećaj pripadnosti, ljubavi i odgovornosti prema njoj.</p><p>U ovoj lekciji upoznat ćemo našu domovinu Bosnu i Hercegovinu, njene ljepote i vrijednosti, ali i naše obaveze prema njoj.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Mjesto gdje smo prvi put razveselili roditelje dolaskom na ovaj svijet jeste naša domovina. Nakon rođenja najčešće u svojoj domovini odrastamo i živimo. Ali i kada nam bude sudbina pa je napustimo, volimo je, štitimo i čuvamo. Zato uvijek ponosno kažimo MOJA DOMOVINA JE BOSNA I HERCEGOVINA.</p><p>Da bismo voljeli domovinu potrebno je:</p><ul><li><p>da je upoznamo,</p></li><li><p>cijenimo,</p></li><li><p>da izvršavamo obaveze prema njoj,</p></li><li><p>da poštujemo njene zakone,</p></li><li><p>da je branimo i čuvamo,</p></li><li><p>da je razvijamo i unapređujemo.</p></li></ul><p>Bosna i Hercegovina je smještena u jugoistočnoj Evropi, a graniči s Hrvatskom na sjeveru, sjeverozapadu i jugu, te sa Srbijom i Crnom Gorom na istoku. Najveći dio teritorija čine planine i visoki krš, prekriveni šumama i pašnjacima.</p><p>Najviši vrh je Maglić (2386 metara). Nizine se nalaze na sjeveru i jugozapadu.</p><p>Buško jezero je najveće (umjetno) jezero u Bosni i Hercegovini, a najduža rijeka je Bosna koja protječe samo kroz Bosnu i Hercegovinu.</p><p>Grad Neum je jedini izlaz na more.</p><p>Najveći gradovi Bosne i Hercegovine su: Sarajevo, Tuzla, Zenica, Banja Luka, Mostar i Bihać.</p><div class=\"info-card\"><p style=\"text-align: center;\">Dan državnosti moje domovine Bosne i Hercegovine je 25. novembar. Dan kada su narodi Bosne i Hercegovine izglasali nezavisnost Republike Bosne i Hercegovine je 1. mart 1992.</p><p style=\"text-align: center;\">Glavni grad naše domovine je Sarajevo.</p><p style=\"text-align: center;\">Površina Bosne i Hercegovine je 51.209 kilometara kvadratnih. Prema popisu iz 2013. godine broj stanovnika je 3 miliona 531 hiljada i 159</p></div><p></p><p style=\"text-align: center;\"><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">MOJA JEDINA DOMOVINA ZOVE SE BOSNA I HERCEGOVINA</mark></strong></p><p style=\"text-align: center;\">Moja jedina domovina zove se Bosna.<br>Kroz mene teče bosansko srebro i zlato,<br>njene soli i njen ugalj, njeno željezo<br>i nebrojene druge rude u mome su biću osnova.</p><p style=\"text-align: center;\">Moja jedina domovina je Bosna<br>i drugačije ne more bit!</p><p style=\"text-align: center;\">Kroz mene teče bosanski potok, bunar, vodica,<br>sve bosanske šume i nebo bosansko<br>u mome biću osnova je i drugačije ne more bit!</p><p style=\"text-align: center;\">Moja jedina domovina Bosna puna je mezarluka,<br>bezistana, turbeta, hamama u toplim ljudskim kućama.</p><p style=\"text-align: center;\">Moja jedina domovina je Bosna i drugačije ne more bit!</p><p style=\"text-align: center;\">Moja domovina Bosna ukrašena je pletenicama djevojaka<br>i šamijama na dragim i mudrim glavama nena<br>koje, u glavi svojoj, u kući svojoj i van nje,<br>nose prefinjenu kulturu života. Nene, koje vide daleko, koje nose mudrost<br>i koje pred očima nemaju koprenu ko neki danas.</p><p style=\"text-align: center;\">Moja jedina domovina zove se Bosna<br>i drugačije ne more bit!</p><p style=\"text-align: center;\">Moja domovina Bosna puna je naučnika koji nose ahmedije,<br>puna je naučnika koje ne učimo u školama.<br>Bosanski naučnici žive u sokacima dalekim i nepoznatim.</p><p style=\"text-align: center;\">Moja jedina domovina zove se Bosna<br>i drugačije ne more bit!</p><p style=\"text-align: center;\">Moja jedina domovina je Bosna!<br>To je potvrđeno muhtarskim pečatom moga djeda i pradjeda.<br>To je potvrđeno dimijama mojih tetaka,<br>šamijama i kerama na njima.</p><p style=\"text-align: center;\">Moja jedina domovina je Bosna! ....<br>To je mihrab u koji se ne dira i ne dijeli se ono što je cijelo.</p><p style=\"text-align: center;\">Emir Hadžihafizbegović</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <p><strong><mark data-color=\"#fef08a\" style=\"background-color: rgb(254, 240, 138); color: inherit;\">RAZGOVOR S MUALLIMOM</mark></strong></p><ul><li><p>Koje su pouke poeme o Bosni i Hercegovini?</p></li></ul><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":63,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Kada je islam došao u BiH?\",\"odgovori\":[\"U 10. vijeku\",\"U 13. vijeku\",\"U 15. vijeku\",\"U 18. vijeku\"],\"tacanOdgovor\":2},{\"pitanje\":\"Ko je na čelu Islamske zajednice u BiH?\",\"odgovori\":[\"Muftija\",\"Imam\",\"Reisu-l-ulema\",\"Kadija\"],\"tacanOdgovor\":2},{\"pitanje\":\"Koja je najznačajnija džamija u BiH?\",\"odgovori\":[\"Ferhadija\",\"Gazi Husrev-begova\",\"Aladža\",\"Karadžoz-begova\"],\"tacanOdgovor\":1},{\"pitanje\":\"Kada je osnovana Gazi Husrev-begova medresa?\",\"odgovori\":[\"1431.\",\"1537.\",\"1678.\",\"1878.\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta je mekteb?\",\"odgovori\":[\"Visoka škola\",\"Osnovna vjerska pouka za djecu\",\"Srednja škola\",\"Fakultet\"],\"tacanOdgovor\":1},{\"pitanje\":\"Koji akaid slijede bosanski muslimani?\",\"odgovori\":[\"Ešarijski\",\"Maturidijski\",\"Selefi\",\"Mutezilijski\"],\"tacanOdgovor\":1}]"},{"nivo":21,"slug":"bosanski-jezik","naslov":"Bosanski jezik","content_html":"<div class=\"lesson-container\">\n<h1>BOSANSKI JEZIK I KULTURA</h1><div class=\"hero-box\">\n            <img src=\"/edu/assets/images/bosanski_jezik.jpg\">\n        </div>\n    \n        \n        \n        \n        \n        \n        <!--PRIPREMA-START--><div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n\n      <div style=\"background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: #ffffff; padding: 22px 24px; border-radius: 14px; margin-bottom: 22px; box-shadow: 0 6px 18px rgba(20,184,166,0.25);\">\n        <div style=\"font-size: 1.35rem; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 10px;\">📋 Priprema za nastavu</div>\n        <div style=\"background: rgba(255,255,255,0.18); padding: 12px 16px; border-radius: 10px; margin-bottom: 12px;\">\n          <div style=\"font-size: 0.8rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700;\">Nastavna jedinica</div>\n          <div style=\"font-size: 1.15rem; font-weight: 700; margin-top: 4px;\">Bosanski jezik</div>\n        </div>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px;\">\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Predmet</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Vjeronauka/Kultura</div>\n          </div>\n          <div style=\"background: rgba(255,255,255,0.18); padding: 10px 14px; border-radius: 10px;\">\n            <div style=\"font-size: 0.78rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700;\">Tip sata</div>\n            <div style=\"font-weight: 700; font-size: 1.05rem; margin-top: 3px;\">Obrada novog gradiva</div>\n          </div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🎯 Ciljevi nastavnog sata</h3>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-bottom: 22px;\">\n        <div style=\"background: #fef2f2; border-top: 4px solid #ef4444; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #b91c1c; margin-bottom: 6px; font-size: 0.95rem;\">❤️ Odgojni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje ljubavi prema maternjem jeziku i ponosa na njega</div>\n        </div>\n        <div style=\"background: #eff6ff; border-top: 4px solid #3b82f6; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #1d4ed8; margin-bottom: 6px; font-size: 0.95rem;\">📚 Obrazovni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Upoznati učenike sa bosanskim jezikom – historijom, pismom, značajem</div>\n        </div>\n        <div style=\"background: #f0fdf4; border-top: 4px solid #22c55e; padding: 14px 16px; border-radius: 10px;\">\n          <div style=\"font-weight: 800; color: #15803d; margin-bottom: 6px; font-size: 0.95rem;\">⚙️ Funkcionalni cilj</div>\n          <div style=\"color: #1f2937; line-height: 1.5;\">Razvijanje navike pravilnog korištenja bosanskog jezika</div>\n        </div>\n      </div>\n\n      <h3 style=\"margin: 22px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">🗂️ Organizacija nastave</h3>\n      <div style=\"background: #f8fafc; border: 1px solid #e2e8f0; padding: 16px 18px; border-radius: 10px; margin-bottom: 22px;\">\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #e0f2fe; color: #075985; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Oblici rada</span> Frontalni, individualni</div>\n        <div style=\"margin-bottom: 10px;\"><span style=\"display: inline-block; background: #ecfdf5; color: #065f46; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Sredstva</span> Udžbenik, tabla, kreda</div>\n        <div><span style=\"display: inline-block; background: #fef3c7; color: #92400e; padding: 3px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; margin-right: 8px;\">Metode</span> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</div>\n      </div>\n\n      <h3 style=\"margin: 24px 0 14px 0; color: #0f766e; font-size: 1.2rem; display: flex; align-items: center; gap: 8px;\">📖 Struktura sata</h3>\n\n      <div style=\"background: #eff6ff; border-left: 5px solid #3b82f6; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #1d4ed8; font-size: 1.05rem; margin-bottom: 8px;\">🔵 Uvodni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Djeco, na kojem jeziku govorimo? Bosanskom! Da li je vaš maternji jezik važan? Hajde da naučimo zašto je tako.</p>\n      </div>\n\n      <div style=\"background: #f0fdf4; border-left: 5px solid #22c55e; padding: 14px 18px; border-radius: 0 12px 12px 0; margin-bottom: 14px;\">\n        <div style=\"font-weight: 800; color: #15803d; font-size: 1.05rem; margin-bottom: 8px;\">🟢 Glavni dio</div>\n        <div style=\"line-height: 1.6; color: #1f2937;\"><p>Bosanski jezik je maternji jezik Bošnjaka i jedan od službenih jezika BiH.</p><p>Pisao se kroz historiju različitim pismima: bosanČica (bosansko ćirilično pismo), arebica (arapsko pismo prilagođeno bosanskom), latinica i ćirilica.</p><p>Bosanski jezik ima bogatu tradiciju: narodne pjesme, balade, sevdalinke, mevludi, ilahije, kasside.</p><p>Veliki bošnjački pisci: Mak Dizdar, Meša Selimović, Nedžad Ibrišimović, Skender Kulenović, Muhamed Filipović i mnogi drugi.</p><p>Naša obaveza: pravilno govoriti, čitati i pisati bosanskim jezikom; izbjegavati strane riječi gdje ima naših; čuvati ljepotu jezika.</p><p>Razgovor: Koje su tvoje omiljene bosanske riječi? Šta voliš čitati na bosanskom?</p></div>\n      </div>\n\n      <div style=\"background: #fefce8; border-left: 5px solid #eab308; padding: 14px 18px; border-radius: 0 12px 12px 0;\">\n        <div style=\"font-weight: 800; color: #a16207; font-size: 1.05rem; margin-bottom: 8px;\">🟡 Završni dio</div>\n        <p style=\"margin: 0; line-height: 1.6; color: #1f2937;\">Učenici nabrajaju bošnjačke pjesnike ili pisce koje znaju. Zaključak: jezik je duša naroda – čuvajmo ga.</p>\n      </div>\n\n    </div>\n  </div>\n</div><!--PRIPREMA-END-->\n        <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('STORY', this)\">UVOD U LEKCIJU <span class=\"section-icon\">▼</span></button>\n        <div id=\"STORY\" class=\"lesson-content active\" style=\"display: block;\">\n            <p>Čovjek od samog početka ima potrebu da govori, izražava misli i razumije druge ljude. Bez jezika ne bi bilo ni znanja, ni kulture, ni međusobnog razumijevanja. Svaki narod ima svoj jezik kojim čuva svoju tradiciju, historiju i identitet.</p><p>U ovoj lekciji upoznat ćemo bosanski jezik, njegov razvoj kroz historiju i njegove posebnosti koje ga čine jedinstvenim.</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('ILMIHAL', this)\">NAUČIMO IZ ILMIHALA <span class=\"section-icon\">▶</span></button>\n        <div id=\"ILMIHAL\" class=\"lesson-content\">\n            <p>Od postanka čovječanstva, čovjek je imao potrebu da stupa u kontakt s drugim ljudima, da razgovara i komunicira. Allah, dž.š., nas uči da je Adema, a.s., poučio imenima stvari i tako mu omogućio komunikaciju koja je do danas prisutna i nužna. Svaki narod ima svoj maternji jezik kroz koji ostvaruje tu komunikaciju. Naš maternji jezik je bosanski jezik. On se ubraja u južnoslavenske jezike kojim govore stanovnici Bosne i Hercegovine i jedan je od službenih jezika u našoj domovini. Historija bosanskog jezika seže daleko u prošlost jer je vezana za nastanak države Bosne i Hercegovine, ali i bošnjačkog naroda.</p><p>Bošnjaci od svoga postojanja jezik nazivaju bosanskim, o čemu svjedoče mnogobrojna djela, dokumenti, te trgovački putnici koji su putovali Bosnom. Jedan od prvih spomena naziva bosanskog jezika nalazimo u djelu “Historija pisanih jezika” od Konstantina Filozofa koje je napisano oko 1300. godine. Također, jedan od starijih spomena bosanskog jezika je onaj iz notarskih knjiga grada Kotora od 3. jula 1436.</p><p>Mehmed Hevaji Uskufi je 1631. napisao prvi rječnik bosanskog jezika koji je karakterističan po tome što se radilo o rimovanom bosansko-turskom rječniku.</p><p>Kroz svoju dugu historiju, bosanski jezik je opstao u različitim državnim sistemima, pa je tako u vrijeme osmanske vladavine bosanski jezik bio jedan od službenih jezika na sultanovom dvoru, ali i u službenim aktima.</p><p>Svaki jezik, pa i bosanski, vezan je za pismo kojim se izražava, pa tako za bosanski jezik možemo vezati nekoliko pisama:</p><ul><li><p>latinica i ćirilica – iako je ćirilica manje u upotrebi</p></li><li><p>historijska pisma – bosančica – prilagođena varijanta ćirilice za pisanje na bosanskom jeziku te arebica prilagođena varijanta arapskog pisma glasovnom izgovoru bosanskog jezika</p></li></ul><p>Iako je kroz historiju bilo pokušaja da se bosanski jezik službeno izbaci iz upotrebe, on nikada nije mogao biti izbačen iz govorne upotrebe među stanovništvom Bosne i Hercegovine. Njegovom kontinuitetu će uvijek svjedočiti bogata književnoumjetnička djela nastala kroz njegovu historiju, kao i stanovništvo kojem je bosanski jezik maternji jezik.</p><p>Bosanski jezik je kao i svaki drugi jezik živa materija podložna promjenama. Posljednja standardizacija bosanskog jezika izražena je u rječniku Alije Isakovića, pravopisu Senahida Halilovića i gramatici Dževada Jahića, Senahida Halilovića i Ismaila Palića.</p><p>Kao odraz specifičnosti bosanskog jezika propisana je i upotreba posuđenica: turcizama, arabizama, germanizama, te posebno očuvanje glasova h i f u nekim riječima – kahva, duhan i sl.</p><p>Primjeri posuđenica su mnogobrojni, a neki od njih su:</p><p><strong>Turcizmi</strong> – posuđenice u našem jeziku porijeklom iz turskog jezika: jastuk, jorgan, baklava</p><p><strong>Arabizmi</strong> – posuđenice u našem jeziku porijeklom iz arapskog jezika: makaze, haber, limun</p><p><strong>Germanizmi</strong> – posuđenice u našem jeziku porijeklom iz njemačkog jezika: šrafciger, šnita, cigla</p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('QUIZ_SECTION', this)\">PROVJERI SVOJE ZNANJE <span class=\"section-icon\">▶</span></button>\n        <div id=\"QUIZ_SECTION\" class=\"lesson-content\">\n            <h2>MINI KVIZ</h2><p></p>\n        </div>\n    </div>\n    <div class=\"lesson-accordion\">\n        <button class=\"lesson-section-btn\" onclick=\"toggleSection('PITANJA', this)\">PITANJA I ZADACI <span class=\"section-icon\">▶</span></button>\n        <div id=\"PITANJA\" class=\"lesson-content\">\n            <ol><li><p>U koju grupu jezika se ubraja bosanski jezik?</p></li><li><p>Ko je napisao prvi rječnik bosanskog jezika i kada?</p></li><li><p>Šta su turcizmi, arabizmi i germanizmi?</p></li><li><p>Kada se spomene bosanski jezik, na šta te sve asocira?</p></li></ol><p></p>\n        </div>\n    </div>\n</div>","audio_src":null,"redoslijed":64,"is_published":true,"kviz_pitanja":"[{\"pitanje\":\"Šta znači 'Es-selamu alejkum'?\",\"odgovori\":[\"Dobro jutro\",\"Mir s vama\",\"Hvala\",\"Zbogom\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta znači 'Inšallah'?\",\"odgovori\":[\"Hvala Allahu\",\"Allah je najveći\",\"Ako Bog da\",\"Slavljen neka je Allah\"],\"tacanOdgovor\":2},{\"pitanje\":\"Šta znači 'Elhamdulillah'?\",\"odgovori\":[\"U ime Allaha\",\"Hvala Allahu\",\"Ako Bog da\",\"Slavljen neka je Allah\"],\"tacanOdgovor\":1},{\"pitanje\":\"Ko je hafiz?\",\"odgovori\":[\"Imam\",\"Onaj ko zna cijeli Kur'an napamet\",\"Učitelj\",\"Muezzin\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta je sadaka?\",\"odgovori\":[\"Obavezni porez\",\"Dobrovoljni prilog\",\"Kazna\",\"Dug\"],\"tacanOdgovor\":1},{\"pitanje\":\"Šta znači 'Bismillah'?\",\"odgovori\":[\"Hvala Allahu\",\"Allah je najveći\",\"U ime Allaha\",\"Mir s vama\"],\"tacanOdgovor\":2},{\"pitanje\":\"Ko je muezzin?\",\"odgovori\":[\"Onaj ko uči ezan\",\"Onaj ko klanja\",\"Onaj ko posti\",\"Onaj ko putuje\"],\"tacanOdgovor\":0}]"}];
